const HSK4_DATA = {"lessons":[{"id":1,"title_cn":"我们来中国学习了","title_pinyin":"Wǒmen lái Zhōngguó xuéxí le","title_vn":"Chúng em đã đến Trung Quốc học tập","goals":["Có thể nghe hiểu và trao đổi thông tin về làm thủ tục nhập học và xin học bổng.","Có thể trình bày bằng lời hoặc bằng văn bản lý do chọn chuyên ngành và định hướng phát triển nghề nghiệp trong tương lai.","Hiểu được tình hình học tập và sinh hoạt của du học sinh nước ngoài tại các trường đại học Trung Quốc."],"vocab":[{"hanzi":"签证","pinyin":"qiānzhèng","pos":"dt.","vn":"thị thực, visa","examples":[{"cn":"我已经申请了去美国的签证。","pinyin":"Wǒ yǐjīng shēnqǐng le qù Měiguó de qiānzhèng.","vn":"Tôi đã xin visa đi Mỹ rồi."},{"cn":"办签证需要准备很多材料。","pinyin":"Bàn qiānzhèng xūyào zhǔnbèi hěn duō cáiliào.","vn":"Làm visa cần chuẩn bị rất nhiều giấy tờ."},{"cn":"他的签证下个月就到期了。","pinyin":"Tā de qiānzhèng xià ge yuè jiù dàoqī le.","vn":"Visa của anh ấy tháng sau là hết hạn rồi."}]},{"hanzi":"入学","pinyin":"rùxué","pos":"dgt.","vn":"nhập học","examples":[{"cn":"孩子今年九月入学。","pinyin":"Háizi jīnnián jiǔyuè rùxué.","vn":"Đứa trẻ tháng chín năm nay nhập học."},{"cn":"入学以后你会认识很多新朋友。","pinyin":"Rùxué yǐhòu nǐ huì rènshi hěn duō xīn péngyou.","vn":"Sau khi nhập học bạn sẽ quen được rất nhiều bạn mới."},{"cn":"我们学校的入学考试挺难的。","pinyin":"Wǒmen xuéxiào de rùxué kǎoshì tǐng nán de.","vn":"Kỳ thi nhập học của trường chúng tôi khá khó."}]},{"hanzi":"通知","pinyin":"tōngzhī","pos":"dgt./dt.","vn":"thông báo","examples":[{"cn":"老师在群里发了一个通知。","pinyin":"Lǎoshī zài qún lǐ fā le yí ge tōngzhī.","vn":"Thầy giáo đã đăng một thông báo trong nhóm."},{"cn":"公司通知我们明天放假。","pinyin":"Gōngsī tōngzhī wǒmen míngtiān fàngjià.","vn":"Công ty thông báo chúng tôi được nghỉ ngày mai."},{"cn":"你收到录取通知了吗？","pinyin":"Nǐ shōudào lùqǔ tōngzhī le ma?","vn":"Bạn nhận được thông báo trúng tuyển chưa?"}]},{"hanzi":"证件","pinyin":"zhèngjiàn","pos":"dt.","vn":"giấy tờ, giấy chứng nhận","examples":[{"cn":"进大楼需要出示证件。","pinyin":"Jìn dàlóu xūyào chūshì zhèngjiàn.","vn":"Vào tòa nhà cần xuất trình giấy tờ."},{"cn":"我把证件忘在家里了。","pinyin":"Wǒ bǎ zhèngjiàn wàng zài jiā li le.","vn":"Tôi quên giấy tờ ở nhà mất rồi."},{"cn":"办理手续时一定要带好证件。","pinyin":"Bànlǐ shǒuxù shí yídìng yào dài hǎo zhèngjiàn.","vn":"Khi làm thủ tục nhất định phải mang theo đầy đủ giấy tờ."}]},{"hanzi":"材料","pinyin":"cáiliào","pos":"dt.","vn":"tài liệu, tư liệu","examples":[{"cn":"申请奖学金需要准备哪些材料？","pinyin":"Shēnqǐng jiǎngxuéjīn xūyào zhǔnbèi nǎxiē cáiliào?","vn":"Xin học bổng cần chuẩn bị những tài liệu gì?"},{"cn":"这个包的材料摸起来很舒服。","pinyin":"Zhège bāo de cáiliào mō qǐlai hěn shūfu.","vn":"Chất liệu của chiếc túi này sờ vào rất dễ chịu."},{"cn":"他正在收集写论文的材料。","pinyin":"Tā zhèngzài shōují xiě lùnwén de cáiliào.","vn":"Anh ấy đang thu thập tài liệu để viết luận văn."}]},{"hanzi":"证","pinyin":"zhèng","pos":"dt.","vn":"giấy chứng nhận, chứng","examples":[{"cn":"你带学生证了吗？","pinyin":"Nǐ dài xuéshēngzhèng le ma?","vn":"Bạn mang thẻ sinh viên chưa?"},{"cn":"他考了一个驾驶证。","pinyin":"Tā kǎo le yí ge jiàshǐzhèng.","vn":"Anh ấy đã thi được bằng lái xe."},{"cn":"这个证明文件需要盖章才有效。","pinyin":"Zhège zhèngmíng wénjiàn xūyào gàizhāng cái yǒuxiào.","vn":"Giấy chứng nhận này cần đóng dấu mới có hiệu lực."}]},{"hanzi":"任何","pinyin":"rènhé","pos":"đt.","vn":"bất cứ, bất kỳ","examples":[{"cn":"任何人都可以参加这个活动。","pinyin":"Rènhé rén dōu kěyǐ cānjiā zhège huódòng.","vn":"Bất cứ ai cũng có thể tham gia hoạt động này."},{"cn":"我现在没有任何办法解决这个问题。","pinyin":"Wǒ xiànzài méiyǒu rènhé bànfǎ jiějué zhège wèntí.","vn":"Bây giờ tôi không có cách nào để giải quyết vấn đề này cả."},{"cn":"不管任何时候，你都可以给我打电话。","pinyin":"Bùguǎn rènhé shíhou, nǐ dōu kěyǐ gěi wǒ dǎ diànhuà.","vn":"Bất kể lúc nào, bạn đều có thể gọi điện cho tôi."}]},{"hanzi":"食堂","pinyin":"shítáng","pos":"dt.","vn":"nhà ăn, căng tin","examples":[{"cn":"我们一般中午在食堂吃饭。","pinyin":"Wǒmen yìbān zhōngwǔ zài shítáng chīfàn.","vn":"Chúng tôi thường ăn trưa ở căng tin."},{"cn":"学校食堂的菜又便宜又好吃。","pinyin":"Xuéxiào shítáng de cài yòu piányi yòu hǎochī.","vn":"Món ăn ở căng tin trường vừa rẻ vừa ngon."},{"cn":"食堂今天中午人特别多。","pinyin":"Shítáng jīntiān zhōngwǔ rén tèbié duō.","vn":"Trưa nay căng tin đông người đặc biệt."}]},{"hanzi":"座","pinyin":"zuò","pos":"lượng.","vn":"(lượng từ dùng cho núi, tòa nhà và các vật thể cố định tương tự)","examples":[{"cn":"那座山看起来很高。","pinyin":"Nà zuò shān kàn qǐlai hěn gāo.","vn":"Ngọn núi đó nhìn có vẻ rất cao."},{"cn":"学校旁边新建了一座图书馆。","pinyin":"Xuéxiào pángbiān xīn jiàn le yí zuò túshūguǎn.","vn":"Bên cạnh trường mới xây một tòa thư viện."},{"cn":"这座城市的夜景特别美。","pinyin":"Zhè zuò chéngshì de yèjǐng tèbié měi.","vn":"Cảnh đêm của thành phố này đặc biệt đẹp."}]},{"hanzi":"申请","pinyin":"shēnqǐng","pos":"dgt.","vn":"xin, nộp đơn xin","examples":[{"cn":"我打算申请这所大学的硕士。","pinyin":"Wǒ dǎsuàn shēnqǐng zhè suǒ dàxué de shuòshì.","vn":"Tôi định nộp đơn xin học thạc sĩ ở trường đại học này."},{"cn":"他已经申请了三份工作。","pinyin":"Tā yǐjīng shēnqǐng le sān fèn gōngzuò.","vn":"Anh ấy đã nộp đơn xin ba công việc rồi."},{"cn":"申请的时候一定要填清楚自己的信息。","pinyin":"Shēnqǐng de shíhou yídìng yào tián qīngchu zìjǐ de xìnxī.","vn":"Khi nộp đơn nhất định phải điền rõ ràng thông tin của mình."}]},{"hanzi":"奖学金","pinyin":"jiǎngxuéjīn","pos":"dt.","vn":"học bổng","examples":[{"cn":"她这学期得了一等奖学金。","pinyin":"Tā zhè xuéqī dé le yīděng jiǎngxuéjīn.","vn":"Học kỳ này cô ấy được học bổng hạng nhất."},{"cn":"学习好就有机会申请奖学金。","pinyin":"Xuéxí hǎo jiù yǒu jīhuì shēnqǐng jiǎngxuéjīn.","vn":"Học tốt thì có cơ hội xin học bổng."},{"cn":"这个奖学金能减轻不少经济压力。","pinyin":"Zhège jiǎngxuéjīn néng jiǎnqīng bùshǎo jīngjì yālì.","vn":"Học bổng này có thể giảm bớt khá nhiều áp lực kinh tế."}]},{"hanzi":"表现","pinyin":"biǎoxiàn","pos":"dgt.","vn":"biểu hiện, thể hiện","examples":[{"cn":"他最近在公司的表现很好。","pinyin":"Tā zuìjìn zài gōngsī de biǎoxiàn hěn hǎo.","vn":"Dạo gần đây anh ấy thể hiện rất tốt ở công ty."},{"cn":"老师表扬了他这学期的表现。","pinyin":"Lǎoshī biǎoyáng le tā zhè xuéqī de biǎoxiàn.","vn":"Thầy giáo đã khen ngợi biểu hiện của cậu ấy học kỳ này."},{"cn":"比赛那天他表现得特别紧张。","pinyin":"Bǐsài nà tiān tā biǎoxiàn de tèbié jǐnzhāng.","vn":"Hôm thi đấu cậu ấy thể hiện rất căng thẳng."}]},{"hanzi":"获得","pinyin":"huòdé","pos":"dgt.","vn":"giành được, đạt được","examples":[{"cn":"他在这次比赛中获得了第一名。","pinyin":"Tā zài zhè cì bǐsài zhōng huòdé le dì yī míng.","vn":"Anh ấy đã giành được giải nhất trong cuộc thi lần này."},{"cn":"努力学习才能获得好成绩。","pinyin":"Nǔlì xuéxí cái néng huòdé hǎo chéngjì.","vn":"Phải chăm chỉ học tập mới đạt được thành tích tốt."},{"cn":"她终于获得了去国外留学的机会。","pinyin":"Tā zhōngyú huòdé le qù guówài liúxué de jīhuì.","vn":"Cuối cùng cô ấy cũng giành được cơ hội đi du học nước ngoài."}]},{"hanzi":"要是","pinyin":"yàoshi","pos":"liên.","vn":"nếu, nếu như","examples":[{"cn":"要是明天下雨，我们就不去了。","pinyin":"Yàoshi míngtiān xiàyǔ, wǒmen jiù bú qù le.","vn":"Nếu mai trời mưa thì chúng ta không đi nữa."},{"cn":"要是你有时间，就来帮帮我吧。","pinyin":"Yàoshi nǐ yǒu shíjiān, jiù lái bāngbang wǒ ba.","vn":"Nếu bạn có thời gian thì đến giúp tôi một chút nhé."},{"cn":"要是早知道堵车，我就早点出门了。","pinyin":"Yàoshi zǎo zhīdào dǔchē, wǒ jiù zǎodiǎn chūmén le.","vn":"Nếu sớm biết tắc đường thì tôi đã ra khỏi nhà sớm hơn rồi."}]},{"hanzi":"减轻","pinyin":"jiǎnqīng","pos":"dgt.","vn":"giảm nhẹ, giảm bớt","examples":[{"cn":"多运动可以减轻压力。","pinyin":"Duō yùndòng kěyǐ jiǎnqīng yālì.","vn":"Vận động nhiều có thể giảm bớt áp lực."},{"cn":"这个药能减轻疼痛。","pinyin":"Zhège yào néng jiǎnqīng téngtòng.","vn":"Loại thuốc này có thể giảm nhẹ cơn đau."},{"cn":"父母想办法减轻孩子的学习负担。","pinyin":"Fùmǔ xiǎng bànfǎ jiǎnqīng háizi de xuéxí fùdān.","vn":"Cha mẹ nghĩ cách giảm nhẹ gánh nặng học tập cho con cái."}]},{"hanzi":"经济","pinyin":"jīngjì","pos":"dt.","vn":"kinh tế","examples":[{"cn":"这几年国家的经济发展得很快。","pinyin":"Zhè jǐ nián guójiā de jīngjì fāzhǎn de hěn kuài.","vn":"Mấy năm nay kinh tế quốc gia phát triển rất nhanh."},{"cn":"他大学学的是国际经济专业。","pinyin":"Tā dàxué xué de shì guójì jīngjì zhuānyè.","vn":"Anh ấy học chuyên ngành kinh tế quốc tế ở đại học."},{"cn":"我现在经济上不太宽裕。","pinyin":"Wǒ xiànzài jīngjì shang bú tài kuānyù.","vn":"Hiện giờ tôi không mấy dư dả về kinh tế."}]},{"hanzi":"压力","pinyin":"yālì","pos":"dt.","vn":"áp lực","examples":[{"cn":"最近工作压力特别大。","pinyin":"Zuìjìn gōngzuò yālì tèbié dà.","vn":"Gần đây áp lực công việc đặc biệt lớn."},{"cn":"他给自己的压力太大了。","pinyin":"Tā gěi zìjǐ de yālì tài dà le.","vn":"Anh ấy tự tạo áp lực cho mình quá lớn."},{"cn":"听音乐是我放松压力的方法。","pinyin":"Tīng yīnyuè shì wǒ fàngsōng yālì de fāngfǎ.","vn":"Nghe nhạc là cách tôi giải tỏa áp lực."}]},{"hanzi":"加油","pinyin":"jiāyóu","pos":"dgt.","vn":"cố gắng, cổ vũ","examples":[{"cn":"考试加油，你一定可以的！","pinyin":"Kǎoshì jiāyóu, nǐ yídìng kěyǐ de!","vn":"Cố lên thi nhé, bạn chắc chắn làm được!"},{"cn":"大家都在为运动员加油。","pinyin":"Dàjiā dōu zài wèi yùndòngyuán jiāyóu.","vn":"Mọi người đều đang cổ vũ cho vận động viên."},{"cn":"别放弃，再加油一下就成功了。","pinyin":"Bié fàngqì, zài jiāyóu yíxià jiù chénggōng le.","vn":"Đừng bỏ cuộc, cố thêm một chút nữa là thành công rồi."}]},{"hanzi":"随着","pinyin":"suízhe","pos":"giới.","vn":"cùng với","examples":[{"cn":"随着年龄的增长，他变得更成熟了。","pinyin":"Suízhe niánlíng de zēngzhǎng, tā biàn de gèng chéngshú le.","vn":"Cùng với tuổi tác tăng lên, anh ấy trở nên chín chắn hơn."},{"cn":"随着科技的发展，生活越来越方便。","pinyin":"Suízhe kējì de fāzhǎn, shēnghuó yuè lái yuè fāngbiàn.","vn":"Cùng với sự phát triển của khoa học kỹ thuật, cuộc sống ngày càng tiện lợi."},{"cn":"随着天气变冷，穿的衣服也多了起来。","pinyin":"Suízhe tiānqì biàn lěng, chuān de yīfu yě duō le qǐlai.","vn":"Cùng với thời tiết trở lạnh, quần áo mặc cũng nhiều lên."}]},{"hanzi":"课程","pinyin":"kèchéng","pos":"dt.","vn":"khóa học, chương trình học","examples":[{"cn":"这学期我选了五门课程。","pinyin":"Zhè xuéqī wǒ xuǎn le wǔ mén kèchéng.","vn":"Học kỳ này tôi đã đăng ký năm môn học."},{"cn":"这门课程的内容特别有意思。","pinyin":"Zhè mén kèchéng de nèiróng tèbié yǒu yìsi.","vn":"Nội dung môn học này đặc biệt thú vị."},{"cn":"学校最近调整了课程安排。","pinyin":"Xuéxiào zuìjìn tiáozhěng le kèchéng ānpái.","vn":"Gần đây trường đã điều chỉnh lịch trình học."}]},{"hanzi":"专业","pinyin":"zhuānyè","pos":"dt./tt.","vn":"chuyên ngành; chuyên nghiệp","examples":[{"cn":"你大学学的是什么专业？","pinyin":"Nǐ dàxué xué de shì shénme zhuānyè?","vn":"Bạn học chuyên ngành gì ở đại học?"},{"cn":"他对电脑维修特别专业。","pinyin":"Tā duì diànnǎo wéixiū tèbié zhuānyè.","vn":"Anh ấy rất chuyên nghiệp trong việc sửa máy tính."},{"cn":"这个医生看起来很专业。","pinyin":"Zhège yīshēng kàn qǐlai hěn zhuānyè.","vn":"Vị bác sĩ này trông rất chuyên nghiệp."}]},{"hanzi":"本科","pinyin":"běnkē","pos":"dt.","vn":"đại học (hệ cử nhân), bậc cử nhân","examples":[{"cn":"他本科毕业以后就去工作了。","pinyin":"Tā běnkē bìyè yǐhòu jiù qù gōngzuò le.","vn":"Anh ấy tốt nghiệp đại học xong là đi làm luôn."},{"cn":"我本科学的专业跟现在的工作不太一样。","pinyin":"Wǒ běnkē xué de zhuānyè gēn xiànzài de gōngzuò bú tài yíyàng.","vn":"Chuyên ngành tôi học hồi đại học không giống với công việc hiện tại."},{"cn":"这所学校的本科教育很有名。","pinyin":"Zhè suǒ xuéxiào de běnkē jiàoyù hěn yǒumíng.","vn":"Nền giáo dục bậc cử nhân của trường này rất nổi tiếng."}]},{"hanzi":"硕士","pinyin":"shuòshì","pos":"dt.","vn":"thạc sĩ","examples":[{"cn":"她正在读硕士研究生。","pinyin":"Tā zhèngzài dú shuòshì yánjiūshēng.","vn":"Cô ấy đang học thạc sĩ."},{"cn":"他打算毕业后去国外读硕士。","pinyin":"Tā dǎsuàn bìyè hòu qù guówài dú shuòshì.","vn":"Anh ấy định tốt nghiệp xong sẽ đi nước ngoài học thạc sĩ."},{"cn":"硕士学位对找工作很有帮助。","pinyin":"Shuòshì xuéwèi duì zhǎo gōngzuò hěn yǒu bāngzhù.","vn":"Bằng thạc sĩ rất có ích cho việc tìm việc làm."}]},{"hanzi":"研究生","pinyin":"yánjiūshēng","pos":"dt.","vn":"nghiên cứu sinh, học viên cao học","examples":[{"cn":"我表姐现在是研究生。","pinyin":"Wǒ biǎojiě xiànzài shì yánjiūshēng.","vn":"Chị họ tôi hiện giờ là nghiên cứu sinh."},{"cn":"他考上了北京大学的研究生。","pinyin":"Tā kǎoshàng le Běijīng Dàxué de yánjiūshēng.","vn":"Anh ấy đã thi đỗ cao học trường Đại học Bắc Kinh."},{"cn":"研究生的学习压力比本科大很多。","pinyin":"Yánjiūshēng de xuéxí yālì bǐ běnkē dà hěn duō.","vn":"Áp lực học tập của nghiên cứu sinh lớn hơn đại học rất nhiều."}]},{"hanzi":"博士","pinyin":"bóshì","pos":"dt.","vn":"tiến sĩ","examples":[{"cn":"他花了五年时间才拿到博士学位。","pinyin":"Tā huā le wǔ nián shíjiān cái nádào bóshì xuéwèi.","vn":"Anh ấy mất năm năm mới lấy được bằng tiến sĩ."},{"cn":"她是一位很有名的博士。","pinyin":"Tā shì yí wèi hěn yǒumíng de bóshì.","vn":"Cô ấy là một vị tiến sĩ rất nổi tiếng."},{"cn":"读博士需要很强的研究能力。","pinyin":"Dú bóshì xūyào hěn qiáng de yánjiū nénglì.","vn":"Học tiến sĩ cần có năng lực nghiên cứu rất mạnh."}]},{"hanzi":"研究","pinyin":"yánjiū","pos":"dgt.","vn":"nghiên cứu","examples":[{"cn":"他正在研究一个新课题。","pinyin":"Tā zhèngzài yánjiū yí ge xīn kètí.","vn":"Anh ấy đang nghiên cứu một đề tài mới."},{"cn":"我们应该好好研究一下这个问题。","pinyin":"Wǒmen yīnggāi hǎohǎo yánjiū yíxià zhège wèntí.","vn":"Chúng ta nên nghiên cứu kỹ vấn đề này."},{"cn":"这项研究花了他很多年时间。","pinyin":"Zhè xiàng yánjiū huā le tā hěn duō nián shíjiān.","vn":"Công trình nghiên cứu này đã tiêu tốn của anh ấy rất nhiều năm."}]},{"hanzi":"活动","pinyin":"huódòng","pos":"dt./dgt.","vn":"hoạt động","examples":[{"cn":"学校周末组织了一个活动。","pinyin":"Xuéxiào zhōumò zǔzhī le yí ge huódòng.","vn":"Cuối tuần trường tổ chức một hoạt động."},{"cn":"他很少参加课外活动。","pinyin":"Tā hěn shǎo cānjiā kèwài huódòng.","vn":"Anh ấy rất ít khi tham gia hoạt động ngoại khóa."},{"cn":"多活动活动对身体有好处。","pinyin":"Duō huódòng huódòng duì shēntǐ yǒu hǎochù.","vn":"Vận động nhiều có lợi cho sức khỏe."}]},{"hanzi":"通过","pinyin":"tōngguò","pos":"giới./dgt.","vn":"thông qua","examples":[{"cn":"他通过努力终于成功了。","pinyin":"Tā tōngguò nǔlì zhōngyú chénggōng le.","vn":"Anh ấy thông qua nỗ lực cuối cùng đã thành công."},{"cn":"这次考试他顺利通过了。","pinyin":"Zhè cì kǎoshì tā shùnlì tōngguò le.","vn":"Kỳ thi lần này anh ấy đã vượt qua một cách suôn sẻ."},{"cn":"我们通过朋友认识了这个老师。","pinyin":"Wǒmen tōngguò péngyou rènshi le zhège lǎoshī.","vn":"Chúng tôi quen biết thầy giáo này thông qua một người bạn."}]},{"hanzi":"交流","pinyin":"jiāoliú","pos":"dgt.","vn":"giao lưu","examples":[{"cn":"我们应该多和外国朋友交流。","pinyin":"Wǒmen yīnggāi duō hé wàiguó péngyou jiāoliú.","vn":"Chúng ta nên giao lưu nhiều hơn với bạn bè nước ngoài."},{"cn":"这次会议是为了促进两国之间的文化交流。","pinyin":"Zhè cì huìyì shì wèile cùjìn liǎng guó zhījiān de wénhuà jiāoliú.","vn":"Hội nghị lần này là để thúc đẩy giao lưu văn hóa giữa hai nước."},{"cn":"他跟同事的交流越来越少了。","pinyin":"Tā gēn tóngshì de jiāoliú yuè lái yuè shǎo le.","vn":"Việc giao lưu của anh ấy với đồng nghiệp ngày càng ít đi."}]},{"hanzi":"适应","pinyin":"shìyìng","pos":"dgt.","vn":"thích nghi, thích ứng","examples":[{"cn":"我已经适应了这里的生活。","pinyin":"Wǒ yǐjīng shìyìng le zhèlǐ de shēnghuó.","vn":"Tôi đã thích nghi với cuộc sống ở đây rồi."},{"cn":"刚开始他很难适应新的环境。","pinyin":"Gāng kāishǐ tā hěn nán shìyìng xīn de huánjìng.","vn":"Lúc mới đầu anh ấy rất khó thích nghi với môi trường mới."},{"cn":"多数人需要时间去适应变化。","pinyin":"Duōshù rén xūyào shíjiān qù shìyìng biànhuà.","vn":"Phần lớn mọi người cần thời gian để thích nghi với sự thay đổi."}]},{"hanzi":"将来","pinyin":"jiānglái","pos":"dt.","vn":"tương lai","examples":[{"cn":"你将来想做什么工作？","pinyin":"Nǐ jiānglái xiǎng zuò shénme gōngzuò?","vn":"Trong tương lai bạn muốn làm công việc gì?"},{"cn":"我对将来充满了希望。","pinyin":"Wǒ duì jiānglái chōngmǎn le xīwàng.","vn":"Tôi tràn đầy hy vọng về tương lai."},{"cn":"这个决定会影响他的将来。","pinyin":"Zhège juédìng huì yǐngxiǎng tā de jiānglái.","vn":"Quyết định này sẽ ảnh hưởng đến tương lai của anh ấy."}]},{"hanzi":"国际","pinyin":"guójì","pos":"tt./dt.","vn":"quốc tế","examples":[{"cn":"他在一家国际公司工作。","pinyin":"Tā zài yì jiā guójì gōngsī gōngzuò.","vn":"Anh ấy làm việc ở một công ty quốc tế."},{"cn":"这个城市每年都举办国际电影节。","pinyin":"Zhège chéngshì měi nián dōu jǔbàn guójì diànyǐngjié.","vn":"Thành phố này mỗi năm đều tổ chức liên hoan phim quốc tế."},{"cn":"她希望以后能从事国际贸易方面的工作。","pinyin":"Tā xīwàng yǐhòu néng cóngshì guójì màoyì fāngmiàn de gōngzuò.","vn":"Cô ấy hy vọng sau này có thể làm công việc liên quan đến thương mại quốc tế."}]},{"hanzi":"当","pinyin":"dāng","pos":"dgt.","vn":"làm (nghề gì)","examples":[{"cn":"我从小就想当一名老师。","pinyin":"Wǒ cóngxiǎo jiù xiǎng dāng yì míng lǎoshī.","vn":"Từ nhỏ tôi đã muốn làm giáo viên."},{"cn":"他毕业以后当上了工程师。","pinyin":"Tā bìyè yǐhòu dāngshàng le gōngchéngshī.","vn":"Anh ấy tốt nghiệp xong thì trở thành kỹ sư."},{"cn":"她在学校一直当班长。","pinyin":"Tā zài xuéxiào yìzhí dāng bānzhǎng.","vn":"Ở trường cô ấy luôn luôn làm lớp trưởng."}]},{"hanzi":"教育","pinyin":"jiàoyù","pos":"dt./dgt.","vn":"giáo dục","examples":[{"cn":"父母很重视孩子的教育。","pinyin":"Fùmǔ hěn zhòngshì háizi de jiàoyù.","vn":"Cha mẹ rất coi trọng việc giáo dục con cái."},{"cn":"这个国家的教育水平很高。","pinyin":"Zhège guójiā de jiàoyù shuǐpíng hěn gāo.","vn":"Trình độ giáo dục của quốc gia này rất cao."},{"cn":"他从事教育工作已经二十年了。","pinyin":"Tā cóngshì jiàoyù gōngzuò yǐjīng èrshí nián le.","vn":"Anh ấy làm công tác giáo dục đã hai mươi năm rồi."}]},{"hanzi":"成为","pinyin":"chéngwéi","pos":"dgt.","vn":"trở thành","examples":[{"cn":"他的梦想是成为一名医生。","pinyin":"Tā de mèngxiǎng shì chéngwéi yì míng yīshēng.","vn":"Ước mơ của anh ấy là trở thành một bác sĩ."},{"cn":"这座城市已经成为了旅游胜地。","pinyin":"Zhè zuò chéngshì yǐjīng chéngwéi le lǚyóu shèngdì.","vn":"Thành phố này đã trở thành điểm du lịch nổi tiếng."},{"cn":"经过努力，他终于成为了一名律师。","pinyin":"Jīngguò nǔlì, tā zhōngyú chéngwéi le yì míng lǜshī.","vn":"Qua nỗ lực, cuối cùng anh ấy đã trở thành một luật sư."}]},{"hanzi":"教师","pinyin":"jiàoshī","pos":"dt.","vn":"giáo viên","examples":[{"cn":"我妈妈是一名小学教师。","pinyin":"Wǒ māma shì yì míng xiǎoxué jiàoshī.","vn":"Mẹ tôi là một giáo viên tiểu học."},{"cn":"当教师是一份很有意义的工作。","pinyin":"Dāng jiàoshī shì yí fèn hěn yǒu yìyì de gōngzuò.","vn":"Làm giáo viên là một công việc rất có ý nghĩa."},{"cn":"这位教师对学生非常耐心。","pinyin":"Zhè wèi jiàoshī duì xuésheng fēicháng nàixīn.","vn":"Vị giáo viên này rất kiên nhẫn với học sinh."}]},{"hanzi":"贸易","pinyin":"màoyì","pos":"dt.","vn":"thương mại, mậu dịch","examples":[{"cn":"两国之间的贸易越来越频繁。","pinyin":"Liǎng guó zhījiān de màoyì yuè lái yuè pínfán.","vn":"Thương mại giữa hai nước ngày càng nhộn nhịp."},{"cn":"他大学学的是国际贸易专业。","pinyin":"Tā dàxué xué de shì guójì màoyì zhuānyè.","vn":"Anh ấy học chuyên ngành thương mại quốc tế ở đại học."},{"cn":"这家公司主要做电子产品贸易。","pinyin":"Zhè jiā gōngsī zhǔyào zuò diànzǐ chǎnpǐn màoyì.","vn":"Công ty này chủ yếu kinh doanh mậu dịch sản phẩm điện tử."}]},{"hanzi":"方面","pinyin":"fāngmiàn","pos":"dt.","vn":"phương diện, mặt","examples":[{"cn":"他在学习方面很努力。","pinyin":"Tā zài xuéxí fāngmiàn hěn nǔlì.","vn":"Anh ấy rất nỗ lực về mặt học tập."},{"cn":"这件事在很多方面都值得我们学习。","pinyin":"Zhè jiàn shì zài hěn duō fāngmiàn dōu zhídé wǒmen xuéxí.","vn":"Việc này ở nhiều phương diện đều đáng để chúng ta học hỏi."},{"cn":"我们应该从经济和文化两个方面来分析。","pinyin":"Wǒmen yīnggāi cóng jīngjì hé wénhuà liǎng ge fāngmiàn lái fēnxī.","vn":"Chúng ta nên phân tích từ hai phương diện kinh tế và văn hóa."}]},{"hanzi":"知识","pinyin":"zhīshi","pos":"dt.","vn":"kiến thức","examples":[{"cn":"他的知识特别丰富。","pinyin":"Tā de zhīshi tèbié fēngfù.","vn":"Kiến thức của anh ấy đặc biệt phong phú."},{"cn":"读书可以增长知识。","pinyin":"Dúshū kěyǐ zēngzhǎng zhīshi.","vn":"Đọc sách có thể tăng thêm kiến thức."},{"cn":"这本书里有很多实用的知识。","pinyin":"Zhè běn shū lǐ yǒu hěn duō shíyòng de zhīshi.","vn":"Trong cuốn sách này có rất nhiều kiến thức thực dụng."}]},{"hanzi":"另","pinyin":"lìng","pos":"đt.","vn":"khác, cái khác","examples":[{"cn":"这件事我们另找时间再说吧。","pinyin":"Zhè jiàn shì wǒmen lìng zhǎo shíjiān zài shuō ba.","vn":"Việc này chúng ta tìm lúc khác nói chuyện nhé."},{"cn":"他已经搬到另一个城市去了。","pinyin":"Tā yǐjīng bān dào lìng yí ge chéngshì qù le.","vn":"Anh ấy đã chuyển đến một thành phố khác rồi."},{"cn":"这件事情还有另外一种解释。","pinyin":"Zhè jiàn shìqing hái yǒu lìngwài yì zhǒng jiěshì.","vn":"Việc này còn có một cách giải thích khác nữa."}]}],"grammar":[{"title":"指示代词\"任何\"","explanation_vn":"Đại từ chỉ định \"任何\" biểu thị ý nghĩa \"bất cứ cái gì\". Khi bổ nghĩa cho danh từ thường không dùng \"的\", phía sau thường đi kèm với \"都\" hoặc \"也\".","examples":[{"cn":"你们以后有任何问题都可以来找我。","pinyin":"Nǐmen yǐhòu yǒu rènhé wèntí dōu kěyǐ lái zhǎo wǒ.","vn":"Sau này các em có bất cứ vấn đề gì đều có thể đến tìm cô."},{"cn":"明天我们8点出发，任何人也不能迟到。","pinyin":"Míngtiān wǒmen bā diǎn chūfā, rènhé rén yě bù néng chídào.","vn":"Ngày mai chúng ta xuất phát lúc 8 giờ, bất cứ ai cũng không được đến muộn."},{"cn":"学校有任何通知，我都会第一时间告诉你。","pinyin":"Xuéxiào yǒu rènhé tōngzhī, wǒ dōu huì dìyī shíjiān gàosu nǐ.","vn":"Trường có bất cứ thông báo gì, mình đều sẽ báo cho cậu ngay lập tức."}]},{"title":"假设复句\"要是……，就……\"","explanation_vn":"Vế trước nêu ra một giả thiết, vế sau biểu thị kết quả xảy ra khi giả thiết đó được thực hiện.","examples":[{"cn":"要是申请到奖学金，就能减轻不少经济压力。","pinyin":"Yàoshi shēnqǐng dào jiǎngxuéjīn, jiù néng jiǎnqīng bùshǎo jīngjì yālì.","vn":"Nếu xin được học bổng thì có thể giảm bớt không ít áp lực kinh tế."},{"cn":"你要是明天有时间，就跟我一起去爬山吧。","pinyin":"Nǐ yàoshi míngtiān yǒu shíjiān, jiù gēn wǒ yìqǐ qù páshān ba.","vn":"Nếu ngày mai cậu có thời gian thì cùng mình đi leo núi nhé."},{"cn":"要是她不愿意参加比赛，我们就再问问别人。","pinyin":"Yàoshi tā bú yuànyì cānjiā bǐsài, wǒmen jiù zài wènwen biérén.","vn":"Nếu cô ấy không muốn tham gia thi đấu thì chúng ta sẽ hỏi người khác."}]},{"title":"介词\"随着\"","explanation_vn":"Giới từ \"随着\" thường đi kèm với từ ngữ hoặc cụm từ biểu thị sự thay đổi, biểu thị một sự việc là điều kiện để sự việc khác xảy ra.","examples":[{"cn":"随着中国的发展，越来越多的外国学生来到中国的大学学习。","pinyin":"Suízhe Zhōngguó de fāzhǎn, yuèláiyuè duō de wàiguó xuésheng láidào Zhōngguó de dàxué xuéxí.","vn":"Cùng với sự phát triển của Trung Quốc, ngày càng nhiều du học sinh nước ngoài đến các trường đại học Trung Quốc học tập."},{"cn":"随着中文水平的提高，我现在能看懂中文报纸了。","pinyin":"Suízhe Zhōngwén shuǐpíng de tígāo, wǒ xiànzài néng kàndǒng Zhōngwén bàozhǐ le.","vn":"Cùng với trình độ tiếng Trung được nâng cao, bây giờ mình đã có thể đọc hiểu báo tiếng Trung."},{"cn":"随着小区的环境越来越好，来这里买房子的人也变多了。","pinyin":"Suízhe xiǎoqū de huánjìng yuèláiyuè hǎo, lái zhèlǐ mǎi fángzi de rén yě biàn duō le.","vn":"Cùng với môi trường khu dân cư ngày càng tốt lên, số người đến đây mua nhà cũng tăng lên."}]},{"title":"并列复句\"一方面……，另一方面……\"","explanation_vn":"Câu phức liên hợp \"一方面……，另一方面……\" thường dùng để trình bày hai phương diện nguyên nhân, tình huống,... cùng tồn tại song song.","examples":[{"cn":"来到中国留学，一方面是为了学习语言和知识，另一方面也是为将来的工作和生活做准备。","pinyin":"Láidào Zhōngguó liúxué, yì fāngmiàn shì wèile xuéxí yǔyán hé zhīshi, lìng yì fāngmiàn yě shì wèi jiānglái de gōngzuò hé shēnghuó zuò zhǔnbèi.","vn":"Đến Trung Quốc du học, một mặt là để học ngôn ngữ và kiến thức, mặt khác cũng là để chuẩn bị cho công việc và cuộc sống sau này."},{"cn":"他经常在网上买东西，一方面因为便宜，另一方面因为方便。","pinyin":"Tā jīngcháng zài wǎngshang mǎi dōngxi, yì fāngmiàn yīnwèi piányi, lìng yì fāngmiàn yīnwèi fāngbiàn.","vn":"Anh ấy thường mua đồ trên mạng, một mặt vì rẻ, mặt khác vì tiện lợi."},{"cn":"多做运动一方面能让身体更健康，另一方面也能减轻压力。","pinyin":"Duō zuò yùndòng yì fāngmiàn néng ràng shēntǐ gèng jiànkāng, lìng yì fāngmiàn yě néng jiǎnqīng yālì.","vn":"Tập thể dục nhiều một mặt có thể giúp cơ thể khỏe mạnh hơn, mặt khác cũng có thể giảm bớt áp lực."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"老师","cn":"你们好，欢迎来到中国留学！请把护照、签证和入学通知书给我。","pinyin":"Nǐmen hǎo, huānyíng láidào Zhōngguó liúxué! Qǐng bǎ hùzhào, qiānzhèng hé rùxué tōngzhīshū gěi wǒ."},{"speaker":"白家月","cn":"好的。这是我们的证件和材料。","pinyin":"Hǎo de. Zhè shì wǒmen de zhèngjiàn hé cáiliào."},{"speaker":"","cn":"（几分钟后。）","pinyin":"(Jǐ fēnzhōng hòu.)"},{"speaker":"老师","cn":"办好了，这是你们的学生证，下周一开始上课。先试听两周，然后在网上选课。","pinyin":"Bànhǎo le, zhè shì nǐmen de xuéshengzhèng, xià zhōuyī kāishǐ shàngkè. Xiān shìtīng liǎng zhōu, ránhòu zài wǎngshang xuǎnkè."},{"speaker":"白家月、陈天中","cn":"谢谢老师。","pinyin":"Xièxie lǎoshī."},{"speaker":"老师","cn":"不客气，你们以后有任何问题都可以来找我。","pinyin":"Bú kèqi, nǐmen yǐhòu yǒu rènhé wèntí dōu kěyǐ lái zhǎo wǒ."}],"translation_vn":"Cô giáo: Các em chào, chào mừng các em đến Trung Quốc du học! Hãy đưa hộ chiếu, visa và giấy báo nhập học cho cô.\nBạch Gia Nguyệt: Vâng ạ. Đây là giấy tờ và tài liệu của chúng em.\n(Vài phút sau.)\nCô giáo: Xong rồi, đây là thẻ sinh viên của các em, thứ Hai tuần sau bắt đầu học. Trước tiên dự thính hai tuần, sau đó chọn môn học trên mạng.\nBạch Gia Nguyệt, Trần Thiên Trung: Chúng em cảm ơn cô ạ.\nCô giáo: Không có gì, sau này các em có bất cứ vấn đề gì đều có thể đến tìm cô.","audio_dialogue":"1-1.mp3","audio_vocab":"1-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"陈天中","cn":"你看，咱们的校园真大！有图书馆、体育馆、超市，还有好几个食堂。","pinyin":"Nǐ kàn, zánmen de xiàoyuán zhēn dà! Yǒu túshūguǎn, tǐyùguǎn, chāoshì, hái yǒu hǎojǐ gè shítáng."},{"speaker":"白家月","cn":"是啊，我觉得学校就像一座小城市，什么都有，方便极了。","pinyin":"Shì a, wǒ juéde xuéxiào jiù xiàng yí zuò xiǎo chéngshì, shénme dōu yǒu, fāngbiàn jíle."},{"speaker":"陈天中","cn":"刚才老师说，咱们可以申请奖学金，你了解过吗？","pinyin":"Gāngcái lǎoshī shuō, zánmen kěyǐ shēnqǐng jiǎngxuéjīn, nǐ liǎojiě guo ma?"},{"speaker":"白家月","cn":"我听说过一点儿，好像成绩好、表现好的学生都有机会获得奖学金。","pinyin":"Wǒ tīngshuō guo yìdiǎnr, hǎoxiàng chéngjì hǎo, biǎoxiàn hǎo de xuésheng dōu yǒu jīhuì huòdé jiǎngxuéjīn."},{"speaker":"陈天中","cn":"那太好了，要是申请到奖学金，就能减轻不少经济压力。","pinyin":"Nà tài hǎo le, yàoshi shēnqǐng dào jiǎngxuéjīn, jiù néng jiǎnqīng bùshǎo jīngjì yālì."},{"speaker":"白家月","cn":"没错，我们一起加油吧！","pinyin":"Méicuò, wǒmen yìqǐ jiāyóu ba!"}],"translation_vn":"Trần Thiên Trung: Cậu xem, khuôn viên trường mình thật rộng! Có thư viện, nhà thi đấu, siêu thị, còn có mấy nhà ăn nữa.\nBạch Gia Nguyệt: Đúng vậy, mình thấy trường học giống như một thành phố nhỏ, cái gì cũng có, tiện lợi vô cùng.\nTrần Thiên Trung: Vừa nãy thầy/cô nói, chúng mình có thể xin học bổng, cậu tìm hiểu chưa?\nBạch Gia Nguyệt: Mình nghe nói một chút, hình như sinh viên có thành tích tốt, biểu hiện tốt đều có cơ hội giành được học bổng.\nTrần Thiên Trung: Thế thì tốt quá, nếu xin được học bổng thì có thể giảm bớt không ít áp lực kinh tế.\nBạch Gia Nguyệt: Đúng vậy, chúng mình cùng cố gắng nhé!","audio_dialogue":"1-3.mp3","audio_vocab":"1-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"随着中国的发展，越来越多的外国学生来到中国的大学学习。他们可以先上一年的中文课程，然后根据自己的兴趣和需要选择专业。除了读本科课程，他们还可以申请读硕士研究生或者博士研究生。在大学里，外国学生可以和中国学生一起学习、做研究、参加校园活动。通过这些交流，外国学生能更快地适应中国的大学生活。","pinyin":"Suízhe Zhōngguó de fāzhǎn, yuèláiyuè duō de wàiguó xuésheng láidào Zhōngguó de dàxué xuéxí. Tāmen kěyǐ xiān shàng yì nián de Zhōngwén kèchéng, ránhòu gēnjù zìjǐ de xìngqù hé xūyào xuǎnzé zhuānyè. Chúle dú běnkē kèchéng, tāmen hái kěyǐ shēnqǐng dú shuòshì yánjiūshēng huòzhě bóshì yánjiūshēng. Zài dàxué lǐ, wàiguó xuésheng kěyǐ hé Zhōngguó xuésheng yìqǐ xuéxí, zuò yánjiū, cānjiā xiàoyuán huódòng. Tōngguò zhèxiē jiāoliú, wàiguó xuésheng néng gèng kuài de shìyìng Zhōngguó de dàxué shēnghuó."}],"translation_vn":"Cùng với sự phát triển của Trung Quốc, ngày càng nhiều du học sinh nước ngoài đến các trường đại học Trung Quốc học tập. Họ có thể học một năm khóa tiếng Trung trước, sau đó căn cứ vào sở thích và nhu cầu của bản thân để chọn chuyên ngành. Ngoài việc học chương trình đại học, họ còn có thể xin học thạc sĩ hoặc tiến sĩ. Ở trường đại học, du học sinh nước ngoài có thể cùng học tập, nghiên cứu, tham gia các hoạt động trong khuôn viên trường với sinh viên Trung Quốc. Thông qua những giao lưu này, du học sinh nước ngoài có thể nhanh chóng thích nghi với cuộc sống đại học ở Trung Quốc.","audio_dialogue":"1-5.mp3","audio_vocab":"1-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"很多外国学生来中国学习以前，就已经想好了自己的发展方向。有人对经济感兴趣，希望将来在国际公司工作；有人喜欢学医，打算回国后当一名医生；还有人对教育有热情，想要成为一名教师。陈天中想选择跟经济有关的专业，希望通过学习，了解更多国际贸易方面的知识。安妮以后想做一名中文老师，所以要选择国际中文教育专业。对他们来说，来到中国留学，一方面是为了学习语言和知识，另一方面也是为将来的工作和生活做准备。","pinyin":"Hěn duō wàiguó xuésheng lái Zhōngguó xuéxí yǐqián, jiù yǐjīng xiǎnghǎo le zìjǐ de fāzhǎn fāngxiàng. Yǒu rén duì jīngjì gǎn xìngqù, xīwàng jiānglái zài guójì gōngsī gōngzuò; yǒu rén xǐhuan xuéyī, dǎsuàn huíguó hòu dāng yì míng yīshēng; hái yǒu rén duì jiàoyù yǒu rèqíng, xiǎngyào chéngwéi yì míng jiàoshī. Chén Tiānzhōng xiǎng xuǎnzé gēn jīngjì yǒuguān de zhuānyè, xīwàng tōngguò xuéxí, liǎojiě gèng duō guójì màoyì fāngmiàn de zhīshi. Ānnī yǐhòu xiǎng zuò yì míng Zhōngwén lǎoshī, suǒyǐ yào xuǎnzé guójì Zhōngwén jiàoyù zhuānyè. Duì tāmen láishuō, láidào Zhōngguó liúxué, yì fāngmiàn shì wèile xuéxí yǔyán hé zhīshi, lìng yì fāngmiàn yě shì wèi jiānglái de gōngzuò hé shēnghuó zuò zhǔnbèi."}],"translation_vn":"Rất nhiều du học sinh nước ngoài trước khi đến Trung Quốc học tập đã nghĩ kỹ về hướng phát triển của bản thân. Có người hứng thú với kinh tế, hy vọng sau này làm việc trong công ty quốc tế; có người thích học y, dự định về nước làm bác sĩ; lại có người nhiệt huyết với giáo dục, muốn trở thành giáo viên. Trần Thiên Trung muốn chọn chuyên ngành liên quan đến kinh tế, hy vọng thông qua việc học để hiểu biết thêm về lĩnh vực thương mại quốc tế. Annie sau này muốn làm giáo viên tiếng Trung, vì vậy sẽ chọn chuyên ngành Giáo dục tiếng Trung quốc tế. Đối với họ, đến Trung Quốc du học, một mặt là để học ngôn ngữ và kiến thức, mặt khác cũng là để chuẩn bị cho công việc và cuộc sống sau này.","audio_dialogue":"1-7.mp3","audio_vocab":"1-8.mp3"}]},{"id":2,"title_cn":"租到了合适的房子","title_pinyin":"Zūdào le héshì de fángzi","title_vn":"Tôi đã thuê được căn nhà phù hợp","goals":["Có thể nghe hiểu và trao đổi các chủ đề liên quan đến việc thuê nhà.","Có thể trình bày bằng lời hoặc bằng văn bản nguyện vọng, yêu cầu thuê nhà,...","Hiểu được quan niệm về nhà ở của người Trung Quốc."],"vocab":[{"hanzi":"房东","pinyin":"fángdōng","pos":"dt.","vn":"chủ nhà","examples":[{"cn":"我的房东人很好，经常帮我修东西。","pinyin":"Wǒ de fángdōng rén hěn hǎo, jīngcháng bāng wǒ xiū dōngxi.","vn":"Chủ nhà của tôi rất tốt bụng, thường giúp tôi sửa đồ."},{"cn":"房东昨天通知我下个月要涨房租。","pinyin":"Fángdōng zuótiān tōngzhī wǒ xià ge yuè yào zhǎng fángzū.","vn":"Chủ nhà hôm qua báo tôi là tháng sau sẽ tăng tiền thuê."},{"cn":"我跟房东商量了一下搬家的事。","pinyin":"Wǒ gēn fángdōng shāngliang le yíxià bānjiā de shì.","vn":"Tôi đã bàn bạc với chủ nhà về chuyện chuyển nhà."}]},{"hanzi":"出租","pinyin":"chūzū","pos":"dgt.","vn":"cho thuê","examples":[{"cn":"这套房子正在出租。","pinyin":"Zhè tào fángzi zhèngzài chūzū.","vn":"Căn nhà này đang được cho thuê."},{"cn":"他把多余的房间出租给了学生。","pinyin":"Tā bǎ duōyú de fángjiān chūzū gěi le xuésheng.","vn":"Anh ấy đã cho sinh viên thuê căn phòng thừa."},{"cn":"我们公司有出租车可以用。","pinyin":"Wǒmen gōngsī yǒu chūzūchē kěyǐ yòng.","vn":"Công ty chúng tôi có taxi để sử dụng."}]},{"hanzi":"房租","pinyin":"fángzū","pos":"dt.","vn":"tiền thuê nhà","examples":[{"cn":"这边的房租每个月要三千块。","pinyin":"Zhèbiān de fángzū měi ge yuè yào sānqiān kuài.","vn":"Tiền thuê nhà ở đây mỗi tháng là ba nghìn tệ."},{"cn":"房租这个月还没交呢。","pinyin":"Fángzū zhège yuè hái méi jiāo ne.","vn":"Tiền thuê nhà tháng này vẫn chưa đóng."},{"cn":"市中心的房租比郊区贵多了。","pinyin":"Shìzhōngxīn de fángzū bǐ jiāoqū guì duō le.","vn":"Tiền thuê nhà ở trung tâm thành phố đắt hơn ngoại ô nhiều."}]},{"hanzi":"收拾","pinyin":"shōushi","pos":"dgt.","vn":"dọn dẹp, thu dọn","examples":[{"cn":"周末我打算好好收拾一下房间。","pinyin":"Zhōumò wǒ dǎsuàn hǎohǎo shōushi yíxià fángjiān.","vn":"Cuối tuần tôi định dọn dẹp phòng cho thật sạch sẽ."},{"cn":"出发之前记得把行李收拾好。","pinyin":"Chūfā zhīqián jìde bǎ xíngli shōushi hǎo.","vn":"Trước khi xuất phát nhớ thu dọn hành lý cho gọn gàng."},{"cn":"他从来不收拾自己的桌子。","pinyin":"Tā cónglái bù shōushi zìjǐ de zhuōzi.","vn":"Anh ấy chưa bao giờ dọn dẹp bàn của mình."}]},{"hanzi":"租","pinyin":"zū","pos":"dgt.","vn":"thuê","examples":[{"cn":"我在北京租了一个单间。","pinyin":"Wǒ zài Běijīng zū le yí ge dānjiān.","vn":"Tôi đã thuê một phòng đơn ở Bắc Kinh."},{"cn":"他们打算租一辆车去旅游。","pinyin":"Tāmen dǎsuàn zū yí liàng chē qù lǚyóu.","vn":"Họ định thuê một chiếc xe để đi du lịch."},{"cn":"这里租房子方便吗？","pinyin":"Zhèlǐ zū fángzi fāngbiàn ma?","vn":"Thuê nhà ở đây có tiện không?"}]},{"hanzi":"嗯","pinyin":"ng","pos":"ct.","vn":"ừ, vâng","examples":[{"cn":"嗯，我知道了。","pinyin":"Ng, wǒ zhīdào le.","vn":"Ừ, tôi biết rồi."},{"cn":"嗯，这个主意不错。","pinyin":"Ng, zhège zhǔyi búcuò.","vn":"Ừ, ý kiến này không tệ."},{"cn":"嗯……让我再想想。","pinyin":"Ng……ràng wǒ zài xiǎngxiang.","vn":"Ừm... để tôi nghĩ thêm chút nữa."}]},{"hanzi":"亮","pinyin":"liàng","pos":"tt./dgt.","vn":"sáng, sáng sủa","examples":[{"cn":"这个房间的灯特别亮。","pinyin":"Zhège fángjiān de dēng tèbié liàng.","vn":"Đèn của căn phòng này rất sáng."},{"cn":"天刚亮他就起床了。","pinyin":"Tiān gāng liàng tā jiù qǐchuáng le.","vn":"Trời vừa sáng là anh ấy đã dậy rồi."},{"cn":"屋子里亮着一盏小灯。","pinyin":"Wūzi lǐ liàng zhe yì zhǎn xiǎo dēng.","vn":"Trong phòng sáng một ngọn đèn nhỏ."}]},{"hanzi":"就是","pinyin":"jiùshì","pos":"trợ.","vn":"(trợ từ dùng cuối câu, thường đi với \"了\" để nhấn mạnh sự khẳng định) là được, thế thôi","examples":[{"cn":"你喜欢就是了，别管别人怎么说。","pinyin":"Nǐ xǐhuan jiùshì le, bié guǎn biéren zěnme shuō.","vn":"Bạn thích là được, đừng quan tâm người khác nói gì."},{"cn":"别想太多，做好自己的事就是了。","pinyin":"Bié xiǎng tài duō, zuò hǎo zìjǐ de shì jiùshì le.","vn":"Đừng nghĩ nhiều quá, làm tốt việc của mình là được."},{"cn":"他只是说说而已，你别放在心上就是了。","pinyin":"Tā zhǐshì shuōshuo éryǐ, nǐ bié fàng zài xīnshang jiùshì le.","vn":"Anh ấy chỉ nói vậy thôi, bạn đừng để trong lòng là được rồi."}]},{"hanzi":"种","pinyin":"zhòng","pos":"dgt.","vn":"trồng","examples":[{"cn":"爷爷在院子里种了很多花。","pinyin":"Yéye zài yuànzi lǐ zhòng le hěn duō huā.","vn":"Ông nội đã trồng rất nhiều hoa trong sân."},{"cn":"我们打算在阳台上种点蔬菜。","pinyin":"Wǒmen dǎsuàn zài yángtái shang zhòng diǎn shūcài.","vn":"Chúng tôi định trồng chút rau trên ban công."},{"cn":"这种树很容易种活。","pinyin":"Zhè zhǒng shù hěn róngyì zhòng huó.","vn":"Loại cây này rất dễ trồng sống."}]},{"hanzi":"周围","pinyin":"zhōuwéi","pos":"dt.","vn":"xung quanh","examples":[{"cn":"我家周围有很多商店。","pinyin":"Wǒ jiā zhōuwéi yǒu hěn duō shāngdiàn.","vn":"Xung quanh nhà tôi có rất nhiều cửa hàng."},{"cn":"学校周围环境很安静。","pinyin":"Xuéxiào zhōuwéi huánjìng hěn ānjìng.","vn":"Môi trường xung quanh trường rất yên tĩnh."},{"cn":"他看了看周围，发现没有人。","pinyin":"Tā kàn le kàn zhōuwéi, fāxiàn méiyǒu rén.","vn":"Anh ấy nhìn quanh và phát hiện không có ai."}]},{"hanzi":"不过","pinyin":"búguò","pos":"liên.","vn":"nhưng, tuy nhiên","examples":[{"cn":"这个地方不错，不过有点儿贵。","pinyin":"Zhège dìfang búcuò, búguò yǒudiǎnr guì.","vn":"Chỗ này khá được, nhưng mà hơi đắt một chút."},{"cn":"他很聪明，不过有时候太粗心。","pinyin":"Tā hěn cōngming, búguò yǒushíhou tài cūxīn.","vn":"Anh ấy rất thông minh, nhưng đôi khi hơi bất cẩn."},{"cn":"我想去，不过没有时间。","pinyin":"Wǒ xiǎng qù, búguò méiyǒu shíjiān.","vn":"Tôi muốn đi, nhưng không có thời gian."}]},{"hanzi":"毕业","pinyin":"bìyè","pos":"dgt.","vn":"tốt nghiệp","examples":[{"cn":"他今年夏天就要毕业了。","pinyin":"Tā jīnnián xiàtiān jiù yào bìyè le.","vn":"Mùa hè năm nay anh ấy sắp tốt nghiệp rồi."},{"cn":"毕业以后你有什么打算？","pinyin":"Bìyè yǐhòu nǐ yǒu shénme dǎsuàn?","vn":"Sau khi tốt nghiệp bạn có dự định gì?"},{"cn":"我们是同一年毕业的。","pinyin":"Wǒmen shì tóng yì nián bìyè de.","vn":"Chúng tôi tốt nghiệp cùng một năm."}]},{"hanzi":"恐怕","pinyin":"kǒngpà","pos":"phó.","vn":"e rằng, sợ rằng","examples":[{"cn":"外面下雨了，我们恐怕去不了了。","pinyin":"Wàimiàn xiàyǔ le, wǒmen kǒngpà qù bu liǎo le.","vn":"Ngoài trời đang mưa, e là chúng ta không đi được rồi."},{"cn":"这件事恐怕没那么简单。","pinyin":"Zhè jiàn shì kǒngpà méi nàme jiǎndān.","vn":"Việc này e rằng không đơn giản như vậy."},{"cn":"他今天恐怕来不了了。","pinyin":"Tā jīntiān kǒngpà lái bu liǎo le.","vn":"Hôm nay e là anh ấy không đến được."}]},{"hanzi":"热闹","pinyin":"rènao","pos":"dgt./tt./dt.","vn":"náo nhiệt, nhộn nhịp; sự náo nhiệt","examples":[{"cn":"春节的时候街上特别热闹。","pinyin":"Chūnjié de shíhou jiē shang tèbié rènao.","vn":"Vào dịp Tết Nguyên Đán đường phố rất náo nhiệt."},{"cn":"我喜欢热闹的地方。","pinyin":"Wǒ xǐhuan rènao de dìfang.","vn":"Tôi thích những nơi náo nhiệt."},{"cn":"大家一起聊天，气氛很热闹。","pinyin":"Dàjiā yìqǐ liáotiān, qìfēn hěn rènao.","vn":"Mọi người cùng nhau trò chuyện, không khí rất nhộn nhịp."}]},{"hanzi":"入住","pinyin":"rùzhù","pos":"dgt.","vn":"chuyển vào ở, nhận phòng","examples":[{"cn":"我们下午三点才能入住酒店。","pinyin":"Wǒmen xiàwǔ sān diǎn cái néng rùzhù jiǔdiàn.","vn":"Ba giờ chiều chúng tôi mới có thể nhận phòng khách sạn."},{"cn":"新房子已经装修好了，可以入住了。","pinyin":"Xīn fángzi yǐjīng zhuāngxiū hǎo le, kěyǐ rùzhù le.","vn":"Nhà mới đã trang trí xong rồi, có thể dọn vào ở được rồi."},{"cn":"入住的时候需要出示身份证。","pinyin":"Rùzhù de shíhou xūyào chūshì shēnfènzhèng.","vn":"Khi nhận phòng cần xuất trình chứng minh thư."}]},{"hanzi":"日记","pinyin":"rìjì","pos":"dt.","vn":"nhật ký","examples":[{"cn":"她每天都写日记。","pinyin":"Tā měitiān dōu xiě rìjì.","vn":"Mỗi ngày cô ấy đều viết nhật ký."},{"cn":"我把今天发生的事记在了日记里。","pinyin":"Wǒ bǎ jīntiān fāshēng de shì jì zài le rìjì lǐ.","vn":"Tôi đã ghi lại chuyện xảy ra hôm nay vào nhật ký."},{"cn":"这是我中学时候写的日记。","pinyin":"Zhè shì wǒ zhōngxué shíhou xiě de rìjì.","vn":"Đây là cuốn nhật ký tôi viết hồi trung học."}]},{"hanzi":"顺利","pinyin":"shùnlì","pos":"tt.","vn":"thuận lợi, suôn sẻ","examples":[{"cn":"祝你考试顺利！","pinyin":"Zhù nǐ kǎoshì shùnlì!","vn":"Chúc bạn thi cử thuận lợi!"},{"cn":"这次旅行一切都很顺利。","pinyin":"Zhè cì lǚxíng yíqiè dōu hěn shùnlì.","vn":"Chuyến du lịch lần này mọi thứ đều rất suôn sẻ."},{"cn":"事情没有想象中那么顺利。","pinyin":"Shìqing méiyǒu xiǎngxiàng zhōng nàme shùnlì.","vn":"Mọi việc không suôn sẻ như trong tưởng tượng."}]},{"hanzi":"并","pinyin":"bìng","pos":"liên./phó.","vn":"và, hơn nữa; (nhấn mạnh phủ định) hoàn toàn (không)","examples":[{"cn":"他并没有想象中那么难相处。","pinyin":"Tā bìng méiyǒu xiǎngxiàng zhōng nàme nán xiāngchǔ.","vn":"Anh ấy hoàn toàn không khó gần như trong tưởng tượng."},{"cn":"我并不是不喜欢这个工作。","pinyin":"Wǒ bìng bú shì bù xǐhuan zhège gōngzuò.","vn":"Tôi hoàn toàn không phải là không thích công việc này."},{"cn":"会议通过了这个计划，并决定下周开始实施。","pinyin":"Huìyì tōngguò le zhège jìhuà, bìng juédìng xiàzhōu kāishǐ shíshī.","vn":"Cuộc họp đã thông qua kế hoạch này, và quyết định tuần sau bắt đầu thực hiện."}]},{"hanzi":"客厅","pinyin":"kètīng","pos":"dt.","vn":"phòng khách","examples":[{"cn":"客厅里放着一张大沙发。","pinyin":"Kètīng lǐ fàng zhe yì zhāng dà shāfā.","vn":"Trong phòng khách đặt một chiếc ghế sofa lớn."},{"cn":"我们家的客厅不太大。","pinyin":"Wǒmen jiā de kètīng bú tài dà.","vn":"Phòng khách nhà chúng tôi không to lắm."},{"cn":"晚上大家都坐在客厅看电视。","pinyin":"Wǎnshang dàjiā dōu zuò zài kètīng kàn diànshì.","vn":"Buổi tối mọi người đều ngồi ở phòng khách xem tivi."}]},{"hanzi":"台","pinyin":"tái","pos":"lượng.","vn":"(lượng từ dùng cho máy móc, thiết bị,...)","examples":[{"cn":"我买了一台新电脑。","pinyin":"Wǒ mǎi le yì tái xīn diànnǎo.","vn":"Tôi đã mua một chiếc máy tính mới."},{"cn":"厨房里有一台洗碗机。","pinyin":"Chúfáng lǐ yǒu yì tái xǐwǎnjī.","vn":"Trong bếp có một chiếc máy rửa bát."},{"cn":"这台空调用了好几年了。","pinyin":"Zhè tái kōngtiáo yòng le hǎo jǐ nián le.","vn":"Chiếc điều hòa này đã dùng được mấy năm rồi."}]},{"hanzi":"厨房","pinyin":"chúfáng","pos":"dt.","vn":"nhà bếp","examples":[{"cn":"妈妈在厨房做饭。","pinyin":"Māma zài chúfáng zuòfàn.","vn":"Mẹ đang nấu cơm trong bếp."},{"cn":"这个厨房有点儿小。","pinyin":"Zhège chúfáng yǒudiǎnr xiǎo.","vn":"Nhà bếp này hơi nhỏ một chút."},{"cn":"厨房里有很多锅碗瓢盆。","pinyin":"Chúfáng lǐ yǒu hěn duō guōwǎnpiáopén.","vn":"Trong bếp có rất nhiều nồi niêu xoong chảo."}]},{"hanzi":"平常","pinyin":"píngcháng","pos":"dt./tt.","vn":"ngày thường; bình thường","examples":[{"cn":"他平常不怎么说话。","pinyin":"Tā píngcháng bù zěnme shuōhuà.","vn":"Bình thường anh ấy không hay nói chuyện."},{"cn":"我平常都坐地铁上班。","pinyin":"Wǒ píngcháng dōu zuò dìtiě shàngbān.","vn":"Bình thường tôi đi tàu điện ngầm đi làm."},{"cn":"今天跟平常不太一样。","pinyin":"Jīntiān gēn píngcháng bú tài yíyàng.","vn":"Hôm nay không giống ngày thường lắm."}]},{"hanzi":"基本上","pinyin":"jīběnshàng","pos":"phó.","vn":"về cơ bản, về căn bản","examples":[{"cn":"这件事基本上已经解决了。","pinyin":"Zhè jiàn shì jīběnshàng yǐjīng jiějué le.","vn":"Việc này về cơ bản đã giải quyết xong rồi."},{"cn":"我基本上每天都去健身房。","pinyin":"Wǒ jīběnshàng měitiān dōu qù jiànshēnfáng.","vn":"Về cơ bản mỗi ngày tôi đều đến phòng tập."},{"cn":"他说的基本上都是事实。","pinyin":"Tā shuō de jīběnshàng dōu shì shìshí.","vn":"Những gì anh ấy nói về cơ bản đều là sự thật."}]},{"hanzi":"整个","pinyin":"zhěnggè","pos":"tt.","vn":"cả, toàn bộ","examples":[{"cn":"他整个下午都在睡觉。","pinyin":"Tā zhěnggè xiàwǔ dōu zài shuìjiào.","vn":"Cả buổi chiều anh ấy đều ngủ."},{"cn":"这场雨下了整个晚上。","pinyin":"Zhè chǎng yǔ xià le zhěnggè wǎnshang.","vn":"Trận mưa này đã rơi suốt cả đêm."},{"cn":"整个班都为他感到骄傲。","pinyin":"Zhěnggè bān dōu wèi tā gǎndào jiāo'ào.","vn":"Cả lớp đều cảm thấy tự hào về anh ấy."}]},{"hanzi":"毛巾","pinyin":"máojīn","pos":"dt.","vn":"khăn mặt","examples":[{"cn":"请把毛巾挂在那边。","pinyin":"Qǐng bǎ máojīn guà zài nàbiān.","vn":"Làm ơn treo khăn mặt ở đằng kia."},{"cn":"这条毛巾是新买的。","pinyin":"Zhè tiáo máojīn shì xīn mǎi de.","vn":"Chiếc khăn mặt này mới mua."},{"cn":"洗完脸用毛巾擦干。","pinyin":"Xǐ wán liǎn yòng máojīn cā gān.","vn":"Rửa mặt xong dùng khăn lau khô."}]},{"hanzi":"建议","pinyin":"jiànyì","pos":"dt./dgt.","vn":"đề nghị, gợi ý","examples":[{"cn":"我建议你早点睡觉。","pinyin":"Wǒ jiànyì nǐ zǎodiǎn shuìjiào.","vn":"Tôi đề nghị bạn đi ngủ sớm một chút."},{"cn":"他给了我一个很好的建议。","pinyin":"Tā gěi le wǒ yí ge hěn hǎo de jiànyì.","vn":"Anh ấy đã đưa cho tôi một gợi ý rất hay."},{"cn":"谢谢你的建议，我会考虑的。","pinyin":"Xièxie nǐ de jiànyì, wǒ huì kǎolǜ de.","vn":"Cảm ơn lời đề nghị của bạn, tôi sẽ cân nhắc."}]},{"hanzi":"查看","pinyin":"chákàn","pos":"dgt.","vn":"xem xét, kiểm tra","examples":[{"cn":"请查看一下你的邮箱。","pinyin":"Qǐng chákàn yíxià nǐ de yóuxiāng.","vn":"Hãy kiểm tra hộp thư của bạn một chút."},{"cn":"我每天都会查看天气预报。","pinyin":"Wǒ měitiān dōu huì chákàn tiānqì yùbào.","vn":"Mỗi ngày tôi đều xem dự báo thời tiết."},{"cn":"他打开手机查看了一下时间。","pinyin":"Tā dǎkāi shǒujī chákàn le yíxià shíjiān.","vn":"Anh ấy mở điện thoại xem giờ một chút."}]},{"hanzi":"信息","pinyin":"xìnxī","pos":"dt.","vn":"thông tin","examples":[{"cn":"你可以在网上查这个信息。","pinyin":"Nǐ kěyǐ zài wǎngshàng chá zhège xìnxī.","vn":"Bạn có thể tra thông tin này trên mạng."},{"cn":"他给我发了一条信息。","pinyin":"Tā gěi wǒ fā le yì tiáo xìnxī.","vn":"Anh ấy đã gửi cho tôi một tin nhắn."},{"cn":"这个消息来源的信息不太可靠。","pinyin":"Zhège xiāoxi láiyuán de xìnxī bú tài kěkào.","vn":"Thông tin từ nguồn tin này không mấy đáng tin cậy."}]},{"hanzi":"查找","pinyin":"cházhǎo","pos":"dgt.","vn":"tìm kiếm","examples":[{"cn":"我在网上查找相关的资料。","pinyin":"Wǒ zài wǎngshàng cházhǎo xiāngguān de zīliào.","vn":"Tôi đang tìm kiếm tài liệu liên quan trên mạng."},{"cn":"他花了很长时间查找原因。","pinyin":"Tā huā le hěn cháng shíjiān cházhǎo yuányīn.","vn":"Anh ấy đã mất rất nhiều thời gian tìm hiểu nguyên nhân."},{"cn":"你可以用这个软件查找附近的餐厅。","pinyin":"Nǐ kěyǐ yòng zhège ruǎnjiàn cházhǎo fùjìn de cāntīng.","vn":"Bạn có thể dùng phần mềm này để tìm nhà hàng gần đó."}]},{"hanzi":"接着","pinyin":"jiēzhe","pos":"phó./dgt.","vn":"tiếp theo, sau đó","examples":[{"cn":"他说完以后，接着就离开了。","pinyin":"Tā shuō wán yǐhòu, jiēzhe jiù líkāi le.","vn":"Anh ấy nói xong là lập tức rời đi."},{"cn":"先把菜洗好，接着切成小块。","pinyin":"Xiān bǎ cài xǐ hǎo, jiēzhe qiē chéng xiǎo kuài.","vn":"Trước tiên rửa sạch rau, tiếp theo cắt thành miếng nhỏ."},{"cn":"他接着我的话往下讲。","pinyin":"Tā jiēzhe wǒ de huà wǎng xià jiǎng.","vn":"Anh ấy tiếp lời tôi nói tiếp."}]},{"hanzi":"同时","pinyin":"tóngshí","pos":"liên./dt.","vn":"đồng thời","examples":[{"cn":"他一边听音乐，同时一边做作业。","pinyin":"Tā yìbiān tīng yīnyuè, tóngshí yìbiān zuò zuòyè.","vn":"Anh ấy vừa nghe nhạc, đồng thời vừa làm bài tập."},{"cn":"这个方法又快又好，同时也很省钱。","pinyin":"Zhège fāngfǎ yòu kuài yòu hǎo, tóngshí yě hěn shěngqián.","vn":"Phương pháp này vừa nhanh vừa tốt, đồng thời cũng rất tiết kiệm tiền."},{"cn":"两件事几乎是同时发生的。","pinyin":"Liǎng jiàn shì jīhū shì tóngshí fāshēng de.","vn":"Hai việc này gần như xảy ra đồng thời."}]},{"hanzi":"位置","pinyin":"wèizhì","pos":"dt.","vn":"vị trí","examples":[{"cn":"这个房子的位置很方便。","pinyin":"Zhège fángzi de wèizhì hěn fāngbiàn.","vn":"Vị trí của căn nhà này rất tiện lợi."},{"cn":"请把杯子放回原来的位置。","pinyin":"Qǐng bǎ bēizi fàng huí yuánlái de wèizhì.","vn":"Hãy đặt cốc về vị trí ban đầu."},{"cn":"我找不到这家店的具体位置。","pinyin":"Wǒ zhǎo bu dào zhè jiā diàn de jùtǐ wèizhì.","vn":"Tôi không tìm được vị trí cụ thể của cửa hàng này."}]},{"hanzi":"价格","pinyin":"jiàgé","pos":"dt.","vn":"giá cả","examples":[{"cn":"这家店的价格挺合理的。","pinyin":"Zhè jiā diàn de jiàgé tǐng hélǐ de.","vn":"Giá cả của cửa hàng này khá hợp lý."},{"cn":"最近水果的价格涨了不少。","pinyin":"Zuìjìn shuǐguǒ de jiàgé zhǎng le bùshǎo.","vn":"Dạo gần đây giá hoa quả đã tăng khá nhiều."},{"cn":"你可以比较一下不同商店的价格。","pinyin":"Nǐ kěyǐ bǐjiào yíxià bùtóng shāngdiàn de jiàgé.","vn":"Bạn có thể so sánh giá cả của các cửa hàng khác nhau."}]},{"hanzi":"理想","pinyin":"lǐxiǎng","pos":"tt./dt.","vn":"lý tưởng","examples":[{"cn":"这个结果不太理想。","pinyin":"Zhège jiéguǒ bú tài lǐxiǎng.","vn":"Kết quả này không mấy lý tưởng."},{"cn":"这套房子的位置非常理想。","pinyin":"Zhè tào fángzi de wèizhì fēicháng lǐxiǎng.","vn":"Vị trí của căn nhà này rất lý tưởng."},{"cn":"每个人都有自己的理想。","pinyin":"Měi ge rén dōu yǒu zìjǐ de lǐxiǎng.","vn":"Mỗi người đều có lý tưởng của riêng mình."}]},{"hanzi":"由于","pinyin":"yóuyú","pos":"liên./giới.","vn":"do, bởi vì","examples":[{"cn":"由于下大雨，比赛取消了。","pinyin":"Yóuyú xià dàyǔ, bǐsài qǔxiāo le.","vn":"Do trời mưa to nên trận đấu đã bị hủy."},{"cn":"由于身体不舒服，他请假了。","pinyin":"Yóuyú shēntǐ bù shūfu, tā qǐngjià le.","vn":"Do cảm thấy không khỏe nên anh ấy đã xin nghỉ."},{"cn":"由于工作太忙，他很久没回家了。","pinyin":"Yóuyú gōngzuò tài máng, tā hěn jiǔ méi huíjiā le.","vn":"Do công việc quá bận nên anh ấy đã lâu không về nhà."}]},{"hanzi":"工资","pinyin":"gōngzī","pos":"dt.","vn":"tiền lương","examples":[{"cn":"他这个月的工资还没发。","pinyin":"Tā zhège yuè de gōngzī hái méi fā.","vn":"Lương tháng này của anh ấy vẫn chưa được phát."},{"cn":"这份工作工资不高，但是很稳定。","pinyin":"Zhè fèn gōngzuò gōngzī bù gāo, dànshì hěn wěndìng.","vn":"Công việc này lương không cao nhưng rất ổn định."},{"cn":"公司每个月十号发工资。","pinyin":"Gōngsī měi ge yuè shí hào fā gōngzī.","vn":"Công ty trả lương vào ngày mười hằng tháng."}]},{"hanzi":"感","pinyin":"gǎn","pos":"htố.","vn":"(hậu tố chỉ cảm giác) cảm","examples":[{"cn":"他对这份工作很有成就感。","pinyin":"Tā duì zhè fèn gōngzuò hěn yǒu chéngjiùgǎn.","vn":"Anh ấy có cảm giác thành tựu rất lớn với công việc này."},{"cn":"这件事让我很有安全感。","pinyin":"Zhè jiàn shì ràng wǒ hěn yǒu ānquángǎn.","vn":"Việc này khiến tôi cảm thấy rất an toàn."},{"cn":"住在这里让人有一种归属感。","pinyin":"Zhù zài zhèlǐ ràng rén yǒu yì zhǒng guīshǔgǎn.","vn":"Sống ở đây khiến người ta có cảm giác thuộc về."}]}],"grammar":[{"title":"固定格式\"×就是了\"","explanation_vn":"Cấu trúc cố định \"×就是了\" được dùng trong khẩu ngữ, đặt ở cuối câu để biểu thị ý khẳng định.","examples":[{"cn":"如果决定租了，告诉我就是了。","pinyin":"Rúguǒ juédìng zū le, gàosu wǒ jiùshì le.","vn":"Nếu quyết định thuê rồi thì báo cho tôi là được."},{"cn":"我一定能办到，您放心就是了。","pinyin":"Wǒ yídìng néng bàndào, nín fàngxīn jiùshì le.","vn":"Tôi chắc chắn làm được, ông/bà cứ yên tâm."},{"cn":"这次考得不好没关系，下次努力就是了。","pinyin":"Zhè cì kǎo de bù hǎo méi guānxi, xià cì nǔlì jiùshì le.","vn":"Lần này thi không tốt cũng không sao, lần sau cố gắng là được."}]},{"title":"转折复句\"……，不过……\"","explanation_vn":"Liên từ \"不过\" được dùng ở đầu vế câu thứ hai trong hai vế câu, biểu thị ý chuyển ngoặt.","examples":[{"cn":"这个小区的环境真不错，不过我听说，附近有十几家公司，很多刚毕业的学生都租住在这里。","pinyin":"Zhège xiǎoqū de huánjìng zhēn búcuò, búguò wǒ tīngshuō, fùjìn yǒu shíjǐ jiā gōngsī, hěn duō gāng bìyè de xuésheng dōu zūzhù zài zhèlǐ.","vn":"Môi trường khu dân cư này thật sự không tệ, nhưng tôi nghe nói gần đó có hơn chục công ty, rất nhiều sinh viên mới tốt nghiệp đều thuê nhà ở đây."},{"cn":"我们在动物园看见了很多动物，不过没看见大熊猫。","pinyin":"Wǒmen zài dòngwùyuán kànjiàn le hěn duō dòngwù, búguò méi kànjiàn dàxióngmāo.","vn":"Chúng tôi đã nhìn thấy rất nhiều động vật ở sở thú, nhưng không nhìn thấy gấu trúc."},{"cn":"我刚来北京时还不太习惯这里的天气，不过很快就适应了。","pinyin":"Wǒ gāng lái Běijīng shí hái bú tài xíguàn zhèlǐ de tiānqì, búguò hěn kuài jiù shìyìng le.","vn":"Khi mới đến Bắc Kinh tôi vẫn chưa quen lắm với thời tiết ở đây, nhưng rất nhanh đã thích nghi được."}]},{"title":"连词/副词\"并\"","explanation_vn":"\"并\" có nhiều cách dùng. Phần này giới thiệu hai cách dùng của \"并\" là liên từ và phó từ: (1) \"并\" làm liên từ, nối các động từ song âm tiết, cụm từ hoặc vế câu song song, biểu thị quan hệ song song, mang ý nghĩa tiến thêm một bước; (2) \"并\" làm phó từ, đặt trước từ phủ định để nhấn mạnh ngữ khí phủ định, nói rõ sự thật không phải như vậy.","examples":[{"cn":"房东又向我介绍了一下房子里的东西，并告诉我这些东西怎么用。","pinyin":"Fángdōng yòu xiàng wǒ jièshào le yíxià fángzi lǐ de dōngxi, bìng gàosu wǒ zhèxiē dōngxi zěnme yòng.","vn":"Chủ nhà lại giới thiệu cho tôi một lượt về đồ đạc trong nhà, đồng thời cho tôi biết cách sử dụng những thứ đó."},{"cn":"她考上了北京大学并申请到了奖学金。","pinyin":"Tā kǎoshàng le Běijīng Dàxué bìng shēnqǐng dào le jiǎngxuéjīn.","vn":"Cô ấy thi đỗ vào Đại học Bắc Kinh và xin được học bổng."},{"cn":"我并没有答应你就租这个房子，我还要再想想。","pinyin":"Wǒ bìng méiyǒu dāying nǐ jiù zū zhège fángzi, wǒ hái yào zài xiǎngxiang.","vn":"Tôi hoàn toàn chưa đồng ý thuê căn nhà này, tôi còn phải suy nghĩ thêm."}]},{"title":"连词/介词\"由于\"","explanation_vn":"\"由于\" có hai cách dùng: (1) làm liên từ, đặt ở đầu vế câu trước trong câu phức để biểu thị nguyên nhân, vế câu sau thường có các từ như \"所以\", \"因此\"; (2) làm giới từ, biểu thị nguyên nhân hoặc lý do.","examples":[{"cn":"在中国，由于很多刚工作的年轻人工资还不太高，所以他们一开始也不买房，都选择租房。","pinyin":"Zài Zhōngguó, yóuyú hěn duō gāng gōngzuò de niánqīngrén gōngzī hái bú tài gāo, suǒyǐ tāmen yì kāishǐ yě bù mǎifáng, dōu xuǎnzé zūfáng.","vn":"Ở Trung Quốc, do rất nhiều bạn trẻ mới đi làm có mức lương chưa cao lắm, nên ban đầu họ cũng không mua nhà, đều chọn thuê nhà."},{"cn":"由于一直下大雨，所以我们决定不爬山了。","pinyin":"Yóuyú yìzhí xià dàyǔ, suǒyǐ wǒmen juédìng bù páshān le.","vn":"Do trời mưa to liên tục, nên chúng tôi quyết định không leo núi nữa."},{"cn":"由于大家的努力，这次运动会我们班获得了第一名。","pinyin":"Yóuyú dàjiā de nǔlì, zhè cì yùndònghuì wǒmen bān huòdé le dìyī míng.","vn":"Nhờ sự nỗ lực của mọi người, trong hội thao lần này lớp chúng tôi đã giành giải nhất."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"房东","cn":"请进！我给你们介绍一下，这个房子有两个房间，那个大房间出租，房租每月5500元。现在已经收拾好了，想租的话，今天就可以搬进来。","pinyin":"Qǐng jìn! Wǒ gěi nǐmen jièshào yíxià, zhège fángzi yǒu liǎng gè fángjiān, nàge dà fángjiān chūzū, fángzū měi yuè wǔqiānwǔbǎi yuán. Xiànzài yǐjīng shōushi hǎo le, xiǎng zū de huà, jīntiān jiù kěyǐ bān jìnlái."},{"speaker":"白家月","cn":"嗯，这个房间真不小，还挺亮。小区离我们学校也不远。","pinyin":"Ng, zhège fángjiān zhēn bù xiǎo, hái tǐng liàng. Xiǎoqū lí wǒmen xuéxiào yě bù yuǎn."},{"speaker":"房东","cn":"是的，我们小区离地铁站也很近，生活上很方便。如果决定租了，告诉我就是了。","pinyin":"Shì de, wǒmen xiǎoqū lí dìtiězhàn yě hěn jìn, shēnghuó shàng hěn fāngbiàn. Rúguǒ juédìng zū le, gàosu wǒ jiùshì le."},{"speaker":"白家月","cn":"好的，我们再去看看外边的环境。","pinyin":"Hǎo de, wǒmen zài qù kànkan wàibian de huánjìng."}],"translation_vn":"Chủ nhà: Mời vào! Để tôi giới thiệu cho các em, căn nhà này có hai phòng, phòng lớn kia cho thuê, tiền thuê mỗi tháng 5500 tệ. Hiện tại đã dọn dẹp xong rồi, nếu muốn thuê thì hôm nay có thể dọn vào ở luôn.\nBạch Gia Nguyệt: Dạ, phòng này thật sự không nhỏ, lại khá sáng sủa. Khu này cũng không xa trường của chúng em.\nChủ nhà: Đúng vậy, khu chúng tôi cũng gần ga tàu điện ngầm, sinh hoạt rất tiện lợi. Nếu quyết định thuê thì cứ báo cho tôi là được.\nBạch Gia Nguyệt: Vâng ạ, chúng em đi xem thêm môi trường bên ngoài nữa.","audio_dialogue":"2-1.mp3","audio_vocab":"2-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"李文","cn":"家月，你看，那边还有个小花园。","pinyin":"Jiāyuè, nǐ kàn, nàbian hái yǒu gè xiǎo huāyuán."},{"speaker":"白家月","cn":"嗯，这个小区到处是花，还种了不少树，周围也很安静。","pinyin":"Ng, zhège xiǎoqū dàochù shì huā, hái zhòng le bùshǎo shù, zhōuwéi yě hěn ānjìng."},{"speaker":"李文","cn":"是啊！这个小区的环境真不错，不过我听说，附近有十几家公司，很多刚毕业的学生都租住在这里。周末他们可能会玩到很晚，恐怕会影响你休息。","pinyin":"Shì a! Zhège xiǎoqū de huánjìng zhēn búcuò, búguò wǒ tīngshuō, fùjìn yǒu shíjǐ jiā gōngsī, hěn duō gāng bìyè de xuésheng dōu zūzhù zài zhèlǐ. Zhōumò tāmen kěnéng huì wán dào hěn wǎn, kǒngpà huì yǐngxiǎng nǐ xiūxi."},{"speaker":"白家月","cn":"没关系，我还想多认识一些朋友，和他们一起玩呢。","pinyin":"Méi guānxi, wǒ hái xiǎng duō rènshi yìxiē péngyou, hé tāmen yìqǐ wán ne."},{"speaker":"李文","cn":"是呢，大家可以一起热闹热闹。","pinyin":"Shì ne, dàjiā kěyǐ yìqǐ rènao rènao."},{"speaker":"白家月","cn":"这里房租合适，环境很好，而且房东也热情，所以我决定租这个房子了，明天就入住新家。","pinyin":"Zhèlǐ fángzū héshì, huánjìng hěn hǎo, érqiě fángdōng yě rèqíng, suǒyǐ wǒ juédìng zū zhège fángzi le, míngtiān jiù rùzhù xīnjiā."}],"translation_vn":"Lý Văn: Gia Nguyệt, cậu xem, bên kia còn có một vườn hoa nhỏ nữa.\nBạch Gia Nguyệt: Ừ, khu này chỗ nào cũng có hoa, còn trồng khá nhiều cây, xung quanh cũng rất yên tĩnh.\nLý Văn: Đúng vậy! Môi trường khu này thật sự không tệ, nhưng mình nghe nói gần đây có hơn chục công ty, rất nhiều sinh viên mới tốt nghiệp đều thuê nhà ở đây. Cuối tuần họ có thể chơi đến khuya, e rằng sẽ ảnh hưởng đến việc nghỉ ngơi của cậu.\nBạch Gia Nguyệt: Không sao, mình còn muốn quen thêm vài người bạn, chơi cùng họ nữa.\nLý Văn: Đúng vậy, mọi người có thể cùng nhau vui vẻ náo nhiệt.\nBạch Gia Nguyệt: Ở đây tiền thuê hợp lý, môi trường tốt, hơn nữa chủ nhà cũng nhiệt tình, nên mình quyết định thuê căn nhà này rồi, ngày mai sẽ dọn vào nhà mới.","audio_dialogue":"2-3.mp3","audio_vocab":"2-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"8月25日，晴","pinyin":"Bā yuè èrshíwǔ rì, qíng"},{"speaker":"","cn":"昨天我顺利租到了合适的房子，今天李文帮我搬家。搬进去的时候，房东又向我介绍了一下房子里的东西，并告诉我这些东西怎么用。","pinyin":"Zuótiān wǒ shùnlì zūdào le héshì de fángzi, jīntiān Lǐ Wén bāng wǒ bānjiā. Bān jìnqù de shíhou, fángdōng yòu xiàng wǒ jièshào le yíxià fángzi lǐ de dōngxi, bìng gàosu wǒ zhèxiē dōngxi zěnme yòng."},{"speaker":"","cn":"我看了一下，客厅里有椅子、沙发，还有一台大电视；厨房里有冰箱和一些做饭用的东西，不过，我平常主要在学校食堂吃，基本上不做饭。我租的房间里，除了一张床以外，还有一台空调、一张书桌和一把椅子。","pinyin":"Wǒ kàn le yíxià, kètīng lǐ yǒu yǐzi, shāfā, hái yǒu yì tái dà diànshì; chúfáng lǐ yǒu bīngxiāng hé yìxiē zuòfàn yòng de dōngxi, búguò, wǒ píngcháng zhǔyào zài xuéxiào shítáng chī, jīběnshàng bú zuòfàn. Wǒ zū de fángjiān lǐ, chúle yì zhāng chuáng yǐwài, hái yǒu yì tái kōngtiáo, yì zhāng shūzhuō hé yì bǎ yǐzi."},{"speaker":"","cn":"看完整个房子后，我准备再去买几条毛巾，其他东西还不需要。","pinyin":"Kànwán zhěnggè fángzi hòu, wǒ zhǔnbèi zài qù mǎi jǐ tiáo máojīn, qítā dōngxi hái bù xūyào."}],"translation_vn":"Ngày 25 tháng 8, trời nắng\nHôm qua mình đã thuận lợi thuê được căn nhà ưng ý, hôm nay Lý Văn giúp mình chuyển nhà. Lúc dọn vào, chủ nhà lại giới thiệu cho mình một lượt về đồ đạc trong nhà, đồng thời cho mình biết cách sử dụng những thứ đó.\nMình xem qua một lượt, phòng khách có ghế, sofa, còn có một chiếc ti vi lớn; nhà bếp có tủ lạnh và một số đồ dùng để nấu ăn, nhưng mình thường chủ yếu ăn ở nhà ăn trường, về cơ bản không nấu ăn. Phòng mình thuê, ngoài một chiếc giường ra, còn có một chiếc điều hòa, một chiếc bàn học và một chiếc ghế.\nSau khi xem xong cả căn nhà, mình định đi mua thêm vài chiếc khăn mặt nữa, những thứ khác thì chưa cần.","audio_dialogue":"2-5.mp3","audio_vocab":"2-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"在李文的帮助下，白家月租到了合适的房子。对白家月来说，这次租房并不容易。根据李文的建议，她先在租房网站和App上查看有关信息，查找合适的房子，接着又去看了看房子，同时了解房子周围的环境。她看了好几个房子，才找到一个位置、环境和价格都合适的，最后顺利租到了理想的房子。","pinyin":"Zài Lǐ Wén de bāngzhù xià, Bái Jiāyuè zūdào le héshì de fángzi. Duì Bái Jiāyuè láishuō, zhè cì zūfáng bìng bù róngyì. Gēnjù Lǐ Wén de jiànyì, tā xiān zài zūfáng wǎngzhàn hé App shàng chákàn yǒuguān xìnxī, cházhǎo héshì de fángzi, jiēzhe yòu qù kàn le kàn fángzi, tóngshí liǎojiě fángzi zhōuwéi de huánjìng. Tā kàn le hǎojǐ gè fángzi, cái zhǎodào yí gè wèizhì, huánjìng hé jiàgé dōu héshì de, zuìhòu shùnlì zūdào le lǐxiǎng de fángzi."},{"speaker":"","cn":"租房的时候，李文告诉白家月，在中国，由于很多刚工作的年轻人工资还不太高，所以他们一开始也不买房，都选择租房。工作几年后，不少人就会买房，因为大家一直觉得，有房才有家，有自己的房子会更有安全感。","pinyin":"Zūfáng de shíhou, Lǐ Wén gàosu Bái Jiāyuè, zài Zhōngguó, yóuyú hěn duō gāng gōngzuò de niánqīngrén gōngzī hái bú tài gāo, suǒyǐ tāmen yì kāishǐ yě bù mǎifáng, dōu xuǎnzé zūfáng. Gōngzuò jǐ nián hòu, bùshǎo rén jiù huì mǎifáng, yīnwèi dàjiā yìzhí juéde, yǒu fáng cái yǒu jiā, yǒu zìjǐ de fángzi huì gèng yǒu ānquángǎn."}],"translation_vn":"Với sự giúp đỡ của Lý Văn, Bạch Gia Nguyệt đã thuê được căn nhà ưng ý. Đối với Bạch Gia Nguyệt mà nói, lần thuê nhà này không hề dễ dàng. Theo gợi ý của Lý Văn, trước tiên cô xem thông tin liên quan trên các trang web và ứng dụng cho thuê nhà, tìm kiếm căn nhà phù hợp, sau đó lại đi xem nhà, đồng thời tìm hiểu môi trường xung quanh căn nhà. Cô đã xem qua mấy căn nhà mới tìm được một căn có vị trí, môi trường và giá cả đều phù hợp, cuối cùng thuận lợi thuê được căn nhà lý tưởng.\nLúc thuê nhà, Lý Văn nói với Bạch Gia Nguyệt rằng ở Trung Quốc, do rất nhiều bạn trẻ mới đi làm có mức lương chưa cao lắm, nên ban đầu họ cũng không mua nhà, đều chọn thuê nhà. Sau khi đi làm vài năm, không ít người sẽ mua nhà, vì mọi người đều cho rằng có nhà mới có tổ ấm, có nhà riêng sẽ cảm thấy an toàn hơn.","audio_dialogue":"2-7.mp3","audio_vocab":"2-8.mp3"}]},{"id":3,"title_cn":"手机扫一下","title_pinyin":"Shǒujī sǎo yíxià","title_vn":"Quét điện thoại một chút","goals":["Có thể nghe hiểu và trao đổi về các chủ đề như tải ứng dụng, mua sắm trực tuyến, thanh toán bằng điện thoại.","Có thể diễn đạt bằng lời nói hoặc chữ viết các công dụng khác nhau của điện thoại di động.","Hiểu được các cách bảo vệ thông tin cá nhân trong thời đại mạng internet."],"vocab":[{"hanzi":"十字路口","pinyin":"shízì lùkǒu","pos":"","vn":"ngã tư","examples":[{"cn":"前面的十字路口往左转就到了。","pinyin":"qián miàn de shí zì lù kǒu wǎng zuǒ zhuǎn jiù dào le 。","vn":"Ngã tư phía trước rẽ trái là tới."},{"cn":"他在十字路口等红绿灯。","pinyin":"tā zài shí zì lù kǒu děng hóng lǜ dēng 。","vn":"Anh ấy đứng ở ngã tư đợi đèn giao thông."},{"cn":"这个十字路口车特别多，过马路要小心。","pinyin":"zhè ge shí zì lù kǒu chē tè bié duō ， guò mǎ lù yào xiǎo xīn 。","vn":"Ngã tư này nhiều xe lắm, qua đường phải cẩn thận."}]},{"hanzi":"直接","pinyin":"zhíjiē","pos":"tt.","vn":"trực tiếp","examples":[{"cn":"你有什么问题可以直接问我。","pinyin":"nǐ yǒu shén me wèn tí kě yǐ zhí jiē wèn wǒ 。","vn":"Có vấn đề gì bạn cứ hỏi trực tiếp tôi."},{"cn":"这趟火车直接到北京，不用换车。","pinyin":"zhè tàng huǒ chē zhí jiē dào běi jīng ， bù yòng huàn chē 。","vn":"Chuyến tàu này đi thẳng đến Bắc Kinh, không cần đổi tàu."},{"cn":"他做事很直接，从不拐弯抹角。","pinyin":"tā zuò shì hěn zhí jiē ， cóng bù guǎi wān mò jiǎo 。","vn":"Anh ấy làm việc rất thẳng thắn, chẳng bao giờ vòng vo."}]},{"hanzi":"转","pinyin":"zhuǎn","pos":"dgt.","vn":"rẽ, quay, chuyển","examples":[{"cn":"前面路口往右转就是超市。","pinyin":"qián miàn lù kǒu wǎng yòu zhuǎn jiù shì chāo shì 。","vn":"Phía trước rẽ phải là tới siêu thị."},{"cn":"这件事我得转告一下我的同事。","pinyin":"zhè jiàn shì wǒ dé zhuǎn gào yī xià wǒ de tóng shì 。","vn":"Việc này tôi phải chuyển lời lại cho đồng nghiệp."},{"cn":"他转过身，笑着跟我打招呼。","pinyin":"tā zhuǎn guò shēn ， xiào zhe gēn wǒ dǎ zhāo hū 。","vn":"Anh ấy quay người lại, cười chào tôi."}]},{"hanzi":"正好","pinyin":"zhènghǎo","pos":"phó./tt.","vn":"đúng lúc, vừa khéo, vừa vặn","examples":[{"cn":"我正准备出门，你正好打电话来了。","pinyin":"wǒ zhèng zhǔn bèi chū mén ， nǐ zhèng hǎo dǎ diàn huà lái le 。","vn":"Tôi vừa định ra ngoài thì đúng lúc bạn gọi điện tới."},{"cn":"这件衣服的大小正好合适。","pinyin":"zhè jiàn yī fú de dà xiǎo zhèng hǎo hé shì 。","vn":"Cỡ áo này vừa khéo vừa vặn."},{"cn":"我正好有事要找你，就过来了。","pinyin":"wǒ zhèng hǎo yǒu shì yào zhǎo nǐ ， jiù guò lái le 。","vn":"Tôi đúng lúc có việc muốn tìm bạn nên ghé qua."}]},{"hanzi":"熟悉","pinyin":"shúxī","pos":"dgt.","vn":"quen thuộc, am hiểu","examples":[{"cn":"我对这座城市很熟悉，可以带你逛逛。","pinyin":"wǒ duì zhè zuò chéng shì hěn shú xī ， kě yǐ dài nǐ guàng guàng 。","vn":"Tôi rất quen thuộc với thành phố này, có thể dẫn bạn đi dạo."},{"cn":"这个声音听起来很熟悉，是谁啊？","pinyin":"zhè ge shēng yīn tīng qǐ lái hěn shú xī ， shì shuí a ？","vn":"Giọng nói này nghe quen quen, là ai vậy nhỉ?"},{"cn":"新来的同事还不熟悉公司的规矩。","pinyin":"xīn lái de tóng shì hái bù shú xī gōng sī de guī jǔ 。","vn":"Đồng nghiệp mới vẫn chưa quen với quy định của công ty."}]},{"hanzi":"正","pinyin":"zhèng","pos":"tt.","vn":"thẳng, ngay ngắn","examples":[{"cn":"把画挂正一点，歪了。","pinyin":"bǎ huà guà zhèng yì diǎn ， wāi le 。","vn":"Treo bức tranh thẳng lại chút, nó bị lệch rồi."},{"cn":"他坐得很正，一点都不驼背。","pinyin":"tā zuò dé hěn zhèng ， yì diǎn dōu bù tuó bèi 。","vn":"Anh ấy ngồi rất ngay ngắn, không hề gù lưng."},{"cn":"字写得又正又好看。","pinyin":"zì xiě dé yòu zhèng yòu hǎo kàn 。","vn":"Chữ viết vừa ngay ngắn vừa đẹp."}]},{"hanzi":"目的地","pinyin":"mùdìdì","pos":"dt.","vn":"điểm đến, đích đến","examples":[{"cn":"我们快到目的地了，再坚持一下。","pinyin":"wǒ men kuài dào mù dì dì le ， zài jiān chí yī xià 。","vn":"Chúng ta sắp đến điểm đến rồi, cố thêm chút nữa."},{"cn":"导航显示离目的地还有十分钟的路程。","pinyin":"dǎo háng xiǎn shì lí mù dì dì hái yǒu shí fēn zhōng de lù chéng 。","vn":"Định vị hiển thị còn mười phút nữa là tới đích."},{"cn":"这次旅行的目的地是云南。","pinyin":"zhè cì lǚ xíng de mù dì dì shì yún nán 。","vn":"Điểm đến của chuyến đi lần này là Vân Nam."}]},{"hanzi":"下载","pinyin":"xiàzài","pos":"dgt.","vn":"tải xuống","examples":[{"cn":"我在手机上下载了一个新软件。","pinyin":"wǒ zài shǒu jī shàng xià zài le yí gè xīn ruǎn jiàn 。","vn":"Tôi đã tải một phần mềm mới về điện thoại."},{"cn":"这个视频下载需要一点时间。","pinyin":"zhè ge shì pín xià zài xū yào yì diǎn shí jiān 。","vn":"Video này tải xuống cần một chút thời gian."},{"cn":"你可以直接从网上下载这个文件。","pinyin":"nǐ kě yǐ zhí jiē cóng wǎng shàng xià zài zhè ge wén jiàn 。","vn":"Bạn có thể tải trực tiếp tệp này từ trên mạng."}]},{"hanzi":"进行","pinyin":"jìnxíng","pos":"dgt.","vn":"tiến hành, thực hiện","examples":[{"cn":"会议正在进行中，请不要打扰。","pinyin":"huì yì zhèng zài jìn xíng zhōng ， qǐng bú yào dǎ rǎo 。","vn":"Cuộc họp đang diễn ra, xin đừng làm phiền."},{"cn":"这项研究已经进行了三年。","pinyin":"zhè xiàng yán jiū yǐ jīng jìn xíng le sān nián 。","vn":"Dự án nghiên cứu này đã tiến hành được ba năm."},{"cn":"比赛将在明天上午进行。","pinyin":"bǐ sài jiāng zài míng tiān shàng wǔ jìn xíng 。","vn":"Trận thi đấu sẽ được tổ chức vào sáng mai."}]},{"hanzi":"支付","pinyin":"zhīfù","pos":"dgt.","vn":"thanh toán, chi trả","examples":[{"cn":"现在很多人都用手机支付。","pinyin":"xiàn zài hěn duō rén dōu yòng shǒu jī zhī fù 。","vn":"Bây giờ rất nhiều người thanh toán bằng điện thoại."},{"cn":"这笔钱可以分期支付。","pinyin":"zhè bǐ qián kě yǐ fēn qī zhī fù 。","vn":"Khoản tiền này có thể trả góp."},{"cn":"他忘了支付这个月的房租。","pinyin":"tā wàng le zhī fù zhè ge yuè de fáng zū 。","vn":"Anh ấy quên thanh toán tiền thuê nhà tháng này."}]},{"hanzi":"软件","pinyin":"ruǎnjiàn","pos":"dt.","vn":"phần mềm","examples":[{"cn":"这个软件用起来特别方便。","pinyin":"zhè ge ruǎn jiàn yòng qǐ lái tè bié fāng biàn 。","vn":"Phần mềm này dùng rất tiện."},{"cn":"他是专门做软件开发的。","pinyin":"tā shì zhuān mén zuò ruǎn jiàn kāi fā de 。","vn":"Anh ấy chuyên làm phát triển phần mềm."},{"cn":"我电脑上的软件需要更新了。","pinyin":"wǒ diàn nǎo shàng de ruǎn jiàn xū yào gēng xīn le 。","vn":"Phần mềm trên máy tính của tôi cần cập nhật rồi."}]},{"hanzi":"不仅","pinyin":"bùjǐn","pos":"liên.","vn":"không những...(mà còn...)","examples":[{"cn":"他不仅会说中文，还会说英语。","pinyin":"tā bù jǐn huì shuō zhōng wén ， hái huì shuō yīng yǔ 。","vn":"Anh ấy không những biết nói tiếng Trung mà còn biết tiếng Anh."},{"cn":"这家店不仅便宜，味道也不错。","pinyin":"zhè jiā diàn bù jǐn pián yi ， wèi dào yě bù cuò 。","vn":"Quán này không những rẻ mà vị cũng ngon."},{"cn":"不仅是我，连他也觉得这很难。","pinyin":"bù jǐn shì wǒ ， lián tā yě jué de zhè hěn nán 。","vn":"Không chỉ tôi, mà ngay cả anh ấy cũng thấy việc này khó."}]},{"hanzi":"扫码","pinyin":"sǎomǎ","pos":"dgt.","vn":"quét mã QR","examples":[{"cn":"进门需要扫码登记一下。","pinyin":"jìn mén xū yào sǎo mǎ dēng jì yī xià 。","vn":"Vào cửa cần quét mã đăng ký."},{"cn":"买单的时候直接扫码就行。","pinyin":"mǎi dān de shí hòu zhí jiē sǎo mǎ jiù xíng 。","vn":"Lúc thanh toán chỉ cần quét mã là xong."},{"cn":"他教妈妈怎么扫码支付。","pinyin":"tā jiào mā mā zěn me sǎo mǎ zhī fù 。","vn":"Anh ấy dạy mẹ cách quét mã thanh toán."}]},{"hanzi":"结账","pinyin":"jiézhàng","pos":"dgt.","vn":"thanh toán, tính tiền","examples":[{"cn":"服务员，麻烦结账。","pinyin":"fú wù yuán ， má fán jié zhàng 。","vn":"Phục vụ ơi, tính tiền giúp tôi."},{"cn":"我们俩AA制，各付各的结账。","pinyin":"wǒ men liǎ AA zhì ， gè fù gè de jié zhàng 。","vn":"Hai chúng tôi chia tiền ai nấy tính."},{"cn":"吃完饭他抢着去结账了。","pinyin":"chī wán fàn tā qiǎng zhe qù jié zhàng le 。","vn":"Ăn xong anh ấy giành thanh toán trước."}]},{"hanzi":"购物","pinyin":"gòuwù","pos":"dgt.","vn":"mua sắm","examples":[{"cn":"周末我喜欢去商场购物。","pinyin":"zhōu mò wǒ xǐ huān qù shāng chǎng gòu wù 。","vn":"Cuối tuần tôi thích đi trung tâm thương mại mua sắm."},{"cn":"现在网上购物特别方便。","pinyin":"xiàn zài wǎng shàng gòu wù tè bié fāng biàn 。","vn":"Bây giờ mua sắm online rất tiện lợi."},{"cn":"双十一购物节很多东西都打折。","pinyin":"shuāng shí yī gòu wù jié hěn duō dōng xī dōu dǎ zhé 。","vn":"Ngày hội mua sắm mùng 11 tháng 11 nhiều thứ giảm giá lắm."}]},{"hanzi":"订","pinyin":"dìng","pos":"dgt.","vn":"đặt (hàng, chỗ)","examples":[{"cn":"我已经订好酒店了。","pinyin":"wǒ yǐ jīng dìng hǎo jiǔ diàn le 。","vn":"Tôi đã đặt khách sạn rồi."},{"cn":"周末的票得提前订。","pinyin":"zhōu mò de piào dé tí qián dìng 。","vn":"Vé cuối tuần phải đặt trước."},{"cn":"他帮我订了一张明天的机票。","pinyin":"tā bāng wǒ dìng le yī zhāng míng tiān de jī piào 。","vn":"Anh ấy đặt giúp tôi vé máy bay ngày mai."}]},{"hanzi":"快递","pinyin":"kuàidì","pos":"dt.","vn":"chuyển phát nhanh","examples":[{"cn":"我的快递今天应该能到。","pinyin":"wǒ de kuài dì jīn tiān yīng gāi néng dào 。","vn":"Hôm nay bưu kiện của tôi chắc sẽ tới."},{"cn":"这个东西寄快递要三天。","pinyin":"zhè ge dōng xī jì kuài dì yào sān tiān 。","vn":"Gửi món này qua chuyển phát nhanh mất ba ngày."},{"cn":"快递员刚才给我送来一个包裹。","pinyin":"kuài dì yuán gāng cái gěi wǒ sòng lái yí gè bāo guǒ 。","vn":"Nhân viên giao hàng vừa đưa cho tôi một gói hàng."}]},{"hanzi":"微信","pinyin":"Wēixìn","pos":"danh từ riêng","vn":"WeChat","examples":[{"cn":"加个微信吧，方便联系。","pinyin":"jiā gè wēi xìn ba ， fāng biàn lián xì 。","vn":"Kết bạn WeChat đi, liên lạc cho tiện."},{"cn":"我每天都用微信跟朋友聊天。","pinyin":"wǒ měi tiān dōu yòng wēi xìn gēn péng yǒu liáo tiān 。","vn":"Ngày nào tôi cũng dùng WeChat chat với bạn bè."},{"cn":"这个消息我在微信群里看到的。","pinyin":"zhè ge xiāo xī wǒ zài wēi xìn qún lǐ kàn dào de 。","vn":"Tin này tôi thấy trong nhóm WeChat."}]},{"hanzi":"支付宝","pinyin":"Zhīfùbǎo","pos":"danh từ riêng","vn":"Alipay","examples":[{"cn":"我习惯用支付宝付钱。","pinyin":"wǒ xí guàn yòng zhī fù bǎo fù qián 。","vn":"Tôi quen dùng Alipay để trả tiền."},{"cn":"支付宝里还有一些优惠券。","pinyin":"zhī fù bǎo lǐ hái yǒu yī xiē yōu huì quàn 。","vn":"Trong Alipay còn có vài phiếu giảm giá."},{"cn":"他用支付宝给我转了钱。","pinyin":"tā yòng zhī fù bǎo gěi wǒ zhuǎn le qián 。","vn":"Anh ấy chuyển tiền cho tôi qua Alipay."}]},{"hanzi":"现金","pinyin":"xiànjīn","pos":"dt.","vn":"tiền mặt","examples":[{"cn":"现在很少有人带现金出门了。","pinyin":"xiàn zài hěn shǎo yǒu rén dài xiàn jīn chū mén le 。","vn":"Bây giờ rất ít người mang tiền mặt ra ngoài."},{"cn":"这家店只收现金，不能刷卡。","pinyin":"zhè jiā diàn zhǐ shōu xiàn jīn ， bù néng shuā kǎ 。","vn":"Cửa hàng này chỉ nhận tiền mặt, không quẹt thẻ được."},{"cn":"身上留点现金比较方便。","pinyin":"shēn shàng liú diǎn xiàn jīn bǐ jiào fāng biàn 。","vn":"Mang theo chút tiền mặt vẫn tiện hơn."}]},{"hanzi":"网购","pinyin":"wǎnggòu","pos":"dgt.","vn":"mua sắm trực tuyến","examples":[{"cn":"我这几年很少逛街，都是网购。","pinyin":"wǒ zhè jǐ nián hěn shǎo guàng jiē ， dōu shì wǎng gòu 。","vn":"Mấy năm nay tôi ít đi dạo phố, toàn mua sắm online."},{"cn":"网购虽然方便，但有时候收到的东西不太满意。","pinyin":"wǎng gòu suī rán fāng biàn ， dàn yǒu shí hòu shōu dào de dōng xī bù tài mǎn yì 。","vn":"Mua online tuy tiện nhưng đôi khi nhận hàng không ưng ý."},{"cn":"她是个网购达人，什么都在网上买。","pinyin":"tā shì gè wǎng gòu dá rén ， shén me dōu zài wǎng shàng mǎi 。","vn":"Cô ấy là tín đồ mua sắm online, cái gì cũng mua trên mạng."}]},{"hanzi":"寄","pinyin":"jì","pos":"dgt.","vn":"gửi","examples":[{"cn":"我给你寄了一份生日礼物。","pinyin":"wǒ gěi nǐ jì le yī fèn shēng rì lǐ wù 。","vn":"Tôi đã gửi cho bạn một món quà sinh nhật."},{"cn":"这封信是从国外寄来的。","pinyin":"zhè fēng xìn shì cóng guó wài jì lái de 。","vn":"Lá thư này được gửi từ nước ngoài về."},{"cn":"麻烦帮我把这个包裹寄到上海。","pinyin":"má fán bāng wǒ bǎ zhè ge bāo guǒ jì dào shàng hǎi 。","vn":"Phiền bạn gửi giúp gói hàng này đến Thượng Hải."}]},{"hanzi":"等","pinyin":"děng","pos":"trợ.","vn":"v.v., vân vân","examples":[{"cn":"水果、蔬菜等都要新鲜的才好吃。","pinyin":"shuǐ guǒ 、 shū cài děng dōu yào xīn xiān de cái hǎo chī 。","vn":"Trái cây, rau củ v.v. đều phải tươi mới ngon."},{"cn":"他带了手机、钱包、钥匙等出门。","pinyin":"tā dài le shǒu jī 、 qián bāo 、 yào shi děng chū mén 。","vn":"Anh ấy mang theo điện thoại, ví tiền, chìa khóa v.v. khi ra ngoài."},{"cn":"这次活动准备了礼物、奖金等奖励。","pinyin":"zhè cì huó dòng zhǔn bèi le lǐ wù 、 jiǎng jīn děng jiǎng lì 。","vn":"Hoạt động lần này chuẩn bị quà, tiền thưởng v.v. để khích lệ."}]},{"hanzi":"货","pinyin":"huò","pos":"dt.","vn":"hàng hóa","examples":[{"cn":"这批货明天就能到。","pinyin":"zhè pī huò míng tiān jiù néng dào 。","vn":"Lô hàng này ngày mai sẽ tới."},{"cn":"老板正在仓库里清点货。","pinyin":"lǎo bǎn zhèng zài cāng kù lǐ qīng diǎn huò 。","vn":"Ông chủ đang kiểm hàng trong kho."},{"cn":"这家店的货挺齐全的。","pinyin":"zhè jiā diàn de huò tǐng qí quán de 。","vn":"Hàng hóa ở cửa tiệm này khá đầy đủ."}]},{"hanzi":"甚至","pinyin":"shènzhì","pos":"liên.","vn":"thậm chí","examples":[{"cn":"他忙得甚至没时间吃饭。","pinyin":"tā máng dé shèn zhì méi shí jiān chī fàn 。","vn":"Anh ấy bận đến mức thậm chí không có thời gian ăn cơm."},{"cn":"这件事甚至连他自己都不知道。","pinyin":"zhè jiàn shì shèn zhì lián tā zì jǐ dōu bù zhī dào 。","vn":"Việc này thậm chí chính anh ấy cũng không biết."},{"cn":"天气太热了，甚至晚上也睡不着。","pinyin":"tiān qì tài rè le ， shèn zhì wǎn shàng yě shuì bù zhe 。","vn":"Trời nóng quá, thậm chí ban đêm cũng không ngủ được."}]},{"hanzi":"改变","pinyin":"gǎibiàn","pos":"dgt.","vn":"thay đổi","examples":[{"cn":"这件事改变了我对他的看法。","pinyin":"zhè jiàn shì gǎi biàn le wǒ duì tā de kàn fǎ 。","vn":"Việc này đã thay đổi cách nhìn của tôi về anh ấy."},{"cn":"他决定改变自己的生活方式。","pinyin":"tā jué dìng gǎi biàn zì jǐ de shēng huó fāng shì 。","vn":"Anh ấy quyết định thay đổi lối sống của mình."},{"cn":"时代在改变，我们也要跟上。","pinyin":"shí dài zài gǎi biàn ， wǒ men yě yào gēn shàng 。","vn":"Thời đại đang thay đổi, chúng ta cũng phải bắt kịp."}]},{"hanzi":"手指","pinyin":"shǒuzhǐ","pos":"dt.","vn":"ngón tay","examples":[{"cn":"他的手指被刀割破了。","pinyin":"tā de shǒu zhǐ bèi dāo gē pò le 。","vn":"Ngón tay anh ấy bị dao cắt đứt."},{"cn":"她用手指指了指那个方向。","pinyin":"tā yòng shǒu zhǐ zhǐ le zhǐ nà ge fāng xiàng 。","vn":"Cô ấy dùng ngón tay chỉ về hướng đó."},{"cn":"弹钢琴需要灵活的手指。","pinyin":"tán gāng qín xū yào líng huó de shǒu zhǐ 。","vn":"Chơi piano cần có những ngón tay linh hoạt."}]},{"hanzi":"乱","pinyin":"luàn","pos":"phó./tt.","vn":"bừa bãi, lộn xộn","examples":[{"cn":"房间太乱了，收拾一下吧。","pinyin":"fáng jiān tài luàn le ， shōu shí yī xià ba 。","vn":"Phòng bừa bộn quá, dọn dẹp đi chứ."},{"cn":"别把东西乱扔。","pinyin":"bié bǎ dōng xī luàn rēng 。","vn":"Đừng vứt đồ bừa bãi."},{"cn":"他一着急，说话就乱了。","pinyin":"tā yī zháo jí ， shuō huà jiù luàn le 。","vn":"Anh ấy vừa vội là nói năng lộn xộn liền."}]},{"hanzi":"管","pinyin":"guǎn","pos":"dgt.","vn":"quản lý, kiểm soát","examples":[{"cn":"这件事由他来管。","pinyin":"zhè jiàn shì yóu tā lái guǎn 。","vn":"Việc này để anh ấy quản lý."},{"cn":"父母管孩子也要讲究方法。","pinyin":"fù mǔ guǎn hái zi yě yào jiǎng jiū fāng fǎ 。","vn":"Cha mẹ quản con cái cũng phải có phương pháp."},{"cn":"这事儿不归我管。","pinyin":"zhè shì ér bù guī wǒ guǎn 。","vn":"Việc này không thuộc trách nhiệm của tôi."}]},{"hanzi":"提供","pinyin":"tígōng","pos":"dgt.","vn":"cung cấp","examples":[{"cn":"公司给员工提供免费午餐。","pinyin":"gōng sī gěi yuán gōng tí gōng miǎn fèi wǔ cān 。","vn":"Công ty cung cấp bữa trưa miễn phí cho nhân viên."},{"cn":"能不能提供一些具体的建议？","pinyin":"néng bù néng tí gōng yī xiē jù tǐ de jiàn yì ？","vn":"Bạn có thể đưa ra vài gợi ý cụ thể không?"},{"cn":"这家酒店提供免费的早餐。","pinyin":"zhè jiā jiǔ diàn tí gōng miǎn fèi de zǎo cān 。","vn":"Khách sạn này cung cấp bữa sáng miễn phí."}]},{"hanzi":"身份证","pinyin":"shēnfènzhèng","pos":"dt.","vn":"chứng minh thư, thẻ căn cước","examples":[{"cn":"办卡需要带身份证。","pinyin":"bàn kǎ xū yào dài shēn fèn zhèng 。","vn":"Làm thẻ cần mang theo chứng minh thư."},{"cn":"我把身份证弄丢了，得去补办。","pinyin":"wǒ bǎ shēn fèn zhèng nòng diū le ， dé qù bǔ bàn 。","vn":"Tôi làm mất chứng minh thư rồi, phải đi làm lại."},{"cn":"住酒店要出示身份证。","pinyin":"zhù jiǔ diàn yào chū shì shēn fèn zhèng 。","vn":"Ở khách sạn phải xuất trình chứng minh thư."}]},{"hanzi":"个人","pinyin":"gèrén","pos":"dt.","vn":"cá nhân","examples":[{"cn":"这只是我个人的看法。","pinyin":"zhè zhǐ shì wǒ gè rén de kàn fǎ 。","vn":"Đây chỉ là ý kiến cá nhân của tôi."},{"cn":"请不要透露客户的个人信息。","pinyin":"qǐng bú yào tòu lù kè hù de gè rén xìn xī 。","vn":"Xin đừng tiết lộ thông tin cá nhân của khách hàng."},{"cn":"这是个人问题，跟公司没关系。","pinyin":"zhè shì gè rén wèn tí ， gēn gōng sī méi guān xì 。","vn":"Đây là chuyện cá nhân, không liên quan đến công ty."}]},{"hanzi":"能否","pinyin":"néngfǒu","pos":"dgt.","vn":"có thể hay không","examples":[{"cn":"我想问问能否提前拿到工资。","pinyin":"wǒ xiǎng wèn wèn néng fǒu tí qián ná dào gōng zī 。","vn":"Tôi muốn hỏi xem có thể nhận lương sớm hay không."},{"cn":"能否成功，还要看他的努力。","pinyin":"néng fǒu chéng gōng ， hái yào kàn tā de nǔ lì 。","vn":"Có thành công hay không còn phải xem sự cố gắng của anh ấy."},{"cn":"这件事能否解决，就看明天的会议了。","pinyin":"zhè jiàn shì néng fǒu jiě jué ， jiù kàn míng tiān de huì yì le 。","vn":"Việc này có giải quyết được hay không còn tùy vào cuộc họp ngày mai."}]},{"hanzi":"保护","pinyin":"bǎohù","pos":"dgt.","vn":"bảo vệ","examples":[{"cn":"我们应该保护环境。","pinyin":"wǒ men yīng gāi bǎo hù huán jìng 。","vn":"Chúng ta nên bảo vệ môi trường."},{"cn":"他一直在保护自己的隐私。","pinyin":"tā yì zhí zài bǎo hù zì jǐ de yǐn sī 。","vn":"Anh ấy luôn bảo vệ sự riêng tư của mình."},{"cn":"父母总是想保护孩子。","pinyin":"fù mǔ zǒng shì xiǎng bǎo hù hái zi 。","vn":"Cha mẹ luôn muốn bảo vệ con cái."}]},{"hanzi":"于是","pinyin":"yúshì","pos":"liên.","vn":"thế là, vì vậy","examples":[{"cn":"他说得有道理，于是我就同意了。","pinyin":"tā shuō dé yǒu dào lǐ ， yú shì wǒ jiù tóng yì le 。","vn":"Anh ấy nói có lý, thế là tôi đồng ý."},{"cn":"天下雨了，于是我们取消了计划。","pinyin":"tiān xià yǔ le ， yú shì wǒ men qǔ xiāo le jì huà 。","vn":"Trời mưa nên chúng tôi đã hủy kế hoạch."},{"cn":"她很困，于是早早地睡了。","pinyin":"tā hěn kùn ， yú shì zǎo zǎo dì shuì le 。","vn":"Cô ấy buồn ngủ nên đi ngủ sớm."}]},{"hanzi":"密码","pinyin":"mìmǎ","pos":"dt.","vn":"mật khẩu","examples":[{"cn":"我忘记了手机的密码。","pinyin":"wǒ wàng jì le shǒu jī de mì mǎ 。","vn":"Tôi quên mật khẩu điện thoại rồi."},{"cn":"请设置一个安全的密码。","pinyin":"qǐng shè zhì yí gè ān quán de mì mǎ 。","vn":"Hãy đặt một mật khẩu an toàn."},{"cn":"他的密码被别人偷偷看到了。","pinyin":"tā de mì mǎ bèi bié rén tōu tōu kàn dào le 。","vn":"Mật khẩu của anh ấy đã bị người khác lén xem thấy."}]},{"hanzi":"随便","pinyin":"suíbiàn","pos":"tt./dgt./liên.","vn":"tùy tiện, tùy ý","examples":[{"cn":"你随便坐，别客气。","pinyin":"nǐ suí biàn zuò ， bié kè qì 。","vn":"Bạn cứ ngồi tự nhiên, đừng khách sáo."},{"cn":"这事不能随便答应别人。","pinyin":"zhè shì bù néng suí biàn dā yìng bié rén 。","vn":"Việc này không thể tùy tiện hứa với người khác."},{"cn":"晚饭随便吃点就行。","pinyin":"wǎn fàn suí biàn chī diǎn jiù xíng 。","vn":"Bữa tối ăn tạm gì đó cũng được."}]},{"hanzi":"技术","pinyin":"jìshù","pos":"dt.","vn":"kỹ thuật, công nghệ","examples":[{"cn":"这家公司的技术很先进。","pinyin":"zhè jiā gōng sī de jì shù hěn xiān jìn 。","vn":"Công nghệ của công ty này rất tiên tiến."},{"cn":"他掌握了一门很有用的技术。","pinyin":"tā zhǎng wò le yī mén hěn yǒu yòng de jì shù 。","vn":"Anh ấy đã nắm vững một kỹ thuật rất hữu ích."},{"cn":"现在的技术发展得真快。","pinyin":"xiàn zài de jì shù fā zhǎn dé zhēn kuài 。","vn":"Công nghệ bây giờ phát triển nhanh thật."}]},{"hanzi":"法律","pinyin":"fǎlǜ","pos":"dt.","vn":"pháp luật","examples":[{"cn":"每个人都应该遵守法律。","pinyin":"měi gè rén dōu yīng gāi zūn shǒu fǎ lǜ 。","vn":"Mỗi người đều nên tuân thủ pháp luật."},{"cn":"这件事要用法律来解决。","pinyin":"zhè jiàn shì yào yòng fǎ lǜ lái jiě jué 。","vn":"Việc này phải dùng pháp luật để giải quyết."},{"cn":"他学的是法律专业。","pinyin":"tā xué de shì fǎ lǜ zhuān yè 。","vn":"Anh ấy học chuyên ngành luật."}]},{"hanzi":"手段","pinyin":"shǒuduàn","pos":"dt.","vn":"biện pháp, thủ đoạn","examples":[{"cn":"他用了一些不正当的手段。","pinyin":"tā yòng le yī xiē bù zhèng dāng de shǒu duàn 。","vn":"Anh ta đã dùng vài thủ đoạn không chính đáng."},{"cn":"为了达到目的，他不择手段。","pinyin":"wèi le dá dào mù dì ， tā bù zé shǒu duàn 。","vn":"Để đạt được mục đích, anh ta không từ thủ đoạn nào."},{"cn":"这只是暂时的手段，不是长久之计。","pinyin":"zhè zhǐ shì zàn shí de shǒu duàn ， bú shì cháng jiǔ zhī jì 。","vn":"Đây chỉ là biện pháp tạm thời, không phải kế lâu dài."}]},{"hanzi":"保证","pinyin":"bǎozhèng","pos":"dgt./dt.","vn":"đảm bảo, cam đoan","examples":[{"cn":"我保证以后不会再迟到了。","pinyin":"wǒ bǎo zhèng yǐ hòu bú huì zài chí dào le 。","vn":"Tôi đảm bảo sau này sẽ không đi muộn nữa."},{"cn":"质量是我们最大的保证。","pinyin":"zhì liàng shì wǒ men zuì dà de bǎo zhèng 。","vn":"Chất lượng là bảo đảm lớn nhất của chúng tôi."},{"cn":"他向我保证会按时完成任务。","pinyin":"tā xiàng wǒ bǎo zhèng huì àn shí wán chéng rèn wù 。","vn":"Anh ấy cam đoan với tôi sẽ hoàn thành nhiệm vụ đúng hạn."}]},{"hanzi":"网络","pinyin":"wǎngluò","pos":"dt.","vn":"mạng, internet","examples":[{"cn":"这里的网络信号不太好。","pinyin":"zhè lǐ de wǎng luò xìn hào bù tài hǎo 。","vn":"Sóng mạng ở đây không tốt lắm."},{"cn":"他是靠网络赚钱的。","pinyin":"tā shì kào wǎng luò zhuàn qián de 。","vn":"Anh ấy kiếm tiền nhờ internet."},{"cn":"现在网络购物真方便。","pinyin":"xiàn zài wǎng luò gòu wù zhēn fāng biàn 。","vn":"Bây giờ mua sắm qua mạng thật tiện lợi."}]}],"grammar":[{"title":"转折复句\"……X是X，就是/不过……\"","explanation_vn":"Trong câu phức này, \"X是X\" là cấu trúc cố định, biểu thị sự khẳng định một tình huống hay thuộc tính nào đó, phía sau dùng các từ như \"就是\", \"不过\" để biểu thị ý chuyển ngoặt hoặc bổ sung thêm, chỉ ra rằng nội dung ở vế trước có giới hạn nhất định.","examples":[{"cn":"北京大是大，不过这边的路基本上都是正南正北、正东正西的，很好找。","pinyin":"Běijīng dà shì dà, búguò zhèbian de lù jīběnshàng dōu shì zhèngnán zhèngběi, zhèngdōng zhèngxī de, hěn hǎo zhǎo.","vn":"Bắc Kinh rộng thì rộng thật, nhưng đường ở khu này cơ bản đều là chính nam chính bắc, chính đông chính tây, rất dễ tìm."},{"cn":"这个房子便宜是便宜，就是离我的公司太远了。","pinyin":"Zhège fángzi piányi shì piányi, jiùshì lí wǒ de gōngsī tài yuǎn le.","vn":"Căn nhà này rẻ thì rẻ thật, chỉ có điều là cách công ty tôi quá xa."},{"cn":"我们想是想了，就是没想出更好的办法。","pinyin":"Wǒmen xiǎng shì xiǎng le, jiùshì méi xiǎngchū gèng hǎo de bànfǎ.","vn":"Chúng tôi nghĩ thì có nghĩ rồi, chỉ là chưa nghĩ ra cách nào tốt hơn."}]},{"title":"递进复句\"不仅/不光……，还/而且……\"","explanation_vn":"\"不仅/不光(không những)……，还/而且(mà còn)……\" biểu thị quan hệ tăng tiến. Vế sau là sự mở rộng hoặc bổ sung cho vế trước, biểu thị ý nghĩa tiến thêm một bước. Bài này học dạng câu phức có chung một chủ ngữ, cấu trúc là: Chủ ngữ + 不仅/不光……，还/而且……","examples":[{"cn":"现在我不仅会扫码结账，还会用手机在网上购物了。","pinyin":"Xiànzài wǒ bùjǐn huì sǎomǎ jiézhàng, hái huì yòng shǒujī zài wǎngshang gòuwù le.","vn":"Bây giờ tôi không những biết quét mã thanh toán, mà còn biết dùng điện thoại mua sắm trực tuyến nữa."},{"cn":"王老师不光教我们说中文，而且带我们了解中国文化。","pinyin":"Wáng lǎoshī bùguāng jiāo wǒmen shuō Zhōngwén, érqiě dài wǒmen liǎojiě Zhōngguó wénhuà.","vn":"Cô Vương không những dạy chúng tôi nói tiếng Trung, mà còn dẫn chúng tôi tìm hiểu văn hóa Trung Quốc."},{"cn":"现在很多书店不仅卖书，还卖咖啡和奶茶。","pinyin":"Xiànzài hěn duō shūdiàn bùjǐn mài shū, hái mài kāfēi hé nǎichá.","vn":"Hiện nay nhiều hiệu sách không những bán sách, mà còn bán cà phê và trà sữa."}]},{"title":"连词\"甚至\"","explanation_vn":"Liên từ \"甚至\" nhấn mạnh một tình huống nào đó nổi bật hơn, vượt ra ngoài dự đoán thông thường.","examples":[{"cn":"在中国网购，不仅选择多、价格不高，而且送货很快，很多留学生甚至改变了自己的购物习惯。","pinyin":"Zài Zhōngguó wǎnggòu, bùjǐn xuǎnzé duō, jiàgé bù gāo, érqiě sònghuò hěn kuài, hěn duō liúxuéshēng shènzhì gǎibiàn le zìjǐ de gòuwù xíguàn.","vn":"Mua sắm trực tuyến ở Trung Quốc không những có nhiều lựa chọn, giá cả không cao, mà việc giao hàng còn rất nhanh, rất nhiều du học sinh thậm chí đã thay đổi thói quen mua sắm của mình."},{"cn":"高铁速度真快，甚至还没看清楚，它就已经开过去了。","pinyin":"Gāotiě sùdù zhēn kuài, shènzhì hái méi kàn qīngchu, tā jiù yǐjīng kāi guòqù le.","vn":"Tàu cao tốc nhanh thật, thậm chí còn chưa kịp nhìn rõ thì nó đã chạy qua mất rồi."},{"cn":"这个小区真不错，有小花园、球场，甚至还有一个超市。","pinyin":"Zhège xiǎoqū zhēn búcuò, yǒu xiǎo huāyuán, qiúchǎng, shènzhì hái yǒu yí gè chāoshì.","vn":"Khu dân cư này thật tốt, có vườn hoa nhỏ, sân bóng, thậm chí còn có cả một siêu thị."}]},{"title":"承接复句\"……，于是……\"","explanation_vn":"Hai vế câu mô tả theo thứ tự các hành động hoặc sự việc liên tiếp, \"于是\" được dùng ở đầu vế sau. Giữa hai vế có quan hệ trước sau, về mặt logic có quan hệ nối tiếp.","examples":[{"cn":"在提供这些信息时，我们也会担心：我的个人信息能否得到保护？于是，有人在网上说出了自己的担心。","pinyin":"Zài tígōng zhèxiē xìnxī shí, wǒmen yě huì dānxīn: wǒ de gèrén xìnxī néngfǒu dédào bǎohù? Yúshì, yǒu rén zài wǎngshang shuōchū le zìjǐ de dānxīn.","vn":"Khi cung cấp những thông tin này, chúng ta cũng sẽ lo lắng: liệu thông tin cá nhân của mình có được bảo vệ hay không? Thế là, có người đã nói ra nỗi lo của mình trên mạng."},{"cn":"她从小就想当医生，于是上大学时就选择了学医。","pinyin":"Tā cóngxiǎo jiù xiǎng dāng yīshēng, yúshì shàng dàxué shí jiù xuǎnzé le xuéyī.","vn":"Từ nhỏ cô ấy đã muốn làm bác sĩ, vì vậy khi lên đại học đã chọn học ngành y."},{"cn":"最近总感冒，于是他决定病好后就开始锻炼身体。","pinyin":"Zuìjìn zǒng gǎnmào, yúshì tā juédìng bìng hǎo hòu jiù kāishǐ duànliàn shēntǐ.","vn":"Gần đây cứ bị cảm hoài, thế là anh ấy quyết định sau khi khỏi bệnh sẽ bắt đầu tập luyện thể thao."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"陈天中","cn":"请问，花园小区怎么走？","pinyin":"Qǐngwèn, Huāyuán Xiǎoqū zěnme zǒu?"},{"speaker":"同学","cn":"你往前走，到十字路口不要过马路，直接右转就到小区门口了。正好我也去那边，一起走吧。","pinyin":"Nǐ wǎng qián zǒu, dào shízì lùkǒu búyào guò mǎlù, zhíjiē yòuzhuǎn jiù dào xiǎoqū ménkǒu le. Zhènghǎo wǒ yě qù nàbian, yìqǐ zǒu ba."},{"speaker":"陈天中","cn":"好的。我刚来中国，不熟悉路。北京真是太大了。","pinyin":"Hǎo de. Wǒ gāng lái Zhōngguó, bù shúxī lù. Běijīng zhēn shì tài dà le."},{"speaker":"同学","cn":"北京大是大，不过这边的路基本上都是正南正北、正东正西的，很好找。你也可以用手机地图，很容易就能找到目的地。","pinyin":"Běijīng dà shì dà, búguò zhèbian de lù jīběnshàng dōu shì zhèngnán zhèngběi, zhèngdōng zhèngxī de, hěn hǎo zhǎo. Nǐ yě kěyǐ yòng shǒujī dìtú, hěn róngyì jiù néng zhǎodào mùdìdì."},{"speaker":"陈天中","cn":"嗯，不过很多中文地名我还不认识。","pinyin":"Ng, búguò hěn duō Zhōngwén dìmíng wǒ hái bú rènshi."},{"speaker":"同学","cn":"没关系，你很快就会熟悉的。","pinyin":"Méi guānxi, nǐ hěn kuài jiù huì shúxī de."}],"translation_vn":"Trần Thiên Trung: Xin hỏi, đi đến khu dân cư Hoa Viên thế nào ạ?\nBạn học: Bạn đi thẳng về phía trước, đến ngã tư thì đừng qua đường, rẽ phải trực tiếp là đến cổng khu dân cư rồi. Đúng lúc mình cũng đi hướng đó, đi cùng nhau nhé.\nTrần Thiên Trung: Được ạ. Mình mới đến Trung Quốc, chưa quen đường. Bắc Kinh thật là quá rộng lớn.\nBạn học: Bắc Kinh thì rộng là rộng thật, nhưng đường ở khu này cơ bản đều là chính nam chính bắc, chính đông chính tây, rất dễ tìm. Bạn cũng có thể dùng bản đồ điện thoại, rất dễ dàng tìm được điểm đến.\nTrần Thiên Trung: Vâng, nhưng có nhiều tên địa danh tiếng Trung mình vẫn chưa biết.\nBạn học: Không sao, bạn sẽ sớm quen thôi.","audio_dialogue":"3-1.mp3","audio_vocab":"3-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"陈天中","cn":"前两天和李文喝咖啡时，他帮我下载了微信和支付宝，教我认识里边的汉字，还教我用手机进行支付。","pinyin":"Qián liǎng tiān hé Lǐ Wén hē kāfēi shí, tā bāng wǒ xiàzài le Wēixìn hé Zhīfùbǎo, jiāo wǒ rènshi lǐbian de Hànzì, hái jiāo wǒ yòng shǒujī jìnxíng zhīfù."},{"speaker":"白家月","cn":"他也教了我怎么用这两个软件。","pinyin":"Tā yě jiāo le wǒ zěnme yòng zhè liǎng gè ruǎnjiàn."},{"speaker":"陈天中","cn":"现在我不仅会扫码结账，还会用手机在网上购物了。昨天我就在网上订了一台电脑，今天下午一点送到。","pinyin":"Xiànzài wǒ bùjǐn huì sǎomǎ jiézhàng, hái huì yòng shǒujī zài wǎngshang gòuwù le. Zuótiān wǒ jiù zài wǎngshang dìng le yì tái diànnǎo, jīntiān xiàwǔ yī diǎn sòngdào."},{"speaker":"白家月","cn":"学会了这些，我们在中国生活真是方便了不少。","pinyin":"Xuéhuì le zhèxiē, wǒmen zài Zhōngguó shēnghuó zhēn shì fāngbiàn le bùshǎo."},{"speaker":"陈天中","cn":"对。快递员要到了，我得马上回去！家月，明天见！","pinyin":"Duì. Kuàidìyuán yào dào le, wǒ děi mǎshàng huíqù! Jiāyuè, míngtiān jiàn!"},{"speaker":"白家月","cn":"好的，天中，再见。","pinyin":"Hǎo de, Tiānzhōng, zàijiàn."}],"translation_vn":"Trần Thiên Trung: Hôm trước uống cà phê với Lý Văn, anh ấy đã giúp mình tải WeChat và Alipay, dạy mình nhận biết chữ Hán trong đó, còn dạy mình dùng điện thoại để thanh toán.\nBạch Gia Nguyệt: Anh ấy cũng dạy mình cách dùng hai phần mềm này.\nTrần Thiên Trung: Bây giờ mình không chỉ biết quét mã thanh toán, mà còn biết dùng điện thoại mua sắm trực tuyến nữa. Hôm qua mình đã đặt mua một chiếc máy tính trên mạng, chiều nay một giờ sẽ được giao đến.\nBạch Gia Nguyệt: Học được những điều này, cuộc sống của chúng ta ở Trung Quốc thật sự tiện lợi hơn nhiều.\nTrần Thiên Trung: Đúng vậy. Nhân viên giao hàng sắp đến rồi, mình phải về ngay đây! Gia Nguyệt, hẹn gặp lại ngày mai nhé!\nBạch Gia Nguyệt: Được rồi, Thiên Trung, tạm biệt.","audio_dialogue":"3-3.mp3","audio_vocab":"3-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"白家月和陈天中刚到北京时就发现，中国人在饭馆或超市结账时，几乎都用手机支付，只有他们用现金结账。在李文的帮助下，白家月和陈天中也都学会了用手机支付、网购、寄快递等等。在中国网购，不仅选择多、价格不高，而且送货很快，很多留学生甚至改变了自己的购物习惯。不过，由于网购太方便了，动动手指就能买到想要的东西，他们也开始担心自己在网购时会乱花钱。怎么才能管住自己不乱花钱呢？","pinyin":"Bái Jiāyuè hé Chén Tiānzhōng gāng dào Běijīng shí jiù fāxiàn, Zhōngguórén zài fànguǎn huò chāoshì jiézhàng shí, jīhū dōu yòng shǒujī zhīfù, zhǐyǒu tāmen yòng xiànjīn jiézhàng. Zài Lǐ Wén de bāngzhù xià, Bái Jiāyuè hé Chén Tiānzhōng yě dōu xuéhuì le yòng shǒujī zhīfù, wǎnggòu, jì kuàidì děngděng. Zài Zhōngguó wǎnggòu, bùjǐn xuǎnzé duō, jiàgé bù gāo, érqiě sònghuò hěn kuài, hěn duō liúxuéshēng shènzhì gǎibiàn le zìjǐ de gòuwù xíguàn. Búguò, yóuyú wǎnggòu tài fāngbiàn le, dòngdong shǒuzhǐ jiù néng mǎidào xiǎngyào de dōngxi, tāmen yě kāishǐ dānxīn zìjǐ zài wǎnggòu shí huì luàn huāqián. Zěnme cái néng guǎnzhù zìjǐ bú luàn huāqián ne?"}],"translation_vn":"Khi Bạch Gia Nguyệt và Trần Thiên Trung mới đến Bắc Kinh đã phát hiện ra rằng người Trung Quốc khi thanh toán ở nhà hàng hay siêu thị hầu như đều dùng điện thoại để trả tiền, chỉ có họ là dùng tiền mặt để thanh toán. Nhờ sự giúp đỡ của Lý Văn, Bạch Gia Nguyệt và Trần Thiên Trung cũng đều đã học được cách thanh toán bằng điện thoại, mua sắm trực tuyến, gửi chuyển phát nhanh, v.v. Khi mua sắm trực tuyến ở Trung Quốc, không những có nhiều lựa chọn, giá cả không cao, mà việc giao hàng còn rất nhanh, rất nhiều du học sinh thậm chí đã thay đổi thói quen mua sắm của mình. Tuy nhiên, vì mua sắm trực tuyến quá tiện lợi, chỉ cần động ngón tay là có thể mua được thứ mình muốn, nên họ cũng bắt đầu lo lắng rằng mình sẽ tiêu tiền bừa bãi khi mua sắm trực tuyến. Làm thế nào để có thể kiểm soát bản thân không tiêu tiền bừa bãi đây?","audio_dialogue":"3-5.mp3","audio_vocab":"3-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"网上购物或者订票时，我们经常需要提供姓名、手机号、身份证号等个人信息。在提供这些信息时，我们也会担心：我的个人信息能否得到保护？于是，有人在网上说出了自己的担心，很快就有人给出了一些建议。比如，别把密码随便告诉别人，不在网上发自己的车票、机票信息……现在，很多国家也通过技术、法律等手段来保证个人信息安全。比如中国的网络安全法、个人信息保护法等就很好地保护了人们的个人信息。","pinyin":"Wǎngshang gòuwù huòzhě dìngpiào shí, wǒmen jīngcháng xūyào tígōng xìngmíng, shǒujīhào, shēnfènzhènghào děng gèrén xìnxī. Zài tígōng zhèxiē xìnxī shí, wǒmen yě huì dānxīn: wǒ de gèrén xìnxī néngfǒu dédào bǎohù? Yúshì, yǒu rén zài wǎngshang shuōchū le zìjǐ de dānxīn, hěn kuài jiù yǒu rén gěichū le yìxiē jiànyì. Bǐrú, bié bǎ mìmǎ suíbiàn gàosu biérén, bú zài wǎngshang fā zìjǐ de chēpiào, jīpiào xìnxī... Xiànzài, hěn duō guójiā yě tōngguò jìshù, fǎlǜ děng shǒuduàn lái bǎozhèng gèrén xìnxī ānquán. Bǐrú Zhōngguó de Wǎngluò Ānquán Fǎ, Gèrén Xìnxī Bǎohù Fǎ děng jiù hěn hǎo de bǎohù le rénmen de gèrén xìnxī."}],"translation_vn":"Khi mua sắm trực tuyến hoặc đặt vé, chúng ta thường cần cung cấp các thông tin cá nhân như họ tên, số điện thoại, số chứng minh thư. Khi cung cấp những thông tin này, chúng ta cũng lo lắng: liệu thông tin cá nhân của mình có được bảo vệ hay không? Thế là, có người đã nói ra nỗi lo của mình trên mạng, và nhanh chóng có người đưa ra một số lời khuyên. Chẳng hạn, đừng tùy tiện nói mật khẩu cho người khác biết, không đăng thông tin vé tàu, vé máy bay của mình lên mạng... Hiện nay, rất nhiều quốc gia cũng thông qua các biện pháp như công nghệ, pháp luật để đảm bảo an toàn thông tin cá nhân. Ví dụ như Luật An ninh mạng, Luật Bảo vệ thông tin cá nhân của Trung Quốc đã bảo vệ rất tốt thông tin cá nhân của người dân.","audio_dialogue":"3-7.mp3","audio_vocab":"3-8.mp3"}]},{"id":4,"title_cn":"很高兴能帮到你","title_pinyin":"Hěn gāoxìng néng bāngdào nǐ","title_vn":"Rất vui vì đã giúp được bạn","goals":["Có thể nghe hiểu và trao đổi về các chủ đề nhờ giúp đỡ hoặc giúp đỡ người khác trong cuộc sống hằng ngày.","Có thể diễn đạt bằng lời nói hoặc chữ viết về các phương thức đi lại khác nhau cùng ưu nhược điểm của chúng.","Hiểu được các dịch vụ tiện ích phục vụ người dân ở các thành phố Trung Quốc."],"vocab":[{"hanzi":"啊","pinyin":"ā","pos":"ct.","vn":"a, ôi (thán từ)","examples":[{"cn":"啊，下雨了！","pinyin":"a ， xià yǔ le ！","vn":"A, trời mưa rồi!"},{"cn":"这个蛋糕真好吃啊！","pinyin":"zhè ge dàn gāo zhēn hǎo chī a ！","vn":"Cái bánh này ngon thật đấy!"},{"cn":"啊，我忘带钥匙了。","pinyin":"a ， wǒ wàng dài yào shi le 。","vn":"Ôi, tôi quên mang chìa khóa rồi."}]},{"hanzi":"停","pinyin":"tíng","pos":"dgt.","vn":"dừng; đỗ (xe)","examples":[{"cn":"车停在路边了。","pinyin":"chē tíng zài lù biān le 。","vn":"Xe đã đỗ bên đường rồi."},{"cn":"雨一会儿就停了。","pinyin":"yǔ yī huì er jiù tíng le 。","vn":"Lát nữa mưa sẽ tạnh thôi."},{"cn":"请把车停在那边。","pinyin":"qǐng bǎ chē tíng zài nà biān 。","vn":"Làm ơn đỗ xe ở đằng kia."}]},{"hanzi":"交","pinyin":"jiāo","pos":"dgt.","vn":"nộp, giao","examples":[{"cn":"作业明天要交。","pinyin":"zuò yè míng tiān yào jiāo 。","vn":"Mai phải nộp bài tập."},{"cn":"他把钱交给了老板。","pinyin":"tā bǎ qián jiāo gěi le lǎo bǎn 。","vn":"Anh ấy đã giao tiền cho ông chủ."},{"cn":"这个月的房租还没交。","pinyin":"zhè ge yuè de fáng zū hái méi jiāo 。","vn":"Tiền thuê nhà tháng này chưa nộp."}]},{"hanzi":"费","pinyin":"fèi","pos":"dt./dgt.","vn":"phí, chi phí; tốn kém","examples":[{"cn":"这个月的电费有点多。","pinyin":"zhè ge yuè de diàn fèi yǒu diǎn duō 。","vn":"Tiền điện tháng này hơi nhiều."},{"cn":"做这件事太费时间了。","pinyin":"zuò zhè jiàn shì tài fèi shí jiān le 。","vn":"Làm việc này tốn thời gian quá."},{"cn":"停车费一个小时十块钱。","pinyin":"tíng chē fèi yí gè xiǎo shí shí kuài qián 。","vn":"Phí đỗ xe là mười tệ một giờ."}]},{"hanzi":"信号","pinyin":"xìnhào","pos":"dt.","vn":"tín hiệu, sóng","examples":[{"cn":"这里山区信号不好。","pinyin":"zhè lǐ shān qū xìn hào bù hǎo 。","vn":"Ở vùng núi này sóng điện thoại không tốt."},{"cn":"手机一点信号都没有。","pinyin":"shǒu jī yì diǎn xìn hào dōu méi yǒu 。","vn":"Điện thoại chẳng có chút tín hiệu nào."},{"cn":"他给我打了个信号，让我过去。","pinyin":"tā gěi wǒ dǎ le gè xìn hào ， ràng wǒ guò qù 。","vn":"Anh ấy ra hiệu cho tôi để tôi qua đó."}]},{"hanzi":"感谢","pinyin":"gǎnxiè","pos":"dgt.","vn":"cảm ơn","examples":[{"cn":"非常感谢你的帮助。","pinyin":"fēi cháng gǎn xiè nǐ de bāng zhù 。","vn":"Rất cảm ơn sự giúp đỡ của bạn."},{"cn":"我要感谢所有支持我的人。","pinyin":"wǒ yào gǎn xiè suǒ yǒu zhī chí wǒ de rén 。","vn":"Tôi muốn cảm ơn tất cả những người ủng hộ mình."},{"cn":"他特意来感谢老师。","pinyin":"tā tè yì lái gǎn xiè lǎo shī 。","vn":"Anh ấy đặc biệt đến cảm ơn thầy giáo."}]},{"hanzi":"联系","pinyin":"liánxì","pos":"dgt.","vn":"liên hệ","examples":[{"cn":"有事可以随时联系我。","pinyin":"yǒu shì kě yǐ suí shí lián xì wǒ 。","vn":"Có việc gì cứ liên hệ tôi bất cứ lúc nào."},{"cn":"我们好久没联系了。","pinyin":"wǒ men hǎo jiǔ méi lián xì le 。","vn":"Chúng tôi đã lâu không liên lạc rồi."},{"cn":"请留下你的联系方式。","pinyin":"qǐng liú xià nǐ de lián xì fāng shì 。","vn":"Xin để lại cách liên hệ của bạn."}]},{"hanzi":"方式","pinyin":"fāngshì","pos":"dt.","vn":"phương thức, cách thức","examples":[{"cn":"每个人的学习方式不一样。","pinyin":"měi gè rén de xué xí fāng shì bù yí yàng 。","vn":"Cách học của mỗi người mỗi khác."},{"cn":"这种沟通方式不太好。","pinyin":"zhè zhǒng gōu tōng fāng shì bù tài hǎo 。","vn":"Phương thức giao tiếp này không ổn lắm."},{"cn":"请选择你方便的联系方式。","pinyin":"qǐng xuǎn zé nǐ fāng biàn de lián xì fāng shì 。","vn":"Hãy chọn cách liên hệ thuận tiện cho bạn."}]},{"hanzi":"客气","pinyin":"kèqi","pos":"dgt./tt.","vn":"khách sáo; lịch sự","examples":[{"cn":"别客气，像在自己家一样。","pinyin":"bié kè qì ， xiàng zài zì jǐ jiā yī yàng 。","vn":"Đừng khách sáo, cứ như ở nhà mình vậy."},{"cn":"他对谁都很客气。","pinyin":"tā duì shéi dōu hěn kè qì 。","vn":"Anh ấy rất lịch sự với mọi người."},{"cn":"你太客气了，不用送礼物的。","pinyin":"nǐ tài kè qì le ， bù yòng sòng lǐ wù de 。","vn":"Bạn khách sáo quá, không cần tặng quà đâu."}]},{"hanzi":"剩","pinyin":"shèng","pos":"dgt.","vn":"còn thừa, còn lại","examples":[{"cn":"饭还剩不少，别浪费。","pinyin":"fàn hái shèng bù shǎo ， bié làng fèi 。","vn":"Cơm vẫn còn thừa khá nhiều, đừng lãng phí."},{"cn":"时间不多了，只剩十分钟了。","pinyin":"shí jiān bù duō le ， zhǐ shèng shí fēn zhōng le 。","vn":"Thời gian không còn nhiều, chỉ còn mười phút nữa thôi."},{"cn":"钱都花完了，什么都没剩下。","pinyin":"qián dōu huā wán le ， shén me dōu méi shèng xià 。","vn":"Tiền tiêu hết sạch, chẳng còn lại gì cả."}]},{"hanzi":"提","pinyin":"tí","pos":"dgt.","vn":"xách","examples":[{"cn":"他提着一个大箱子上楼。","pinyin":"tā tí zhe yí gè dà xiāng zi shàng lóu 。","vn":"Anh ấy xách một chiếc va li to lên lầu."},{"cn":"我帮你提东西吧。","pinyin":"wǒ bāng nǐ tí dōng xī ba 。","vn":"Tôi xách đồ giúp bạn nhé."},{"cn":"她手里提着几袋水果。","pinyin":"tā shǒu lǐ tí zhe jǐ dài shuǐ guǒ 。","vn":"Cô ấy tay xách mấy túi hoa quả."}]},{"hanzi":"袋子","pinyin":"dàizi","pos":"dt.","vn":"túi","examples":[{"cn":"买菜的袋子放在厨房。","pinyin":"mǎi cài de dài zi fàng zài chú fáng 。","vn":"Túi đựng rau để trong bếp."},{"cn":"这个袋子装不下这么多东西。","pinyin":"zhè ge dài zi zhuāng bù xià zhè me duō dōng xī 。","vn":"Cái túi này không đựng được nhiều đồ như vậy."},{"cn":"请给我一个塑料袋子。","pinyin":"qǐng gěi wǒ yí gè sù liào dài zi 。","vn":"Cho tôi xin một cái túi ni lông."}]},{"hanzi":"重","pinyin":"zhòng","pos":"tt./dt.","vn":"nặng; trọng lượng","examples":[{"cn":"这个箱子真重，得两个人才能抬。","pinyin":"zhè ge xiāng zi zhēn zhòng ， dé liǎng gè rén cái néng tái 。","vn":"Cái thùng này nặng thật, phải hai người mới khiêng nổi."},{"cn":"他说话的语气很重。","pinyin":"tā shuō huà de yǔ qì hěn zhòng 。","vn":"Giọng nói của anh ấy rất nặng nề."},{"cn":"这次任务很重，大家都要加把劲。","pinyin":"zhè cì rèn wù hěn zhòng ， dà jiā dōu yào jiā bǎ jìn 。","vn":"Nhiệm vụ lần này rất nặng, mọi người phải cố gắng lên."}]},{"hanzi":"算","pinyin":"suàn","pos":"dgt.","vn":"coi như, tính là","examples":[{"cn":"这顿饭就算我请客吧。","pinyin":"zhè dùn fàn jiù suàn wǒ qǐng kè ba 。","vn":"Bữa này coi như tôi mời vậy."},{"cn":"这件事就算了，别再提了。","pinyin":"zhè jiàn shì jiù suàn le ， bié zài tí le 。","vn":"Chuyện này thôi bỏ qua, đừng nhắc lại nữa."},{"cn":"他这次表现还算不错。","pinyin":"tā zhè cì biǎo xiàn hái suàn bú cuò 。","vn":"Lần này anh ấy thể hiện cũng coi như không tệ."}]},{"hanzi":"再说","pinyin":"zàishuō","pos":"liên.","vn":"hơn nữa, vả lại","examples":[{"cn":"今天太晚了，再说我也很累，改天再去吧。","pinyin":"jīn tiān tài wǎn le ， zài shuō wǒ yě hěn lèi ， gǎi tiān zài qù ba 。","vn":"Hôm nay muộn quá rồi, hơn nữa tôi cũng mệt, hôm khác hẵng đi."},{"cn":"这件衣服有点贵，再说颜色也不太适合我。","pinyin":"zhè jiàn yī fú yǒu diǎn guì ， zài shuō yán sè yě bù tài shì hé wǒ 。","vn":"Cái áo này hơi đắt, vả lại màu cũng không hợp với tôi lắm."},{"cn":"他身体不太好，再说年纪也大了，别让他干重活。","pinyin":"tā shēn tǐ bù tài hǎo ， zài shuō nián jì yě dà le ， bié ràng tā gàn zhòng huó 。","vn":"Sức khỏe anh ấy không tốt, vả lại tuổi cũng lớn rồi, đừng để anh ấy làm việc nặng."}]},{"hanzi":"之间","pinyin":"zhījiān","pos":"dt.","vn":"giữa, trong khoảng","examples":[{"cn":"他们俩之间有点误会。","pinyin":"tā men liǎ zhī jiān yǒu diǎn wù huì 。","vn":"Giữa hai người họ có chút hiểu lầm."},{"cn":"这件事发生在上个月之间。","pinyin":"zhè jiàn shì fā shēng zài shàng gè yuè zhī jiān 。","vn":"Chuyện này xảy ra trong khoảng tháng trước."},{"cn":"公司和员工之间要互相信任。","pinyin":"gōng sī hé yuán gōng zhī jiān yào hù xiāng xìn rèn 。","vn":"Công ty và nhân viên phải tin tưởng lẫn nhau."}]},{"hanzi":"互相","pinyin":"hùxiāng","pos":"phó.","vn":"lẫn nhau, qua lại","examples":[{"cn":"我们应该互相帮助。","pinyin":"wǒ men yīng gāi hù xiāng bāng zhù 。","vn":"Chúng ta nên giúp đỡ lẫn nhau."},{"cn":"夫妻之间要互相理解。","pinyin":"fū qī zhī jiān yào hù xiāng lǐ jiě 。","vn":"Vợ chồng phải hiểu nhau."},{"cn":"大家互相认识一下吧。","pinyin":"dà jiā hù xiāng rèn shí yī xià ba 。","vn":"Mọi người làm quen với nhau một chút nhé."}]},{"hanzi":"辛苦","pinyin":"xīnkǔ","pos":"dgt./tt.","vn":"vất vả, cực nhọc","examples":[{"cn":"这段时间你辛苦了。","pinyin":"zhè duàn shí jiān nǐ xīn kǔ le 。","vn":"Dạo này bạn vất vả rồi."},{"cn":"父母为了孩子真的很辛苦。","pinyin":"fù mǔ wèi le hái zi zhēn de hěn xīn kǔ 。","vn":"Cha mẹ vì con cái thật sự rất cực nhọc."},{"cn":"辛苦大家加班完成这个项目。","pinyin":"xīn kǔ dà jiā jiā bān wán chéng zhè ge xiàng mù 。","vn":"Mọi người vất vả tăng ca để hoàn thành dự án này."}]},{"hanzi":"出行","pinyin":"chūxíng","pos":"dgt.","vn":"đi lại, ra ngoài đi đường","examples":[{"cn":"节假日出行的人特别多。","pinyin":"jié jià rì chū xíng de rén tè bié duō 。","vn":"Ngày lễ số người đi lại đặc biệt đông."},{"cn":"骑电动车出行又方便又环保。","pinyin":"qí diàn dòng chē chū xíng yòu fāng biàn yòu huán bǎo 。","vn":"Đi lại bằng xe điện vừa tiện vừa thân thiện môi trường."},{"cn":"下雪天出行要小心路滑。","pinyin":"xià xuě tiān chū xíng yào xiǎo xīn lù huá 。","vn":"Ngày tuyết rơi đi đường phải cẩn thận trơn trượt."}]},{"hanzi":"距离","pinyin":"jùlí","pos":"dt./dgt.","vn":"khoảng cách; cách xa","examples":[{"cn":"这里离公司的距离不远。","pinyin":"zhè lǐ lí gōng sī de jù lí bù yuǎn 。","vn":"Khoảng cách từ đây đến công ty không xa."},{"cn":"我们之间的距离越来越远了。","pinyin":"wǒ men zhī jiān de jù lí yuè lái yuè yuǎn le 。","vn":"Khoảng cách giữa chúng tôi ngày càng xa hơn."},{"cn":"跑步可以锻炼身体，距离不用太长。","pinyin":"pǎo bù kě yǐ duàn liàn shēn tǐ ， jù lí bù yòng tài zhǎng 。","vn":"Chạy bộ có thể rèn luyện sức khỏe, khoảng cách không cần quá dài."}]},{"hanzi":"往往","pinyin":"wǎngwǎng","pos":"phó.","vn":"thường thường","examples":[{"cn":"成功的人往往更努力。","pinyin":"chéng gōng de rén wǎng wǎng gèng nǔ lì 。","vn":"Người thành công thường nỗ lực hơn."},{"cn":"他往往加班到很晚。","pinyin":"tā wǎng wǎng jiā bān dào hěn wǎn 。","vn":"Anh ấy thường tăng ca đến rất khuya."},{"cn":"事情往往没有想象中那么简单。","pinyin":"shì qíng wǎng wǎng méi yǒu xiǎng xiàng zhōng nà me jiǎn dān 。","vn":"Sự việc thường không đơn giản như người ta tưởng."}]},{"hanzi":"既","pinyin":"jì","pos":"phó.","vn":"vừa... (vừa...)","examples":[{"cn":"这个方法既简单又有效。","pinyin":"zhè ge fāng fǎ jì jiǎn dān yòu yǒu xiào 。","vn":"Cách này vừa đơn giản vừa hiệu quả."},{"cn":"他既聪明又勤奋。","pinyin":"tā jì cōng míng yòu qín fèn 。","vn":"Anh ấy vừa thông minh vừa chăm chỉ."},{"cn":"这个房子既便宜又宽敞。","pinyin":"zhè ge fáng zi jì pián yi yòu kuān chǎng 。","vn":"Căn nhà này vừa rẻ vừa rộng rãi."}]},{"hanzi":"电动车","pinyin":"diàndòngchē","pos":"dt.","vn":"xe điện","examples":[{"cn":"他每天骑电动车上班。","pinyin":"tā měi tiān qí diàn dòng chē shàng bān 。","vn":"Anh ấy mỗi ngày đi xe điện đi làm."},{"cn":"电动车比摩托车环保。","pinyin":"diàn dòng chē bǐ mó tuō chē huán bǎo 。","vn":"Xe điện thân thiện môi trường hơn xe máy."},{"cn":"电动车没电了，得找地方充电。","pinyin":"diàn dòng chē méi diàn le ， dé zhǎo dì fāng chōng diàn 。","vn":"Xe điện hết điện rồi, phải tìm chỗ sạc."}]},{"hanzi":"速度","pinyin":"sùdù","pos":"dt.","vn":"tốc độ","examples":[{"cn":"这辆车的速度真快。","pinyin":"zhè liàng chē de sù dù zhēn kuài 。","vn":"Tốc độ của chiếc xe này nhanh thật."},{"cn":"他说话的速度有点快。","pinyin":"tā shuō huà de sù dù yǒu diǎn kuài 。","vn":"Tốc độ nói chuyện của anh ấy hơi nhanh."},{"cn":"这里的网络速度太慢了，看视频总卡。","pinyin":"zhè lǐ de wǎng luò sù dù tài màn le ， kàn shì pín zǒng kǎ 。","vn":"Tốc độ mạng ở đây chậm quá, xem video cứ bị giật."}]},{"hanzi":"充电","pinyin":"chōngdiàn","pos":"dgt.","vn":"sạc điện","examples":[{"cn":"手机没电了，我去充电。","pinyin":"shǒu jī méi diàn le ， wǒ qù chōng diàn 。","vn":"Điện thoại hết pin rồi, tôi đi sạc đây."},{"cn":"电动车晚上一般在家充电。","pinyin":"diàn dòng chē wǎn shàng yì bān zài jiā chōng diàn 。","vn":"Xe điện thường sạc ở nhà vào buổi tối."},{"cn":"这个充电器坏了。","pinyin":"zhè ge chōng diàn qì huài le 。","vn":"Cái sạc này hỏng rồi."}]},{"hanzi":"流行","pinyin":"liúxíng","pos":"dgt.","vn":"phổ biến, thịnh hành","examples":[{"cn":"这种发型现在很流行。","pinyin":"zhè zhǒng fà xíng xiàn zài hěn liú xíng 。","vn":"Kiểu tóc này bây giờ rất thịnh hành."},{"cn":"短视频在年轻人中很流行。","pinyin":"duǎn shì pín zài nián qīng rén zhōng hěn liú xíng 。","vn":"Video ngắn rất phổ biến trong giới trẻ."},{"cn":"这首歌去年特别流行。","pinyin":"zhè shǒu gē qù nián tè bié liú xíng 。","vn":"Bài hát này năm ngoái rất thịnh hành."}]},{"hanzi":"省","pinyin":"shěng","pos":"dgt.","vn":"tiết kiệm","examples":[{"cn":"坐地铁能省不少钱。","pinyin":"zuò dì tiě néng shěng bù shǎo qián 。","vn":"Đi tàu điện ngầm tiết kiệm được khá nhiều tiền."},{"cn":"他平时很省，很少乱花钱。","pinyin":"tā píng shí hěn shěng ， hěn shǎo luàn huā qián 。","vn":"Anh ấy bình thường rất tiết kiệm, ít khi tiêu xài lung tung."},{"cn":"这样做能省不少时间。","pinyin":"zhè yàng zuò néng shěng bù shǎo shí jiān 。","vn":"Làm vậy có thể tiết kiệm được nhiều thời gian."}]},{"hanzi":"力气","pinyin":"lìqi","pos":"dt.","vn":"sức lực","examples":[{"cn":"搬这个箱子真费力气。","pinyin":"bān zhè ge xiāng zi zhēn fèi lì qì 。","vn":"Khiêng cái thùng này thật tốn sức."},{"cn":"他力气很大，一个人就能抬起来。","pinyin":"tā lì qì hěn dà ， yí gè rén jiù néng tái qǐ lái 。","vn":"Anh ấy khỏe lắm, một mình cũng khiêng nổi."},{"cn":"我今天没什么力气，想休息一下。","pinyin":"wǒ jīn tiān méi shén me lì qì ， xiǎng xiū xī yī xià 。","vn":"Hôm nay tôi không còn sức, muốn nghỉ ngơi một chút."}]},{"hanzi":"乘客","pinyin":"chéngkè","pos":"dt.","vn":"hành khách","examples":[{"cn":"请乘客系好安全带。","pinyin":"qǐng chéng kè jì hǎo ān quán dài 。","vn":"Mời hành khách thắt dây an toàn."},{"cn":"这趟车上的乘客不多。","pinyin":"zhè tàng chē shàng de chéng kè bù duō 。","vn":"Chuyến xe này không có nhiều hành khách."},{"cn":"司机提醒乘客注意脚下。","pinyin":"sī jī tí xǐng chéng kè zhù yì jiǎo xià 。","vn":"Tài xế nhắc hành khách chú ý dưới chân."}]},{"hanzi":"购买","pinyin":"gòumǎi","pos":"dgt.","vn":"mua","examples":[{"cn":"他打算购买一套新房子。","pinyin":"tā dǎ suàn gòu mǎi yī tào xīn fáng zi 。","vn":"Anh ấy định mua một căn nhà mới."},{"cn":"这些材料需要去市场购买。","pinyin":"zhè xiē cái liào xū yào qù shì chǎng gòu mǎi 。","vn":"Những nguyên liệu này cần ra chợ mua."},{"cn":"购买前请仔细看看说明书。","pinyin":"gòu mǎi qián qǐng zǐ xì kàn kàn shuō míng shū 。","vn":"Trước khi mua hãy đọc kỹ hướng dẫn sử dụng."}]},{"hanzi":"食物","pinyin":"shíwù","pos":"dt.","vn":"thức ăn","examples":[{"cn":"冰箱里有不少食物。","pinyin":"bīng xiāng lǐ yǒu bù shǎo shí wù 。","vn":"Trong tủ lạnh có khá nhiều thức ăn."},{"cn":"这种食物对身体不太好。","pinyin":"zhè zhǒng shí wù duì shēn tǐ bù tài hǎo 。","vn":"Loại thức ăn này không tốt cho sức khỏe lắm."},{"cn":"旅行时要带一些食物。","pinyin":"lǚ xíng shí yào dài yī xiē shí wù 。","vn":"Khi đi du lịch nên mang theo ít thức ăn."}]},{"hanzi":"免费","pinyin":"miǎnfèi","pos":"dgt.","vn":"miễn phí","examples":[{"cn":"这个活动是免费参加的。","pinyin":"zhè ge huó dòng shì miǎn fèi cān jiā de 。","vn":"Hoạt động này được tham gia miễn phí."},{"cn":"第一次体验免费。","pinyin":"dì yī cì tǐ yàn miǎn fèi 。","vn":"Lần trải nghiệm đầu tiên miễn phí."},{"cn":"这里停车不免费。","pinyin":"zhè lǐ tíng chē bù miǎn fèi 。","vn":"Đỗ xe ở đây không miễn phí đâu."}]},{"hanzi":"早餐","pinyin":"zǎocān","pos":"dt.","vn":"bữa sáng","examples":[{"cn":"我每天都吃早餐。","pinyin":"wǒ měi tiān dōu chī zǎo cān 。","vn":"Ngày nào tôi cũng ăn sáng."},{"cn":"酒店提供免费早餐。","pinyin":"jiǔ diàn tí gōng miǎn fèi zǎo cān 。","vn":"Khách sạn cung cấp bữa sáng miễn phí."},{"cn":"他从来不吃早餐，习惯不好。","pinyin":"tā cóng lái bù chī zǎo cān ， xí guàn bù hǎo 。","vn":"Anh ấy chẳng bao giờ ăn sáng, thói quen không tốt."}]},{"hanzi":"来得及","pinyin":"láidejí","pos":"dgt.","vn":"kịp, còn kịp","examples":[{"cn":"现在出发还来得及。","pinyin":"xiàn zài chū fā hái lái de jí 。","vn":"Bây giờ xuất phát vẫn còn kịp."},{"cn":"别着急，时间来得及。","pinyin":"bié zháo jí ， shí jiān lái de jí 。","vn":"Đừng vội, thời gian vẫn còn kịp."},{"cn":"只要快点，还来得及赶上火车。","pinyin":"zhǐ yào kuài diǎn ， hái lái de jí gǎn shàng huǒ chē 。","vn":"Chỉ cần nhanh lên một chút, vẫn kịp bắt chuyến tàu."}]},{"hanzi":"鲜花","pinyin":"xiānhuā","pos":"dt.","vn":"hoa tươi","examples":[{"cn":"他送了我一束鲜花。","pinyin":"tā sòng le wǒ yī shù xiān huā 。","vn":"Anh ấy tặng tôi một bó hoa tươi."},{"cn":"婚礼现场摆满了鲜花。","pinyin":"hūn lǐ xiàn chǎng bǎi mǎn le xiān huā 。","vn":"Lễ cưới ngập tràn hoa tươi."},{"cn":"这些鲜花是今天早上刚送到的。","pinyin":"zhè xiē xiān huā shì jīn tiān zǎo shàng gāng sòng dào de 。","vn":"Chỗ hoa tươi này sáng nay vừa mới được giao đến."}]},{"hanzi":"顺便","pinyin":"shùnbiàn","pos":"phó.","vn":"tiện thể, nhân tiện","examples":[{"cn":"你去超市的时候顺便帮我买瓶水。","pinyin":"nǐ qù chāo shì de shí hòu shùn biàn bāng wǒ mǎi píng shuǐ 。","vn":"Khi bạn đi siêu thị thì tiện thể mua giúp tôi chai nước."},{"cn":"我去机场顺便去看看朋友。","pinyin":"wǒ qù jī chǎng shùn biàn qù kàn kàn péng yǒu 。","vn":"Tôi đi sân bay tiện thể ghé thăm bạn."},{"cn":"顺便问一下，你今天有空吗？","pinyin":"shùn biàn wèn yī xià ， nǐ jīn tiān yǒu kòng ma ？","vn":"Tiện thể hỏi luôn, hôm nay bạn có rảnh không?"}]},{"hanzi":"心情","pinyin":"xīnqíng","pos":"dt.","vn":"tâm trạng","examples":[{"cn":"今天心情不太好。","pinyin":"jīn tiān xīn qíng bù tài hǎo 。","vn":"Hôm nay tâm trạng không được tốt lắm."},{"cn":"听了这首歌，我的心情好多了。","pinyin":"tīng le zhè shǒu gē ， wǒ de xīn qíng hǎo duō le 。","vn":"Nghe bài hát này xong tâm trạng tôi khá hơn nhiều."},{"cn":"他似乎心情不错，一直在笑。","pinyin":"tā sì hū xīn qíng bù cuò ， yì zhí zài xiào 。","vn":"Anh ấy có vẻ tâm trạng tốt, cứ cười suốt."}]},{"hanzi":"更加","pinyin":"gèngjiā","pos":"phó.","vn":"càng, càng thêm","examples":[{"cn":"经过这件事，他变得更加成熟了。","pinyin":"jīng guò zhè jiàn shì ， tā biàn dé gèng jiā chéng shú le 。","vn":"Qua chuyện này, anh ấy trở nên chín chắn hơn."},{"cn":"有了你的帮助，事情更加顺利了。","pinyin":"yǒu le nǐ de bāng zhù ， shì qíng gèng jiā shùn lì le 。","vn":"Có sự giúp đỡ của bạn, mọi việc càng thêm thuận lợi."},{"cn":"天气更加冷了，多穿点衣服。","pinyin":"tiān qì gèng jiā lěng le ， duō chuān diǎn yī fú 。","vn":"Trời càng lạnh hơn rồi, mặc thêm quần áo vào."}]},{"hanzi":"愉快","pinyin":"yúkuài","pos":"tt.","vn":"vui vẻ","examples":[{"cn":"祝你周末愉快！","pinyin":"zhù nǐ zhōu mò yú kuài ！","vn":"Chúc bạn cuối tuần vui vẻ!"},{"cn":"我们合作得很愉快。","pinyin":"wǒ men hé zuò dé hěn yú kuài 。","vn":"Chúng tôi hợp tác rất vui vẻ."},{"cn":"这次旅行很愉快。","pinyin":"zhè cì lǚ xíng hěn yú kuài 。","vn":"Chuyến đi lần này rất vui vẻ."}]}],"grammar":[{"title":"可能补语\"动词+得/不+了\"","explanation_vn":"\"得了\" và \"不了\" được đặt sau động từ hoặc chen vào giữa từ ly hợp, tạo thành bổ ngữ khả năng, biểu thị động tác hay kết quả có thể hoàn thành hoặc thực hiện được hay không.","examples":[{"cn":"手机没有信号，上不了网，买不了地铁票了。","pinyin":"Shǒujī méiyǒu xìnhào, shàngbuliǎo wǎng, mǎibuliǎo dìtiěpiào le.","vn":"Điện thoại không có sóng, không vào mạng được, nên không mua được vé tàu điện ngầm."},{"cn":"她刚才给我发信息，说她今天来不了了。","pinyin":"Tā gāngcái gěi wǒ fā xìnxī, shuō tā jīntiān láibuliǎo le.","vn":"Lúc nãy cô ấy nhắn tin cho tôi, nói hôm nay cô ấy không đến được."},{"cn":"明天的足球比赛，你们班男生参加得了吗？","pinyin":"Míngtiān de zúqiú bǐsài, nǐmen bān nánshēng cānjiā deliǎo ma?","vn":"Trận bóng đá ngày mai, các bạn nam lớp bạn tham gia được không?"}]},{"title":"连词\"再说\"","explanation_vn":"Liên từ \"再说\" dùng để nêu ra một lý do hoặc tình huống, sau đó bổ sung thêm một lý do hoặc tình huống khác.","examples":[{"cn":"我提着这些东西就算锻炼身体了，再说邻居之间就是要互相帮助啊。","pinyin":"Wǒ tízhe zhèxiē dōngxi jiù suàn duànliàn shēntǐ le, zàishuō línjū zhījiān jiùshì yào hùxiāng bāngzhù a.","vn":"Tôi xách mấy thứ này coi như tập thể dục rồi, hơn nữa hàng xóm với nhau thì phải giúp đỡ lẫn nhau chứ."},{"cn":"今天太晚了，别去超市了，再说外面还在下雨呢。","pinyin":"Jīntiān tài wǎn le, bié qù chāoshì le, zàishuō wàimiàn hái zài xiàyǔ ne.","vn":"Hôm nay muộn quá rồi, đừng đi siêu thị nữa, với lại bên ngoài vẫn đang mưa đấy."},{"cn":"你就跟我们一起参加活动吧。你今天正好有时间，再说人多也更热闹。","pinyin":"Nǐ jiù gēn wǒmen yìqǐ cānjiā huódòng ba. Nǐ jīntiān zhènghǎo yǒu shíjiān, zàishuō rén duō yě gèng rènao.","vn":"Bạn cứ tham gia hoạt động cùng chúng tôi đi. Hôm nay bạn đúng lúc rảnh, hơn nữa đông người thì càng náo nhiệt."}]},{"title":"并列复句\"既……，又/也……\"","explanation_vn":"\"既……，又/也……\" dùng để liên kết tính từ, động từ hoặc cụm từ, biểu thị việc đồng thời có mấy tính chất hoặc tồn tại mấy tình huống cùng lúc.","examples":[{"cn":"她觉得这样既方便，又能锻炼身体，还能保护环境。","pinyin":"Tā juéde zhèyàng jì fāngbiàn, yòu néng duànliàn shēntǐ, hái néng bǎohù huánjìng.","vn":"Cô ấy thấy như vậy vừa tiện lợi, vừa có thể rèn luyện sức khỏe, lại còn bảo vệ được môi trường."},{"cn":"这家饭馆的菜既好吃，又便宜。","pinyin":"Zhè jiā fànguǎn de cài jì hǎochī, yòu piányi.","vn":"Món ăn ở nhà hàng này vừa ngon, vừa rẻ."},{"cn":"我很喜欢这门课程，既能提高中文水平，也能学到历史知识。","pinyin":"Wǒ hěn xǐhuan zhè mén kèchéng, jì néng tígāo Zhōngwén shuǐpíng, yě néng xuédào lìshǐ zhīshi.","vn":"Tôi rất thích môn học này, vừa có thể nâng cao trình độ tiếng Trung, vừa có thể học được kiến thức lịch sử."}]},{"title":"固定短语\"来得及/来不及\"","explanation_vn":"\"来得及\" biểu thị vẫn còn thời gian, có thể lo liệu hoặc kịp làm; \"来不及\" biểu thị vì thời gian gấp gáp nên không thể lo liệu hoặc không kịp làm.","examples":[{"cn":"没来得及吃早饭的人在这里就能买到热包子和牛奶等。","pinyin":"Méi láidejí chī zǎofàn de rén zài zhèlǐ jiù néng mǎidào rè bāozi hé niúnǎi děng.","vn":"Những người chưa kịp ăn sáng có thể mua bánh bao nóng và sữa, v.v. ở đây."},{"cn":"你现在才告诉我，我来不及通知大家了。","pinyin":"Nǐ xiànzài cái gàosu wǒ, wǒ láibují tōngzhī dàjiā le.","vn":"Bây giờ bạn mới nói cho tôi biết, tôi không kịp thông báo cho mọi người nữa rồi."},{"cn":"中午12点的飞机，咱们9点出发来得及吗？","pinyin":"Zhōngwǔ shí'èr diǎn de fēijī, zánmen jiǔ diǎn chūfā láidejí ma?","vn":"Chuyến bay 12 giờ trưa, chúng ta xuất phát lúc 9 giờ có kịp không?"}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"陈天中","cn":"啊，我的手机停机了！怎么办啊？","pinyin":"Ā, wǒ de shǒujī tíngjī le! Zěnme bàn a?"},{"speaker":"路人","cn":"你好，你看上去很着急，需要帮忙吗？","pinyin":"Nǐ hǎo, nǐ kàn shàngqù hěn zháojí, xūyào bāngmáng ma?"},{"speaker":"陈天中","cn":"我忘了交电话费，手机停机了。我没带现金，手机没有信号，上不了网，买不了地铁票了。","pinyin":"Wǒ wàng le jiāo diànhuàfèi, shǒujī tíngjī le. Wǒ méi dài xiànjīn, shǒujī méiyǒu xìnhào, shàngbuliǎo wǎng, mǎibuliǎo dìtiěpiào le."},{"speaker":"路人","cn":"你要去哪儿？我帮你买张票。","pinyin":"Nǐ yào qù nǎr? Wǒ bāng nǐ mǎi zhāng piào."},{"speaker":"陈天中","cn":"太感谢你了，我要去北京大学站。对了，能不能告诉我你的联系方式？我想把钱还给你。","pinyin":"Tài gǎnxiè nǐ le, wǒ yào qù Běijīng Dàxué Zhàn. Duìle, néng bu néng gàosu wǒ nǐ de liánxì fāngshì? Wǒ xiǎng bǎ qián huán gěi nǐ."},{"speaker":"路人","cn":"别客气，很高兴能帮到你。","pinyin":"Bié kèqi, hěn gāoxìng néng bāngdào nǐ."}],"translation_vn":"Trần Thiên Trung: A, điện thoại của mình bị khóa máy rồi! Phải làm sao đây?\nNgười qua đường: Chào bạn, trông bạn có vẻ rất gấp, cần giúp đỡ không?\nTrần Thiên Trung: Mình quên đóng tiền điện thoại nên bị khóa máy rồi. Mình không mang tiền mặt, điện thoại lại không có sóng, không vào mạng được, không mua được vé tàu điện ngầm nữa.\nNgười qua đường: Bạn định đi đâu? Để mình mua vé giúp bạn.\nTrần Thiên Trung: Cảm ơn bạn nhiều lắm, mình muốn đến ga Đại học Bắc Kinh. Mà này, bạn có thể cho mình biết cách liên lạc với bạn không? Mình muốn trả lại tiền cho bạn.\nNgười qua đường: Đừng khách sáo, rất vui vì đã giúp được bạn.","audio_dialogue":"4-1.mp3","audio_vocab":"4-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"白家月","cn":"阿姨，您怎么站在这儿不上楼？","pinyin":"Āyí, nín zěnme zhàn zài zhèr bú shànglóu?"},{"speaker":"邻居","cn":"我开车去超市买了不少东西，刚拿过来了一些。我先休息一会儿，再去车里拿剩下的。","pinyin":"Wǒ kāichē qù chāoshì mǎi le bùshǎo dōngxi, gāng ná guòlái le yìxiē. Wǒ xiān xiūxi yíhuìr, zài qù chē lǐ ná shèngxià de."},{"speaker":"白家月","cn":"我正好要上楼，我帮您提上去吧。","pinyin":"Wǒ zhènghǎo yào shànglóu, wǒ bāng nín tí shàngqù ba."},{"speaker":"邻居","cn":"不用不用，这几个袋子太重了，我自己拿吧。","pinyin":"Búyòng búyòng, zhè jǐ gè dàizi tài zhòng le, wǒ zìjǐ ná ba."},{"speaker":"白家月","cn":"没事，我提着这些东西就算锻炼身体了，再说邻居之间就是要互相帮助啊。","pinyin":"Méishì, wǒ tízhe zhèxiē dōngxi jiù suàn duànliàn shēntǐ le, zàishuō línjū zhījiān jiùshì yào hùxiāng bāngzhù a."},{"speaker":"邻居","cn":"谢谢家月！那就辛苦你了。","pinyin":"Xièxie Jiāyuè! Nà jiù xīnkǔ nǐ le."}],"translation_vn":"Bạch Gia Nguyệt: Cô ơi, sao cô đứng đây mà không lên nhà vậy ạ?\nHàng xóm: Cô lái xe đi siêu thị mua kha khá đồ, vừa mang một ít lên đây. Cô nghỉ một chút rồi quay lại xe lấy nốt phần còn lại.\nBạch Gia Nguyệt: Cháu đúng lúc cũng định lên nhà, để cháu xách giúp cô lên nhé.\nHàng xóm: Không cần đâu, mấy túi này nặng lắm, để cô tự xách thôi.\nBạch Gia Nguyệt: Không sao đâu cô, cháu xách mấy thứ này coi như tập thể dục rồi, với lại hàng xóm với nhau thì phải giúp đỡ lẫn nhau chứ ạ.\nHàng xóm: Cảm ơn Gia Nguyệt nhé! Vậy thì vất vả cho cháu rồi.","audio_dialogue":"4-3.mp3","audio_vocab":"4-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"在城市里，人们出行的方式越来越多。短距离出行时，骑自行车往往是人们常见的选择。白家月就很喜欢骑车去学校，她觉得这样既方便，又能锻炼身体，还能保护环境。除了骑自行车，人们还会选择骑电动车。电动车速度快，价格不高，充电也很方便，所以越来越流行。陈天中平时也骑自行车，不过为了省力气，他最近打算买一辆电动车。","pinyin":"Zài chéngshì lǐ, rénmen chūxíng de fāngshì yuèláiyuè duō. Duǎn jùlí chūxíng shí, qí zìxíngchē wǎngwǎng shì rénmen chángjiàn de xuǎnzé. Bái Jiāyuè jiù hěn xǐhuan qíchē qù xuéxiào, tā juéde zhèyàng jì fāngbiàn, yòu néng duànliàn shēntǐ, hái néng bǎohù huánjìng. Chúle qí zìxíngchē, rénmen hái huì xuǎnzé qí diàndòngchē. Diàndòngchē sùdù kuài, jiàgé bù gāo, chōngdiàn yě hěn fāngbiàn, suǒyǐ yuèláiyuè liúxíng. Chén Tiānzhōng píngshí yě qí zìxíngchē, búguò wèile shěng lìqi, tā zuìjìn dǎsuàn mǎi yí liàng diàndòngchē."}],"translation_vn":"Trong thành phố, cách thức đi lại của mọi người ngày càng đa dạng. Khi di chuyển quãng đường ngắn, đi xe đạp thường là lựa chọn phổ biến của mọi người. Bạch Gia Nguyệt rất thích đạp xe đến trường, cô ấy cảm thấy như vậy vừa tiện lợi, vừa có thể rèn luyện sức khỏe, lại vừa bảo vệ môi trường. Ngoài đi xe đạp ra, mọi người còn có thể chọn đi xe điện. Xe điện có tốc độ nhanh, giá cả không cao, sạc điện cũng rất tiện, nên ngày càng phổ biến. Trần Thiên Trung bình thường cũng đi xe đạp, nhưng để tiết kiệm sức lực, gần đây anh ấy định mua một chiếc xe điện.","audio_dialogue":"4-5.mp3","audio_vocab":"4-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"在中国，乘客可以在不少地铁站里直接扫码购买食物和饮料，有的地铁站还提供免费借雨伞、发雨衣等服务。有些地铁站附近公司比较多，工作日站里还有早餐车，没来得及吃早饭的人在这里就能买到热包子和牛奶等，省了不少时间。有的地铁站里甚至还有鲜花店，乘客下班时可以顺便买花送给家人。这些小小的服务，不仅方便了人们的出行，也让大家的心情变得更加愉快。","pinyin":"Zài Zhōngguó, chéngkè kěyǐ zài bùshǎo dìtiězhàn lǐ zhíjiē sǎomǎ gòumǎi shíwù hé yǐnliào, yǒude dìtiězhàn hái tígōng miǎnfèi jiè yǔsǎn, fā yǔyī děng fúwù. Yǒuxiē dìtiězhàn fùjìn gōngsī bǐjiào duō, gōngzuòrì zhàn lǐ hái yǒu zǎocānchē, méi láidejí chī zǎofàn de rén zài zhèlǐ jiù néng mǎidào rè bāozi hé niúnǎi děng, shěng le bùshǎo shíjiān. Yǒude dìtiězhàn lǐ shènzhì hái yǒu xiānhuādiàn, chéngkè xiàbān shí kěyǐ shùnbiàn mǎihuā sònggěi jiārén. Zhèxiē xiǎoxiǎo de fúwù, bùjǐn fāngbiàn le rénmen de chūxíng, yě ràng dàjiā de xīnqíng biànde gèngjiā yúkuài."}],"translation_vn":"Ở Trung Quốc, hành khách có thể quét mã trực tiếp để mua đồ ăn và thức uống ngay tại nhiều ga tàu điện ngầm, có ga còn cung cấp dịch vụ cho mượn ô miễn phí, phát áo mưa, v.v. Một số ga tàu điện ngầm gần nơi có nhiều công ty, vào ngày làm việc trong ga còn có xe bán đồ ăn sáng, những người không kịp ăn sáng có thể mua bánh bao nóng và sữa, v.v. ở đây, tiết kiệm được không ít thời gian. Có ga tàu điện ngầm thậm chí còn có cả cửa hàng hoa tươi, hành khách khi tan làm có thể tiện thể mua hoa tặng người thân. Những dịch vụ nhỏ bé này, không những giúp việc đi lại của mọi người thuận tiện hơn, mà còn khiến tâm trạng của mọi người trở nên vui vẻ hơn.","audio_dialogue":"4-7.mp3","audio_vocab":"4-8.mp3"}]},{"id":5,"title_cn":"“不怕辣”和“怕不辣”","title_pinyin":"\"Bú pà là\" hé \"pà bú là\"","title_vn":"“Không sợ cay” và “sợ không cay”","goals":["Có thể nghe hiểu và trao đổi về chủ đề thói quen ăn uống và tụ họp ăn uống.","Có thể diễn đạt bằng lời nói hoặc chữ viết về sở thích ăn uống cá nhân và trải nghiệm dùng bữa.","Hiểu được thói quen ăn uống của người Trung Quốc và lễ nghi sắp xếp chỗ ngồi trong các bữa tiệc chính thức."],"vocab":[{"hanzi":"至少","pinyin":"zhìshǎo","pos":"phó.","vn":"ít nhất","examples":[{"cn":"这件事至少要三天才能做完。","pinyin":"Zhè jiàn shì zhìshǎo yào sān tiān cái néng zuò wán.","vn":"Việc này ít nhất phải ba ngày mới làm xong."},{"cn":"你至少也该打个电话告诉我一声吧。","pinyin":"Nǐ zhìshǎo yě gāi dǎ ge diànhuà gàosu wǒ yì shēng ba.","vn":"Cậu ít nhất cũng nên gọi điện báo cho tôi một tiếng chứ."},{"cn":"我们班至少有一半的人考过了HSK四级。","pinyin":"Wǒmen bān zhìshǎo yǒu yíbàn de rén kǎo guo le HSK sì jí.","vn":"Lớp tôi ít nhất có một nửa người đã thi đỗ HSK cấp 4."}]},{"hanzi":"中餐","pinyin":"zhōngcān","pos":"dt.","vn":"bữa ăn Trung Hoa, món Trung","examples":[{"cn":"你喜欢吃中餐还是西餐？","pinyin":"Nǐ xǐhuan chī zhōngcān háishi xīcān?","vn":"Bạn thích ăn món Trung hay món Tây hơn?"},{"cn":"这家饭店既做中餐也做西餐。","pinyin":"Zhè jiā fàndiàn jì zuò zhōngcān yě zuò xīcān.","vn":"Nhà hàng này vừa làm món Trung vừa làm món Tây."},{"cn":"在国外待久了，特别想吃一顿正宗的中餐。","pinyin":"Zài guówài dāi jiǔ le, tèbié xiǎng chī yí dùn zhèngzōng de zhōngcān.","vn":"Ở nước ngoài lâu rồi, tôi đặc biệt thèm ăn một bữa món Trung chính gốc."}]},{"hanzi":"专门","pinyin":"zhuānmén","pos":"phó./tt.","vn":"chuyên, đặc biệt; chuyên biệt","examples":[{"cn":"他专门为了这件事跑了一趟北京。","pinyin":"Tā zhuānmén wèile zhè jiàn shì pǎo le yí tàng Běijīng.","vn":"Anh ấy chuyên đi một chuyến Bắc Kinh chỉ vì việc này."},{"cn":"这家店是专门卖火锅底料的。","pinyin":"Zhè jiā diàn shì zhuānmén mài huǒguō dǐliào de.","vn":"Cửa hàng này chuyên bán gia vị nồi lẩu."},{"cn":"公司专门请了一位老师教我们商务汉语。","pinyin":"Gōngsī zhuānmén qǐng le yí wèi lǎoshī jiāo wǒmen shāngwù Hànyǔ.","vn":"Công ty mời riêng một thầy giáo dạy chúng tôi tiếng Hán thương mại."}]},{"hanzi":"煮","pinyin":"zhǔ","pos":"dgt.","vn":"nấu, luộc","examples":[{"cn":"水开了，把面条放进去煮五分钟就行。","pinyin":"Shuǐ kāi le, bǎ miàntiáo fàng jìnqù zhǔ wǔ fēnzhōng jiù xíng.","vn":"Nước sôi rồi, cho mì vào luộc năm phút là được."},{"cn":"我妈每天早上都给我煮鸡蛋吃。","pinyin":"Wǒ mā měi tiān zǎoshang dōu gěi wǒ zhǔ jīdàn chī.","vn":"Sáng nào mẹ tôi cũng luộc trứng cho tôi ăn."},{"cn":"这锅汤已经煮了两个小时了，应该很入味了。","pinyin":"Zhè guō tāng yǐjīng zhǔ le liǎng ge xiǎoshí le, yīnggāi hěn rùwèi le.","vn":"Nồi canh này đã nấu được hai tiếng rồi, chắc ngấm gia vị lắm rồi."}]},{"hanzi":"油","pinyin":"yóu","pos":"dt.","vn":"dầu","examples":[{"cn":"这道菜放了太多油，吃起来有点腻。","pinyin":"Zhè dào cài fàng le tài duō yóu, chī qǐlái yǒudiǎn nì.","vn":"Món này cho nhiều dầu quá, ăn hơi ngấy."},{"cn":"锅里的油热了以后再把葱花放进去炒。","pinyin":"Guō lǐ de yóu rè le yǐhòu zài bǎ cōnghuā fàng jìnqù chǎo.","vn":"Đợi dầu trong chảo nóng rồi mới cho hành lá vào xào."},{"cn":"医生让我少吃油，多吃清淡的东西。","pinyin":"Yīshēng ràng wǒ shǎo chī yóu, duō chī qīngdàn de dōngxi.","vn":"Bác sĩ bảo tôi ăn ít dầu mỡ, ăn nhiều đồ thanh đạm hơn."}]},{"hanzi":"道","pinyin":"dào","pos":"lượng.","vn":"(lượng từ chỉ món ăn, công đoạn...)","examples":[{"cn":"今天晚上我们点了十道菜，够吃了吧。","pinyin":"Jīntiān wǎnshang wǒmen diǎn le shí dào cài, gòu chī le ba.","vn":"Tối nay chúng tôi gọi mười món rồi, đủ ăn rồi nhỉ."},{"cn":"这道菜的做法其实挺简单的。","pinyin":"Zhè dào cài de zuòfǎ qíshí tǐng jiǎndān de.","vn":"Cách làm món này thật ra khá đơn giản."},{"cn":"服务员，再给我们上一道汤吧。","pinyin":"Fúwùyuán, zài gěi wǒmen shàng yí dào tāng ba.","vn":"Phục vụ ơi, cho chúng tôi thêm một món canh nữa nhé."}]},{"hanzi":"熟","pinyin":"shú/shóu","pos":"tt.","vn":"chín; quen thuộc","examples":[{"cn":"肉还没熟呢，再煮一会儿吧。","pinyin":"Ròu hái méi shú ne, zài zhǔ yíhuìr ba.","vn":"Thịt chưa chín đâu, nấu thêm một lúc nữa đi."},{"cn":"我们俩认识十几年了，关系很熟。","pinyin":"Wǒmen liǎ rènshi shí jǐ nián le, guānxi hěn shú.","vn":"Hai chúng tôi quen nhau hơn chục năm rồi, quan hệ rất thân."},{"cn":"这条路我走得很熟，闭着眼睛都能走。","pinyin":"Zhè tiáo lù wǒ zǒu de hěn shú, bì zhe yǎnjing dōu néng zǒu.","vn":"Con đường này tôi đi quen lắm rồi, nhắm mắt cũng đi được."}]},{"hanzi":"倒","pinyin":"dào","pos":"dgt.","vn":"đổ, rót","examples":[{"cn":"服务员帮我们把茶倒上了。","pinyin":"Fúwùyuán bāng wǒmen bǎ chá dào shàng le.","vn":"Phục vụ đã rót trà giúp chúng tôi."},{"cn":"小心点，别把汤倒出来了。","pinyin":"Xiǎoxīn diǎn, bié bǎ tāng dào chūlái le.","vn":"Cẩn thận chút, đừng để canh đổ ra ngoài."},{"cn":"你先把油倒进锅里，然后再放菜。","pinyin":"Nǐ xiān bǎ yóu dào jìn guō lǐ, ránhòu zài fàng cài.","vn":"Bạn đổ dầu vào chảo trước, rồi mới cho rau vào."}]},{"hanzi":"辣椒","pinyin":"làjiāo","pos":"dt.","vn":"ớt","examples":[{"cn":"四川菜里放的辣椒特别多。","pinyin":"Sìchuān cài lǐ fàng de làjiāo tèbié duō.","vn":"Món ăn Tứ Xuyên cho rất nhiều ớt."},{"cn":"我不太能吃辣椒，一点点就受不了。","pinyin":"Wǒ bú tài néng chī làjiāo, yìdiǎndiǎn jiù shòu bu liǎo.","vn":"Tôi không ăn ớt được mấy, chỉ một chút là chịu không nổi."},{"cn":"妈妈在阳台上种了几棵辣椒。","pinyin":"Māma zài yángtái shang zhòng le jǐ kē làjiāo.","vn":"Mẹ trồng mấy cây ớt trên ban công."}]},{"hanzi":"辣","pinyin":"là","pos":"tt.","vn":"cay","examples":[{"cn":"这个菜太辣了，我吃不下去。","pinyin":"Zhège cài tài là le, wǒ chī bu xiàqù.","vn":"Món này cay quá, tôi không ăn nổi."},{"cn":"你能吃辣吗？要不要少放点辣椒？","pinyin":"Nǐ néng chī là ma? Yào bu yào shǎo fàng diǎn làjiāo?","vn":"Bạn ăn cay được không? Có cần cho ít ớt lại không?"},{"cn":"湖南人口味一般比较辣。","pinyin":"Húnán rén kǒuwèi yìbān bǐjiào là.","vn":"Người Hồ Nam nói chung khẩu vị khá cay."}]},{"hanzi":"水煮鱼","pinyin":"Shuǐzhǔyú","pos":"danh từ riêng","vn":"Cá om nước kiểu Tứ Xuyên (Thủy chử ngư)","examples":[{"cn":"我们点一份水煮鱼吧，这家店做得特别好吃。","pinyin":"Wǒmen diǎn yí fèn Shuǐzhǔyú ba, zhè jiā diàn zuò de tèbié hǎochī.","vn":"Chúng ta gọi một phần cá om nước kiểu Tứ Xuyên đi, quán này làm ngon lắm."},{"cn":"水煮鱼虽然看着红红的，但其实没有那么辣。","pinyin":"Shuǐzhǔyú suīrán kàn zhe hónghóng de, dàn qíshí méiyǒu nàme là.","vn":"Cá om nước tuy nhìn đỏ rực nhưng thật ra không cay đến thế."},{"cn":"第一次吃水煮鱼的时候，我被辣得直流汗。","pinyin":"Dì yī cì chī Shuǐzhǔyú de shíhou, wǒ bèi là de zhí liú hàn.","vn":"Lần đầu ăn cá om nước, tôi bị cay đến chảy mồ hôi liên tục."}]},{"hanzi":"敢","pinyin":"gǎn","pos":"dgt.","vn":"dám","examples":[{"cn":"我不敢一个人走夜路。","pinyin":"Wǒ bù gǎn yí ge rén zǒu yèlù.","vn":"Tôi không dám đi đường đêm một mình."},{"cn":"你敢不敢吃这么辣的辣椒？","pinyin":"Nǐ gǎn bu gǎn chī zhème là de làjiāo?","vn":"Bạn có dám ăn quả ớt cay thế này không?"},{"cn":"他是我们班最敢说话的人。","pinyin":"Tā shì wǒmen bān zuì gǎn shuōhuà de rén.","vn":"Anh ấy là người dám nói nhất lớp chúng tôi."}]},{"hanzi":"肚子","pinyin":"dùzi","pos":"dt.","vn":"bụng","examples":[{"cn":"我肚子饿了，咱们快点吃饭吧。","pinyin":"Wǒ dùzi è le, zánmen kuài diǎn chīfàn ba.","vn":"Bụng tôi đói rồi, chúng ta ăn cơm nhanh lên đi."},{"cn":"吃坏肚子了，一直跑厕所。","pinyin":"Chī huài dùzi le, yìzhí pǎo cèsuǒ.","vn":"Ăn hỏng bụng rồi, cứ phải chạy toilet suốt."},{"cn":"吃得太饱了，肚子都撑了。","pinyin":"Chī de tài bǎo le, dùzi dōu chēng le.","vn":"Ăn no quá, bụng căng cứng luôn."}]},{"hanzi":"相同","pinyin":"xiāngtóng","pos":"tt.","vn":"giống nhau","examples":[{"cn":"我们俩的想法完全相同。","pinyin":"Wǒmen liǎ de xiǎngfǎ wánquán xiāngtóng.","vn":"Suy nghĩ của hai chúng tôi hoàn toàn giống nhau."},{"cn":"这两件衣服的颜色不太相同。","pinyin":"Zhè liǎng jiàn yīfu de yánsè bú tài xiāngtóng.","vn":"Màu sắc của hai chiếc áo này không hoàn toàn giống nhau."},{"cn":"每个人对这件事的看法都不相同。","pinyin":"Měi ge rén duì zhè jiàn shì de kànfǎ dōu bù xiāngtóng.","vn":"Mỗi người có cách nhìn về việc này đều khác nhau."}]},{"hanzi":"顺序","pinyin":"shùnxù","pos":"dt.","vn":"thứ tự, trình tự","examples":[{"cn":"请大家按顺序排队上车。","pinyin":"Qǐng dàjiā àn shùnxù páiduì shàng chē.","vn":"Mời mọi người xếp hàng theo thứ tự lên xe."},{"cn":"这些照片的顺序乱了，我重新排一下。","pinyin":"Zhèxiē zhàopiàn de shùnxù luàn le, wǒ chóngxīn pái yíxià.","vn":"Thứ tự mấy tấm ảnh này bị lộn rồi, tôi sắp lại một chút."},{"cn":"做菜也有顺序，先放什么后放什么很重要。","pinyin":"Zuò cài yě yǒu shùnxù, xiān fàng shénme hòu fàng shénme hěn zhòngyào.","vn":"Nấu ăn cũng có thứ tự, cho gì trước cho gì sau rất quan trọng."}]},{"hanzi":"够","pinyin":"gòu","pos":"phó./dgt.","vn":"khá, đủ mức; đủ","examples":[{"cn":"这些钱够不够买一台新手机？","pinyin":"Zhèxiē qián gòu bu gòu mǎi yì tái xīn shǒujī?","vn":"Số tiền này có đủ mua một chiếc điện thoại mới không?"},{"cn":"好了好了，够了，别再给我夹菜了。","pinyin":"Hǎo le hǎo le, gòu le, bié zài gěi wǒ jiā cài le.","vn":"Được rồi được rồi, đủ rồi, đừng gắp thêm thức ăn cho tôi nữa."},{"cn":"他已经够努力了，结果还是没考上。","pinyin":"Tā yǐjīng gòu nǔlì le, jiéguǒ háishi méi kǎo shàng.","vn":"Anh ấy đã đủ nỗ lực rồi, nhưng kết quả vẫn không thi đỗ."}]},{"hanzi":"不够","pinyin":"búgòu","pos":"phó./dgt.","vn":"không đủ","examples":[{"cn":"这点钱不够付房租的。","pinyin":"Zhè diǎn qián búgòu fù fángzū de.","vn":"Số tiền này không đủ để trả tiền thuê nhà."},{"cn":"我觉得你对他不够尊重。","pinyin":"Wǒ juéde nǐ duì tā búgòu zūnzhòng.","vn":"Tôi thấy bạn đối với anh ấy không đủ tôn trọng."},{"cn":"时间不够了，我们得快点走了。","pinyin":"Shíjiān búgòu le, wǒmen děi kuài diǎn zǒu le.","vn":"Thời gian không đủ nữa rồi, chúng ta phải đi nhanh thôi."}]},{"hanzi":"达到","pinyin":"dádào","pos":"dgt.","vn":"đạt đến, đạt tới","examples":[{"cn":"他终于达到了自己的目标。","pinyin":"Tā zhōngyú dádào le zìjǐ de mùbiāo.","vn":"Anh ấy cuối cùng đã đạt được mục tiêu của mình."},{"cn":"这次考试的成绩没有达到我的预期。","pinyin":"Zhè cì kǎoshì de chéngjì méiyǒu dádào wǒ de yùqī.","vn":"Kết quả kỳ thi lần này chưa đạt được kỳ vọng của tôi."},{"cn":"气温已经达到了三十五度。","pinyin":"Qìwēn yǐjīng dádào le sānshíwǔ dù.","vn":"Nhiệt độ đã đạt tới ba mươi lăm độ."}]},{"hanzi":"聚","pinyin":"jù","pos":"dgt.","vn":"tụ họp","examples":[{"cn":"周末我们几个老同学聚一聚吧。","pinyin":"Zhōumò wǒmen jǐ ge lǎo tóngxué jù yi jù ba.","vn":"Cuối tuần mấy bạn cũ chúng ta tụ tập lại đi."},{"cn":"放假了，一家人终于能聚在一起了。","pinyin":"Fàngjià le, yì jiā rén zhōngyú néng jù zài yìqǐ le.","vn":"Nghỉ lễ rồi, cả nhà cuối cùng cũng tụ họp được với nhau."},{"cn":"很多人聚在门口，不知道发生了什么事。","pinyin":"Hěn duō rén jù zài ménkǒu, bù zhīdào fāshēng le shénme shì.","vn":"Rất nhiều người tụ tập ở cửa, không biết đã xảy ra chuyện gì."}]},{"hanzi":"午餐","pinyin":"wǔcān","pos":"dt.","vn":"bữa trưa","examples":[{"cn":"我们公司的午餐是免费的。","pinyin":"Wǒmen gōngsī de wǔcān shì miǎnfèi de.","vn":"Bữa trưa ở công ty chúng tôi được miễn phí."},{"cn":"午餐时间到了，我们一起去吃饭吧。","pinyin":"Wǔcān shíjiān dào le, wǒmen yìqǐ qù chīfàn ba.","vn":"Đến giờ ăn trưa rồi, chúng ta cùng đi ăn cơm đi."},{"cn":"今天午餐我随便吃了点面包。","pinyin":"Jīntiān wǔcān wǒ suíbiàn chī le diǎn miànbāo.","vn":"Hôm nay bữa trưa tôi ăn qua loa mấy miếng bánh mì."}]},{"hanzi":"咸","pinyin":"xián","pos":"tt.","vn":"mặn","examples":[{"cn":"这个汤有点咸，加点水吧。","pinyin":"Zhège tāng yǒudiǎn xián, jiā diǎn shuǐ ba.","vn":"Canh này hơi mặn, cho thêm chút nước đi."},{"cn":"我口味比较清淡，不喜欢太咸的菜。","pinyin":"Wǒ kǒuwèi bǐjiào qīngdàn, bù xǐhuan tài xián de cài.","vn":"Khẩu vị tôi khá thanh đạm, không thích món quá mặn."},{"cn":"放盐的时候小心点，别放太咸了。","pinyin":"Fàng yán de shíhou xiǎoxīn diǎn, bié fàng tài xián le.","vn":"Lúc cho muối chú ý một chút, đừng cho mặn quá."}]},{"hanzi":"凉","pinyin":"liáng","pos":"tt.","vn":"nguội, mát; (món) nguội","examples":[{"cn":"饭凉了，我给你热一下吧。","pinyin":"Fàn liáng le, wǒ gěi nǐ rè yíxià ba.","vn":"Cơm nguội rồi, để tôi hâm nóng lại cho bạn nhé."},{"cn":"今天天气有点凉，多穿件衣服吧。","pinyin":"Jīntiān tiānqì yǒudiǎn liáng, duō chuān jiàn yīfu ba.","vn":"Hôm nay trời hơi mát lạnh, mặc thêm áo đi."},{"cn":"夏天我最喜欢吃凉面了。","pinyin":"Xiàtiān wǒ zuì xǐhuan chī liángmiàn le.","vn":"Mùa hè tôi thích nhất ăn mì lạnh."}]},{"hanzi":"酸","pinyin":"suān","pos":"tt.","vn":"chua","examples":[{"cn":"这个水果有点酸，不太甜。","pinyin":"Zhège shuǐguǒ yǒudiǎn suān, bú tài tián.","vn":"Loại trái cây này hơi chua, không ngọt lắm."},{"cn":"我怀孕的时候特别爱吃酸的东西。","pinyin":"Wǒ huáiyùn de shíhou tèbié ài chī suān de dōngxi.","vn":"Lúc mang thai tôi đặc biệt thích ăn đồ chua."},{"cn":"跑完步以后，我的腿有点酸。","pinyin":"Pǎo wán bù yǐhòu, wǒ de tuǐ yǒudiǎn suān.","vn":"Chạy bộ xong, chân tôi hơi mỏi."}]},{"hanzi":"汤","pinyin":"tāng","pos":"dt.","vn":"canh, súp","examples":[{"cn":"妈妈每天都给我们做一锅汤。","pinyin":"Māma měi tiān dōu gěi wǒmen zuò yì guō tāng.","vn":"Mẹ ngày nào cũng nấu một nồi canh cho chúng tôi."},{"cn":"你多喝点汤，暖暖身子。","pinyin":"Nǐ duō hē diǎn tāng, nuǎnnuǎn shēnzi.","vn":"Bạn uống nhiều canh một chút cho ấm người."},{"cn":"这家店的酸汤米线特别有名。","pinyin":"Zhè jiā diàn de suāntāng mǐxiàn tèbié yǒumíng.","vn":"Món bún nước chua của quán này nổi tiếng lắm."}]},{"hanzi":"各","pinyin":"gè","pos":"phó./đt.","vn":"mỗi, từng","examples":[{"cn":"大家各坐各的位置吧。","pinyin":"Dàjiā gè zuò gè de wèizhi ba.","vn":"Mọi người ai ngồi vị trí người nấy nhé."},{"cn":"各地的饮食习惯都不太一样。","pinyin":"Gè dì de yǐnshí xíguàn dōu bú tài yíyàng.","vn":"Thói quen ăn uống ở mỗi nơi đều không giống nhau."},{"cn":"这件事各有各的看法，很难说谁对谁错。","pinyin":"Zhè jiàn shì gè yǒu gè de kànfǎ, hěn nán shuō shéi duì shéi cuò.","vn":"Việc này mỗi người một ý, khó mà nói ai đúng ai sai."}]},{"hanzi":"付","pinyin":"fù","pos":"dgt.","vn":"trả (tiền)","examples":[{"cn":"这顿饭我来付钱吧。","pinyin":"Zhè dùn fàn wǒ lái fù qián ba.","vn":"Bữa này để tôi trả tiền nhé."},{"cn":"你可以用手机付款。","pinyin":"Nǐ kěyǐ yòng shǒujī fùkuǎn.","vn":"Bạn có thể dùng điện thoại để thanh toán."},{"cn":"房租得每个月按时付。","pinyin":"Fángzū děi měi ge yuè ànshí fù.","vn":"Tiền thuê nhà phải trả đúng hạn mỗi tháng."}]},{"hanzi":"聚餐","pinyin":"jùcān","pos":"dgt.","vn":"ăn tụ tập, liên hoan","examples":[{"cn":"今晚公司组织聚餐，大家都要参加。","pinyin":"Jīnwǎn gōngsī zǔzhī jùcān, dàjiā dōu yào cānjiā.","vn":"Tối nay công ty tổ chức liên hoan, mọi người đều phải tham gia."},{"cn":"周末我们班要去聚餐庆祝一下。","pinyin":"Zhōumò wǒmen bān yào qù jùcān qìngzhù yíxià.","vn":"Cuối tuần lớp chúng tôi sẽ đi liên hoan ăn mừng một chút."},{"cn":"好久没和老朋友聚餐了，真想他们。","pinyin":"Hǎojiǔ méi hé lǎo péngyou jùcān le, zhēn xiǎng tāmen.","vn":"Lâu rồi không đi ăn tụ tập với bạn cũ, thật sự nhớ họ."}]},{"hanzi":"辣子鸡","pinyin":"Làzijī","pos":"danh từ riêng","vn":"Gà xào ớt (Lạt tử kê)","examples":[{"cn":"这家馆子的辣子鸡做得特别地道。","pinyin":"Zhè jiā guǎnzi de làzijī zuò de tèbié dìdao.","vn":"Món gà xào ớt của quán này làm rất chuẩn vị."},{"cn":"我第一次吃辣子鸡的时候，被里面的辣椒吓了一跳。","pinyin":"Wǒ dì yī cì chī làzijī de shíhou, bèi lǐmiàn de làjiāo xià le yí tiào.","vn":"Lần đầu tiên ăn gà xào ớt, tôi bị đống ớt trong đó làm giật mình."},{"cn":"来重庆一定要尝尝正宗的辣子鸡。","pinyin":"Lái Chóngqìng yídìng yào chángchang zhèngzōng de làzijī.","vn":"Đến Trùng Khánh nhất định phải thử món gà xào ớt chính gốc."}]},{"hanzi":"松鼠鼟鱼","pinyin":"Sōngshǔ Guìyú","pos":"danh từ riêng","vn":"Cá quế hình sóc (Tùng thử quế ngư)","examples":[{"cn":"松鼠鼟鱼的样子看起来真的很像一只小松鼠。","pinyin":"Sōngshǔ Guìyú de yàngzi kàn qǐlái zhēnde hěn xiàng yì zhī xiǎo sōngshǔ.","vn":"Món cá quế hình sóc trông thật sự rất giống một chú sóc nhỏ."},{"cn":"这家饭店的松鼠鼟鱼味道又酸又甜，很好吃。","pinyin":"Zhè jiā fàndiàn de Sōngshǔ Guìyú wèidao yòu suān yòu tián, hěn hǎochī.","vn":"Món cá quế hình sóc của nhà hàng này vị vừa chua vừa ngọt, rất ngon."},{"cn":"朋友过生日，我们特意点了一道松鼠鼟鱼。","pinyin":"Péngyou guò shēngrì, wǒmen tèyì diǎn le yí dào Sōngshǔ Guìyú.","vn":"Bạn tôi sinh nhật, chúng tôi cố tình gọi riêng một món cá quế hình sóc."}]},{"hanzi":"红烧羊肉","pinyin":"Hóngshāo Yángròu","pos":"danh từ riêng","vn":"Thịt cừu kho đỏ","examples":[{"cn":"冬天吃一碗红烧羊肉，浑身都暖和了。","pinyin":"Dōngtiān chī yì wǎn Hóngshāo Yángròu, húnshēn dōu nuǎnhuo le.","vn":"Mùa đông ăn một bát thịt cừu kho đỏ là cả người ấm hẳn lên."},{"cn":"我妈做的红烧羊肉一点都不腥。","pinyin":"Wǒ mā zuò de Hóngshāo Yángròu yìdiǎn dōu bù xīng.","vn":"Thịt cừu kho đỏ mẹ tôi làm chẳng có mùi gây chút nào."},{"cn":"今天餐厅的特色菜是红烧羊肉。","pinyin":"Jīntiān cāntīng de tèsè cài shì Hóngshāo Yángròu.","vn":"Món đặc sản của nhà hàng hôm nay là thịt cừu kho đỏ."}]},{"hanzi":"贵州","pinyin":"Guìzhōu","pos":"danh từ riêng","vn":"tỉnh Quý Châu","examples":[{"cn":"贵州的风景非常美，很多人都喜欢去那儿旅游。","pinyin":"Guìzhōu de fēngjǐng fēicháng měi, hěn duō rén dōu xǐhuan qù nàr lǚyóu.","vn":"Phong cảnh Quý Châu rất đẹp, nhiều người thích đến đó du lịch."},{"cn":"他是贵州人，口味偏酸辣。","pinyin":"Tā shì Guìzhōu rén, kǒuwèi piān suān là.","vn":"Anh ấy là người Quý Châu, khẩu vị thiên về chua cay."},{"cn":"这次出差，我要去贵州待一个星期。","pinyin":"Zhè cì chūchāi, wǒ yào qù Guìzhōu dāi yí ge xīngqī.","vn":"Chuyến công tác này tôi sẽ ở Quý Châu một tuần."}]},{"hanzi":"酸汤米线","pinyin":"Suāntāng Mǐxiàn","pos":"danh từ riêng","vn":"Bún nước chua","examples":[{"cn":"贵州的酸汤米线闻起来很香，味道又酸又开胃。","pinyin":"Guìzhōu de suāntāng mǐxiàn wén qǐlái hěn xiāng, wèidao yòu suān yòu kāiwèi.","vn":"Bún nước chua Quý Châu ngửi rất thơm, vị vừa chua vừa kích thích vị giác."},{"cn":"我中午点了一碗酸汤米线当午餐。","pinyin":"Wǒ zhōngwǔ diǎn le yì wǎn suāntāng mǐxiàn dāng wǔcān.","vn":"Trưa nay tôi gọi một bát bún nước chua làm bữa trưa."},{"cn":"天冷的时候来一碗热乎乎的酸汤米线最舒服了。","pinyin":"Tiān lěng de shíhou lái yì wǎn rèhūhū de suāntāng mǐxiàn zuì shūfu le.","vn":"Trời lạnh mà ăn một bát bún nước chua nóng hổi thì sướng nhất."}]},{"hanzi":"随意","pinyin":"suíyì","pos":"tt.","vn":"tùy ý, thoải mái","examples":[{"cn":"大家随意坐，不用客气。","pinyin":"Dàjiā suíyì zuò, búyòng kèqi.","vn":"Mọi người cứ ngồi tùy ý, không cần khách sáo."},{"cn":"这顿饭不用太正式，随意吃点就行。","pinyin":"Zhè dùn fàn búyòng tài zhèngshì, suíyì chī diǎn jiù xíng.","vn":"Bữa này không cần quá trang trọng, ăn tùy ý một chút là được."},{"cn":"他做事一向很随意，从来不喜欢计划。","pinyin":"Tā zuòshì yíxiàng hěn suíyì, cónglái bù xǐhuan jìhuà.","vn":"Anh ấy làm việc luôn rất tùy hứng, chưa bao giờ thích lập kế hoạch."}]},{"hanzi":"正式","pinyin":"zhèngshì","pos":"tt.","vn":"chính thức","examples":[{"cn":"我们公司下个月才正式开业。","pinyin":"Wǒmen gōngsī xià ge yuè cái zhèngshì kāiyè.","vn":"Công ty chúng tôi tháng sau mới chính thức khai trương."},{"cn":"这是正式的邀请函，请大家按时出席。","pinyin":"Zhè shì zhèngshì de yāoqǐng hán, qǐng dàjiā ànshí chūxí.","vn":"Đây là thư mời chính thức, mời mọi người đến đúng giờ."},{"cn":"他今天穿得特别正式，是不是要去面试？","pinyin":"Tā jīntiān chuān de tèbié zhèngshì, shì bu shì yào qù miànshì?","vn":"Hôm nay anh ấy ăn mặc rất chỉnh tề, có phải sắp đi phỏng vấn không?"}]},{"hanzi":"普通","pinyin":"pǔtōng","pos":"tt.","vn":"bình thường, phổ thông","examples":[{"cn":"我只是一个普通的上班族。","pinyin":"Wǒ zhǐshì yí ge pǔtōng de shàngbānzú.","vn":"Tôi chỉ là một dân văn phòng bình thường."},{"cn":"这家饭店装修得很普通，但菜做得特别好吃。","pinyin":"Zhè jiā fàndiàn zhuāngxiū de hěn pǔtōng, dàn cài zuò de tèbié hǎochī.","vn":"Nhà hàng này trang trí rất bình thường nhưng món ăn nấu cực ngon."},{"cn":"这件事其实很普通，没什么好大惊小怪的。","pinyin":"Zhè jiàn shì qíshí hěn pǔtōng, méi shénme hǎo dàjīngxiǎoguài de.","vn":"Việc này thật ra rất bình thường, chẳng có gì phải ầm ĩ cả."}]},{"hanzi":"重视","pinyin":"zhòngshì","pos":"dgt.","vn":"coi trọng","examples":[{"cn":"这家公司非常重视员工的意见。","pinyin":"Zhè jiā gōngsī fēicháng zhòngshì yuángōng de yìjiàn.","vn":"Công ty này rất coi trọng ý kiến của nhân viên."},{"cn":"中国人吃饭时很重视座位的安排。","pinyin":"Zhōngguó rén chīfàn shí hěn zhòngshì zuòwèi de ānpái.","vn":"Người Trung Quốc khi ăn cơm rất coi trọng việc sắp xếp chỗ ngồi."},{"cn":"父母应该重视孩子的心理健康。","pinyin":"Fùmǔ yīnggāi zhòngshì háizi de xīnlǐ jiànkāng.","vn":"Bố mẹ nên coi trọng sức khỏe tâm lý của con cái."}]},{"hanzi":"座位","pinyin":"zuòwèi","pos":"dt.","vn":"chỗ ngồi","examples":[{"cn":"请问，这个座位有人坐吗？","pinyin":"Qǐngwèn, zhège zuòwèi yǒu rén zuò ma?","vn":"Xin hỏi, chỗ ngồi này có ai ngồi chưa ạ?"},{"cn":"服务员帮我们安排了一个靠窗的座位。","pinyin":"Fúwùyuán bāng wǒmen ānpái le yí ge kào chuāng de zuòwèi.","vn":"Phục vụ đã sắp xếp cho chúng tôi một chỗ ngồi cạnh cửa sổ."},{"cn":"电影院里的座位都是按号对号入座的。","pinyin":"Diànyǐngyuàn lǐ de zuòwèi dōu shì àn hào duìhào rùzuò de.","vn":"Chỗ ngồi trong rạp chiếu phim đều ngồi đúng theo số ghế."}]},{"hanzi":"安排","pinyin":"ānpái","pos":"dgt.","vn":"sắp xếp","examples":[{"cn":"这次旅行你帮我安排一下行程吧。","pinyin":"Zhè cì lǚxíng nǐ bāng wǒ ānpái yíxià xíngchéng ba.","vn":"Chuyến đi lần này bạn giúp tôi sắp xếp lịch trình một chút nhé."},{"cn":"老板把这个项目安排给了我。","pinyin":"Lǎobǎn bǎ zhège xiàngmù ānpái gěi le wǒ.","vn":"Sếp đã giao dự án này cho tôi."},{"cn":"我最近工作太忙，什么都没时间安排。","pinyin":"Wǒ zuìjìn gōngzuò tài máng, shénme dōu méi shíjiān ānpái.","vn":"Dạo này tôi làm việc bận quá, chẳng có thời gian sắp xếp gì cả."}]},{"hanzi":"按照","pinyin":"ànzhào","pos":"giới.","vn":"theo, dựa theo","examples":[{"cn":"请按照说明书上的步骤操作。","pinyin":"Qǐng ànzhào shuōmíngshū shang de bùzhòu cāozuò.","vn":"Hãy thao tác theo đúng các bước trong sách hướng dẫn."},{"cn":"我们应该按照年龄大小来安排座位。","pinyin":"Wǒmen yīnggāi ànzhào niánlíng dàxiǎo lái ānpái zuòwèi.","vn":"Chúng ta nên sắp xếp chỗ ngồi theo thứ tự tuổi tác."},{"cn":"一切都按照计划进行，没出什么问题。","pinyin":"Yíqiè dōu ànzhào jìhuà jìnxíng, méi chū shénme wèntí.","vn":"Mọi việc đều diễn ra theo đúng kế hoạch, không có vấn đề gì."}]},{"hanzi":"年龄","pinyin":"niánlíng","pos":"dt.","vn":"tuổi tác","examples":[{"cn":"请问您的年龄是多少？","pinyin":"Qǐngwèn nín de niánlíng shì duōshao?","vn":"Xin hỏi anh/chị bao nhiêu tuổi ạ?"},{"cn":"这份工作对年龄没有要求。","pinyin":"Zhè fèn gōngzuò duì niánlíng méiyǒu yāoqiú.","vn":"Công việc này không yêu cầu về tuổi tác."},{"cn":"随着年龄的增长，他越来越稳重了。","pinyin":"Suízhe niánlíng de zēngzhǎng, tā yuè lái yuè wěnzhòng le.","vn":"Cùng với tuổi tác tăng lên, anh ấy ngày càng chín chắn hơn."}]},{"hanzi":"面对","pinyin":"miànduì","pos":"dgt.","vn":"đối diện","examples":[{"cn":"我们应该勇敢地面对困难。","pinyin":"Wǒmen yīnggāi yǒnggǎn de miànduì kùnnan.","vn":"Chúng ta nên dũng cảm đối diện với khó khăn."},{"cn":"面对老师的提问，他一时不知道怎么回答。","pinyin":"Miànduì lǎoshī de tíwèn, tā yìshí bù zhīdào zěnme huídá.","vn":"Đối diện với câu hỏi của thầy giáo, cậu ấy nhất thời không biết trả lời thế nào."},{"cn":"吃饭的时候，长辈一般坐在面对门口的位置。","pinyin":"Chīfàn de shíhou, zhǎngbèi yìbān zuò zài miànduì ménkǒu de wèizhi.","vn":"Khi ăn cơm, người lớn tuổi thường ngồi ở vị trí hướng mặt ra cửa."}]},{"hanzi":"主人","pinyin":"zhǔrén","pos":"dt.","vn":"chủ nhà","examples":[{"cn":"作为主人，他对每位客人都照顾得很周到。","pinyin":"Zuòwéi zhǔrén, tā duì měi wèi kèrén dōu zhàogu de hěn zhōudào.","vn":"Là chủ nhà, anh ấy chăm sóc từng vị khách rất chu đáo."},{"cn":"客人到了，主人赶紧出来迎接。","pinyin":"Kèrén dào le, zhǔrén gǎnjǐn chūlái yíngjiē.","vn":"Khách đến rồi, chủ nhà vội vàng ra đón."},{"cn":"这只狗很听主人的话。","pinyin":"Zhè zhī gǒu hěn tīng zhǔrén de huà.","vn":"Con chó này rất nghe lời chủ của nó."}]},{"hanzi":"等","pinyin":"děng","pos":"giới.","vn":"đợi đến, chờ đến","examples":[{"cn":"等老板来了，我们再开始开会吧。","pinyin":"Děng lǎobǎn lái le, wǒmen zài kāishǐ kāihuì ba.","vn":"Đợi sếp đến rồi chúng ta mới bắt đầu họp."},{"cn":"我们一直等到晚上十点，他才到。","pinyin":"Wǒmen yìzhí děng dào wǎnshang shí diǎn, tā cái dào.","vn":"Chúng tôi đợi mãi đến mười giờ tối, anh ấy mới đến."},{"cn":"等菜都上齐了，大家才动筷子。","pinyin":"Děng cài dōu shàng qí le, dàjiā cái dòng kuàizi.","vn":"Đợi món ăn được bày đủ hết, mọi người mới bắt đầu cầm đũa."}]},{"hanzi":"尊重","pinyin":"zūnzhòng","pos":"dgt.","vn":"tôn trọng","examples":[{"cn":"我们应该尊重每一位长辈。","pinyin":"Wǒmen yīnggāi zūnzhòng měi yí wèi zhǎngbèi.","vn":"Chúng ta nên tôn trọng mỗi vị trưởng bối."},{"cn":"无论做什么决定，都要尊重孩子自己的意见。","pinyin":"Wúlùn zuò shénme juédìng, dōu yào zūnzhòng háizi zìjǐ de yìjiàn.","vn":"Dù đưa ra quyết định gì cũng phải tôn trọng ý kiến riêng của con cái."},{"cn":"他虽然是老板，但对员工一直很尊重。","pinyin":"Tā suīrán shì lǎobǎn, dàn duì yuángōng yìzhí hěn zūnzhòng.","vn":"Tuy là sếp nhưng anh ấy luôn tôn trọng nhân viên."}]}],"grammar":[{"title":"范围副词“至少” Phó từ chỉ phạm vi “至少”","explanation_vn":"Phó từ chỉ phạm vi \"至少\" biểu thị thời gian, số lượng, mức độ... không thấp hơn một giới hạn tối thiểu nào đó.","examples":[{"cn":"家月，你来中国至少两个月了，习惯吃中餐了吗？","pinyin":"Jiāyuè, nǐ lái Zhōngguó zhìshǎo liǎng gè yuè le, xíguàn chī Zhōngcān le ma?","vn":"Gia Nguyệt, em đến Trung Quốc ít nhất đã hai tháng rồi, đã quen ăn món Trung chưa?"},{"cn":"每年至少有两百名留学生来我校学习中文专业。","pinyin":"Měi nián zhìshǎo yǒu liǎngbǎi míng liúxuéshēng lái wǒ xiào xuéxí Zhōngwén zhuānyè.","vn":"Mỗi năm có ít nhất hai trăm du học sinh đến trường chúng tôi học chuyên ngành tiếng Trung."},{"cn":"我们虽然没有见过面，但至少在网上聊过很多次，也算比较熟悉了。","pinyin":"Wǒmen suīrán méiyǒu jiànguo miàn, dàn zhìshǎo zài wǎngshang liáoguo hěn duō cì, yě suàn bǐjiào shúxī le.","vn":"Tuy chúng tôi chưa gặp mặt nhau, nhưng ít nhất cũng đã trò chuyện trên mạng nhiều lần, cũng coi như khá quen biết rồi."}]},{"title":"副词/动词“够” Phó từ/Động từ “够”","explanation_vn":"\"够\" có hai từ loại: (1) phó từ, biểu thị mức độ cao, thường dùng trong cấu trúc cố định \"够……的\"; (2) động từ, biểu thị về số lượng đáp ứng đủ nhu cầu hoặc đạt đến một tiêu chuẩn, mức độ nào đó.","examples":[{"cn":"你的中文水平够高的，这都听懂了！","pinyin":"Nǐ de Zhōngwén shuǐpíng gòu gāo de, zhè dōu tīngdǒng le!","vn":"Trình độ tiếng Trung của bạn khá cao đấy, cái này cũng nghe hiểu được!"},{"cn":"明天请家月和李文来家里吃饭，四个菜够不够？","pinyin":"Míngtiān qǐng Jiāyuè hé Lǐ Wén lái jiālǐ chīfàn, sì gè cài gòu bú gòu?","vn":"Ngày mai mời Gia Nguyệt và Lý Văn đến nhà ăn cơm, bốn món có đủ không?"},{"cn":"我尝了一下，还不够甸，再加一点儿糖吧。","pinyin":"Wǒ cháng le yíxià, hái búgòu tián, zài jiā yìdiǎnr táng ba.","vn":"Tôi nếm thử rồi, vẫn chưa đủ ngọt, cho thêm chút đường nữa đi."}]},{"title":"固定格式“各×各的” Cấu trúc cố định “各×各的”","explanation_vn":"Cấu trúc cố định \"各×各的\" biểu thị mỗi người độc lập thực hiện cùng một loại hành động, không ảnh hưởng lẫn nhau.","examples":[{"cn":"大家觉得还是各付各的更合适。","pinyin":"Dàjiā juéde háishi gè fù gè de gèng héshì.","vn":"Mọi người cảm thấy ai trả tiền của người đó thì hợp lý hơn."},{"cn":"到了办公室，大家就开始各忙各的了。","pinyin":"Dàole bàngōngshì, dàjiā jiù kāishǐ gè máng gè de le.","vn":"Đến văn phòng, mọi người liền bắt đầu ai làm việc của người nấy."},{"cn":"在图书馆里，大家都很安静，各看各的书。","pinyin":"Zài túshūguǎn lǐ, dàjiā dōu hěn ānjìng, gè kàn gè de shū.","vn":"Trong thư viện, mọi người đều rất yên lặng, ai đọc sách của người nấy."}]},{"title":"介词“等” Giới từ “等”","explanation_vn":"Trong bài này, \"等\" là giới từ, biểu thị \"đợi đến\", dùng để dẫn ra thời gian, điều kiện.","examples":[{"cn":"如果聚餐时有老人，年轻人要等老人坐下后再坐。","pinyin":"Rúguǒ jùcān shí yǒu lǎorén, niánqīngrén yào děng lǎorén zuòxià hòu zài zuò.","vn":"Nếu trong bữa tiệc có người lớn tuổi, người trẻ phải đợi người lớn tuổi ngồi xuống rồi mới ngồi."},{"cn":"等我写完作业，再跟你出去玩。","pinyin":"Děng wǒ xiěwán zuòyè, zài gēn nǐ chūqù wán.","vn":"Đợi tôi làm xong bài tập rồi sẽ ra ngoài chơi với bạn."},{"cn":"等我们到火车站的时候，火车已经开走了。","pinyin":"Děng wǒmen dào huǒchēzhàn de shíhou, huǒchē yǐjīng kāizǒu le.","vn":"Đợi đến khi chúng tôi tới ga tàu thì tàu đã chạy mất rồi."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"刘明","cn":"家月，你来中国至少两个月了，习惯吃中餐了吗？","pinyin":"Jiāyuè, nǐ lái Zhōngguó zhìshǎo liǎng gè yuè le, xíguàn chī Zhōngcān le ma?"},{"speaker":"白家月","cn":"习惯了，而且我很喜欢吃中国菜。","pinyin":"Xíguàn le, érqiě wǒ hěn xǐhuan chī Zhōngguócài."},{"speaker":"王一雪","cn":"你还没吃过水煮鱼吧？这是我专门为你做的。","pinyin":"Nǐ hái méi chīguo Shuǐzhǔyú ba? Zhè shì wǒ zhuānmén wèi nǐ zuò de."},{"speaker":"白家月","cn":"看起来不像水煮鱼，更像“油煮鱼”。","pinyin":"Kàn qǐlái bú xiàng Shuǐzhǔyú, gèng xiàng \"yóuzhǔyú\"."},{"speaker":"王一雪","cn":"这道菜是先用水把鱼煮熟，最后再倒上辣椒油，其实只有最上面那一层是油。你尝尝，对你来说辣不辣？","pinyin":"Zhè dào cài shì xiān yòng shuǐ bǎ yú zhǔshú, zuìhòu zài dàoshàng làjiāoyóu, qíshí zhǐyǒu zuì shàngmian nà yì céng shì yóu. Nǐ chángchang, duì nǐ láishuō là bú là?"},{"speaker":"白家月","cn":"辣是辣，但是非常好吃！","pinyin":"Là shì là, dànshì fēicháng hǎochī!"},{"speaker":"王一雪","cn":"那你多吃点儿，不要客气。","pinyin":"Nà nǐ duō chī diǎnr, búyào kèqi."}],"translation_vn":"Lưu Minh: Gia Nguyệt, em đến Trung Quốc ít nhất đã hai tháng rồi, đã quen ăn món Trung chưa?\nBạch Gia Nguyệt: Quen rồi ạ, với lại em rất thích ăn món Trung Quốc.\nVương Nhất Tuyết: Em chưa ăn cá om kiểu Tứ Xuyên bao giờ đúng không? Đây là món chị làm riêng cho em đấy.\nBạch Gia Nguyệt: Trông không giống cá om nước, mà giống “cá om dầu” hơn.\nVương Nhất Tuyết: Món này là luộc chín cá bằng nước trước, cuối cùng mới đổ dầu ớt lên trên, thực ra chỉ có lớp trên cùng là dầu thôi. Em nếm thử xem, với em thì có cay không?\nBạch Gia Nguyệt: Cay thì cay thật, nhưng rất ngon!\nVương Nhất Tuyết: Vậy em ăn nhiều một chút, đừng khách sáo.","audio_dialogue":"5-1.mp3","audio_vocab":"5-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"我听李文说，你现在也爱吃辣了？","pinyin":"Wǒ tīng Lǐ Wén shuō, nǐ xiànzài yě ài chī là le?"},{"speaker":"白家月","cn":"是的，来中国以后，我越来越喜欢吃辣了。","pinyin":"Shì de, lái Zhōngguó yǐhòu, wǒ yuèláiyuè xǐhuan chī là le."},{"speaker":"王一雪","cn":"我们以前不太敢吃辣，吃完可能会肚子不舒服，不过现在也慢慢适应了。","pinyin":"Wǒmen yǐqián bú tài gǎn chī là, chīwán kěnéng huì dùzi bù shūfu, búguò xiànzài yě mànmàn shìyìng le."},{"speaker":"刘明","cn":"对，我们现在都不怕辣了。家月，你是“不怕辣”还是“怕不辣”？","pinyin":"Duì, wǒmen xiànzài dōu bú pà là le. Jiāyuè, nǐ shì \"bú pà là\" háishi \"pà bú là\"?"},{"speaker":"白家月","cn":"中文真有意思，相同的字，顺序一换，意思就变了。","pinyin":"Zhōngwén zhēn yǒu yìsi, xiāngtóng de zì, shùnxù yí huàn, yìsi jiù biàn le."},{"speaker":"李文","cn":"你的中文水平够高的，这都听懂了！你说得对，“不怕辣”是说不怕吃辣的菜，“怕不辣”是担心菜还不够辣呢。","pinyin":"Nǐ de Zhōngwén shuǐpíng gòu gāo de, zhè dōu tīngdǒng le! Nǐ shuō de duì, \"bú pà là\" shì shuō bú pà chī là de cài, \"pà bú là\" shì dānxīn cài hái búgòu là ne."},{"speaker":"白家月","cn":"我还达不到“怕不辣”的水平，甚至也不能算“不怕辣”，只是喜欢吃辣。","pinyin":"Wǒ hái dábúdào \"pà bú là\" de shuǐpíng, shènzhì yě bù néng suàn \"bú pà là\", zhǐshì xǐhuan chī là."}],"translation_vn":"Vương Nhất Tuyết: Chị nghe Lý Văn nói, bây giờ em cũng thích ăn cay rồi à?\nBạch Gia Nguyệt: Vâng, sau khi đến Trung Quốc, em ngày càng thích ăn cay hơn.\nVương Nhất Tuyết: Trước đây bọn chị không dám ăn cay lắm, ăn xong có thể bị đau bụng, nhưng giờ cũng dần thích nghi rồi.\nLưu Minh: Đúng vậy, giờ bọn anh đều không sợ cay nữa. Gia Nguyệt, em là kiểu “không sợ cay” hay “sợ không cay”?\nBạch Gia Nguyệt: Tiếng Trung thật thú vị, cùng những chữ đó, chỉ đổi thứ tự là ý nghĩa đã thay đổi rồi.\nLý Văn: Trình độ tiếng Trung của em khá cao đấy, cái này cũng nghe hiểu được! Em nói đúng, “không sợ cay” là nói không sợ ăn món cay, “sợ không cay” là lo món chưa đủ cay đấy.\nBạch Gia Nguyệt: Em còn chưa đạt đến trình độ “sợ không cay”, thậm chí cũng không tính là “không sợ cay”, chỉ là thích ăn cay thôi.","audio_dialogue":"5-3.mp3","audio_vocab":"5-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"周末，白家月、陈天中、李文和安妮聚在一起吃午餐。白家月想吃辣的，要了辣子鸡；陈天中爱吃甸的，想尝尝松鼠鼟鱼；李文更喜欢吃咸的，选了红烧羊肉和一道凉菜；安妮听说贵州酸汤很有名，点了酸汤米线。他们边吃边聊，非常愉快。","pinyin":"Zhōumò, Bái Jiāyuè, Chén Tiānzhōng, Lǐ Wén hé Ānnī jù zài yìqǐ chī wǔcān. Bái Jiāyuè xiǎng chī là de, yào le Làzijī; Chén Tiānzhōng ài chī tián de, xiǎng chángchang Sōngshǔ Guìyú; Lǐ Wén gèng xǐhuan chī xián de, xuǎn le Hóngshāo Yángròu hé yí dào liángcài; Ānnī tīngshuō Guìzhōu suāntāng hěn yǒumíng, diǎn le Suāntāng Mǐxiàn. Tāmen biān chī biān liáo, fēicháng yúkuài."},{"speaker":"","cn":"结账时，李文想请客，但大家觉得还是各付各的更合适。于是，李文付完钱后，大家把钱转给了他，还笑着说下次再一起聚餐。","pinyin":"Jiézhàng shí, Lǐ Wén xiǎng qǐngkè, dàn dàjiā juéde háishi gè fù gè de gèng héshì. Yúshì, Lǐ Wén fùwán qián hòu, dàjiā bǎ qián zhuǎngěi le tā, hái xiàozhe shuō xià cì zài yìqǐ jùcān."}],"translation_vn":"Cuối tuần, Bạch Gia Nguyệt, Trần Thiên Trung, Lý Văn và Annie tụ họp cùng nhau ăn trưa. Bạch Gia Nguyệt muốn ăn cay nên gọi món gà xào ớt; Trần Thiên Trung thích ăn ngọt, muốn nếm thử cá quế hình sóc; Lý Văn lại thích ăn mặn hơn, chọn thịt cừu kho đỏ và một món nguội; Annie nghe nói canh chua Quý Châu rất nổi tiếng nên gọi bún nước chua. Họ vừa ăn vừa trò chuyện, rất vui vẻ.\nKhi thanh toán, Lý Văn muốn mời cả nhóm, nhưng mọi người cảm thấy ai trả tiền của người đó thì hợp lý hơn. Thế là, sau khi Lý Văn trả tiền xong, mọi người chuyển tiền lại cho anh, còn cười nói lần sau lại cùng nhau tụ họp ăn uống.","audio_dialogue":"5-5.mp3","audio_vocab":"5-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"今天吃饭的时候，大家坐得比较随意。李文告诉白家月，在中国，正式聚餐和普通聚餐不同，正式聚餐时人们比较重视座位的安排，比如可以按照年龄大小来安排，年龄比较大的客人往往会坐在中间或者面对门口的座位。大家坐下时，主人会请客人先坐。如果聚餐时有老人，年轻人要等老人坐下后再坐。","pinyin":"Jīntiān chīfàn de shíhou, dàjiā zuò de bǐjiào suíyì. Lǐ Wén gàosu Bái Jiāyuè, zài Zhōngguó, zhèngshì jùcān hé pǔtōng jùcān bùtóng, zhèngshì jùcān shí rénmen bǐjiào zhòngshì zuòwèi de ānpái, bǐrú kěyǐ ànzhào niánlíng dàxiǎo lái ānpái, niánlíng bǐjiào dà de kèrén wǎngwǎng huì zuò zài zhōngjiān huòzhě miànduì ménkǒu de zuòwèi. Dàjiā zuòxià shí, zhǔrén huì qǐng kèrén xiān zuò. Rúguǒ jùcān shí yǒu lǎorén, niánqīngrén yào děng lǎorén zuòxià hòu zài zuò."},{"speaker":"","cn":"白家月听后觉得很有意思，她认为这么做是照顾客人、尊重老人的表现。","pinyin":"Bái Jiāyuè tīng hòu juéde hěn yǒu yìsi, tā rènwéi zhème zuò shì zhàogù kèrén, zūnzhòng lǎorén de biǎoxiàn."}],"translation_vn":"Hôm nay lúc ăn cơm, mọi người ngồi khá tùy ý. Lý Văn nói với Bạch Gia Nguyệt rằng ở Trung Quốc, tụ họp ăn uống chính thức khác với tụ họp thông thường, khi tụ họp chính thức người ta khá coi trọng việc sắp xếp chỗ ngồi, chẳng hạn có thể sắp xếp theo tuổi tác, những vị khách lớn tuổi hơn thường sẽ ngồi ở giữa hoặc chỗ ngồi đối diện cửa ra vào. Khi mọi người ngồi xuống, chủ nhà sẽ mời khách ngồi trước. Nếu trong bữa tiệc có người lớn tuổi, người trẻ phải đợi người lớn tuổi ngồi xuống rồi mới ngồi.\nBạch Gia Nguyệt nghe xong cảm thấy rất thú vị, cô cho rằng làm như vậy là biểu hiện của việc quan tâm khách và tôn trọng người lớn tuổi.","audio_dialogue":"5-7.mp3","audio_vocab":"5-8.mp3"}]},{"id":6,"title_cn":"我陪你去看病","title_pinyin":"Wǒ péi nǐ qù kànbìng","title_vn":"Tôi đưa bạn đi khám bệnh","goals":["Có thể nghe hiểu và trao đổi các thông tin như tình trạng sức khỏe và phương án điều trị.","Có thể diễn đạt bằng lời nói hoặc chữ viết về quá trình đi khám bệnh.","Hiểu được quy trình cơ bản khi đi khám bệnh ở Trung Quốc."],"vocab":[{"hanzi":"咳嗽","pinyin":"késou","pos":"dgt.","vn":"ho","examples":[{"cn":"我最近老咳嗽，也不知道是不是感冒了。","pinyin":"Wǒ zuìjìn lǎo késou, yě bù zhīdào shì bu shì gǎnmào le.","vn":"Dạo này tôi cứ ho mãi, không biết có phải bị cảm không."},{"cn":"孩子咳嗽得厉害，我们赶紧带他去医院了。","pinyin":"Háizi késou de lìhai, wǒmen gǎnjǐn dài tā qù yīyuàn le.","vn":"Đứa bé ho dữ dội quá, chúng tôi vội đưa cháu đi bệnh viện."},{"cn":"多喝点热水，对咳嗽有好处。","pinyin":"Duō hē diǎn rè shuǐ, duì késou yǒu hǎochu.","vn":"Uống nhiều nước ấm sẽ có lợi cho việc ho."}]},{"hanzi":"咳","pinyin":"ké","pos":"dgt.","vn":"ho","examples":[{"cn":"他咳了两声，清了清嗓子。","pinyin":"Tā ké le liǎng shēng, qīng le qīng sǎngzi.","vn":"Anh ấy ho hai tiếng, hắng giọng một chút."},{"cn":"晚上睡觉的时候别老咳，会吵醒别人的。","pinyin":"Wǎnshang shuìjiào de shíhou bié lǎo ké, huì chǎo xǐng biérén de.","vn":"Ban đêm ngủ đừng ho mãi, sẽ làm người khác tỉnh giấc đấy."},{"cn":"烟太大了，呛得我直咳。","pinyin":"Yān tài dà le, qiàng de wǒ zhí ké.","vn":"Khói nhiều quá, sặc đến mức tôi ho liên tục."}]},{"hanzi":"厉害","pinyin":"lìhai","pos":"tt.","vn":"nghiêm trọng, dữ dội","examples":[{"cn":"他最近咳得很厉害，应该去看医生。","pinyin":"Tā zuìjìn ké de hěn lìhai, yīnggāi qù kàn yīshēng.","vn":"Dạo này anh ấy ho dữ dội lắm, nên đi khám bác sĩ."},{"cn":"他的汉语说得真厉害，跟中国人一样。","pinyin":"Tā de Hànyǔ shuō de zhēn lìhai, gēn Zhōngguó rén yíyàng.","vn":"Anh ấy nói tiếng Hán giỏi thật, giống hệt người Trung Quốc."},{"cn":"今天外面风刮得特别厉害。","pinyin":"Jīntiān wàimiàn fēng guā de tèbié lìhai.","vn":"Hôm nay ngoài trời gió thổi dữ dội lắm."}]},{"hanzi":"严重","pinyin":"yánzhòng","pos":"tt.","vn":"nghiêm trọng","examples":[{"cn":"医生说他的病情不算严重，吃点药就好了。","pinyin":"Yīshēng shuō tā de bìngqíng bú suàn yánzhòng, chī diǎn yào jiù hǎo le.","vn":"Bác sĩ nói bệnh tình của anh ấy không nghiêm trọng lắm, uống chút thuốc là khỏi."},{"cn":"这座城市的空气污染越来越严重了。","pinyin":"Zhè zuò chéngshì de kōngqì wūrǎn yuè lái yuè yánzhòng le.","vn":"Ô nhiễm không khí của thành phố này ngày càng nghiêm trọng."},{"cn":"这次事故造成了严重的损失。","pinyin":"Zhè cì shìgù zàochéng le yánzhòng de sǔnshī.","vn":"Vụ tai nạn lần này gây ra tổn thất nghiêm trọng."}]},{"hanzi":"赶快","pinyin":"gǎnkuài","pos":"phó.","vn":"nhanh chóng, ngay lập tức","examples":[{"cn":"快迟到了，我们赶快走吧。","pinyin":"Kuài chídào le, wǒmen gǎnkuài zǒu ba.","vn":"Sắp trễ rồi, chúng ta nhanh đi thôi."},{"cn":"你发烧了，赶快去医院看看吧。","pinyin":"Nǐ fāshāo le, gǎnkuài qù yīyuàn kànkan ba.","vn":"Bạn bị sốt rồi, mau đi bệnh viện khám đi."},{"cn":"下雨了，赶快把窗户关上。","pinyin":"Xià yǔ le, gǎnkuài bǎ chuānghu guān shàng.","vn":"Trời mưa rồi, mau đóng cửa sổ lại."}]},{"hanzi":"陪","pinyin":"péi","pos":"dgt.","vn":"đi cùng, tháp tùng","examples":[{"cn":"周末我陪妈妈去医院检查身体。","pinyin":"Zhōumò wǒ péi māma qù yīyuàn jiǎnchá shēntǐ.","vn":"Cuối tuần tôi đưa mẹ đi bệnh viện khám sức khỏe."},{"cn":"他一个人在国外，没人陪他过生日。","pinyin":"Tā yí ge rén zài guówài, méi rén péi tā guò shēngrì.","vn":"Anh ấy một mình ở nước ngoài, không có ai cùng đón sinh nhật."},{"cn":"你能不能陪我去一趟超市？","pinyin":"Nǐ néng bu néng péi wǒ qù yí tàng chāoshì?","vn":"Bạn có thể đi cùng tôi đến siêu thị một chuyến không?"}]},{"hanzi":"翻译","pinyin":"fānyì","pos":"dgt./dt.","vn":"phiên dịch; người phiên dịch","examples":[{"cn":"她的工作是把中文翻译成英文。","pinyin":"Tā de gōngzuò shì bǎ Zhōngwén fānyì chéng Yīngwén.","vn":"Công việc của cô ấy là dịch tiếng Trung sang tiếng Anh."},{"cn":"我们需要请一位翻译来帮忙。","pinyin":"Wǒmen xūyào qǐng yí wèi fānyì lái bāngmáng.","vn":"Chúng tôi cần mời một phiên dịch viên đến giúp đỡ."},{"cn":"这句话很难翻译，意思不太好表达。","pinyin":"Zhè jù huà hěn nán fānyì, yìsi bú tài hǎo biǎodá.","vn":"Câu này rất khó dịch, ý nghĩa không dễ diễn đạt."}]},{"hanzi":"护士","pinyin":"hùshi","pos":"dt.","vn":"y tá","examples":[{"cn":"护士给我量了体温，说有点发烧。","pinyin":"Hùshi gěi wǒ liáng le tǐwēn, shuō yǒudiǎn fāshāo.","vn":"Y tá đo thân nhiệt cho tôi, nói là hơi sốt."},{"cn":"她大学毕业以后当了一名护士。","pinyin":"Tā dàxué bìyè yǐhòu dāng le yì míng hùshi.","vn":"Sau khi tốt nghiệp đại học, cô ấy trở thành một y tá."},{"cn":"护士很耐心地教我怎么吃药。","pinyin":"Hùshi hěn nàixīn de jiāo wǒ zěnme chī yào.","vn":"Y tá kiên nhẫn chỉ cho tôi cách uống thuốc."}]},{"hanzi":"表","pinyin":"biǎo","pos":"dt.","vn":"biểu mẫu, bảng","examples":[{"cn":"请先填一下这张表。","pinyin":"Qǐng xiān tián yíxià zhè zhāng biǎo.","vn":"Xin hãy điền vào biểu mẫu này trước."},{"cn":"挂号的时候需要填写个人信息表。","pinyin":"Guàhào de shíhou xūyào tiánxiě gèrén xìnxī biǎo.","vn":"Khi đăng ký khám bệnh cần điền bảng thông tin cá nhân."},{"cn":"你把这份表格交给护士就行了。","pinyin":"Nǐ bǎ zhè fèn biǎogé jiāo gěi hùshi jiù xíng le.","vn":"Bạn đưa tờ biểu mẫu này cho y tá là được."}]},{"hanzi":"性别","pinyin":"xìngbié","pos":"dt.","vn":"giới tính","examples":[{"cn":"表格上要写姓名、年龄和性别。","pinyin":"Biǎogé shang yào xiě xìngmíng, niánlíng hé xìngbié.","vn":"Trên biểu mẫu cần ghi họ tên, tuổi tác và giới tính."},{"cn":"这份工作不限性别，男女都可以报名。","pinyin":"Zhè fèn gōngzuò bú xiàn xìngbié, nánnǚ dōu kěyǐ bàomíng.","vn":"Công việc này không giới hạn giới tính, nam nữ đều có thể đăng ký."},{"cn":"现在还不知道孩子的性别。","pinyin":"Xiànzài hái bù zhīdào háizi de xìngbié.","vn":"Hiện tại vẫn chưa biết giới tính của đứa bé."}]},{"hanzi":"国籍","pinyin":"guójí","pos":"dt.","vn":"quốc tịch","examples":[{"cn":"请问您的国籍是哪里？","pinyin":"Qǐngwèn nín de guójí shì nǎli?","vn":"Xin hỏi quốc tịch của anh/chị là gì?"},{"cn":"办理签证需要提供国籍证明。","pinyin":"Bànlǐ qiānzhèng xūyào tígōng guójí zhèngmíng.","vn":"Làm thủ tục visa cần cung cấp giấy chứng nhận quốc tịch."},{"cn":"他虽然长得像中国人，但其实是越南国籍。","pinyin":"Tā suīrán zhǎng de xiàng Zhōngguó rén, dàn qíshí shì Yuènán guójí.","vn":"Anh ấy tuy trông giống người Trung Quốc nhưng thực ra mang quốc tịch Việt Nam."}]},{"hanzi":"家庭","pinyin":"jiātíng","pos":"dt.","vn":"gia đình","examples":[{"cn":"他出生在一个普通的家庭。","pinyin":"Tā chūshēng zài yí ge pǔtōng de jiātíng.","vn":"Anh ấy sinh ra trong một gia đình bình thường."},{"cn":"家庭和睦对孩子的成长很重要。","pinyin":"Jiātíng hémù duì háizi de chéngzhǎng hěn zhòngyào.","vn":"Gia đình hòa thuận rất quan trọng đối với sự trưởng thành của trẻ."},{"cn":"工作太忙了，没时间照顾家庭。","pinyin":"Gōngzuò tài máng le, méi shíjiān zhàogu jiātíng.","vn":"Công việc bận quá, không có thời gian chăm lo gia đình."}]},{"hanzi":"地址","pinyin":"dìzhǐ","pos":"dt.","vn":"địa chỉ","examples":[{"cn":"麻烦你把你家地址发给我一下。","pinyin":"Máfan nǐ bǎ nǐ jiā dìzhǐ fā gěi wǒ yíxià.","vn":"Phiền bạn gửi địa chỉ nhà cho tôi một chút."},{"cn":"快递送到这个地址就行了。","pinyin":"Kuàidì sòng dào zhège dìzhǐ jiù xíng le.","vn":"Chuyển phát nhanh giao đến địa chỉ này là được."},{"cn":"我搬家了，地址换了。","pinyin":"Wǒ bānjiā le, dìzhǐ huàn le.","vn":"Tôi chuyển nhà rồi, địa chỉ thay đổi rồi."}]},{"hanzi":"挂号","pinyin":"guàhào","pos":"dgt.","vn":"đăng ký khám bệnh","examples":[{"cn":"我们先去挂号，然后排队看病。","pinyin":"Wǒmen xiān qù guàhào, ránhòu páiduì kànbìng.","vn":"Chúng ta đi đăng ký khám bệnh trước, rồi xếp hàng khám."},{"cn":"现在可以用手机提前挂号了，不用排队了。","pinyin":"Xiànzài kěyǐ yòng shǒujī tíqián guàhào le, búyòng páiduì le.","vn":"Bây giờ có thể dùng điện thoại đăng ký khám trước, không cần xếp hàng nữa."},{"cn":"今天医院人太多了，挂号都挂了半天。","pinyin":"Jīntiān yīyuàn rén tài duō le, guàhào dōu guà le bàntiān.","vn":"Hôm nay bệnh viện đông người quá, đăng ký khám mất cả buổi."}]},{"hanzi":"排队","pinyin":"páiduì","pos":"dgt.","vn":"xếp hàng","examples":[{"cn":"请大家排队，不要插队。","pinyin":"Qǐng dàjiā páiduì, búyào chāduì.","vn":"Mời mọi người xếp hàng, đừng chen ngang."},{"cn":"我在医院排队排了快一个小时了。","pinyin":"Wǒ zài yīyuàn páiduì pái le kuài yí ge xiǎoshí le.","vn":"Tôi xếp hàng ở bệnh viện gần một tiếng đồng hồ rồi."},{"cn":"买这款手机的人太多了，大家都在门口排队。","pinyin":"Mǎi zhè kuǎn shǒujī de rén tài duō le, dàjiā dōu zài ménkǒu páiduì.","vn":"Người mua mẫu điện thoại này đông quá, ai cũng xếp hàng trước cửa."}]},{"hanzi":"大厅","pinyin":"dàtīng","pos":"dt.","vn":"sảnh lớn, đại sảnh","examples":[{"cn":"请在一楼大厅等我，我马上下来。","pinyin":"Qǐng zài yī lóu dàtīng děng wǒ, wǒ mǎshàng xiàlái.","vn":"Hãy đợi tôi ở sảnh lớn tầng một, tôi xuống ngay."},{"cn":"医院大厅里挂号的人特别多。","pinyin":"Yīyuàn dàtīng lǐ guàhào de rén tèbié duō.","vn":"Trong sảnh lớn bệnh viện người đăng ký khám đông vô cùng."},{"cn":"机场大厅里有很多行李箱。","pinyin":"Jīchǎng dàtīng lǐ yǒu hěn duō xínglixiāng.","vn":"Trong sảnh lớn sân bay có rất nhiều vali."}]},{"hanzi":"偶尔","pinyin":"ǒu'ěr","pos":"phó./tt.","vn":"thỉnh thoảng; không thường xuyên","examples":[{"cn":"我平时很少喝咖啡，偶尔才喝一杯。","pinyin":"Wǒ píngshí hěn shǎo hē kāfēi, ǒu'ěr cái hē yì bēi.","vn":"Bình thường tôi ít uống cà phê, thỉnh thoảng mới uống một ly."},{"cn":"他工作很忙，偶尔才有时间回家看看。","pinyin":"Tā gōngzuò hěn máng, ǒu'ěr cái yǒu shíjiān huí jiā kànkan.","vn":"Anh ấy làm việc bận rộn, thỉnh thoảng mới có thời gian về nhà thăm."},{"cn":"偶尔吃点辣的也没关系。","pinyin":"Ǒu'ěr chī diǎn là de yě méi guānxi.","vn":"Thỉnh thoảng ăn chút đồ cay cũng không sao."}]},{"hanzi":"身","pinyin":"shēn","pos":"dt./lượng.","vn":"thân, người; (lượng từ chỉ) bộ (quần áo)","examples":[{"cn":"他浑身都是汗，刚运动完。","pinyin":"Tā húnshēn dōu shì hàn, gāng yùndòng wán.","vn":"Anh ấy cả người đầy mồ hôi, vừa mới tập thể dục xong."},{"cn":"她今天穿了一身新衣服。","pinyin":"Tā jīntiān chuān le yì shēn xīn yīfu.","vn":"Hôm nay cô ấy mặc một bộ quần áo mới."},{"cn":"他身上带了不少现金。","pinyin":"Tā shēnshang dài le bù shǎo xiànjīn.","vn":"Trên người anh ấy mang theo khá nhiều tiền mặt."}]},{"hanzi":"结果","pinyin":"jiéguǒ","pos":"dt./liên.","vn":"kết quả; kết quả là","examples":[{"cn":"体检结果出来了，一切正常。","pinyin":"Tǐjiǎn jiéguǒ chūlái le, yíqiè zhèngcháng.","vn":"Kết quả khám sức khỏe đã có rồi, mọi thứ bình thường."},{"cn":"我复习了一整晚，结果还是没考好。","pinyin":"Wǒ fùxí le yì zhěng wǎn, jiéguǒ háishi méi kǎo hǎo.","vn":"Tôi ôn bài cả đêm, kết quả là vẫn thi không tốt."},{"cn":"他想早点出发，结果路上堵车迟到了。","pinyin":"Tā xiǎng zǎodiǎn chūfā, jiéguǒ lùshang dǔchē chídào le.","vn":"Anh ấy muốn xuất phát sớm, kết quả là bị kẹt xe nên đến muộn."}]},{"hanzi":"性","pinyin":"xìng","pos":"htố.","vn":"(hậu tố chỉ tính chất, đặc điểm, phạm vi nhất định)","examples":[{"cn":"这个药只有一定的治疗性，不能完全根治。","pinyin":"Zhège yào zhǐyǒu yídìng de zhìliáoxìng, bù néng wánquán gēnzhì.","vn":"Loại thuốc này chỉ có tính điều trị nhất định, không thể chữa dứt hoàn toàn."},{"cn":"这个决定的重要性大家都明白。","pinyin":"Zhège juédìng de zhòngyàoxìng dàjiā dōu míngbai.","vn":"Tầm quan trọng của quyết định này mọi người đều hiểu rõ."},{"cn":"这种病有一定的传染性，要注意隔离。","pinyin":"Zhè zhǒng bìng yǒu yídìng de chuánrǎnxìng, yào zhùyì gélí.","vn":"Loại bệnh này có tính lây nhiễm nhất định, cần chú ý cách ly."}]},{"hanzi":"体温","pinyin":"tǐwēn","pos":"dt.","vn":"thân nhiệt","examples":[{"cn":"护士给病人量了体温。","pinyin":"Hùshi gěi bìngrén liáng le tǐwēn.","vn":"Y tá đo thân nhiệt cho bệnh nhân."},{"cn":"他的体温已经恢复正常了。","pinyin":"Tā de tǐwēn yǐjīng huīfù zhèngcháng le.","vn":"Thân nhiệt của anh ấy đã trở lại bình thường."},{"cn":"进门之前要先测一下体温。","pinyin":"Jìn mén zhīqián yào xiān cè yíxià tǐwēn.","vn":"Trước khi vào cửa cần đo thân nhiệt trước."}]},{"hanzi":"降","pinyin":"jiàng","pos":"dgt.","vn":"hạ, giảm","examples":[{"cn":"吃了药以后，他的体温慢慢降下来了。","pinyin":"Chī le yào yǐhòu, tā de tǐwēn mànmàn jiàng xiàlái le.","vn":"Sau khi uống thuốc, thân nhiệt của anh ấy từ từ hạ xuống."},{"cn":"最近气温降得很快，大家要注意保暖。","pinyin":"Zuìjìn qìwēn jiàng de hěn kuài, dàjiā yào zhùyì bǎonuǎn.","vn":"Dạo này nhiệt độ hạ rất nhanh, mọi người chú ý giữ ấm."},{"cn":"这款手机最近降价了不少。","pinyin":"Zhè kuǎn shǒujī zuìjìn jiàngjià le bù shǎo.","vn":"Mẫu điện thoại này dạo gần đây giảm giá khá nhiều."}]},{"hanzi":"光","pinyin":"guāng","pos":"phó.","vn":"chỉ, chỉ riêng","examples":[{"cn":"这件事光靠我一个人是做不完的。","pinyin":"Zhè jiàn shì guāng kào wǒ yí ge rén shì zuò bu wán de.","vn":"Việc này chỉ dựa vào một mình tôi thì không làm xong được."},{"cn":"他光说不做，一点用都没有。","pinyin":"Tā guāng shuō bú zuò, yìdiǎn yòng dōu méiyǒu.","vn":"Anh ta chỉ nói mà không làm, chẳng ích gì cả."},{"cn":"别光顾着玩手机，快去写作业。","pinyin":"Bié guāng gùzhe wán shǒujī, kuài qù xiě zuòyè.","vn":"Đừng chỉ mải chơi điện thoại, mau đi làm bài tập đi."}]},{"hanzi":"打针","pinyin":"dǎzhēn","pos":"dgt.","vn":"tiêm (thuốc)","examples":[{"cn":"医生说需要打针才能好得快一点。","pinyin":"Yīshēng shuō xūyào dǎzhēn cái néng hǎo de kuài yìdiǎn.","vn":"Bác sĩ nói cần tiêm thuốc mới khỏi nhanh hơn một chút."},{"cn":"我最怕打针了，一看到针就紧张。","pinyin":"Wǒ zuì pà dǎzhēn le, yí kàndào zhēn jiù jǐnzhāng.","vn":"Tôi sợ tiêm nhất, cứ nhìn thấy kim là căng thẳng."},{"cn":"护士给孩子打针的时候特别温柔。","pinyin":"Hùshi gěi háizi dǎzhēn de shíhou tèbié wēnróu.","vn":"Lúc tiêm cho em bé, cô y tá rất nhẹ nhàng."}]},{"hanzi":"有效","pinyin":"yǒuxiào","pos":"dgt.","vn":"có hiệu quả","examples":[{"cn":"这个方法对治疗咳嗽很有效。","pinyin":"Zhège fāngfǎ duì zhìliáo késou hěn yǒuxiào.","vn":"Phương pháp này rất có hiệu quả trong việc điều trị ho."},{"cn":"这张票三天内有效，过期就不能用了。","pinyin":"Zhè zhāng piào sān tiān nèi yǒuxiào, guòqī jiù bù néng yòng le.","vn":"Tấm vé này có hiệu lực trong ba ngày, quá hạn thì không dùng được nữa."},{"cn":"吃药以后退烧很有效，一下就好多了。","pinyin":"Chī yào yǐhòu tuìshāo hěn yǒuxiào, yíxià jiù hǎo duō le.","vn":"Uống thuốc xong hạ sốt rất hiệu quả, khỏi hẳn ngay."}]},{"hanzi":"按时","pinyin":"ànshí","pos":"phó.","vn":"đúng giờ, đúng thời gian quy định","examples":[{"cn":"你一定要按时吃药，不能忘。","pinyin":"Nǐ yídìng yào ànshí chī yào, bù néng wàng.","vn":"Bạn nhất định phải uống thuốc đúng giờ, không được quên."},{"cn":"我们每天都按时上下班。","pinyin":"Wǒmen měi tiān dōu ànshí shàngxiàbān.","vn":"Chúng tôi ngày nào cũng đi làm tan làm đúng giờ."},{"cn":"这份作业要按时交，不能迟交。","pinyin":"Zhè fèn zuòyè yào ànshí jiāo, bù néng chí jiāo.","vn":"Bài tập này phải nộp đúng hạn, không được nộp muộn."}]},{"hanzi":"汗","pinyin":"hàn","pos":"dt.","vn":"mồ hôi","examples":[{"cn":"天太热了，我出了一身汗。","pinyin":"Tiān tài rè le, wǒ chū le yì shēn hàn.","vn":"Trời nóng quá, tôi ra mồ hôi khắp người."},{"cn":"他紧张得手心都出汗了。","pinyin":"Tā jǐnzhāng de shǒuxīn dōu chūhàn le.","vn":"Anh ấy căng thẳng đến mức lòng bàn tay cũng ra mồ hôi."},{"cn":"发烧出点汗以后，体温就降下来了。","pinyin":"Fāshāo chū diǎn hàn yǐhòu, tǐwēn jiù jiàng xiàlái le.","vn":"Sốt mà ra chút mồ hôi rồi thì thân nhiệt sẽ hạ xuống."}]},{"hanzi":"醒","pinyin":"xǐng","pos":"dgt.","vn":"tỉnh dậy, thức giấc","examples":[{"cn":"我昨天晚上半夜醒了好几次。","pinyin":"Wǒ zuótiān wǎnshang bànyè xǐng le hǎo jǐ cì.","vn":"Tối qua tôi tỉnh giấc mấy lần giữa đêm."},{"cn":"闹钟响了，他还没醒。","pinyin":"Nàozhōng xiǎng le, tā hái méi xǐng.","vn":"Chuông báo thức kêu rồi mà anh ấy vẫn chưa tỉnh."},{"cn":"孩子睡醒了，开始哭闹找妈妈。","pinyin":"Háizi shuì xǐng le, kāishǐ kūnào zhǎo māma.","vn":"Đứa bé ngủ dậy rồi, bắt đầu khóc lóc đòi tìm mẹ."}]},{"hanzi":"感觉","pinyin":"gǎnjué","pos":"dgt./dt.","vn":"cảm thấy; cảm giác","examples":[{"cn":"我今天感觉不太舒服，有点头疼。","pinyin":"Wǒ jīntiān gǎnjué bú tài shūfu, yǒudiǎn tóuténg.","vn":"Hôm nay tôi cảm thấy không được khỏe lắm, hơi đau đầu."},{"cn":"他给人的感觉特别真诚。","pinyin":"Tā gěi rén de gǎnjué tèbié zhēnchéng.","vn":"Anh ấy mang lại cảm giác rất chân thành cho người khác."},{"cn":"吃完药以后，感觉好多了。","pinyin":"Chī wán yào yǐhòu, gǎnjué hǎo duō le.","vn":"Uống thuốc xong rồi, cảm thấy khá hơn nhiều."}]},{"hanzi":"低","pinyin":"dī","pos":"tt.","vn":"thấp","examples":[{"cn":"他的体温有点低，才三十五度。","pinyin":"Tā de tǐwēn yǒudiǎn dī, cái sānshíwǔ dù.","vn":"Thân nhiệt của anh ấy hơi thấp, mới ba mươi lăm độ."},{"cn":"这份工作的工资太低了，我不想做。","pinyin":"Zhè fèn gōngzuò de gōngzī tài dī le, wǒ bù xiǎng zuò.","vn":"Lương công việc này thấp quá, tôi không muốn làm."},{"cn":"今天的气温比昨天低了不少。","pinyin":"Jīntiān de qìwēn bǐ zuótiān dī le bù shǎo.","vn":"Nhiệt độ hôm nay thấp hơn hôm qua khá nhiều."}]},{"hanzi":"难受","pinyin":"nánshòu","pos":"tt.","vn":"khó chịu","examples":[{"cn":"我肚子疼得难受，想去医院看看。","pinyin":"Wǒ dùzi téng de nánshòu, xiǎng qù yīyuàn kànkan.","vn":"Bụng tôi đau khó chịu quá, muốn đi bệnh viện khám."},{"cn":"听到这个消息，我心里特别难受。","pinyin":"Tīngdào zhège xiāoxi, wǒ xīnli tèbié nánshòu.","vn":"Nghe tin này, lòng tôi cảm thấy rất khó chịu."},{"cn":"穿这双鞋走路脚很难受。","pinyin":"Chuān zhè shuāng xié zǒulù jiǎo hěn nánshòu.","vn":"Đi giày này đi bộ chân cảm thấy rất khó chịu."}]},{"hanzi":"通","pinyin":"tōng","pos":"dgt.","vn":"hiểu, thông suốt","examples":[{"cn":"他汉语说得很流利，但书面语还不太通。","pinyin":"Tā Hànyǔ shuō de hěn liúlì, dàn shūmiànyǔ hái bú tài tōng.","vn":"Anh ấy nói tiếng Hán rất trôi chảy nhưng văn viết thì chưa thông thạo lắm."},{"cn":"这条路现在已经通了，可以开车过去了。","pinyin":"Zhè tiáo lù xiànzài yǐjīng tōng le, kěyǐ kāichē guòqù le.","vn":"Con đường này bây giờ đã thông rồi, có thể lái xe qua được."},{"cn":"我打了好几次电话都打不通。","pinyin":"Wǒ dǎ le hǎo jǐ cì diànhuà dōu dǎ bu tōng.","vn":"Tôi gọi điện mấy lần liền đều không thông được."}]},{"hanzi":"过程","pinyin":"guòchéng","pos":"dt.","vn":"quá trình","examples":[{"cn":"学习一门语言的过程虽然辛苦，但很有意思。","pinyin":"Xuéxí yì mén yǔyán de guòchéng suīrán xīnkǔ, dàn hěn yǒu yìsi.","vn":"Quá trình học một ngôn ngữ tuy vất vả nhưng rất thú vị."},{"cn":"治疗的过程需要一段时间，别着急。","pinyin":"Zhìliáo de guòchéng xūyào yí duàn shíjiān, bié zháojí.","vn":"Quá trình điều trị cần một khoảng thời gian, đừng vội."},{"cn":"整个过程我都记录下来了。","pinyin":"Zhěnggè guòchéng wǒ dōu jìlù xiàlái le.","vn":"Cả quá trình tôi đều ghi chép lại hết."}]},{"hanzi":"部","pinyin":"bù","pos":"dt.","vn":"khoa, bộ phận","examples":[{"cn":"你应该去挂号部挂个号。","pinyin":"Nǐ yīnggāi qù guàhào bù guà ge hào.","vn":"Bạn nên đến khoa đăng ký khám để đăng ký."},{"cn":"他在市场部工作了五年了。","pinyin":"Tā zài shìchǎng bù gōngzuò le wǔ nián le.","vn":"Anh ấy làm việc ở bộ phận thị trường được năm năm rồi."},{"cn":"医院的内科部在二楼。","pinyin":"Yīyuàn de nèikē bù zài èr lóu.","vn":"Khoa nội của bệnh viện ở tầng hai."}]},{"hanzi":"收费","pinyin":"shōufèi","pos":"dgt.","vn":"thu phí","examples":[{"cn":"这个停车场是收费的，停一小时十块钱。","pinyin":"Zhège tíngchēchǎng shì shōufèi de, tíng yì xiǎoshí shí kuài qián.","vn":"Bãi đỗ xe này có thu phí, đỗ một tiếng mười đồng."},{"cn":"这家医院挂号不收费。","pinyin":"Zhè jiā yīyuàn guàhào bù shōufèi.","vn":"Bệnh viện này đăng ký khám không thu phí."},{"cn":"请问送货上门还收费吗？","pinyin":"Qǐngwèn sònghuò shàngmén hái shōufèi ma?","vn":"Xin hỏi giao hàng tận nhà có thu phí nữa không?"}]},{"hanzi":"情况","pinyin":"qíngkuàng","pos":"dt.","vn":"tình hình","examples":[{"cn":"你的情况我已经了解了，别担心。","pinyin":"Nǐ de qíngkuàng wǒ yǐjīng liǎojiě le, bié dānxīn.","vn":"Tình hình của bạn tôi đã nắm rõ rồi, đừng lo lắng."},{"cn":"根据目前的情况来看，还需要再观察几天。","pinyin":"Gēnjù mùqián de qíngkuàng lái kàn, hái xūyào zài guānchá jǐ tiān.","vn":"Theo tình hình hiện tại thì cần phải theo dõi thêm vài ngày."},{"cn":"他突然遇到这种情况，一时不知道怎么办。","pinyin":"Tā tūrán yùdào zhè zhǒng qíngkuàng, yìshí bù zhīdào zěnme bàn.","vn":"Anh ấy đột nhiên gặp phải tình huống này, nhất thời không biết làm sao."}]},{"hanzi":"好","pinyin":"hǎo","pos":"dgt.","vn":"để, nhằm","examples":[{"cn":"把窗户关好，别感冒了。","pinyin":"Bǎ chuānghu guān hǎo, bié gǎnmào le.","vn":"Đóng cửa sổ lại cho kín để khỏi bị cảm."},{"cn":"你多穿点衣服，好出门。","pinyin":"Nǐ duō chuān diǎn yīfu, hǎo chūmén.","vn":"Bạn mặc thêm quần áo để tiện ra ngoài."},{"cn":"我把药放在这儿，好随时吃。","pinyin":"Wǒ bǎ yào fàng zài zhèr, hǎo suíshí chī.","vn":"Tôi để thuốc ở đây để tiện uống bất cứ lúc nào."}]},{"hanzi":"治疗","pinyin":"zhìliáo","pos":"dgt.","vn":"điều trị","examples":[{"cn":"这种病需要住院治疗。","pinyin":"Zhè zhǒng bìng xūyào zhùyuàn zhìliáo.","vn":"Loại bệnh này cần phải nhập viện điều trị."},{"cn":"经过一段时间的治疗，他的病好多了。","pinyin":"Jīngguò yí duàn shíjiān de zhìliáo, tā de bìng hǎo duō le.","vn":"Sau một thời gian điều trị, bệnh của anh ấy đã khá hơn nhiều."},{"cn":"医生正在研究新的治疗方法。","pinyin":"Yīshēng zhèngzài yánjiū xīn de zhìliáo fāngfǎ.","vn":"Bác sĩ đang nghiên cứu phương pháp điều trị mới."}]},{"hanzi":"步","pinyin":"bù","pos":"dt.","vn":"bước","examples":[{"cn":"他走了几步就觉得累了。","pinyin":"Tā zǒu le jǐ bù jiù juéde lèi le.","vn":"Anh ấy đi vài bước là cảm thấy mệt rồi."},{"cn":"做事要一步一步来，不能着急。","pinyin":"Zuòshì yào yí bù yí bù lái, bù néng zháojí.","vn":"Làm việc phải từng bước một, không được vội vàng."},{"cn":"这是治疗过程中很重要的一步。","pinyin":"Zhè shì zhìliáo guòchéng zhōng hěn zhòngyào de yí bù.","vn":"Đây là một bước rất quan trọng trong quá trình điều trị."}]}],"grammar":[{"title":"形容词“厉害” Tính từ “厉害”","explanation_vn":"Tính từ \"厉害\" có thể đặt sau động từ hoặc tính từ, biểu thị mức độ rất cao, cấu trúc là \"động từ + được + (phó từ) + 厉害\" hoặc \"tính từ + được + 厉害\".","examples":[{"cn":"我还发烧，一直咳嗽，咳得很厉害。","pinyin":"Wǒ hái fāshāo, yìzhí késou, ké de hěn lìhai.","vn":"Tôi còn bị sốt, cứ ho mãi, ho rất dữ dội."},{"cn":"我昨天跑步跑多了，今天腐疼得厉害。","pinyin":"Wǒ zuótiān pǎobù pǎo duō le, jīntiān fǔ téng de lìhai.","vn":"Hôm qua tôi chạy bộ nhiều quá, hôm nay chân đau kinh khủng."},{"cn":"这道菜辣得厉害，我吃了一口就不敢再吃了。","pinyin":"Zhè dào cài là de lìhai, wǒ chī le yì kǒu jiù bù gǎn zài chī le.","vn":"Món này cay kinh khủng, tôi ăn một miếng là không dám ăn nữa."}]},{"title":"固定格式“（没）有什么（好）×的” Cấu trúc cố định “（没）有什么（好）×的”","explanation_vn":"Cấu trúc cố định \"(没)有什么(好)×的\" biểu thị không cần thiết phải làm việc gì đó, hoặc có một cảm giác, trạng thái nào đó.","examples":[{"cn":"你跟我有什么好客气的。","pinyin":"Nǐ gēn wǒ yǒu shénme hǎo kèqi de.","vn":"Bạn với tôi thì có gì phải khách sáo chứ."},{"cn":"这种事在网上有很多，没有什么奇怪的。","pinyin":"Zhè zhǒng shì zài wǎngshang yǒu hěn duō, méiyǒu shénme qíguài de.","vn":"Chuyện như vậy trên mạng có nhiều lắm, chẳng có gì lạ cả."},{"cn":"我觉得这家商场里的东西都很一般，没有什么好买的。","pinyin":"Wǒ juéde zhè jiā shāngchǎng lǐ de dōngxi dōu hěn yìbān, méiyǒu shénme hǎo mǎi de.","vn":"Tôi thấy đồ trong trung tâm thương mại này đều bình thường, chẳng có gì đáng mua cả."}]},{"title":"频率副词“偶尔” Phó từ tần suất “偶尔”","explanation_vn":"Phó từ tần suất \"偶尔\" biểu thị hành động hoặc tình huống xảy ra rất ít lần.","examples":[{"cn":"她告诉医生，自己平时身体不错，偶尔才会生一次病。","pinyin":"Tā gàosu yīshēng, zìjǐ píngshí shēntǐ búcuò, ǒu'ěr cái huì shēng yícì bìng.","vn":"Cô ấy nói với bác sĩ rằng bình thường sức khỏe mình khá tốt, thỉnh thoảng mới bị bệnh một lần."},{"cn":"他经常在家看电影，偶尔才去电影院看。","pinyin":"Tā jīngcháng zài jiā kàn diànyǐng, ǒu'ěr cái qù diànyǐngyuàn kàn.","vn":"Anh ấy thường xem phim ở nhà, thỉnh thoảng mới đến rạp chiếu phim xem."},{"cn":"我一般都在学校食堂吃饭，偶尔会跟朋友一起出去吃。","pinyin":"Wǒ yìbān dōu zài xuéxiào shítáng chīfàn, ǒu'ěr huì gēn péngyou yìqǐ chūqù chī.","vn":"Tôi thường ăn ở căng tin trường, thỉnh thoảng mới cùng bạn bè ra ngoài ăn."}]},{"title":"目的复句“……，好……” Câu phức chỉ mục đích “……，好……”","explanation_vn":"Vế trước nói về một hành động hay tình huống nào đó, vế sau nêu rõ mục đích của hành động hay tình huống đó.","examples":[{"cn":"医生有时还会做一些检查，好给出合适的治疗方法。","pinyin":"Yīshēng yǒushí hái huì zuò yìxiē jiǎnchá, hǎo gěichū héshì de zhìliáo fāngfǎ.","vn":"Bác sĩ đôi khi còn làm một số xét nghiệm, để đưa ra phương pháp điều trị phù hợp."},{"cn":"你们先了解一下情况，好做出决定。","pinyin":"Nǐmen xiān liǎojiě yíxià qíngkuàng, hǎo zuòchū juédìng.","vn":"Các bạn hãy tìm hiểu tình hình trước, để đưa ra quyết định."},{"cn":"我把电话号码告诉你，以后有什么事好联系我。","pinyin":"Wǒ bǎ diànhuà hàomǎ gàosu nǐ, yǐhòu yǒu shénme shì hǎo liánxì wǒ.","vn":"Tôi cho bạn số điện thoại, sau này có việc gì thì tiện liên lạc với tôi."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"喜，李文，我身体不舒服。","pinyin":"Xǐ, Lǐ Wén, wǒ shēntǐ bù shūfu."},{"speaker":"李文","cn":"你怎么了？听你的声音，好像感冒了。","pinyin":"Nǐ zěnme le? Tīng nǐ de shēngyīn, hǎoxiàng gǎnmào le."},{"speaker":"白家月","cn":"对，我还发烧，一直咳嗽，咳得很厉害。","pinyin":"Duì, wǒ hái fāshāo, yìzhí késou, ké de hěn lìhai."},{"speaker":"李文","cn":"那挺严重的，最好赶快去医院检查一下。","pinyin":"Nà tǐng yánzhòng de, zuìhǎo gǎnkuài qù yīyuàn jiǎnchá yíxià."},{"speaker":"白家月","cn":"我也这么想，不过我来中国后还没去过医院，不知道怎么在中国的医院看病。","pinyin":"Wǒ yě zhème xiǎng, búguò wǒ lái Zhōngguó hòu hái méi qù guo yīyuàn, bù zhīdào zěnme zài Zhōngguó de yīyuàn kànbìng."},{"speaker":"李文","cn":"没关系，我陪你一起去，还能帮你翻译。你在家等一下，我现在就去接你。","pinyin":"Méi guānxi, wǒ péi nǐ yìqǐ qù, hái néng bāng nǐ fānyì. Nǐ zài jiā děng yíxià, wǒ xiànzài jiù qù jiē nǐ."},{"speaker":"白家月","cn":"太好了！有你陪着，我就放心多了。","pinyin":"Tài hǎo le! Yǒu nǐ péi zhe, wǒ jiù fàngxīn duō le."}],"translation_vn":"Bạch Gia Nguyệt: Alo, Lý Văn, mình thấy khó chịu trong người.\nLý Văn: Bạn làm sao vậy? Nghe giọng có vẻ bị cảm rồi.\nBạch Gia Nguyệt: Đúng vậy, mình còn bị sốt, cứ ho mãi, ho rất dữ dội.\nLý Văn: Nghe có vẻ nghiêm trọng đấy, tốt nhất nên nhanh chóng đến bệnh viện kiểm tra một lần.\nBạch Gia Nguyệt: Mình cũng nghĩ vậy, nhưng từ khi đến Trung Quốc mình chưa đi bệnh viện lần nào, không biết cách khám bệnh ở bệnh viện Trung Quốc như thế nào.\nLý Văn: Không sao, mình đi cùng bạn, còn có thể giúp bạn phiên dịch nữa. Bạn ở nhà đợi một lát, mình đến đón bạn ngay bây giờ.\nBạch Gia Nguyệt: Tuyệt quá! Có bạn đi cùng, mình yên tâm hơn nhiều rồi.","audio_dialogue":"6-1.mp3","audio_vocab":"6-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"李文","cn":"护士，您好，我的这位外国朋友生病了，第一次来这里看病，需要怎么做？","pinyin":"Hùshi, nínhǎo, wǒ de zhè wèi wàiguó péngyou shēngbìng le, dìyī cì lái zhèlǐ kànbìng, xūyào zěnme zuò?"},{"speaker":"护士","cn":"请在这张表上写上病人的姓名、性别、国籍、年龄、电话号码和家庭地址。","pinyin":"Qǐng zài zhè zhāng biǎo shàng xiěshang bìngrén de xìngmíng, xìngbié, guójí, niánlíng, diànhuà hàomǎ hé jiātíng dìzhǐ."},{"speaker":"李文","cn":"我写好了，您看看，这样可以吗？","pinyin":"Wǒ xiě hǎo le, nín kànkan, zhèyàng kěyǐ ma?"},{"speaker":"护士","cn":"没问题，您拿着病人的护照去挂号吧。","pinyin":"Méi wèntí, nín názhe bìngrén de hùzhào qù guàhào ba."},{"speaker":"李文","cn":"家月，我去排队挂号，你先在大厅休息，别着急。","pinyin":"Jiāyuè, wǒ qù páiduì guàhào, nǐ xiān zài dàtīng xiūxi, bié zháojí."},{"speaker":"白家月","cn":"好的，真是太谢谢你了！","pinyin":"Hǎo de, zhēnshi tài xièxie nǐ le!"},{"speaker":"李文","cn":"你跟我有什么好客气的。","pinyin":"Nǐ gēn wǒ yǒu shénme hǎo kèqi de."}],"translation_vn":"Lý Văn: Chào y tá, bạn nước ngoài của tôi bị ốm, đây là lần đầu tiên bạn ấy đến đây khám bệnh, cần làm thế nào ạ?\nY tá: Xin anh điền vào biểu mẫu này họ tên, giới tính, quốc tịch, tuổi, số điện thoại và địa chỉ gia đình của bệnh nhân.\nLý Văn: Tôi viết xong rồi, chị xem giúp, thế này được chưa ạ?\nY tá: Không có vấn đề gì, anh cầm hộ chiếu của bệnh nhân đi đăng ký khám bệnh nhé.\nLý Văn: Gia Nguyệt, mình đi xếp hàng đăng ký khám đây, bạn cứ nghỉ ở sảnh trước, đừng lo lắng.\nBạch Gia Nguyệt: Được rồi, thật sự cảm ơn bạn nhiều lắm!\nLý Văn: Bạn với mình thì có gì phải khách sáo chứ.","audio_dialogue":"6-3.mp3","audio_vocab":"6-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"下午白家月去看病了，她告诉医生，自己平时身体不错，偶尔才会生一次病。这次她病得很厉害，头也一直疼，身上一点儿力气都没有。医生给她做了检查，检查结果出来后，发现她得了比较严重的流行性感冒。","pinyin":"Xiàwǔ Bái Jiāyuè qù kànbìng le, tā gàosu yīshēng, zìjǐ píngshí shēntǐ búcuò, ǒu'ěr cái huì shēng yícì bìng. Zhè cì tā bìng de hěn lìhai, tóu yě yìzhí téng, shēnshang yìdiǎnr lìqi dōu méiyǒu. Yīshēng gěi tā zuò le jiǎnchá, jiǎnchá jiéguǒ chūlái hòu, fāxiàn tā dé le bǐjiào yánzhòng de liúxíngxìng gǎnmào."},{"speaker":"","cn":"医生告诉她，现在需要把体温降下来，光吃药恐怕不够，打针会更有效。医生还让她回家以后按时吃药，多喝水，多休息。","pinyin":"Yīshēng gàosu tā, xiànzài xūyào bǎ tǐwēn jiàng xiàlái, guāng chīyào kǒngpà búgòu, dǎzhēn huì gèng yǒuxiào. Yīshēng hái ràng tā huíjiā yǐhòu ànshí chīyào, duō hēshuǐ, duō xiūxi."},{"speaker":"","cn":"晚上，白家月睡觉时出了一身汗。第二天醒来时，她感觉头不那么疼了，体温也低了一些，身体不那么难受了。","pinyin":"Wǎnshang, Bái Jiāyuè shuìjiào shí chū le yìshēn hàn. Dì èr tiān xǐnglái shí, tā gǎnjué tóu bú nàme téng le, tǐwēn yě dī le yìxiē, shēntǐ bú nàme nánshòu le."}],"translation_vn":"Buổi chiều Bạch Gia Nguyệt đi khám bệnh, cô nói với bác sĩ rằng bình thường sức khỏe mình khá tốt, thỉnh thoảng mới bị bệnh một lần. Lần này cô bị bệnh khá nặng, đầu cứ đau mãi, người không còn chút sức lực nào. Bác sĩ đã khám cho cô, sau khi có kết quả kiểm tra, phát hiện cô bị cúm mùa khá nghiêm trọng.\nBác sĩ nói với cô rằng bây giờ cần hạ thân nhiệt xuống, chỉ uống thuốc thôi e là chưa đủ, tiêm thuốc sẽ hiệu quả hơn. Bác sĩ còn dặn cô về nhà uống thuốc đúng giờ, uống nhiều nước, nghỉ ngơi nhiều.\nBuổi tối, lúc ngủ Bạch Gia Nguyệt đổ một thân mồ hôi. Sáng hôm sau tỉnh dậy, cô cảm thấy đầu đỡ đau hơn, thân nhiệt cũng hạ xuống một chút, người không còn khó chịu như trước nữa.","audio_dialogue":"6-5.mp3","audio_vocab":"6-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"外国人第一次在中国看病，可能会担心语言不通，或者觉得看病的过程和自己的国家不同。其实，这些问题都有办法解决。","pinyin":"Wàiguórén dìyī cì zài Zhōngguó kànbìng, kěnéng huì dānxīn yǔyán bù tōng, huòzhě juéde kànbìng de guòchéng hé zìjǐ de guójiā bùtóng. Qíshí, zhèxiē wèntí dōu yǒu bànfǎ jiějué."},{"speaker":"","cn":"有的医院有国际部，那里的医生一般会说英文，交流比较方便，但是国际部的收费比较高。如果没有特别需要，可以选择普通部，用简单的中文和医生交流。","pinyin":"Yǒude yīyuàn yǒu guójìbù, nàlǐ de yīshēng yìbān huì shuō Yīngwén, jiāoliú bǐjiào fāngbiàn, dànshì guójìbù de shōufèi bǐjiào gāo. Rúguǒ méiyǒu tèbié xūyào, kěyǐ xuǎnzé pǔtōngbù, yòng jiǎndān de Zhōngwén hé yīshēng jiāoliú."},{"speaker":"","cn":"在中国看病要先挂号，然后再去找医生。医生会问病人的情况，有时还会做一些检查，好给出合适的治疗方法。只要按照医生说的一步一步来，一般都可以顺利得到治疗。","pinyin":"Zài Zhōngguó kànbìng yào xiān guàhào, ránhòu zài qù zhǎo yīshēng. Yīshēng huì wèn bìngrén de qíngkuàng, yǒushí hái huì zuò yìxiē jiǎnchá, hǎo gěichū héshì de zhìliáo fāngfǎ. Zhǐyào ànzhào yīshēng shuō de yíbù yíbù lái, yìbān dōu kěyǐ shùnlì dédào zhìliáo."}],"translation_vn":"Người nước ngoài lần đầu đi khám bệnh ở Trung Quốc có thể lo lắng về bất đồng ngôn ngữ, hoặc cảm thấy quy trình khám bệnh khác với đất nước mình. Thực ra, những vấn đề này đều có cách giải quyết.\nMột số bệnh viện có khoa quốc tế, bác sĩ ở đó thường biết nói tiếng Anh, giao tiếp khá thuận tiện, nhưng chi phí của khoa quốc tế lại khá cao. Nếu không có nhu cầu đặc biệt, có thể chọn khoa thường, dùng tiếng Trung đơn giản để giao tiếp với bác sĩ.\nKhám bệnh ở Trung Quốc cần đăng ký trước, sau đó mới đi gặp bác sĩ. Bác sĩ sẽ hỏi tình hình của bệnh nhân, có khi còn làm một số xét nghiệm, để đưa ra phương pháp điều trị phù hợp. Chỉ cần làm theo từng bước mà bác sĩ nói, nhìn chung đều có thể được điều trị thuận lợi.","audio_dialogue":"6-7.mp3","audio_vocab":"6-8.mp3"}]},{"id":7,"title_cn":"在工作中学习","title_pinyin":"Zài gōngzuò zhōng xuéxí","title_vn":"Học hỏi trong công việc","goals":["Có thể nghe hiểu và trao đổi về nhiệm vụ công việc, sắp xếp công việc và các nội dung liên quan.","Có thể trình bày bằng lời nói hoặc văn bản kinh nghiệm làm việc và đưa ra lời khuyên về phát triển sự nghiệp.","Hiểu được cách làm việc coi trọng học hỏi và tích lũy kinh nghiệm trong môi trường công sở."],"vocab":[{"hanzi":"打扰","pinyin":"dǎrǎo","pos":"dgt.","vn":"làm phiền, quấy rầy","examples":[{"cn":"不好意思，打扰您一下，请问洗手间在哪儿？","pinyin":"bù hǎoyìsi, dǎrǎo nín yíxià, qǐngwèn xǐshǒujiān zài nǎr?","vn":"Xin lỗi, làm phiền anh/chị một chút, cho hỏi nhà vệ sinh ở đâu ạ?"},{"cn":"他正在开会，你最好别打扰他。","pinyin":"tā zhèngzài kāihuì, nǐ zuìhǎo bié dǎrǎo tā.","vn":"Anh ấy đang họp, tốt nhất bạn đừng làm phiền anh ấy."},{"cn":"真不好意思，打扰你休息了。","pinyin":"zhēn bù hǎoyìsi, dǎrǎo nǐ xiūxi le.","vn":"Thật xin lỗi, đã làm phiền bạn nghỉ ngơi rồi."}]},{"hanzi":"市场","pinyin":"shìchǎng","pos":"dt.","vn":"thị trường, chợ","examples":[{"cn":"这个产品在市场上很受欢迎。","pinyin":"zhège chǎnpǐn zài shìchǎng shàng hěn shòu huānyíng.","vn":"Sản phẩm này rất được ưa chuộng trên thị trường."},{"cn":"我周末喜欢去菜市场买新鲜的蔬菜。","pinyin":"wǒ zhōumò xǐhuan qù càishìchǎng mǎi xīnxiān de shūcài.","vn":"Cuối tuần tôi thích đi chợ mua rau tươi."},{"cn":"最近市场竞争越来越激烈了。","pinyin":"zuìjìn shìchǎng jìngzhēng yuèláiyuè jīliè le.","vn":"Gần đây cạnh tranh trên thị trường ngày càng khốc liệt."}]},{"hanzi":"调查","pinyin":"diàochá","pos":"dgt.","vn":"điều tra, khảo sát","examples":[{"cn":"公司打算做一个市场调查，了解客户的需求。","pinyin":"gōngsī dǎsuàn zuò yí ge shìchǎng diàochá, liǎojiě kèhù de xūqiú.","vn":"Công ty dự định làm một cuộc khảo sát thị trường để hiểu nhu cầu khách hàng."},{"cn":"警察正在调查这起案件。","pinyin":"jǐngchá zhèngzài diàochá zhè qǐ ànjiàn.","vn":"Cảnh sát đang điều tra vụ án này."},{"cn":"我们对一百个用户做了调查，结果挺有意思的。","pinyin":"wǒmen duì yìbǎi ge yònghù zuò le diàochá, jiéguǒ tǐng yǒuyìsi de.","vn":"Chúng tôi đã khảo sát một trăm người dùng, kết quả khá thú vị."}]},{"hanzi":"计划","pinyin":"jìhuà","pos":"dt./dgt.","vn":"kế hoạch; lập kế hoạch","examples":[{"cn":"我计划暑假的时候去云南旅游。","pinyin":"wǒ jìhuà shǔjià de shíhou qù Yúnnán lǚyóu.","vn":"Tôi dự định nghỉ hè sẽ đi du lịch Vân Nam."},{"cn":"这个计划听起来不错，我们试试吧。","pinyin":"zhège jìhuà tīngqǐlái búcuò, wǒmen shìshi ba.","vn":"Kế hoạch này nghe có vẻ hay, chúng ta thử xem."},{"cn":"因为下雨，我们的计划被打乱了。","pinyin":"yīnwèi xiàyǔ, wǒmen de jìhuà bèi dǎluàn le.","vn":"Vì trời mưa nên kế hoạch của chúng tôi bị đảo lộn."}]},{"hanzi":"内容","pinyin":"nèiróng","pos":"dt.","vn":"nội dung","examples":[{"cn":"这本书的内容很丰富，值得一看。","pinyin":"zhè běn shū de nèiróng hěn fēngfù, zhídé yí kàn.","vn":"Nội dung của cuốn sách này rất phong phú, đáng để đọc."},{"cn":"你能把报告的主要内容讲一下吗？","pinyin":"nǐ néng bǎ bàogào de zhǔyào nèiróng jiǎng yíxià ma?","vn":"Bạn có thể trình bày nội dung chính của báo cáo không?"},{"cn":"这部电影的内容太无聊了，我看到一半就睡着了。","pinyin":"zhè bù diànyǐng de nèiróng tài wúliáo le, wǒ kàndào yíbàn jiù shuìzháo le.","vn":"Nội dung bộ phim này quá nhàm chán, tôi xem đến nửa chừng đã ngủ mất rồi."}]},{"hanzi":"改","pinyin":"gǎi","pos":"dgt.","vn":"sửa, thay đổi","examples":[{"cn":"这篇文章有几个地方需要改一下。","pinyin":"zhè piān wénzhāng yǒu jǐ ge dìfang xūyào gǎi yíxià.","vn":"Bài viết này có mấy chỗ cần sửa lại."},{"cn":"我已经把错误的地方都改好了。","pinyin":"wǒ yǐjīng bǎ cuòwù de dìfang dōu gǎihǎo le.","vn":"Tôi đã sửa xong hết những chỗ sai rồi."},{"cn":"他下定决心要改掉熬夜的坏习惯。","pinyin":"tā xiàdìng juéxīn yào gǎidiào áoyè de huài xíguàn.","vn":"Anh ấy quyết tâm sửa bỏ thói quen xấu thức khuya."}]},{"hanzi":"细心","pinyin":"xìxīn","pos":"tt.","vn":"cẩn thận, tỉ mỉ","examples":[{"cn":"她做事一向很细心，很少出错。","pinyin":"tā zuòshì yíxiàng hěn xìxīn, hěn shǎo chūcuò.","vn":"Cô ấy làm việc luôn rất cẩn thận, hiếm khi sai sót."},{"cn":"护士对病人非常细心，照顾得很周到。","pinyin":"hùshi duì bìngrén fēicháng xìxīn, zhàogù de hěn zhōudào.","vn":"Y tá rất tỉ mỉ với bệnh nhân, chăm sóc rất chu đáo."},{"cn":"这份工作需要细心的人才能做好。","pinyin":"zhè fèn gōngzuò xūyào xìxīn de rén cái néng zuòhǎo.","vn":"Công việc này cần người cẩn thận mới làm tốt được."}]},{"hanzi":"客户","pinyin":"kèhù","pos":"dt.","vn":"khách hàng","examples":[{"cn":"我今天下午要跟一个重要客户见面。","pinyin":"wǒ jīntiān xiàwǔ yào gēn yí ge zhòngyào kèhù jiànmiàn.","vn":"Chiều nay tôi phải gặp một khách hàng quan trọng."},{"cn":"我们公司非常重视客户的意见。","pinyin":"wǒmen gōngsī fēicháng zhòngshì kèhù de yìjiàn.","vn":"Công ty chúng tôi rất coi trọng ý kiến của khách hàng."},{"cn":"这家店的老客户特别多，生意一直很好。","pinyin":"zhè jiā diàn de lǎo kèhù tèbié duō, shēngyi yìzhí hěn hǎo.","vn":"Cửa hàng này có rất nhiều khách quen, việc kinh doanh luôn tốt."}]},{"hanzi":"真正","pinyin":"zhēnzhèng","pos":"tt./phó.","vn":"thực sự, chân chính","examples":[{"cn":"他才是我真正的朋友，一直在我困难的时候帮我。","pinyin":"tā cái shì wǒ zhēnzhèng de péngyou, yìzhí zài wǒ kùnnan de shíhou bāng wǒ.","vn":"Anh ấy mới thực sự là bạn tôi, luôn giúp tôi lúc khó khăn."},{"cn":"我现在才真正明白这句话的意思。","pinyin":"wǒ xiànzài cái zhēnzhèng míngbai zhè jù huà de yìsi.","vn":"Bây giờ tôi mới thực sự hiểu ý nghĩa của câu nói này."},{"cn":"这才是真正的中国味道。","pinyin":"zhè cái shì zhēnzhèng de Zhōngguó wèidao.","vn":"Đây mới chính là hương vị Trung Quốc thực thụ."}]},{"hanzi":"想法","pinyin":"xiǎngfǎ","pos":"dt.","vn":"ý kiến, suy nghĩ","examples":[{"cn":"我对这件事有一个不一样的想法。","pinyin":"wǒ duì zhè jiàn shì yǒu yí ge bù yíyàng de xiǎngfǎ.","vn":"Tôi có một suy nghĩ khác về chuyện này."},{"cn":"你能说说你的想法吗？","pinyin":"nǐ néng shuōshuo nǐ de xiǎngfǎ ma?","vn":"Bạn có thể nói ra suy nghĩ của mình không?"},{"cn":"他的想法总是跟别人不太一样，挺有创意的。","pinyin":"tā de xiǎngfǎ zǒngshì gēn biéren bú tài yíyàng, tǐng yǒu chuàngyì de.","vn":"Suy nghĩ của anh ấy luôn khác người khác, khá sáng tạo."}]},{"hanzi":"任务","pinyin":"rènwù","pos":"dt.","vn":"nhiệm vụ","examples":[{"cn":"老板给我安排了一个新任务。","pinyin":"lǎobǎn gěi wǒ ānpái le yí ge xīn rènwù.","vn":"Sếp đã giao cho tôi một nhiệm vụ mới."},{"cn":"这次的任务很难，但是我们一定能完成。","pinyin":"zhè cì de rènwù hěn nán, dànshì wǒmen yídìng néng wánchéng.","vn":"Nhiệm vụ lần này rất khó, nhưng chúng tôi nhất định hoàn thành được."},{"cn":"我终于把这个月的任务完成了，可以放松一下了。","pinyin":"wǒ zhōngyú bǎ zhège yuè de rènwù wánchéng le, kěyǐ fàngsōng yíxià le.","vn":"Cuối cùng tôi cũng hoàn thành nhiệm vụ tháng này, có thể thư giãn một chút rồi."}]},{"hanzi":"及时","pinyin":"jíshí","pos":"phó./tt.","vn":"kịp thời","examples":[{"cn":"多亏了你及时提醒，不然我就迟到了。","pinyin":"duōkuī le nǐ jíshí tíxǐng, bùrán wǒ jiù chídào le.","vn":"May nhờ bạn nhắc nhở kịp thời, không thì tôi đã trễ rồi."},{"cn":"医生及时赶到，救了病人一命。","pinyin":"yīshēng jíshí gǎndào, jiù le bìngrén yí mìng.","vn":"Bác sĩ đến kịp thời, đã cứu sống bệnh nhân."},{"cn":"有问题要及时反馈给我们，别拖着。","pinyin":"yǒu wèntí yào jíshí fǎnkuì gěi wǒmen, bié tuōzhe.","vn":"Có vấn đề gì phải phản hồi kịp thời cho chúng tôi, đừng trì hoãn."}]},{"hanzi":"出差","pinyin":"chūchāi","pos":"dgt.","vn":"đi công tác","examples":[{"cn":"我下周要去上海出差。","pinyin":"wǒ xiàzhōu yào qù Shànghǎi chūchāi.","vn":"Tuần sau tôi phải đi công tác Thượng Hải."},{"cn":"他经常出差，一个月在家待不了几天。","pinyin":"tā jīngcháng chūchāi, yí ge yuè zài jiā dāibuliǎo jǐ tiān.","vn":"Anh ấy thường xuyên đi công tác, một tháng ở nhà không được mấy ngày."},{"cn":"出差的时候别忘了带充电器。","pinyin":"chūchāi de shíhou bié wàng le dài chōngdiànqì.","vn":"Lúc đi công tác đừng quên mang theo sạc điện thoại."}]},{"hanzi":"经验","pinyin":"jīngyàn","pos":"dt.","vn":"kinh nghiệm","examples":[{"cn":"这位老师教学经验很丰富。","pinyin":"zhè wèi lǎoshī jiàoxué jīngyàn hěn fēngfù.","vn":"Giáo viên này có kinh nghiệm giảng dạy rất phong phú."},{"cn":"没关系，失败也是一种经验。","pinyin":"méiguānxi, shībài yě shì yì zhǒng jīngyàn.","vn":"Không sao, thất bại cũng là một loại kinh nghiệm."},{"cn":"找工作的时候，经验比学历更重要。","pinyin":"zhǎo gōngzuò de shíhou, jīngyàn bǐ xuélì gèng zhòngyào.","vn":"Khi tìm việc, kinh nghiệm quan trọng hơn bằng cấp."}]},{"hanzi":"采访","pinyin":"cǎifǎng","pos":"dgt.","vn":"phỏng vấn","examples":[{"cn":"记者正在采访一位获奖的运动员。","pinyin":"jìzhě zhèngzài cǎifǎng yí wèi huòjiǎng de yùndòngyuán.","vn":"Phóng viên đang phỏng vấn một vận động viên đoạt giải."},{"cn":"明天电视台要来公司采访我们的经理。","pinyin":"míngtiān diànshìtái yào lái gōngsī cǎifǎng wǒmen de jīnglǐ.","vn":"Ngày mai đài truyền hình sẽ đến công ty phỏng vấn giám đốc của chúng tôi."},{"cn":"这次采访让我了解了很多以前不知道的事情。","pinyin":"zhè cì cǎifǎng ràng wǒ liǎojiě le hěn duō yǐqián bù zhīdào de shìqing.","vn":"Lần phỏng vấn này giúp tôi hiểu được nhiều điều mà trước đây không biết."}]},{"hanzi":"产品","pinyin":"chǎnpǐn","pos":"dt.","vn":"sản phẩm","examples":[{"cn":"我们公司新出的产品卖得特别好。","pinyin":"wǒmen gōngsī xīn chū de chǎnpǐn mài de tèbié hǎo.","vn":"Sản phẩm mới ra của công ty chúng tôi bán rất chạy."},{"cn":"这款产品质量不错，价格也合理。","pinyin":"zhè kuǎn chǎnpǐn zhìliàng búcuò, jiàgé yě hélǐ.","vn":"Sản phẩm này chất lượng tốt, giá cả cũng hợp lý."},{"cn":"他们正在开发一种新产品。","pinyin":"tāmen zhèngzài kāifā yì zhǒng xīn chǎnpǐn.","vn":"Họ đang phát triển một loại sản phẩm mới."}]},{"hanzi":"看法","pinyin":"kànfǎ","pos":"dt.","vn":"quan điểm, cách nhìn","examples":[{"cn":"你对这件事有什么看法？","pinyin":"nǐ duì zhè jiàn shì yǒu shénme kànfǎ?","vn":"Bạn có quan điểm gì về chuyện này?"},{"cn":"每个人的看法不一样，我们可以听听大家的意见。","pinyin":"měi ge rén de kànfǎ bù yíyàng, wǒmen kěyǐ tīngting dàjiā de yìjiàn.","vn":"Quan điểm mỗi người mỗi khác, chúng ta có thể lắng nghe ý kiến mọi người."},{"cn":"经过这次经历，我对生活有了新的看法。","pinyin":"jīngguò zhè cì jīnglì, wǒ duì shēnghuó yǒu le xīn de kànfǎ.","vn":"Qua trải nghiệm lần này, tôi đã có cách nhìn mới về cuộc sống."}]},{"hanzi":"提前","pinyin":"tíqián","pos":"dgt.","vn":"làm trước, tiến hành sớm","examples":[{"cn":"飞机提前了半个小时起飞。","pinyin":"fēijī tíqián le bàn ge xiǎoshí qǐfēi.","vn":"Máy bay cất cánh sớm nửa tiếng."},{"cn":"考试要提前十分钟到教室。","pinyin":"kǎoshì yào tíqián shí fēnzhōng dào jiàoshì.","vn":"Thi cử phải đến phòng học sớm mười phút."},{"cn":"我们最好提前订票，不然可能买不到了。","pinyin":"wǒmen zuìhǎo tíqián dìng piào, bùrán kěnéng mǎibudào le.","vn":"Chúng ta tốt nhất nên đặt vé trước, không thì có thể không mua được."}]},{"hanzi":"便于","pinyin":"biànyú","pos":"dgt.","vn":"thuận tiện cho","examples":[{"cn":"请把资料整理好，便于大家查看。","pinyin":"qǐng bǎ zīliào zhěnglǐhǎo, biànyú dàjiā chákàn.","vn":"Xin hãy sắp xếp tài liệu cho gọn, để mọi người tiện xem."},{"cn":"这种设计便于用户操作。","pinyin":"zhè zhǒng shèjì biànyú yònghù cāozuò.","vn":"Thiết kế kiểu này thuận tiện cho người dùng thao tác."},{"cn":"为了便于联系，请留下你的手机号码。","pinyin":"wèile biànyú liánxì, qǐng liúxià nǐ de shǒujī hàomǎ.","vn":"Để tiện liên lạc, xin để lại số điện thoại của bạn."}]},{"hanzi":"既然","pinyin":"jìrán","pos":"liên.","vn":"đã như vậy thì, bởi vì","examples":[{"cn":"既然你已经决定了，我就不再劝你了。","pinyin":"jìrán nǐ yǐjīng juédìng le, wǒ jiù bú zài quàn nǐ le.","vn":"Đã như vậy là bạn quyết định rồi, tôi sẽ không khuyên bạn nữa."},{"cn":"既然下雨了，我们就改天再去吧。","pinyin":"jìrán xiàyǔ le, wǒmen jiù gǎitiān zài qù ba.","vn":"Đã mưa rồi thì chúng ta đổi ngày khác đi vậy."},{"cn":"既然大家都同意，那就这么定了。","pinyin":"jìrán dàjiā dōu tóngyì, nà jiù zhème dìng le.","vn":"Mọi người đã đồng ý rồi thì cứ quyết định như vậy nhé."}]},{"hanzi":"谈","pinyin":"tán","pos":"dgt.","vn":"bàn bạc, nói chuyện","examples":[{"cn":"我们找个时间好好谈谈吧。","pinyin":"wǒmen zhǎo ge shíjiān hǎohǎo tántan ba.","vn":"Chúng ta tìm thời gian nói chuyện kỹ một chút đi."},{"cn":"他正在和客户谈一个大项目。","pinyin":"tā zhèngzài hé kèhù tán yí ge dà xiàngmù.","vn":"Anh ấy đang bàn bạc với khách hàng về một dự án lớn."},{"cn":"这个问题不太好谈，我们先放一放吧。","pinyin":"zhège wèntí bú tài hǎo tán, wǒmen xiān fàng yi fàng ba.","vn":"Vấn đề này khó bàn, chúng ta tạm gác lại đã."}]},{"hanzi":"笔","pinyin":"bǐ","pos":"lượng.","vn":"khoản (dùng cho tiền bạc, tài khoản...)","examples":[{"cn":"公司这个月签了一笔大生意。","pinyin":"gōngsī zhège yuè qiān le yì bǐ dà shēngyi.","vn":"Tháng này công ty đã ký được một khoản làm ăn lớn."},{"cn":"他从银行取了一笔钱。","pinyin":"tā cóng yínháng qǔ le yì bǐ qián.","vn":"Anh ấy đã rút một khoản tiền từ ngân hàng."},{"cn":"这笔账我还没算清楚。","pinyin":"zhè bǐ zhàng wǒ hái méi suàn qīngchu.","vn":"Khoản tiền này tôi vẫn chưa tính rõ ràng."}]},{"hanzi":"生意","pinyin":"shēngyi","pos":"dt.","vn":"công việc kinh doanh, buôn bán","examples":[{"cn":"他的生意做得越来越大了。","pinyin":"tā de shēngyi zuò de yuèláiyuè dà le.","vn":"Công việc kinh doanh của anh ấy ngày càng lớn mạnh."},{"cn":"最近生意不太好，店里客人很少。","pinyin":"zuìjìn shēngyi bú tài hǎo, diàn lǐ kèrén hěn shǎo.","vn":"Dạo này buôn bán không tốt lắm, khách ở cửa hàng rất ít."},{"cn":"她辞职以后自己开始做生意了。","pinyin":"tā cízhí yǐhòu zìjǐ kāishǐ zuò shēngyi le.","vn":"Sau khi nghỉ việc, cô ấy bắt đầu tự kinh doanh."}]},{"hanzi":"困难","pinyin":"kùnnan","pos":"dt./tt.","vn":"khó khăn","examples":[{"cn":"我们遇到了一些困难，但一定能克服。","pinyin":"wǒmen yùdào le yìxiē kùnnan, dàn yídìng néng kèfú.","vn":"Chúng tôi gặp phải một số khó khăn, nhưng nhất định sẽ vượt qua được."},{"cn":"这道题对我来说有点困难。","pinyin":"zhè dào tí duì wǒ láishuō yǒudiǎn kùnnan.","vn":"Bài này đối với tôi hơi khó."},{"cn":"家里经济困难，他从小就很懂事。","pinyin":"jiā lǐ jīngjì kùnnan, tā cóngxiǎo jiù hěn dǒngshì.","vn":"Kinh tế gia đình khó khăn, anh ấy từ nhỏ đã rất hiểu chuyện."}]},{"hanzi":"优点","pinyin":"yōudiǎn","pos":"dt.","vn":"ưu điểm","examples":[{"cn":"她的优点是做事很认真。","pinyin":"tā de yōudiǎn shì zuòshì hěn rènzhēn.","vn":"Ưu điểm của cô ấy là làm việc rất nghiêm túc."},{"cn":"这种材料的优点是又轻又结实。","pinyin":"zhè zhǒng cáiliào de yōudiǎn shì yòu qīng yòu jiēshi.","vn":"Ưu điểm của loại vật liệu này là vừa nhẹ vừa chắc chắn."},{"cn":"每个人都有自己的优点，不用跟别人比。","pinyin":"měi ge rén dōu yǒu zìjǐ de yōudiǎn, búyòng gēn biéren bǐ.","vn":"Mỗi người đều có ưu điểm riêng, không cần so sánh với người khác."}]},{"hanzi":"缺点","pinyin":"quēdiǎn","pos":"dt.","vn":"khuyết điểm, nhược điểm","examples":[{"cn":"每个人都有缺点，不用太在意。","pinyin":"měi ge rén dōu yǒu quēdiǎn, búyòng tài zàiyì.","vn":"Ai cũng có khuyết điểm, không cần để tâm quá."},{"cn":"这个计划有一个明显的缺点，就是花费太高。","pinyin":"zhège jìhuà yǒu yí ge míngxiǎn de quēdiǎn, jiùshì huāfèi tài gāo.","vn":"Kế hoạch này có một khuyết điểm rõ ràng, đó là chi phí quá cao."},{"cn":"他最大的缺点是太固执了。","pinyin":"tā zuìdà de quēdiǎn shì tài gùzhí le.","vn":"Khuyết điểm lớn nhất của anh ấy là quá cố chấp."}]},{"hanzi":"实际","pinyin":"shíjì","pos":"tt./dt.","vn":"thực tế","examples":[{"cn":"这个计划听起来不错，但不太实际。","pinyin":"zhège jìhuà tīngqǐlái búcuò, dàn bú tài shíjì.","vn":"Kế hoạch này nghe có vẻ hay, nhưng không thực tế lắm."},{"cn":"我们要根据实际情况来调整计划。","pinyin":"wǒmen yào gēnjù shíjì qíngkuàng lái tiáozhěng jìhuà.","vn":"Chúng ta phải điều chỉnh kế hoạch theo tình hình thực tế."},{"cn":"他看起来很年轻，实际已经四十岁了。","pinyin":"tā kànqǐlái hěn niánqīng, shíjì yǐjīng sìshí suì le.","vn":"Anh ấy trông còn trẻ, thực tế đã bốn mươi tuổi rồi."}]},{"hanzi":"效果","pinyin":"xiàoguǒ","pos":"dt.","vn":"hiệu quả","examples":[{"cn":"这种药的效果很明显，吃了两天就好多了。","pinyin":"zhè zhǒng yào de xiàoguǒ hěn míngxiǎn, chī le liǎng tiān jiù hǎo duō le.","vn":"Loại thuốc này hiệu quả rất rõ, uống hai ngày đã đỡ nhiều rồi."},{"cn":"广告效果不太好，没带来多少客户。","pinyin":"guǎnggào xiàoguǒ bú tài hǎo, méi dàilái duōshǎo kèhù.","vn":"Hiệu quả quảng cáo không tốt lắm, không mang lại nhiều khách hàng."},{"cn":"新方法试了一下，效果比以前好多了。","pinyin":"xīn fāngfǎ shì le yíxià, xiàoguǒ bǐ yǐqián hǎo duō le.","vn":"Thử phương pháp mới, hiệu quả tốt hơn trước nhiều."}]},{"hanzi":"点","pinyin":"diǎn","pos":"dt.","vn":"điểm","examples":[{"cn":"你说的这个点很重要，我记下来了。","pinyin":"nǐ shuō de zhège diǎn hěn zhòngyào, wǒ jìxiàlái le.","vn":"Điểm bạn nói rất quan trọng, tôi đã ghi lại rồi."},{"cn":"这篇报告有几个重点需要再强调一下。","pinyin":"zhè piān bàogào yǒu jǐ ge zhòngdiǎn xūyào zài qiángdiào yíxià.","vn":"Bản báo cáo này có mấy điểm trọng tâm cần nhấn mạnh thêm."},{"cn":"我觉得他说得有道理，特别是最后那一点。","pinyin":"wǒ juéde tā shuō de yǒu dàolǐ, tèbié shì zuìhòu nà yì diǎn.","vn":"Tôi thấy anh ấy nói có lý, đặc biệt là điểm cuối cùng đó."}]},{"hanzi":"一下","pinyin":"yíxià","pos":"phó.","vn":"ngay lập tức, bỗng nhiên","examples":[{"cn":"他一下愣住了，不知道该说什么。","pinyin":"tā yíxià lèngzhù le, bù zhīdào gāi shuō shénme.","vn":"Anh ấy bỗng sững người, không biết nên nói gì."},{"cn":"听到这个消息，她一下哭了出来。","pinyin":"tīngdào zhège xiāoxi, tā yíxià kū le chūlái.","vn":"Nghe tin này, cô ấy bỗng bật khóc."},{"cn":"天气一下冷了下来，大家都穿上了外套。","pinyin":"tiānqì yíxià lěng le xiàlái, dàjiā dōu chuānshàng le wàitào.","vn":"Thời tiết bỗng trở lạnh, mọi người đều khoác thêm áo khoác."}]},{"hanzi":"份","pinyin":"fèn","pos":"lượng.","vn":"phần, bản (dùng để chỉ phần, bản, bộ...)","examples":[{"cn":"请给我一份报纸。","pinyin":"qǐng gěi wǒ yí fèn bàozhǐ.","vn":"Cho tôi một tờ báo."},{"cn":"这份报告你看完了吗？","pinyin":"zhè fèn bàogào nǐ kànwán le ma?","vn":"Bản báo cáo này bạn xem xong chưa?"},{"cn":"我想点一份炒饭和一份汤。","pinyin":"wǒ xiǎng diǎn yí fèn chǎofàn hé yí fèn tāng.","vn":"Tôi muốn gọi một phần cơm rang và một phần canh."}]},{"hanzi":"积累","pinyin":"jīlěi","pos":"dgt.","vn":"tích lũy","examples":[{"cn":"学习语言需要慢慢积累词汇量。","pinyin":"xuéxí yǔyán xūyào mànmàn jīlěi cíhuìliàng.","vn":"Học ngôn ngữ cần tích lũy dần dần vốn từ vựng."},{"cn":"他工作多年，积累了不少经验。","pinyin":"tā gōngzuò duō nián, jīlěi le bùshǎo jīngyàn.","vn":"Anh ấy làm việc nhiều năm, đã tích lũy không ít kinh nghiệm."},{"cn":"这些问题都是长期积累下来的，不是一天造成的。","pinyin":"zhèxiē wèntí dōu shì chángqī jīlěi xiàlái de, búshì yì tiān zàochéng de.","vn":"Những vấn đề này đều do tích lũy lâu dài, không phải do một ngày mà thành."}]},{"hanzi":"使","pinyin":"shǐ","pos":"dgt.","vn":"khiến cho, làm cho","examples":[{"cn":"这件事使我明白了很多道理。","pinyin":"zhè jiàn shì shǐ wǒ míngbai le hěn duō dàolǐ.","vn":"Chuyện này khiến tôi hiểu ra được nhiều đạo lý."},{"cn":"他的鼓励使我有了继续努力的勇气。","pinyin":"tā de gǔlì shǐ wǒ yǒu le jìxù nǔlì de yǒngqì.","vn":"Sự động viên của anh ấy khiến tôi có dũng khí tiếp tục cố gắng."},{"cn":"这种新技术能使生产效率大大提高。","pinyin":"zhè zhǒng xīn jìshù néng shǐ shēngchǎn xiàolǜ dàdà tígāo.","vn":"Công nghệ mới này có thể khiến hiệu suất sản xuất tăng lên đáng kể."}]},{"hanzi":"进入","pinyin":"jìnrù","pos":"dgt.","vn":"tiến vào, bước vào","examples":[{"cn":"毕业以后他就进入了一家大公司工作。","pinyin":"bìyè yǐhòu tā jiù jìnrù le yì jiā dà gōngsī gōngzuò.","vn":"Sau khi tốt nghiệp, anh ấy đã vào làm việc tại một công ty lớn."},{"cn":"我们已经正式进入冬天了。","pinyin":"wǒmen yǐjīng zhèngshì jìnrù dōngtiān le.","vn":"Chúng ta đã chính thức bước vào mùa đông."},{"cn":"请大家把手机静音，比赛马上就要进入第二轮了。","pinyin":"qǐng dàjiā bǎ shǒujī jìngyīn, bǐsài mǎshàng jiù yào jìnrù dì èr lún le.","vn":"Mời mọi người tắt chuông điện thoại, trận đấu sắp bước vào vòng hai rồi."}]},{"hanzi":"社会","pinyin":"shèhuì","pos":"dt.","vn":"xã hội","examples":[{"cn":"我们要努力做一个对社会有用的人。","pinyin":"wǒmen yào nǔlì zuò yí ge duì shèhuì yǒuyòng de rén.","vn":"Chúng ta phải cố gắng trở thành người có ích cho xã hội."},{"cn":"现在社会发展得很快，变化很大。","pinyin":"xiànzài shèhuì fāzhǎn de hěn kuài, biànhuà hěn dà.","vn":"Xã hội hiện nay phát triển rất nhanh, thay đổi rất lớn."},{"cn":"刚进入社会的年轻人往往缺少经验。","pinyin":"gāng jìnrù shèhuì de niánqīngrén wǎngwǎng quēshǎo jīngyàn.","vn":"Những người trẻ mới bước vào xã hội thường thiếu kinh nghiệm."}]},{"hanzi":"管理","pinyin":"guǎnlǐ","pos":"dgt.","vn":"quản lý","examples":[{"cn":"他负责管理公司的财务。","pinyin":"tā fùzé guǎnlǐ gōngsī de cáiwù.","vn":"Anh ấy phụ trách quản lý tài chính của công ty."},{"cn":"这个小区的管理做得不错，很安全。","pinyin":"zhège xiǎoqū de guǎnlǐ zuò de búcuò, hěn ānquán.","vn":"Khu dân cư này quản lý khá tốt, rất an toàn."},{"cn":"她工作能力强，很快就被提升为管理人员。","pinyin":"tā gōngzuò nénglì qiáng, hěn kuài jiù bèi tíshēng wéi guǎnlǐ rényuán.","vn":"Năng lực làm việc của cô ấy mạnh, chẳng mấy chốc đã được thăng chức làm quản lý."}]},{"hanzi":"基础","pinyin":"jīchǔ","pos":"dt.","vn":"nền tảng, cơ sở","examples":[{"cn":"打好基础对学习来说非常重要。","pinyin":"dǎhǎo jīchǔ duì xuéxí láishuō fēicháng zhòngyào.","vn":"Xây dựng nền tảng vững chắc rất quan trọng đối với việc học."},{"cn":"他的英语基础很好，学起来很快。","pinyin":"tā de Yīngyǔ jīchǔ hěn hǎo, xué qǐlái hěn kuài.","vn":"Nền tảng tiếng Anh của anh ấy rất tốt, học rất nhanh."},{"cn":"信任是朋友关系的基础。","pinyin":"xìnrèn shì péngyou guānxì de jīchǔ.","vn":"Sự tin tưởng là nền tảng của mối quan hệ bạn bè."}]},{"hanzi":"能力","pinyin":"nénglì","pos":"dt.","vn":"năng lực","examples":[{"cn":"他的工作能力很强，经理很信任他。","pinyin":"tā de gōngzuò nénglì hěn qiáng, jīnglǐ hěn xìnrèn tā.","vn":"Năng lực làm việc của anh ấy rất mạnh, giám đốc rất tin tưởng anh ấy."},{"cn":"这家公司很看重应聘者的沟通能力。","pinyin":"zhè jiā gōngsī hěn kànzhòng yìngpìnzhě de gōutōng nénglì.","vn":"Công ty này rất coi trọng khả năng giao tiếp của ứng viên."},{"cn":"多参加这样的活动可以锻炼你的能力。","pinyin":"duō cānjiā zhèyàng de huódòng kěyǐ duànliàn nǐ de nénglì.","vn":"Tham gia nhiều hoạt động như vậy có thể rèn luyện năng lực của bạn."}]},{"hanzi":"今后","pinyin":"jīnhòu","pos":"dt.","vn":"từ nay về sau, tương lai","examples":[{"cn":"今后我会更加努力工作。","pinyin":"jīnhòu wǒ huì gèngjiā nǔlì gōngzuò.","vn":"Từ nay về sau tôi sẽ làm việc chăm chỉ hơn."},{"cn":"希望大家今后多多关照。","pinyin":"xīwàng dàjiā jīnhòu duōduō guānzhào.","vn":"Mong mọi người từ nay về sau chiếu cố nhiều."},{"cn":"今后遇到问题要及时跟我说。","pinyin":"jīnhòu yùdào wèntí yào jíshí gēn wǒ shuō.","vn":"Về sau gặp vấn đề gì phải nói với tôi kịp thời."}]}],"grammar":[{"title":"固定格式\"在……方面\"","explanation_vn":"Cấu trúc cố định \"在……方面\" (về mặt...) dùng để giới hạn phạm vi hoặc lĩnh vực đang bàn luận.","examples":[{"cn":"在内容方面，您觉得有需要改的吗？","pinyin":"Zài nèiróng fāngmiàn, nín juéde yǒu xūyào gǎi de ma?","vn":"Về mặt nội dung, chị thấy có cần sửa gì không?"},{"cn":"在时间安排方面，你可以再想一想。","pinyin":"Zài shíjiān ānpái fāngmiàn, nǐ kěyǐ zài xiǎng yi xiǎng.","vn":"Về mặt sắp xếp thời gian, bạn có thể suy nghĩ thêm."},{"cn":"他才来中国两个月，在生活方面，还不太习惯。","pinyin":"Tā cái lái Zhōngguó liǎng ge yuè, zài shēnghuó fāngmiàn, hái bú tài xíguàn.","vn":"Anh ấy mới đến Trung Quốc được hai tháng, về mặt sinh hoạt, vẫn chưa quen lắm."}]},{"title":"因果复句\"既然……，就……\"","explanation_vn":"Câu phức nhân quả \"既然……，就……\" (đã như vậy thì...): vế trước nêu tiền đề, vế sau nêu kết luận được suy ra từ tiền đề đó.","examples":[{"cn":"既然出差时间不长，就要安排好时间，多获得有用的信息。","pinyin":"Jìrán chūchāi shíjiān bù cháng, jiù yào ānpái hǎo shíjiān, duō huòdé yǒuyòng de xìnxī.","vn":"Đã đi công tác không lâu thì phải sắp xếp thời gian tốt, thu thập nhiều thông tin hữu ích."},{"cn":"既然大家都同意，我们就这么做吧。","pinyin":"Jìrán dàjiā dōu tóngyì, wǒmen jiù zhème zuò ba.","vn":"Đã mọi người đều đồng ý thì chúng ta cứ làm như vậy đi."},{"cn":"既然你们已经决定了，就不要再改了。","pinyin":"Jìrán nǐmen yǐjīng juédìng le, jiù búyào zài gǎi le.","vn":"Đã các bạn quyết định rồi thì đừng thay đổi nữa."}]},{"title":"固定格式\"拿……来说\"","explanation_vn":"Cấu trúc cố định \"拿……来说\" (lấy... mà nói) dùng để dẫn ra một khía cạnh cụ thể hoặc ví dụ.","examples":[{"cn":"拿和客户交流来说，虽然她能把产品的优缺点说得很清楚，但实际效果并不理想。","pinyin":"Ná hé kèhù jiāoliú lái shuō, suīrán tā néng bǎ chǎnpǐn de yōuquēdiǎn shuō de hěn qīngchu, dàn shíjì xiàoguǒ bìng bù lǐxiǎng.","vn":"Lấy việc giao tiếp với khách hàng mà nói, tuy cô ấy có thể trình bày rõ ràng ưu nhược điểm của sản phẩm, nhưng hiệu quả thực tế lại không như ý."},{"cn":"现在的生活很方便。拿购物来说，人们不出门就能买到想要的东西。","pinyin":"Xiànzài de shēnghuó hěn fāngbiàn. Ná gòuwù lái shuō, rénmen bù chūmén jiù néng mǎidào xiǎngyào de dōngxi.","vn":"Cuộc sống hiện nay rất tiện lợi. Lấy việc mua sắm mà nói, người ta không cần ra khỏi nhà cũng có thể mua được thứ mình muốn."},{"cn":"在中国，南北方的生活习惯不同。拿吃饭来说，一般南方人更爱吃米饭。","pinyin":"Zài Zhōngguó, nánběifāng de shēnghuó xíguàn bùtóng. Ná chīfàn lái shuō, yìbān nánfāngrén gèng ài chī mǐfàn.","vn":"Ở Trung Quốc, thói quen sinh hoạt giữa miền Nam và miền Bắc khác nhau. Lấy việc ăn uống mà nói, người miền Nam nhìn chung thích ăn cơm hơn."}]},{"title":"兼语句\"主语+使+宾语+动词短语\"","explanation_vn":"Câu kiêm ngữ \"chủ ngữ + 使 + tân ngữ + cụm động từ\" biểu thị một tình huống hoặc nguyên nhân nào đó khiến người hoặc sự vật xảy ra thay đổi hoặc tạo ra kết quả.","examples":[{"cn":"如果总是换工作，可能会使自己的发展受到影响。","pinyin":"Rúguǒ zǒngshì huàn gōngzuò, kěnéng huì shǐ zìjǐ de fāzhǎn shòudào yǐngxiǎng.","vn":"Nếu cứ liên tục đổi việc, có thể sẽ khiến sự phát triển của bản thân bị ảnh hưởng."},{"cn":"这个新方法使工作变得更加简单了。","pinyin":"Zhège xīn fāngfǎ shǐ gōngzuò biànde gèngjiā jiǎndān le.","vn":"Phương pháp mới này khiến công việc trở nên đơn giản hơn."},{"cn":"参加这些交流活动使留学生更快适应了大学生活。","pinyin":"Cānjiā zhèxiē jiāoliú huódòng shǐ liúxuéshēng gèng kuài shìyìng le dàxué shēnghuó.","vn":"Việc tham gia các hoạt động giao lưu này giúp lưu học sinh thích nghi nhanh hơn với cuộc sống đại học."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"同事","cn":"经理，打扰您一下。市场调查的计划书我昨天发到您邮箱了。在内容方面，您觉得有需要改的吗？","pinyin":"Jīnglǐ, dǎrǎo nín yíxià. Shìchǎng diàochá de jìhuàshū wǒ zuótiān fā dào nín yóuxiāng le. Zài nèiróng fāngmiàn, nín juéde yǒu xūyào gǎi de ma?"},{"speaker":"王一雪","cn":"我看过了，写得不错，就是调查的地点只有超市，不太够。","pinyin":"Wǒ kàn guo le, xiě de búcuò, jiùshì diàochá de dìdiǎn zhǐyǒu chāoshì, bú tài gòu."},{"speaker":"同事","cn":"好的，那我再加一些网店。","pinyin":"Hǎo de, nà wǒ zài jiā yìxiē wǎngdiàn."},{"speaker":"王一雪","cn":"行。做调查的时候要细心，注意了解客户真正的想法。","pinyin":"Xíng. Zuò diàochá de shíhou yào xìxīn, zhùyì liǎojiě kèhù zhēnzhèng de xiǎngfǎ."},{"speaker":"同事","cn":"明白了，我会认真准备，按时完成任务。","pinyin":"Míngbai le, wǒ huì rènzhēn zhǔnbèi, ànshí wánchéng rènwù."},{"speaker":"王一雪","cn":"嗯，如果遇到什么问题，及时跟我联系。","pinyin":"Ng, rúguǒ yùdào shénme wèntí, jíshí gēn wǒ liánxì."}],"translation_vn":"Đồng nghiệp: Giám đốc, làm phiền chị một chút. Bản kế hoạch khảo sát thị trường em đã gửi vào email của chị hôm qua rồi. Về mặt nội dung, chị thấy có cần sửa gì không ạ?\nVương Nhất Tuyết: Chị xem rồi, viết khá tốt, chỉ có điều địa điểm khảo sát chỉ có siêu thị, chưa đủ.\nĐồng nghiệp: Vâng, vậy em sẽ thêm một số cửa hàng trực tuyến.\nVương Nhất Tuyết: Được. Khi khảo sát phải cẩn thận, chú ý tìm hiểu suy nghĩ thực sự của khách hàng.\nĐồng nghiệp: Em hiểu rồi, em sẽ chuẩn bị kỹ càng, hoàn thành nhiệm vụ đúng hạn.\nVương Nhất Tuyết: Ừ, nếu gặp vấn đề gì thì liên hệ với chị kịp thời nhé.","audio_dialogue":"7-1.mp3","audio_vocab":"7-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"同事","cn":"杨哥，经理让我下周去上海出差，做市场调查，你有这方面的经验吗？","pinyin":"Yáng gē, jīnglǐ ràng wǒ xià zhōu qù Shànghǎi chūchāi, zuò shìchǎng diàochá, nǐ yǒu zhè fāngmiàn de jīngyàn ma?"},{"speaker":"杨同乐","cn":"你要去几天？主要调查什么内容？","pinyin":"Nǐ yào qù jǐ tiān? Zhǔyào diàochá shénme nèiróng?"},{"speaker":"同事","cn":"去四天，打算采访一些客户，了解他们对新产品的看法。","pinyin":"Qù sì tiān, dǎsuàn cǎifǎng yìxiē kèhù, liǎojiě tāmen duì xīn chǎnpǐn de kànfǎ."},{"speaker":"杨同乐","cn":"那你要提前准备好问题，便于和客户交流。","pinyin":"Nà nǐ yào tíqián zhǔnbèi hǎo wèntí, biànyú hé kèhù jiāoliú."},{"speaker":"同事","cn":"好的，我已经准备了一些问题。","pinyin":"Hǎo de, wǒ yǐjīng zhǔnbèi le yìxiē wèntí."},{"speaker":"杨同乐","cn":"很好。既然出差时间不长，就要安排好时间，多获得有用的信息。","pinyin":"Hěn hǎo. Jìrán chūchāi shíjiān bù cháng, jiù yào ānpái hǎo shíjiān, duō huòdé yǒuyòng de xìnxī."}],"translation_vn":"Đồng nghiệp: Anh Dương, giám đốc bảo em tuần sau đi công tác Thượng Hải, làm khảo sát thị trường, anh có kinh nghiệm về việc này không?\nDương Đồng Lạc: Em đi mấy ngày? Chủ yếu khảo sát nội dung gì?\nĐồng nghiệp: Đi bốn ngày, em định phỏng vấn một số khách hàng, tìm hiểu ý kiến của họ về sản phẩm mới.\nDương Đồng Lạc: Vậy em phải chuẩn bị trước các câu hỏi, để thuận tiện giao tiếp với khách hàng.\nĐồng nghiệp: Vâng, em đã chuẩn bị sẵn một số câu hỏi rồi.\nDương Đồng Lạc: Tốt lắm. Đã đi công tác không lâu thì phải sắp xếp thời gian tốt, thu thập nhiều thông tin hữu ích.","audio_dialogue":"7-3.mp3","audio_vocab":"7-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"前段时间，杨同乐的同事谈成了一笔不错的生意。刚开始，这位同事也遇到了一些困难。拿和客户交流来说，虽然她能把产品的优缺点说得很清楚，但实际效果并不理想。杨同乐告诉她，这是因为她介绍的方式都一样。其实，不同年龄、不同性别的客户对产品的关注点是不一样的。于是，这位同事又认真地进行了几次市场调查，了解不同客户的想法。后来她在面对不同客户时，能根据他们的情况介绍产品，效果一下就好了很多。","pinyin":"Qián duàn shíjiān, Yáng Tónglè de tóngshì tánchéng le yì bǐ búcuò de shēngyi. Gāng kāishǐ, zhè wèi tóngshì yě yùdào le yìxiē kùnnan. Ná hé kèhù jiāoliú lái shuō, suīrán tā néng bǎ chǎnpǐn de yōuquēdiǎn shuō de hěn qīngchu, dàn shíjì xiàoguǒ bìng bù lǐxiǎng. Yáng Tónglè gàosu tā, zhè shì yīnwèi tā jièshào de fāngshì dōu yíyàng. Qíshí, bùtóng niánlíng, bùtóng xìngbié de kèhù duì chǎnpǐn de guānzhùdiǎn shì bù yíyàng de. Yúshì, zhè wèi tóngshì yòu rènzhēn de jìnxíng le jǐ cì shìchǎng diàochá, liǎojiě bùtóng kèhù de xiǎngfǎ. Hòulái tā zài miànduì bùtóng kèhù shí, néng gēnjù tāmen de qíngkuàng jièshào chǎnpǐn, xiàoguǒ yíxià jiù hǎo le hěn duō."}],"translation_vn":"Một thời gian trước, đồng nghiệp của Dương Đồng Lạc đã đàm phán thành công một thương vụ khá tốt. Lúc đầu, đồng nghiệp này cũng gặp phải một số khó khăn. Lấy việc giao tiếp với khách hàng mà nói, tuy cô ấy có thể trình bày rõ ràng ưu nhược điểm của sản phẩm, nhưng hiệu quả thực tế lại không như ý. Dương Đồng Lạc nói với cô ấy rằng đó là vì cách giới thiệu của cô lúc nào cũng giống nhau. Thực ra, khách hàng ở độ tuổi khác nhau, giới tính khác nhau sẽ có những điểm quan tâm khác nhau đối với sản phẩm. Thế là, đồng nghiệp này lại nghiêm túc tiến hành khảo sát thị trường thêm vài lần nữa, tìm hiểu suy nghĩ của các khách hàng khác nhau. Sau đó khi đối diện với các khách hàng khác nhau, cô ấy có thể giới thiệu sản phẩm theo tình hình của từng người, hiệu quả nhờ đó tốt lên rất nhiều.","audio_dialogue":"7-5.mp3","audio_vocab":"7-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"有的年轻人经常换工作，总觉得下一份工作会更好。但是，适应新工作往往需要比较长的时间。如果总是换工作，不但很难积累经验，还可能会使自己的发展受到影响。我认为，年轻人刚进入社会时，不能只关心工资的高低，更要重视学习。比如，学习课本中没有的专业知识，了解公司的管理方式，学会和同事有效交流，等等。只有把这些基础打好，提高工作能力，今后才会有更好的发展机会。","pinyin":"Yǒude niánqīngrén jīngcháng huàn gōngzuò, zǒng juéde xià yí fèn gōngzuò huì gèng hǎo. Dànshì, shìyìng xīn gōngzuò wǎngwǎng xūyào bǐjiào cháng de shíjiān. Rúguǒ zǒngshì huàn gōngzuò, búdàn hěn nán jīlěi jīngyàn, hái kěnéng huì shǐ zìjǐ de fāzhǎn shòudào yǐngxiǎng. Wǒ rènwéi, niánqīngrén gāng jìnrù shèhuì shí, bù néng zhǐ guānxīn gōngzī de gāodī, gèng yào zhòngshì xuéxí. Bǐrú, xuéxí kèběn zhōng méiyǒu de zhuānyè zhīshi, liǎojiě gōngsī de guǎnlǐ fāngshì, xuéhuì hé tóngshì yǒuxiào jiāoliú, děngděng. Zhǐyǒu bǎ zhèxiē jīchǔ dǎhǎo, tígāo gōngzuò nénglì, jīnhòu cái huì yǒu gèng hǎo de fāzhǎn jīhuì."}],"translation_vn":"Có những người trẻ thường xuyên đổi việc, luôn cảm thấy công việc tiếp theo sẽ tốt hơn. Nhưng thích nghi với công việc mới thường cần một khoảng thời gian khá dài. Nếu cứ liên tục đổi việc, không những khó tích lũy kinh nghiệm, mà còn có thể khiến sự phát triển của bản thân bị ảnh hưởng. Tôi cho rằng, khi người trẻ mới bước vào xã hội, không nên chỉ quan tâm đến mức lương cao hay thấp, mà càng phải coi trọng việc học hỏi. Ví dụ như học những kiến thức chuyên môn không có trong sách giáo khoa, tìm hiểu cách quản lý của công ty, học cách giao tiếp hiệu quả với đồng nghiệp, v.v. Chỉ khi xây dựng tốt những nền tảng này, nâng cao năng lực làm việc, thì sau này mới có cơ hội phát triển tốt hơn.","audio_dialogue":"7-7.mp3","audio_vocab":"7-8.mp3"}]},{"id":8,"title_cn":"该放松时就放松","title_pinyin":"Gāi fàngsōng shí jiù fàngsōng","title_vn":"Khi cần thư giãn thì hãy thư giãn","goals":["Có thể nghe hiểu và trao đổi về các chủ đề liên quan đến phương pháp và cách thức giảm căng thẳng.","Có thể trình bày bằng lời nói hoặc văn bản quan điểm về việc giảm căng thẳng và thư giãn.","Hiểu được vào cuối tuần người Trung Quốc thường đi đâu để thư giãn."],"vocab":[{"hanzi":"紧张","pinyin":"jǐnzhāng","pos":"tt.","vn":"căng thẳng; (nguồn cung) khan hiếm","examples":[{"cn":"我第一次上台演讲，特别紧张。","pinyin":"wǒ dì yī cì shàngtái yǎnjiǎng, tèbié jǐnzhāng.","vn":"Lần đầu tiên lên sân khấu diễn thuyết, tôi rất căng thẳng."},{"cn":"最近工作太忙了，生活节奏一直很紧张。","pinyin":"zuìjìn gōngzuò tài máng le, shēnghuó jiézòu yìzhí hěn jǐnzhāng.","vn":"Dạo này công việc quá bận, nhịp sống luôn căng thẳng."},{"cn":"过年期间火车票很紧张，要提前订。","pinyin":"guònián qījiān huǒchēpiào hěn jǐnzhāng, yào tíqián dìng.","vn":"Dịp Tết vé tàu rất khan hiếm, phải đặt trước."}]},{"hanzi":"放松","pinyin":"fàngsōng","pos":"dgt.","vn":"thư giãn, thả lỏng","examples":[{"cn":"周末我喜欢听听音乐，放松一下。","pinyin":"zhōumò wǒ xǐhuan tīngting yīnyuè, fàngsōng yíxià.","vn":"Cuối tuần tôi thích nghe nhạc để thư giãn một chút."},{"cn":"考完试了，终于可以放松放松了。","pinyin":"kǎowán shì le, zhōngyú kěyǐ fàngsōng fàngsōng le.","vn":"Thi xong rồi, cuối cùng cũng có thể thư giãn một chút."},{"cn":"深呼吸，放松身体，别那么紧张。","pinyin":"shēn hūxī, fàngsōng shēntǐ, bié nàme jǐnzhāng.","vn":"Hít thở sâu, thả lỏng cơ thể, đừng căng thẳng như vậy."}]},{"hanzi":"呀","pinyin":"yā","pos":"ct.","vn":"ôi, ồ (thán từ)","examples":[{"cn":"呀，下雨了！快把衣服收进来。","pinyin":"yā, xiàyǔ le! kuài bǎ yīfu shōu jìnlái.","vn":"Ôi, trời mưa rồi! Mau thu quần áo vào đi."},{"cn":"呀，这个蛋糕看起来好好吃啊！","pinyin":"yā, zhège dàngāo kànqǐlái hǎo hǎochī a!","vn":"Ồ, cái bánh này trông ngon quá đi!"},{"cn":"呀，我把钥匙忘在家里了。","pinyin":"yā, wǒ bǎ yàoshi wàng zài jiā lǐ le.","vn":"Ôi, tôi để quên chìa khóa ở nhà rồi."}]},{"hanzi":"不管","pinyin":"bùguǎn","pos":"liên.","vn":"bất kể, dù cho","examples":[{"cn":"不管多忙，他每天都抽时间陪孩子。","pinyin":"bùguǎn duō máng, tā měitiān dōu chōu shíjiān péi háizi.","vn":"Dù bận đến đâu, anh ấy mỗi ngày đều dành thời gian ở bên con."},{"cn":"不管别人怎么说，我都要坚持自己的想法。","pinyin":"bùguǎn biéren zěnme shuō, wǒ dōu yào jiānchí zìjǐ de xiǎngfǎ.","vn":"Dù người khác nói thế nào, tôi vẫn kiên trì suy nghĩ của mình."},{"cn":"不管刮风下雨，他都坚持跑步。","pinyin":"bùguǎn guāfēng xiàyǔ, tā dōu jiānchí pǎobù.","vn":"Bất kể mưa gió, anh ấy đều kiên trì chạy bộ."}]},{"hanzi":"郊区","pinyin":"jiāoqū","pos":"dt.","vn":"ngoại ô","examples":[{"cn":"我家住在郊区，空气比市区好多了。","pinyin":"wǒ jiā zhù zài jiāoqū, kōngqì bǐ shìqū hǎo duō le.","vn":"Nhà tôi ở ngoại ô, không khí tốt hơn nội thành nhiều."},{"cn":"周末我们打算去郊区爬山。","pinyin":"zhōumò wǒmen dǎsuàn qù jiāoqū páshān.","vn":"Cuối tuần chúng tôi định đi leo núi ở ngoại ô."},{"cn":"这家餐厅开在郊区，环境特别安静。","pinyin":"zhè jiā cāntīng kāi zài jiāoqū, huánjìng tèbié ānjìng.","vn":"Nhà hàng này mở ở ngoại ô, môi trường rất yên tĩnh."}]},{"hanzi":"游玩","pinyin":"yóuwán","pos":"dgt.","vn":"đi chơi, du ngoạn","examples":[{"cn":"我们打算这个周末去公园游玩。","pinyin":"wǒmen dǎsuàn zhège zhōumò qù gōngyuán yóuwán.","vn":"Chúng tôi định cuối tuần này đi công viên chơi."},{"cn":"暑假我带孩子去海边游玩了几天。","pinyin":"shǔjià wǒ dài háizi qù hǎibiān yóuwán le jǐ tiān.","vn":"Nghỉ hè tôi đưa con đi chơi ở biển mấy ngày."},{"cn":"这个景点很适合一家人游玩。","pinyin":"zhège jǐngdiǎn hěn shìhé yì jiā rén yóuwán.","vn":"Điểm tham quan này rất thích hợp cho cả gia đình đi chơi."}]},{"hanzi":"主意","pinyin":"zhǔyi","pos":"dt.","vn":"ý kiến, chủ ý","examples":[{"cn":"他突然想到一个好主意。","pinyin":"tā tūrán xiǎngdào yí ge hǎo zhǔyi.","vn":"Anh ấy bỗng nghĩ ra một ý kiến hay."},{"cn":"你拿个主意吧，我都行。","pinyin":"nǐ ná ge zhǔyi ba, wǒ dōu xíng.","vn":"Bạn quyết định đi, tôi sao cũng được."},{"cn":"别总是改主意，这样很难做决定。","pinyin":"bié zǒngshì gǎi zhǔyi, zhèyàng hěn nán zuò juédìng.","vn":"Đừng cứ đổi ý suốt, như vậy rất khó đưa ra quyết định."}]},{"hanzi":"外出","pinyin":"wàichū","pos":"dgt.","vn":"ra ngoài, đi ra ngoài","examples":[{"cn":"外出的时候请记得带上雨伞。","pinyin":"wàichū de shíhou qǐng jìde dàishàng yǔsǎn.","vn":"Khi ra ngoài xin nhớ mang theo ô."},{"cn":"他经常外出办事，很少在办公室。","pinyin":"tā jīngcháng wàichū bànshì, hěn shǎo zài bàngōngshì.","vn":"Anh ấy thường xuyên ra ngoài giải quyết việc, ít khi ở văn phòng."},{"cn":"外出旅行前要检查好所有证件。","pinyin":"wàichū lǚxíng qián yào jiǎnchá hǎo suǒyǒu zhèngjiàn.","vn":"Trước khi ra ngoài du lịch phải kiểm tra kỹ tất cả giấy tờ."}]},{"hanzi":"戴","pinyin":"dài","pos":"dgt.","vn":"đội, đeo","examples":[{"cn":"外面很冷，出门记得戴手套。","pinyin":"wàimian hěn lěng, chūmén jìde dài shǒutào.","vn":"Bên ngoài rất lạnh, ra ngoài nhớ đeo găng tay."},{"cn":"她戴着一副好看的眼镜。","pinyin":"tā dàizhe yí fù hǎokàn de yǎnjìng.","vn":"Cô ấy đang đeo một cặp kính rất đẹp."},{"cn":"骑车的时候一定要戴头盔。","pinyin":"qíchē de shíhou yídìng yào dài tóukuī.","vn":"Khi đi xe nhất định phải đội mũ bảo hiểm."}]},{"hanzi":"帽子","pinyin":"màozi","pos":"dt.","vn":"mũ, nón","examples":[{"cn":"今天太阳很大，我戴了一顶帽子。","pinyin":"jīntiān tàiyáng hěn dà, wǒ dài le yì dǐng màozi.","vn":"Hôm nay nắng to, tôi đã đội một chiếc mũ."},{"cn":"这顶帽子是我妈妈送我的生日礼物。","pinyin":"zhè dǐng màozi shì wǒ māma sòng wǒ de shēngrì lǐwù.","vn":"Chiếc mũ này là quà sinh nhật mẹ tặng tôi."},{"cn":"风太大了，他的帽子被吹跑了。","pinyin":"fēng tài dà le, tā de màozi bèi chuīpǎo le.","vn":"Gió quá to, mũ của anh ấy bị thổi bay mất."}]},{"hanzi":"长城","pinyin":"Chángchéng","pos":"danh từ riêng","vn":"Vạn Lý Trường Thành","examples":[{"cn":"我终于有机会去长城看看了。","pinyin":"wǒ zhōngyú yǒu jīhuì qù Chángchéng kànkan le.","vn":"Cuối cùng tôi cũng có cơ hội đi xem Vạn Lý Trường Thành."},{"cn":"长城是中国最有名的景点之一。","pinyin":"Chángchéng shì Zhōngguó zuì yǒumíng de jǐngdiǎn zhī yī.","vn":"Vạn Lý Trường Thành là một trong những điểm tham quan nổi tiếng nhất Trung Quốc."},{"cn":"站在长城上，风景真是太美了。","pinyin":"zhàn zài Chángchéng shàng, fēngjǐng zhēnshi tài měi le.","vn":"Đứng trên Vạn Lý Trường Thành, phong cảnh thật sự quá đẹp."}]},{"hanzi":"项目","pinyin":"xiàngmù","pos":"dt.","vn":"dự án","examples":[{"cn":"我们公司正在做一个新项目。","pinyin":"wǒmen gōngsī zhèngzài zuò yí ge xīn xiàngmù.","vn":"Công ty chúng tôi đang làm một dự án mới."},{"cn":"这个项目下个月就要结束了。","pinyin":"zhège xiàngmù xià ge yuè jiù yào jiéshù le.","vn":"Dự án này tháng sau sẽ kết thúc."},{"cn":"他被安排负责这个重要项目。","pinyin":"tā bèi ānpái fùzé zhège zhòngyào xiàngmù.","vn":"Anh ấy được phân công phụ trách dự án quan trọng này."}]},{"hanzi":"加班","pinyin":"jiābān","pos":"dgt.","vn":"làm thêm giờ, tăng ca","examples":[{"cn":"今天任务太多了，我得加班。","pinyin":"jīntiān rènwù tài duō le, wǒ děi jiābān.","vn":"Hôm nay việc quá nhiều, tôi phải làm thêm giờ."},{"cn":"他经常加班到很晚才回家。","pinyin":"tā jīngcháng jiābān dào hěn wǎn cái huíjiā.","vn":"Anh ấy thường xuyên tăng ca đến rất khuya mới về nhà."},{"cn":"周末还要加班，真是太累了。","pinyin":"zhōumò hái yào jiābān, zhēnshi tài lèi le.","vn":"Cuối tuần còn phải làm thêm giờ, thật sự quá mệt."}]},{"hanzi":"熬夜","pinyin":"áoyè","pos":"dgt.","vn":"thức khuya","examples":[{"cn":"为了赶报告，他昨晚熬夜到很晚。","pinyin":"wèile gǎn bàogào, tā zuówǎn áoyè dào hěn wǎn.","vn":"Để kịp báo cáo, tối qua anh ấy thức khuya đến rất muộn."},{"cn":"经常熬夜对身体不好。","pinyin":"jīngcháng áoyè duì shēntǐ bù hǎo.","vn":"Thức khuya thường xuyên không tốt cho sức khỏe."},{"cn":"我昨天熬夜看球赛，今天特别困。","pinyin":"wǒ zuótiān áoyè kàn qiúsài, jīntiān tèbié kùn.","vn":"Hôm qua tôi thức khuya xem bóng đá, hôm nay buồn ngủ ghê."}]},{"hanzi":"否则","pinyin":"fǒuzé","pos":"liên.","vn":"nếu không thì","examples":[{"cn":"你得早点出发，否则就赶不上火车了。","pinyin":"nǐ děi zǎodiǎn chūfā, fǒuzé jiù gǎnbushàng huǒchē le.","vn":"Bạn phải xuất phát sớm hơn, nếu không sẽ lỡ tàu đấy."},{"cn":"多穿点衣服，否则会感冒的。","pinyin":"duō chuān diǎn yīfu, fǒuzé huì gǎnmào de.","vn":"Mặc thêm quần áo, không thì sẽ bị cảm đấy."},{"cn":"我们要抓紧时间完成，否则来不及了。","pinyin":"wǒmen yào zhuājǐn shíjiān wánchéng, fǒuzé láibují le.","vn":"Chúng ta phải tranh thủ thời gian hoàn thành, nếu không sẽ không kịp."}]},{"hanzi":"失去","pinyin":"shīqù","pos":"dgt.","vn":"mất đi, đánh mất","examples":[{"cn":"他因为一次错误失去了这份工作。","pinyin":"tā yīnwèi yí cì cuòwù shīqù le zhè fèn gōngzuò.","vn":"Anh ấy vì một sai lầm mà mất đi công việc này."},{"cn":"健康失去了就很难再找回来。","pinyin":"jiànkāng shīqù le jiù hěn nán zài zhǎohuílái.","vn":"Sức khỏe đã mất đi thì rất khó tìm lại được."},{"cn":"别让机会白白失去了。","pinyin":"bié ràng jīhuì báibái shīqù le.","vn":"Đừng để cơ hội uổng phí trôi mất."}]},{"hanzi":"值得","pinyin":"zhídé","pos":"dgt.","vn":"đáng, xứng đáng","examples":[{"cn":"这部电影真的很值得一看。","pinyin":"zhè bù diànyǐng zhēnde hěn zhídé yí kàn.","vn":"Bộ phim này thực sự rất đáng xem."},{"cn":"为了这个结果，一切付出都值得。","pinyin":"wèile zhège jiéguǒ, yíqiè fùchū dōu zhídé.","vn":"Vì kết quả này, mọi công sức bỏ ra đều xứng đáng."},{"cn":"他的建议很值得我们参考。","pinyin":"tā de jiànyì hěn zhídé wǒmen cānkǎo.","vn":"Gợi ý của anh ấy rất đáng để chúng ta tham khảo."}]},{"hanzi":"暂停","pinyin":"zàntíng","pos":"dgt.","vn":"tạm dừng","examples":[{"cn":"因为下大雨，比赛暂停了一会儿。","pinyin":"yīnwèi xià dàyǔ, bǐsài zàntíng le yíhuìr.","vn":"Vì mưa to, trận đấu đã tạm dừng một lúc."},{"cn":"这个项目因为资金问题暂停了。","pinyin":"zhège xiàngmù yīnwèi zījīn wèntí zàntíng le.","vn":"Dự án này vì vấn đề kinh phí đã bị tạm dừng."},{"cn":"我们先暂停讨论，休息十分钟再继续。","pinyin":"wǒmen xiān zàntíng tǎolùn, xiūxi shí fēnzhōng zài jìxù.","vn":"Chúng ta tạm dừng thảo luận trước, nghỉ mười phút rồi tiếp tục."}]},{"hanzi":"之后","pinyin":"zhīhòu","pos":"dt.","vn":"sau đó, sau khi","examples":[{"cn":"下班之后我们一起去吃饭吧。","pinyin":"xiàbān zhīhòu wǒmen yìqǐ qù chīfàn ba.","vn":"Sau khi tan làm chúng ta cùng đi ăn cơm nhé."},{"cn":"毕业之后他就去北京工作了。","pinyin":"bìyè zhīhòu tā jiù qù Běijīng gōngzuò le.","vn":"Sau khi tốt nghiệp, anh ấy đã đi Bắc Kinh làm việc."},{"cn":"之后的事情我们再慢慢商量。","pinyin":"zhīhòu de shìqing wǒmen zài mànmàn shāngliang.","vn":"Những việc sau đó chúng ta từ từ bàn bạc tiếp."}]},{"hanzi":"风景","pinyin":"fēngjǐng","pos":"dt.","vn":"phong cảnh","examples":[{"cn":"这里的风景真美，让人心情愉快。","pinyin":"zhèlǐ de fēngjǐng zhēn měi, ràng rén xīnqíng yúkuài.","vn":"Phong cảnh ở đây thật đẹp, khiến người ta vui vẻ."},{"cn":"我们开车沿着海边，一路风景特别好。","pinyin":"wǒmen kāichē yánzhe hǎibiān, yílù fēngjǐng tèbié hǎo.","vn":"Chúng tôi lái xe dọc bờ biển, suốt chặng đường phong cảnh rất đẹp."},{"cn":"这张照片把当地的风景拍得非常漂亮。","pinyin":"zhè zhāng zhàopiàn bǎ dāngdì de fēngjǐng pāi de fēicháng piàoliang.","vn":"Bức ảnh này chụp phong cảnh địa phương rất đẹp."}]},{"hanzi":"效率","pinyin":"xiàolǜ","pos":"dt.","vn":"hiệu suất","examples":[{"cn":"用了新软件以后，工作效率提高了不少。","pinyin":"yòng le xīn ruǎnjiàn yǐhòu, gōngzuò xiàolǜ tígāo le bùshǎo.","vn":"Sau khi dùng phần mềm mới, hiệu suất công việc đã tăng lên không ít."},{"cn":"他做事效率很高，总能提前完成任务。","pinyin":"tā zuòshì xiàolǜ hěn gāo, zǒng néng tíqián wánchéng rènwù.","vn":"Anh ấy làm việc rất hiệu quả, luôn hoàn thành nhiệm vụ sớm."},{"cn":"开会时间太长会影响大家的效率。","pinyin":"kāihuì shíjiān tài cháng huì yǐngxiǎng dàjiā de xiàolǜ.","vn":"Họp quá lâu sẽ ảnh hưởng đến hiệu suất của mọi người."}]},{"hanzi":"下降","pinyin":"xiàjiàng","pos":"dgt.","vn":"giảm xuống, hạ xuống","examples":[{"cn":"最近公司的销售量下降了很多。","pinyin":"zuìjìn gōngsī de xiāoshòuliàng xiàjiàng le hěn duō.","vn":"Dạo này doanh số của công ty đã giảm xuống nhiều."},{"cn":"气温下降了，大家要注意保暖。","pinyin":"qìwēn xiàjiàng le, dàjiā yào zhùyì bǎonuǎn.","vn":"Nhiệt độ đã giảm xuống, mọi người cần chú ý giữ ấm."},{"cn":"熬夜太多会使记忆力下降。","pinyin":"áoyè tài duō huì shǐ jìyìlì xiàjiàng.","vn":"Thức khuya quá nhiều sẽ làm trí nhớ giảm sút."}]},{"hanzi":"相比","pinyin":"xiāngbǐ","pos":"dgt.","vn":"so với, so sánh","examples":[{"cn":"跟以前相比，现在的生活方便多了。","pinyin":"gēn yǐqián xiāngbǐ, xiànzài de shēnghuó fāngbiàn duō le.","vn":"So với trước đây, cuộc sống hiện nay tiện lợi hơn nhiều."},{"cn":"这两种方法相比，我觉得第二种更有效。","pinyin":"zhè liǎng zhǒng fāngfǎ xiāngbǐ, wǒ juéde dì èr zhǒng gèng yǒuxiào.","vn":"So sánh hai phương pháp này, tôi thấy cách thứ hai hiệu quả hơn."},{"cn":"跟城市相比，这里的空气新鲜多了。","pinyin":"gēn chéngshì xiāngbǐ, zhèlǐ de kōngqì xīnxiān duō le.","vn":"So với thành phố, không khí ở đây trong lành hơn nhiều."}]},{"hanzi":"因此","pinyin":"yīncǐ","pos":"liên.","vn":"do đó, vì vậy","examples":[{"cn":"他工作很努力，因此得到了老板的赏识。","pinyin":"tā gōngzuò hěn nǔlì, yīncǐ dédào le lǎobǎn de shǎngshí.","vn":"Anh ấy làm việc rất chăm chỉ, do đó được sếp đánh giá cao."},{"cn":"最近下雨太多，因此交通变得很堵。","pinyin":"zuìjìn xiàyǔ tài duō, yīncǐ jiāotōng biàn de hěn dǔ.","vn":"Gần đây mưa quá nhiều, vì vậy giao thông trở nên ùn tắc."},{"cn":"她身体不舒服，因此今天请假没来上班。","pinyin":"tā shēntǐ bù shūfu, yīncǐ jīntiān qǐngjià méi lái shàngbān.","vn":"Cô ấy không khỏe trong người, vì vậy hôm nay xin nghỉ không đi làm."}]},{"hanzi":"提醒","pinyin":"tíxǐng","pos":"dgt.","vn":"nhắc nhở","examples":[{"cn":"谢谢你提醒我，不然我就忘了。","pinyin":"xièxie nǐ tíxǐng wǒ, bùrán wǒ jiù wàng le.","vn":"Cảm ơn bạn đã nhắc tôi, không thì tôi đã quên mất rồi."},{"cn":"妈妈每天都提醒我多穿点衣服。","pinyin":"māma měitiān dōu tíxǐng wǒ duō chuān diǎn yīfu.","vn":"Mẹ mỗi ngày đều nhắc tôi mặc thêm quần áo."},{"cn":"老师提醒大家明天考试要带铅笔。","pinyin":"lǎoshī tíxǐng dàjiā míngtiān kǎoshì yào dài qiānbǐ.","vn":"Thầy giáo nhắc nhở mọi người ngày mai thi phải mang bút chì."}]},{"hanzi":"与","pinyin":"yǔ","pos":"giới./liên.","vn":"với; và","examples":[{"cn":"这件事与你没有任何关系。","pinyin":"zhè jiàn shì yǔ nǐ méiyǒu rènhé guānxì.","vn":"Chuyện này không liên quan gì đến bạn."},{"cn":"成功与努力是分不开的。","pinyin":"chénggōng yǔ nǔlì shì fēnbukāi de.","vn":"Thành công và sự nỗ lực là không thể tách rời."},{"cn":"他与朋友一起开了一家小店。","pinyin":"tā yǔ péngyou yìqǐ kāi le yì jiā xiǎo diàn.","vn":"Anh ấy cùng bạn mở một cửa hàng nhỏ."}]},{"hanzi":"大自然","pinyin":"dàzìrán","pos":"dt.","vn":"thiên nhiên","examples":[{"cn":"我们应该保护大自然，爱护环境。","pinyin":"wǒmen yīnggāi bǎohù dàzìrán, àihù huánjìng.","vn":"Chúng ta nên bảo vệ thiên nhiên, giữ gìn môi trường."},{"cn":"周末我喜欢去郊外接触大自然。","pinyin":"zhōumò wǒ xǐhuan qù jiāowài jiēchù dàzìrán.","vn":"Cuối tuần tôi thích ra ngoại ô để gần gũi với thiên nhiên."},{"cn":"大自然真是太神奇了，什么都能找到答案。","pinyin":"dàzìrán zhēnshi tài shénqí le, shénme dōu néng zhǎodào dá'àn.","vn":"Thiên nhiên thật kỳ diệu, cái gì cũng có thể tìm thấy câu trả lời."}]},{"hanzi":"美丽","pinyin":"měilì","pos":"tt.","vn":"đẹp, xinh đẹp","examples":[{"cn":"这座城市真美丽，到处都是绿树和花。","pinyin":"zhè zuò chéngshì zhēn měilì, dàochù dōu shì lǜshù hé huā.","vn":"Thành phố này thật đẹp, khắp nơi đều là cây xanh và hoa."},{"cn":"她今天穿得特别美丽。","pinyin":"tā jīntiān chuān de tèbié měilì.","vn":"Hôm nay cô ấy ăn mặc đặc biệt xinh đẹp."},{"cn":"桂林的山水非常美丽，是著名的旅游景点。","pinyin":"Guìlín de shānshuǐ fēicháng měilì, shì zhùmíng de lǚyóu jǐngdiǎn.","vn":"Sơn thủy Quế Lâm rất đẹp, là điểm du lịch nổi tiếng."}]},{"hanzi":"景色","pinyin":"jǐngsè","pos":"dt.","vn":"cảnh sắc, phong cảnh","examples":[{"cn":"山顶上的景色让人看了忘不了。","pinyin":"shāndǐng shàng de jǐngsè ràng rén kàn le wàngbuliǎo.","vn":"Cảnh sắc trên đỉnh núi khiến người ta xem rồi không thể quên."},{"cn":"秋天的景色特别好看，到处都是红叶。","pinyin":"qiūtiān de jǐngsè tèbié hǎokàn, dàochù dōu shì hóngyè.","vn":"Cảnh sắc mùa thu đặc biệt đẹp, khắp nơi đều là lá đỏ."},{"cn":"从窗户望出去，外面的景色非常漂亮。","pinyin":"cóng chuānghu wàng chūqù, wàimian de jǐngsè fēicháng piàoliang.","vn":"Nhìn ra từ cửa sổ, cảnh sắc bên ngoài rất đẹp."}]},{"hanzi":"首都","pinyin":"shǒudū","pos":"dt.","vn":"thủ đô","examples":[{"cn":"北京是中国的首都。","pinyin":"Běijīng shì Zhōngguó de shǒudū.","vn":"Bắc Kinh là thủ đô của Trung Quốc."},{"cn":"我打算暑假去首都旅游。","pinyin":"wǒ dǎsuàn shǔjià qù shǒudū lǚyóu.","vn":"Tôi dự định nghỉ hè đi du lịch thủ đô."},{"cn":"首都的交通一般都比较拥挤。","pinyin":"shǒudū de jiāotōng yìbān dōu bǐjiào yōngjǐ.","vn":"Giao thông ở thủ đô nhìn chung thường khá đông đúc."}]},{"hanzi":"市区","pinyin":"shìqū","pos":"dt.","vn":"khu vực nội thành","examples":[{"cn":"我们公司在市区，交通很方便。","pinyin":"wǒmen gōngsī zài shìqū, jiāotōng hěn fāngbiàn.","vn":"Công ty chúng tôi ở khu nội thành, giao thông rất tiện lợi."},{"cn":"市区的房租比郊区贵不少。","pinyin":"shìqū de fángzū bǐ jiāoqū guì bùshǎo.","vn":"Tiền thuê nhà ở nội thành đắt hơn ngoại ô nhiều."},{"cn":"周末市区人太多了，我们还是去郊区吧。","pinyin":"zhōumò shìqū rén tài duō le, wǒmen háishi qù jiāoqū ba.","vn":"Cuối tuần nội thành đông người quá, chúng ta đi ngoại ô thôi."}]},{"hanzi":"眼前","pinyin":"yǎnqián","pos":"dt.","vn":"trước mắt","examples":[{"cn":"眼前的这片风景让大家都惊呆了。","pinyin":"yǎnqián de zhè piàn fēngjǐng ràng dàjiā dōu jīngdāi le.","vn":"Cảnh tượng trước mắt khiến mọi người đều sững sờ."},{"cn":"我们先解决眼前的问题，别想太远。","pinyin":"wǒmen xiān jiějué yǎnqián de wèntí, bié xiǎng tài yuǎn.","vn":"Chúng ta giải quyết vấn đề trước mắt trước, đừng nghĩ quá xa."},{"cn":"到了山顶，眼前是一片美丽的景色。","pinyin":"dào le shāndǐng, yǎnqián shì yí piàn měilì de jǐngsè.","vn":"Lên đến đỉnh núi, trước mắt là một khung cảnh đẹp."}]},{"hanzi":"美景","pinyin":"měijǐng","pos":"dt.","vn":"cảnh đẹp","examples":[{"cn":"这里的美景吸引了很多游客前来参观。","pinyin":"zhèlǐ de měijǐng xīyǐn le hěn duō yóukè qiánlái cānguān.","vn":"Cảnh đẹp ở đây đã thu hút rất nhiều du khách đến tham quan."},{"cn":"我想用相机把这片美景拍下来。","pinyin":"wǒ xiǎng yòng xiàngjī bǎ zhè piàn měijǐng pāixiàlái.","vn":"Tôi muốn dùng máy ảnh chụp lại cảnh đẹp này."},{"cn":"黄山的美景真是让人流连忘返。","pinyin":"Huángshān de měijǐng zhēnshi ràng rén liúlián wàngfǎn.","vn":"Cảnh đẹp của núi Hoàng Sơn thực sự khiến người ta lưu luyến không muốn rời."}]},{"hanzi":"参观","pinyin":"cānguān","pos":"dgt.","vn":"tham quan","examples":[{"cn":"明天我们要去博物馆参观。","pinyin":"míngtiān wǒmen yào qù bówùguǎn cānguān.","vn":"Ngày mai chúng tôi sẽ đi tham quan bảo tàng."},{"cn":"欢迎大家来我们学校参观。","pinyin":"huānyíng dàjiā lái wǒmen xuéxiào cānguān.","vn":"Hoan nghênh mọi người đến tham quan trường chúng tôi."},{"cn":"参观完故宫以后，我对中国历史更感兴趣了。","pinyin":"cānguān wán Gùgōng yǐhòu, wǒ duì Zhōngguó lìshǐ gèng gǎn xìngqù le.","vn":"Sau khi tham quan Cố Cung xong, tôi càng thêm hứng thú với lịch sử Trung Quốc."}]},{"hanzi":"景点","pinyin":"jǐngdiǎn","pos":"dt.","vn":"điểm tham quan, danh lam thắng cảnh","examples":[{"cn":"这个城市有很多著名的景点。","pinyin":"zhège chéngshì yǒu hěn duō zhùmíng de jǐngdiǎn.","vn":"Thành phố này có rất nhiều điểm tham quan nổi tiếng."},{"cn":"暑假景点里到处都是游客。","pinyin":"shǔjià jǐngdiǎn lǐ dàochù dōu shì yóukè.","vn":"Nghỉ hè ở các điểm tham quan khắp nơi đều là du khách."},{"cn":"我们打算把每个景点都走一遍。","pinyin":"wǒmen dǎsuàn bǎ měi ge jǐngdiǎn dōu zǒu yí biàn.","vn":"Chúng tôi dự định đi qua từng điểm tham quan một."}]},{"hanzi":"交通","pinyin":"jiāotōng","pos":"dt.","vn":"giao thông","examples":[{"cn":"这个城市的交通特别方便。","pinyin":"zhège chéngshì de jiāotōng tèbié fāngbiàn.","vn":"Giao thông của thành phố này đặc biệt thuận tiện."},{"cn":"下班高峰期交通很堵，建议坐地铁。","pinyin":"xiàbān gāofēngqī jiāotōng hěn dǔ, jiànyì zuò dìtiě.","vn":"Giờ cao điểm tan tầm giao thông rất tắc, nên đi tàu điện ngầm."},{"cn":"过马路要注意交通安全。","pinyin":"guò mǎlù yào zhùyì jiāotōng ānquán.","vn":"Qua đường phải chú ý an toàn giao thông."}]},{"hanzi":"乘坐","pinyin":"chéngzuò","pos":"dgt.","vn":"đi, ngồi (xe, tàu...)","examples":[{"cn":"我们乘坐火车去上海。","pinyin":"wǒmen chéngzuò huǒchē qù Shànghǎi.","vn":"Chúng tôi đi tàu hỏa đến Thượng Hải."},{"cn":"请乘坐电梯到五楼。","pinyin":"qǐng chéngzuò diàntī dào wǔ lóu.","vn":"Xin đi thang máy lên tầng năm."},{"cn":"第一次乘坐飞机，她有点紧张。","pinyin":"dì yī cì chéngzuò fēijī, tā yǒudiǎn jǐnzhāng.","vn":"Lần đầu tiên đi máy bay, cô ấy hơi căng thẳng."}]},{"hanzi":"十分","pinyin":"shífēn","pos":"phó.","vn":"rất, vô cùng","examples":[{"cn":"这个消息让大家十分兴奋。","pinyin":"zhège xiāoxi ràng dàjiā shífēn xīngfèn.","vn":"Tin tức này khiến mọi người vô cùng phấn khích."},{"cn":"他对这次的结果十分满意。","pinyin":"tā duì zhè cì de jiéguǒ shífēn mǎnyì.","vn":"Anh ấy rất hài lòng với kết quả lần này."},{"cn":"这里的风景十分美丽，值得一来。","pinyin":"zhèlǐ de fēngjǐng shífēn měilì, zhídé yì lái.","vn":"Phong cảnh ở đây vô cùng đẹp, rất đáng để đến."}]},{"hanzi":"实际上","pinyin":"shíjìshàng","pos":"phó.","vn":"thực tế thì, trên thực tế","examples":[{"cn":"他看起来很忙，实际上没什么事做。","pinyin":"tā kànqǐlái hěn máng, shíjìshàng méi shénme shì zuò.","vn":"Anh ấy trông có vẻ bận, nhưng thực tế thì không có việc gì làm."},{"cn":"大家都以为她很严肃，实际上她很幽默。","pinyin":"dàjiā dōu yǐwéi tā hěn yánsù, shíjìshàng tā hěn yōumò.","vn":"Mọi người đều tưởng cô ấy nghiêm túc, nhưng thực tế cô ấy rất hài hước."},{"cn":"这个方法听起来复杂，实际上操作很简单。","pinyin":"zhège fāngfǎ tīngqǐlái fùzá, shíjìshàng cāozuò hěn jiǎndān.","vn":"Phương pháp này nghe có vẻ phức tạp, nhưng thực tế thao tác rất đơn giản."}]},{"hanzi":"故宫","pinyin":"Gùgōng","pos":"danh từ riêng","vn":"Cố Cung (Tử Cấm Thành)","examples":[{"cn":"去北京旅游一定要去故宫看看。","pinyin":"qù Běijīng lǚyóu yídìng yào qù Gùgōng kànkan.","vn":"Đi du lịch Bắc Kinh nhất định phải đến Cố Cung xem thử."},{"cn":"故宫是明清两代的皇宫。","pinyin":"Gùgōng shì Míng Qīng liǎng dài de huánggōng.","vn":"Cố Cung là hoàng cung của hai triều đại Minh và Thanh."},{"cn":"故宫里的建筑非常宏伟，让人印象深刻。","pinyin":"Gùgōng lǐ de jiànzhù fēicháng hóngwěi, ràng rén yìnxiàng shēnkè.","vn":"Các công trình kiến trúc trong Cố Cung rất hùng vĩ, để lại ấn tượng sâu sắc."}]}],"grammar":[{"title":"条件复句\"不管……，都/也……\"","explanation_vn":"Câu phức điều kiện \"不管……，都/也……\" (bất kể... đều/cũng...): vế trước nêu một điều kiện có khả năng xảy ra, vế sau biểu thị kết quả không thay đổi. Cấu trúc cơ bản: 不管 + điều kiện/tình huống/sự thay đổi, (chủ ngữ) + 都/也 + kết quả.","examples":[{"cn":"不管去哪儿，能放松的地方都行。","pinyin":"Bùguǎn qù nǎr, néng fàngsōng de dìfang dōu xíng.","vn":"Bất kể đi đâu, chỉ cần là nơi có thể thư giãn thì đều được."},{"cn":"不管有什么想法，你都要说出来，让我们知道。","pinyin":"Bùguǎn yǒu shénme xiǎngfǎ, nǐ dōu yào shuō chūlái, ràng wǒmen zhīdào.","vn":"Bất kể có suy nghĩ gì, bạn đều phải nói ra để chúng tôi biết."},{"cn":"不管遇到多大困难，我们也要坚持，最后一定能完成任务。","pinyin":"Bùguǎn yùdào duō dà kùnnan, wǒmen yě yào jiānchí, zuìhòu yídìng néng wánchéng rènwù.","vn":"Bất kể gặp phải khó khăn lớn đến đâu, chúng ta cũng phải kiên trì, cuối cùng nhất định sẽ hoàn thành được nhiệm vụ."}]},{"title":"假设复句\"……，否则……\"","explanation_vn":"Câu phức giả thiết \"……，否则……\" (…, nếu không thì…): vế trước nêu ra yêu cầu, đề nghị hoặc điều kiện, vế sau nói rõ hậu quả sẽ xảy ra nếu tình huống ở vế trước không được thực hiện.","examples":[{"cn":"还是别给自己太大压力，否则，失去健康就不值得了。","pinyin":"Háishi bié gěi zìjǐ tài dà yālì, fǒuzé, shīqù jiànkāng jiù bù zhídé le.","vn":"Tốt nhất đừng tạo cho mình quá nhiều áp lực, nếu không, đánh mất sức khỏe thì không đáng chút nào."},{"cn":"今晚早点儿睡吧，否则明天早上起不来，又该迟到了。","pinyin":"Jīnwǎn zǎodiǎnr shuì ba, fǒuzé míngtiān zǎoshang qǐbulái, yòu gāi chídào le.","vn":"Tối nay ngủ sớm một chút đi, nếu không sáng mai dậy không nổi, lại trễ giờ mất."},{"cn":"吃不完的菜要放进冰箱，否则很容易坏。","pinyin":"Chībuwán de cài yào fàngjìn bīngxiāng, fǒuzé hěn róngyì huài.","vn":"Thức ăn không ăn hết phải cho vào tủ lạnh, nếu không rất dễ bị hỏng."}]},{"title":"比较句\"跟……相比\"","explanation_vn":"\"跟……相比\" (so với...) là cấu trúc biểu thị sự so sánh. Giới từ \"跟\" thường được dùng trong khẩu ngữ, trong những hoàn cảnh không trang trọng lắm. Trong văn viết, trong những hoàn cảnh trang trọng thường dùng \"与\".","examples":[{"cn":"跟一直加班相比，休息好了再工作，效率更高。","pinyin":"Gēn yìzhí jiābān xiāngbǐ, xiūxi hǎo le zài gōngzuò, xiàolǜ gèng gāo.","vn":"So với việc cứ liên tục làm thêm giờ, nghỉ ngơi đầy đủ rồi mới làm việc sẽ có hiệu suất cao hơn."},{"cn":"跟读研究生相比，我更想直接工作。","pinyin":"Gēn dú yánjiūshēng xiāngbǐ, wǒ gèng xiǎng zhíjiē gōngzuò.","vn":"So với việc học lên thạc sĩ, tôi muốn đi làm trực tiếp hơn."},{"cn":"跟用现金相比，手机支付更方便些。","pinyin":"Gēn yòng xiànjīn xiāngbǐ, shǒujī zhīfù gèng fāngbiàn xiē.","vn":"So với việc dùng tiền mặt, thanh toán bằng điện thoại tiện lợi hơn một chút."}]},{"title":"固定短语\"有A有B\"","explanation_vn":"Trong cụm từ cố định \"有A有B\" (có A có B), A và B phần lớn là dạng đơn âm tiết, một số ít là dạng song âm tiết. A và B thường có ý nghĩa liên quan, gần giống hoặc đối lập nhau.","examples":[{"cn":"郊区有山有水，还有很多农家乐。","pinyin":"Jiāoqū yǒu shān yǒu shuǐ, hái yǒu hěn duō nóngjiālè.","vn":"Vùng ngoại ô có núi có sông, còn có rất nhiều nhà nghỉ dưỡng kiểu nông trại."},{"cn":"超市里的苹果有大有小，有红有绿，看起来都非常好吃。","pinyin":"Chāoshì lǐ de píngguǒ yǒu dà yǒu xiǎo, yǒu hóng yǒu lǜ, kàn qǐlái dōu fēicháng hǎochī.","vn":"Táo trong siêu thị có to có nhỏ, có đỏ có xanh, trông đều rất ngon."},{"cn":"春天，公园里到处都是人，有男有女，有大人有孩子，特别热闹。","pinyin":"Chūntiān, gōngyuán lǐ dàochù dōu shì rén, yǒu nán yǒu nǚ, yǒu dàrén yǒu háizi, tèbié rènao.","vn":"Mùa xuân, trong công viên đâu đâu cũng là người, có nam có nữ, có người lớn có trẻ em, rất náo nhiệt."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"安妮","cn":"家月，最近学习太紧张了，咱们明天出去放松放松吧。","pinyin":"Jiāyuè, zuìjìn xuéxí tài jǐnzhāng le, zánmen míngtiān chūqù fàngsōng fàngsōng ba."},{"speaker":"白家月","cn":"呀，正好我也想出去呢。咱们去哪儿好呢？","pinyin":"Yā, zhènghǎo wǒ yě xiǎng chūqù ne. Zánmen qù nǎr hǎo ne?"},{"speaker":"安妮","cn":"不管去哪儿，能放松的地方都行。","pinyin":"Bùguǎn qù nǎr, néng fàngsōng de dìfang dōu xíng."},{"speaker":"白家月","cn":"郊区怎么样？","pinyin":"Jiāoqū zěnmeyàng?"},{"speaker":"安妮","cn":"天中说，下周王老师要带咱们去郊区游玩呢。","pinyin":"Tiānzhōng shuō, xià zhōu Wáng lǎoshī yào dài zánmen qù jiāoqū yóuwán ne."},{"speaker":"白家月","cn":"是吗？那咱们明天去爬长城吧，不是说\"不到长城非好汉\"吗？","pinyin":"Shì ma? Nà zánmen míngtiān qù pá Chángchéng ba, bú shì shuō \"búdào Chángchéng fēi hǎohàn\" ma?"},{"speaker":"安妮","cn":"好主意！不过明天是个大晴天，外出记得戴帽子。","pinyin":"Hǎo zhǔyi! Búguò míngtiān shì ge dà qíngtiān, wàichū jìde dài màozi."}],"translation_vn":"Annie: Gia Nguyệt, dạo này học hành căng thẳng quá, ngày mai chúng mình ra ngoài thư giãn một chút đi.\nBạch Gia Nguyệt: Ôi, đúng lúc mình cũng muốn ra ngoài đây. Chúng mình đi đâu nhỉ?\nAnnie: Bất kể đi đâu, chỗ nào có thể thư giãn là được.\nBạch Gia Nguyệt: Đi ngoại ô thì sao?\nAnnie: Thiên Trung nói tuần sau thầy Vương sẽ dẫn chúng mình đi chơi ngoại ô đấy.\nBạch Gia Nguyệt: Thật à? Vậy ngày mai chúng mình đi leo Vạn Lý Trường Thành đi, chẳng phải người ta nói \"chưa đến Trường Thành chưa phải hảo hán\" sao?\nAnnie: Ý hay đấy! Nhưng ngày mai trời nắng to, ra ngoài nhớ đội mũ nhé.","audio_dialogue":"8-1.mp3","audio_vocab":"8-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"李文","cn":"同乐哥，你们平时工作忙吗？","pinyin":"Tónglè gē, nǐmen píngshí gōngzuò máng ma?"},{"speaker":"杨同乐","cn":"挺忙的。以前我总觉得年轻时要多学多干，所以参加了公司里的很多项目，经常加班、熬夜，身体也亮起了红灯。","pinyin":"Tǐng máng de. Yǐqián wǒ zǒng juéde niánqīng shí yào duō xué duō gàn, suǒyǐ cānjiā le gōngsī lǐ de hěn duō xiàngmù, jīngcháng jiābān, áoyè, shēntǐ yě liàngqǐ le hóngdēng."},{"speaker":"李文","cn":"还是别给自己太大压力，否则，失去健康就不值得了。","pinyin":"Háishi bié gěi zìjǐ tài dà yālì, fǒuzé, shīqù jiànkāng jiù bù zhídé le."},{"speaker":"杨同乐","cn":"是啊，后来我就不接那么多项目了。我发现暂停下来、好好休息之后，我能把工作做得更快更好。","pinyin":"Shì a, hòulái wǒ jiù bù jiē nàme duō xiàngmù le. Wǒ fāxiàn zàntíng xiàlái, hǎohǎo xiūxi zhīhòu, wǒ néng bǎ gōngzuò zuò de gèng kuài gèng hǎo."},{"speaker":"李文","cn":"对，该工作时就工作，该放松时就要放松。","pinyin":"Duì, gāi gōngzuò shí jiù gōngzuò, gāi fàngsōng shí jiù yào fàngsōng."},{"speaker":"杨同乐","cn":"是的，现在我周末常来郊区，在好山好水好风景中放松自己。","pinyin":"Shì de, xiànzài wǒ zhōumò cháng lái jiāoqū, zài hǎo shān hǎo shuǐ hǎo fēngjǐng zhōng fàngsōng zìjǐ."}],"translation_vn":"Lý Văn: Anh Đồng Lạc, mọi người thường ngày làm việc bận không?\nDương Đồng Lạc: Khá bận. Trước đây anh luôn nghĩ rằng lúc còn trẻ phải học nhiều làm nhiều, nên đã tham gia rất nhiều dự án trong công ty, thường xuyên tăng ca, thức khuya, sức khỏe cũng báo động rồi.\nLý Văn: Vẫn nên đừng tạo cho mình quá nhiều áp lực, nếu không, đánh mất sức khỏe thì không đáng đâu.\nDương Đồng Lạc: Đúng vậy, sau đó anh không nhận nhiều dự án như thế nữa. Anh phát hiện ra rằng sau khi tạm dừng lại, nghỉ ngơi thật tốt, anh có thể làm việc nhanh hơn và tốt hơn.\nLý Văn: Đúng rồi, nên làm việc khi cần làm việc, và nên thư giãn khi cần thư giãn.\nDương Đồng Lạc: Đúng vậy, bây giờ cuối tuần anh thường đến ngoại ô, thư giãn bản thân giữa núi non sông nước và phong cảnh đẹp.","audio_dialogue":"8-3.mp3","audio_vocab":"8-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"以前杨同乐总觉得自己年轻，就应该多学多干、积累经验。很多年轻人和他想法一样。但是，由于工作紧张，他们经常加班、熬夜，休息不够，结果工作效率下降，健康也受到了影响。现在越来越多的人认识到，跟一直加班相比，休息好了再工作，效率更高。因此，很多人开始做出改变，提醒自己减轻压力、多多放松。比如，杨同乐周末时或者与朋友们去郊区游玩，在大自然美丽的景色中好好放松自己；或者就在家里安安静静地看看书。休息好了，再回去上班时，心情愉快，工作效率也更高。","pinyin":"Yǐqián Yáng Tónglè zǒng juéde zìjǐ niánqīng, jiù yīnggāi duō xué duō gàn, jīlěi jīngyàn. Hěn duō niánqīngrén hé tā xiǎngfǎ yíyàng. Dànshì, yóuyú gōngzuò jǐnzhāng, tāmen jīngcháng jiābān, áoyè, xiūxi búgòu, jiéguǒ gōngzuò xiàolǜ xiàjiàng, jiànkāng yě shòudào le yǐngxiǎng. Xiànzài yuè lái yuè duō de rén rènshi dào, gēn yìzhí jiābān xiāngbǐ, xiūxi hǎo le zài gōngzuò, xiàolǜ gèng gāo. Yīncǐ, hěn duō rén kāishǐ zuòchū gǎibiàn, tíxǐng zìjǐ jiǎnqīng yālì, duōduō fàngsōng. Bǐrú, Yáng Tónglè zhōumò shí huòzhě yǔ péngyoumen qù jiāoqū yóuwán, zài dàzìrán měilì de jǐngsè zhōng hǎohǎo fàngsōng zìjǐ; huòzhě jiù zài jiālǐ ān'ānjìngjìng de kànkan shū. Xiūxi hǎo le, zài huíqù shàngbān shí, xīnqíng yúkuài, gōngzuò xiàolǜ yě gèng gāo."}],"translation_vn":"Trước đây Dương Đồng Lạc luôn nghĩ rằng mình còn trẻ, nên phải học nhiều làm nhiều, tích lũy kinh nghiệm. Rất nhiều người trẻ cũng có suy nghĩ giống anh. Nhưng vì công việc căng thẳng, họ thường xuyên tăng ca, thức khuya, nghỉ ngơi không đủ, kết quả là hiệu suất làm việc giảm xuống, sức khỏe cũng bị ảnh hưởng. Hiện nay ngày càng nhiều người nhận ra rằng, so với việc cứ liên tục tăng ca, nghỉ ngơi đầy đủ rồi mới làm việc sẽ có hiệu suất cao hơn. Vì vậy, nhiều người bắt đầu thay đổi, tự nhắc nhở bản thân giảm bớt áp lực, thư giãn nhiều hơn. Ví dụ, Dương Đồng Lạc vào cuối tuần thường cùng bạn bè đi chơi ở ngoại ô, thư giãn bản thân giữa cảnh sắc thiên nhiên tươi đẹp; hoặc ở nhà yên tĩnh đọc sách. Khi nghỉ ngơi đầy đủ rồi, lúc quay lại đi làm, tâm trạng vui vẻ, hiệu suất làm việc cũng cao hơn.","audio_dialogue":"8-5.mp3","audio_vocab":"8-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"一到周末，很多人都喜欢外出游玩。你一般去哪里呢？我生活在中国的首都——北京。在北京，周末的时候，有人会在市区公园走走，看看眼前的美景；有人喜欢去参观长城、故宫等有名的景点，放松心情的同时，也能了解历史文化。北京交通很方便，所以我和家人更爱乘坐公交车去郊区，偶尔也会自己开车。郊区有山有水，还有很多农家乐，吃、玩、住都十分方便。在我看来，不管去哪里玩，实际上都是为了放松。也可以说，只要能放松，去哪儿都合适。","pinyin":"Yí dào zhōumò, hěn duō rén dōu xǐhuan wàichū yóuwán. Nǐ yìbān qù nǎlǐ ne? Wǒ shēnghuó zài Zhōngguó de shǒudū — Běijīng. Zài Běijīng, zhōumò de shíhou, yǒurén huì zài shìqū gōngyuán zǒuzou, kànkan yǎnqián de měijǐng; yǒurén xǐhuan qù cānguān Chángchéng, Gùgōng děng yǒumíng de jǐngdiǎn, fàngsōng xīnqíng de tóngshí, yě néng liǎojiě lìshǐ wénhuà. Běijīng jiāotōng hěn fāngbiàn, suǒyǐ wǒ hé jiārén gèng ài chéngzuò gōngjiāochē qù jiāoqū, ǒu'ěr yě huì zìjǐ kāichē. Jiāoqū yǒu shān yǒu shuǐ, hái yǒu hěn duō nóngjiālè, chī, wán, zhù dōu shífēn fāngbiàn. Zài wǒ kànlái, bùguǎn qù nǎlǐ wán, shíjìshàng dōu shì wèile fàngsōng. Yě kěyǐ shuō, zhǐyào néng fàngsōng, qù nǎr dōu héshì."}],"translation_vn":"Cứ đến cuối tuần là rất nhiều người thích ra ngoài đi chơi. Bạn thường đi đâu nhỉ? Tôi sống ở thủ đô của Trung Quốc — Bắc Kinh. Ở Bắc Kinh, vào cuối tuần, có người đi dạo ở công viên trong khu nội thành, ngắm nhìn cảnh đẹp trước mắt; có người thích đi tham quan các điểm du lịch nổi tiếng như Vạn Lý Trường Thành, Cố Cung, vừa thư giãn tâm trạng vừa có thể tìm hiểu lịch sử văn hóa. Giao thông ở Bắc Kinh rất thuận tiện, nên tôi và gia đình thích đi xe buýt ra ngoại ô hơn, thỉnh thoảng cũng tự lái xe. Vùng ngoại ô có núi có sông, còn có rất nhiều nhà nghỉ dưỡng kiểu nông trại, ăn, chơi, ở đều rất thuận tiện. Theo tôi, bất kể đi chơi ở đâu, thực chất đều là để thư giãn. Cũng có thể nói, chỉ cần có thể thư giãn được thì đi đâu cũng thích hợp.","audio_dialogue":"8-7.mp3","audio_vocab":"8-8.mp3"}]},{"id":9,"title_cn":"遇见你，刚刚好","title_pinyin":"Yùjiàn nǐ, gānggāng hǎo","title_vn":"Gặp em, thật vừa vặn","goals":["Có thể nghe hiểu và trao đổi về các chủ đề liên quan đến tình yêu, tình bạn.","Có thể diễn đạt bằng lời nói hoặc văn viết về giá trị hay ý nghĩa của tình yêu, tình bạn.","Hiểu được quan niệm về tình yêu, tình bạn của người Trung Quốc."],"vocab":[{"hanzi":"祝","pinyin":"zhù","pos":"dgt.","vn":"chúc","examples":[{"cn":"祝你生日快乐！","pinyin":"Zhù nǐ shēngrì kuàilè!","vn":"Chúc bạn sinh nhật vui vẻ!"},{"cn":"我祝你们俩百年好合。","pinyin":"Wǒ zhù nǐmen liǎ bǎinián hǎohé.","vn":"Tôi chúc hai bạn trăm năm hạnh phúc."},{"cn":"老师祝我们考试顺利。","pinyin":"Lǎoshī zhù wǒmen kǎoshì shùnlì.","vn":"Thầy giáo chúc chúng tôi thi cử thuận lợi."}]},{"hanzi":"巧克力","pinyin":"qiǎokèlì","pos":"dt.","vn":"sô-cô-la","examples":[{"cn":"我特别喜欢吃巧克力。","pinyin":"Wǒ tèbié xǐhuan chī qiǎokèlì.","vn":"Tôi đặc biệt thích ăn sô-cô-la."},{"cn":"情人节他送了我一盒巧克力。","pinyin":"Qíngrénjié tā sòngle wǒ yì hé qiǎokèlì.","vn":"Ngày lễ tình nhân anh ấy tặng tôi một hộp sô-cô-la."},{"cn":"这个蛋糕里加了很多巧克力。","pinyin":"Zhège dàngāo lǐ jiāle hěn duō qiǎokèlì.","vn":"Chiếc bánh này cho rất nhiều sô-cô-la."}]},{"hanzi":"感动","pinyin":"gǎndòng","pos":"tt./dgt.","vn":"cảm động; làm cảm động","examples":[{"cn":"看完这部电影我特别感动。","pinyin":"Kànwán zhè bù diànyǐng wǒ tèbié gǎndòng.","vn":"Xem xong bộ phim này tôi rất cảm động."},{"cn":"他的话深深地感动了大家。","pinyin":"Tā de huà shēnshēn de gǎndòngle dàjiā.","vn":"Lời nói của anh ấy làm mọi người cảm động sâu sắc."},{"cn":"她被朋友们的关心感动得哭了。","pinyin":"Tā bèi péngyoumen de guānxīn gǎndòng de kūle.","vn":"Cô ấy được bạn bè quan tâm nên cảm động đến phát khóc."}]},{"hanzi":"浪漫","pinyin":"làngmàn","pos":"tt.","vn":"lãng mạn","examples":[{"cn":"他是个很浪漫的人，总是给我惊喜。","pinyin":"Tā shì ge hěn làngmàn de rén, zǒngshì gěi wǒ jīngxǐ.","vn":"Anh ấy là người rất lãng mạn, luôn cho tôi bất ngờ."},{"cn":"巴黎是个充满浪漫气息的城市。","pinyin":"Bālí shì ge chōngmǎn làngmàn qìxī de chéngshì.","vn":"Paris là thành phố tràn đầy không khí lãng mạn."},{"cn":"他们在海边看日落，气氛特别浪漫。","pinyin":"Tāmen zài hǎibiān kàn rìluò, qìfēn tèbié làngmàn.","vn":"Họ ngắm hoàng hôn trên biển, không khí rất lãng mạn."}]},{"hanzi":"幽默","pinyin":"yōumò","pos":"tt.","vn":"hài hước","examples":[{"cn":"他说话很幽默，大家都喜欢跟他聊天。","pinyin":"Tā shuōhuà hěn yōumò, dàjiā dōu xǐhuan gēn tā liáotiān.","vn":"Anh ấy nói chuyện rất hài hước, mọi người đều thích trò chuyện với anh ấy."},{"cn":"这个老师讲课很幽默，一点都不无聊。","pinyin":"Zhège lǎoshī jiǎngkè hěn yōumò, yìdiǎn dōu bù wúliáo.","vn":"Thầy giáo này giảng bài rất hài hước, chẳng chán tí nào."},{"cn":"她有很强的幽默感。","pinyin":"Tā yǒu hěn qiáng de yōumògǎn.","vn":"Cô ấy có khiếu hài hước rất mạnh."}]},{"hanzi":"耐心","pinyin":"nàixīn","pos":"tt./dt.","vn":"kiên nhẫn; sự kiên nhẫn","examples":[{"cn":"教小孩子一定要有耐心。","pinyin":"Jiāo xiǎoháizi yídìng yào yǒu nàixīn.","vn":"Dạy trẻ con nhất định phải có kiên nhẫn."},{"cn":"她很耐心地给我解释了好几遍。","pinyin":"Tā hěn nàixīn de gěi wǒ jiěshìle hǎo jǐ biàn.","vn":"Cô ấy rất kiên nhẫn giải thích cho tôi mấy lần."},{"cn":"老板对我们一直很有耐心。","pinyin":"Lǎobǎn duì wǒmen yìzhí hěn yǒu nàixīn.","vn":"Sếp luôn rất kiên nhẫn với chúng tôi."}]},{"hanzi":"吸引","pinyin":"xīyǐn","pos":"dgt.","vn":"thu hút","examples":[{"cn":"这家店的橱窗设计很吸引人。","pinyin":"Zhè jiā diàn de chúchuāng shèjì hěn xīyǐn rén.","vn":"Cách thiết kế tủ kính của cửa hàng này rất thu hút người xem."},{"cn":"她的笑容一下子就吸引了我。","pinyin":"Tā de xiàoróng yíxiàzi jiù xīyǐnle wǒ.","vn":"Nụ cười của cô ấy ngay lập tức thu hút tôi."},{"cn":"这个活动吸引了很多年轻人参加。","pinyin":"Zhège huódòng xīyǐnle hěn duō niánqīngrén cānjiā.","vn":"Hoạt động này thu hút rất nhiều bạn trẻ tham gia."}]},{"hanzi":"当时","pinyin":"dāngshí","pos":"dt.","vn":"lúc đó, khi đó","examples":[{"cn":"我当时太紧张了，什么都忘了。","pinyin":"Wǒ dāngshí tài jǐnzhāng le, shénme dōu wàngle.","vn":"Lúc đó tôi quá hồi hộp nên quên hết cả."},{"cn":"当时我们都还是学生。","pinyin":"Dāngshí wǒmen dōu hái shì xuésheng.","vn":"Khi đó chúng tôi vẫn còn là học sinh."},{"cn":"他当时并没有意识到问题的严重性。","pinyin":"Tā dāngshí bìng méiyǒu yìshí dào wèntí de yánzhòngxìng.","vn":"Lúc đó anh ấy hoàn toàn chưa nhận ra mức độ nghiêm trọng của vấn đề."}]},{"hanzi":"错过","pinyin":"cuòguò","pos":"dgt.","vn":"bỏ lỡ","examples":[{"cn":"我差点错过了这班飞机。","pinyin":"Wǒ chàdiǎn cuòguòle zhè bān fēijī.","vn":"Tôi suýt lỡ chuyến bay này."},{"cn":"别错过这次难得的机会。","pinyin":"Bié cuòguò zhè cì nándé de jīhuì.","vn":"Đừng bỏ lỡ cơ hội hiếm có này."},{"cn":"他因为睡过头错过了面试。","pinyin":"Tā yīnwèi shuìguòtóu cuòguòle miànshì.","vn":"Anh ấy vì ngủ quên nên lỡ buổi phỏng vấn."}]},{"hanzi":"幸运","pinyin":"xìngyùn","pos":"tt./dt.","vn":"may mắn","examples":[{"cn":"能认识你真是我的幸运。","pinyin":"Néng rènshi nǐ zhēnshi wǒ de xìngyùn.","vn":"Được quen biết bạn thực sự là may mắn của tôi."},{"cn":"他很幸运，中了彩票。","pinyin":"Tā hěn xìngyùn, zhòngle cǎipiào.","vn":"Anh ấy rất may mắn, trúng số."},{"cn":"我觉得自己是个幸运的人。","pinyin":"Wǒ juéde zìjǐ shì ge xìngyùn de rén.","vn":"Tôi cảm thấy mình là người may mắn."}]},{"hanzi":"幸福","pinyin":"xìngfú","pos":"tt./dt.","vn":"hạnh phúc","examples":[{"cn":"一家人在一起就是幸福。","pinyin":"Yì jiā rén zài yìqǐ jiùshì xìngfú.","vn":"Cả nhà bên nhau chính là hạnh phúc."},{"cn":"她现在的生活很幸福。","pinyin":"Tā xiànzài de shēnghuó hěn xìngfú.","vn":"Cuộc sống hiện tại của cô ấy rất hạnh phúc."},{"cn":"他们俩看起来很幸福。","pinyin":"Tāmen liǎ kànqǐlái hěn xìngfú.","vn":"Hai người họ trông rất hạnh phúc."}]},{"hanzi":"尽管","pinyin":"jǐnguǎn","pos":"liên.","vn":"mặc dù","examples":[{"cn":"尽管下着大雨，他还是坚持去上班。","pinyin":"Jǐnguǎn xiàzhe dàyǔ, tā háishi jiānchí qù shàngbān.","vn":"Mặc dù trời mưa to, anh ấy vẫn kiên quyết đi làm."},{"cn":"尽管很累，她还是把作业做完了。","pinyin":"Jǐnguǎn hěn lèi, tā háishi bǎ zuòyè zuòwánle.","vn":"Mặc dù rất mệt, cô ấy vẫn làm xong bài tập."},{"cn":"尽管工资不高，他依然很喜欢这份工作。","pinyin":"Jǐnguǎn gōngzī bù gāo, tā yīrán hěn xǐhuan zhè fèn gōngzuò.","vn":"Mặc dù lương không cao, anh ấy vẫn rất thích công việc này."}]},{"hanzi":"性格","pinyin":"xìnggé","pos":"dt.","vn":"tính cách","examples":[{"cn":"他的性格很开朗。","pinyin":"Tā de xìnggé hěn kāilǎng.","vn":"Tính cách của anh ấy rất cởi mở."},{"cn":"我们俩性格差别很大。","pinyin":"Wǒmen liǎ xìnggé chābié hěn dà.","vn":"Tính cách của hai chúng tôi khác nhau nhiều."},{"cn":"这个孩子性格有点内向。","pinyin":"Zhège háizi xìnggé yǒudiǎn nèixiàng.","vn":"Đứa trẻ này tính cách hơi hướng nội."}]},{"hanzi":"共同","pinyin":"gòngtóng","pos":"tt.","vn":"chung","examples":[{"cn":"我们有共同的爱好。","pinyin":"Wǒmen yǒu gòngtóng de àihào.","vn":"Chúng tôi có sở thích chung."},{"cn":"这是大家共同努力的结果。","pinyin":"Zhè shì dàjiā gòngtóng nǔlì de jiéguǒ.","vn":"Đây là kết quả nỗ lực chung của mọi người."},{"cn":"他们俩有很多共同语言。","pinyin":"Tāmen liǎ yǒu hěn duō gòngtóng yǔyán.","vn":"Hai người họ có rất nhiều điểm chung để nói chuyện."}]},{"hanzi":"责任","pinyin":"zérèn","pos":"dt.","vn":"trách nhiệm","examples":[{"cn":"这是我的责任，我会负责到底。","pinyin":"Zhè shì wǒ de zérèn, wǒ huì fùzé dàodǐ.","vn":"Đây là trách nhiệm của tôi, tôi sẽ chịu trách nhiệm đến cùng."},{"cn":"家长要对孩子的教育负责任。","pinyin":"Jiāzhǎng yào duì háizi de jiàoyù fù zérèn.","vn":"Phụ huynh phải có trách nhiệm với việc giáo dục con cái."},{"cn":"他把责任都推给了别人。","pinyin":"Tā bǎ zérèn dōu tuī gěile biérén.","vn":"Anh ấy đẩy hết trách nhiệm cho người khác."}]},{"hanzi":"相互","pinyin":"xiānghù","pos":"phó.","vn":"lẫn nhau, qua lại","examples":[{"cn":"我们应该相互理解，相互帮助。","pinyin":"Wǒmen yīnggāi xiānghù lǐjiě, xiānghù bāngzhù.","vn":"Chúng ta nên hiểu nhau và giúp đỡ lẫn nhau."},{"cn":"朋友之间要相互信任。","pinyin":"Péngyou zhījiān yào xiānghù xìnrèn.","vn":"Bạn bè với nhau phải tin tưởng lẫn nhau."},{"cn":"这两件事相互影响。","pinyin":"Zhè liǎng jiàn shì xiānghù yǐngxiǎng.","vn":"Hai việc này ảnh hưởng lẫn nhau."}]},{"hanzi":"理解","pinyin":"lǐjiě","pos":"dgt.","vn":"hiểu, thấu hiểu","examples":[{"cn":"我完全理解你的感受。","pinyin":"Wǒ wánquán lǐjiě nǐ de gǎnshòu.","vn":"Tôi hoàn toàn hiểu cảm nhận của bạn."},{"cn":"父母有时候很难理解孩子的想法。","pinyin":"Fùmǔ yǒu shíhou hěn nán lǐjiě háizi de xiǎngfǎ.","vn":"Cha mẹ đôi khi rất khó hiểu suy nghĩ của con cái."},{"cn":"谢谢你的理解。","pinyin":"Xièxie nǐ de lǐjiě.","vn":"Cảm ơn sự thấu hiểu của bạn."}]},{"hanzi":"支持","pinyin":"zhīchí","pos":"dgt.","vn":"ủng hộ","examples":[{"cn":"不管你做什么决定，我都支持你。","pinyin":"Bùguǎn nǐ zuò shénme juédìng, wǒ dōu zhīchí nǐ.","vn":"Dù bạn quyết định thế nào, tôi đều ủng hộ bạn."},{"cn":"家人的支持对我很重要。","pinyin":"Jiārén de zhīchí duì wǒ hěn zhòngyào.","vn":"Sự ủng hộ của gia đình rất quan trọng với tôi."},{"cn":"这个计划得到了大家的支持。","pinyin":"Zhège jìhuà dédàole dàjiā de zhīchí.","vn":"Kế hoạch này nhận được sự ủng hộ của mọi người."}]},{"hanzi":"印象","pinyin":"yìnxiàng","pos":"dt.","vn":"ấn tượng","examples":[{"cn":"她给我留下了很深的印象。","pinyin":"Tā gěi wǒ liúxiàle hěn shēn de yìnxiàng.","vn":"Cô ấy để lại cho tôi ấn tượng rất sâu sắc."},{"cn":"我对那个城市印象特别好。","pinyin":"Wǒ duì nàge chéngshì yìnxiàng tèbié hǎo.","vn":"Tôi có ấn tượng rất tốt về thành phố đó."},{"cn":"第一印象很重要。","pinyin":"Dì yī yìnxiàng hěn zhòngyào.","vn":"Ấn tượng ban đầu rất quan trọng."}]},{"hanzi":"实在","pinyin":"shízài","pos":"tt./phó.","vn":"thật thà; thực ra","examples":[{"cn":"他是个实在人，从不说谎。","pinyin":"Tā shì ge shízài rén, cóngbù shuōhuǎng.","vn":"Anh ấy là người thật thà, chưa bao giờ nói dối."},{"cn":"这件事实在太麻烦了。","pinyin":"Zhè jiàn shì shízài tài máfan le.","vn":"Việc này thực sự quá phiền phức."},{"cn":"我实在不知道该怎么办。","pinyin":"Wǒ shízài bù zhīdào gāi zěnme bàn.","vn":"Tôi thực sự không biết nên làm thế nào."}]},{"hanzi":"阳光","pinyin":"yángguāng","pos":"tt./dt.","vn":"rạng rỡ; ánh nắng","examples":[{"cn":"今天阳光真好。","pinyin":"Jīntiān yángguāng zhēn hǎo.","vn":"Hôm nay nắng thật đẹp."},{"cn":"她笑起来特别阳光。","pinyin":"Tā xiào qǐlái tèbié yángguāng.","vn":"Cô ấy cười lên trông thật rạng rỡ."},{"cn":"我喜欢躺在阳光下晒太阳。","pinyin":"Wǒ xǐhuan tǎng zài yángguāng xià shài tàiyáng.","vn":"Tôi thích nằm phơi nắng dưới ánh mặt trời."}]},{"hanzi":"负责","pinyin":"fùzé","pos":"tt./dgt.","vn":"có trách nhiệm; phụ trách","examples":[{"cn":"这个项目由我负责。","pinyin":"Zhège xiàngmù yóu wǒ fùzé.","vn":"Dự án này do tôi phụ trách."},{"cn":"他做事很负责任。","pinyin":"Tā zuòshì hěn fùzérèn.","vn":"Anh ấy làm việc rất có trách nhiệm."},{"cn":"谁负责今天的会议记录？","pinyin":"Shéi fùzé jīntiān de huìyì jìlù?","vn":"Ai phụ trách ghi biên bản cuộc họp hôm nay?"}]},{"hanzi":"积极","pinyin":"jījí","pos":"tt.","vn":"tích cực","examples":[{"cn":"他工作一直很积极。","pinyin":"Tā gōngzuò yìzhí hěn jījí.","vn":"Anh ấy làm việc luôn rất tích cực."},{"cn":"我们要积极面对困难。","pinyin":"Wǒmen yào jījí miànduì kùnnan.","vn":"Chúng ta phải tích cực đối mặt với khó khăn."},{"cn":"她对生活态度很积极。","pinyin":"Tā duì shēnghuó tàidu hěn jījí.","vn":"Cô ấy có thái độ sống rất tích cực."}]},{"hanzi":"此","pinyin":"cǐ","pos":"đt.","vn":"này","examples":[{"cn":"由此可见，他真的很努力。","pinyin":"Yóucǐ kějiàn, tā zhēn de hěn nǔlì.","vn":"Từ đó có thể thấy, anh ấy thực sự rất nỗ lực."},{"cn":"就此打住吧，别再说了。","pinyin":"Jiù cǐ dǎzhù ba, bié zài shuōle.","vn":"Dừng tại đây thôi, đừng nói nữa."},{"cn":"特此通知，请大家注意。","pinyin":"Tècǐ tōngzhī, qǐng dàjiā zhùyì.","vn":"Đặc biệt thông báo điều này, xin mọi người lưu ý."}]},{"hanzi":"从此","pinyin":"cóngcǐ","pos":"phó.","vn":"từ đó","examples":[{"cn":"从此以后，我们再也没见过面。","pinyin":"Cóngcǐ yǐhòu, wǒmen zài yě méi jiànguò miàn.","vn":"Từ đó về sau, chúng tôi không bao giờ gặp lại nhau nữa."},{"cn":"从此他改掉了坏习惯。","pinyin":"Cóngcǐ tā gǎidiàole huài xíguàn.","vn":"Từ đó anh ấy bỏ được thói quen xấu."},{"cn":"从此，她爱上了画画。","pinyin":"Cóngcǐ, tā àishàngle huàhuà.","vn":"Từ đó, cô ấy yêu thích vẽ tranh."}]},{"hanzi":"产生","pinyin":"chǎnshēng","pos":"dgt.","vn":"nảy sinh","examples":[{"cn":"这件事让我对他产生了怀疑。","pinyin":"Zhè jiàn shì ràng wǒ duì tā chǎnshēngle huáiyí.","vn":"Việc này khiến tôi nảy sinh nghi ngờ với anh ta."},{"cn":"两人之间渐渐产生了感情。","pinyin":"Liǎng rén zhījiān jiànjiàn chǎnshēngle gǎnqíng.","vn":"Hai người dần dần nảy sinh tình cảm."},{"cn":"这个决定会产生很大的影响。","pinyin":"Zhège juédìng huì chǎnshēng hěn dà de yǐngxiǎng.","vn":"Quyết định này sẽ gây ra ảnh hưởng rất lớn."}]},{"hanzi":"爱情","pinyin":"àiqíng","pos":"dt.","vn":"tình yêu","examples":[{"cn":"他们的爱情故事很感人。","pinyin":"Tāmen de àiqíng gùshi hěn gǎnrén.","vn":"Câu chuyện tình yêu của họ rất cảm động."},{"cn":"爱情需要用心经营。","pinyin":"Àiqíng xūyào yòngxīn jīngyíng.","vn":"Tình yêu cần được vun đắp bằng cả tấm lòng."},{"cn":"她还没遇到真正的爱情。","pinyin":"Tā hái méi yùdào zhēnzhèng de àiqíng.","vn":"Cô ấy vẫn chưa gặp được tình yêu đích thực."}]},{"hanzi":"间","pinyin":"jiān","pos":"dt.","vn":"khoảng giữa","examples":[{"cn":"他们之间的关系越来越好。","pinyin":"Tāmen zhījiān de guānxi yuè lái yuè hǎo.","vn":"Mối quan hệ giữa họ ngày càng tốt đẹp."},{"cn":"中美两国之间有很多合作项目。","pinyin":"Zhōng Měi liǎng guó zhījiān yǒu hěn duō hézuò xiàngmù.","vn":"Giữa hai nước Trung-Mỹ có rất nhiều dự án hợp tác."},{"cn":"朋友之间应该坦诚相待。","pinyin":"Péngyou zhījiān yīnggāi tǎnchéng xiāngdài.","vn":"Bạn bè với nhau nên đối xử chân thành."}]},{"hanzi":"友情","pinyin":"yǒuqíng","pos":"dt.","vn":"tình bạn","examples":[{"cn":"我们的友情已经十年了。","pinyin":"Wǒmen de yǒuqíng yǐjīng shí nián le.","vn":"Tình bạn của chúng tôi đã mười năm rồi."},{"cn":"她很珍惜这段友情。","pinyin":"Tā hěn zhēnxī zhè duàn yǒuqíng.","vn":"Cô ấy rất trân trọng tình bạn này."},{"cn":"友情比金钱更珍贵。","pinyin":"Yǒuqíng bǐ jīnqián gèng zhēnguì.","vn":"Tình bạn quý giá hơn tiền bạc."}]},{"hanzi":"美好","pinyin":"měihǎo","pos":"tt.","vn":"tốt đẹp","examples":[{"cn":"祝你有一个美好的明天。","pinyin":"Zhù nǐ yǒu yí ge měihǎo de míngtiān.","vn":"Chúc bạn có một ngày mai tốt đẹp."},{"cn":"那是我童年最美好的回忆。","pinyin":"Nà shì wǒ tóngnián zuì měihǎo de huíyì.","vn":"Đó là kỷ niệm đẹp nhất thời thơ ấu của tôi."},{"cn":"愿你的生活一直这么美好。","pinyin":"Yuàn nǐ de shēnghuó yìzhí zhème měihǎo.","vn":"Mong cuộc sống của bạn luôn tốt đẹp như thế này."}]},{"hanzi":"人生","pinyin":"rénshēng","pos":"dt.","vn":"cuộc đời, nhân sinh","examples":[{"cn":"人生就像一场旅行。","pinyin":"Rénshēng jiù xiàng yì chǎng lǚxíng.","vn":"Cuộc đời giống như một chuyến du hành."},{"cn":"他的人生经历很丰富。","pinyin":"Tā de rénshēng jīnglì hěn fēngfù.","vn":"Trải nghiệm cuộc đời của anh ấy rất phong phú."},{"cn":"这是我人生中最重要的决定。","pinyin":"Zhè shì wǒ rénshēng zhōng zuì zhòngyào de juédìng.","vn":"Đây là quyết định quan trọng nhất trong cuộc đời tôi."}]},{"hanzi":"精彩","pinyin":"jīngcǎi","pos":"tt.","vn":"tuyệt vời, đặc sắc","examples":[{"cn":"这场比赛太精彩了。","pinyin":"Zhè chǎng bǐsài tài jīngcǎi le.","vn":"Trận đấu này thật tuyệt vời."},{"cn":"他的演讲非常精彩。","pinyin":"Tā de yǎnjiǎng fēicháng jīngcǎi.","vn":"Bài diễn thuyết của anh ấy rất đặc sắc."},{"cn":"这部电影的结局很精彩。","pinyin":"Zhè bù diànyǐng de jiéjú hěn jīngcǎi.","vn":"Kết thúc của bộ phim này rất hay."}]},{"hanzi":"感情","pinyin":"gǎnqíng","pos":"dt.","vn":"tình cảm","examples":[{"cn":"他们俩的感情越来越好。","pinyin":"Tāmen liǎ de gǎnqíng yuè lái yuè hǎo.","vn":"Tình cảm của hai người ngày càng tốt."},{"cn":"我对这个地方有很深的感情。","pinyin":"Wǒ duì zhège dìfang yǒu hěn shēn de gǎnqíng.","vn":"Tôi có tình cảm sâu đậm với nơi này."},{"cn":"感情的事不能勉强。","pinyin":"Gǎnqíng de shì bùnéng miǎnqiǎng.","vn":"Chuyện tình cảm không thể miễn cưỡng."}]},{"hanzi":"深","pinyin":"shēn","pos":"tt.","vn":"sâu đậm","examples":[{"cn":"他们之间的感情很深。","pinyin":"Tāmen zhījiān de gǎnqíng hěn shēn.","vn":"Tình cảm giữa họ rất sâu đậm."},{"cn":"这条河很深，小心别掉进去。","pinyin":"Zhè tiáo hé hěn shēn, xiǎoxīn bié diào jìnqù.","vn":"Con sông này rất sâu, cẩn thận đừng ngã xuống."},{"cn":"她对他的印象很深。","pinyin":"Tā duì tā de yìnxiàng hěn shēn.","vn":"Cô ấy có ấn tượng rất sâu sắc về anh ta."}]},{"hanzi":"经营","pinyin":"jīngyíng","pos":"dgt.","vn":"vun đắp, quản lý","examples":[{"cn":"他在经营一家小餐馆。","pinyin":"Tā zài jīngyíng yì jiā xiǎo cānguǎn.","vn":"Anh ấy đang quản lý một nhà hàng nhỏ."},{"cn":"婚姻需要双方共同经营。","pinyin":"Hūnyīn xūyào shuāngfāng gòngtóng jīngyíng.","vn":"Hôn nhân cần cả hai bên cùng vun đắp."},{"cn":"这家公司经营得不错。","pinyin":"Zhè jiā gōngsī jīngyíng de búcuò.","vn":"Công ty này quản lý kinh doanh khá tốt."}]},{"hanzi":"对方","pinyin":"duìfāng","pos":"dt.","vn":"đối phương","examples":[{"cn":"吵架的时候也要听听对方的想法。","pinyin":"Chǎojià de shíhou yě yào tīngting duìfāng de xiǎngfǎ.","vn":"Khi cãi nhau cũng nên lắng nghe suy nghĩ của đối phương."},{"cn":"打电话的时候要先确认对方是谁。","pinyin":"Dǎ diànhuà de shíhou yào xiān quèrèn duìfāng shì shéi.","vn":"Khi gọi điện phải xác nhận trước người ở đầu dây là ai."},{"cn":"他总是能站在对方的角度考虑问题。","pinyin":"Tā zǒngshì néng zhàn zài duìfāng de jiǎodù kǎolǜ wèntí.","vn":"Anh ấy luôn có thể suy nghĩ vấn đề từ góc độ của đối phương."}]},{"hanzi":"感受","pinyin":"gǎnshòu","pos":"dt./dgt.","vn":"cảm nhận","examples":[{"cn":"说说你对这件事的感受吧。","pinyin":"Shuōshuo nǐ duì zhè jiàn shì de gǎnshòu ba.","vn":"Nói xem cảm nhận của bạn về việc này đi."},{"cn":"我能感受到你的真诚。","pinyin":"Wǒ néng gǎnshòu dào nǐ de zhēnchéng.","vn":"Tôi có thể cảm nhận được sự chân thành của bạn."},{"cn":"每个人的感受都不一样。","pinyin":"Měi ge rén de gǎnshòu dōu bù yíyàng.","vn":"Cảm nhận của mỗi người đều khác nhau."}]},{"hanzi":"尤其","pinyin":"yóuqí","pos":"phó.","vn":"đặc biệt là","examples":[{"cn":"我喜欢吃水果，尤其是西瓜。","pinyin":"Wǒ xǐhuan chī shuǐguǒ, yóuqí shì xīguā.","vn":"Tôi thích ăn trái cây, đặc biệt là dưa hấu."},{"cn":"夏天很热，尤其是在南方。","pinyin":"Xiàtiān hěn rè, yóuqí shì zài nánfāng.","vn":"Mùa hè rất nóng, đặc biệt là ở miền Nam."},{"cn":"他对历史很感兴趣，尤其是中国古代史。","pinyin":"Tā duì lìshǐ hěn gǎn xìngqù, yóuqí shì Zhōngguó gǔdàishǐ.","vn":"Anh ấy rất thích lịch sử, đặc biệt là lịch sử cổ đại Trung Quốc."}]},{"hanzi":"日子","pinyin":"rìzi","pos":"dt.","vn":"ngày tháng, cuộc sống","examples":[{"cn":"这些日子你过得怎么样？","pinyin":"Zhèxiē rìzi nǐ guò de zěnmeyàng?","vn":"Những ngày qua bạn sống thế nào?"},{"cn":"结婚的日子已经定好了。","pinyin":"Jiéhūn de rìzi yǐjīng dìnghǎole.","vn":"Ngày cưới đã được ấn định rồi."},{"cn":"他们俩的日子过得很幸福。","pinyin":"Tāmen liǎ de rìzi guò de hěn xìngfú.","vn":"Ngày tháng của hai người họ sống rất hạnh phúc."}]},{"hanzi":"从来","pinyin":"cónglái","pos":"phó.","vn":"từ trước đến nay","examples":[{"cn":"他从来不迟到。","pinyin":"Tā cónglái bù chídào.","vn":"Anh ấy từ trước đến nay chưa bao giờ đến muộn."},{"cn":"我从来没去过国外。","pinyin":"Wǒ cónglái méi qùguò guówài.","vn":"Tôi chưa bao giờ ra nước ngoài."},{"cn":"她从来都这么热情。","pinyin":"Tā cónglái dōu zhème rèqíng.","vn":"Cô ấy từ trước đến nay luôn nhiệt tình như vậy."}]}],"grammar":[{"title":"紧缩复句\"不……也……\"","explanation_vn":"Câu phức rút gọn \"不……也……\" biểu thị rằng dù trong một điều kiện phủ định nào đó, kết quả phía sau vẫn chắc chắn xảy ra. Thường dùng trong khẩu ngữ.","examples":[{"cn":"我不说你也懂我在想什么。","pinyin":"Wǒ bù shuō nǐ yě dǒng wǒ zài xiǎng shénme.","vn":"Em không nói mà anh vẫn hiểu em đang nghĩ gì."},{"cn":"他不复习也能考出好成绩。","pinyin":"Tā bù fùxí yě néng kǎochū hǎo chéngjì.","vn":"Cậu ấy không ôn bài vẫn thi được điểm cao."},{"cn":"我很清楚他为什么生气，不问我也知道。","pinyin":"Wǒ hěn qīngchu tā wèishénme shēngqì, bú wèn wǒ yě zhīdào.","vn":"Tôi biết rất rõ tại sao anh ấy giận, không cần hỏi tôi cũng biết."}]},{"title":"转折复句\"尽管……，但是/可是……\"","explanation_vn":"Câu phức chuyển ý \"尽管……，但是/可是……\" biểu thị sự chuyển ý. \"尽管\" có nghĩa là \"mặc dù\", dùng để dẫn ra một tình huống nào đó, còn \"但是、可是\" dẫn ra tình huống hoặc kết quả trái ngược.","examples":[{"cn":"他们尽管性格不同，但是有很多共同爱好。","pinyin":"Tāmen jǐnguǎn xìnggé bùtóng, dànshì yǒu hěn duō gòngtóng àihào.","vn":"Mặc dù tính cách họ khác nhau, nhưng họ có rất nhiều sở thích chung."},{"cn":"尽管时间紧张、压力很大，但是他们还是完成了任务。","pinyin":"Jǐnguǎn shíjiān jǐnzhāng, yālì hěn dà, dànshì tāmen háishi wánchéng le rènwù.","vn":"Dù thời gian gấp gáp, áp lực lớn, nhưng họ vẫn hoàn thành nhiệm vụ."},{"cn":"尽管她已经很累了，可是还是很耐心地给女儿读睡前故事。","pinyin":"Jǐnguǎn tā yǐjīng hěn lèi le, kěshì háishi hěn nàixīn de gěi nǚ'ér dú shuìqián gùshi.","vn":"Dù cô ấy đã rất mệt, nhưng vẫn kiên nhẫn đọc truyện trước khi ngủ cho con gái."}]},{"title":"指示代词\"此\"","explanation_vn":"Đại từ chỉ định \"此\" biểu thị \"này, cái này\", thường dùng trong văn viết hoặc các trường hợp trang trọng.","examples":[{"cn":"此次出差，让两人熟悉了起来，从此成了好朋友。","pinyin":"Cǐcì chūchāi, ràng liǎng rén shúxī le qǐlái, cóngcǐ chéng le hǎo péngyou.","vn":"Chuyến công tác này đã giúp hai người trở nên thân thiết, từ đó trở thành bạn tốt."},{"cn":"此人聪明、有能力，一定能顺利完成任务。","pinyin":"Cǐrén cōngming, yǒu nénglì, yídìng néng shùnlì wánchéng rènwù.","vn":"Người này thông minh, có năng lực, nhất định sẽ hoàn thành nhiệm vụ thuận lợi."},{"cn":"此材料很重要，必须直接交给他。","pinyin":"Cǐ cáiliào hěn zhòngyào, bìxū zhíjiē jiāogěi tā.","vn":"Tài liệu này rất quan trọng, phải trực tiếp đưa cho anh ấy."}]},{"title":"时间副词\"从来\"","explanation_vn":"Phó từ chỉ thời gian \"从来\" chỉ việc gì đó luôn như vậy từ trước đến nay. Thường dùng trong câu phủ định, đôi khi cũng dùng trong câu khẳng định.","examples":[{"cn":"爱，从来都是相互尊重、理解与支持，不是吗？","pinyin":"Ài, cónglái dōu shì xiānghù zūnzhòng, lǐjiě yǔ zhīchí, bú shì ma?","vn":"Tình yêu, từ trước đến nay vẫn luôn là sự tôn trọng, thấu hiểu và ủng hộ lẫn nhau, phải không?"},{"cn":"我从来没见过这个颜色的花，它叫什么名字啊？","pinyin":"Wǒ cónglái méi jiànguo zhège yánsè de huā, tā jiào shénme míngzi a?","vn":"Tôi chưa từng thấy bông hoa màu này bao giờ, nó tên là gì vậy?"},{"cn":"我从来不喜欢一个人旅游，每次都要和家人或朋友一起去。","pinyin":"Wǒ cónglái bù xǐhuan yígè rén lǚyóu, měi cì dōu yào hé jiārén huò péngyou yìqǐ qù.","vn":"Tôi chưa bao giờ thích đi du lịch một mình, lần nào cũng phải đi cùng gia đình hoặc bạn bè."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"李文","cn":"家月，给你的，祝你生日快乐！","pinyin":"Jiāyuè, gěi nǐ de, zhù nǐ shēngrì kuàilè!"},{"speaker":"白家月","cn":"啊，好漂亮的花！还有巧克力！你怎么知道我喜欢这个巧克力？","pinyin":"Ā, hǎo piàoliang de huā! Hái yǒu qiǎokèlì! Nǐ zěnme zhīdào wǒ xǐhuan zhège qiǎokèlì?"},{"speaker":"李文","cn":"上次咱们去超市，看你拿起来看了看又放下了，我就记住了。","pinyin":"Shàng cì zánmen qù chāoshì, kàn nǐ ná qǐlái kàn le kàn yòu fàngxià le, wǒ jiù jìzhù le."},{"speaker":"白家月","cn":"好感动！我不说你也懂我在想什么，你真是细心又浪漫。其实刚认识不久，你的幽默与耐心就很吸引我，不过我当时也只把你当普通朋友。如果你没有一直找我聊天儿，我们可能就错过了。","pinyin":"Hǎo gǎndòng! Wǒ bù shuō nǐ yě dǒng wǒ zài xiǎng shénme, nǐ zhēnshi xìxīn yòu làngmàn. Qíshí gāng rènshi bùjiǔ, nǐ de yōumò yǔ nàixīn jiù hěn xīyǐn wǒ, búguò wǒ dāngshí yě zhǐ bǎ nǐ dàng pǔtōng péngyou. Rúguǒ nǐ méiyǒu yìzhí zhǎo wǒ liáotiānr, wǒmen kěnéng jiù cuòguò le."},{"speaker":"李文","cn":"我终于遇见了对的人，哪能错过呢？","pinyin":"Wǒ zhōngyú yùjiàn le duì de rén, nǎ néng cuòguò ne?"},{"speaker":"白家月","cn":"遇见你，我也觉得很幸运。","pinyin":"Yùjiàn nǐ, wǒ yě juéde hěn xìngyùn."}],"translation_vn":"Lý Văn: Gia Nguyệt, tặng em này, chúc em sinh nhật vui vẻ!\nBạch Gia Nguyệt: A, hoa đẹp quá! Còn có cả sô-cô-la nữa! Sao anh biết em thích loại sô-cô-la này?\nLý Văn: Lần trước mình đi siêu thị, anh thấy em cầm lên xem rồi lại đặt xuống, nên anh nhớ luôn.\nBạch Gia Nguyệt: Cảm động quá! Em không nói mà anh vẫn hiểu em đang nghĩ gì, anh đúng là người tinh tế lại lãng mạn. Thật ra mới quen nhau không lâu, sự hài hước và kiên nhẫn của anh đã rất thu hút em rồi, nhưng lúc đó em cũng chỉ coi anh là bạn bình thường thôi. Nếu anh không liên tục tìm em trò chuyện, có lẽ chúng ta đã bỏ lỡ nhau rồi.\nLý Văn: Cuối cùng anh cũng gặp được đúng người, sao có thể bỏ lỡ được chứ?\nBạch Gia Nguyệt: Gặp được anh, em cũng thấy mình thật may mắn.","audio_dialogue":"9-1.mp3","audio_vocab":"9-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"看到一飞和同乐结婚后这么幸福，我这个介绍人也特别开心。","pinyin":"Kàndào Yīfēi hé Tónglè jiéhūn hòu zhème xìngfú, wǒ zhège jièshàorén yě tèbié kāixīn."},{"speaker":"刘明","cn":"是啊，同乐是你的好朋友，一飞是你妹妹，你都很了解。","pinyin":"Shì a, Tónglè shì nǐ de hǎo péngyou, Yīfēi shì nǐ mèimei, nǐ dōu hěn liǎojiě."},{"speaker":"王一雪","cn":"嗯，他们尽管性格不同，但是有很多共同爱好。特别是同乐人好，性格也好，很有责任感。","pinyin":"Ng, tāmen jǐnguǎn xìnggé bùtóng, dànshì yǒu hěn duō gòngtóng àihào. Tèbié shì Tónglè rén hǎo, xìnggé yě hǎo, hěn yǒu zérèngǎn."},{"speaker":"刘明","cn":"是的，一飞也算在对的时间遇到了对的人。后边的路还很长，希望他们能一直相互理解、相互支持。","pinyin":"Shì de, Yīfēi yě suàn zài duì de shíjiān yùdào le duì de rén. Hòubian de lù hái hěn cháng, xīwàng tāmen néng yìzhí xiānghù lǐjiě, xiānghù zhīchí."},{"speaker":"王一雪","cn":"我了解同乐，更了解一飞，相信他们会一直走下去的。","pinyin":"Wǒ liǎojiě Tónglè, gèng liǎojiě Yīfēi, xiāngxìn tāmen huì yìzhí zǒu xiàqù de."},{"speaker":"刘明","cn":"祝他们越来越幸福。","pinyin":"Zhù tāmen yuè lái yuè xìngfú."}],"translation_vn":"Vương Nhất Tuyết: Thấy Nhất Phi và Đồng Lạc kết hôn hạnh phúc như vậy, mình là người mai mối cũng thấy đặc biệt vui.\nLưu Minh: Đúng vậy, Đồng Lạc là bạn thân của em, Nhất Phi là em gái em, em hiểu rõ cả hai người.\nVương Nhất Tuyết: Ừm, dù hai người tính cách khác nhau, nhưng có rất nhiều sở thích chung. Đặc biệt Đồng Lạc là người tốt, tính cách cũng tốt, rất có trách nhiệm.\nLưu Minh: Đúng vậy, Nhất Phi cũng coi như đã gặp đúng người vào đúng thời điểm. Con đường phía trước còn dài, hy vọng họ sẽ luôn thấu hiểu và ủng hộ lẫn nhau.\nVương Nhất Tuyết: Em hiểu Đồng Lạc, lại càng hiểu Nhất Phi hơn, tin rằng họ sẽ đi cùng nhau đến cuối con đường.\nLưu Minh: Chúc họ ngày càng hạnh phúc.","audio_dialogue":"9-3.mp3","audio_vocab":"9-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"王一雪比杨同乐更早进入公司。杨同乐刚来不久，王一雪对他印象就非常好：人很实在，性格阳光，工作负责，表现积极……后来他们一起出了次差，此次出差，让两人熟悉了起来，从此成了好朋友。一次聊天儿时，王一雪了解到杨同乐还没女朋友，正好自己的妹妹王一飞也没有男朋友，于是王一雪就把王一飞介绍给了他。杨同乐和王一飞认识后，很聊得来，两人之间慢慢产生了爱情，最后成了夫妻。杨同乐说自己很幸运，和王一雪这份同事间的友情，给他带来了美好的爱情。","pinyin":"Wáng Yīxuě bǐ Yáng Tónglè gèng zǎo jìnrù gōngsī. Yáng Tónglè gāng lái bùjiǔ, Wáng Yīxuě duì tā yìnxiàng jiù fēicháng hǎo: rén hěn shízài, xìnggé yángguāng, gōngzuò fùzé, biǎoxiàn jījí... Hòulái tāmen yìqǐ chū le cì chāi, cǐcì chūchāi, ràng liǎng rén shúxī le qǐlái, cóngcǐ chéng le hǎo péngyou. Yícì liáotiānr shí, Wáng Yīxuě liǎojiě dào Yáng Tónglè hái méi nǚpéngyou, zhènghǎo zìjǐ de mèimei Wáng Yīfēi yě méiyǒu nánpéngyou, yúshì Wáng Yīxuě jiù bǎ Wáng Yīfēi jièshào gěi le tā. Yáng Tónglè hé Wáng Yīfēi rènshi hòu, hěn liáo de lái, liǎng rén zhījiān mànmàn chǎnshēng le àiqíng, zuìhòu chéng le fūqī. Yáng Tónglè shuō zìjǐ hěn xìngyùn, hé Wáng Yīxuě zhè fèn tóngshì jiān de yǒuqíng, gěi tā dàilái le měihǎo de àiqíng."}],"translation_vn":"Vương Nhất Tuyết vào công ty sớm hơn Dương Đồng Lạc. Dương Đồng Lạc mới đến chưa lâu, Vương Nhất Tuyết đã có ấn tượng rất tốt về anh: con người thật thà, tính cách rạng rỡ, làm việc có trách nhiệm, thể hiện tích cực... Sau đó hai người cùng đi công tác một lần, chuyến công tác này đã giúp hai người trở nên thân thiết, từ đó trở thành bạn tốt của nhau. Trong một lần trò chuyện, Vương Nhất Tuyết biết được Dương Đồng Lạc vẫn chưa có bạn gái, đúng lúc em gái mình là Vương Nhất Phi cũng chưa có bạn trai, thế là Vương Nhất Tuyết liền giới thiệu Nhất Phi cho anh. Sau khi Dương Đồng Lạc và Vương Nhất Phi quen biết nhau, hai người rất hợp chuyện, tình cảm giữa họ dần dần nảy sinh, cuối cùng trở thành vợ chồng. Dương Đồng Lạc nói rằng mình thật may mắn, chính tình bạn đồng nghiệp này với Vương Nhất Tuyết đã mang đến cho anh một tình yêu tốt đẹp.","audio_dialogue":"9-5.mp3","audio_vocab":"9-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"李文在校园里遇见白家月，从此，他们的人生变得更加精彩；王一飞和杨同乐通过王一雪介绍认识后，感情越来越深，最后两人幸福地走到了一起。在我看来，遇见爱情的方式并不重要，重要的是在合适的时间遇到了合适的人。遇见你，刚刚好。不过美好的遇见只是爱的开始，爱更需要经营。在一段感情中，两个人要多关注对方的感受，尤其是结婚后，更要共同经营好家庭，日子才能越过越好。爱，从来都是相互尊重、理解与支持，不是吗？","pinyin":"Lǐ Wén zài xiàoyuán lǐ yùjiàn Bái Jiāyuè, cóngcǐ, tāmen de rénshēng biànde gèngjiā jīngcǎi; Wáng Yīfēi hé Yáng Tónglè tōngguò Wáng Yīxuě jièshào rènshi hòu, gǎnqíng yuè lái yuè shēn, zuìhòu liǎng rén xìngfú de zǒudào le yìqǐ. Zài wǒ kànlái, yùjiàn àiqíng de fāngshì bìng bú zhòngyào, zhòngyào de shì zài héshì de shíjiān yùdào le héshì de rén. Yùjiàn nǐ, gānggāng hǎo. Búguò měihǎo de yùjiàn zhǐshì ài de kāishǐ, ài gèng xūyào jīngyíng. Zài yíduàn gǎnqíng zhōng, liǎng ge rén yào duō guānzhù duìfāng de gǎnshòu, yóuqí shì jiéhūn hòu, gèng yào gòngtóng jīngyíng hǎo jiātíng, rìzi cái néng yuè guò yuè hǎo. Ài, cónglái dōu shì xiānghù zūnzhòng, lǐjiě yǔ zhīchí, bú shì ma?"}],"translation_vn":"Lý Văn gặp Bạch Gia Nguyệt trong khuôn viên trường, từ đó, cuộc sống của họ trở nên rực rỡ hơn; Vương Nhất Phi và Dương Đồng Lạc quen nhau qua sự giới thiệu của Vương Nhất Tuyết, tình cảm ngày càng sâu đậm, cuối cùng hai người đã hạnh phúc đến với nhau. Theo tôi, cách thức gặp được tình yêu không quan trọng, điều quan trọng là đã gặp đúng người vào đúng thời điểm. Gặp em, thật vừa vặn. Nhưng cuộc gặp gỡ tốt đẹp chỉ là khởi đầu của tình yêu, tình yêu còn cần được vun đắp nhiều hơn nữa. Trong một mối quan hệ, hai người cần quan tâm nhiều hơn đến cảm nhận của đối phương, đặc biệt là sau khi kết hôn, càng cần cùng nhau vun đắp tổ ấm, để cuộc sống ngày càng tốt đẹp hơn. Tình yêu, từ trước đến nay vẫn luôn là sự tôn trọng, thấu hiểu và ủng hộ lẫn nhau, phải không?","audio_dialogue":"9-7.mp3","audio_vocab":"9-8.mp3"}]},{"id":10,"title_cn":"南方不懂北方的冷","title_pinyin":"Nánfāng bù dǒng běifāng de lěng","title_vn":"Người miền Nam không hiểu cái lạnh miền Bắc","goals":["Có thể nghe hiểu và trao đổi các chủ đề liên quan đến mối quan hệ giữa khí hậu với môi trường, cuộc sống.","Có thể diễn đạt bằng lời nói hoặc văn viết về tầm quan trọng và cách thực hiện cụ thể của việc bảo vệ môi trường.","Hiểu được sự khác biệt về khí hậu, đời sống xã hội,... giữa miền Nam và miền Bắc Trung Quốc."],"vocab":[{"hanzi":"小伙子","pinyin":"xiǎohuǒzi","pos":"dt.","vn":"chàng trai, anh chàng","examples":[{"cn":"这个小伙子真能干。","pinyin":"Zhège xiǎohuǒzi zhēn nénggàn.","vn":"Chàng trai này thật giỏi giang."},{"cn":"那个小伙子长得很帅。","pinyin":"Nàge xiǎohuǒzi zhǎng de hěn shuài.","vn":"Chàng trai đó trông rất đẹp trai."},{"cn":"小伙子，你这是要去哪儿啊？","pinyin":"Xiǎohuǒzi, nǐ zhè shì yào qù nǎr a?","vn":"Này chàng trai, cậu định đi đâu vậy?"}]},{"hanzi":"气温","pinyin":"qìwēn","pos":"dt.","vn":"nhiệt độ không khí","examples":[{"cn":"今天气温下降了很多。","pinyin":"Jīntiān qìwēn xiàjiàngle hěn duō.","vn":"Hôm nay nhiệt độ không khí giảm xuống rất nhiều."},{"cn":"这几天气温一直很高。","pinyin":"Zhè jǐ tiān qìwēn yìzhí hěn gāo.","vn":"Mấy ngày nay nhiệt độ không khí luôn cao."},{"cn":"气温变化大，注意保暖。","pinyin":"Qìwēn biànhuà dà, zhùyì bǎonuǎn.","vn":"Nhiệt độ thay đổi lớn, chú ý giữ ấm."}]},{"hanzi":"零下","pinyin":"líng xià","pos":"","vn":"dưới 0 độ, âm độ","examples":[{"cn":"哈尔滨冬天经常是零下二十多度。","pinyin":"Hā'ěrbīn dōngtiān jīngcháng shì líng xià èrshí duō dù.","vn":"Mùa đông Cáp Nhĩ Tân thường âm hơn hai mươi độ."},{"cn":"今天气温零下五度，特别冷。","pinyin":"Jīntiān qìwēn líng xià wǔ dù, tèbié lěng.","vn":"Hôm nay nhiệt độ âm năm độ, lạnh vô cùng."},{"cn":"零下的天气里，河水都结冰了。","pinyin":"Líng xià de tiānqì lǐ, héshuǐ dōu jiébīng le.","vn":"Trong thời tiết dưới 0 độ, nước sông đã đóng băng."}]},{"hanzi":"度","pinyin":"dù","pos":"lượng.","vn":"độ","examples":[{"cn":"今天最高温度三十五度。","pinyin":"Jīntiān zuì gāo wēndù sānshíwǔ dù.","vn":"Nhiệt độ cao nhất hôm nay là ba mươi lăm độ."},{"cn":"水烧到一百度就会沸腾。","pinyin":"Shuǐ shāo dào yìbǎi dù jiù huì fèiténg.","vn":"Nước đun đến một trăm độ sẽ sôi."},{"cn":"这个角度大概是九十度。","pinyin":"Zhège jiǎodù dàgài shì jiǔshí dù.","vn":"Góc này khoảng chín mươi độ."}]},{"hanzi":"冻","pinyin":"dòng","pos":"dgt.","vn":"lạnh cóng, đóng băng","examples":[{"cn":"外面太冷了，我的手都冻僵了。","pinyin":"Wàimiàn tài lěng le, wǒ de shǒu dōu dòngjiāng le.","vn":"Bên ngoài lạnh quá, tay tôi lạnh cóng cứng cả lại."},{"cn":"把肉放进冰箱冻一下。","pinyin":"Bǎ ròu fàng jìn bīngxiāng dòng yíxià.","vn":"Cho thịt vào tủ lạnh đông một chút."},{"cn":"河面都冻住了。","pinyin":"Hémiàn dōu dòngzhù le.","vn":"Mặt sông đều đã đóng băng."}]},{"hanzi":"后悔","pinyin":"hòuhuǐ","pos":"dgt.","vn":"hối hận","examples":[{"cn":"我很后悔当初没有好好学习。","pinyin":"Wǒ hěn hòuhuǐ dāngchū méiyǒu hǎohāo xuéxí.","vn":"Tôi rất hối hận vì ngày trước đã không học hành đàng hoàng."},{"cn":"你要是现在放弃，以后会后悔的。","pinyin":"Nǐ yàoshi xiànzài fàngqì, yǐhòu huì hòuhuǐ de.","vn":"Nếu bây giờ bạn bỏ cuộc, sau này sẽ hối hận đấy."},{"cn":"他后悔没有听父母的话。","pinyin":"Tā hòuhuǐ méiyǒu tīng fùmǔ de huà.","vn":"Anh ấy hối hận vì không nghe lời bố mẹ."}]},{"hanzi":"就是","pinyin":"jiùshì","pos":"phó.","vn":"đúng vậy, chính là","examples":[{"cn":"对，我就是这个意思。","pinyin":"Duì, wǒ jiùshì zhège yìsi.","vn":"Đúng vậy, ý tôi chính là như vậy."},{"cn":"他就是我们常说的那个人。","pinyin":"Tā jiùshì wǒmen cháng shuō de nàge rén.","vn":"Anh ta chính là người mà chúng ta hay nhắc tới."},{"cn":"就是因为下雨，比赛才取消了。","pinyin":"Jiùshì yīnwèi xiàyǔ, bǐsài cái qǔxiāo le.","vn":"Chính vì trời mưa nên trận đấu mới bị hủy."}]},{"hanzi":"温度","pinyin":"wēndù","pos":"dt.","vn":"nhiệt độ","examples":[{"cn":"今天的温度有点低。","pinyin":"Jīntiān de wēndù yǒudiǎn dī.","vn":"Nhiệt độ hôm nay hơi thấp."},{"cn":"请调一下空调的温度。","pinyin":"Qǐng tiáo yíxià kōngtiáo de wēndù.","vn":"Làm ơn chỉnh lại nhiệt độ điều hòa."},{"cn":"这里的温度全年都很稳定。","pinyin":"Zhèlǐ de wēndù quánnián dōu hěn wěndìng.","vn":"Nhiệt độ ở đây ổn định quanh năm."}]},{"hanzi":"差别","pinyin":"chābié","pos":"dt.","vn":"sự khác biệt","examples":[{"cn":"南方和北方的气候差别很大。","pinyin":"Nánfāng hé běifāng de qìhòu chābié hěn dà.","vn":"Khí hậu miền Nam và miền Bắc khác nhau rất nhiều."},{"cn":"这两种产品质量差别不大。","pinyin":"Zhè liǎng zhǒng chǎnpǐn zhìliàng chābié bú dà.","vn":"Chất lượng của hai sản phẩm này không khác nhau nhiều."},{"cn":"他们俩的想法差别很大。","pinyin":"Tāmen liǎ de xiǎngfǎ chābié hěn dà.","vn":"Suy nghĩ của hai người họ khác nhau rất nhiều."}]},{"hanzi":"厚","pinyin":"hòu","pos":"tt.","vn":"dày","examples":[{"cn":"这本书很厚，我还没看完。","pinyin":"Zhè běn shū hěn hòu, wǒ hái méi kànwán.","vn":"Cuốn sách này rất dày, tôi vẫn chưa đọc xong."},{"cn":"冬天要穿厚一点的衣服。","pinyin":"Dōngtiān yào chuān hòu yìdiǎn de yīfu.","vn":"Mùa đông phải mặc quần áo dày hơn một chút."},{"cn":"这件大衣挺厚的，很保暖。","pinyin":"Zhè jiàn dàyī tǐng hòu de, hěn bǎonuǎn.","vn":"Chiếc áo khoác này khá dày, rất giữ ấm."}]},{"hanzi":"广州","pinyin":"Guǎngzhōu","pos":"danh từ riêng","vn":"Quảng Châu","examples":[{"cn":"我下个月要去广州出差。","pinyin":"Wǒ xià ge yuè yào qù Guǎngzhōu chūchāi.","vn":"Tháng sau tôi phải đi công tác Quảng Châu."},{"cn":"广州的夏天特别热。","pinyin":"Guǎngzhōu de xiàtiān tèbié rè.","vn":"Mùa hè ở Quảng Châu đặc biệt nóng."},{"cn":"她是广州人。","pinyin":"Tā shì Guǎngzhōu rén.","vn":"Cô ấy là người Quảng Châu."}]},{"hanzi":"哈尔滨","pinyin":"Hā'ěrbīn","pos":"danh từ riêng","vn":"Cáp Nhĩ Tân","examples":[{"cn":"哈尔滨的冰雕很有名。","pinyin":"Hā'ěrbīn de bīngdiāo hěn yǒumíng.","vn":"Tượng băng ở Cáp Nhĩ Tân rất nổi tiếng."},{"cn":"哈尔滨冬天非常冷。","pinyin":"Hā'ěrbīn dōngtiān fēicháng lěng.","vn":"Mùa đông ở Cáp Nhĩ Tân rất lạnh."},{"cn":"他是哈尔滨人，特别能喝酒。","pinyin":"Tā shì Hā'ěrbīn rén, tèbié néng hē jiǔ.","vn":"Anh ấy là người Cáp Nhĩ Tân, uống rượu rất giỏi."}]},{"hanzi":"寒假","pinyin":"hánjià","pos":"dt.","vn":"kỳ nghỉ đông","examples":[{"cn":"寒假我打算回老家过年。","pinyin":"Hánjià wǒ dǎsuàn huí lǎojiā guònián.","vn":"Kỳ nghỉ đông tôi định về quê ăn Tết."},{"cn":"孩子们寒假都在家写作业。","pinyin":"Háizimen hánjià dōu zài jiā xiě zuòyè.","vn":"Bọn trẻ nghỉ đông đều ở nhà làm bài tập."},{"cn":"寒假期间学校不上课。","pinyin":"Hánjià qījiān xuéxiào bú shàngkè.","vn":"Trong kỳ nghỉ đông trường không học."}]},{"hanzi":"暖和","pinyin":"nuǎnhuo","pos":"tt./dgt.","vn":"ấm áp; trở nên ấm áp","examples":[{"cn":"今天天气很暖和。","pinyin":"Jīntiān tiānqì hěn nuǎnhuo.","vn":"Hôm nay thời tiết rất ấm áp."},{"cn":"多穿点衣服，暖和一些。","pinyin":"Duō chuān diǎn yīfu, nuǎnhuo yìxiē.","vn":"Mặc thêm quần áo để ấm hơn một chút."},{"cn":"屋里开了暖气，特别暖和。","pinyin":"Wū lǐ kāile nuǎnqì, tèbié nuǎnhuo.","vn":"Trong phòng bật lò sưởi nên rất ấm áp."}]},{"hanzi":"低于","pinyin":"dīyú","pos":"dgt.","vn":"thấp hơn","examples":[{"cn":"今天的气温低于零度。","pinyin":"Jīntiān de qìwēn dīyú líng dù.","vn":"Nhiệt độ hôm nay thấp hơn 0 độ."},{"cn":"这个月的销售额低于预期。","pinyin":"Zhège yuè de xiāoshòu'é dīyú yùqī.","vn":"Doanh số tháng này thấp hơn dự kiến."},{"cn":"他的分数低于及格线。","pinyin":"Tā de fēnshù dīyú jígéxiàn.","vn":"Điểm số của anh ấy thấp hơn điểm đạt."}]},{"hanzi":"摄氏度","pinyin":"shèshìdù","pos":"lượng.","vn":"độ C","examples":[{"cn":"今天气温是三十摄氏度。","pinyin":"Jīntiān qìwēn shì sānshí shèshìdù.","vn":"Nhiệt độ hôm nay là ba mươi độ C."},{"cn":"水的沸点是一百摄氏度。","pinyin":"Shuǐ de fèidiǎn shì yìbǎi shèshìdù.","vn":"Điểm sôi của nước là một trăm độ C."},{"cn":"这里冬天气温能到零下十摄氏度。","pinyin":"Zhèlǐ dōngtiān qìwēn néng dào líng xià shí shèshìdù.","vn":"Mùa đông ở đây nhiệt độ có thể xuống âm mười độ C."}]},{"hanzi":"受不了","pinyin":"shòubuliǎo","pos":"dgt.","vn":"không chịu nổi","examples":[{"cn":"这里的天气太热了，我真受不了。","pinyin":"Zhèlǐ de tiānqì tài rè le, wǒ zhēn shòubuliǎo.","vn":"Thời tiết ở đây nóng quá, tôi thực sự không chịu nổi."},{"cn":"他说话太啰嗦，我都受不了了。","pinyin":"Tā shuōhuà tài luōsuo, wǒ dōu shòubuliǎo le.","vn":"Anh ấy nói chuyện dài dòng quá, tôi không chịu nổi nữa."},{"cn":"这种噪音让人受不了。","pinyin":"Zhè zhǒng zàoyīn ràng rén shòubuliǎo.","vn":"Tiếng ồn kiểu này khiến người ta không chịu nổi."}]},{"hanzi":"举办","pinyin":"jǔbàn","pos":"dgt.","vn":"tổ chức","examples":[{"cn":"学校下周要举办一场运动会。","pinyin":"Xuéxiào xià zhōu yào jǔbàn yì chǎng yùndònghuì.","vn":"Tuần sau trường sẽ tổ chức một hội thao."},{"cn":"这次晚会是由学生会举办的。","pinyin":"Zhè cì wǎnhuì shì yóu xuéshēnghuì jǔbàn de.","vn":"Buổi tối văn nghệ lần này do hội sinh viên tổ chức."},{"cn":"北京举办过奥运会。","pinyin":"Běijīng jǔbànguò Àoyùnhuì.","vn":"Bắc Kinh từng tổ chức Thế vận hội."}]},{"hanzi":"各种","pinyin":"gèzhǒng","pos":"đt.","vn":"các loại, mọi loại","examples":[{"cn":"市场上有各种各样的水果。","pinyin":"Shìchǎng shàng yǒu gè zhǒng gè yàng de shuǐguǒ.","vn":"Ở chợ có đủ các loại trái cây."},{"cn":"他经历过各种困难。","pinyin":"Tā jīnglìguò gèzhǒng kùnnan.","vn":"Anh ấy đã trải qua đủ các loại khó khăn."},{"cn":"这里提供各种服务。","pinyin":"Zhèlǐ tígōng gèzhǒng fúwù.","vn":"Ở đây cung cấp đủ các loại dịch vụ."}]},{"hanzi":"植物","pinyin":"zhíwù","pos":"dt.","vn":"thực vật","examples":[{"cn":"她家阳台上种了很多植物。","pinyin":"Tā jiā yángtái shàng zhòngle hěn duō zhíwù.","vn":"Trên ban công nhà cô ấy trồng rất nhiều cây."},{"cn":"这种植物只能在热带生长。","pinyin":"Zhè zhǒng zhíwù zhǐnéng zài rèdài shēngzhǎng.","vn":"Loại thực vật này chỉ sinh trưởng được ở vùng nhiệt đới."},{"cn":"他很喜欢研究植物。","pinyin":"Tā hěn xǐhuan yánjiū zhíwù.","vn":"Anh ấy rất thích nghiên cứu thực vật."}]},{"hanzi":"公里","pinyin":"gōnglǐ","pos":"lượng.","vn":"ki-lô-mét","examples":[{"cn":"这里离市中心大概十公里。","pinyin":"Zhèlǐ lí shìzhōngxīn dàgài shí gōnglǐ.","vn":"Chỗ này cách trung tâm thành phố khoảng mười ki-lô-mét."},{"cn":"他每天跑五公里。","pinyin":"Tā měitiān pǎo wǔ gōnglǐ.","vn":"Anh ấy chạy bộ năm ki-lô-mét mỗi ngày."},{"cn":"这条路全长一百多公里。","pinyin":"Zhè tiáo lù quáncháng yìbǎi duō gōnglǐ.","vn":"Con đường này dài tổng cộng hơn một trăm ki-lô-mét."}]},{"hanzi":"气候","pinyin":"qìhòu","pos":"dt.","vn":"khí hậu","examples":[{"cn":"这里的气候四季分明。","pinyin":"Zhèlǐ de qìhòu sìjì fēnmíng.","vn":"Khí hậu ở đây bốn mùa rõ rệt."},{"cn":"南方气候比较潮湿。","pinyin":"Nánfāng qìhòu bǐjiào cháoshī.","vn":"Khí hậu miền Nam khá ẩm ướt."},{"cn":"气候变化对农业影响很大。","pinyin":"Qìhòu biànhuà duì nóngyè yǐngxiǎng hěn dà.","vn":"Biến đổi khí hậu ảnh hưởng rất lớn đến nông nghiệp."}]},{"hanzi":"而","pinyin":"ér","pos":"liên.","vn":"mà, nhưng, và","examples":[{"cn":"他不是不努力，而是方法不对。","pinyin":"Tā búshì bù nǔlì, érshì fāngfǎ bú duì.","vn":"Anh ấy không phải không cố gắng, mà là phương pháp sai."},{"cn":"这件事说起来容易，而做起来很难。","pinyin":"Zhè jiàn shì shuō qǐlái róngyì, ér zuò qǐlái hěn nán.","vn":"Việc này nói thì dễ, nhưng làm thì rất khó."},{"cn":"她既聪明而又勤奋。","pinyin":"Tā jì cōngming ér yòu qínfèn.","vn":"Cô ấy vừa thông minh lại vừa chăm chỉ."}]},{"hanzi":"此外","pinyin":"cǐwài","pos":"liên.","vn":"ngoài ra","examples":[{"cn":"此外，我们还需要准备一些材料。","pinyin":"Cǐwài, wǒmen hái xūyào zhǔnbèi yìxiē cáiliào.","vn":"Ngoài ra, chúng ta còn cần chuẩn bị thêm một số tài liệu."},{"cn":"他会说英语，此外还会说法语。","pinyin":"Tā huì shuō Yīngyǔ, cǐwài hái huì shuō Fǎyǔ.","vn":"Anh ấy biết nói tiếng Anh, ngoài ra còn biết nói tiếng Pháp."},{"cn":"此外，这个计划还有一些细节需要讨论。","pinyin":"Cǐwài, zhège jìhuà hái yǒu yìxiē xìjié xūyào tǎolùn.","vn":"Ngoài ra, kế hoạch này còn có một số chi tiết cần bàn bạc."}]},{"hanzi":"方言","pinyin":"fāngyán","pos":"dt.","vn":"phương ngữ, tiếng địa phương","examples":[{"cn":"中国各地的方言差别很大。","pinyin":"Zhōngguó gèdì de fāngyán chābié hěn dà.","vn":"Tiếng địa phương ở các vùng của Trung Quốc khác nhau rất nhiều."},{"cn":"我听不懂他说的方言。","pinyin":"Wǒ tīngbudǒng tā shuō de fāngyán.","vn":"Tôi không nghe hiểu tiếng địa phương anh ấy nói."},{"cn":"她能说好几种方言。","pinyin":"Tā néng shuō hǎo jǐ zhǒng fāngyán.","vn":"Cô ấy biết nói mấy loại phương ngữ."}]},{"hanzi":"普通话","pinyin":"pǔtōnghuà","pos":"dt.","vn":"tiếng phổ thông (Trung Quốc)","examples":[{"cn":"他的普通话说得很标准。","pinyin":"Tā de pǔtōnghuà shuō de hěn biāozhǔn.","vn":"Anh ấy nói tiếng phổ thông rất chuẩn."},{"cn":"在学校老师都用普通话教学。","pinyin":"Zài xuéxiào lǎoshī dōu yòng pǔtōnghuà jiàoxué.","vn":"Ở trường thầy cô đều dùng tiếng phổ thông để giảng dạy."},{"cn":"我正在学习普通话。","pinyin":"Wǒ zhèngzài xuéxí pǔtōnghuà.","vn":"Tôi đang học tiếng phổ thông."}]},{"hanzi":"较","pinyin":"jiào","pos":"phó.","vn":"tương đối, khá","examples":[{"cn":"这个方法较为简单。","pinyin":"Zhège fāngfǎ jiàowéi jiǎndān.","vn":"Phương pháp này tương đối đơn giản."},{"cn":"今年的收入较去年有所增长。","pinyin":"Jīnnián de shōurù jiào qùnián yǒusuǒ zēngzhǎng.","vn":"Thu nhập năm nay tăng hơn so với năm ngoái."},{"cn":"他的态度较以前好多了。","pinyin":"Tā de tàidu jiào yǐqián hǎo duō le.","vn":"Thái độ của anh ấy khá hơn trước nhiều."}]},{"hanzi":"使用","pinyin":"shǐyòng","pos":"dgt.","vn":"sử dụng","examples":[{"cn":"请按照说明书正确使用这个产品。","pinyin":"Qǐng ànzhào shuōmíngshū zhèngquè shǐyòng zhège chǎnpǐn.","vn":"Xin hãy sử dụng sản phẩm này đúng cách theo hướng dẫn."},{"cn":"这个软件使用起来很方便。","pinyin":"Zhège ruǎnjiàn shǐyòng qǐlái hěn fāngbiàn.","vn":"Phần mềm này sử dụng rất tiện lợi."},{"cn":"他经常使用这台电脑工作。","pinyin":"Tā jīngcháng shǐyòng zhè tái diànnǎo gōngzuò.","vn":"Anh ấy thường xuyên dùng chiếc máy tính này để làm việc."}]},{"hanzi":"引起","pinyin":"yǐnqǐ","pos":"dgt.","vn":"gây ra","examples":[{"cn":"这件事引起了大家的注意。","pinyin":"Zhè jiàn shì yǐnqǐle dàjiā de zhùyì.","vn":"Việc này đã thu hút sự chú ý của mọi người."},{"cn":"他的发言引起了争论。","pinyin":"Tā de fāyán yǐnqǐle zhēnglùn.","vn":"Bài phát biểu của anh ấy đã gây ra tranh luận."},{"cn":"吸烟容易引起肺部疾病。","pinyin":"Xīyān róngyì yǐnqǐ fèibù jíbìng.","vn":"Hút thuốc dễ gây ra bệnh về phổi."}]},{"hanzi":"误会","pinyin":"wùhuì","pos":"dt./dgt.","vn":"hiểu lầm","examples":[{"cn":"这只是个误会，我们解释清楚就好了。","pinyin":"Zhè zhǐshì ge wùhuì, wǒmen jiěshì qīngchu jiù hǎole.","vn":"Đây chỉ là hiểu lầm thôi, chúng ta giải thích rõ là được."},{"cn":"他误会了我的意思。","pinyin":"Tā wùhuìle wǒ de yìsi.","vn":"Anh ấy đã hiểu lầm ý của tôi."},{"cn":"别误会，我不是那个意思。","pinyin":"Bié wùhuì, wǒ búshì nàge yìsi.","vn":"Đừng hiểu lầm, tôi không có ý đó."}]},{"hanzi":"亲爱","pinyin":"qīn'ài","pos":"tt.","vn":"thân mến","examples":[{"cn":"亲爱的朋友们，大家好。","pinyin":"Qīn'ài de péngyoumen, dàjiā hǎo.","vn":"Các bạn thân mến, xin chào mọi người."},{"cn":"亲爱的，我回来了。","pinyin":"Qīn'ài de, wǒ huílái le.","vn":"Em yêu, anh về rồi."},{"cn":"亲爱的妈妈，我很想你。","pinyin":"Qīn'ài de māma, wǒ hěn xiǎng nǐ.","vn":"Mẹ thân yêu, con rất nhớ mẹ."}]},{"hanzi":"再次","pinyin":"zàicì","pos":"phó.","vn":"một lần nữa","examples":[{"cn":"我再次提醒大家注意安全。","pinyin":"Wǒ zàicì tíxǐng dàjiā zhùyì ānquán.","vn":"Tôi một lần nữa nhắc nhở mọi người chú ý an toàn."},{"cn":"他们再次见面已经是十年后了。","pinyin":"Tāmen zàicì jiànmiàn yǐjīng shì shí nián hòu le.","vn":"Họ gặp lại nhau một lần nữa đã là mười năm sau."},{"cn":"请再次确认一下信息是否正确。","pinyin":"Qǐng zàicì quèrèn yíxià xìnxī shìfǒu zhèngquè.","vn":"Xin hãy xác nhận lại một lần nữa xem thông tin có chính xác không."}]},{"hanzi":"开展","pinyin":"kāizhǎn","pos":"dgt.","vn":"triển khai","examples":[{"cn":"学校将开展一系列环保活动。","pinyin":"Xuéxiào jiāng kāizhǎn yíxìliè huánbǎo huódòng.","vn":"Nhà trường sẽ triển khai một loạt hoạt động bảo vệ môi trường."},{"cn":"公司决定在海外开展业务。","pinyin":"Gōngsī juédìng zài hǎiwài kāizhǎn yèwù.","vn":"Công ty quyết định triển khai kinh doanh ở nước ngoài."},{"cn":"这项工作正在顺利开展。","pinyin":"Zhè xiàng gōngzuò zhèngzài shùnlì kāizhǎn.","vn":"Công việc này đang được triển khai thuận lợi."}]},{"hanzi":"绿色","pinyin":"lǜsè","pos":"tt.","vn":"xanh, thân thiện với môi trường","examples":[{"cn":"现在很多人提倡绿色出行。","pinyin":"Xiànzài hěn duō rén tíchàng lǜsè chūxíng.","vn":"Hiện nay nhiều người đề xướng di chuyển xanh, thân thiện môi trường."},{"cn":"她喜欢穿绿色的衣服。","pinyin":"Tā xǐhuan chuān lǜsè de yīfu.","vn":"Cô ấy thích mặc quần áo màu xanh."},{"cn":"这是一款绿色环保产品。","pinyin":"Zhè shì yì kuǎn lǜsè huánbǎo chǎnpǐn.","vn":"Đây là một sản phẩm xanh, thân thiện với môi trường."}]},{"hanzi":"环保","pinyin":"huánbǎo","pos":"dt./tt.","vn":"bảo vệ môi trường","examples":[{"cn":"我们应该提高环保意识。","pinyin":"Wǒmen yīnggāi tígāo huánbǎo yìshí.","vn":"Chúng ta nên nâng cao ý thức bảo vệ môi trường."},{"cn":"这种材料很环保。","pinyin":"Zhè zhǒng cáiliào hěn huánbǎo.","vn":"Loại vật liệu này rất thân thiện với môi trường."},{"cn":"政府大力推广环保政策。","pinyin":"Zhèngfǔ dàlì tuīguǎng huánbǎo zhèngcè.","vn":"Chính phủ ra sức thúc đẩy chính sách bảo vệ môi trường."}]},{"hanzi":"拒绝","pinyin":"jùjué","pos":"dgt.","vn":"từ chối","examples":[{"cn":"他拒绝了我的请求。","pinyin":"Tā jùjuéle wǒ de qǐngqiú.","vn":"Anh ấy đã từ chối yêu cầu của tôi."},{"cn":"她很委婉地拒绝了那份工作。","pinyin":"Tā hěn wěiwǎn de jùjuéle nà fèn gōngzuò.","vn":"Cô ấy đã khéo léo từ chối công việc đó."},{"cn":"面对诱惑，他果断地拒绝了。","pinyin":"Miànduì yòuhuò, tā guǒduàn de jùjuéle.","vn":"Đối mặt với cám dỗ, anh ấy đã dứt khoát từ chối."}]},{"hanzi":"浪费","pinyin":"làngfèi","pos":"dgt.","vn":"lãng phí","examples":[{"cn":"别浪费粮食。","pinyin":"Bié làngfèi liángshi.","vn":"Đừng lãng phí lương thực."},{"cn":"这样做太浪费时间了。","pinyin":"Zhèyàng zuò tài làngfèi shíjiān le.","vn":"Làm như vậy quá lãng phí thời gian."},{"cn":"他从不浪费一分钱。","pinyin":"Tā cóngbù làngfèi yì fēn qián.","vn":"Anh ấy không bao giờ lãng phí dù một đồng."}]},{"hanzi":"节约","pinyin":"jiéyuē","pos":"dgt.","vn":"tiết kiệm","examples":[{"cn":"我们应该节约用水。","pinyin":"Wǒmen yīnggāi jiéyuē yòngshuǐ.","vn":"Chúng ta nên tiết kiệm nước."},{"cn":"她生活很节约，不乱花钱。","pinyin":"Tā shēnghuó hěn jiéyuē, bú luàn huāqián.","vn":"Cô ấy sống rất tiết kiệm, không tiêu tiền bừa bãi."},{"cn":"节约能源，从我做起。","pinyin":"Jiéyuē néngyuán, cóng wǒ zuòqǐ.","vn":"Tiết kiệm năng lượng, bắt đầu từ chính tôi."}]},{"hanzi":"资源","pinyin":"zīyuán","pos":"dt.","vn":"tài nguyên","examples":[{"cn":"水是非常宝贵的资源。","pinyin":"Shuǐ shì fēicháng bǎoguì de zīyuán.","vn":"Nước là nguồn tài nguyên vô cùng quý giá."},{"cn":"这个地区自然资源丰富。","pinyin":"Zhège dìqū zìrán zīyuán fēngfù.","vn":"Khu vực này tài nguyên thiên nhiên phong phú."},{"cn":"我们要合理利用资源。","pinyin":"Wǒmen yào hélǐ lìyòng zīyuán.","vn":"Chúng ta phải sử dụng tài nguyên một cách hợp lý."}]},{"hanzi":"光","pinyin":"guāng","pos":"tt.","vn":"hết sạch","examples":[{"cn":"他把身上的钱都花光了。","pinyin":"Tā bǎ shēnshang de qián dōu huāguāng le.","vn":"Anh ấy tiêu hết sạch tiền trong người."},{"cn":"这瓶水我一口气喝光了。","pinyin":"Zhè píng shuǐ wǒ yìkǒuqì hēguāng le.","vn":"Chai nước này tôi uống hết sạch một hơi."},{"cn":"饭都被孩子们吃光了。","pinyin":"Fàn dōu bèi háizimen chīguāng le.","vn":"Cơm đã bị bọn trẻ ăn hết sạch."}]},{"hanzi":"垃圾","pinyin":"lājī","pos":"dt.","vn":"rác","examples":[{"cn":"请把垃圾扔进垃圾桶。","pinyin":"Qǐng bǎ lājī rēng jìn lājītǒng.","vn":"Xin hãy vứt rác vào thùng rác."},{"cn":"这里到处都是垃圾。","pinyin":"Zhèlǐ dàochù dōu shì lājī.","vn":"Nơi này khắp nơi đều là rác."},{"cn":"我们应该学会垃圾分类。","pinyin":"Wǒmen yīnggāi xuéhuì lājī fēnlèi.","vn":"Chúng ta nên học cách phân loại rác."}]},{"hanzi":"分类","pinyin":"fēnlèi","pos":"dgt.","vn":"phân loại","examples":[{"cn":"垃圾要分类处理。","pinyin":"Lājī yào fēnlèi chǔlǐ.","vn":"Rác phải được xử lý theo phân loại."},{"cn":"这些文件需要按类别分类。","pinyin":"Zhèxiē wénjiàn xūyào àn lèibié fēnlèi.","vn":"Những tài liệu này cần được phân loại theo hạng mục."},{"cn":"图书馆的书都按主题分类摆放。","pinyin":"Túshūguǎn de shū dōu àn zhǔtí fēnlèi bǎifàng.","vn":"Sách trong thư viện đều được phân loại và sắp xếp theo chủ đề."}]},{"hanzi":"日常","pinyin":"rìcháng","pos":"tt.","vn":"thường ngày, hàng ngày","examples":[{"cn":"这些都是我们日常生活中常用的东西。","pinyin":"Zhèxiē dōu shì wǒmen rìcháng shēnghuó zhōng chángyòng de dōngxi.","vn":"Đây đều là những thứ thường dùng trong cuộc sống hàng ngày của chúng ta."},{"cn":"他把日常开支记得很清楚。","pinyin":"Tā bǎ rìcháng kāizhī jì de hěn qīngchu.","vn":"Anh ấy ghi chép chi tiêu hàng ngày rất rõ ràng."},{"cn":"保持日常锻炼对身体很好。","pinyin":"Bǎochí rìcháng duànliàn duì shēntǐ hěn hǎo.","vn":"Duy trì tập luyện hàng ngày rất tốt cho sức khỏe."}]}],"grammar":[{"title":"固定格式\"说什么/怎么（着）也得×\"","explanation_vn":"Cấu trúc cố định \"说什么/怎么（着）也得×\" biểu thị sự cần thiết hoặc quyết tâm bắt buộc phải làm gì đó, thường dùng trong khẩu ngữ.","examples":[{"cn":"更重要的是，说什么也得穿上厚一点儿的衣服。","pinyin":"Gèng zhòngyào de shì, shuō shénme yě děi chuānshang hòu yìdiǎnr de yīfu.","vn":"Quan trọng hơn là, dù thế nào cũng phải mặc quần áo dày một chút."},{"cn":"假期还有两天就结束了，我明天说什么也得把作业做完了。","pinyin":"Jiàqī hái yǒu liǎng tiān jiù jiéshù le, wǒ míngtiān shuō shénme yě děi bǎ zuòyè zuòwán le.","vn":"Kỳ nghỉ còn hai ngày nữa là kết thúc, ngày mai dù thế nào tôi cũng phải làm xong bài tập."},{"cn":"我很后悔上次没参加这个活动，这次怎么着也得去。","pinyin":"Wǒ hěn hòuhuǐ shàng cì méi cānjiā zhège huódòng, zhè cì zěnmezhe yě děi qù.","vn":"Tôi rất hối hận vì lần trước không tham gia hoạt động này, lần này dù thế nào cũng phải đi."}]},{"title":"固定短语\"有的是\"","explanation_vn":"Cụm từ cố định \"有的是\" thường dùng trong khẩu ngữ, biểu thị có rất nhiều, nhấn mạnh số lượng dồi dào.","examples":[{"cn":"没问题，受得了，我有的是厚衣服。","pinyin":"Méi wèntí, shòudeliǎo, wǒ yǒudeshì hòu yīfu.","vn":"Không vấn đề gì, chịu được, tôi có thừa quần áo dày."},{"cn":"过年时，家里有的是好吃的、好喝的，孩子们特别开心。","pinyin":"Guònián shí, jiālǐ yǒudeshì hǎochī de, hǎohē de, háizimen tèbié kāixīn.","vn":"Dịp Tết, trong nhà có đầy đồ ăn ngon, đồ uống ngon, bọn trẻ đặc biệt vui."},{"cn":"这个市场特别大，有的是水果和菜，你想买什么菜都能买到。","pinyin":"Zhège shìchǎng tèbié dà, yǒudeshì shuǐguǒ hé cài, nǐ xiǎng mǎi shénme cài dōu néng mǎidào.","vn":"Khu chợ này rất lớn, có đủ loại hoa quả và rau, bạn muốn mua rau gì cũng mua được."}]},{"title":"连词\"而\"","explanation_vn":"Liên từ \"而\" nối động từ, tính từ hoặc cụm từ, vế câu, có nhiều nghĩa khác nhau, ở đây giới thiệu ba cách dùng: (1) biểu thị sự chuyển ý, \"而\" nối hai thành phần có ý nghĩa trái ngược nhau; (2) biểu thị sự tiếp nối về mặt ý nghĩa; (3) biểu thị quan hệ nhân quả trước sau về mặt sự lý.","examples":[{"cn":"广州基本上没有冬天，而哈尔滨的冬天一般会从十月开始，到第二年的三四月才结束。","pinyin":"Guǎngzhōu jīběnshàng méiyǒu dōngtiān, ér Hā'ěrbīn de dōngtiān yìbān huì cóng shíyuè kāishǐ, dào dì èr nián de sānsìyuè cái jiéshù.","vn":"Quảng Châu hầu như không có mùa đông, còn mùa đông ở Cáp Nhĩ Tân thường bắt đầu từ tháng Mười, đến tận tháng Ba tháng Tư năm sau mới kết thúc."},{"cn":"在这个紧张而兴奋的日子里，我们都走出教室，为运动员们加油。","pinyin":"Zài zhège jǐnzhāng ér xīngfèn de rìzi lǐ, wǒmen dōu zǒuchū jiàoshì, wèi yùndòngyuánmen jiāyóu.","vn":"Trong những ngày căng thẳng mà phấn khích này, chúng tôi đều ra khỏi lớp học để cổ vũ cho các vận động viên."},{"cn":"冬天，这个城市因为天气暖和而吸引了很多游客。","pinyin":"Dōngtiān, zhège chéngshì yīnwèi tiānqì nuǎnhuo ér xīyǐn le hěn duō yóukè.","vn":"Vào mùa đông, thành phố này vì thời tiết ấm áp nên thu hút rất nhiều du khách."}]},{"title":"频率副词\"再次\"","explanation_vn":"Phó từ tần suất \"再次\" đứng trước động từ, biểu thị lần thứ hai, thêm một lần nữa.","examples":[{"cn":"今年的\"世界环境日\"，我们再次开展\"绿色生活\"活动。","pinyin":"Jīnnián de \"Shìjiè Huánjìng Rì\", wǒmen zàicì kāizhǎn \"Lǜsè Shēnghuó\" huódòng.","vn":"Nhân \"Ngày Môi trường Thế giới\" năm nay, chúng ta lại tiếp tục triển khai hoạt động \"Sống xanh\"."},{"cn":"我去年冬天去过一次哈尔滨，很喜欢那里的雪；今年冬天，我计划再次去哈尔滨看雪。","pinyin":"Wǒ qùnián dōngtiān qù guo yícì Hā'ěrbīn, hěn xǐhuan nàlǐ de xuě; jīnnián dōngtiān, wǒ jìhuà zàicì qù Hā'ěrbīn kàn xuě.","vn":"Mùa đông năm ngoái tôi từng đến Cáp Nhĩ Tân một lần, rất thích tuyết ở đó; mùa đông năm nay, tôi dự định đi Cáp Nhĩ Tân ngắm tuyết một lần nữa."},{"cn":"再次感谢您的支持与关心！","pinyin":"Zàicì gǎnxiè nín de zhīchí yǔ guānxīn!","vn":"Một lần nữa xin cảm ơn sự ủng hộ và quan tâm của quý vị!"}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"刘明","cn":"你看，这个小伙子从广州去哈尔滨出差，没想到哈尔滨的气温降到了零下二十几度，把他冻坏了。","pinyin":"Nǐ kàn, zhège xiǎohuǒzi cóng Guǎngzhōu qù Hā'ěrbīn chūchāi, méi xiǎngdào Hā'ěrbīn de qìwēn jiàng dào le língxià èrshí jǐ dù, bǎ tā dònghuài le."},{"speaker":"王一雪","cn":"他一定后悔自己穿少了吧？","pinyin":"Tā yídìng hòuhuǐ zìjǐ chuān shǎo le ba?"},{"speaker":"刘明","cn":"是啊，这就叫南方不懂北方的冷。","pinyin":"Shì a, zhè jiù jiào nánfāng bù dǒng běifāng de lěng."},{"speaker":"王一雪","cn":"就是呢，冬天北方和南方的温度差别还是很大的。","pinyin":"Jiùshì ne, dōngtiān běifāng hé nánfāng de wēndù chābié háishi hěn dà de."},{"speaker":"刘明","cn":"所以冬天来北方，尤其是东北，一定要提前查好目的地的天气，看看下不下雪，气温怎么样。","pinyin":"Suǒyǐ dōngtiān lái běifāng, yóuqí shì Dōngběi, yídìng yào tíqián cháhǎo mùdìdì de tiānqì, kànkan xià bú xiàxuě, qìwēn zěnmeyàng."},{"speaker":"王一雪","cn":"对。更重要的是，说什么也得穿上厚一点儿的衣服。","pinyin":"Duì. Gèng zhòngyào de shì, shuō shénme yě děi chuānshang hòu yìdiǎnr de yīfu."}],"translation_vn":"Lưu Minh: Em xem này, anh chàng này từ Quảng Châu đi công tác đến Cáp Nhĩ Tân, không ngờ nhiệt độ ở Cáp Nhĩ Tân hạ xuống âm hai mươi mấy độ, khiến anh ta lạnh cóng luôn.\nVương Nhất Tuyết: Chắc anh ta hối hận vì mặc ít đồ quá nhỉ?\nLưu Minh: Đúng vậy, đây gọi là người miền Nam không hiểu được cái lạnh của miền Bắc.\nVương Nhất Tuyết: Đúng thế, mùa đông sự chênh lệch nhiệt độ giữa miền Bắc và miền Nam vẫn rất lớn.\nLưu Minh: Vì vậy mùa đông đến miền Bắc, đặc biệt là vùng Đông Bắc, nhất định phải tra trước thời tiết nơi đến, xem có tuyết không, nhiệt độ thế nào.\nVương Nhất Tuyết: Đúng vậy. Quan trọng hơn là, dù thế nào cũng phải mặc quần áo dày một chút.","audio_dialogue":"10-1.mp3","audio_vocab":"10-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一飞","cn":"寒假你们打算做什么呢？","pinyin":"Hánjià nǐmen dǎsuàn zuò shénme ne?"},{"speaker":"陈天中","cn":"我们刚刚还说呢，家月春节时要去广州，我计划去哈尔滨。","pinyin":"Wǒmen gānggāng hái shuō ne, Jiāyuè Chūnjié shí yào qù Guǎngzhōu, wǒ jìhuà qù Hā'ěrbīn."},{"speaker":"王一飞","cn":"那时候广州暖和，但哈尔滨特别冷，气温一般都低于零下十摄氏度甚至零下二十摄氏度，这么低的温度你受不了吧？","pinyin":"Nà shíhou Guǎngzhōu nuǎnhuo, dàn Hā'ěrbīn tèbié lěng, qìwēn yìbān dōu dīyú língxià shí shèshìdù shènzhì língxià èrshí shèshìdù, zhème dī de wēndù nǐ shòubuliǎo ba?"},{"speaker":"陈天中","cn":"没问题，受得了，我有的是厚衣服。我去哈尔滨主要是想看雪，听说春节时那里会举办很多活动。","pinyin":"Méi wèntí, shòudeliǎo, wǒ yǒudeshì hòu yīfu. Wǒ qù Hā'ěrbīn zhǔyào shì xiǎng kàn xuě, tīngshuō Chūnjié shí nàlǐ huì jǔbàn hěn duō huódòng."},{"speaker":"白家月","cn":"我想在广州过年，那里冬天比较暖和。而且我喜欢看花，听说广州的鲜花市场很有名，里面有各种植物。","pinyin":"Wǒ xiǎng zài Guǎngzhōu guònián, nàlǐ dōngtiān bǐjiào nuǎnhuo. Érqiě wǒ xǐhuan kàn huā, tīngshuō Guǎngzhōu de xiānhuā shìchǎng hěn yǒumíng, lǐmiàn yǒu gèzhǒng zhíwù."},{"speaker":"王一飞","cn":"真不错！听你们这么一说，我也想外出旅游了。","pinyin":"Zhēn búcuò! Tīng nǐmen zhème yì shuō, wǒ yě xiǎng wàichū lǚyóu le."}],"translation_vn":"Vương Nhất Phi: Kỳ nghỉ đông các bạn định làm gì vậy?\nTrần Thiên Trung: Bọn mình vừa mới nói đấy, Gia Nguyệt Tết sẽ đi Quảng Châu, mình thì định đi Cáp Nhĩ Tân.\nVương Nhất Phi: Lúc đó Quảng Châu ấm áp, nhưng Cáp Nhĩ Tân lại rất lạnh, nhiệt độ thường thấp hơn âm mười độ C thậm chí âm hai mươi độ C, nhiệt độ thấp như vậy cậu chịu được không?\nTrần Thiên Trung: Không vấn đề gì, chịu được, mình có thừa quần áo dày mà. Mình đi Cáp Nhĩ Tân chủ yếu là muốn xem tuyết, nghe nói Tết ở đó sẽ tổ chức rất nhiều hoạt động.\nBạch Gia Nguyệt: Mình muốn đón Tết ở Quảng Châu, mùa đông ở đó khá ấm áp. Hơn nữa mình thích ngắm hoa, nghe nói chợ hoa tươi ở Quảng Châu rất nổi tiếng, trong đó có đủ loại thực vật.\nVương Nhất Phi: Hay thật đấy! Nghe các bạn nói vậy, mình cũng muốn đi du lịch rồi.","audio_dialogue":"10-3.mp3","audio_vocab":"10-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"广州和哈尔滨，一个在南方，一个在北方，两个城市之间的距离有三千多公里，气候也大不相同。广州基本上没有冬天，而哈尔滨的冬天一般会从十月开始，到第二年的三四月才结束。广州四季开满鲜花，所以又叫\"花城\"；哈尔滨冬天冰雪多，所以也叫\"冰城\"。此外，两地的方言也不一样。哈尔滨方言和普通话听起来比较像，而广州方言和普通话差别较大。如果广州人和哈尔滨人都只使用自己的方言，那么交流就很困难，甚至还可能引起误会。其实，中国很多地方都有自己的方言，所以，为了顺利交流，中国人从小都要学习普通话。","pinyin":"Guǎngzhōu hé Hā'ěrbīn, yígè zài nánfāng, yígè zài běifāng, liǎng ge chéngshì zhījiān de jùlí yǒu sānqiān duō gōnglǐ, qìhòu yě dàbùxiāngtóng. Guǎngzhōu jīběnshàng méiyǒu dōngtiān, ér Hā'ěrbīn de dōngtiān yìbān huì cóng shíyuè kāishǐ, dào dì èr nián de sānsìyuè cái jiéshù. Guǎngzhōu sìjì kāimǎn xiānhuā, suǒyǐ yòu jiào \"Huāchéng\"; Hā'ěrbīn dōngtiān bīngxuě duō, suǒyǐ yě jiào \"Bīngchéng\". Cǐwài, liǎng dì de fāngyán yě bù yíyàng. Hā'ěrbīn fāngyán hé pǔtōnghuà tīng qǐlái bǐjiào xiàng, ér Guǎngzhōu fāngyán hé pǔtōnghuà chābié jiào dà. Rúguǒ Guǎngzhōurén hé Hā'ěrbīnrén dōu zhǐ shǐyòng zìjǐ de fāngyán, nàme jiāoliú jiù hěn kùnnan, shènzhì hái kěnéng yǐnqǐ wùhuì. Qíshí, Zhōngguó hěn duō dìfang dōu yǒu zìjǐ de fāngyán, suǒyǐ, wèile shùnlì jiāoliú, Zhōngguórén cóngxiǎo dōu yào xuéxí pǔtōnghuà."}],"translation_vn":"Quảng Châu và Cáp Nhĩ Tân, một ở miền Nam, một ở miền Bắc, khoảng cách giữa hai thành phố hơn ba nghìn ki-lô-mét, khí hậu cũng rất khác nhau. Quảng Châu hầu như không có mùa đông, còn mùa đông ở Cáp Nhĩ Tân thường bắt đầu từ tháng Mười, đến tận tháng Ba tháng Tư năm sau mới kết thúc. Quảng Châu bốn mùa hoa nở rộ, nên còn được gọi là \"thành phố hoa\"; mùa đông ở Cáp Nhĩ Tân nhiều băng tuyết, nên cũng được gọi là \"thành phố băng\". Ngoài ra, phương ngữ của hai nơi cũng không giống nhau. Phương ngữ Cáp Nhĩ Tân nghe khá giống tiếng phổ thông, còn phương ngữ Quảng Châu lại khác biệt khá lớn so với tiếng phổ thông. Nếu người Quảng Châu và người Cáp Nhĩ Tân đều chỉ dùng phương ngữ của mình, thì việc giao tiếp sẽ rất khó khăn, thậm chí còn có thể gây hiểu lầm. Thực ra, rất nhiều nơi ở Trung Quốc đều có phương ngữ riêng, vì vậy, để giao tiếp thuận lợi, người Trung Quốc từ nhỏ đều phải học tiếng phổ thông.","audio_dialogue":"10-5.mp3","audio_vocab":"10-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"亲爱的同学们：今年的\"世界环境日\"，我们再次开展\"绿色生活\"活动，希望同学们做到：一、绿色出行。绿色一小步，环保一大步。根据距离选择绿色交通方式。距离短时可以走路或者骑自行车，距离长时多乘坐公交车或者地铁。二、拒绝浪费。节约资源，坚持一水多用、人走灯关、餐餐都\"光盘\"。三、垃圾分类。积极参加校园、小区环保活动，学习垃圾分类知识，从小事做起，做好垃圾分类。保护环境是每一个人的责任。同学们，让我们共同努力，让绿色生活成为我们的日常习惯！校学生会 2026年6月5日","pinyin":"Qīn'ài de tóngxuémen: Jīnnián de \"Shìjiè Huánjìng Rì\", wǒmen zàicì kāizhǎn \"Lǜsè Shēnghuó\" huódòng, xīwàng tóngxuémen zuòdào: Yī, lǜsè chūxíng. Lǜsè yì xiǎo bù, huánbǎo yí dà bù. Gēnjù jùlí xuǎnzé lǜsè jiāotōng fāngshì. Jùlí duǎn shí kěyǐ zǒulù huòzhě qí zìxíngchē, jùlí cháng shí duō chéngzuò gōngjiāochē huòzhě dìtiě. Èr, jùjué làngfèi. Jiéyuē zīyuán, jiānchí yì shuǐ duō yòng, rén zǒu dēng guān, cāncān dōu \"guāngpán\". Sān, lājī fēnlèi. Jījí cānjiā xiàoyuán, xiǎoqū huánbǎo huódòng, xuéxí lājī fēnlèi zhīshi, cóng xiǎoshì zuòqǐ, zuòhǎo lājī fēnlèi. Bǎohù huánjìng shì měi yígè rén de zérèn. Tóngxuémen, ràng wǒmen gòngtóng nǔlì, ràng lǜsè shēnghuó chéngwéi wǒmen de rìcháng xíguàn! Xiào Xuéshēnghuì èr líng èr liù nián liù yuè wǔ rì"}],"translation_vn":"Các bạn học sinh thân mến: Nhân \"Ngày Môi trường Thế giới\" năm nay, chúng ta lại tiếp tục triển khai hoạt động \"Sống xanh\", hy vọng các bạn làm được những điều sau: Một, Di chuyển xanh. Một bước nhỏ xanh, một bước lớn bảo vệ môi trường. Hãy chọn phương thức di chuyển xanh tùy theo khoảng cách. Khi khoảng cách gần có thể đi bộ hoặc đi xe đạp, khi khoảng cách xa nên đi xe buýt hoặc tàu điện ngầm nhiều hơn. Hai, Nói không với lãng phí. Tiết kiệm tài nguyên, kiên trì dùng nước nhiều lần, ra khỏi phòng tắt đèn, mỗi bữa ăn đều \"sạch đĩa\". Ba, Phân loại rác. Tích cực tham gia các hoạt động bảo vệ môi trường ở trường học, khu dân cư, học kiến thức phân loại rác, bắt đầu từ những việc nhỏ, làm tốt việc phân loại rác. Bảo vệ môi trường là trách nhiệm của mỗi người. Các bạn ơi, hãy cùng nhau nỗ lực, để lối sống xanh trở thành thói quen hàng ngày của chúng ta! Hội Học sinh Nhà trường, Ngày 5 tháng 6 năm 2026","audio_dialogue":"10-7.mp3","audio_vocab":"10-8.mp3"}]},{"id":11,"title_cn":"活到老学到老","title_pinyin":"Huó dào lǎo xué dào lǎo","title_vn":"Sống đến già, học đến già","goals":["Có thể nghe hiểu và trao đổi các chủ đề như giáo dục suốt đời, giảng dạy trực tuyến, học tập qua mạng,...","Có thể trình bày bằng lời hoặc bằng văn bản về ý nghĩa của giáo dục suốt đời và học tập qua mạng.","Hiểu được quan niệm về giáo dục của người Trung Quốc."],"vocab":[{"hanzi":"老年","pinyin":"lǎonián","pos":"dt.","vn":"tuổi già, người cao tuổi","examples":[{"cn":"很多老年人喜欢早上在公园锻炼身体。","pinyin":"Hěn duō lǎoniánrén xǐhuan zǎoshang zài gōngyuán duànliàn shēntǐ.","vn":"Rất nhiều người cao tuổi thích tập thể dục ở công viên vào buổi sáng."},{"cn":"社区为老年人举办了各种兴趣班。","pinyin":"Shèqū wèi lǎoniánrén jǔbàn le gèzhǒng xìngqùbān.","vn":"Khu dân cư đã tổ chức nhiều lớp năng khiếu cho người cao tuổi."},{"cn":"爷爷退休后，老年生活过得非常充实。","pinyin":"Yéye tuìxiū hòu, lǎonián shēnghuó guò de fēicháng chōngshí.","vn":"Sau khi nghỉ hưu, cuộc sống tuổi già của ông nội rất phong phú và trọn vẹn."}]},{"hanzi":"散步","pinyin":"sànbù","pos":"dgt.","vn":"đi dạo, tản bộ","examples":[{"cn":"晚饭后，我常和家人一起去河边散步。","pinyin":"Wǎnfàn hòu, wǒ cháng hé jiārén yìqǐ qù hébiān sànbù.","vn":"Sau bữa tối, tôi thường cùng gia đình ra bờ sông đi dạo."},{"cn":"今天天气真舒服，咱们出去散散步吧。","pinyin":"Jīntiān tiānqì zhēn shūfu, zánmen chūqù sànsanbù ba.","vn":"Thời tiết hôm nay dễ chịu quá, chúng ta ra ngoài tản bộ một chút đi."},{"cn":"每天坚持散步半小时对健康很有好处。","pinyin":"Měitiān jiānchí sànbù bàn xiǎoshí duì jiànkāng hěn yǒu hǎochù.","vn":"Mỗi ngày kiên trì đi bộ nửa tiếng rất có lợi cho sức khỏe."}]},{"hanzi":"丰富","pinyin":"fēngfù","pos":"tt.","vn":"phong phú","examples":[{"cn":"他的工作经验非常丰富，大家都很信任他。","pinyin":"Tā de gōngzuò jīngyàn fēicháng fēngfù, dàjiā dōu hěn xìnrèn tā.","vn":"Kinh nghiệm làm việc của anh ấy rất phong phú, mọi người đều rất tin tưởng anh ấy."},{"cn":"大学的课余生活特别丰富。","pinyin":"Dàxué de kèyú shēnghuó tèbié fēngfù.","vn":"Đời sống ngoại khóa ở đại học đặc biệt phong phú."},{"cn":"图书馆里的中文资料十分丰富。","pinyin":"Túshūguǎn lǐ de Zhōngwén zīliào shífēn fēngfù.","vn":"Tài liệu tiếng Trung trong thư viện vô cùng phong phú."}]},{"hanzi":"羡慕","pinyin":"xiànmù","pos":"dgt.","vn":"ngưỡng mộ, ghen tị","examples":[{"cn":"她能说四种外语，真是让人羡慕。","pinyin":"Tā néng shuō sì zhǒng wàiyǔ, zhēn shì ràng rén xiànmù.","vn":"Cô ấy có thể nói bốn ngoại ngữ, thật khiến người ta ngưỡng mộ."},{"cn":"我很羡慕你有一份既轻松又高薪的工作。","pinyin":"Wǒ hěn xiànmù nǐ yǒu yí fèn jì qīngsōng yòu gāoxīn de gōngzuò.","vn":"Tôi rất ngưỡng mộ bạn có một công việc vừa nhẹ nhàng vừa lương cao."},{"cn":"看到他们一家人这么幸福，大家都很羡慕。","pinyin":"Kàndào tāmen yìjiārén zhème xìngfú, dàjiā dōu hěn xiànmù.","vn":"Nhìn thấy cả nhà họ hạnh phúc như vậy, ai cũng đều ngưỡng mộ."}]},{"hanzi":"即使","pinyin":"jíshǐ","pos":"liên.","vn":"cho dù, dù cho","examples":[{"cn":"即使遇到再大的困难，我们也不能放弃。","pinyin":"Jíshǐ yùdào zài dà de kùnnan, wǒmen yě bù néng fàngqì.","vn":"Cho dù gặp khó khăn lớn đến đâu, chúng ta cũng không được bỏ cuộc."},{"cn":"即使外面刮风下雨，他还是每天坚持跑步。","pinyin":"Jíshǐ wàimiàn guāfēng xiàyǔ, tā háishi měitiān jiānchí pǎobù.","vn":"Cho dù bên ngoài mưa gió, anh ấy vẫn kiên trì chạy bộ mỗi ngày."},{"cn":"即使你不提醒我，我也记得今天是你的生日。","pinyin":"Jíshǐ nǐ bù tíxǐng wǒ, wǒ yě jìde jīntiān shì nǐ de shēngrì.","vn":"Cho dù bạn không nhắc tôi, tôi vẫn nhớ hôm nay là sinh nhật bạn."}]},{"hanzi":"活","pinyin":"huó","pos":"dgt./tt./dt.","vn":"sống; linh hoạt, sống động; công việc","examples":[{"cn":"人要活到老，学到老。","pinyin":"Rén yào huó dào lǎo, xué dào lǎo.","vn":"Con người phải sống đến già, học đến già."},{"cn":"他脑子很活，总能想到好办法。","pinyin":"Tā nǎozi hěn huó, zǒng néng xiǎngdào hǎo bànfǎ.","vn":"Đầu óc anh ấy rất linh hoạt, luôn nghĩ ra được cách hay."},{"cn":"家里的重活儿一般都是爸爸干。","pinyin":"Jiā lǐ de zhònghuór yìbān dōu shì bàba gàn.","vn":"Những việc nặng trong nhà thường đều do bố làm."}]},{"hanzi":"继续","pinyin":"jìxù","pos":"dgt.","vn":"tiếp tục","examples":[{"cn":"休息十分钟后，我们继续上课。","pinyin":"Xiūxi shí fēnzhōng hòu, wǒmen jìxù shàngkè.","vn":"Nghỉ giải lao mười phút xong, chúng ta tiếp tục học."},{"cn":"本科毕业后，她打算继续读研究生。","pinyin":"Běnkē bìyè hòu, tā dǎsuàn jìxù dú yánjiūshēng.","vn":"Sau khi tốt nghiệp đại học, cô ấy định tiếp tục học cao học."},{"cn":"雨停了，比赛可以继续进行了。","pinyin":"Yǔ tíng le, bǐsài kěyǐ jìxù jìnxíng le.","vn":"Mưa tạnh rồi, trận đấu có thể tiếp tục diễn ra."}]},{"hanzi":"网友","pinyin":"wǎngyǒu","pos":"dt.","vn":"bạn trên mạng, cư dân mạng","examples":[{"cn":"这条新闻在网上引起了很多网友的讨论。","pinyin":"Zhè tiáo xīnwén zài wǎngshang yǐnqǐ le hěn duō wǎngyǒu de tǎolùn.","vn":"Tin tức này đã thu hút sự thảo luận của rất nhiều cư dân mạng."},{"cn":"我认识了一位喜欢摄影的网友，我们常交流经验。","pinyin":"Wǒ rènshi le yí wèi xǐhuan shèyǐng de wǎngyǒu, wǒmen cháng jiāoliú jīngyàn.","vn":"Tôi quen một người bạn trên mạng thích nhiếp ảnh, chúng tôi thường xuyên trao đổi kinh nghiệm."},{"cn":"热心的网友们很快帮她找到了资料。","pinyin":"Rèxīn de wǎngyǒumen hěn kuài bāng tā zhǎodào le zīliào.","vn":"Các cư dân mạng nhiệt tình nhanh chóng giúp cô ấy tìm thấy tài liệu."}]},{"hanzi":"无聊","pinyin":"wúliáo","pos":"tt.","vn":"nhàm chán, buồn chán","examples":[{"cn":"一个人待在家里太无聊了，我们去看电影吧。","pinyin":"Yí ge rén dāi zài jiā lǐ tài wúliáo le, wǒmen qù kàn diànyǐng ba.","vn":"Ở nhà một mình chán quá, chúng ta đi xem phim đi."},{"cn":"我觉得那本书写得有点儿无聊，没看完。","pinyin":"Wǒ juéde nà běn shū xiě de yǒudiǎnr wúliáo, méi kànwán.","vn":"Tôi thấy cuốn sách đó viết hơi nhàm chán nên chưa đọc hết."},{"cn":"只要有书看，我就一点儿也不觉得无聊。","pinyin":"Zhǐyào yǒu shū kàn, wǒ jiù yìdiǎnr yě bù juéde wúliáo.","vn":"Chỉ cần có sách để đọc là tôi không thấy chán chút nào."}]},{"hanzi":"太极拳","pinyin":"Tàijíquán","pos":"danh từ riêng","vn":"Thái cực quyền","examples":[{"cn":"爷爷每天早上都会去公园打太极拳。","pinyin":"Yéye měitiān zǎoshang dōu huì qù gōngyuán dǎ Tàijíquán.","vn":"Ông nội mỗi sáng đều ra công viên tập Thái cực quyền."},{"cn":"练习太极拳不仅能强身健体，还能让人放松心情。","pinyin":"Liànxí Tàijíquán bùjǐn néng qiángshēn jiàntǐ, hái néng ràng rén fàngsōng xīnqíng.","vn":"Tập Thái cực quyền không chỉ rèn luyện sức khỏe mà còn giúp tinh thần thư giãn."},{"cn":"越来越多的外国人对中国的太极拳感兴趣。","pinyin":"Yuè lái yuè duō de wàiguórén duì Zhōngguó de Tàijíquán gǎn xìngqù.","vn":"Ngày càng có nhiều người nước ngoài hứng thú với Thái cực quyền của Trung Quốc."}]},{"hanzi":"数字","pinyin":"shùzì","pos":"tt./dt.","vn":"kỹ thuật số, số hóa; con số","examples":[{"cn":"我们学校建了很多现代化的数字教室。","pinyin":"Wǒmen xuéxiào jiàn le hěn duō xiàndàihuà de shùzì jiàoshì.","vn":"Trường chúng tôi đã xây dựng nhiều phòng học số hiện đại."},{"cn":"在中国文化中，数字“八”代表好运和发财。","pinyin":"Zài Zhōngguó wénhuà zhōng, shùzì \"bā\" dàibiǎo hǎoyùn hé fācái.","vn":"Trong văn hóa Trung Quốc, con số 8 tượng trưng cho may mắn và phát tài."},{"cn":"请把这个表格里的数字再核对一遍。","pinyin":"Qǐng bǎ zhège biǎogé lǐ de shùzì zài héduì yí biàn.","vn":"Xin hãy kiểm tra lại các con số trong bảng biểu này một lần nữa."}]},{"hanzi":"点名","pinyin":"diǎnmíng","pos":"dgt.","vn":"điểm danh","examples":[{"cn":"每节课开始前，老师都会先点名。","pinyin":"Měi jié kè kāishǐ qián, lǎoshī dōu huì xiān diǎnmíng.","vn":"Trước khi mỗi tiết học bắt đầu, thầy giáo đều điểm danh trước."},{"cn":"现在用手机扫码就能点名，非常方便。","pinyin":"Xiànzài yòng shǒujī sǎomǎ jiù néng diǎnmíng, fēicháng fāngbiàn.","vn":"Bây giờ dùng điện thoại quét mã là điểm danh được, vô cùng tiện lợi."},{"cn":"他今天迟到了，差点儿错过老师点名。","pinyin":"Tā jīntiān chídào le, chàdiǎnr cuòguò lǎoshī diǎnmíng.","vn":"Hôm nay cậu ấy đi muộn, suýt nữa thì lỡ lúc thầy điểm danh."}]},{"hanzi":"教授","pinyin":"jiàoshòu","pos":"dt.","vn":"giáo sư","examples":[{"cn":"明天下午有一位著名的教授来学校做讲座。","pinyin":"Míngtiān xiàwǔ yǒu yí wèi zhùmíng de jiàoshòu lái xuéxiào zuò jiǎngzuò.","vn":"Chiều mai có một vị giáo sư nổi tiếng đến trường diễn thuyết."},{"cn":"王教授讲课非常生动，学生们都很喜欢听。","pinyin":"Wáng jiàoshòu jiǎngkè fēicháng shēngdòng, xuéshengmen dōu hěn xǐhuan tīng.","vn":"Giáo sư Vương giảng bài rất sinh động, sinh viên ai cũng thích nghe."},{"cn":"我给教授发了一封电子邮件，请教一个问题。","pinyin":"Wǒ gěi jiàoshòu fā le yì fēng diànzǐ yóujiàn, qǐngjiào yí ge wèntí.","vn":"Tôi đã gửi một bức thư điện tử cho giáo sư để xin hỏi một vấn đề."}]},{"hanzi":"线上","pinyin":"xiànshàng","pos":"dt.","vn":"trực tuyến, online","examples":[{"cn":"我现在每周都会上两次线上中文课。","pinyin":"Wǒ xiànzài měizhōu dōu huì shàng liǎng cì xiànshàng Zhōngwén kè.","vn":"Hiện nay mỗi tuần tôi đều học hai buổi tiếng Trung trực tuyến."},{"cn":"由于大家不在同一个城市，这次会议改为线上举行。","pinyin":"Yóuyú dàjiā bú zài tóng yí ge chéngshì, zhè cì huìyì gǎiwéi xiànshàng jǔxíng.","vn":"Vì mọi người không ở cùng một thành phố nên cuộc họp lần này chuyển sang tổ chức trực tuyến."},{"cn":"线上购物节省了大家不少时间和精力。","pinyin":"Xiànshàng gòuwù jiéshěng le dàjiā bùshǎo shíjiān hé jīnglì.","vn":"Mua sắm trực tuyến đã tiết kiệm cho mọi người không ít thời gian và công sức."}]},{"hanzi":"线下","pinyin":"xiànxià","pos":"dt.","vn":"trực tiếp (ngoại tuyến), offline","examples":[{"cn":"虽然线上学习很方便，但我还是更喜欢线下上课。","pinyin":"Suīrán xiànshàng xuéxí hěn fāngbiàn, dàn wǒ háishi gèng xǐhuan xiànxià shàngkè.","vn":"Tuy học trực tuyến rất tiện lợi, nhưng tôi vẫn thích học trực tiếp trên lớp hơn."},{"cn":"这家商店结合了线上销售和线下体验。","pinyin":"Zhè jiā shāngdiàn jiéhé le xiànshàng xiāoshòu hé xiànxià tǐyàn.","vn":"Cửa hàng này kết hợp giữa bán hàng trực tuyến và trải nghiệm trực tiếp."},{"cn":"这个周末我们打算组织一次线下聚会。","pinyin":"Zhège zhōumò wǒmen dǎsuàn zǔzhī yí cì xiànxià jùhuì.","vn":"Cuối tuần này chúng tôi dự định tổ chức một buổi gặp mặt trực tiếp."}]},{"hanzi":"视频","pinyin":"shìpín","pos":"dt.","vn":"video","examples":[{"cn":"我每天晚上都会和远方的父母打视频电话。","pinyin":"Wǒ měitiān wǎnshang dōu huì hé yuǎnfāng de fùmǔ dǎ shìpín diànhuà.","vn":"Tối nào tôi cũng gọi điện video cho bố mẹ ở phương xa."},{"cn":"她在网上分享了一个教大家做中国菜的视频。","pinyin":"Tā zài wǎngshang fēnxiǎng le yí ge jiāo dàjiā zuò Zhōngguócài de shìpín.","vn":"Cô ấy đã chia sẻ trên mạng một video dạy mọi người nấu món Trung Quốc."},{"cn":"课后可以看教学视频来复习重点内容。","pinyin":"Kèhòu kěyǐ kàn jiàoxué shìpín lái fùxí zhòngdiǎn nèiróng.","vn":"Sau giờ học có thể xem video bài giảng để ôn tập nội dung trọng tâm."}]},{"hanzi":"记录","pinyin":"jìlù","pos":"dt.","vn":"bản ghi chép, ghi lại","examples":[{"cn":"开会时，小王负责做详细的会议记录。","pinyin":"Kāihuì shí, Xiǎo Wáng fùzé zuò xiángxì de huìyì jìlù.","vn":"Khi họp, Tiểu Vương phụ trách làm biên bản cuộc họp chi tiết."},{"cn":"你可以在手机上查看最近的消费记录。","pinyin":"Nǐ kěyǐ zài shǒujī shang chákàn zuìjìn de xiāofèi jìlù.","vn":"Bạn có thể kiểm tra lịch sử chi tiêu gần đây trên điện thoại."},{"cn":"这本日记里有我大学四年的成长记录。","pinyin":"Zhè běn rìjì lǐ yǒu wǒ dàxué sì nián de chéngzhǎng jìlù.","vn":"Trong cuốn nhật ký này có ghi chép quá trình trưởng thành bốn năm đại học của tôi."}]},{"hanzi":"资料","pinyin":"zīliào","pos":"dt.","vn":"tư liệu, tài liệu","examples":[{"cn":"写论文之前，我们需要先查很多资料。","pinyin":"Xiě lùnwén zhīqián, wǒmen xūyào xiān chá hěn duō zīliào.","vn":"Trước khi viết luận văn, chúng ta cần tra cứu rất nhiều tài liệu."},{"cn":"请你把这份学习资料发到班级群里。","pinyin":"Qǐng nǐ bǎ zhè fèn xuéxí zīliào fā dào bānjí qún lǐ.","vn":"Bạn hãy gửi tài liệu học tập này vào nhóm lớp nhé."},{"cn":"网上有很多免费的中文听力资料。","pinyin":"Wǎngshang yǒu hěn duō miǎnfèi de Zhōngwén tīnglì zīliào.","vn":"Trên mạng có rất nhiều tài liệu luyện nghe tiếng Trung miễn phí."}]},{"hanzi":"自学","pinyin":"zìxué","pos":"dgt.","vn":"tự học","examples":[{"cn":"她没有报班，完全是靠自己自学通过考试的。","pinyin":"Tā méiyǒu bàobān, wánquán shì kào zìjǐ zìxué tōngguò kǎoshì de.","vn":"Cô ấy không đăng ký lớp học, hoàn toàn tự học mà đỗ kỳ thi."},{"cn":"现在网络资源丰富，自学一门新技能变得容易多了。","pinyin":"Xiànzài wǎngluò zīyuán fēngfù, zìxué yì mén xīn jìnéng biàn de róngyì duō le.","vn":"Hiện nay tài nguyên mạng phong phú, việc tự học một kỹ năng mới trở nên dễ dàng hơn nhiều."},{"cn":"自学最重要的是制定合理的计划并坚持下去。","pinyin":"Zìxué zuì zhòngyào de shì zhìdìng hélǐ de jìhuà bìng jiānchí xiàqù.","vn":"Điều quan trọng nhất khi tự học là lập kế hoạch hợp lý và kiên trì thực hiện."}]},{"hanzi":"口语","pinyin":"kǒuyǔ","pos":"dt.","vn":"khẩu ngữ, tiếng nói","examples":[{"cn":"想提高中文口语，就要多听、多说。","pinyin":"Xiǎng tígāo Zhōngwén kǒuyǔ, jiù yào duō tīng, duō shuō.","vn":"Muốn nâng cao khẩu ngữ tiếng Trung thì phải nghe nhiều, nói nhiều."},{"cn":"虽然她的汉字写得不多，但口语非常流利。","pinyin":"Suīrán tā de Hànzì xiě de bù duō, dàn kǒuyǔ fēicháng liúlì.","vn":"Tuy cô ấy viết chữ Hán chưa nhiều, nhưng nói chuyện rất lưu loát."},{"cn":"这个表达在日常口语中经常用到。","pinyin":"Zhège biǎodá zài rìcháng kǒuyǔ zhōng jīngcháng yòngdào.","vn":"Cách diễn đạt này thường xuyên được dùng trong khẩu ngữ hằng ngày."}]},{"hanzi":"科技","pinyin":"kējì","pos":"dt.","vn":"khoa học kỹ thuật, công nghệ","examples":[{"cn":"现代科技让人们的生活越来越方便。","pinyin":"Xiàndài kējì ràng rénmen de shēnghuó yuè lái yuè fāngbiàn.","vn":"Công nghệ hiện đại giúp cuộc sống con người ngày càng tiện lợi."},{"cn":"他在一家高科技公司做软件开发。","pinyin":"Tā zài yì jiā gāokējì gōngsī zuò ruǎnjiàn kāifā.","vn":"Anh ấy làm phát triển phần mềm tại một công ty công nghệ cao."},{"cn":"周末我打算带孩子去参观科技馆。","pinyin":"Zhōumò wǒ dǎsuàn dài háizi qù cānguān kējìguǎn.","vn":"Cuối tuần tôi dự định đưa con đi tham quan bảo tàng khoa học công nghệ."}]},{"hanzi":"获取","pinyin":"huòqǔ","pos":"dgt.","vn":"thu được, tiếp thu, giành được","examples":[{"cn":"互联网为我们获取信息提供了极大便利。","pinyin":"Hùliánwǎng wèi wǒmen huòqǔ xìnxī tígōng le jídà biànlì.","vn":"Internet mang lại sự tiện lợi to lớn cho chúng ta trong việc tiếp cận thông tin."},{"cn":"读书是获取知识最重要的方式之一。","pinyin":"Dúshū shì huòqǔ zhīshi zuì zhòngyào de fāngshì zhī yī.","vn":"Đọc sách là một trong những cách quan trọng nhất để tiếp thu kiến thức."},{"cn":"通过这次实习，他获取了宝贵的实践经验。","pinyin":"Tōngguò zhè cì shíxí, tā huòqǔ le bǎoguì de shíjiàn jīngyàn.","vn":"Thông qua đợt thực tập lần này, cậu ấy đã tích lũy được kinh nghiệm thực tiễn quý báu."}]},{"hanzi":"礼貌","pinyin":"lǐmào","pos":"dt./tt.","vn":"lễ phép, lịch sự","examples":[{"cn":"这个孩子见了长辈总是主动问好，非常有礼貌。","pinyin":"Zhège háizi jiàn le zhǎngbèi zǒngshì zhǔdòng wènhǎo, fēicháng yǒu lǐmào.","vn":"Đứa trẻ này gặp người lớn luôn chủ động chào hỏi, rất lễ phép."},{"cn":"别人说话时随便打断是不礼貌的。","pinyin":"Biéren shuōhuà shí suíbiàn dǎduàn shì bù lǐmào de.","vn":"Tùy tiện ngắt lời khi người khác đang nói là bất lịch sự."},{"cn":"我们应该对每一位客人都礼貌微笑。","pinyin":"Wǒmen yīnggāi duì měi yí wèi kèrén dōu lǐmào wēixiào.","vn":"Chúng ta nên mỉm cười lịch sự với mỗi vị khách."}]},{"hanzi":"打招呼","pinyin":"dǎ zhāohu","pos":"","vn":"chào hỏi","examples":[{"cn":"早上在小区里遇到邻居，我会笑着和他们打招呼。","pinyin":"Zǎoshang zài xiǎoqū lǐ yùdào línjū, wǒ huì xiàozhe hé tāmen dǎ zhāohu.","vn":"Buổi sáng gặp hàng xóm trong khu dân cư, tôi đều mỉm cười chào hỏi họ."},{"cn":"他走得太急了，连招呼都没打就离开了。","pinyin":"Tā zǒu de tài jí le, lián zhāohu dōu méi dǎ jiù líkāi le.","vn":"Anh ấy đi vội quá, thậm chí chẳng kịp chào một tiếng đã rời đi."},{"cn":"你去之前最好先跟他打个招呼。","pinyin":"Nǐ qù zhīqián zuìhǎo xiān gēn tā dǎ ge zhāohu.","vn":"Trước khi đến tốt nhất bạn nên báo trước với anh ấy một tiếng."}]},{"hanzi":"家长","pinyin":"jiāzhǎng","pos":"dt.","vn":"phụ huynh","examples":[{"cn":"学校本周五下午要开家长会。","pinyin":"Xuéxiào běn zhōuwǔ xiàwǔ yào kāi jiāzhǎnghuì.","vn":"Chiều thứ Sáu tuần này trường sẽ tổ chức họp phụ huynh."},{"cn":"家长应该多倾听孩子的想法，不要只看成绩。","pinyin":"Jiāzhǎng yīnggāi duō qīngtīng háizi de xiǎngfǎ, búyào zhǐ kàn chéngjì.","vn":"Phụ huynh nên lắng nghe suy nghĩ của con nhiều hơn, đừng chỉ nhìn vào thành tích."},{"cn":"放学时间到了，很多家长在校门口等孩子。","pinyin":"Fàngxué shíjiān dào le, hěn duō jiāzhǎng zài xiàoménkǒu děng háizi.","vn":"Đến giờ tan học rồi, rất nhiều phụ huynh đang đợi con ở cổng trường."}]},{"hanzi":"成功","pinyin":"chénggōng","pos":"tt./dgt.","vn":"thành công","examples":[{"cn":"经过多年的努力，他的创业终于成功了。","pinyin":"Jīngguò duō nián de nǔlì, tā de chuàngyè zhōngyú chénggōng le.","vn":"Sau nhiều năm nỗ lực, việc khởi nghiệp của anh ấy cuối cùng đã thành công."},{"cn":"这次文化交流活动办得非常成功。","pinyin":"Zhè cì wénhuà jiāoliú huódòng bàn de fēicháng chénggōng.","vn":"Hoạt động giao lưu văn hóa lần này được tổ chức rất thành công."},{"cn":"每个人对成功的定义都不太一样。","pinyin":"Měi ge rén duì chénggōng de dìngyì dōu bú tài yíyàng.","vn":"Định nghĩa về thành công của mỗi người đều không hoàn toàn giống nhau."}]},{"hanzi":"分数","pinyin":"fēnshù","pos":"dt.","vn":"điểm số","examples":[{"cn":"这次数学考试他的分数比上次提高了不少。","pinyin":"Zhè cì shùxué kǎoshì tā de fēnshù bǐ shàng cì tígāo le bùshǎo.","vn":"Điểm số bài thi toán lần này của cậu ấy cao hơn lần trước khá nhiều."},{"cn":"分数固然重要，但学习能力更加关键。","pinyin":"Fēnshù gùrán zhòngyào, dàn xuéxí nénglì gèngjiā guānjiàn.","vn":"Điểm số tuy quan trọng, nhưng năng lực học tập còn then chốt hơn."},{"cn":"期末考试的分数下周一才会公布。","pinyin":"Qīmò kǎoshì de fēnshù xià zhōuyī cái huì gōngbù.","vn":"Điểm thi cuối kỳ thứ Hai tuần sau mới được công bố."}]},{"hanzi":"目的","pinyin":"mùdì","pos":"dt.","vn":"mục đích","examples":[{"cn":"我来中国留学的目的是深入学习汉语和中国文化。","pinyin":"Wǒ lái Zhōngguó liúxué de mùdì shì shēnrù xuéxí Hànyǔ hé Zhōngguó wénhuà.","vn":"Mục đích tôi đến Trung Quốc du học là để học sâu về tiếng Hán và văn hóa Trung Quốc."},{"cn":"我们举办这次比赛的目的是鼓励大家多锻炼身体。","pinyin":"Wǒmen jǔbàn zhè cì bǐsài de mùdì shì gǔlì dàjiā duō duànliàn shēntǐ.","vn":"Mục đích chúng tôi tổ chức cuộc thi lần này là để khuyến khích mọi người tập thể dục nhiều hơn."},{"cn":"不管做什么事，都要先明确自己的目的。","pinyin":"Bùguǎn zuò shénme shì, dōu yào xiān míngquè zìjǐ de mùdì.","vn":"Bất kể làm việc gì cũng phải xác định rõ mục đích của mình trước."}]},{"hanzi":"养成","pinyin":"yǎngchéng","pos":"dgt.","vn":"hình thành, rèn luyện (thói quen)","examples":[{"cn":"我们要从小养成早睡早起的好习惯。","pinyin":"Wǒmen yào cóngxiǎo yǎngchéng zǎoshuì zǎoqǐ de hǎo xíguàn.","vn":"Chúng ta cần rèn luyện thói quen tốt ngủ sớm dậy sớm từ nhỏ."},{"cn":"他养成了每天睡前看半小时书的习惯。","pinyin":"Tā yǎngchéng le měitiān shuìqián kàn bàn xiǎoshí shū de xíguàn.","vn":"Anh ấy đã hình thành thói quen đọc sách nửa tiếng mỗi tối trước khi ngủ."},{"cn":"养成一个好习惯通常需要很长时间的坚持。","pinyin":"Yǎngchéng yí ge hǎo xíguàn tōngcháng xūyào hěn cháng shíjiān de jiānchí.","vn":"Hình thành một thói quen tốt thường cần sự kiên trì trong thời gian dài."}]},{"hanzi":"留","pinyin":"liú","pos":"dgt.","vn":"để dành, lưu lại, ở lại","examples":[{"cn":"不管工作多忙，我都会留出时间陪家人。","pinyin":"Bùguǎn gōngzuò duō máng, wǒ dōu huì liúchū shíjiān péi jiārén.","vn":"Dù công việc bận rộn đến đâu, tôi vẫn sẽ dành thời gian ở bên gia đình."},{"cn":"请你把联系方式留给我，有消息我立刻通知你。","pinyin":"Qǐng nǐ bǎ liánxì fāngshì liú gěi wǒ, yǒu xiāoxi wǒ lìkè tōngzhī nǐ.","vn":"Xin bạn để lại thông tin liên lạc cho tôi, có tin gì tôi sẽ báo bạn ngay."},{"cn":"这次旅行给我留下了非常美好的印象。","pinyin":"Zhè cì lǚxíng gěi wǒ liúxià le fēicháng měihǎo de yìnxiàng.","vn":"Chuyến du lịch lần này đã để lại cho tôi ấn tượng vô cùng tốt đẹp."}]},{"hanzi":"做法","pinyin":"zuòfǎ","pos":"dt.","vn":"cách làm","examples":[{"cn":"我觉得他的这种做法非常明智。","pinyin":"Wǒ juéde tā de zhè zhǒng zuòfǎ fēicháng míngzhì.","vn":"Tôi thấy cách làm này của anh ấy rất sáng suốt."},{"cn":"这道菜的做法其实很简单，你学一次就会了。","pinyin":"Zhè dào cài de zuòfǎ qíshí hěn jiǎndān, nǐ xué yí cì jiù huì le.","vn":"Cách làm món ăn này thực ra rất đơn giản, bạn học một lần là biết ngay."},{"cn":"大家对这件事有不同的看法和做法。","pinyin":"Dàjiā duì zhè jiàn shì yǒu bùtóng de kànfǎ hé zuòfǎ.","vn":"Mọi người có cách nhìn và cách làm khác nhau đối với việc này."}]},{"hanzi":"棒","pinyin":"bàng","pos":"tt.","vn":"tuyệt vời, giỏi, cừ","examples":[{"cn":"你的中文说得越来越棒了！","pinyin":"Nǐ de Zhōngwén shuō de yuè lái yuè bàng le!","vn":"Tiếng Trung của bạn nói ngày càng giỏi rồi!"},{"cn":"这个主意真棒，我们马上就开始准备吧。","pinyin":"Zhège zhǔyi zhēn bàng, wǒmen mǎshàng jiù kāishǐ zhǔnbèi ba.","vn":"Ý tưởng này thật tuyệt vời, chúng ta bắt đầu chuẩn bị ngay thôi."},{"cn":"昨晚的音乐会精彩极了，演员们表现得太棒了。","pinyin":"Zuówǎn de yīnyuèhuì jīngcǎi jíle, yǎnyuánmen biǎoxiàn de tài bàng le.","vn":"Buổi hòa nhạc tối qua vô cùng đặc sắc, các nghệ sĩ biểu diễn quá tuyệt vời."}]},{"hanzi":"一生","pinyin":"yìshēng","pos":"dt.","vn":"cả đời, suốt đời","examples":[{"cn":"学习不是一时的事，而是人一生的事情。","pinyin":"Xuéxí bú shì yìshí de shì, érshì rén yìshēng de shìqing.","vn":"Học tập không phải chuyện nhất thời, mà là việc của cả đời người."},{"cn":"这位科学家把自己的一生都献给了教育事业。","pinyin":"Zhè wèi kēxuéjiā bǎ zìjǐ de yìshēng dōu xiàn gěi le jiàoyù shìyè.","vn":"Nhà khoa học này đã cống hiến cả cuộc đời mình cho sự nghiệp giáo dục."},{"cn":"那段难忘的经历让我一生都记得。","pinyin":"Nà duàn nánwàng de jīnglì ràng wǒ yìshēng dōu jìde.","vn":"Trải nghiệm khó quên ấy khiến tôi nhớ suốt đời."}]},{"hanzi":"快速","pinyin":"kuàisù","pos":"tt.","vn":"nhanh chóng","examples":[{"cn":"这几年，中国的经济和科技都在快速发展。","pinyin":"Zhè jǐ nián, Zhōngguó de jīngjì hé kējì dōu zài kuàisù fāzhǎn.","vn":"Mấy năm nay, kinh tế và công nghệ của Trung Quốc đều đang phát triển nhanh chóng."},{"cn":"请大家快速阅读这篇短文，然后回答问题。","pinyin":"Qǐng dàjiā kuàisù yuèdú zhè piān duǎnwén, ránhòu huídá wèntí.","vn":"Mời mọi người đọc nhanh đoạn văn ngắn này rồi trả lời câu hỏi."},{"cn":"通过这个软件，我们可以快速找到需要的资料。","pinyin":"Tōngguò zhège ruǎnjiàn, wǒmen kěyǐ kuàisù zhǎodào xūyào de zīliào.","vn":"Thông qua phần mềm này, chúng ta có thể nhanh chóng tìm thấy tài liệu cần thiết."}]},{"hanzi":"优秀","pinyin":"yōuxiù","pos":"tt.","vn":"ưu tú, xuất sắc","examples":[{"cn":"她学习刻苦，成绩一直非常优秀。","pinyin":"Tā xuéxí kèkǔ, chéngjì yìzhí fēicháng yōuxiù.","vn":"Cô ấy học tập chăm chỉ, thành tích luôn rất xuất sắc."},{"cn":"我们公司今年招聘了许多优秀的年轻人才。","pinyin":"Wǒmen gōngsī jīnnián zhāopìn le xǔduō yōuxiù de niánqīng réncái.","vn":"Công ty chúng tôi năm nay đã tuyển dụng nhiều nhân tài trẻ xuất sắc."},{"cn":"他是一位既负责任又很优秀的老师。","pinyin":"Tā shì yí wèi jì fù zérèn yòu hěn yōuxiù de lǎoshī.","vn":"Thầy ấy là một giáo viên vừa có trách nhiệm vừa rất ưu tú."}]},{"hanzi":"律师","pinyin":"lǜshī","pos":"dt.","vn":"luật sư","examples":[{"cn":"我姐姐大学毕业后成了一名律师。","pinyin":"Wǒ jiějie dàxué bìyè hòu chéng le yì míng lǜshī.","vn":"Sau khi tốt nghiệp đại học, chị gái tôi đã trở thành luật sư."},{"cn":"遇到法律问题时，最好咨询一下专业律师。","pinyin":"Yùdào fǎlǜ wèntí shí, zuìhǎo zīxún yíxià zhuānyè lǜshī.","vn":"Khi gặp vấn đề pháp lý, tốt nhất nên tham khảo ý kiến của luật sư chuyên nghiệp."},{"cn":"作为一名律师，他必须不断学习新的法律条文。","pinyin":"Zuòwéi yì míng lǜshī, tā bìxū búduàn xuéxí xīn de fǎlǜ tiáowén.","vn":"Là một luật sư, anh ấy phải không ngừng học hỏi các điều luật mới."}]},{"hanzi":"仍","pinyin":"réng","pos":"phó.","vn":"vẫn, vẫn còn","examples":[{"cn":"虽然已经退休了，但他仍每天坚持读书写字。","pinyin":"Suīrán yǐjīng tuìxiū le, dàn tā réng měitiān jiānchí dúshū xiězì.","vn":"Tuy đã nghỉ hưu rồi, nhưng ông ấy vẫn kiên trì đọc sách viết chữ mỗi ngày."},{"cn":"都晚上十一点了，办公室的灯仍亮着。","pinyin":"Dōu wǎnshang shíyī diǎn le, bàngōngshì de dēng réng liàngzhe.","vn":"Đã 11 giờ tối rồi mà đèn văn phòng vẫn còn sáng."},{"cn":"这件事过去很多年了，但我仍记忆犹新。","pinyin":"Zhè jiàn shì guòqù hěn duō nián le, dàn wǒ réng jìyì yóuxīn.","vn":"Chuyện này đã qua nhiều năm rồi, nhưng tôi vẫn nhớ như in."}]},{"hanzi":"准时","pinyin":"zhǔnshí","pos":"tt.","vn":"đúng giờ","examples":[{"cn":"明天早上八点准时出发，请大家不要迟到。","pinyin":"Míngtiān zǎoshang bā diǎn zhǔnshí chūfā, qǐng dàjiā búyào chídào.","vn":"8 giờ sáng mai xuất phát đúng giờ, mọi người đừng đến muộn nhé."},{"cn":"这趟高铁几乎每次都很准时。","pinyin":"Zhè tàng gāotiě jīhū měi cì dōu hěn zhǔnshí.","vn":"Chuyến tàu cao tốc này hầu như lần nào cũng rất đúng giờ."},{"cn":"约会的时候准时到达是对别人的尊重。","pinyin":"Yuēhuì de shíhou zhǔnshí dàodá shì duì biéren de zūnzhòng.","vn":"Đến đúng giờ khi có hẹn là sự tôn trọng đối với người khác."}]},{"hanzi":"网页","pinyin":"wǎngyè","pos":"dt.","vn":"trang web","examples":[{"cn":"网络有点儿慢，这个网页半天都打不开。","pinyin":"Wǎngluò yǒudiǎnr màn, zhège wǎngyè bàntiān dōu dǎbukāi.","vn":"Mạng hơi chậm, trang web này mãi không mở ra được."},{"cn":"他最近正在老年大学学习如何制作网页。","pinyin":"Tā zuìjìn zhèngzài lǎonián dàxué xuéxí rúhé zhìzuò wǎngyè.","vn":"Gần đây ông ấy đang học cách thiết kế trang web ở trường đại học người cao tuổi."},{"cn":"你可以点击网页右上角的按钮进行登录。","pinyin":"Nǐ kěyǐ diǎnjī wǎngyè yòushàngjiǎo de ànniǔ jìnxíng dēnglù.","vn":"Bạn có thể nhấp vào nút ở góc trên bên phải trang web để đăng nhập."}]},{"hanzi":"弹","pinyin":"tán","pos":"dgt.","vn":"đánh, gảy (đàn)","examples":[{"cn":"妹妹从小就学弹钢琴，现在弹得很好听。","pinyin":"Mèimei cóngxiǎo jiù xué tán gāngqín, xiànzài tán de hěn hǎotīng.","vn":"Em gái học đánh đàn piano từ nhỏ, giờ đánh rất hay."},{"cn":"周末我喜欢在房间里弹吉他放松一下。","pinyin":"Zhōumò wǒ xǐhuan zài fángjiān lǐ tán jítā fàngsōng yíxià.","vn":"Cuối tuần tôi thích chơi đàn guitar trong phòng để thư giãn một chút."},{"cn":"听她弹完这首曲子，大家都热烈鼓掌。","pinyin":"Tīng tā tánwán zhè shǒu qǔzi, dàjiā dōu rèliè gǔzhǎng.","vn":"Nghe cô ấy đàn xong bản nhạc này, mọi người đều vỗ tay nhiệt liệt."}]},{"hanzi":"钢琴","pinyin":"gāngqín","pos":"dt.","vn":"đàn piano, dương cầm","examples":[{"cn":"客厅里放着一架白色的钢琴。","pinyin":"Kètīng lǐ fàngzhe yí jià báisè de gāngqín.","vn":"Trong phòng khách đặt một cây đàn piano màu trắng."},{"cn":"她每天都坚持练习一个小时的钢琴。","pinyin":"Tā měitiān dōu jiānchí liànxí yí ge xiǎoshí de gāngqín.","vn":"Mỗi ngày cô ấy đều kiên trì luyện đàn piano một tiếng đồng hồ."},{"cn":"这首钢琴曲听起来温柔又动人。","pinyin":"Zhè shǒu gāngqínqǔ tīng qǐlai wēnróu yòu dòngrén.","vn":"Bản nhạc piano này nghe thật dịu dàng và cảm động."}]},{"hanzi":"重新","pinyin":"chóngxīn","pos":"phó.","vn":"lại từ đầu, một lần nữa","examples":[{"cn":"刚才没听清楚，麻烦你重新说一遍好吗？","pinyin":"Gāngcái méi tīng qīngchu, máfan nǐ chóngxīn shuō yí biàn hǎo ma?","vn":"Vừa nãy nghe không rõ, phiền bạn nói lại một lần nữa được không?"},{"cn":"文件保存失败了，我们得重新写一份。","pinyin":"Wénjiàn bǎocún shībài le, wǒmen děi chóngxīn xiě yí fèn.","vn":"Lưu tệp bị lỗi rồi, chúng ta phải viết lại một bản khác."},{"cn":"退休后重新走进校园学习，让他感到很开心。","pinyin":"Tuìxiū hòu chóngxīn zǒujìn xiàoyuán xuéxí, ràng tā gǎndào hěn kāixīn.","vn":"Sau khi nghỉ hưu bước lại vào trường học tập khiến ông cảm thấy rất vui."}]},{"hanzi":"孔子","pinyin":"Kǒngzǐ","pos":"danh từ riêng","vn":"Khổng Tử","examples":[{"cn":"孔子是中国古代著名的思想家和教育家。","pinyin":"Kǒngzǐ shì Zhōngguó gǔdài zhùmíng de sīxiǎngjiā hé jiàoyùjiā.","vn":"Khổng Tử là nhà tư tưởng và nhà giáo dục nổi tiếng thời cổ đại Trung Quốc."},{"cn":"孔子的很多教育思想至今仍然很有意义。","pinyin":"Kǒngzǐ de hěn duō jiàoyù sīxiǎng zhìjīn réngrán hěn yǒu yìyì.","vn":"Nhiều tư tưởng giáo dục của Khổng Tử đến nay vẫn còn rất có ý nghĩa."},{"cn":"“学而不厌”是孔子说的一句名言。","pinyin":"\"Xué ér bú yàn\" shì Kǒngzǐ shuō de yí jù míngyán.","vn":"\"Học nhi bất yếm\" (học không biết chán) là một câu danh ngôn của Khổng Tử."}]}],"grammar":[{"title":"让步复句\"即使……，也……\"","explanation_vn":"Câu phức nhượng bộ \"即使……，也……\" (cho dù..., cũng...): vế trước đưa ra một giả thiết, thường là tình huống bất lợi hoặc cực đoan; vế sau biểu thị kết quả sẽ không thay đổi hoặc không bị ảnh hưởng.","examples":[{"cn":"有些人即使年龄大了，也坚持去老年班学习。","pinyin":"Yǒuxiē rén jíshǐ niánlíng dà le, yě jiānchí qù lǎoniánbān xuéxí.","vn":"Một số người cho dù đã lớn tuổi rồi vẫn kiên trì đến lớp dành cho người cao tuổi để học tập."},{"cn":"即使明天下大雨，我们也会按时出发。","pinyin":"Jíshǐ míngtiān xià dà yǔ, wǒmen yě huì ànshí chūfā.","vn":"Cho dù ngày mai trời mưa to, chúng tôi cũng sẽ xuất phát đúng giờ."},{"cn":"即使大家都说很难，我也要试一试。","pinyin":"Jíshǐ dàjiā dōu shuō hěn nán, wǒ yě yào shì yi shì.","vn":"Cho dù mọi người đều nói rất khó, tôi cũng muốn thử một lần."}]},{"title":"让步复句\"就是……，也……\"","explanation_vn":"Trong câu phức nhượng bộ \"就是……，也……\", \"就是\" là liên từ, mẫu câu này thường dùng trong khẩu ngữ. Vế trước nêu ra giả thiết cực đoan hoặc điều kiện nhượng bộ, vế sau biểu thị trong điều kiện đó kết quả vẫn không thay đổi, hoặc vẫn giữ nguyên một thái độ, hành động nào đó.","examples":[{"cn":"我就是不在教室，也可以学习中文，和同学一起练口语。","pinyin":"Wǒ jiùshì bú zài jiàoshì, yě kěyǐ xuéxí Zhōngwén, hé tóngxué yìqǐ liàn kǒuyǔ.","vn":"Mình cho dù không ở trong lớp học cũng có thể học tiếng Trung và luyện khẩu ngữ cùng bạn học."},{"cn":"锻炼身体很重要，就是再忙，也要坚持运动。","pinyin":"Duànliàn shēntǐ hěn zhòngyào, jiùshì zài máng, yě yào jiānchí yùndòng.","vn":"Rèn luyện sức khỏe rất quan trọng, cho dù bận đến mấy cũng phải kiên trì vận động."},{"cn":"明天开会需要这份材料，我就是今晚不睡觉，也要把它改完。","pinyin":"Míngtiān kāihuì xūyào zhè fèn cáiliào, wǒ jiùshì jīnwǎn bú shuìjiào, yě yào bǎ tā gǎiwán.","vn":"Cuộc họp ngày mai cần tài liệu này, tối nay tôi có thức trắng đêm cũng phải sửa xong nó."}]},{"title":"并列复句\"不是……，而是……\"","explanation_vn":"Câu phức liên hợp \"不是……，而是……\" (không phải..., mà là...) phủ định tình huống ở vế trước, khẳng định vế sau, nhấn mạnh sự khác biệt hoặc đối lập giữa hai vế.","examples":[{"cn":"教育的目的不是让孩子考高分，而是帮助孩子养成好习惯。","pinyin":"Jiàoyù de mùdì bú shì ràng háizi kǎo gāofēn, érshì bāngzhù háizi yǎngchéng hǎo xíguàn.","vn":"Mục đích của giáo dục không phải là để con thi điểm cao, mà là giúp con hình thành thói quen tốt."},{"cn":"我不是想喝茶，而是想喝水。","pinyin":"Wǒ bú shì xiǎng hē chá, érshì xiǎng hē shuǐ.","vn":"Tôi không phải muốn uống trà, mà là muốn uống nước lọc."},{"cn":"我放学后不是直接回家，而是先去超市买笔。","pinyin":"Wǒ fàngxué hòu bú shì zhíjiē huí jiā, érshì xiān qù chāoshì mǎi bǐ.","vn":"Sau khi tan học tôi không về nhà thẳng, mà là ghé siêu thị mua bút trước."}]},{"title":"固定短语\"就是说\"","explanation_vn":"Cụm từ cố định \"就是说\" (tức là, nói cách khác) dùng để giải thích sâu hơn hoặc diễn đạt theo một cách khác cho nội dung phía trước.","examples":[{"cn":"人要一直坚持学习，就是说，学习是人一生的事情，要活到老学到老。","pinyin":"Rén yào yìzhí jiānchí xuéxí, jiùshì shuō, xuéxí shì rén yìshēng de shìqing, yào huó dào lǎo xué dào lǎo.","vn":"Con người cần luôn kiên trì học tập, tức là học tập là việc của cả đời người, phải sống đến già học đến già."},{"cn":"别着急写，就是说，别着急动笔，想好后再写。","pinyin":"Bié zháojí xiě, jiùshì shuō, bié zháojí dòngbǐ, xiǎnghǎo hòu zài xiě.","vn":"Đừng vội viết, tức là đừng vội cầm bút ngay, hãy nghĩ kỹ rồi mới viết."},{"cn":"这份工作的工资是根据你工作的完成情况来发的，就是说，你完成得越多，工资越高。","pinyin":"Zhè fèn gōngzuò de gōngzī shì gēnjù nǐ gōngzuò de wánchéng qíngkuàng lái fā de, jiùshì shuō, nǐ wánchéng de yuè duō, gōngzī yuè gāo.","vn":"Tiền lương của công việc này được trả dựa trên tình hình hoàn thành công việc của bạn, nói cách khác, bạn hoàn thành càng nhiều thì lương càng cao."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"这里的老年人真不少。","pinyin":"Zhèlǐ de lǎoniánrén zhēn bùshǎo."},{"speaker":"李文","cn":"嗯，住在附近的老年人都会来这儿，有的散步，有的唱歌、跳舞，还有的打太极拳。","pinyin":"Ng, zhù zài fùjìn de lǎoniánrén dōu huì lái zhèr, yǒude sànbù, yǒude chànggē, tiàowǔ, hái yǒude dǎ Tàijíquán."},{"speaker":"白家月","cn":"他们的生活真丰富，让人羡慕。","pinyin":"Tāmen de shēnghuó zhēn fēngfù, ràng rén xiànmù."},{"speaker":"李文","cn":"是的。有些人即使年龄大了，也坚持去老年班学习。","pinyin":"Shì de. Yǒuxiē rén jíshǐ niánlíng dà le, yě jiānchí qù lǎoniánbān xuéxí."},{"speaker":"白家月","cn":"真是活到老学到老啊。","pinyin":"Zhēnshi huó dào lǎo xué dào lǎo a."},{"speaker":"李文","cn":"对，我爷爷就每周都去老年班学电脑。他总说，老年人也要继续学习，“你看，我都七八十岁了，还上网和网友们聊天儿呢，生活一点儿都不无聊。”","pinyin":"Duì, wǒ yéye jiù měi zhōu dōu qù lǎoniánbān xué diànnǎo. Tā zǒng shuō, lǎoniánrén yě yào jìxù xuéxí, \"Nǐ kàn, wǒ dōu qī bā shí suì le, hái shàngwǎng hé wǎngyǒumen liáotiānr ne, shēnghuó yìdiǎnr dōu bù wúliáo.\""}],"translation_vn":"Bạch Gia Nguyệt: Người cao tuổi ở đây thật đông.\nLý Văn: Ừ, các cụ sống gần đây đều đến chỗ này, người thì đi dạo, người thì ca hát, nhảy múa, còn có người tập Thái cực quyền nữa.\nBạch Gia Nguyệt: Cuộc sống của họ thật phong phú, khiến người ta ngưỡng mộ.\nLý Văn: Đúng vậy. Một số người cho dù đã lớn tuổi rồi vẫn kiên trì đến lớp học cho người cao tuổi để học tập.\nBạch Gia Nguyệt: Đúng là sống đến già, học đến già.\nLý Văn: Đúng thế, ông nội mình tuần nào cũng đến lớp người cao tuổi học máy tính. Ông luôn nói người già cũng phải tiếp tục học hỏi: \"Cháu xem, ông bảy tám mươi tuổi rồi mà vẫn lên mạng trò chuyện với bạn bè trên mạng đấy, cuộc sống chẳng hề nhàm chán chút nào.\"","audio_dialogue":"11-1.mp3","audio_vocab":"11-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"安妮","cn":"家月，我们今天的课是在数字教室上的，感觉挺不一样的。","pinyin":"Jiāyuè, wǒmen jīntiān de kè shì zài shùzì jiàoshì shàng de, gǎnjué tǐng bù yíyàng de."},{"speaker":"白家月","cn":"是的，数字教室可以拍照点名，教授在线上点名，不用像线下那样一个个叫名字，特别节约时间。","pinyin":"Shì de, shùzì jiàoshì kěyǐ pāizhào diǎnmíng, jiàoshòu zài xiànshàng diǎnmíng, búyòng xiàng xiànxià nàyàng yí ge ge jiào míngzi, tèbié jiéyuē shíjiān."},{"speaker":"李文","cn":"最方便的是，课上没听明白时，课后还能在学校网站上找到视频记录看。","pinyin":"Zuì fāngbiàn de shì, kèshàng méi tīng míngbai shí, kèhòu hái néng zài xuéxiào wǎngzhàn shàng zhǎodào shìpín jìlù kàn."},{"speaker":"安妮","cn":"对，上课我都不用着急记笔记了。","pinyin":"Duì, shàngkè wǒ dōu búyòng zháojí jì bǐjì le."},{"speaker":"李文","cn":"不仅数字教室很方便，现在网上到处是学习资料，想查什么都能查到，自学也更方便了。","pinyin":"Bùjǐn shùzì jiàoshì hěn fāngbiàn, xiànzài wǎngshàng dàochù shì xuéxí zīliào, xiǎng chá shénme dōu néng chádào, zìxué yě gèng fāngbiàn le."},{"speaker":"白家月","cn":"是的，只要有手机或电脑，我就是不在教室，也可以学习中文，和同学一起练口语。","pinyin":"Shì de, zhǐyào yǒu shǒujī huò diànnǎo, wǒ jiùshì bú zài jiàoshì, yě kěyǐ xuéxí Zhōngwén, hé tóngxué yìqǐ liàn kǒuyǔ."},{"speaker":"安妮","cn":"科技真是让获取知识变得简单多了。","pinyin":"Kējì zhēnshi ràng huòqǔ zhīshi biànde jiǎndān duō le."}],"translation_vn":"Annie: Gia Nguyệt ơi, buổi học hôm nay của chúng mình học ở phòng học số, cảm giác khá là khác biệt.\nBạch Gia Nguyệt: Đúng vậy, phòng học số có thể chụp ảnh điểm danh, giáo sư điểm danh trực tuyến, không cần gọi từng tên một như học trực tiếp, rất tiết kiệm thời gian.\nLý Văn: Điều tiện lợi nhất là khi trên lớp nghe chưa hiểu, sau giờ học vẫn có thể tìm bản ghi video trên trang web của trường để xem lại.\nAnnie: Đúng rồi, trong giờ học mình còn không phải vội vàng ghi chép nữa.\nLý Văn: Không chỉ phòng học số rất tiện lợi, bây giờ trên mạng đâu đâu cũng có tài liệu học tập, muốn tra gì cũng tra được, tự học cũng thuận tiện hơn nhiều.\nBạch Gia Nguyệt: Đúng thế, chỉ cần có điện thoại hoặc máy tính, mình cho dù không ở trong lớp học cũng có thể học tiếng Trung và luyện khẩu ngữ cùng bạn học.\nAnnie: Công nghệ thực sự khiến việc tiếp thu kiến thức trở nên đơn giản hơn nhiều.","audio_dialogue":"11-3.mp3","audio_vocab":"11-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"今天星期六，我们去了一雪姐姐家。姐姐家的两个孩子很有礼貌，我们一进门，就马上和我们打招呼。","pinyin":"Jīntiān xīngqīliù, wǒmen qùle Yīxuě jiějie jiā. Jiějie jiā de liǎng ge háizi hěn yǒu lǐmào, wǒmen yí jìnmén, jiù mǎshàng hé wǒmen dǎ zhāohu."},{"speaker":"","cn":"在姐姐家，我们也聊到了孩子的教育。姐姐说，以前他们和很多家长一样，觉得孩子上个好大学，人生才是成功的。所以，他们只关心孩子的分数，结果孩子压力特别大，每天都很不开心。后来，他们认识到，教育的目的不是让孩子考高分，而是帮助孩子养成好习惯。于是，他们做出改变，每天都给孩子留出时间外出锻炼身体，或者看些自己感兴趣的书。","pinyin":"Zài jiějie jiā, wǒmen yě liáodào le háizi de jiàoyù. Jiějie shuō, yǐqián tāmen hé hěn duō jiāzhǎng yíyàng, juéde háizi shàng ge hǎo dàxué, rénshēng cái shì chénggōng de. Suǒyǐ, tāmen zhǐ guānxīn háizi de fēnshù, jiéguǒ háizi yālì tèbié dà, měitiān dōu hěn bù kāixīn. Hòulái, tāmen rènshi dào, jiàoyù de mùdì bú shì ràng háizi kǎo gāofēn, érshì bāngzhù háizi yǎngchéng hǎo xíguàn. Yúshì, tāmen zuòchū gǎibiàn, měitiān dōu gěi háizi liúchū shíjiān wàichū duànliàn shēntǐ, huòzhě kàn xiē zìjǐ gǎn xìngqù de shū."},{"speaker":"","cn":"我觉得他们的做法真棒。","pinyin":"Wǒ juéde tāmen de zuòfǎ zhēn bàng."}],"translation_vn":"Hôm nay là thứ Bảy, chúng tôi đến nhà chị Nhất Tuyết chơi. Hai đứa con nhà chị rất lễ phép, chúng tôi vừa bước vào cửa là các bé lập tức chào hỏi ngay.\nỞ nhà chị, chúng tôi cũng trò chuyện về việc giáo dục con cái. Chị kể, trước đây anh chị cũng giống như nhiều phụ huynh khác, nghĩ rằng con đỗ vào một trường đại học tốt thì cuộc đời mới coi là thành công. Vì vậy, họ chỉ quan tâm đến điểm số của con, kết quả là các con chịu áp lực vô cùng lớn, ngày nào cũng không vui. Về sau, anh chị nhận ra rằng mục đích của giáo dục không phải là để con thi điểm cao, mà là giúp con hình thành những thói quen tốt. Thế là họ đã thay đổi, mỗi ngày đều dành thời gian cho con ra ngoài rèn luyện sức khỏe, hoặc đọc những cuốn sách mà chúng thích.\nTôi thấy cách làm của anh chị thật tuyệt vời.","audio_dialogue":"11-5.mp3","audio_vocab":"11-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"“学而不厌”是两千多年前中国教育家孔子说过的话，意思是人要一直坚持学习，就是说，学习是人一生的事情，要活到老学到老。在世界快速变化的今天，“学而不厌”变得更加重要。","pinyin":"\"Xué ér bú yàn\" shì liǎng qiān duō nián qián Zhōngguó jiàoyùjiā Kǒngzǐ shuōguo de huà, yìsi shì rén yào yìzhí jiānchí xuéxí, jiùshì shuō, xuéxí shì rén yìshēng de shìqing, yào huó dào lǎo xué dào lǎo. Zài shìjiè kuàisù biànhuà de jīntiān, \"xué ér bú yàn\" biànde gèngjiā zhòngyào."},{"speaker":"","cn":"我有一位很优秀的律师朋友，他一直在学习新的法律知识。他说，这不仅是律师的要求和责任，也是提高自己能力的重要方法。","pinyin":"Wǒ yǒu yí wèi hěn yōuxiù de lǜshī péngyou, tā yìzhí zài xuéxí xīn de fǎlǜ zhīshi. Tā shuō, zhè bùjǐn shì lǜshī de yāoqiú hé zérèn, yě shì tígāo zìjǐ nénglì de zhòngyào fāngfǎ."},{"speaker":"","cn":"同时我也认为，人就是不再工作了，坚持学习仍很重要。就像我爷爷，虽然七十多岁了，每天还准时去老年大学上课，学习做网页、弹钢琴。他说，重新当一回学生，生活更有意思了，也感觉自己变年轻了。","pinyin":"Tóngshí wǒ yě rènwéi, rén jiùshì búzài gōngzuò le, jiānchí xuéxí réng hěn zhòngyào. Jiù xiàng wǒ yéye, suīrán qīshí duō suì le, měitiān hái zhǔnshí qù lǎonián dàxué shàngkè, xuéxí zuò wǎngyè, tán gāngqín. Tā shuō, chóngxīn dāng yì huí xuésheng, shēnghuó gèng yǒuyìsi le, yě gǎnjué zìjǐ biàn niánqīng le."}],"translation_vn":"\"Học nhi bất yếm\" (học không biết chán) là câu nói của nhà giáo dục Trung Quốc Khổng Tử cách đây hơn hai nghìn năm, ý nói con người phải luôn kiên trì học tập, tức là học tập là việc của cả đời người, phải sống đến già học đến già. Trong thế giới thay đổi nhanh chóng ngày nay, tinh thần \"học không biết chán\" càng trở nên quan trọng hơn.\nTôi có một người bạn luật sư rất xuất sắc, anh ấy vẫn luôn học hỏi những kiến thức pháp luật mới. Anh ấy nói, đây không chỉ là yêu cầu và trách nhiệm của người luật sư, mà còn là phương pháp quan trọng để nâng cao năng lực bản thân.\nĐồng thời tôi cũng cho rằng, con người cho dù không còn đi làm nữa thì việc kiên trì học tập vẫn rất quan trọng. Giống như ông nội tôi, tuy đã hơn bảy mươi tuổi rồi nhưng mỗi ngày vẫn đúng giờ đến trường đại học dành cho người cao tuổi để học làm trang web, học đánh đàn piano. Ông nói, được làm học sinh lại một lần nữa khiến cuộc sống thêm thú vị, và ông cũng cảm thấy mình trẻ ra.","audio_dialogue":"11-7.mp3","audio_vocab":"11-8.mp3"}]},{"id":12,"title_cn":"幸福的家庭","title_pinyin":"Xìngfú de jiātíng","title_vn":"Gia đình hạnh phúc","goals":["Có thể nghe hiểu và trao đổi về chủ đề gia đình hạnh phúc.","Có thể kể lại bằng lời hoặc bằng văn bản những câu chuyện đời sống về gia đình hạnh phúc.","Hiểu được đặc điểm văn hóa tình thân gia đình của người Trung Quốc."],"vocab":[{"hanzi":"毛衣","pinyin":"máoyī","pos":"dt.","vn":"áo len","examples":[{"cn":"天冷了，出门记得穿件厚毛衣。","pinyin":"Tiān lěng le, chūmén jìde chuān jiàn hòu máoyī.","vn":"Trời lạnh rồi, ra ngoài nhớ mặc một chiếc áo len dày nhé."},{"cn":"这件米色的毛衣摸起来特别柔软。","pinyin":"Zhè jiàn mǐsè de máoyī mō qǐlai tèbié róuruǎn.","vn":"Chiếc áo len màu kem này sờ vào đặc biệt mềm mại."},{"cn":"妈妈亲手给我织了一件毛衣。","pinyin":"Māma qīnshǒu gěi wǒ zhī le yí jiàn máoyī.","vn":"Mẹ tự tay đan cho tôi một chiếc áo len."}]},{"hanzi":"样子","pinyin":"yàngzi","pos":"dt.","vn":"kiểu dáng, dáng vẻ","examples":[{"cn":"这双鞋的样子很时尚，穿起来也很舒服。","pinyin":"Zhè shuāng xié de yàngzi hěn shíshàng, chuān qǐlai yě hěn shūfu.","vn":"Kiểu dáng của đôi giày này rất thời trang, đi vào cũng rất êm chân."},{"cn":"看他着急的样子，一定是出了什么事。","pinyin":"Kàn tā zháojí de yàngzi, yídìng shì chū le shénme shì.","vn":"Nhìn dáng vẻ lo lắng của anh ấy, chắc chắn là có chuyện gì xảy ra rồi."},{"cn":"多年不见，家乡已经完全变了样子。","pinyin":"Duō nián bú jiàn, jiāxiāng yǐjīng wánquán biàn le yàngzi.","vn":"Nhiều năm không gặp, quê hương đã hoàn toàn thay đổi diện mạo."}]},{"hanzi":"适合","pinyin":"shìhé","pos":"dgt.","vn":"phù hợp, hợp","examples":[{"cn":"这条裙子的颜色很适合你，显得特别精神。","pinyin":"Zhè tiáo qúnzi de yánsè hěn shìhé nǐ, xiǎnde tèbié jīngshen.","vn":"Màu sắc của chiếc váy này rất hợp với bạn, trông rất tươi tắn."},{"cn":"这里的气候冬暖夏凉，非常适合老年人居住。","pinyin":"Zhèlǐ de qìhòu dōngnuǎn xiàliáng, fēicháng shìhé lǎoniánrén jūzhù.","vn":"Khí hậu ở đây mùa đông ấm mùa hè mát, rất phù hợp cho người cao tuổi sinh sống."},{"cn":"每个人都有适合自己的学习方法。","pinyin":"Měi ge rén dōu yǒu shìhé zìjǐ de xuéxí fāngfǎ.","vn":"Mỗi người đều có phương pháp học tập phù hợp với bản thân."}]},{"hanzi":"售货员","pinyin":"shòuhuòyuán","pos":"dt.","vn":"nhân viên bán hàng","examples":[{"cn":"这位售货员态度热情，耐心地帮我挑尺码。","pinyin":"Zhè wèi shòuhuòyuán tàidu rèqíng, nàixīn de bāng wǒ tiāo chǐmǎ.","vn":"Nhân viên bán hàng này thái độ nhiệt tình, kiên nhẫn giúp tôi chọn cỡ."},{"cn":"你可以问问售货员，这款手机还有没有货。","pinyin":"Nǐ kěyǐ wènwen shòuhuòyuán, zhè kuǎn shǒujī hái yǒu méiyǒu huò.","vn":"Bạn có thể hỏi nhân viên bán hàng xem mẫu điện thoại này còn hàng không."},{"cn":"商场里人太多了，售货员们都忙不过来。","pinyin":"Shāngchǎng lǐ rén tài duō le, shòuhuòyuánmen dōu máng bu guòlái.","vn":"Trong trung tâm thương mại đông người quá, các nhân viên bán hàng làm không xuể."}]},{"hanzi":"质量","pinyin":"zhìliàng","pos":"dt.","vn":"chất lượng","examples":[{"cn":"这家店的东西虽然贵一点儿，但质量很有保障。","pinyin":"Zhè jiā diàn de dōngxi suīrán guì yìdiǎnr, dàn zhìliàng hěn yǒu bǎozhàng.","vn":"Đồ của cửa hàng này tuy hơi đắt một chút, nhưng chất lượng rất đảm bảo."},{"cn":"早睡早起能明显提高我们的睡眠质量。","pinyin":"Zǎoshuì zǎoqǐ néng míngxiǎn tígāo wǒmen de shuìmián zhìliàng.","vn":"Ngủ sớm dậy sớm có thể nâng cao rõ rệt chất lượng giấc ngủ của chúng ta."},{"cn":"买衣服时不能只看款式，更要注意质量。","pinyin":"Mǎi yīfu shí bù néng zhǐ kàn kuǎnshì, gèng yào zhùyì zhìliàng.","vn":"Khi mua quần áo không thể chỉ nhìn kiểu dáng mà càng phải chú ý đến chất lượng."}]},{"hanzi":"强","pinyin":"qiáng","pos":"tt.","vn":"tốt hơn, hơn; mạnh mẽ","examples":[{"cn":"一家人平平安安比什么都强。","pinyin":"Yìjiārén píngpíng'ān'ān bǐ shénme dōu qiáng.","vn":"Cả nhà bình an khỏe mạnh còn hơn mọi thứ."},{"cn":"他的学习能力很强，很快就能掌握新技能。","pinyin":"Tā de xuéxí nénglì hěn qiáng, hěn kuài jiù néng zhǎngwò xīn jìnéng.","vn":"Khả năng học hỏi của anh ấy rất mạnh, rất nhanh đã nắm vững kỹ năng mới."},{"cn":"今天的风比昨天强多了，出门要戴帽子。","pinyin":"Jīntiān de fēng bǐ zuótiān qiáng duō le, chūmén yào dài màozi.","vn":"Gió hôm nay mạnh hơn hôm qua nhiều, ra ngoài nhớ đội mũ nhé."}]},{"hanzi":"年底","pinyin":"niándǐ","pos":"dt.","vn":"cuối năm","examples":[{"cn":"一到年底，公司里的工作就特别忙。","pinyin":"Yí dào niándǐ, gōngsī lǐ de gōngzuò jiù tèbié máng.","vn":"Cứ đến cuối năm là công việc ở công ty lại đặc biệt bận rộn."},{"cn":"商场年底大促销，很多商品都在降价。","pinyin":"Shāngchǎng niándǐ dà cùxiāo, hěn duō shāngpǐn dōu zài jiàngjià.","vn":"Trung tâm thương mại khuyến mãi lớn cuối năm, nhiều mặt hàng đều đang giảm giá."},{"cn":"我们打算今年年底带父母去南方旅游。","pinyin":"Wǒmen dǎsuàn jīnnián niándǐ dài fùmǔ qù nánfāng lǚyóu.","vn":"Chúng tôi dự định cuối năm nay đưa bố mẹ đi du lịch miền Nam."}]},{"hanzi":"全","pinyin":"quán","pos":"tt./phó.","vn":"toàn bộ, đầy đủ; hoàn toàn","examples":[{"cn":"这家超市的日用品很全，什么都能买到。","pinyin":"Zhè jiā chāoshì de rìyòngpǐn hěn quán, shénme dōu néng mǎidào.","vn":"Đồ dùng hằng ngày ở siêu thị này rất đầy đủ, thứ gì cũng mua được."},{"cn":"听到这个好消息，全家人都高兴极了。","pinyin":"Tīngdào zhège hǎo xiāoxi, quánjiārén dōu gāoxìng jíle.","vn":"Nghe thấy tin tốt này, cả nhà ai cũng vui mừng khôn xiết."},{"cn":"我把今天要带的资料全准备好了。","pinyin":"Wǒ bǎ jīntiān yào dài de zīliào quán zhǔnbèi hǎo le.","vn":"Tôi đã chuẩn bị xong hết toàn bộ tài liệu cần mang theo hôm nay."}]},{"hanzi":"打折","pinyin":"dǎzhé","pos":"dgt.","vn":"giảm giá, chiết khấu","examples":[{"cn":"这家书店周末全场打八折，我们去逛逛吧。","pinyin":"Zhè jiā shūdiàn zhōumò quánchǎng dǎ bāzhé, wǒmen qù guàngguang ba.","vn":"Hiệu sách này cuối tuần giảm giá 20% toàn bộ cửa hàng, chúng ta đi dạo xem đi."},{"cn":"这件外套正在打折，比原价便宜了两百块。","pinyin":"Zhè jiàn wàitào zhèngzài dǎzhé, bǐ yuánjià piányi le liǎngbǎi kuài.","vn":"Chiếc áo khoác này đang giảm giá, rẻ hơn giá gốc hai trăm tệ."},{"cn":"虽然在打折，但我们也不应该买不需要的东西。","pinyin":"Suīrán zài dǎzhé, dàn wǒmen yě bù yīnggāi mǎi bù xūyào de dōngxi.","vn":"Tuy đang giảm giá nhưng chúng ta cũng không nên mua những thứ không cần thiết."}]},{"hanzi":"值","pinyin":"zhí","pos":"tt./dgt.","vn":"đáng, đáng giá","examples":[{"cn":"这台电脑性能好、价格低，买得真值。","pinyin":"Zhè tái diànnǎo xìngnéng hǎo, jiàgé dī, mǎi de zhēn zhí.","vn":"Chiếc máy tính này cấu hình tốt, giá rẻ, mua thật đáng tiền."},{"cn":"只要能让家人开心，花这点儿钱也值了。","pinyin":"Zhǐyào néng ràng jiārén kāixīn, huā zhè diǎnr qián yě zhí le.","vn":"Chỉ cần làm người nhà vui vẻ, bỏ ra chút tiền này cũng xứng đáng."},{"cn":"这座古建筑非常有历史价值，值不少钱。","pinyin":"Zhè zuò gǔ jiànzhù fēicháng yǒu lìshǐ jiàzhí, zhí bùshǎo qián.","vn":"Công trình kiến trúc cổ này rất có giá trị lịch sử, đáng giá không ít tiền."}]},{"hanzi":"估计","pinyin":"gūjì","pos":"dgt.","vn":"ước chừng, đoán chừng","examples":[{"cn":"天阴得厉害，估计一会儿就要下雨了。","pinyin":"Tiān yīn de lìhai, gūjì yíhuìr jiù yào xiàyǔ le.","vn":"Trời âm u quá, đoán chừng lát nữa sẽ mưa."},{"cn":"路上有点儿堵车，我估计要晚十分钟才能到。","pinyin":"Lùshang yǒudiǎnr dǔchē, wǒ gūjì yào wǎn shí fēnzhōng cái néng dào.","vn":"Đường hơi tắc, tôi ước chừng phải muộn mười phút mới đến nơi được."},{"cn":"这次考试题目不难，估计大家都能考得不错。","pinyin":"Zhè cì kǎoshì tímù bù nán, gūjì dàjiā dōu néng kǎo de búcuò.","vn":"Đề thi lần này không khó, đoán chừng mọi người đều sẽ thi tốt."}]},{"hanzi":"期","pinyin":"qī","pos":"lượng.","vn":"(lượng từ dùng cho khóa học, hoạt động theo định kỳ) kỳ, khóa, đợt","examples":[{"cn":"社区这个月举办了一期书法培训班。","pinyin":"Shèqū zhège yuè jǔbàn le yì qī shūfǎ péixùnbān.","vn":"Khu dân cư tháng này đã tổ chức một khóa học thư pháp."},{"cn":"这一期杂志专门介绍了中国的传统节日。","pinyin":"Zhè yì qī zázhì zhuānmén jièshào le Zhōngguó de chuántǒng jiérì.","vn":"Số tạp chí kỳ này chuyên giới thiệu về các lễ hội truyền thống của Trung Quốc."},{"cn":"那档电视节目每期都会请不同的嘉宾。","pinyin":"Nà dàng diànshì jiémù měi qī dōu huì qǐng bùtóng de jiābīn.","vn":"Chương trình truyền hình đó mỗi số đều mời những khách mời khác nhau."}]},{"hanzi":"听力","pinyin":"tīnglì","pos":"dt.","vn":"thính lực, khả năng nghe","examples":[{"cn":"长时间戴耳机听大声音乐会伤害听力。","pinyin":"Cháng shíjiān dài ěrjī tīng dàshēng yīnyuè huì shānghài tīnglì.","vn":"Đeo tai nghe nghe nhạc âm lượng lớn trong thời gian dài sẽ làm hại thính lực."},{"cn":"我每天坚持听新闻，汉语听力提高得很快。","pinyin":"Wǒ měitiān jiānchí tīng xīnwén, Hànyǔ tīnglì tígāo de hěn kuài.","vn":"Tôi kiên trì nghe tin tức mỗi ngày nên kỹ năng nghe tiếng Hán tiến bộ rất nhanh."},{"cn":"爷爷年纪大了，听力没有以前那么好了。","pinyin":"Yéye niánjì dà le, tīnglì méiyǒu yǐqián nàme hǎo le.","vn":"Ông nội lớn tuổi rồi, thính lực không còn tốt như trước nữa."}]},{"hanzi":"烦","pinyin":"fán","pos":"tt./dgt.","vn":"phiền muộn, bực bội; làm phiền","examples":[{"cn":"最近事情太多，他心里觉得特别烦。","pinyin":"Zuìjìn shìqing tài duō, tā xīnli juéde tèbié fán.","vn":"Dạo này nhiều việc quá, trong lòng anh ấy cảm thấy rất bực bội."},{"cn":"你别总是问同一个问题，真让人烦。","pinyin":"Nǐ bié zǒngshì wèn tóng yí ge wèntí, zhēn ràng rén fán.","vn":"Bạn đừng cứ hỏi mãi một câu hỏi thế, thật làm người ta thấy phiền."},{"cn":"心情烦的时候，出去走走会好受很多。","pinyin":"Xīnqíng fán de shíhou, chūqù zǒuzou huì hǎoshòu hěn duō.","vn":"Khi tâm trạng bực bội, ra ngoài đi dạo một chút sẽ dễ chịu hơn nhiều."}]},{"hanzi":"脱","pinyin":"tuō","pos":"dgt.","vn":"cởi (quần áo, giày dép)","examples":[{"cn":"屋里暖气很足，进来把大衣脱了吧。","pinyin":"Wūli nuǎnqì hěn zú, jìnlái bǎ dàyī tuō le ba.","vn":"Trong phòng máy sưởi rất ấm, vào rồi thì cởi áo khoác ra đi."},{"cn":"进门前请把鞋脱在门口的鞋架旁。","pinyin":"Jìnmén qián qǐng bǎ xié tuō zài ménkǒu de xiéjià páng.","vn":"Trước khi vào nhà xin hãy cởi giày để cạnh giá giày ở cửa."},{"cn":"刚运动完出了汗，先别急着脱衣服，小心感冒。","pinyin":"Gāng yùndòng wán chū le hàn, xiān bié jízhe tuō yīfu, xiǎoxīn gǎnmào.","vn":"Vừa tập thể dục xong đang ra mồ hôi, đừng vội cởi áo kẻo bị cảm lạnh."}]},{"hanzi":"挂","pinyin":"guà","pos":"dgt.","vn":"treo, móc","examples":[{"cn":"客厅的墙上挂着一幅全家福照片。","pinyin":"Kètīng de qiáng shang guàzhe yì fú quánjiāfú zhàopiàn.","vn":"Trên tường phòng khách có treo một bức ảnh gia đình."},{"cn":"脱下来的外套要及时挂进衣柜里。","pinyin":"Tuō xiàlái de wàitào yào jíshí guà jìn yīguì lǐ.","vn":"Áo khoác cởi ra cần treo ngay vào trong tủ quần áo."},{"cn":"过年的时候，家家户户门口都挂起了红灯笼。","pinyin":"Guònián de shíhou, jiājiāhùhù ménkǒu dōu guàqǐ le hóng dēnglong.","vn":"Vào dịp Tết, trước cửa nhà nhà đều treo đèn lồng đỏ."}]},{"hanzi":"脾气","pinyin":"píqi","pos":"dt.","vn":"tính khí, cơn nóng giận","examples":[{"cn":"无论遇到什么不顺心的事，都不要随便对家人发脾气。","pinyin":"Wúlùn yùdào shénme bú shùnxīn de shì, dōu búyào suíbiàn duì jiārén fā píqi.","vn":"Bất kể gặp chuyện gì không vừa ý cũng đừng tùy tiện nổi nóng với người nhà."},{"cn":"老师脾气特别好，从来没对学生大声吼过。","pinyin":"Lǎoshī píqi tèbié hǎo, cónglái méi duì xuésheng dàshēng hǒu guo.","vn":"Cô giáo tính tình rất hiền, chưa bao giờ quát lớn với học sinh."},{"cn":"他虽然脾气有点儿急，但心地非常善良。","pinyin":"Tā suīrán píqi yǒudiǎnr jí, dàn xīndì fēicháng shànliáng.","vn":"Anh ấy tuy tính hơi nóng nảy nhưng tấm lòng rất lương thiện."}]},{"hanzi":"伤心","pinyin":"shāngxīn","pos":"tt.","vn":"đau lòng, buồn bã","examples":[{"cn":"听到外婆生病的消息，她伤心地哭了起来。","pinyin":"Tīngdào wàipó shēngbìng de xiāoxi, tā shāngxīn de kū le qǐlai.","vn":"Nghe tin bà ngoại bị ốm, cô ấy đau lòng bật khóc."},{"cn":"一次考试没考好别太伤心，下次努力就行了。","pinyin":"Yí cì kǎoshì méi kǎohǎo bié tài shāngxīn, xià cì nǔlì jiù xíng le.","vn":"Một lần thi không tốt đừng quá buồn bã, lần sau cố gắng là được."},{"cn":"说重话伤害了朋友的感情，我心里也很伤心。","pinyin":"Shuō zhònghuà shānghài le péngyou de gǎnqíng, wǒ xīnli yě hěn shāngxīn.","vn":"Nói lời nặng nề làm tổn thương tình cảm bạn bè, trong lòng tôi cũng rất buồn."}]},{"hanzi":"批评","pinyin":"pīpíng","pos":"dgt.","vn":"phê bình","examples":[{"cn":"做错了事就要虚心接受别人的批评。","pinyin":"Zuòcuò le shì jiù yào xūxīn jiēshòu biéren de pīpíng.","vn":"Làm sai việc thì cần khiêm tốn tiếp thu lời phê bình của người khác."},{"cn":"因为经常迟到，他今天被经理批评了一顿。","pinyin":"Yīnwèi jīngcháng chídào, tā jīntiān bèi jīnglǐ pīpíng le yí dùn.","vn":"Vì thường xuyên đi muộn, hôm nay anh ấy bị giám đốc phê bình một trận."},{"cn":"妈妈虽然批评了弟弟，但也是为了他好。","pinyin":"Māma suīrán pīpíng le dìdi, dàn yě shì wèile tā hǎo.","vn":"Mẹ tuy phê bình em trai nhưng cũng chỉ là muốn tốt cho em ấy."}]},{"hanzi":"道歉","pinyin":"dàoqiàn","pos":"dgt.","vn":"xin lỗi","examples":[{"cn":"既然是你误会了他，就应该主动向他道歉。","pinyin":"Jìrán shì nǐ wùhuì le tā, jiù yīnggāi zhǔdòng xiàng tā dàoqiàn.","vn":"Đã là bạn hiểu lầm anh ấy thì nên chủ động xin lỗi anh ấy."},{"cn":"小明认识到了自己的错误，认真地跟奶奶道了歉。","pinyin":"Xiǎomíng rènshi dào le zìjǐ de cuòwù, rènzhēn de gēn nǎinai dào le qiàn.","vn":"Tiểu Minh nhận ra lỗi sai của mình và nghiêm túc xin lỗi bà nội."},{"cn":"因为航班延误，航空公司向乘客们表示了道歉。","pinyin":"Yīnwèi hángbān yánwù, hángkōng gōngsī xiàng chéngkèmen biǎoshì le dàoqiàn.","vn":"Do chuyến bay bị hoãn, hãng hàng không đã gửi lời xin lỗi tới các hành khách."}]},{"hanzi":"老家","pinyin":"lǎojiā","pos":"dt.","vn":"quê hương, quê nhà","examples":[{"cn":"每年春节，不管多远我们都会回老家过年。","pinyin":"Měi nián Chūnjié, bùguǎn duō yuǎn wǒmen dōu huì huí lǎojiā guònián.","vn":"Mỗi dịp Tết Nguyên Đán, dù xa đến đâu chúng tôi cũng về quê đón Tết."},{"cn":"我的老家在江南，那里风景如画。","pinyin":"Wǒ de lǎojiā zài Jiāngnán, nàlǐ fēngjǐng rúhuà.","vn":"Quê tôi ở Giang Nam, phong cảnh nơi đó đẹp như tranh vẽ."},{"cn":"父母从老家给我寄来了很多土特产。","pinyin":"Fùmǔ cóng lǎojiā gěi wǒ jìlái le hěn duō tǔtèchǎn.","vn":"Bố mẹ gửi cho tôi rất nhiều đặc sản từ quê nhà."}]},{"hanzi":"自","pinyin":"zì","pos":"giới.","vn":"từ, kể từ","examples":[{"cn":"他自大学毕业以来，一直在这家医院工作。","pinyin":"Tā zì dàxué bìyè yǐlái, yìzhí zài zhè jiā yīyuàn gōngzuò.","vn":"Kể từ khi tốt nghiệp đại học, anh ấy luôn làm việc tại bệnh viện này."},{"cn":"自去年开始，我就养成了每天晨跑的习惯。","pinyin":"Zì qùnián kāishǐ, wǒ jiù yǎngchéng le měitiān chénpǎo de xíguàn.","vn":"Từ năm ngoái, tôi đã hình thành thói quen chạy bộ mỗi sáng."},{"cn":"这列火车自北京出发，开往广州。","pinyin":"Zhè liè huǒchē zì Běijīng chūfā, kāiwǎng Guǎngzhōu.","vn":"Đoàn tàu này khởi hành từ Bắc Kinh đi Quảng Châu."}]},{"hanzi":"父母","pinyin":"fùmǔ","pos":"dt.","vn":"bố mẹ, cha mẹ","examples":[{"cn":"工作再忙，也要常抽时间陪陪父母。","pinyin":"Gōngzuò zài máng, yě yào cháng chōu shíjiān péipei fùmǔ.","vn":"Công việc bận đến mấy cũng nên thường xuyên tranh thủ thời gian ở bên bố mẹ."},{"cn":"父母对子女的爱是世界上最无私的。","pinyin":"Fùmǔ duì zǐnǚ de ài shì shìjiè shang zuì wúsī de.","vn":"Tình yêu của cha mẹ dành cho con cái là tình cảm vô tư nhất trên đời."},{"cn":"我和父母虽然不在同一个城市，但每周都视频聊天。","pinyin":"Wǒ hé fùmǔ suīrán bú zài tóng yí ge chéngshì, dàn měizhōu dōu shìpín liáotiān.","vn":"Tôi và bố mẹ tuy không ở cùng một thành phố, nhưng tuần nào cũng gọi video trò chuyện."}]},{"hanzi":"父子","pinyin":"fùzǐ","pos":"dt.","vn":"cha con, bố con","examples":[{"cn":"他们父子俩性格很像，平时无话不谈。","pinyin":"Tāmen fùzǐ liǎ xìnggé hěn xiàng, píngshí wúhuà bù tán.","vn":"Hai cha con họ tính cách rất giống nhau, bình thường không chuyện gì không nói."},{"cn":"周末这对父子经常一起去公园打羽毛球。","pinyin":"Zhōumò zhè duì fùzǐ jīngcháng yìqǐ qù gōngyuán dǎ yǔmáoqiú.","vn":"Cuối tuần hai bố con này thường cùng nhau ra công viên đánh cầu lông."},{"cn":"经过一番深入交谈，父子之间的误会终于解开了。","pinyin":"Jīngguò yì fān shēnrù jiāotán, fùzǐ zhījiān de wùhuì zhōngyú jiěkāi le.","vn":"Sau một cuộc trò chuyện sâu sắc, hiểu lầm giữa hai cha con cuối cùng đã được hóa giải."}]},{"hanzi":"母子","pinyin":"mǔzǐ","pos":"dt.","vn":"mẹ con","examples":[{"cn":"母子俩多年没见，一见面就紧紧抱在了一起。","pinyin":"Mǔzǐ liǎ duō nián méi jiàn, yí jiànmiàn jiù jǐnjǐn bào zài le yìqǐ.","vn":"Hai mẹ con nhiều năm không gặp, vừa gặp nhau liền ôm chầm lấy nhau."},{"cn":"他们母子关系非常融洽，互相都很体谅。","pinyin":"Tāmen mǔzǐ guānxì fēicháng róngqià, hùxiāng dōu hěn tǐliàng.","vn":"Mối quan hệ mẹ con của họ rất hòa thuận, luôn thông cảm cho nhau."},{"cn":"这张照片记录了母子在一起的温馨瞬间。","pinyin":"Zhè zhāng zhàopiàn jìlù le mǔzǐ zài yìqǐ de wēnxīn shùnjiān.","vn":"Bức ảnh này ghi lại khoảnh khắc ấm áp của hai mẹ con bên nhau."}]},{"hanzi":"无论","pinyin":"wúlùn","pos":"liên.","vn":"bất kể, dù cho","examples":[{"cn":"无论天气多冷，他每天早上都坚持去跑步。","pinyin":"Wúlùn tiānqì duō lěng, tā měitiān zǎoshang dōu jiānchí qù pǎobù.","vn":"Bất kể thời tiết lạnh đến đâu, sáng nào anh ấy cũng kiên trì chạy bộ."},{"cn":"无论你做出什么决定，家人都支持你。","pinyin":"Wúlùn nǐ zuòchū shénme juédìng, jiārén dōu zhīchí nǐ.","vn":"Dù bạn đưa ra quyết định gì, gia đình đều ủng hộ bạn."},{"cn":"无论学习还是工作，态度认真都是最重要的。","pinyin":"Wúlùn xuéxí háishi gōngzuò, tàidu rènzhēn dōu shì zuì zhòngyào de.","vn":"Dù là học tập hay làm việc, thái độ nghiêm túc luôn là điều quan trọng nhất."}]},{"hanzi":"条件","pinyin":"tiáojiàn","pos":"dt.","vn":"điều kiện","examples":[{"cn":"如果条件允许，我明年想去国外交流学习。","pinyin":"Rúguǒ tiáojiàn yǔnxǔ, wǒ míngnián xiǎng qù guówài jiāoliú xuéxí.","vn":"Nếu điều kiện cho phép, sang năm tôi muốn đi trao đổi học tập ở nước ngoài."},{"cn":"现在乡村的医疗和教育条件比以前好多了。","pinyin":"Xiànzài xiāngcūn de yīliáo hé jiàoyù tiáojiàn bǐ yǐqián hǎo duō le.","vn":"Hiện nay điều kiện y tế và giáo dục ở nông thôn tốt hơn trước nhiều."},{"cn":"申请这份奖学金需要满足三个基本条件。","pinyin":"Shēnqǐng zhè fèn jiǎngxuéjīn xūyào mǎnzú sān ge jīběn tiáojiàn.","vn":"Xin học bổng này cần đáp ứng ba điều kiện cơ bản."}]},{"hanzi":"允许","pinyin":"yǔnxǔ","pos":"dgt.","vn":"cho phép","examples":[{"cn":"图书馆里不允许大声说话，请保持安静。","pinyin":"Túshūguǎn lǐ bù yǔnxǔ dàshēng shuōhuà, qǐng bǎochí ānjìng.","vn":"Trong thư viện không được phép nói chuyện lớn tiếng, xin hãy giữ yên lặng."},{"cn":"时间允许的话，我们顺便去看看李老师吧。","pinyin":"Shíjiān yǔnxǔ de huà, wǒmen shùnbiàn qù kànkan Lǐ lǎoshī ba.","vn":"Nếu thời gian cho phép, chúng ta tiện đường ghé thăm thầy Lý nhé."},{"cn":"博物馆的展厅内不允许使用闪光灯拍照。","pinyin":"Bówùguǎn de zhǎntīng nèi bù yǔnxǔ shǐyòng shǎnguāngdēng pāizhào.","vn":"Trong phòng trưng bày của bảo tàng không cho phép dùng đèn flash chụp ảnh."}]},{"hanzi":"另外","pinyin":"lìngwài","pos":"phó./đt./liên.","vn":"riêng, khác; ngoài ra","examples":[{"cn":"今天太晚了，这件事我们另外找时间再谈吧。","pinyin":"Jīntiān tài wǎn le, zhè jiàn shì wǒmen lìngwài zhǎo shíjiān zài tán ba.","vn":"Hôm nay muộn quá rồi, chuyện này chúng ta tìm lúc khác bàn tiếp nhé."},{"cn":"除了这两本书，我还另外买了一本词典。","pinyin":"Chúle zhè liǎng běn shū, wǒ hái lìngwài mǎi le yì běn cídiǎn.","vn":"Ngoài hai cuốn sách này, tôi còn mua thêm một cuốn từ điển nữa."},{"cn":"出门要带好护照，另外别忘了带充电器。","pinyin":"Chūmén yào dài hǎo hùzhào, lìngwài bié wàng le dài chōngdiànqì.","vn":"Ra ngoài nhớ mang theo hộ chiếu, ngoài ra đừng quên mang cục sạc."}]},{"hanzi":"卫生","pinyin":"wèishēng","pos":"dt./tt.","vn":"vệ sinh","examples":[{"cn":"每个周末，我们全家都会一起打扫卫生。","pinyin":"Měi ge zhōumò, wǒmen quánjiā dōu huì yìqǐ dǎsǎo wèishēng.","vn":"Mỗi cuối tuần, cả nhà chúng tôi đều cùng nhau dọn dẹp vệ sinh."},{"cn":"饭前洗手是讲究卫生的好习惯。","pinyin":"Fànqián xǐshǒu shì jiǎngjiu wèishēng de hǎo xíguàn.","vn":"Rửa tay trước khi ăn là một thói quen giữ gìn vệ sinh tốt."},{"cn":"这家餐厅环境干净卫生，让人吃得很放心。","pinyin":"Zhè jiā cāntīng huánjìng gānjìng wèishēng, ràng rén chī de hěn fàngxīn.","vn":"Nhà hàng này không gian sạch sẽ vệ sinh, khiến mọi người ăn rất yên tâm."}]},{"hanzi":"母亲","pinyin":"mǔqīn","pos":"dt.","vn":"mẹ, mẫu thân","examples":[{"cn":"母亲节那天，我给母亲买了一束鲜花。","pinyin":"Mǔqīnjié nà tiān, wǒ gěi mǔqīn mǎi le yí shù xiānhuā.","vn":"Vào Ngày của Mẹ, tôi đã mua tặng mẹ một bó hoa tươi."},{"cn":"母亲虽然话不多，但总是默默地照顾着全家。","pinyin":"Mǔqīn suīrán huà bù duō, dàn zǒngshì mòmò de zhàogùzhe quánjiā.","vn":"Mẹ tuy ít nói nhưng luôn âm thầm chăm sóc cả gia đình."},{"cn":"无论走到哪里，我都最想念母亲做的家常菜。","pinyin":"Wúlùn zǒudào nǎlǐ, wǒ dōu zuì xiǎngniàn mǔqīn zuò de jiāchángcài.","vn":"Dù đi đến đâu, tôi cũng nhớ nhất những món cơm nhà mẹ nấu."}]},{"hanzi":"待","pinyin":"dāi","pos":"dgt.","vn":"ở, lưu lại","examples":[{"cn":"假期我打算在奶奶家待一个星期。","pinyin":"Jiàqī wǒ dǎsuàn zài nǎinai jiā dāi yí ge xīngqī.","vn":"Kỳ nghỉ tôi dự định ở nhà bà nội một tuần."},{"cn":"周末下雨，我哪儿也没去，一直在家里待着。","pinyin":"Zhōumò xiàyǔ, wǒ nǎr yě méi qù, yìzhí zài jiā lǐ dāizhe.","vn":"Cuối tuần trời mưa, tôi chẳng đi đâu cả, cứ ở nhà suốt."},{"cn":"父母待在身边，让我们工作起来安心多了。","pinyin":"Fùmǔ dāi zài shēnbiān, ràng wǒmen gōngzuò qǐlai ānxīn duō le.","vn":"Bố mẹ ở bên cạnh khiến chúng tôi làm việc yên tâm hơn nhiều."}]},{"hanzi":"将","pinyin":"jiāng","pos":"giới.","vn":"(giới từ, cách dùng tương tự \"把\") đem, lấy","examples":[{"cn":"请各位乘客将随身行李放好。","pinyin":"Qǐng gèwèi chéngkè jiāng suíshēn xíngli fànghǎo.","vn":"Xin mời quý hành khách cất gọn hành lý xách tay."},{"cn":"她将父母寄来的点心分给了办公室的同事。","pinyin":"Tā jiāng fùmǔ jìlái de diǎnxin fēn gěi le bàngōngshì de tóngshì.","vn":"Cô ấy đem bánh ngọt bố mẹ gửi lên chia cho các đồng nghiệp trong văn phòng."},{"cn":"请您把表格填好后，将它交到前台。","pinyin":"Qǐng nín bǎ biǎogé tiánhǎo hòu, jiāng tā jiāo dào qiántái.","vn":"Sau khi điền xong biểu mẫu, xin ông/bà nộp nó lại cho quầy lễ tân."}]},{"hanzi":"闻","pinyin":"wén","pos":"dgt.","vn":"ngửi","examples":[{"cn":"刚走进厨房，我就闻到了一股诱人的鸡汤香味。","pinyin":"Gāng zǒujìn chúfáng, wǒ jiù wéndào le yì gǔ yòurén de jītāng xiāngwèi.","vn":"Vừa bước vào bếp, tôi đã ngửi thấy mùi canh gà thơm phức."},{"cn":"你闻闻这杯牛奶，是不是已经变质了？","pinyin":"Nǐ wénwen zhè bēi niúnǎi, shì bu shì yǐjīng biànzhì le?","vn":"Bạn ngửi thử cốc sữa này xem, có phải đã hỏng rồi không?"},{"cn":"春天的公园里，处处都能闻到淡淡的花香。","pinyin":"Chūntiān de gōngyuán lǐ, chùchù dōu néng wéndào dàndàn de huāxiāng.","vn":"Trong công viên mùa xuân, đi đâu cũng có thể ngửi thấy hương hoa thoang thoảng."}]},{"hanzi":"味道","pinyin":"wèidào","pos":"dt.","vn":"mùi vị, hương vị","examples":[{"cn":"这家老字号餐馆的饺子味道非常地道。","pinyin":"Zhè jiā lǎozìhào cānguǎn de jiǎozi wèidào fēicháng dìdào.","vn":"Hương vị sủi cảo ở nhà hàng lâu đời này vô cùng chuẩn vị."},{"cn":"这碗汤的味道既清淡又鲜美，我很喜欢。","pinyin":"Zhè wǎn tāng de wèidào jì qīngdàn yòu xiānměi, wǒ hěn xǐhuan.","vn":"Vị của bát canh này vừa thanh đạm vừa ngọt đậm, tôi rất thích."},{"cn":"不管走得多远，我总忘不了家乡菜的味道。","pinyin":"Bùguǎn zǒu de duō yuǎn, wǒ zǒng wàngbuliǎo jiāxiāngcài de wèidào.","vn":"Dù đi xa đến đâu, tôi vẫn không thể quên được hương vị món ăn quê nhà."}]},{"hanzi":"冷静","pinyin":"lěngjìng","pos":"tt.","vn":"bình tĩnh, điềm tĩnh","examples":[{"cn":"遇到突发情况时，首先要保持冷静。","pinyin":"Yùdào tūfā qíngkuàng shí, shǒuxiān yào bǎochí lěngjìng.","vn":"Khi gặp tình huống bất ngờ, trước tiên phải giữ bình tĩnh."},{"cn":"我们先各自冷静一下，明天再好好谈吧。","pinyin":"Wǒmen xiān gèzì lěngjìng yíxià, míngtiān zài hǎohǎo tán ba.","vn":"Chúng ta hãy cùng bình tĩnh lại một chút, ngày mai nói chuyện tử tế nhé."},{"cn":"她做事一向冷静沉着，从不慌张。","pinyin":"Tā zuòshì yíxiàng lěngjìng chénzhuó, cóng bù huāngzhāng.","vn":"Cô ấy làm việc xưa nay luôn điềm tĩnh chín chắn, chưa bao giờ hoảng hốt."}]},{"hanzi":"鼻子","pinyin":"bízi","pos":"dt.","vn":"mũi","examples":[{"cn":"听到外公说的话，我感动得鼻子一酸。","pinyin":"Tīngdào wàigōng shuō de huà, wǒ gǎndòng de bízi yì suān.","vn":"Nghe những lời ông ngoại nói, tôi cảm động đến cay sống mũi."},{"cn":"他感冒了，鼻子不通气，晚上睡不好觉。","pinyin":"Tā gǎnmào le, bízi bù tōngqì, wǎnshang shuì bu hǎo jiào.","vn":"Anh ấy bị cảm lạnh, nghẹt mũi nên tối ngủ không ngon giấc."},{"cn":"小宝宝的眼睛像妈妈，鼻子像爸爸。","pinyin":"Xiǎo bǎobao de yǎnjing xiàng māma, bízi xiàng bàba.","vn":"Đôi mắt của em bé giống mẹ, còn chiếc mũi thì giống bố."}]},{"hanzi":"父亲","pinyin":"fùqīn","pos":"dt.","vn":"cha, bố, phụ thân","examples":[{"cn":"父亲从小就教育我要做一个诚实勇敢的人。","pinyin":"Fùqīn cóngxiǎo jiù jiàoyù wǒ yào zuò yí ge chéngshí yǒnggǎn de rén.","vn":"Cha dạy tôi từ nhỏ phải trở thành một người trung thực và dũng cảm."},{"cn":"我的父亲是一位认真负责的中学老师。","pinyin":"Wǒ de fùqīn shì yí wèi rènzhēn fùzé de zhōngxué lǎoshī.","vn":"Cha tôi là một giáo viên trung học tận tâm và có trách nhiệm."},{"cn":"父亲很少把爱挂在嘴边，但都在行动里表现出来了。","pinyin":"Fùqīn hěn shǎo bǎ ài guà zài zuǐbiān, dàn dōu zài xíngdòng lǐ biǎoxiàn chūlái le.","vn":"Cha rất ít khi nói lời yêu thương, nhưng đều thể hiện qua từng hành động."}]},{"hanzi":"城","pinyin":"chéng","pos":"dt.","vn":"thành phố, thành","examples":[{"cn":"周末我们打算去郊区玩，星期天晚上再进城。","pinyin":"Zhōumò wǒmen dǎsuàn qù jiāoqū wán, xīngqītiān wǎnshang zài jìnchéng.","vn":"Cuối tuần chúng tôi định ra ngoại ô chơi, tối Chủ nhật mới vào lại thành phố."},{"cn":"这座古城保留着许多明清时期的建筑。","pinyin":"Zhè zuò gǔchéng bǎoliúzhe xǔduō Míng Qīng shíqī de jiànzhù.","vn":"Thành cổ này vẫn lưu giữ nhiều công trình kiến trúc từ thời Minh Thanh."},{"cn":"城里的交通比郊区方便，但也更容易堵车。","pinyin":"Chéng lǐ de jiāotōng bǐ jiāoqū fāngbiàn, dàn yě gèng róngyì dǔchē.","vn":"Giao thông trong thành phố tiện lợi hơn ngoại ô, nhưng cũng dễ tắc đường hơn."}]},{"hanzi":"鲜","pinyin":"xiān","pos":"tt.","vn":"tươi ngon, ngọt (nước dùng, món ăn)","examples":[{"cn":"妈妈炖的这锅鱼汤特别鲜，我喝了两大碗。","pinyin":"Māma dùn de zhè guō yútāng tèbié xiān, wǒ hē le liǎng dà wǎn.","vn":"Nồi canh cá mẹ ninh ngọt ngon vô cùng, tôi đã uống liền hai bát lớn."},{"cn":"早上刚摘的蘑菇煮出来的汤味道真鲜。","pinyin":"Zǎoshang gāng zhāi de mógu zhǔ chūlái de tāng wèidào zhēn xiān.","vn":"Nấm mới hái buổi sáng nấu canh lên vị ngọt thật tuyệt."},{"cn":"海边城市的海鲜既新鲜又鲜美。","pinyin":"Hǎibiān chéngshì de hǎixiān jì xīnxiān yòu xiānměi.","vn":"Hải sản ở thành phố biển vừa tươi mới vừa ngon ngọt."}]},{"hanzi":"暖","pinyin":"nuǎn","pos":"tt.","vn":"ấm áp, ấm","examples":[{"cn":"冬天喝上一碗热鸡汤，全身都暖了起来。","pinyin":"Dōngtiān hēshàng yì wǎn rè jītāng, quánshēn dōu nuǎn le qǐlai.","vn":"Mùa đông uống một bát canh gà nóng, cả người đều ấm hẳn lên."},{"cn":"朋友的一句关心的话，让我心里特别暖。","pinyin":"Péngyou de yí jù guānxīn de huà, ràng wǒ xīnli tèbié nuǎn.","vn":"Một lời hỏi thăm quan tâm của bạn bè khiến lòng tôi cảm thấy vô cùng ấm áp."},{"cn":"春天到了，天气一天比一天暖了。","pinyin":"Chūntiān dào le, tiānqì yì tiān bǐ yì tiān nuǎn le.","vn":"Mùa xuân đến rồi, thời tiết mỗi ngày một ấm hơn."}]},{"hanzi":"勇敢","pinyin":"yǒnggǎn","pos":"tt.","vn":"dũng cảm","examples":[{"cn":"面对挫折时，我们要勇敢地迎接挑战。","pinyin":"Miànduì cuòzhé shí, wǒmen yào yǒnggǎn de yíngjiē tiǎozhàn.","vn":"Khi đối mặt với trắc trở, chúng ta phải dũng cảm đón nhận thử thách."},{"cn":"那个小男孩打针时一点儿也没哭，非常勇敢。","pinyin":"Nàge xiǎo nánhái dǎzhēn shí yìdiǎnr yě méi kū, fēicháng yǒnggǎn.","vn":"Cậu bé đó lúc tiêm chẳng khóc chút nào, vô cùng dũng cảm."},{"cn":"只有勇敢走出第一步，才有可能取得成功。","pinyin":"Zhǐyǒu yǒnggǎn zǒuchū dì-yī bù, cái yǒu kěnéng qǔdé chénggōng.","vn":"Chỉ khi dũng cảm bước đi bước đầu tiên mới có khả năng gặt hái thành công."}]},{"hanzi":"商量","pinyin":"shāngliang","pos":"dgt.","vn":"bàn bạc, thương lượng","examples":[{"cn":"家里有什么大事，他们夫妻俩总会一起商量。","pinyin":"Jiā lǐ yǒu shénme dàshì, tāmen fūqī liǎ zǒng huì yìqǐ shāngliang.","vn":"Trong nhà có chuyện lớn gì, hai vợ chồng họ luôn cùng nhau bàn bạc."},{"cn":"关于周末郊游的路线，我们再好好商量一下吧。","pinyin":"Guānyú zhōumò jiāoyóu de lùxiàn, wǒmen zài hǎohǎo shāngliang yíxià ba.","vn":"Về lộ trình dã ngoại cuối tuần, chúng ta bàn bạc kỹ thêm một chút nhé."},{"cn":"我先跟父母商量商量，明天再给你答复。","pinyin":"Wǒ xiān gēn fùmǔ shāngliang shāngliang, míngtiān zài gěi nǐ dáfù.","vn":"Để tôi bàn bạc với bố mẹ trước đã, ngày mai sẽ trả lời bạn."}]}],"grammar":[{"title":"固定短语\"不怎么\"","explanation_vn":"Cụm từ cố định \"不怎么\" biểu thị mức độ thấp hoặc tần suất không nhiều, có nghĩa là \"không mấy, không lắm, không thường xuyên\".","examples":[{"cn":"样子不错，就是颜色好像不怎么适合她。","pinyin":"Yàngzi búcuò, jiùshì yánsè hǎoxiàng bù zěnme shìhé tā.","vn":"Kiểu dáng khá đẹp, chỉ là màu sắc hình như không hợp với mẹ lắm."},{"cn":"他总是在图书馆看书，不怎么出去玩。","pinyin":"Tā zǒngshì zài túshūguǎn kànshū, bù zěnme chūqù wán.","vn":"Cậu ấy lúc nào cũng đọc sách ở thư viện, không mấy khi ra ngoài chơi."},{"cn":"我爱吃饺子、包子，不怎么喜欢吃米饭。","pinyin":"Wǒ ài chī jiǎozi, bāozi, bù zěnme xǐhuan chī mǐfàn.","vn":"Tôi thích ăn sủi cảo, bánh bao, không thích ăn cơm lắm."}]},{"title":"双重否定","explanation_vn":"Phủ định kép dùng để biểu đạt ý khẳng định, ngữ khí mạnh hơn câu khẳng định thông thường. Các cấu trúc phủ định kép thường gặp gồm \"不是不\" (không phải là không), \"不能不\" (không thể không), \"不得不\" (đành phải, buộc phải),...","examples":[{"cn":"他也不是不知道自己错了，我批评他以后，他马上说放学回来就向奶奶道歉。","pinyin":"Tā yě bú shì bù zhīdào zìjǐ cuò le, wǒ pīpíng tā yǐhòu, tā mǎshàng shuō fàngxué huílái jiù xiàng nǎinai dàoqiàn.","vn":"Thằng bé cũng không phải là không biết mình sai rồi, sau khi em phê bình nó, nó lập tức nói đi học về sẽ xin lỗi bà nội ngay."},{"cn":"今天是我们毕业后第一次同学聚餐，你又是班长，不能不来啊！","pinyin":"Jīntiān shì wǒmen bìyè hòu dì yī cì tóngxué jùcān, nǐ yòu shì bānzhǎng, bù néng bù lái a!","vn":"Hôm nay là buổi liên hoan lớp đầu tiên sau khi tốt nghiệp của chúng ta, cậu lại là lớp trưởng, không thể không đến đâu nhé!"},{"cn":"由于天气不好，飞机不能起飞，爸爸不得不改变计划，明天再去上海。","pinyin":"Yóuyú tiānqì bù hǎo, fēijī bù néng qǐfēi, bàba bùdébù gǎibiàn jìhuà, míngtiān zài qù Shànghǎi.","vn":"Do thời tiết xấu, máy bay không thể cất cánh nên bố đành phải thay đổi kế hoạch, ngày mai mới đi Thượng Hải."}]},{"title":"条件复句\"无论……，都/也……\"","explanation_vn":"Câu phức điều kiện \"无论……，都/也……\" (bất kể..., đều/cũng...) biểu thị trong bất kỳ điều kiện nào thì kết quả cũng không thay đổi.","examples":[{"cn":"杨同乐很关心父母，无论平时工作有多忙，他每个周末都会给父母打电话。","pinyin":"Yáng Tónglè hěn guānxīn fùmǔ, wúlùn píngshí gōngzuò yǒu duō máng, tā měi ge zhōumò dōu huì gěi fùmǔ dǎ diànhuà.","vn":"Dương Đồng Lạc rất quan tâm bố mẹ, bất kể ngày thường công việc bận đến đâu, cuối tuần nào anh ấy cũng gọi điện cho bố mẹ."},{"cn":"只要你努力了，无论你考多少分，你在我们眼里都是最优秀的。","pinyin":"Zhǐyào nǐ nǔlì le, wúlùn nǐ kǎo duōshao fēn, nǐ zài wǒmen yǎnlǐ dōu shì zuì yōuxiù de.","vn":"Chỉ cần con đã cố gắng, bất kể con thi được bao nhiêu điểm, trong mắt bố mẹ con vẫn luôn là người xuất sắc nhất."},{"cn":"无论你遇到什么困难，我都会在你身边。","pinyin":"Wúlùn nǐ yùdào shénme kùnnan, wǒ dōu huì zài nǐ shēnbiān.","vn":"Bất kể bạn gặp khó khăn gì, tôi đều sẽ luôn ở bên cạnh bạn."}]},{"title":"固定格式\"为了……而……\"","explanation_vn":"Cấu trúc cố định \"为了……而……\" (vì... mà...): phần \"为了……\" biểu thị mục đích hoặc mục tiêu, còn phần \"而……\" biểu thị hành động được thực hiện nhằm đạt được mục đích hoặc mục tiêu đó.","examples":[{"cn":"父母总是担心她为了节约时间而不好好吃饭。","pinyin":"Fùmǔ zǒngshì dānxīn tā wèile jiéyuē shíjiān ér bù hǎohāo chīfàn.","vn":"Bố mẹ luôn lo lắng cô ấy vì tiết kiệm thời gian mà không ăn uống đàng hoàng."},{"cn":"我们都在为了生活幸福而努力工作着。","pinyin":"Wǒmen dōu zài wèile shēnghuó xìngfú ér nǔlì gōngzuòzhe.","vn":"Tất cả chúng ta đều đang nỗ lực làm việc vì một cuộc sống hạnh phúc."},{"cn":"他们为了保护环境而拒绝使用纸杯。","pinyin":"Tāmen wèile bǎohù huánjìng ér jùjué shǐyòng zhǐbēi.","vn":"Họ từ chối sử dụng cốc giấy vì mục đích bảo vệ môi trường."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一飞","cn":"你觉得老妈穿这件毛衣怎么样？","pinyin":"Nǐ juéde lǎomā chuān zhè jiàn máoyī zěnmeyàng?"},{"speaker":"杨同乐","cn":"样子不错，就是颜色好像不怎么适合她。","pinyin":"Yàngzi búcuò, jiùshì yánsè hǎoxiàng bù zěnme shìhé tā."},{"speaker":"售货员","cn":"老年人穿这种颜色的衣服正合适，颜色不深，质量还特别好。您看那位阿姨正试着呢，是不是很好看？","pinyin":"Lǎoniánrén chuān zhè zhǒng yánsè de yīfu zhèng héshì, yánsè bù shēn, zhìliàng hái tèbié hǎo. Nín kàn nà wèi āyí zhèng shìzhe ne, shì bu shì hěn hǎokàn?"},{"speaker":"王一飞","cn":"嗯，是挺不错的。同乐，我印象中，老妈也常穿这种颜色的衣服，她应该会喜欢的，买一件吧。","pinyin":"Ng, shì tǐng búcuò de. Tónglè, wǒ yìnxiàng zhōng, lǎomā yě cháng chuān zhè zhǒng yánsè de yīfu, tā yīnggāi huì xǐhuan de, mǎi yí jiàn ba."},{"speaker":"杨同乐","cn":"好的，老妈高兴比什么都强。","pinyin":"Hǎo de, lǎomā gāoxìng bǐ shénme dōu qiáng."},{"speaker":"售货员","cn":"就是，老人开心最重要。我们店正好年底有活动，全场打七折呢，挺值的。","pinyin":"Jiùshì, lǎorén kāixīn zuì zhòngyào. Wǒmen diàn zhènghǎo niándǐ yǒu huódòng, quánchǎng dǎ qī zhé ne, tǐng zhí de."}],"translation_vn":"Vương Nhất Phi: Anh thấy mẹ mặc chiếc áo len này thế nào?\nDương Đồng Lạc: Kiểu dáng đẹp đấy, chỉ có điều màu sắc hình như không hợp với mẹ lắm.\nNhân viên bán hàng: Người lớn tuổi mặc quần áo màu này rất hợp ạ, màu không quá đậm, chất lượng lại cực kỳ tốt. Anh chị xem cô kia đang mặc thử đấy, trông rất đẹp đúng không ạ?\nVương Nhất Phi: Ừ, trông đẹp thật đấy. Đồng Lạc này, trong ấn tượng của em, mẹ cũng hay mặc quần áo màu này, chắc mẹ sẽ thích đấy, mua một chiếc đi anh.\nDương Đồng Lạc: Được thôi, mẹ vui là hơn tất cả mọi thứ.\nNhân viên bán hàng: Đúng đấy ạ, người già vui vẻ là quan trọng nhất. Cửa hàng em đúng dịp cuối năm có chương trình khuyến mãi, giảm giá 30% toàn bộ cửa hàng đấy ạ, rất đáng mua.","audio_dialogue":"12-1.mp3","audio_vocab":"12-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"刘明","cn":"爷爷、奶奶还没回来呢？","pinyin":"Yéye, nǎinai hái méi huílái ne?"},{"speaker":"王一雪","cn":"没呢，估计快了。下午老年班举办一期听力保护活动，他们去参加活动了。","pinyin":"Méi ne, gūjì kuài le. Xiàwǔ lǎoniánbān jǔbàn yì qī tīnglì bǎohù huódòng, tāmen qù cānjiā huódòng le."},{"speaker":"刘明","cn":"他们的活动还挺丰富的！","pinyin":"Tāmen de huódòng hái tǐng fēngfù de!"},{"speaker":"王一雪","cn":"嗯。小明最近要考试，心里有点儿烦，昨天因为脱、挂衣服这点儿小事，就对奶奶发脾气了。","pinyin":"Ng. Xiǎomíng zuìjìn yào kǎoshì, xīnlǐ yǒudiǎnr fán, zuótiān yīnwèi tuō, guà yīfu zhèdiǎnr xiǎoshì, jiù duì nǎinai fā píqi le."},{"speaker":"刘明","cn":"是吗？他这样做老人该伤心了。","pinyin":"Shì ma? Tā zhèyàng zuò lǎorén gāi shāngxīn le."},{"speaker":"王一雪","cn":"就是啊。他也不是不知道自己错了，我批评他以后，他马上说放学回来就向奶奶道歉。","pinyin":"Jiùshì a. Tā yě bú shì bù zhīdào zìjǐ cuò le, wǒ pīpíng tā yǐhòu, tā mǎshàng shuō fàngxué huílái jiù xiàng nǎinai dàoqiàn."},{"speaker":"刘明","cn":"好的，我也再跟他聊聊。","pinyin":"Hǎo de, wǒ yě zài gēn tā liáoliao."},{"speaker":"王一雪","cn":"那就更好了。","pinyin":"Nà jiù gèng hǎo le."}],"translation_vn":"Lưu Minh: Ông bà nội vẫn chưa về à?\nVương Nhất Tuyết: Chưa anh ạ, chắc sắp về rồi. Chiều nay lớp người cao tuổi tổ chức một buổi hoạt động bảo vệ thính lực, ông bà đi tham gia rồi.\nLưu Minh: Hoạt động của ông bà cũng phong phú phết nhỉ!\nVương Nhất Tuyết: Ừ. Tiểu Minh dạo này sắp thi, trong lòng hơi bực bội, hôm qua chỉ vì chút chuyện nhỏ cởi rồi treo quần áo mà đã nổi nóng với bà nội.\nLưu Minh: Thế à? Thằng bé làm vậy ông bà buồn lòng lắm đấy.\nVương Nhất Tuyết: Đúng thế. Thằng bé cũng không phải là không biết mình sai rồi, sau khi em phê bình, nó lập tức bảo tan học về sẽ xin lỗi bà nội ngay.\nLưu Minh: Được rồi, để anh cũng nói chuyện thêm với nó.\nVương Nhất Tuyết: Thế thì càng tốt.","audio_dialogue":"12-3.mp3","audio_vocab":"12-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"杨同乐的老家在上海，他自毕业后一直在北京工作。虽然没和父母生活在一起，但父子、母子关系特别好。杨同乐很关心父母，无论平时工作有多忙，他每个周末都会给父母打电话。条件允许时，他会回上海看父母。","pinyin":"Yáng Tónglè de lǎojiā zài Shànghǎi, tā zì bìyè hòu yìzhí zài Běijīng gōngzuò. Suīrán méi hé fùmǔ shēnghuó zài yìqǐ, dàn fùzǐ, mǔzǐ guānxi tèbié hǎo. Yáng Tónglè hěn guānxīn fùmǔ, wúlùn píngshí gōngzuò yǒu duō máng, tā měi ge zhōumò dōu huì gěi fùmǔ dǎ diànhuà. Tiáojiàn yǔnxǔ shí, tā huì huí Shànghǎi kàn fùmǔ."},{"speaker":"","cn":"刘明和王一雪结婚后，一直没有和父母生活在一起，他们平时会另外找时间去看父母，帮父母做饭，打扫打扫卫生。这两年，刘明的母亲身体不太好，他们很担心，就把父母接到了自己家里照顾。父母待在他们身边，他们也终于能放心地去工作了。","pinyin":"Liú Míng hé Wáng Yīxuě jiéhūn hòu, yìzhí méiyǒu hé fùmǔ shēnghuó zài yìqǐ, tāmen píngshí huì lìngwài zhǎo shíjiān qù kàn fùmǔ, bāng fùmǔ zuòfàn, dǎsǎo dǎsǎo wèishēng. Zhè liǎng nián, Liú Míng de mǔqīn shēntǐ bú tài hǎo, tāmen hěn dānxīn, jiù bǎ fùmǔ jiēdàole zìjǐ jiālǐ zhàogù. Fùmǔ dāi zài tāmen shēnbiān, tāmen yě zhōngyú néng fàngxīn de qù gōngzuò le."}],"translation_vn":"Quê của Dương Đồng Lạc ở Thượng Hải, từ sau khi tốt nghiệp anh luôn làm việc ở Bắc Kinh. Tuy không sống cùng bố mẹ nhưng tình cảm cha con, mẹ con đặc biệt tốt đẹp. Dương Đồng Lạc rất quan tâm đến bố mẹ, bất kể ngày thường công việc có bận rộn đến đâu, cuối tuần nào anh cũng gọi điện cho bố mẹ. Khi điều kiện cho phép, anh sẽ về Thượng Hải thăm bố mẹ.\nSau khi kết hôn, Lưu Minh và Vương Nhất Tuyết vẫn luôn không sống chung với bố mẹ, ngày thường họ sẽ sắp xếp thời gian riêng đến thăm bố mẹ, giúp bố mẹ nấu cơm, dọn dẹp vệ sinh. Hai năm nay sức khỏe mẹ của Lưu Minh không được tốt lắm, họ rất lo lắng nên đã đón bố mẹ về nhà mình chăm sóc. Có bố mẹ ở bên cạnh, họ cuối cùng cũng có thể yên tâm đi làm.","audio_dialogue":"12-5.mp3","audio_vocab":"12-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"下班回家，林静静将父母从老家寄来的鸡汤热了热，当闻到从小就熟悉的味道时，平时冷静的她鼻子还是酸了。","pinyin":"Xiàbān huí jiā, Lín Jìngjìng jiāng fùmǔ cóng lǎojiā jìlái de jītāng rè le rè, dāng wéndào cóngxiǎo jiù shúxī de wèidào shí, píngshí lěngjìng de tā bízi háishì suān le."},{"speaker":"","cn":"林静静一个人来北京工作三年了，父母总是担心她为了节约时间而不好好吃饭，所以每个月都给她寄各种好吃的。这次母亲专门做了林静静最爱喝的鸡汤，为了让食物新鲜，父亲选择了城里最快的快递，上午寄出，下午就能收到。","pinyin":"Lín Jìngjìng yí ge rén lái Běijīng gōngzuò sān nián le, fùmǔ zǒngshì dānxīn tā wèile jiéyuē shíjiān ér bù hǎohāo chīfàn, suǒyǐ měi ge yuè dōu gěi tā jì gèzhǒng hǎochī de. Zhè cì mǔqīn zhuānmén zuòle Lín Jìngjìng zuì ài hē de jītāng, wèile ràng shíwù xīnxiān, fùqīn xuǎnzéle chénglǐ zuì kuài de kuàidì, shàngwǔ jìchū, xiàwǔ jiù néng shōudào."},{"speaker":"","cn":"鸡汤很鲜，林静静心里更暖，她觉得父母好像就在身边。都说“儿行千里母担忧”，父母总对她说：“遇到困难别害怕，要勇敢面对，任何时候都可以和父母商量。”尽管在大城市生活压力有些大，但每当想到父母的这些话，尝到来自老家熟悉的味道，她就觉得又能笑着面对生活了。","pinyin":"Jītāng hěn xiān, Lín Jìngjìng xīnlǐ gèng nuǎn, tā juéde fùmǔ hǎoxiàng jiù zài shēnbiān. Dōu shuō \"ér xíng qiānlǐ mǔ dānyōu\", fùmǔ zǒng duì tā shuō: \"Yùdào kùnnan bié hàipà, yào yǒnggǎn miànduì, rènhé shíhou dōu kěyǐ hé fùmǔ shāngliang.\" Jǐnguǎn zài dà chéngshì shēnghuó yālì yǒuxiē dà, dàn měidāng xiǎngdào fùmǔ de zhèxiē huà, chángdào láizì lǎojiā shúxī de wèidào, tā jiù juéde yòu néng xiàozhe miànduì shēnghuó le."}],"translation_vn":"Tan làm về nhà, Lâm Tĩnh Tĩnh hâm nóng bát canh gà bố mẹ gửi từ quê lên. Khi ngửi thấy mùi vị quen thuộc từ thuở nhỏ ấy, cô gái vốn bình tĩnh ngày thường vẫn không khỏi cay sống mũi.\nLâm Tĩnh Tĩnh một mình đến Bắc Kinh làm việc đã ba năm rồi. Bố mẹ luôn lo lắng cô vì tiết kiệm thời gian mà không ăn uống đàng hoàng, nên tháng nào cũng gửi cho cô đủ thứ đồ ăn ngon. Lần này mẹ nấu riêng món canh gà mà Lâm Tĩnh Tĩnh thích uống nhất, để thức ăn được tươi ngon, bố đã chọn dịch vụ chuyển phát nhanh nhất trong thành phố, sáng gửi đi là chiều đã nhận được.\nCanh gà rất ngọt, lòng Lâm Tĩnh Tĩnh lại càng ấm áp hơn, cô cảm thấy như bố mẹ đang ở ngay bên cạnh mình vậy. Người ta thường nói \"con đi ngàn dặm mẹ lo âu\", bố mẹ luôn dặn cô: \"Gặp khó khăn đừng sợ hãi, hãy dũng cảm đối mặt, bất cứ lúc nào cũng có thể bàn bạc với bố mẹ.\" Mặc dù áp lực cuộc sống ở thành phố lớn có hơi nặng nề, nhưng mỗi khi nhớ đến những lời nói ấy của bố mẹ và nếm trải hương vị quen thuộc từ quê nhà, cô lại thấy mình có thể mỉm cười đối diện với cuộc sống.","audio_dialogue":"12-7.mp3","audio_vocab":"12-8.mp3"}]},{"id":13,"title_cn":"美好的日子","title_pinyin":"Měihǎo de rìzi","title_vn":"Những ngày tháng tươi đẹp","goals":["Có thể nghe hiểu và trao đổi các chủ đề về đời sống ngày lễ.","Có thể trình bày bằng lời hoặc bằng văn bản về đặc điểm ngày lễ, các hoạt động trong ngày lễ,...","Hiểu được nội hàm văn hóa đằng sau việc người Trung Quốc đặc biệt coi trọng các ngày lễ truyền thống."],"vocab":[{"hanzi":"熊","pinyin":"xióng","pos":"dt.","vn":"gấu, con gấu","examples":[{"cn":"动物园里有一只很大的棕熊。","pinyin":"Dòngwùyuán lǐ yǒu yì zhī hěn dà de zōngxióng.","vn":"Trong sở thú có một con gấu nâu rất lớn."},{"cn":"妹妹最喜欢的玩具是一只小熊。","pinyin":"Mèimei zuì xǐhuan de wánjù shì yì zhī xiǎoxióng.","vn":"Món đồ chơi em gái thích nhất là một chú gấu nhỏ."},{"cn":"去森林里徒步时，要小心别遇到熊。","pinyin":"Qù sēnlín lǐ túbù shí, yào xiǎoxīn bié yùdào xióng.","vn":"Khi đi bộ đường dài trong rừng, phải cẩn thận kẻo gặp gấu."}]},{"hanzi":"老虎","pinyin":"lǎohǔ","pos":"dt.","vn":"hổ, con hổ","examples":[{"cn":"老虎看起来非常威风，也很凶猛。","pinyin":"Lǎohǔ kàn qǐlai fēicháng wēifēng, yě hěn xiōngměng.","vn":"Hổ trông vô cùng oai phong và cũng rất hung dữ."},{"cn":"小明在动物园第一次看到了真正的老虎。","pinyin":"Xiǎomíng zài dòngwùyuán dì yī cì kàndào le zhēnzhèng de lǎohǔ.","vn":"Tiểu Minh lần đầu tiên nhìn thấy con hổ thật ở sở thú."},{"cn":"为了保护野生老虎，国家建立了很多自然保护区。","pinyin":"Wèile bǎohù yěshēng lǎohǔ, guójiā jiànlì le hěn duō zìrán bǎohùqū.","vn":"Để bảo vệ hổ hoang dã, nhà nước đã thành lập rất nhiều khu bảo tồn thiên nhiên."}]},{"hanzi":"喊","pinyin":"hǎn","pos":"dgt.","vn":"hét, la hét, gọi to","examples":[{"cn":"图书馆里请保持安静，不要大声喊。","pinyin":"Túshūguǎn lǐ qǐng bǎochí ānjìng, búyào dàshēng hǎn.","vn":"Trong thư viện xin hãy giữ yên lặng, đừng la hét lớn tiếng."},{"cn":"我刚才喊了你几遍，你戴着耳机没听见。","pinyin":"Wǒ gāngcái hǎn le nǐ jǐ biàn, nǐ dàizhe ěrjī méi tīngjiàn.","vn":"Vừa nãy mình gọi cậu mấy lần rồi, cậu đeo tai nghe nên không nghe thấy."},{"cn":"看到比赛赢了，观众们都激动地喊了起来。","pinyin":"Kàndào bǐsài yíng le, guānzhòngmen dōu jīdòng de hǎn le qǐlai.","vn":"Thấy trận đấu thắng rồi, khán giả đều xúc động hò reo lên."}]},{"hanzi":"级","pinyin":"jí","pos":"lượng.","vn":"cấp, bậc, hạng (lượng từ dùng cho cấp bậc, thứ hạng...)","examples":[{"cn":"大熊猫是国家一级保护动物。","pinyin":"Dàxióngmāo shì guójiā yī jí bǎohù dòngwù.","vn":"Gấu trúc lớn là động vật được bảo vệ cấp quốc gia hạng nhất."},{"cn":"他去年顺利通过了HSK四级考试。","pinyin":"Tā qùnián shùnlì tōngguò le HSK sì jí kǎoshì.","vn":"Năm ngoái anh ấy đã vượt qua kỳ thi HSK cấp 4 một cách suôn sẻ."},{"cn":"这家酒店的服务达到了五星级标准。","pinyin":"Zhè jiā jiǔdiàn de fúwù dádào le wǔxīngjí biāozhǔn.","vn":"Dịch vụ của khách sạn này đã đạt tiêu chuẩn năm sao."}]},{"hanzi":"树林","pinyin":"shùlín","pos":"dt.","vn":"rừng cây, khu rừng nhỏ","examples":[{"cn":"公园后面有一片安静的小树林。","pinyin":"Gōngyuán hòumiàn yǒu yí piàn ānjìng de xiǎo shùlín.","vn":"Phía sau công viên có một khu rừng cây nhỏ yên tĩnh."},{"cn":"夏天在树林里散步，感觉特别凉快。","pinyin":"Xiàtiān zài shùlín lǐ sànbù, gǎnjué tèbié liángkuai.","vn":"Mùa hè đi dạo trong rừng cây cảm thấy đặc biệt mát mẻ."},{"cn":"早晨的树林里有很多小鸟在唱歌。","pinyin":"Zǎochén de shùlín lǐ yǒu hěn duō xiǎoniǎo zài chànggē.","vn":"Trong khu rừng buổi sáng có rất nhiều chú chim nhỏ đang hót."}]},{"hanzi":"景区","pinyin":"jǐngqū","pos":"dt.","vn":"khu thắng cảnh, khu du lịch","examples":[{"cn":"这个景区的风景非常美，每年都吸引很多游客。","pinyin":"Zhège jǐngqū de fēngjǐng fēicháng měi, měi nián dōu xīyǐn hěn duō yóukè.","vn":"Phong cảnh của khu thắng cảnh này vô cùng đẹp, mỗi năm đều thu hút rất nhiều du khách."},{"cn":"放假的时候，热门景区的门票需要提前在网上预订。","pinyin":"Fàngjià de shíhou, rèmén jǐngqū de ménpiào xūyào tíqián zài wǎngshang yùdìng.","vn":"Vào kỳ nghỉ, vé vào cửa các khu du lịch nổi tiếng cần đặt trước trên mạng."},{"cn":"景区里有免费的观光车，坐车游览很方便。","pinyin":"Jǐngqū lǐ yǒu miǎnfèi de guānguāngchē, zuòchē yóulǎn hěn fāngbiàn.","vn":"Trong khu thắng cảnh có xe tham quan miễn phí, ngồi xe đi ngắm cảnh rất tiện."}]},{"hanzi":"区","pinyin":"qū","pos":"dt.","vn":"khu, khu vực, quận","examples":[{"cn":"我们的学校位于市中心的文化区。","pinyin":"Wǒmen de xuéxiào wèiyú shìzhōngxīn de wénhuàqū.","vn":"Trường của chúng tôi nằm ở khu văn hóa tại trung tâm thành phố."},{"cn":"这里是休息区，大家可以坐下来喝点水。","pinyin":"Zhèlǐ shì xiūxīqū, dàjiā kěyǐ zuò xiàlai hē diǎn shuǐ.","vn":"Đây là khu vực nghỉ ngơi, mọi người có thể ngồi xuống uống chút nước."},{"cn":"这个城市分为六个不同的行政区。","pinyin":"Zhège chéngshì fēnwéi liù ge bùtóng de xíngzhèngqū.","vn":"Thành phố này được chia thành sáu quận hành chính khác nhau."}]},{"hanzi":"美","pinyin":"měi","pos":"tt.","vn":"đẹp, tươi đẹp","examples":[{"cn":"秋天的香山红叶满山，真是太美了！","pinyin":"Qiūtiān de Xiāngshān hóngyè mǎnshān, zhēn shì tài měi le!","vn":"Hương Sơn mùa thu lá đỏ phủ kín núi, thật sự quá đẹp!"},{"cn":"这首音乐的旋律非常美，让人听了很放松。","pinyin":"Zhè shǒu yīnyuè de xuánlǜ fēicháng měi, ràng rén tīng le hěn fàngsōng.","vn":"Giai điệu của bản nhạc này rất đẹp, khiến người nghe cảm thấy rất thư giãn."},{"cn":"生活中不缺少美，而是缺少发现美的眼睛。","pinyin":"Shēnghuó zhōng bù quēshǎo měi, ér shì quēshǎo fāxiàn měi de yǎnjing.","vn":"Trong cuộc sống không thiếu cái đẹp, mà chỉ thiếu đôi mắt biết phát hiện ra cái đẹp."}]},{"hanzi":"节假日","pinyin":"jiéjiàrì","pos":"dt.","vn":"ngày lễ, ngày nghỉ lễ","examples":[{"cn":"每到节假日，火车站和机场总是人山人海。","pinyin":"Měi dào jiéjiàrì, huǒchēzhàn hé jīchǎng zǒngshì rénshānrénhǎi.","vn":"Mỗi dịp lễ tết, ga tàu hỏa và sân bay lúc nào cũng đông nghịt người."},{"cn":"节假日的时候，我喜欢和家人一起去郊外玩儿。","pinyin":"Jiéjiàrì de shíhou, wǒ xǐhuan hé jiārén yìqǐ qù jiāowài wánr.","vn":"Vào ngày nghỉ lễ, tôi thích cùng gia đình đi ngoại ô chơi."},{"cn":"这家商场在节假日经常推出打折活动。","pinyin":"Zhè jiā shāngchǎng zài jiéjiàrì jīngcháng tuīchū dǎzhé huódòng.","vn":"Trung tâm thương mại này vào các ngày lễ thường tung ra chương trình giảm giá."}]},{"hanzi":"千万","pinyin":"qiānwàn","pos":"phó.","vn":"nhất định, ngàn vạn lần (thường dùng trong câu cầu khiến, khuyên bảo)","examples":[{"cn":"明天的面试非常重要，你千万别迟到。","pinyin":"Míngtiān de miànshì fēicháng zhòngyào, nǐ qiānwàn bié chídào.","vn":"Buổi phỏng vấn ngày mai vô cùng quan trọng, cậu nhất định đừng đến muộn đấy."},{"cn":"外边下雨路滑，开车的时候千万要小心。","pinyin":"Wàibian xiàyǔ lù huá, kāichē de shíhou qiānwàn yào xiǎoxīn.","vn":"Ngoài trời mưa đường trơn, khi lái xe nhất định phải cẩn thận."},{"cn":"出门前千万记得把护照和机票带好。","pinyin":"Chūmén qián qiānwàn jìde bǎ hùzhào hé jīpiào dài hǎo.","vn":"Trước khi ra khỏi nhà nhất định phải nhớ mang theo hộ chiếu và vé máy bay."}]},{"hanzi":"开玩笑","pinyin":"kāi wánxiào","pos":"","vn":"nói đùa, đùa giỡn","examples":[{"cn":"别生气，我刚才只是跟你开玩笑呢。","pinyin":"Bié shēngqì, wǒ gāngcái zhǐshì gēn nǐ kāi wánxiào ne.","vn":"Đừng giận, vừa nãy mình chỉ nói đùa với cậu thôi mà."},{"cn":"他平时很幽默，特别喜欢和朋友开玩笑。","pinyin":"Tā píngshí hěn yōumò, tèbié xǐhuan hé péngyou kāi wánxiào.","vn":"Bình thường anh ấy rất hài hước, đặc biệt thích đùa giỡn với bạn bè."},{"cn":"这件事关系到大家的安全，可不是开玩笑的。","pinyin":"Zhè jiàn shì guānxì dào dàjiā de ānquán, kě bú shì kāi wánxiào de.","vn":"Chuyện này liên quan đến sự an toàn của mọi người, hoàn toàn không phải chuyện đùa đâu."}]},{"hanzi":"东北虎","pinyin":"Dōngběihǔ","pos":"danh từ riêng","vn":"hổ Đông Bắc (hổ Siberia)","examples":[{"cn":"东北虎是世界上体型最大的猫科动物之一。","pinyin":"Dōngběihǔ shì shìjiè shang tǐxíng zuì dà de māokē dòngwù zhī yī.","vn":"Hổ Đông Bắc là một trong những loài động vật họ mèo có kích thước lớn nhất thế giới."},{"cn":"我们在哈尔滨的虎林园看到了很多东北虎。","pinyin":"Wǒmen zài Hā'ěrbīn de Hǔlínyuán kàndào le hěn duō Dōngběihǔ.","vn":"Chúng tôi đã nhìn thấy rất nhiều hổ Đông Bắc ở Công viên Hổ Cáp Nhĩ Tân."},{"cn":"东北虎主要生活在中国东北的森林里。","pinyin":"Dōngběihǔ zhǔyào shēnghuó zài Zhōngguó Dōngběi de sēnlín lǐ.","vn":"Hổ Đông Bắc chủ yếu sinh sống trong các khu rừng ở vùng Đông Bắc Trung Quốc."}]},{"hanzi":"北京野生动物园","pinyin":"Běijīng Yěshēng Dòngwùyuán","pos":"danh từ riêng","vn":"Công viên Động vật hoang dã Bắc Kinh","examples":[{"cn":"周末父母带我去北京野生动物园玩了一天。","pinyin":"Zhōumò fùmǔ dài wǒ qù Běijīng Yěshēng Dòngwùyuán wán le yì tiān.","vn":"Cuối tuần bố mẹ đưa tôi đến Công viên Động vật hoang dã Bắc Kinh chơi một ngày."},{"cn":"在北京野生动物园，游客可以坐车近距离观看动物。","pinyin":"Zài Běijīng Yěshēng Dòngwùyuán, yóukè kěyǐ zuòchē jìnjùlí guānkàn dòngwù.","vn":"Ở Công viên Động vật hoang dã Bắc Kinh, du khách có thể ngồi xe ngắm động vật ở cự ly gần."},{"cn":"北京野生动物园位于北京市大兴区，面积非常大。","pinyin":"Běijīng Yěshēng Dòngwùyuán wèiyú Běijīng Shì Dàxīng Qū, miànjī fēicháng dà.","vn":"Công viên Động vật hoang dã Bắc Kinh nằm ở quận Đại Hưng, thành phố Bắc Kinh, diện tích vô cùng rộng lớn."}]},{"hanzi":"月饼","pinyin":"yuèbing","pos":"dt.","vn":"bánh trung thu","examples":[{"cn":"中秋节晚上，一家人一边赏月，一边吃月饼。","pinyin":"Zhōngqiūjié wǎnshang, yìjiārén yìbiān shǎngyuè, yìbiān chī yuèbing.","vn":"Buổi tối Tết Trung Thu, cả nhà vừa ngắm trăng vừa ăn bánh trung thu."},{"cn":"现在超市里卖的月饼口味越来越多。","pinyin":"Xiànzài chāoshì lǐ mài de yuèbing kǒuwèi yuè lái yuè duō.","vn":"Hiện nay bánh trung thu bán trong siêu thị ngày càng có nhiều hương vị."},{"cn":"我买了两盒月饼，打算送给国内的朋友。","pinyin":"Wǒ mǎi le liǎng hé yuèbing, dǎsuàn sòng gěi guónèi de péngyou.","vn":"Tôi đã mua hai hộp bánh trung thu, định tặng cho bạn bè ở trong nước."}]},{"hanzi":"葡萄","pinyin":"pútao","pos":"dt.","vn":"nho, quả nho","examples":[{"cn":"这种新疆葡萄又大又甜，非常好吃。","pinyin":"Zhè zhǒng Xīnjiāng pútao yòu dà yòu tián, fēicháng hǎochī.","vn":"Loại nho Tân Cương này vừa to vừa ngọt, ăn rất ngon."},{"cn":"妈妈刚洗了一盘新鲜的葡萄，大家快来吃吧。","pinyin":"Māma gāng xǐ le yì pán xīnxiān de pútao, dàjiā kuài lái chī ba.","vn":"Mẹ vừa rửa một đĩa nho tươi, mọi người mau lại ăn đi."},{"cn":"秋天正是吃葡萄的好季节。","pinyin":"Qiūtiān zhèng shì chī pútao de hǎo jìjié.","vn":"Mùa thu đúng là mùa đẹp để ăn nho."}]},{"hanzi":"香","pinyin":"xiāng","pos":"tt.","vn":"thơm, thơm ngon","examples":[{"cn":"刚泡好的绿茶闻起来特别香。","pinyin":"Gāng pàohǎo de lǜchá wén qǐlai tèbié xiāng.","vn":"Trà xanh vừa pha xong ngửi đặc biệt thơm."},{"cn":"厨房里飘来一阵烤鸭的香味，真香啊！","pinyin":"Chúfáng lǐ piāo lái yí zhèn kǎoyā de xiāngwèi, zhēn xiāng a!","vn":"Từ trong bếp bay ra một làn hương vịt quay, thơm quá đi mất!"},{"cn":"他今天太累了，躺在床上很快就睡得很香。","pinyin":"Tā jīntiān tài lèi le, tǎng zài chuáng shang hěn kuài jiù shuì de hěn xiāng.","vn":"Hôm nay anh ấy mệt quá rồi, nằm lên giường một lát đã ngủ rất ngon lành."}]},{"hanzi":"街道","pinyin":"jiēdào","pos":"dt.","vn":"đường phố, phố xá","examples":[{"cn":"下过雨后，城市的街道显得格外干净。","pinyin":"Xiàguo yǔ hòu, chéngshì de jiēdào xiǎnde géwài gānjìng.","vn":"Sau cơn mưa, đường phố của thành phố trông sạch sẽ lạ thường."},{"cn":"过节的时候，街道两旁都挂满了红灯笼。","pinyin":"Guòjié de shíhou, jiēdào liǎngpáng dōu guàmǎn le hóng dēnglong.","vn":"Vào dịp lễ tết, hai bên đường phố đều treo đầy đèn lồng đỏ."},{"cn":"这条古老的街道上保留着许多传统建筑。","pinyin":"Zhè tiáo gǔlǎo de jiēdào shang bǎoliú zhe xǔduō chuántǒng jiànzhù.","vn":"Trên con phố cổ này vẫn lưu giữ nhiều công trình kiến trúc truyền thống."}]},{"hanzi":"剧院","pinyin":"jùyuàn","pos":"dt.","vn":"nhà hát, rạp hát","examples":[{"cn":"周末我打算和朋友去国家大剧院看一场音乐会。","pinyin":"Zhōumò wǒ dǎsuàn hé péngyou qù Guójiā Dàjùyuàn kàn yì chǎng yīnyuèhuì.","vn":"Cuối tuần tôi định cùng bạn đi Nhà hát Lớn Quốc gia xem một buổi hòa nhạc."},{"cn":"这座新落成的剧院可以容纳两千多名观众。","pinyin":"Zhè zuò xīn luòchéng de jùyuàn kěyǐ róngnà liǎngqiān duō míng guānzhòng.","vn":"Nhà hát mới khánh thành này có thể chứa hơn hai nghìn khán giả."},{"cn":"咱们晚上七点在剧院门口集合吧。","pinyin":"Zánmen wǎnshang qī diǎn zài jùyuàn ménkǒu jíhé ba.","vn":"Tối nay bảy giờ chúng mình tập trung ở cổng nhà hát nhé."}]},{"hanzi":"演出","pinyin":"yǎnchū","pos":"dgt.","vn":"biểu diễn, trình diễn","examples":[{"cn":"今晚的京剧演出非常精彩，观众们一直鼓掌。","pinyin":"Jīnwǎn de Jīngjù yǎnchū fēicháng jīngcǎi, guānzhòngmen yìzhí gǔzhǎng.","vn":"Buổi biểu diễn Kinh kịch tối nay vô cùng đặc sắc, khán giả vỗ tay không ngớt."},{"cn":"这个乐队下个月将在北京演出三场。","pinyin":"Zhège yuèduì xià ge yuè jiāng zài Běijīng yǎnchū sān chǎng.","vn":"Ban nhạc này tháng sau sẽ biểu diễn ba buổi ở Bắc Kinh."},{"cn":"为了这次学校晚会的演出，同学们排练了很久。","pinyin":"Wèile zhè cì xuéxiào wǎnhuì de yǎnchū, tóngxuémen páiliàn le hěn jiǔ.","vn":"Để chuẩn bị cho buổi biểu diễn dạ hội của trường lần này, các bạn học đã tập luyện rất lâu."}]},{"hanzi":"赶","pinyin":"gǎn","pos":"dgt.","vn":"gặp đúng lúc, trùng vào; đuổi kịp, vội đi","examples":[{"cn":"今年的国庆节和中秋节赶在了一起。","pinyin":"Jīnnián de Guóqìngjié hé Zhōngqiūjié gǎn zài le yìqǐ.","vn":"Ngày Quốc khánh và Tết Trung Thu năm nay trùng vào nhau."},{"cn":"我得快点走了，还要去机场赶九点的飞机。","pinyin":"Wǒ děi kuàidiǎn zǒu le, hái yào qù jīchǎng gǎn jiǔ diǎn de fēijī.","vn":"Tôi phải đi nhanh thôi, còn phải ra sân bay bắt chuyến bay lúc chín giờ."},{"cn":"真不巧，我们去旅游那天正好赶上下大雨。","pinyin":"Zhēn bùqiǎo, wǒmen qù lǚyóu nà tiān zhènghǎo gǎnshang xià dàyǔ.","vn":"Thật không may, hôm chúng tôi đi du lịch đúng lúc gặp trận mưa to."}]},{"hanzi":"巧","pinyin":"qiǎo","pos":"tt.","vn":"trùng hợp, khéo, đúng lúc","examples":[{"cn":"真巧啊，没想到会在这家书店遇到你！","pinyin":"Zhēn qiǎo a, méi xiǎngdào huì zài zhè jiā shūdiàn yùdào nǐ!","vn":"Trùng hợp thật đấy, không ngờ lại gặp cậu ở hiệu sách này!"},{"cn":"你来得真巧，我刚做好晚饭，一起吃吧。","pinyin":"Nǐ lái de zhēn qiǎo, wǒ gāng zuòhǎo wǎnfàn, yìqǐ chī ba.","vn":"Cậu đến thật đúng lúc, mình vừa nấu xong cơm tối, ăn cùng nhé."},{"cn":"太巧了，我们俩竟然是同一天生日。","pinyin":"Tài qiǎo le, wǒmen liǎ jìngrán shì tóng yì tiān shēngrì.","vn":"Trùng hợp quá, hai đứa mình lại có cùng ngày sinh nhật."}]},{"hanzi":"中秋节","pinyin":"Zhōngqiūjié","pos":"danh từ riêng","vn":"Tết Trung Thu","examples":[{"cn":"农历八月十五是中国的传统节日——中秋节。","pinyin":"Nónglì bāyuè shíwǔ shì Zhōngguó de chuántǒng jiérì — Zhōngqiūjié.","vn":"Ngày rằm tháng Tám âm lịch là ngày lễ truyền thống của Trung Quốc — Tết Trung Thu."},{"cn":"中秋节象征着家人团圆，所以人们都想回家过节。","pinyin":"Zhōngqiūjié xiàngzhēng zhe jiārén tuányuán, suǒyǐ rénmen dōu xiǎng huíjiā guòjié.","vn":"Tết Trung Thu tượng trưng cho sự đoàn viên gia đình, vì vậy mọi người đều muốn về nhà đón lễ."},{"cn":"今年中秋节你打算怎么过？","pinyin":"Jīnnián Zhōngqiūjié nǐ dǎsuàn zěnme guò?","vn":"Tết Trung Thu năm nay bạn định đón như thế nào?"}]},{"hanzi":"加拿大","pinyin":"Jiānádà","pos":"danh từ riêng","vn":"Canada","examples":[{"cn":"安妮来自加拿大，她非常喜欢中国文化。","pinyin":"Ānnī láizì Jiānádà, tā fēicháng xǐhuan Zhōngguó wénhuà.","vn":"Annie đến từ Canada, cô ấy vô cùng yêu thích văn hóa Trung Quốc."},{"cn":"加拿大的冬天很冷，经常下大雪。","pinyin":"Jiānádà de dōngtiān hěn lěng, jīngcháng xià dàxuě.","vn":"Mùa đông ở Canada rất lạnh, thường xuyên có tuyết rơi dày."},{"cn":"我表哥去年去了加拿大读研究生。","pinyin":"Wǒ biǎogē qùnián qù le Jiānádà dú yánjiūshēng.","vn":"Anh họ tôi năm ngoái đã sang Canada học cao học."}]},{"hanzi":"之中","pinyin":"zhīzhōng","pos":"dt.","vn":"trong số, ở giữa, trong","examples":[{"cn":"在这些候选人之中，他的工作经验最丰富。","pinyin":"Zài zhèxiē hòuxuǎnrén zhīzhōng, tā de gōngzuò jīngyàn zuì fēngfù.","vn":"Trong số những ứng viên này, kinh nghiệm làm việc của anh ấy phong phú nhất."},{"cn":"有家人的关心和陪伴，她每天都生活在幸福之中。","pinyin":"Yǒu jiārén de guānxīn hé péibàn, tā měitiān dōu shēnghuó zài xìngfú zhīzhōng.","vn":"Có sự quan tâm và đồng hành của gia đình, mỗi ngày cô ấy đều sống trong hạnh phúc."},{"cn":"目前这项计划还在讨论之中，还没有最终决定。","pinyin":"Mùqián zhè xiàng jìhuà hái zài tǎolùn zhīzhōng, hái méiyǒu zuìzhōng juédìng.","vn":"Hiện tại kế hoạch này vẫn đang trong quá trình thảo luận, vẫn chưa có quyết định cuối cùng."}]},{"hanzi":"铁路","pinyin":"tiělù","pos":"dt.","vn":"đường sắt","examples":[{"cn":"这几年中国的高速铁路发展得非常快。","pinyin":"Zhè jǐ nián Zhōngguó de gāosù tiělù fāzhǎn de fēicháng kuài.","vn":"Mấy năm nay đường sắt cao tốc của Trung Quốc phát triển vô cùng nhanh chóng."},{"cn":"这条新修的铁路把两个重要城市连接了起来。","pinyin":"Zhè tiáo xīn xiū de tiělù bǎ liǎng ge zhòngyào chéngshì liánjiē le qǐlai.","vn":"Tuyến đường sắt mới xây này đã kết nối hai thành phố quan trọng lại với nhau."},{"cn":"我爸爸在铁路部门工作了二十多年。","pinyin":"Wǒ bàba zài tiělù bùmén gōngzuò le èrshí duō nián.","vn":"Bố tôi đã làm việc trong ngành đường sắt hơn hai mươi năm."}]},{"hanzi":"人员","pinyin":"rényuán","pos":"dt.","vn":"nhân viên, cán bộ","examples":[{"cn":"如果遇到任何困难，可以随时联系现场工作人员。","pinyin":"Rúguǒ yùdào rènhé kùnnan, kěyǐ suíshí liánxì xiànchǎng gōngzuò rényuán.","vn":"Nếu gặp bất kỳ khó khăn nào, có thể liên hệ ngay với nhân viên làm việc tại hiện trường."},{"cn":"这家公司正在招聘有经验的技术人员。","pinyin":"Zhè jiā gōngsī zhèngzài zhāopìn yǒu jīngyàn de jìshù rényuán.","vn":"Công ty này đang tuyển dụng nhân viên kỹ thuật có kinh nghiệm."},{"cn":"所有参会人员请于上午九点前完成签到。","pinyin":"Suǒyǒu cānhuì rényuán qǐng yú shàngwǔ jiǔ diǎn qián wánchéng qiāndào.","vn":"Tất cả đại biểu tham dự hội nghị vui lòng hoàn tất điểm danh trước chín giờ sáng."}]},{"hanzi":"反向","pinyin":"fǎnxiàng","pos":"dgt.","vn":"ngược chiều, ngược hướng","examples":[{"cn":"今年春节，很多年轻人选择把父母接到城市里“反向团圆”。","pinyin":"Jīnnián Chūnjié, hěn duō niánqīngrén xuǎnzé bǎ fùmǔ jiēdào chéngshì lǐ “fǎnxiàng tuányuán”.","vn":"Tết năm nay, rất nhiều người trẻ chọn đón bố mẹ lên thành phố để \"đoàn viên ngược\"."},{"cn":"你坐反了，要到马路对面去坐反向的公交车。","pinyin":"Nǐ zuòfǎn le, yào dào mǎlù duìmiàn qù zuò fǎnxiàng de gōngjiāochē.","vn":"Bạn đi ngược chiều rồi, phải sang bên kia đường để bắt xe buýt chiều ngược lại."},{"cn":"节假日反向旅游既能避开人流，又能省下不少费用。","pinyin":"Jiéjiàrì fǎnxiàng lǚyóu jì néng bìkāi rénliú, yòu néng shěngxià bùshǎo fèiyong.","vn":"Du lịch ngược chiều vào ngày lễ vừa có thể tránh đám đông, vừa tiết kiệm được không ít chi phí."}]},{"hanzi":"团圆","pinyin":"tuányuán","pos":"dgt.","vn":"đoàn viên, sum họp","examples":[{"cn":"春节是一家人团圆的日子。","pinyin":"Chūnjié shì yìjiārén tuányuán de rìzi.","vn":"Tết Nguyên Đán là ngày cả gia đình đoàn viên."},{"cn":"不管离家多远，过年时他总会赶回来和父母团圆。","pinyin":"Bùguǎn líjiā duō yuǎn, guònián shí tā zǒng huì gǎn huílai hé fùmǔ tuányuán.","vn":"Dù xa nhà đến đâu, dịp Tết anh ấy luôn vội vã trở về sum họp cùng bố mẹ."},{"cn":"祝你们全家身体健康、幸福团圆！","pinyin":"Zhù nǐmen quánjiā shēntǐ jiànkāng, xìngfú tuányuán!","vn":"Chúc cả gia đình bạn sức khỏe dồi dào, hạnh phúc đoàn viên!"}]},{"hanzi":"左右","pinyin":"zuǒyòu","pos":"dt.","vn":"khoảng, độ, chừng (đứng sau số lượng hoặc thời gian)","examples":[{"cn":"我每天早上七点左右起床吃早饭。","pinyin":"Wǒ měitiān zǎoshang qī diǎn zuǒyòu qǐchuáng chī zǎofàn.","vn":"Mỗi sáng khoảng bảy giờ tôi thức dậy ăn sáng."},{"cn":"从这里坐地铁到机场大概要一个小时左右。","pinyin":"Cóng zhèlǐ zuò dìtiě dào jīchǎng dàgài yào yí ge xiǎoshí zuǒyòu.","vn":"Đi tàu điện ngầm từ đây đến sân bay mất khoảng chừng một tiếng."},{"cn":"这件外套看起来也就三百块左右。","pinyin":"Zhè jiàn wàitào kàn qǐlai yě jiù sānbǎi kuài zuǒyòu.","vn":"Chiếc áo khoác này trông cũng chỉ khoảng ba trăm tệ thôi."}]},{"hanzi":"大约","pinyin":"dàyuē","pos":"phó.","vn":"khoảng, đại khái, chừng","examples":[{"cn":"昨天路上堵车，我大约晚上九点才回到家。","pinyin":"Zuótiān lùshang dǔchē, wǒ dàyuē wǎnshang jiǔ diǎn cái huídào jiā.","vn":"Hôm qua trên đường tắc xe, khoảng chín giờ tối tôi mới về đến nhà."},{"cn":"参加这次马拉松比赛的选手大约有五千人。","pinyin":"Cānjiā zhè cì mǎlāsōng bǐsài de xuǎnshǒu dàyuē yǒu wǔqiān rén.","vn":"Vận động viên tham gia giải marathon lần này có khoảng năm nghìn người."},{"cn":"从北京坐高铁到上海大约需要四个半小时。","pinyin":"Cóng Běijīng zuò gāotiě dào Shànghǎi dàyuē xūyào sì ge bàn xiǎoshí.","vn":"Đi tàu cao tốc từ Bắc Kinh đến Thượng Hải cần khoảng bốn tiếng rưỡi."}]},{"hanzi":"烤","pinyin":"kǎo","pos":"dgt.","vn":"nướng, quay","examples":[{"cn":"周末我们几个朋友打算一起去吃烤肉。","pinyin":"Zhōumò wǒmen jǐ ge péngyou dǎsuàn yìqǐ qù chī kǎoròu.","vn":"Cuối tuần mấy đứa bạn chúng tôi định cùng nhau đi ăn thịt nướng."},{"cn":"姐姐周末在家烤了一个巧克力蛋糕。","pinyin":"Jiějie zhōumò zài jiā kǎo le yí ge qiǎokèlì dàngāo.","vn":"Cuối tuần chị gái ở nhà nướng một chiếc bánh kem sô-cô-la."},{"cn":"来北京旅游，一定要尝尝有名的北京烤鸭。","pinyin":"Lái Běijīng lǚyóu, yídìng yào chángchang yǒumíng de Běijīng kǎoyā.","vn":"Đến Bắc Kinh du lịch nhất định phải nếm thử món vịt quay Bắc Kinh nổi tiếng."}]},{"hanzi":"西红柿","pinyin":"xīhóngshì","pos":"dt.","vn":"cà chua","examples":[{"cn":"西红柿炒鸡蛋是我最拿手的一道家常菜。","pinyin":"Xīhóngshì chǎo jīdàn shì wǒ zuì náshǒu de yí dào jiāchángcài.","vn":"Trứng xào cà chua là món ăn gia đình sở trường nhất của tôi."},{"cn":"妈妈做了一碗热腾腾的西红柿鸡蛋汤。","pinyin":"Māma zuò le yì wǎn rèténgténg de xīhóngshì jīdàntāng.","vn":"Mẹ đã nấu một bát canh trứng cà chua nóng hổi."},{"cn":"超市里今天新进的西红柿又红又新鲜。","pinyin":"Chāoshì lǐ jīntiān xīnjìn de xīhóngshì yòu hóng yòu xīnxiān.","vn":"Cà chua mới nhập hôm nay ở siêu thị vừa đỏ vừa tươi."}]},{"hanzi":"出现","pinyin":"chūxiàn","pos":"dgt.","vn":"xuất hiện","examples":[{"cn":"雨停以后，天空中出现了一道美丽的彩虹。","pinyin":"Yǔ tíng yǐhòu, tiānkōng zhōng chūxiàn le yí dào měilì de cǎihóng.","vn":"Sau khi tạnh mưa, trên bầu trời xuất hiện một cầu vồng tuyệt đẹp."},{"cn":"如果电脑出现故障，请及时找技术人员修理。","pinyin":"Rúguǒ diànnǎo chūxiàn gùzhàng, qǐng jíshí zhǎo jìshù rényuán xiūlǐ.","vn":"Nếu máy tính xuất hiện sự cố, hãy kịp thời tìm nhân viên kỹ thuật sửa chữa."},{"cn":"看到妈妈终于出现在车站出口，孩子们开心极了。","pinyin":"Kàndào māma zhōngyú chūxiàn zài chēzhàn chūkǒu, háizimen kāixīn jí le.","vn":"Thấy mẹ cuối cùng cũng xuất hiện ở lối ra nhà ga, lũ trẻ vui sướng vô cùng."}]},{"hanzi":"作为","pinyin":"zuòwéi","pos":"giới./dgt.","vn":"với tư cách là, làm; coi như","examples":[{"cn":"作为一名学生，认真学习是最重要的任务。","pinyin":"Zuòwéi yì míng xuésheng, rènzhēn xuéxí shì zuì zhòngyào de rènwu.","vn":"Với tư cách là một học sinh, học tập chăm chỉ là nhiệm vụ quan trọng nhất."},{"cn":"他决定把这套茶具作为生日礼物送给爷爷。","pinyin":"Tā juédìng bǎ zhè tào chájù zuòwéi shēngrì lǐwù sòng gěi yéye.","vn":"Anh ấy quyết định lấy bộ ấm trà này làm quà sinh nhật tặng ông nội."},{"cn":"作为好朋友，我们一直互相关心、互相支持。","pinyin":"Zuòwéi hǎo péngyou, wǒmen yìzhí hùxiāng guānxīn, hùxiāng zhīchí.","vn":"Là bạn tốt, chúng tôi luôn quan tâm và ủng hộ lẫn nhau."}]},{"hanzi":"传统","pinyin":"chuántǒng","pos":"tt./dt.","vn":"truyền thống","examples":[{"cn":"春节是中国最重要的传统节日。","pinyin":"Chūnjié shì Zhōngguó zuì zhòngyào de chuántǒng jiérì.","vn":"Tết Nguyên Đán là ngày lễ truyền thống quan trọng nhất của Trung Quốc."},{"cn":"剪纸和书法都是中国的传统艺术。","pinyin":"Jiǎnzhǐ hé shūfǎ dōu shì Zhōngguó de chuántǒng yìshù.","vn":"Cắt giấy và thư pháp đều là nghệ thuật truyền thống của Trung Quốc."},{"cn":"我们要把尊老爱幼的优良传统传承下去。","pinyin":"Wǒmen yào bǎ zūnlǎo'àiyòu de yōuliáng chuántǒng chuánchéng xiàqù.","vn":"Chúng ta cần kế thừa truyền thống tốt đẹp kính già yêu trẻ."}]},{"hanzi":"有着","pinyin":"yǒuzhe","pos":"dgt.","vn":"có, mang","examples":[{"cn":"西安是一座有着三千多年历史的古老城市。","pinyin":"Xī'ān shì yí zuò yǒuzhe sānqiān duō nián lìshǐ de gǔlǎo chéngshì.","vn":"Tây An là một thành phố cổ có hơn ba nghìn năm lịch sử."},{"cn":"这件礼物对我来说有着非常特别的纪念意义。","pinyin":"Zhè jiàn lǐwù duì wǒ láishuō yǒuzhe fēicháng tèbié de jìniàn yìyì.","vn":"Món quà này đối với tôi có ý nghĩa kỷ niệm vô cùng đặc biệt."},{"cn":"他们俩性格很像，也有着共同的兴趣爱好。","pinyin":"Tāmen liǎ xìnggé hěn xiàng, yě yǒuzhe gòngtóng de xìngqù àihào.","vn":"Tính cách hai người họ rất giống nhau, cũng có chung sở thích."}]},{"hanzi":"意义","pinyin":"yìyì","pos":"dt.","vn":"ý nghĩa","examples":[{"cn":"参加这次志愿者活动非常有意义。","pinyin":"Cānjiā zhè cì zhìyuànzhě huódòng fēicháng yǒu yìyì.","vn":"Tham gia hoạt động tình nguyện lần này vô cùng có ý nghĩa."},{"cn":"这次交流对促进两国文化合作具有重要意义。","pinyin":"Zhè cì jiāoliú duì cùjìn liǎng guó wénhuà hézuò jùyǒu zhòngyào yìyì.","vn":"Chuyến giao lưu lần này có ý nghĩa quan trọng đối với việc thúc đẩy hợp tác văn hóa hai nước."},{"cn":"请你查一下词典，弄清楚这个词的具体意义。","pinyin":"Qǐng nǐ chá yíxià cídiǎn, nòng qīngchu zhège cí de jùtǐ yìyì.","vn":"Bạn hãy tra từ điển một chút, làm rõ ý nghĩa cụ thể của từ này."}]},{"hanzi":"到来","pinyin":"dàolái","pos":"dgt.","vn":"đến, tới (dịp lễ, mùa, thời điểm...)","examples":[{"cn":"随着春天的到来，公园里的花都开了。","pinyin":"Suízhe chūntiān de dàolái, gōngyuán lǐ de huā dōu kāi le.","vn":"Cùng với sự xuất hiện của mùa xuân, hoa trong công viên đều đã nở."},{"cn":"人们用热闹的烟花迎接新年的到来。","pinyin":"Rénmen yòng rènao de yānhuā yíngjiē xīnnián de dàolái.","vn":"Mọi người dùng pháo hoa rộn ràng để chào đón năm mới đến."},{"cn":"暑假快要到来了，你有什么旅行计划吗？","pinyin":"Shǔjià kuàiyào dàolái le, nǐ yǒu shénme lǚxíng jìhuà ma?","vn":"Kỳ nghỉ hè sắp tới rồi, bạn có kế hoạch du lịch gì không?"}]},{"hanzi":"美食","pinyin":"měishí","pos":"dt.","vn":"ẩm thực, món ăn ngon","examples":[{"cn":"成都是一座以美食闻名的城市。","pinyin":"Chéngdū shì yí zuò yǐ měishí wénmíng de chéngshì.","vn":"Thành Đô là một thành phố nổi tiếng về ẩm thực."},{"cn":"每次去外地旅游，我都要品尝当地的特色美食。","pinyin":"Měi cì qù wàidì lǚyóu, wǒ dōu yào pǐncháng dāngdì de tèsè měishí.","vn":"Mỗi lần đi du lịch nơi khác, tôi đều phải thưởng thức các món ngon đặc sản địa phương."},{"cn":"过节前，家家户户都会准备各种美食。","pinyin":"Guòjié qián, jiājiāhùhù dōu huì zhǔnbèi gèzhǒng měishí.","vn":"Trước ngày lễ, nhà nhà đều chuẩn bị đủ loại món ăn ngon."}]},{"hanzi":"年夜饭","pinyin":"niányèfàn","pos":"dt.","vn":"bữa cơm tất niên, cơm giao thừa","examples":[{"cn":"除夕晚上，全家人围坐在一起吃丰盛的年夜饭。","pinyin":"Chúxī wǎnshang, quánjiārén wéizuò zài yìqǐ chī fēngshèng de niányèfàn.","vn":"Tối giao thừa, cả nhà quây quần bên nhau ăn bữa cơm tất niên thịnh soạn."},{"cn":"今年我们打算提前预订一家饭店吃年夜饭。","pinyin":"Jīnnián wǒmen dǎsuàn tíqián yùdìng yì jiā fàndiàn chī niányèfàn.","vn":"Năm nay chúng tôi định đặt trước một nhà hàng để ăn cơm tất niên."},{"cn":"年夜饭的餐桌上少不了鱼和饺子。","pinyin":"Niányèfàn de cānzhuō shang shǎo bu liǎo yú hé jiǎozi.","vn":"Trên mâm cơm tất niên không thể thiếu cá và bánh chẻo."}]},{"hanzi":"回忆","pinyin":"huíyì","pos":"dgt.","vn":"hồi tưởng, nhớ lại","examples":[{"cn":"看到这张老照片，我不禁回忆起大学时的快乐时光。","pinyin":"Kàndào zhè zhāng lǎo zhàopiàn, wǒ bùjīn huíyì qǐ dàxué shí de kuàilè shíguāng.","vn":"Nhìn thấy tấm ảnh cũ này, tôi không kìm được nhớ lại quãng thời gian vui vẻ hồi đại học."},{"cn":"爷爷常常向我们回忆他年轻时的故事。","pinyin":"Yéye chángcháng xiàng wǒmen huíyì tā niánqīng shí de gùshi.","vn":"Ông nội thường hồi tưởng kể cho chúng tôi nghe những câu chuyện thời trẻ của ông."},{"cn":"请仔细回忆一下，你把钥匙放在哪里了？","pinyin":"Qǐng zǐxì huíyì yíxià, nǐ bǎ yàoshi fàng zài nǎlǐ le?","vn":"Bạn hãy nhớ kỹ lại xem, bạn đã để chìa khóa ở đâu rồi?"}]},{"hanzi":"童年","pinyin":"tóngnián","pos":"dt.","vn":"tuổi thơ, thời thơ ấu","examples":[{"cn":"我的童年是在乡下爷爷奶奶家度过的。","pinyin":"Wǒ de tóngnián shì zài xiāngxià yéye nǎinai jiā dùguò de.","vn":"Tuổi thơ của tôi trôi qua ở nhà ông bà nội dưới quê."},{"cn":"这部动画片陪伴我度过了快乐的童年。","pinyin":"Zhè bù dònghuàpiàn péibàn wǒ dùguò le kuàilè de tóngnián.","vn":"Bộ phim hoạt hình này đã đồng hành cùng tôi suốt tuổi thơ vui vẻ."},{"cn":"虽然长大了很多，但我依然非常怀念无忧无虑的童年。","pinyin":"Suīrán zhǎngdà le hěn duō, dàn wǒ yīrán fēicháng huáiniàn wúyōuwúlǜ de tóngnián.","vn":"Tuy đã lớn lên nhiều, nhưng tôi vẫn vô cùng nhớ nhung tuổi thơ vô tư không lo nghĩ."}]},{"hanzi":"记忆","pinyin":"jìyì","pos":"dt.","vn":"ký ức, trí nhớ","examples":[{"cn":"那次海边旅行给我留下了美好的记忆。","pinyin":"Nà cì hǎibiān lǚxíng gěi wǒ liúxià le měihǎo de jìyì.","vn":"Chuyến du lịch biển lần đó đã để lại cho tôi những ký ức tươi đẹp."},{"cn":"小时候和兄弟姐妹一起放鞭炮是我最难忘的记忆。","pinyin":"Xiǎoshíhou hé xiōngdì jiěmèi yìqǐ fàng biānpào shì wǒ zuì nánwàng de jìyì.","vn":"Hồi nhỏ cùng anh chị em đốt pháo là ký ức khó quên nhất của tôi."},{"cn":"多复习、多运用能帮助我们加深对生词的记忆。","pinyin":"Duō fùxí, duō yùnyòng néng bāngzhù wǒmen jiāshēn duì shēngcí de jìyì.","vn":"Ôn tập nhiều và vận dụng nhiều có thể giúp chúng ta khắc sâu trí nhớ về từ mới."}]},{"hanzi":"已","pinyin":"yǐ","pos":"phó.","vn":"đã (thường dùng trong văn viết)","examples":[{"cn":"他已在中国生活二十年了，非常熟悉这里的一切。","pinyin":"Tā yǐ zài Zhōngguó shēnghuó èrshí nián le, fēicháng shúxī zhèlǐ de yíqiè.","vn":"Ông ấy đã sống ở Trung Quốc hai mươi năm rồi, vô cùng quen thuộc với mọi thứ ở đây."},{"cn":"时间已不早了，我们明天再继续讨论吧。","pinyin":"Shíjiān yǐ bù zǎo le, wǒmen míngtiān zài jìxù tǎolùn ba.","vn":"Trời đã không còn sớm nữa, ngày mai chúng ta tiếp tục thảo luận nhé."},{"cn":"转眼间，大家毕业已过去五年了。","pinyin":"Zhuǎnyǎnjiān, dàjiā bìyè yǐ guòqù wǔ nián le.","vn":"Thoắt cái mọi người tốt nghiệp đã trôi qua năm năm rồi."}]},{"hanzi":"中年","pinyin":"zhōngnián","pos":"dt.","vn":"trung niên","examples":[{"cn":"人到中年，往往既要照顾老人，又要关心孩子。","pinyin":"Rén dào zhōngnián, wǎngwǎng jì yào zhàogu lǎorén, yòu yào guānxīn háizi.","vn":"Đến tuổi trung niên, con người thường vừa phải chăm sóc người già vừa phải quan tâm con cái."},{"cn":"那位中年男士就是我们学校的新校长。","pinyin":"Nà wèi zhōngnián nánshì jiù shì wǒmen xuéxiào de xīn xiàozhǎng.","vn":"Người đàn ông trung niên kia chính là hiệu trưởng mới của trường chúng tôi."},{"cn":"到了中年以后，更应该注意锻炼身体和保持健康。","pinyin":"Dàole zhōngnián yǐhòu, gèng yīnggāi zhùyì duànliàn shēntǐ hé bǎochí jiànkāng.","vn":"Sau khi bước vào tuổi trung niên, càng nên chú ý rèn luyện thân thể và giữ gìn sức khỏe."}]},{"hanzi":"仍然","pinyin":"réngrán","pos":"phó.","vn":"vẫn, vẫn còn","examples":[{"cn":"虽然遇到了很大困难，但他仍然坚持下来了。","pinyin":"Suīrán yùdào le hěn dà kùnnan, dàn tā réngrán jiānchí xiàlai le.","vn":"Tuy gặp khó khăn rất lớn, nhưng anh ấy vẫn kiên trì vượt qua."},{"cn":"多年没见，她看起来仍然像以前一样年轻。","pinyin":"Duō nián méi jiàn, tā kàn qǐlai réngrán xiàng yǐqián yíyàng niánqīng.","vn":"Nhiều năm không gặp, trông cô ấy vẫn trẻ trung như ngày nào."},{"cn":"外面雨下得很大，他仍然准时来上课了。","pinyin":"Wàimiàn yǔ xià de hěn dà, tā réngrán zhǔnshí lái shàngkè le.","vn":"Bên ngoài trời mưa rất to, anh ấy vẫn đến lớp đúng giờ."}]},{"hanzi":"兄弟","pinyin":"xiōngdì","pos":"dt.","vn":"anh em (trai)","examples":[{"cn":"他们两兄弟长得很像，经常被别人认错。","pinyin":"Tāmen liǎng xiōngdì zhǎng de hěn xiàng, jīngcháng bèi biéren rèncuò.","vn":"Hai anh em họ trông rất giống nhau, thường bị người khác nhận nhầm."},{"cn":"过年时，兄弟姐妹们都从外地赶回家和父母团聚。","pinyin":"Guònián shí, xiōngdì jiěmèimen dōu cóng wàidì gǎn huíjiā hé fùmǔ tuánjù.","vn":"Dịp Tết, các anh chị em đều từ nơi xa vội vã về nhà sum họp cùng bố mẹ."},{"cn":"我们俩从小一起长大，感情就像亲兄弟一样。","pinyin":"Wǒmen liǎ cóngxiǎo yìqǐ zhǎngdà, gǎnqíng jiù xiàng qīn xiōngdì yíyàng.","vn":"Hai chúng tôi lớn lên cùng nhau từ nhỏ, tình cảm giống như anh em ruột vậy."}]},{"hanzi":"元宵节","pinyin":"Yuánxiāojié","pos":"danh từ riêng","vn":"Tết Nguyên Tiêu","examples":[{"cn":"正月十五是元宵节，中国人习惯吃汤圆、赏花灯。","pinyin":"Zhēngyuè shíwǔ shì Yuánxiāojié, Zhōngguórén xíguàn chī tāngyuán, shǎng huādēng.","vn":"Rằm tháng Giêng là Tết Nguyên Tiêu, người Trung Quốc có thói quen ăn bánh trôi và ngắm đèn hoa."},{"cn":"元宵节晚上，公园里举办了热闹的猜灯谜活动。","pinyin":"Yuánxiāojié wǎnshang, gōngyuán lǐ jǔbàn le rènao de cāi dēngmí huódòng.","vn":"Tối Tết Nguyên Tiêu, trong công viên tổ chức hoạt động đoán câu đố đèn lồng rất náo nhiệt."},{"cn":"过了元宵节，春节才算真正结束了。","pinyin":"Guòle Yuánxiāojié, Chūnjié cái suàn zhēnzhèng jiéshù le.","vn":"Qua Tết Nguyên Tiêu thì Tết Nguyên Đán mới coi như thực sự kết thúc."}]},{"hanzi":"端午节","pinyin":"Duānwǔjié","pos":"danh từ riêng","vn":"Tết Đoan Ngọ","examples":[{"cn":"端午节在每年农历五月初五，人们会吃粽子、赛龙舟。","pinyin":"Duānwǔjié zài měi nián nónglì wǔyuè chūwǔ, rénmen huì chī zòngzi, sài lóngzhōu.","vn":"Tết Đoan Ngọ rơi vào mùng 5 tháng 5 âm lịch hàng năm, mọi người sẽ ăn bánh ú và đua thuyền rồng."},{"cn":"今年端午节放三天假，我打算去南方看龙舟比赛。","pinyin":"Jīnnián Duānwǔjié fàng sān tiān jià, wǒ dǎsuàn qù nánfāng kàn lóngzhōu bǐsài.","vn":"Tết Đoan Ngọ năm nay được nghỉ ba ngày, tôi định đi miền Nam xem đua thuyền rồng."},{"cn":"奶奶在端午节前包了很多豆沙粽和肉粽。","pinyin":"Nǎinai zài Duānwǔjié qián bāo le hěn duō dòushāzòng hé ròuzòng.","vn":"Bà nội trước Tết Đoan Ngọ đã gói rất nhiều bánh ú nhân đậu đỏ và bánh ú nhân thịt."}]},{"hanzi":"除夕","pinyin":"Chúxī","pos":"danh từ riêng","vn":"đêm Giao thừa, ngày cuối năm âm lịch","examples":[{"cn":"除夕是一年的最后一天，也是全家人团聚的时刻。","pinyin":"Chúxī shì yì nián de zuìhòu yì tiān, yě shì quánjiārén tuánjù de shíkè.","vn":"Ngày Giao thừa là ngày cuối cùng của năm, cũng là khoảnh khắc cả gia đình sum họp."},{"cn":"除夕夜，很多家庭都有守岁的传统习俗。","pinyin":"Chúxīyè, hěn duō jiātíng dōu yǒu shǒusuì de chuántǒng xísú.","vn":"Đêm Giao thừa, rất nhiều gia đình đều có phong tục truyền thống thức đón giao thừa."},{"cn":"除夕那天，大家都会贴春联、挂灯笼。","pinyin":"Chúxī nà tiān, dàjiā dōu huì tiē chūnlián, guà dēnglong.","vn":"Vào ngày Giao thừa, mọi người đều dán câu đối Tết và treo đèn lồng."}]},{"hanzi":"春晚","pinyin":"Chūnwǎn","pos":"danh từ riêng","vn":"Xuân Vãn (Đêm hội Gala chào xuân)","examples":[{"cn":"除夕晚上看春晚已经成了很多中国家庭的习惯。","pinyin":"Chúxī wǎnshang kàn Chūnwǎn yǐjīng chéng le hěn duō Zhōngguó jiātíng de xíguàn.","vn":"Tối giao thừa xem Xuân Vãn đã trở thành thói quen của rất nhiều gia đình Trung Quốc."},{"cn":"今年春晚的歌舞和相声节目都特别精彩。","pinyin":"Jīnnián Chūnwǎn de gēwǔ hé xiàngsheng jiémù dōu tèbié jīngcǎi.","vn":"Các tiết mục ca múa và tấu hài của Xuân Vãn năm nay đều đặc biệt đặc sắc."},{"cn":"一家人一边包饺子，一边看春晚，气氛热闹极了。","pinyin":"Yìjiārén yìbiān bāo jiǎozi, yìbiān kàn Chūnwǎn, qìfēn rènao jí le.","vn":"Cả nhà vừa gói bánh chẻo vừa xem Xuân Vãn, không khí náo nhiệt vô cùng."}]}],"grammar":[{"title":"固定格式\"怎么都/也+不/没……\"","explanation_vn":"Cấu trúc cố định \"怎么都/也+不/没……\" biểu thị dù nghĩ hết mọi cách cũng không đạt được một kết quả nào đó; đôi khi cũng dùng để biểu thị sự kinh ngạc, không ngờ tới.","examples":[{"cn":"我知道北京野生动物园很大，可怎么也没想到这么大！","pinyin":"Wǒ zhīdào Běijīng Yěshēng Dòngwùyuán hěn dà, kě zěnme yě méi xiǎngdào zhème dà!","vn":"Anh biết Công viên Động vật hoang dã Bắc Kinh rất lớn, nhưng thế nào cũng không ngờ lại lớn đến thế!"},{"cn":"她在包里找了半天，怎么都没找到，真奇怪。","pinyin":"Tā zài bāolǐ zhǎole bàntiān, zěnme dōu méi zhǎodào, zhēn qíguài.","vn":"Cô ấy tìm mãi trong túi, tìm thế nào cũng không thấy, thật kỳ lạ."},{"cn":"我们想看那只熊猫，在动物园等了两个多小时，可是它怎么都不出来。","pinyin":"Wǒmen xiǎng kàn nà zhī xióngmāo, zài dòngwùyuán děngle liǎng ge duō xiǎoshí, kěshì tā zěnme dōu bù chūlái.","vn":"Chúng tôi muốn xem con gấu trúc đó, đợi ở sở thú hơn hai tiếng đồng hồ mà nó nhất quyết không chịu ra."}]},{"title":"固定格式\"一+量词+比+一+量词\"","explanation_vn":"Cấu trúc cố định \"一+量词+比+一+量词\" dùng để so sánh hai hoặc nhiều sự vật, nhấn mạnh cái sau có mức độ sâu hơn cái trước. Thường kết hợp với tính từ tạo thành kết cấu \"一+量词+比+一+量词+形容词\".","examples":[{"cn":"在中国，每年中秋节都会举办很多活动，而且这几年一年比一年热闹。","pinyin":"Zài Zhōngguó, měi nián Zhōngqiūjié dōu huì jǔbàn hěn duō huódòng, érqiě zhè jǐ nián yì nián bǐ yì nián rènao.","vn":"Ở Trung Quốc, mỗi năm vào dịp Tết Trung Thu đều tổ chức rất nhiều hoạt động, hơn nữa mấy năm nay năm sau náo nhiệt hơn năm trước."},{"cn":"夏天快到了，天气也一天比一天热。","pinyin":"Xiàtiān kuài dào le, tiānqì yě yì tiān bǐ yì tiān rè.","vn":"Mùa hè sắp đến rồi, thời tiết cũng ngày một nóng hơn."},{"cn":"这家店里的杯子一个比一个漂亮，我都不知道选哪个了。","pinyin":"Zhè jiā diànlǐ de bēizi yí ge bǐ yí ge piàoliang, wǒ dōu bù zhīdào xuǎn nǎge le.","vn":"Cốc trong cửa hàng này cái sau đẹp hơn cái trước, tôi chẳng biết chọn cái nào nữa."}]},{"title":"用\"大约\"\"左右\"表示概数","explanation_vn":"\"大约\" và \"左右\" biểu thị sự ước lượng, không chắc chắn và có nhiều cách dùng. Trong bài này, chúng được dùng trước hoặc sau từ ngữ chỉ thời gian để biểu thị con số ước lượng về thời gian: \"大约\" đứng trước từ ngữ chỉ thời gian, còn \"左右\" đứng sau từ ngữ chỉ thời gian.","examples":[{"cn":"早上五点左右他们就坐上了高铁，大约七点就来到了儿子工作的城市。","pinyin":"Zǎoshang wǔ diǎn zuǒyòu tāmen jiù zuòshàngle gāotiě, dàyuē qī diǎn jiù láidàole érzi gōngzuò de chéngshì.","vn":"Khoảng năm giờ sáng họ đã lên tàu cao tốc, đến khoảng bảy giờ thì tới thành phố nơi con trai làm việc."},{"cn":"我中午十二点左右到你们学校，和大家一起去食堂吃饭。","pinyin":"Wǒ zhōngwǔ shí'èr diǎn zuǒyòu dào nǐmen xuéxiào, hé dàjiā yìqǐ qù shítáng chīfàn.","vn":"Khoảng mười hai giờ trưa tôi sẽ đến trường các bạn, cùng mọi người đi ăn cơm ở căng tin."},{"cn":"昨天飞机晚点，我晚上大约十点半才到家。","pinyin":"Zuótiān fēijī wǎndiǎn, wǒ wǎnshang dàyuē shí diǎn bàn cái dàojiā.","vn":"Hôm qua máy bay bị trễ chuyến, khoảng mười giờ rưỡi tối tôi mới về đến nhà."}]},{"title":"介词\"作为\"","explanation_vn":"Giới từ \"作为\" chỉ rõ một thân phận nào đó của con người hoặc tính chất nào đó của sự vật. Nó không thể đứng một mình làm thành phần câu mà bắt buộc phải kết hợp với từ ngữ phía sau.","examples":[{"cn":"作为一年里最重要的传统节日，春节对中国人来说有着特别的意义。","pinyin":"Zuòwéi yì nián lǐ zuì zhòngyào de chuántǒng jiérì, Chūnjié duì Zhōngguórén láishuō yǒuzhe tèbié de yìyì.","vn":"Là ngày lễ truyền thống quan trọng nhất trong năm, Tết Nguyên Đán có ý nghĩa đặc biệt đối với người Trung Quốc."},{"cn":"作为新产品，这个手机不仅样子好看，价格也不高。","pinyin":"Zuòwéi xīn chǎnpǐn, zhège shǒujī bùjǐn yàngzi hǎokàn, jiàgé yě bù gāo.","vn":"Là sản phẩm mới, chiếc điện thoại này không chỉ có kiểu dáng đẹp mà giá cả cũng không cao."},{"cn":"作为好朋友，我们一直互相关心、互相帮助。","pinyin":"Zuòwéi hǎo péngyou, wǒmen yìzhí hùxiāng guānxīn, hùxiāng bāngzhù.","vn":"Là bạn tốt của nhau, chúng tôi luôn quan tâm và giúp đỡ lẫn nhau."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"刘小明","cn":"爸爸、妈妈，快看，熊和老虎都在这儿呢！","pinyin":"Bàba, māma, kuài kàn, xióng hé lǎohǔ dōu zài zhèr ne!"},{"speaker":"王一雪","cn":"小明，注意安全，不要一直大喊！","pinyin":"Xiǎomíng, zhùyì ānquán, búyào yìzhí dà hǎn!"},{"speaker":"刘明","cn":"你们看，那个叫东北虎，是国家一级保护动物。那边树林里还有很多动物呢。","pinyin":"Nǐmen kàn, nàge jiào Dōngběihǔ, shì guójiā yījí bǎohù dòngwù. Nàbiān shùlín lǐ hái yǒu hěn duō dòngwù ne."},{"speaker":"刘小明","cn":"咱们都能看到吧？","pinyin":"Zánmen dōu néng kàndào ba?"},{"speaker":"王一雪","cn":"对。景区的车每到一个动物区都会停一会儿，让人们能近距离看看这些动物。","pinyin":"Duì. Jǐngqū de chē měi dào yí ge dòngwùqū dōu huì tíng yíhuìr, ràng rénmen néng jìnjùlí kànkan zhèxiē dòngwù."},{"speaker":"刘明","cn":"真不错，这景区真大、真美！我知道北京野生动物园很大，可怎么也没想到这么大！","pinyin":"Zhēn búcuò, zhè jǐngqū zhēn dà, zhēn měi! Wǒ zhīdào Běijīng Yěshēng Dòngwùyuán hěn dà, kě zěnme yě méi xiǎngdào zhème dà!"},{"speaker":"王一雪","cn":"这里有几千只动物呢，能不大吗？现在是节假日，人多。小明，一会儿千万别跑丢了，我可不是开玩笑呢。","pinyin":"Zhèlǐ yǒu jǐ qiān zhī dòngwù ne, néng bú dà ma? Xiànzài shì jiéjiàrì, rén duō. Xiǎomíng, yíhuìr qiānwàn bié pǎodiū le, wǒ kě bú shì kāi wánxiào ne."}],"translation_vn":"Lưu Tiểu Minh: Bố ơi, mẹ ơi, mau nhìn kìa, gấu và hổ đều ở đây cả này!\nVương Nhất Tuyết: Tiểu Minh, chú ý an toàn, đừng có hét to mãi thế!\nLưu Minh: Hai mẹ con xem kìa, con kia gọi là hổ Đông Bắc, là động vật được bảo vệ cấp quốc gia hạng nhất đấy. Trong khu rừng đằng kia còn có rất nhiều động vật nữa.\nLưu Tiểu Minh: Nhà mình đều có thể nhìn thấy hết chứ ạ?\nVương Nhất Tuyết: Đúng rồi. Xe của khu du lịch cứ đến mỗi khu động vật đều sẽ dừng lại một lát, để mọi người có thể ngắm các loài vật này ở cự ly gần.\nLưu Minh: Tuyệt thật đấy, khu thắng cảnh này vừa rộng vừa đẹp! Anh biết Công viên Động vật hoang dã Bắc Kinh rất lớn, nhưng thế nào cũng không ngờ lại lớn đến thế!\nVương Nhất Tuyết: Ở đây có mấy nghìn con vật cơ mà, sao mà không lớn được? Giờ là ngày nghỉ lễ, đông người lắm. Tiểu Minh, lát nữa nhất định đừng chạy lạc đấy nhé, mẹ không nói đùa đâu.","audio_dialogue":"13-1.mp3","audio_vocab":"13-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一飞","cn":"来，大家快吃月饼，这儿还有葡萄、西瓜。","pinyin":"Lái, dàjiā kuài chī yuèbing, zhèr hái yǒu pútao, xīguā."},{"speaker":"杨同乐","cn":"这是今年的新茶，你们也尝尝。","pinyin":"Zhè shì jīnnián de xīnchá, nǐmen yě chángchang."},{"speaker":"陈天中","cn":"好的。这茶闻着真香！","pinyin":"Hǎo de. Zhè chá wénzhe zhēn xiāng!"},{"speaker":"白家月","cn":"我还是第一次在中国过中秋节呢。","pinyin":"Wǒ háishì dì yī cì zài Zhōngguó guò Zhōngqiūjié ne."},{"speaker":"安妮","cn":"我在加拿大时和中国朋友一起过过中秋节。我记得那天，外面的街道、剧院有很多演出活动。","pinyin":"Wǒ zài Jiānádà shí hé Zhōngguó péngyou yìqǐ guòguo Zhōngqiūjié. Wǒ jìde nà tiān, wàimiàn de jiēdào, jùyuàn yǒu hěn duō yǎnchū huódòng."},{"speaker":"王一飞","cn":"在中国，每年中秋节都会举办很多活动，而且这几年一年比一年热闹。对了，家月，今天是李文爷爷的生日，李文来不了了，你就多吃一块月饼吧。","pinyin":"Zài Zhōngguó, měi nián Zhōngqiūjié dōu huì jǔbàn hěn duō huódòng, érqiě zhè jǐ nián yì nián bǐ yì nián rènao. Duìle, Jiāyuè, jīntiān shì Lǐ Wén yéye de shēngrì, Lǐ Wén lái bu liǎo le, nǐ jiù duō chī yí kuài yuèbing ba."},{"speaker":"白家月","cn":"谢谢，那我就不客气了。","pinyin":"Xièxie, nà wǒ jiù bú kèqi le."},{"speaker":"杨同乐","cn":"中秋节和生日赶在了一块儿，真巧、真好！中秋节多陪陪家人也是应该的。","pinyin":"Zhōngqiūjié hé shēngrì gǎn zài le yíkuàir, zhēn qiǎo, zhēn hǎo! Zhōngqiūjié duō péipei jiārén yě shì yīnggāi de."}],"translation_vn":"Vương Nhất Phi: Nào, mọi người mau ăn bánh trung thu đi, ở đây còn có nho và dưa hấu nữa.\nDương Đồng Lạc: Đây là trà mới năm nay, mọi người cũng nếm thử đi.\nTrần Thiên Trung: Vâng ạ. Trà này ngửi thơm thật đấy!\nBạch Gia Nguyệt: Mình vẫn là lần đầu tiên đón Tết Trung Thu ở Trung Quốc đấy.\nAnnie: Hồi ở Canada mình từng đón Tết Trung Thu cùng bạn người Trung Quốc. Mình nhớ hôm đó, ngoài đường phố và các nhà hát có rất nhiều hoạt động biểu diễn.\nVương Nhất Phi: Ở Trung Quốc, mỗi năm dịp Tết Trung Thu đều tổ chức rất nhiều hoạt động, hơn nữa mấy năm nay năm sau càng náo nhiệt hơn năm trước. À phải rồi, Gia Nguyệt à, hôm nay là sinh nhật ông nội Lý Văn nên Lý Văn không đến được, cậu ăn thêm một miếng bánh trung thu đi nhé.\nBạch Gia Nguyệt: Cảm ơn nhé, vậy mình không khách sáo nữa đâu.\nDương Đồng Lạc: Tết Trung Thu và sinh nhật trùng vào nhau, thật trùng hợp và tuyệt vời! Tết Trung Thu dành nhiều thời gian bên gia đình cũng là điều nên làm mà.","audio_dialogue":"13-3.mp3","audio_vocab":"13-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"中秋节时中国人一般都会回家过节。但是有些人由于工作需要，不能回家，只能一个人留在工作的地方过节。周力就是这些人之中的一位。他是一名铁路工作人员，今年中秋假期，要负责铁路安全检查。","pinyin":"Zhōngqiūjié shí Zhōngguórén yìbān dōu huì huí jiā guòjié. Dànshì yǒuxiē rén yóuyú gōngzuò xūyào, bù néng huí jiā, zhǐ néng yí ge rén liú zài gōngzuò de dìfang guòjié. Zhōu Lì jiùshì zhèxiē rén zhīzhōng de yí wèi. Tā shì yì míng tiělù gōngzuò rényuán, jīnnián Zhōngqiū jiàqī, yào fùzé tiělù ānquán jiǎnchá."},{"speaker":"","cn":"周力的父母知道儿子这次不能回家后，就决定来一次“反向团圆”。早上五点左右他们就坐上了高铁，大约七点就来到了儿子工作的城市。在儿子家，他们做了一桌儿子爱吃的饭菜，有烤肉、烤鱼、饺子等等，还有西红柿鸡蛋汤。周力下班回家，看到一桌子饭菜和突然出现的父母，他感觉特别幸福。","pinyin":"Zhōu Lì de fùmǔ zhīdào érzi zhè cì bù néng huí jiā hòu, jiù juédìng lái yí cì \"fǎnxiàng tuányuán\". Zǎoshang wǔ diǎn zuǒyòu tāmen jiù zuòshàngle gāotiě, dàyuē qī diǎn jiù láidàole érzi gōngzuò de chéngshì. Zài érzi jiā, tāmen zuòle yì zhuō érzi ài chī de fàncài, yǒu kǎoròu, kǎoyú, jiǎozi děngděng, hái yǒu xīhóngshì jīdàn tāng. Zhōu Lì xiàbān huí jiā, kàndào yì zhuōzi fàncài hé tūrán chūxiàn de fùmǔ, tā gǎnjué tèbié xìngfú."},{"speaker":"","cn":"这个中秋节，地点变了，但爱没变。","pinyin":"Zhège Zhōngqiūjié, dìdiǎn biàn le, dàn ài méi biàn."}],"translation_vn":"Vào dịp Tết Trung Thu, người Trung Quốc thường sẽ về nhà đón lễ. Nhưng có một số người do nhu cầu công việc nên không thể về nhà, chỉ đành ở lại một mình nơi làm việc để đón lễ. Chu Lực chính là một trong số những người ấy. Anh là một nhân viên ngành đường sắt, kỳ nghỉ Trung Thu năm nay anh phải phụ trách kiểm tra an toàn đường sắt.\nBố mẹ của Chu Lực sau khi biết lần này con trai không thể về nhà đã quyết định thực hiện một chuyến \"đoàn viên ngược\". Khoảng năm giờ sáng họ đã lên tàu cao tốc, đến khoảng bảy giờ thì tới thành phố nơi con trai làm việc. Ở nhà con trai, họ nấu một bàn đầy những món con thích ăn, có thịt nướng, cá nướng, bánh chẻo,... lại còn có cả canh trứng cà chua. Chu Lực tan làm về nhà, nhìn thấy cả bàn cơm canh cùng bố mẹ bất ngờ xuất hiện, anh cảm thấy vô cùng hạnh phúc.\nTết Trung Thu này, địa điểm đã thay đổi, nhưng tình yêu thương thì không hề đổi thay.","audio_dialogue":"13-5.mp3","audio_vocab":"13-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"中国有很多节日，比如春节、元宵节、端午节、中秋节等。","pinyin":"Zhōngguó yǒu hěn duō jiérì, bǐrú Chūnjié, Yuánxiāojié, Duānwǔjié, Zhōngqiūjié děng."},{"speaker":"","cn":"作为一年里最重要的传统节日，春节对中国人来说有着特别的意义。春节到来时，人们不管在哪里，都想回家过年。春节前也最忙，既要收拾房子、打扫卫生，又要准备各种美食。除夕这天晚上，一家人一边吃年夜饭，一边看春晚。零点一到，大家互相祝新年快乐，到处都是幸福的笑声。","pinyin":"Zuòwéi yì nián lǐ zuì zhòngyào de chuántǒng jiérì, Chūnjié duì Zhōngguórén láishuō yǒuzhe tèbié de yìyì. Chūnjié dàolái shí, rénmen bùguǎn zài nǎlǐ, dōu xiǎng huí jiā guònián. Chūnjié qián yě zuì máng, jì yào shōushi fángzi, dǎsǎo wèishēng, yòu yào zhǔnbèi gèzhǒng měishí. Chúxī zhè tiān wǎnshang, yì jiā rén yìbiān chī niányèfàn, yìbiān kàn Chūnwǎn. Língdiǎn yí dào, dàjiā hùxiāng zhù xīnnián kuàilè, dàochù dōu shì xìngfú de xiàoshēng."},{"speaker":"","cn":"每当回忆起童年，我最美好的记忆很多也发生在过年时。虽然现在已人到中年，离开了家，但是春节仍然是我最喜欢的节日，过年时也更想父母、兄弟姐妹。","pinyin":"Měidāng huíyìqǐ tóngnián, wǒ zuì měihǎo de jìyì hěn duō yě fāshēng zài guònián shí. Suīrán xiànzài yǐ rén dào zhōngnián, líkāile jiā, dànshì Chūnjié réngrán shì wǒ zuì xǐhuan de jiérì, guònián shí yě gèng xiǎng fùmǔ, xiōngdì jiěmèi."}],"translation_vn":"Trung Quốc có rất nhiều ngày lễ, ví dụ như Tết Nguyên Đán, Tết Nguyên Tiêu, Tết Đoan Ngọ, Tết Trung Thu,...\nLà ngày lễ truyền thống quan trọng nhất trong năm, Tết Nguyên Đán có ý nghĩa đặc biệt đối với người Trung Quốc. Khi Tết đến, mọi người dù đang ở đâu cũng đều muốn về nhà đón Tết. Trước Tết cũng là lúc bận rộn nhất, vừa phải dọn dẹp nhà cửa, làm vệ sinh, vừa phải chuẩn bị đủ loại món ăn ngon. Tối đêm Giao thừa, cả nhà vừa ăn bữa cơm tất niên, vừa xem chương trình Xuân Vãn. Vừa điểm 0 giờ, mọi người chúc nhau năm mới vui vẻ, khắp nơi đều tràn ngập tiếng cười hạnh phúc.\nMỗi khi hồi tưởng về tuổi thơ, rất nhiều ký ức tươi đẹp nhất của tôi cũng đều diễn ra vào dịp Tết. Tuy hiện nay đã bước vào tuổi trung niên, rời xa gia đình, nhưng Tết Nguyên Đán vẫn luôn là ngày lễ tôi yêu thích nhất, và mỗi dịp Tết đến tôi lại càng nhớ bố mẹ, anh chị em hơn.","audio_dialogue":"13-7.mp3","audio_vocab":"13-8.mp3"}]},{"id":14,"title_cn":"合适才买","title_pinyin":"Héshì cái mǎi","title_vn":"Phù hợp mới mua","goals":["Có thể nghe hiểu và trao đổi các thông tin liên quan đến giảm giá, so sánh hàng hóa khi mua sắm trực tiếp tại cửa hàng.","Có thể trình bày ý định mua sắm bằng lời hoặc bằng văn bản.","Hiểu được quan niệm tiêu dùng của người Trung Quốc."],"vocab":[{"hanzi":"茶叶","pinyin":"cháyè","pos":"dt.","vn":"trà, lá trà","examples":[{"cn":"爸爸非常喜欢喝茶，家里存着好几种名贵茶叶。","pinyin":"Bàba fēicháng xǐhuan hēchá, jiā li cúnzhe hǎojǐ zhǒng míngguì cháyè.","vn":"Bố rất thích uống trà, trong nhà cất giữ mấy loại trà quý."},{"cn":"这种新上市的绿茶茶叶闻起来特别清香。","pinyin":"Zhè zhǒng xīn shàngshì de lǜchá cháyè wén qǐlai tèbié qīngxiāng.","vn":"Loại lá trà xanh mới ra mắt này ngửi có mùi thơm thanh mát đặc biệt."},{"cn":"去杭州旅游时，我买了两盒当地的茶叶送给朋友。","pinyin":"Qù Hángzhōu lǚyóu shí, wǒ mǎi le liǎng hé dāngdì de cháyè sòng gěi péngyou.","vn":"Khi đi du lịch Hàng Châu, tôi đã mua hai hộp trà đặc sản địa phương tặng bạn bè."}]},{"hanzi":"究竟","pinyin":"jiūjìng","pos":"phó.","vn":"rốt cuộc, cuối cùng, thực ra","examples":[{"cn":"这么多款式，你究竟最喜欢哪一件？","pinyin":"Zhème duō kuǎnshì, nǐ jiūjìng zuì xǐhuan nǎ yí jiàn?","vn":"Nhiều kiểu dáng như thế, rốt cuộc bạn thích nhất chiếc nào?"},{"cn":"我一直没联系上他，他究竟去哪里了？","pinyin":"Wǒ yìzhí méi liánxì shàng tā, tā jiūjìng qù nǎlǐ le?","vn":"Tôi mãi không liên lạc được với anh ấy, rốt cuộc anh ấy đã đi đâu rồi?"},{"cn":"这件事究竟是谁的错，我们必须调查清楚。","pinyin":"Zhè jiàn shì jiūjìng shì shéi de cuò, wǒmen bìxū diàochá qīngchu.","vn":"Chuyện này rốt cuộc là lỗi của ai, chúng ta bắt buộc phải điều tra cho rõ ràng."}]},{"hanzi":"分为","pinyin":"fēnwéi","pos":"dgt.","vn":"chia thành, phân thành","examples":[{"cn":"中国茶叶主要分为绿茶、红茶、乌龙茶等几大类。","pinyin":"Zhōngguó cháyè zhǔyào fēnwéi lǜchá, hóngchá, wūlóngchá děng jǐ dà lèi.","vn":"Trà Trung Quốc chủ yếu được chia thành mấy loại lớn như trà xanh, hồng trà, trà ô long,..."},{"cn":"本次汉语比赛分为初赛和决赛两个阶段。","pinyin":"Běn cì Hànyǔ bǐsài fēnwéi chūsài hé juésài liǎng ge jiēduàn.","vn":"Cuộc thi tiếng Trung lần này được chia thành hai giai đoạn là vòng sơ khảo và vòng chung kết."},{"cn":"这座大桥分为上下两层，上面走汽车，下面通火车。","pinyin":"Zhè zuò dàqiáo fēnwéi shàngxià liǎng céng, shàngmian zǒu qìchē, xiàmian tōng huǒchē.","vn":"Cây cầu lớn này được chia làm hai tầng trên dưới, tầng trên chạy ô tô, tầng dưới chạy tàu hỏa."}]},{"hanzi":"抱歉","pinyin":"bàoqiàn","pos":"tt.","vn":"xin lỗi, có lỗi, áy náy","examples":[{"cn":"非常抱歉，让您久等了。","pinyin":"Fēicháng bàoqiàn, ràng nín jiǔděng le.","vn":"Vô cùng xin lỗi, đã để quý khách phải đợi lâu."},{"cn":"实在抱歉，您要的那款运动鞋今天刚好卖完了。","pinyin":"Shízài bàoqiàn, nín yào de nà kuǎn yùndòngxié jīntiān gānghǎo màiwán le.","vn":"Thật sự xin lỗi, mẫu giày thể thao quý khách cần hôm nay vừa khéo bán hết rồi."},{"cn":"他因为临时有事没能来参加聚会，感到很抱歉。","pinyin":"Tā yīnwèi línshí yǒushì méi néng lái cānjiā jùhuì, gǎndào hěn bàoqiàn.","vn":"Anh ấy vì có việc đột xuất không thể đến dự buổi gặp mặt nên cảm thấy rất áy náy."}]},{"hanzi":"暂时","pinyin":"zànshí","pos":"tt.","vn":"tạm thời","examples":[{"cn":"这件事我们暂时先不讨论，等下周开会再决定。","pinyin":"Zhè jiàn shì wǒmen zànshí xiān bù tǎolùn, děng xiàzhōu kāihuì zài juédìng.","vn":"Chuyện này chúng ta tạm thời chưa bàn vội, đợi cuộc họp tuần sau rồi quyết định."},{"cn":"不好意思，这款新手机目前暂时缺货。","pinyin":"Bùhǎoyìsi, zhè kuǎn xīn shǒujī mùqián zànshí quēhuò.","vn":"Xin lỗi, mẫu điện thoại mới này hiện tại tạm thời hết hàng."},{"cn":"大家可以把大件行李暂时存放在前台。","pinyin":"Dàjiā kěyǐ bǎ dàjiàn xíngli zànshí cúnfàng zài qiántái.","vn":"Mọi người có thể gửi tạm hành lý cồng kềnh ở quầy lễ tân."}]},{"hanzi":"满","pinyin":"mǎn","pos":"dgt./tt.","vn":"đạt đủ (mức quy định); đầy","examples":[{"cn":"今天商场搞活动，购物满三百元就减五十元。","pinyin":"Jīntiān shāngchǎng gǎo huódòng, gòuwù mǎn sānbǎi yuán jiù jiǎn wǔshí yuán.","vn":"Hôm nay trung tâm thương mại có chương trình khuyến mãi, mua sắm đủ ba trăm tệ sẽ được giảm năm mươi tệ."},{"cn":"房间里堆满了他刚买回来的新书。","pinyin":"Fángjiān lǐ duīmǎn le tā gāng mǎi huílai de xīnshū.","vn":"Trong phòng chất đầy sách mới mà anh ấy vừa mua về."},{"cn":"茶杯已经倒满了，再倒就要洒出来了。","pinyin":"Chábēi yǐjīng dàomǎn le, zài dào jiù yào sǎ chūlai le.","vn":"Chén trà đã rót đầy rồi, rót thêm nữa là sẽ tràn ra ngoài đấy."}]},{"hanzi":"两","pinyin":"liǎng","pos":"lượng.","vn":"lạng (đơn vị đo khối lượng của Trung Quốc, bằng 50 gam)","examples":[{"cn":"老板，请给我来二两猪肉大葱馅儿的饺子。","pinyin":"Lǎobǎn, qǐng gěi wǒ lái èr liǎng zhūròu dàcōng xiànr de jiǎozi.","vn":"Ông chủ ơi, cho tôi hai lạng bánh chẻo nhân thịt lợn hành tây."},{"cn":"一斤等于十两，半斤就是五两。","pinyin":"Yì jīn děngyú shí liǎng, bàn jīn jiù shì wǔ liǎng.","vn":"Một cân (Trung Quốc) bằng mười lạng, nửa cân chính là năm lạng."},{"cn":"这种茶叶一次不用买太多，买四两就够喝一阵子了。","pinyin":"Zhè zhǒng cháyè yí cì búyòng mǎi tài duō, mǎi sì liǎng jiù gòu hē yízhènzi le.","vn":"Loại trà này mỗi lần không cần mua quá nhiều, mua bốn lạng là đủ uống một thời gian rồi."}]},{"hanzi":"超过","pinyin":"chāoguò","pos":"dgt.","vn":"vượt quá, hơn","examples":[{"cn":"今天来参观展览的观众人数超过了五千人。","pinyin":"Jīntiān lái cānguān zhǎnlǎn de guānzhòng rénshù chāoguò le wǔqiān rén.","vn":"Số lượng khán giả đến tham quan triển lãm hôm nay đã vượt quá năm nghìn người."},{"cn":"在高速公路上开车，车速不能超过规定标准。","pinyin":"Zài gāosù gōnglù shang kāichē, chēsù bù néng chāoguò guīdìng biāozhǔn.","vn":"Lái xe trên đường cao tốc, tốc độ không được vượt quá mức quy định."},{"cn":"行李重量如果超过二十公斤，就需要多交行李费。","pinyin":"Xíngli zhòngliàng rúguǒ chāoguò èrshí gōngjīn, jiù xūyào duō jiāo xínglifèi.","vn":"Nếu trọng lượng hành lý vượt quá hai mươi kilôgam thì phải đóng thêm phí hành lý."}]},{"hanzi":"盒子","pinyin":"hézi","pos":"dt.","vn":"cái hộp","examples":[{"cn":"她把朋友们送的贺卡都仔细地收在盒子里。","pinyin":"Tā bǎ péngyoumen sòng de hèkǎ dōu zǐxì de shōu zài hézi lǐ.","vn":"Cô ấy cất giữ cẩn thận tất cả thiệp chúc mừng bạn bè tặng vào trong hộp."},{"cn":"这个装月饼的盒子设计得非常精美。","pinyin":"Zhège zhuāng yuèbing de hézi shèjì de fēicháng jīngměi.","vn":"Chiếc hộp đựng bánh trung thu này được thiết kế vô cùng tinh xảo."},{"cn":"桌子上放着一个蓝色的盒子，里面装着生日礼物。","pinyin":"Zhuōzi shang fàngzhe yí ge lánsè de hézi, lǐmiàn zhuāngzhe shēngrì lǐwù.","vn":"Trên bàn đặt một chiếc hộp màu xanh lam, bên trong đựng quà sinh nhật."}]},{"hanzi":"装","pinyin":"zhuāng","pos":"dgt.","vn":"đựng, đóng gói; lắp đặt","examples":[{"cn":"请帮我拿一个大一点儿的袋子装这些水果。","pinyin":"Qǐng bāng wǒ ná yí ge dà yìdiǎnr de dàizi zhuāng zhèxiē shuǐguǒ.","vn":"Làm ơn lấy giúp tôi một chiếc túi to hơn chút để đựng chỗ hoa quả này."},{"cn":"你的背包里装了什么，怎么这么沉？","pinyin":"Nǐ de bēibāo lǐ zhuāng le shénme, zěnme zhème chén?","vn":"Trong ba lô của cậu đựng cái gì mà sao nặng thế?"},{"cn":"我们家新买的空调明天师傅来上门装。","pinyin":"Wǒmen jiā xīn mǎi de kōngtiáo míngtiān shīfu lái shàngmén zhuāng.","vn":"Chiếc điều hòa nhà tôi mới mua ngày mai thợ sẽ đến tận nhà lắp đặt."}]},{"hanzi":"各位","pinyin":"gèwèi","pos":"đt.","vn":"các vị, quý vị, mọi người","examples":[{"cn":"各位同学，今天我们开始学习第十四课。","pinyin":"Gèwèi tóngxué, jīntiān wǒmen kāishǐ xuéxí dì shísì kè.","vn":"Các bạn học sinh thân mến, hôm nay chúng ta bắt đầu học bài số 14."},{"cn":"感谢各位在百忙之中参加今天的活动。","pinyin":"Gǎnxiè gèwèi zài bǎimáng zhīzhōng cānjiā jīntiān de huódòng.","vn":"Cảm ơn quý vị đã bớt chút thời gian bận rộn đến tham dự hoạt động hôm nay."},{"cn":"各位乘客请注意，列车即将进站，请拿好随身物品。","pinyin":"Gèwèi chéngkè qǐng zhùyì, lièchē jíjiāng jìnzhàn, qǐng náhǎo suíshēn wùpǐn.","vn":"Xin quý hành khách chú ý, đoàn tàu sắp vào ga, vui lòng mang theo đồ đạc cá nhân."}]},{"hanzi":"顾客","pinyin":"gùkè","pos":"dt.","vn":"khách hàng","examples":[{"cn":"这家餐厅菜品新鲜、服务周到，很受顾客欢迎。","pinyin":"Zhè jiā cāntīng càipǐn xīnxiān, fúwù zhōudào, hěn shòu gùkè huānyíng.","vn":"Nhà hàng này món ăn tươi ngon, phục vụ chu đáo nên rất được khách hàng yêu thích."},{"cn":"周末商场里打折，前来购物的顾客特别多。","pinyin":"Zhōumò shāngchǎng lǐ dǎzhé, qiánlái gòuwù de gùkè tèbié duō.","vn":"Cuối tuần trung tâm thương mại giảm giá, khách hàng đến mua sắm đặc biệt đông."},{"cn":"售货员总是面带微笑地回答顾客的各种问题。","pinyin":"Shòuhuòyuán zǒngshì miàndài wēixiào de huídá gùkè de gèzhǒng wèntí.","vn":"Nhân viên bán hàng luôn mỉm cười trả lời mọi câu hỏi của khách hàng."}]},{"hanzi":"本","pinyin":"běn","pos":"đt.","vn":"này, của bản thân (trung tâm thương mại này, công ty này...)","examples":[{"cn":"本商场所有冬季服装本周末一律七折优惠。","pinyin":"Běn shāngchǎng suǒyǒu dōngjì fúzhuāng běn zhōumò yílǜ qīzhé yōuhuì.","vn":"Tất cả quần áo mùa đông của trung tâm thương mại này cuối tuần này đồng loạt giảm 30%."},{"cn":"本公司计划于下月推出一款全新的智能手表。","pinyin":"Běn gōngsī jìhuà yú xiàyuè tuīchū yì kuǎn quánxīn de zhìnéng shǒubiǎo.","vn":"Công ty chúng tôi có kế hoạch ra mắt một mẫu đồng hồ thông minh hoàn toàn mới vào tháng tới."},{"cn":"本次会议主要讨论明年的工作安排。","pinyin":"Běn cì huìyì zhǔyào tǎolùn míngnián de gōngzuò ānpái.","vn":"Cuộc họp lần này chủ yếu thảo luận về kế hoạch công việc năm tới."}]},{"hanzi":"假日","pinyin":"jiàrì","pos":"dt.","vn":"ngày nghỉ lễ, ngày lễ","examples":[{"cn":"每逢假日，许多家庭都会开车去郊外露营。","pinyin":"Měiféng jiàrì, xǔduō jiātíng dōu huì kāichē qù jiāowài lùyíng.","vn":"Mỗi dịp ngày nghỉ lễ, rất nhiều gia đình đều lái xe đi ngoại ô cắm trại."},{"cn":"这家旅行社推出了多条假日旅游精品路线。","pinyin":"Zhè jiā lǚxíngshè tuīchū le duō tiáo jiàrì lǚyóu jīngpǐn lùxiàn.","vn":"Công ty du lịch này đã tung ra nhiều tuyến du lịch chất lượng cao cho dịp lễ."},{"cn":"祝大家度过一个轻松愉快的假日！","pinyin":"Zhù dàjiā dùguò yí ge qīngsōng yúkuài de jiàrì!","vn":"Chúc mọi người có một kỳ nghỉ lễ thư giãn và vui vẻ!"}]},{"hanzi":"低价","pinyin":"dījià","pos":"dt.","vn":"giá thấp, giá rẻ","examples":[{"cn":"这家超市经常在晚上八点以后低价处理新鲜蔬菜。","pinyin":"Zhè jiā chāoshì jīngcháng zài wǎnshang bā diǎn yǐhòu dījià chǔlǐ xīnxiān shūcài.","vn":"Siêu thị này thường bán rau tươi với giá thấp sau tám giờ tối."},{"cn":"买东西时不能只图低价，更要看重商品的质量。","pinyin":"Mǎi dōngxi shí bù néng zhǐ tú dījià, gèng yào kànzhòng shāngpǐn de zhìliàng.","vn":"Khi mua đồ không thể chỉ ham giá rẻ, càng phải coi trọng chất lượng hàng hóa."},{"cn":"他在网上抢到了一张飞往成都的低价机票。","pinyin":"Tā zài wǎngshang qiǎngdào le yì zhāng fēiwǎng Chéngdū de dījià jīpiào.","vn":"Anh ấy đã săn được một tấm vé máy bay giá rẻ đi Thành Đô trên mạng."}]},{"hanzi":"促销","pinyin":"cùxiāo","pos":"dgt.","vn":"khuyến mãi, xúc tiến bán hàng","examples":[{"cn":"“双十一”期间，各大电商平台都在搞大型促销活动。","pinyin":"“Shuāngshíyī” qījiān, gè dà diànshāng píngtái dōu zài gǎo dàxíng cùxiāo huódòng.","vn":"Trong dịp \"Song Thập Nhất\", các sàn thương mại điện tử lớn đều tổ chức chương trình khuyến mãi quy mô lớn."},{"cn":"这批酸奶正在促销，买二送一，非常划算。","pinyin":"Zhè pī suānnǎi zhèngzài cùxiāo, mǎi èr sòng yī, fēicháng huásuàn.","vn":"Lô sữa chua này đang khuyến mãi mua hai tặng một, vô cùng hời."},{"cn":"商家为了促销，推出了满减和抽奖两种优惠方式。","pinyin":"Shāngjiā wèile cùxiāo, tuīchū le mǎnjiǎn hé chōujiǎng liǎng zhǒng yōuhuì fāngshì.","vn":"Để kích cầu bán hàng, người bán đã tung ra hai hình thức ưu đãi là giảm giá theo hóa đơn và rút thăm trúng thưởng."}]},{"hanzi":"广播","pinyin":"guǎngbō","pos":"dt./dgt.","vn":"phát thanh, loa phát thanh; phát sóng","examples":[{"cn":"我每天早上开车上班时都会听新闻广播。","pinyin":"Wǒ měitiān zǎoshang kāichē shàngbān shí dōu huì tīng xīnwén guǎngbō.","vn":"Mỗi sáng lái xe đi làm tôi đều nghe đài phát thanh tin tức."},{"cn":"候机室的广播通知大家，飞往上海的航班开始登机了。","pinyin":"Hòujīshì de guǎngbō tōngzhī dàjiā, fēiwǎng Shànghǎi de hángbān kāishǐ dēngjī le.","vn":"Loa phát thanh phòng chờ thông báo mọi người chuyến bay đi Thượng Hải bắt đầu lên máy bay."},{"cn":"学校每天下午都会通过校园广播播放音乐和通知。","pinyin":"Xuéxiào měitiān xiàwǔ dōu huì tōngguò xiàoyuán guǎngbō bōfàng yīnyuè hé tōngzhī.","vn":"Mỗi buổi chiều nhà trường đều phát nhạc và thông báo qua hệ thống loa phát thanh trường học."}]},{"hanzi":"减","pinyin":"jiǎn","pos":"dgt.","vn":"giảm, bớt, trừ","examples":[{"cn":"这款外套今天搞特价，原价八百，现在直接减两百。","pinyin":"Zhè kuǎn wàitào jīntiān gǎo tèjià, yuánjià bābǎi, xiànzài zhíjiē jiǎn liǎngbǎi.","vn":"Mẫu áo khoác này hôm nay bán giá đặc biệt, giá gốc tám trăm, giờ giảm trực tiếp hai trăm."},{"cn":"十减三等于七，这道数学题很简单。","pinyin":"Shí jiǎn sān děngyú qī, zhè dào shùxuétí hěn jiǎndān.","vn":"Mười trừ ba bằng bảy, bài toán này rất đơn giản."},{"cn":"经过半年的坚持运动，他的体重成功减了十斤。","pinyin":"Jīngguò bàn nián de jiānchí yùndòng, tā de tǐzhòng chénggōng jiǎn le shí jīn.","vn":"Sau nửa năm kiên trì tập thể dục, cân nặng của anh ấy đã giảm thành công năm cân."}]},{"hanzi":"广告","pinyin":"guǎnggào","pos":"dt.","vn":"quảng cáo","examples":[{"cn":"电视节目看到最精彩的地方，突然插播了一段广告。","pinyin":"Diànshì jiémù kàndào zuì jīngcǎi de dìfang, tūrán chābō le yí duàn guǎnggào.","vn":"Chương trình ti vi đang xem đến đoạn gay cấn nhất thì bất ngờ chèn một đoạn quảng cáo."},{"cn":"买商品时不能只听广告宣传，还要看其他买家的评价。","pinyin":"Mǎi shāngpǐn shí bù néng zhǐ tīng guǎnggào xuānchuán, hái yào kàn qítā mǎijiā de píngjià.","vn":"Khi mua hàng không thể chỉ nghe quảng cáo tuyên truyền, mà còn phải xem đánh giá của những người mua khác."},{"cn":"这个创意广告拍得非常感人，让人印象深刻。","pinyin":"Zhège chuàngyì guǎnggào pāi de fēicháng gǎnrén, ràng rén yìnxiàng shēnkè.","vn":"Đoạn quảng cáo sáng tạo này quay rất cảm động, để lại ấn tượng sâu sắc cho người xem."}]},{"hanzi":"首先","pinyin":"shǒuxiān","pos":"phó.","vn":"trước tiên, đầu tiên","examples":[{"cn":"学好一门外语，首先要有浓厚的兴趣，其次要坚持练习。","pinyin":"Xuéhǎo yì mén wàiyǔ, shǒuxiān yào yǒu nónghòu de xìngqù, qícì yào jiānchí liànxí.","vn":"Muốn học tốt một ngoại ngữ, trước tiên phải có hứng thú sâu sắc, tiếp theo phải kiên trì luyện tập."},{"cn":"做这道菜，首先把西红柿洗干净切成块。","pinyin":"Zuò zhè dào cài, shǒuxiān bǎ xīhóngshì xǐ gānjìng qiēchéng kuài.","vn":"Làm món này, đầu tiên rửa sạch cà chua rồi cắt thành miếng."},{"cn":"非常感谢大家的支持，首先请允许我介绍一下今天的安排。","pinyin":"Fēicháng gǎnxiè dàjiā de zhīchí, shǒuxiān qǐng yǔnxǔ wǒ jièshào yíxià jīntiān de ānpái.","vn":"Vô cùng cảm ơn sự ủng hộ của mọi người, trước tiên xin phép cho tôi giới thiệu lịch trình hôm nay."}]},{"hanzi":"牌子","pinyin":"páizi","pos":"dt.","vn":"nhãn hiệu, thương hiệu; tấm biển","examples":[{"cn":"这个牌子的运动鞋穿起来既轻便又舒服。","pinyin":"Zhège páizi de yùndòngxié chuān qǐlai jì qīngbiàn yòu shūfu.","vn":"Giày thể thao của thương hiệu này đi vừa nhẹ nhàng vừa thoải mái."},{"cn":"你平时喜欢买哪个牌子的护肤品？","pinyin":"Nǐ píngshí xǐhuan mǎi nǎge páizi de hùfūpǐn?","vn":"Bình thường bạn thích mua mỹ phẩm chăm sóc da của nhãn hiệu nào?"},{"cn":"买家电时，我一般会优先选择口碑好的老牌子。","pinyin":"Mǎi jiādiàn shí, wǒ yìbān huì yōuxiān xuǎnzé kǒubēi hǎo de lǎo páizi.","vn":"Khi mua đồ gia dụng, tôi thường ưu tiên chọn những thương hiệu lâu đời có tiếng tốt."}]},{"hanzi":"降价","pinyin":"jiàngjià","pos":"dgt.","vn":"giảm giá, hạ giá","examples":[{"cn":"听说那款笔记本电脑最近降价了，便宜了五百多块。","pinyin":"Tīngshuō nà kuǎn bǐjìběn diànnǎo zuìjìn jiàngjià le, piányi le wǔbǎi duō kuài.","vn":"Nghe nói chiếc máy tính xách tay đó gần đây giảm giá rồi, rẻ hơn tận hơn năm trăm tệ."},{"cn":"换季的时候，商场里的过季衣服都会大幅度降价。","pinyin":"Huànjì de shíhou, shāngchǎng lǐ de guòjì yīfu dōu huì dàfúdù jiàngjià.","vn":"Lúc giao mùa, quần áo trái mùa trong trung tâm thương mại đều giảm giá mạnh."},{"cn":"这款手机一直没降价，说明它的销量非常好。","pinyin":"Zhè kuǎn shǒujī yìzhí méi jiàngjià, shuōmíng tā de xiāoliàng fēicháng hǎo.","vn":"Mẫu điện thoại này mãi không hạ giá, chứng tỏ doanh số bán hàng của nó rất tốt."}]},{"hanzi":"样式","pinyin":"yàngshì","pos":"dt.","vn":"kiểu dáng, mẫu mã","examples":[{"cn":"这家服装店的衣服样式很新颖，特别受年轻人欢迎。","pinyin":"Zhè jiā fúzhuāngdiàn de yīfu yàngshì hěn xīnyǐng, tèbié shòu niánqīngrén huānyíng.","vn":"Quần áo của tiệm này kiểu dáng rất mới mẻ, đặc biệt được giới trẻ ưa chuộng."},{"cn":"这双鞋的质量不错，就是样式稍微有点儿老气。","pinyin":"Zhè shuāng xié de zhìliàng búcuò, jiùshì yàngshì shāowēi yǒudiǎnr lǎoqì.","vn":"Chất lượng đôi giày này không tệ, chỉ có kiểu dáng hơi bị già một chút."},{"cn":"您可以挑选一下自己喜欢的家具样式和颜色。","pinyin":"Nín kěyǐ tiāoxuǎn yíxià zìjǐ xǐhuan de jiājù yàngshì hé yánsè.","vn":"Quý khách có thể chọn kiểu dáng và màu sắc đồ nội thất mình yêu thích."}]},{"hanzi":"价钱","pinyin":"jiàqián","pos":"dt.","vn":"giá cả, giá tiền","examples":[{"cn":"这件毛衣摸起来很柔软，而且价钱也很公道。","pinyin":"Zhè jiàn máoyī mō qǐlai hěn róuruǎn, érqiě jiàqián yě hěn gōngdào.","vn":"Chiếc áo len này sờ rất mềm mại, hơn nữa giá cả cũng rất phải chăng."},{"cn":"老板，您看这双皮鞋的价钱还能再商量一下吗？","pinyin":"Lǎobǎn, nín kàn zhè shuāng píxié de jiàqián hái néng zài shāngliang yíxià ma?","vn":"Ông chủ ơi, ông xem giá của đôi giày da này có thể thương lượng thêm chút nữa được không?"},{"cn":"同样的水果，早市上的价钱比超市便宜不少。","pinyin":"Tóngyàng de shuǐguǒ, zǎoshì shang de jiàqián bǐ chāoshì piányi bùshǎo.","vn":"Cùng loại hoa quả nhưng giá ở chợ sáng rẻ hơn trong siêu thị khá nhiều."}]},{"hanzi":"商业","pinyin":"shāngyè","pos":"dt.","vn":"thương mại, kinh doanh","examples":[{"cn":"王府井是北京非常有名的商业街。","pinyin":"Wángfǔjǐng shì Běijīng fēicháng yǒumíng de shāngyèjiē.","vn":"Vương Phủ Tỉnh là khu phố thương mại vô cùng nổi tiếng của Bắc Kinh."},{"cn":"这片新开发的商业区汇集了许多大型购物中心和餐馆。","pinyin":"Zhè piàn xīn kāifā de shāngyèqū huìjí le xǔduō dàxíng gòuwù zhōngxīn hé cānguǎn.","vn":"Khu thương mại mới phát triển này tập trung rất nhiều trung tâm mua sắm lớn và nhà hàng."},{"cn":"他大学毕业后选择了从事商业管理方面的工作。","pinyin":"Tā dàxué bìyè hòu xuǎnzé le cóngshì shāngyè guǎnlǐ fāngmiàn de gōngzuò.","vn":"Sau khi tốt nghiệp đại học, anh ấy chọn làm công việc trong lĩnh vực quản trị kinh doanh."}]},{"hanzi":"商品","pinyin":"shāngpǐn","pos":"dt.","vn":"hàng hóa, sản phẩm","examples":[{"cn":"这家大型超市里的商品琳琅满目，应有尽有。","pinyin":"Zhè jiā dàxíng chāoshì lǐ de shāngpǐn línlángmǎnmù, yīngyǒujìnyǒu.","vn":"Hàng hóa trong siêu thị lớn này đa dạng bắt mắt, thứ gì cũng có."},{"cn":"网上购物时，一定要仔细查看商品的详细介绍。","pinyin":"Wǎngshang gòuwù shí, yídìng yào zǐxì chákàn shāngpǐn de xiángxì jièshào.","vn":"Khi mua sắm trực tuyến nhất định phải xem kỹ phần giới thiệu chi tiết về sản phẩm."},{"cn":"如果收到的商品有质量问题，七天之内可以免费退换。","pinyin":"Rúguǒ shōudào de shāngpǐn yǒu zhìliàng wèntí, qī tiān zhīnèi kěyǐ miǎnfèi tuìhuàn.","vn":"Nếu hàng hóa nhận được có vấn đề về chất lượng, trong vòng bảy ngày có thể đổi trả miễn phí."}]},{"hanzi":"种类","pinyin":"zhǒnglèi","pos":"dt.","vn":"chủng loại, loại","examples":[{"cn":"这家书店的图书种类非常齐全，各种外文书也能买到。","pinyin":"Zhè jiā shūdiàn de túshū zhǒnglèi fēicháng qíquán, gèzhǒng wàiwénshū yě néng mǎidào.","vn":"Chủng loại sách ở hiệu sách này vô cùng phong phú, các loại sách ngoại văn cũng có thể mua được."},{"cn":"秋天水果的种类特别多，苹果、梨、葡萄都很新鲜。","pinyin":"Qiūtiān shuǐguǒ de zhǒnglèi tèbié duō, píngguǒ, lí, pútao dōu hěn xīnxiān.","vn":"Mùa thu chủng loại trái cây đặc biệt nhiều, táo, lê, nho đều rất tươi."},{"cn":"随着科技发展，电子产品的种类越来越丰富。","pinyin":"Suízhe kējì fāzhǎn, diànzǐ chǎnpǐn de zhǒnglèi yuè lái yuè fēngfù.","vn":"Cùng với sự phát triển của khoa học công nghệ, chủng loại sản phẩm điện tử ngày càng đa dạng."}]},{"hanzi":"盲盒","pinyin":"mánghé","pos":"dt.","vn":"hộp mù (blind box)","examples":[{"cn":"拆盲盒时那种未知的惊喜感吸引了很多年轻人。","pinyin":"Chāi mánghé shí nà zhǒng wèizhī de jīngxǐgǎn xīyǐn le hěn duō niánqīngrén.","vn":"Cảm giác bất ngờ chưa biết trước khi mở hộp mù đã thu hút rất nhiều người trẻ."},{"cn":"博物馆推出了文物主题盲盒，刚上架就被抢购一空。","pinyin":"Bówùguǎn tuīchū le wénwù zhǔtí mánghé, gāng shàngjià jiù bèi qiǎnggòu yìkōng.","vn":"Bảo tàng ra mắt hộp mù chủ đề cổ vật, vừa lên kệ đã bị mua sạch."},{"cn":"买盲盒要理性消费，不要为了凑齐一整套花太多钱。","pinyin":"Mǎi mánghé yào lǐxìng xiāofèi, búyào wèile còuqí yì zhěngtào huā tài duō qián.","vn":"Mua hộp mù cần tiêu dùng lý trí, đừng vì sưu tầm đủ một bộ mà tiêu quá nhiều tiền."}]},{"hanzi":"缺","pinyin":"quē","pos":"dgt.","vn":"thiếu, hết hàng","examples":[{"cn":"这道菜吃起来好像缺了一点儿盐。","pinyin":"Zhè dào cài chī qǐlai hǎoxiàng quē le yìdiǎnr yán.","vn":"Món này ăn vào hình như thiếu một chút muối."},{"cn":"因为太受欢迎，这种限量版玩具现在到处都缺货。","pinyin":"Yīnwèi tài shòu huānyíng, zhè zhǒng xiànliàngbǎn wánjù xiànzài dàochù dōu quēhuò.","vn":"Vì quá được yêu thích nên món đồ chơi phiên bản giới hạn này giờ đi đâu cũng hết hàng."},{"cn":"这个团队现在最缺的就是有经验的设计师。","pinyin":"Zhège tuánduì xiànzài zuì quē de jiù shì yǒu jīngyàn de shèjìshī.","vn":"Điều nhóm này đang thiếu nhất hiện nay chính là nhà thiết kế có kinh nghiệm."}]},{"hanzi":"许多","pinyin":"xǔduō","pos":"số.","vn":"rất nhiều, nhiều","examples":[{"cn":"公园里种着许多百年老树，风景非常优美。","pinyin":"Gōngyuán lǐ zhòngzhe xǔduō bǎinián lǎoshù, fēngjǐng fēicháng yōuměi.","vn":"Trong công viên trồng rất nhiều cây cổ thụ trăm năm tuổi, phong cảnh vô cùng tươi đẹp."},{"cn":"通过这次实习，我学到了许多书本上没有的实践知识。","pinyin":"Tōngguò zhè cì shíxí, wǒ xuédào le xǔduō shūběn shang méiyǒu de shíjiàn zhīshi.","vn":"Qua đợt thực tập lần này, tôi đã học được rất nhiều kiến thức thực tế không có trong sách vở."},{"cn":"每天早上都有许多老人在广场上打太极拳。","pinyin":"Měitiān zǎoshang dōu yǒu xǔduō lǎorén zài guǎngchǎng shang dǎ tàijíquán.","vn":"Mỗi sáng đều có rất nhiều người cao tuổi tập Thái cực quyền trên quảng trường."}]},{"hanzi":"表示","pinyin":"biǎoshì","pos":"dgt.","vn":"bày tỏ, cho biết, biểu thị","examples":[{"cn":"他对朋友的热情帮助表示衷心的感谢。","pinyin":"Tā duì péngyou de rèqíng bāngzhù biǎoshì zhōngxīn de gǎnxiè.","vn":"Anh ấy bày tỏ lòng cảm ơn chân thành trước sự giúp đỡ nhiệt tình của bạn bè."},{"cn":"高医生表示，只要按时吃药、好好休息，很快就能康复。","pinyin":"Gāo yīshēng biǎoshì, zhǐyào ànshí chīyào, hǎohǎo xiūxi, hěn kuài jiù néng kāngfù.","vn":"Bác sĩ Cao cho biết chỉ cần uống thuốc đúng giờ và nghỉ ngơi tốt thì sẽ sớm bình phục."},{"cn":"在汉语里，红色常常表示喜庆和吉祥。","pinyin":"Zài Hànyǔ lǐ, hóngsè chángcháng biǎoshì xǐqìng hé jíxiáng.","vn":"Trong tiếng Trung, màu đỏ thường biểu thị sự vui mừng và may mắn."}]},{"hanzi":"加上","pinyin":"jiāshàng","pos":"liên.","vn":"cộng thêm, hơn nữa, thêm vào đó","examples":[{"cn":"今天本来就降温了，加上又刮大风，外面冷极了。","pinyin":"Jīntiān běnlái jiù jiàngwēn le, jiāshàng yòu guā dàfēng, wàimiàn lěng jí le.","vn":"Hôm nay vốn đã giảm nhiệt độ rồi, cộng thêm gió thổi mạnh nên ngoài trời lạnh cóng."},{"cn":"这家饭馆菜好吃，加上环境安静，很适合朋友聚餐。","pinyin":"Zhè jiā fànguǎn cài hǎochī, jiāshàng huánjìng ānjìng, hěn shìhé péngyou jùcān.","vn":"Quán ăn này đồ ăn ngon, thêm vào đó không gian yên tĩnh, rất thích hợp cho bạn bè tụ tập ăn uống."},{"cn":"她专业基础扎实，加上沟通能力强，很快就通过了面试。","pinyin":"Tā zhuānyè jīchǔ zhāshi, jiāshàng gōutōng nénglì qiáng, hěn kuài jiù tōngguò le miànshì.","vn":"Cô ấy có nền tảng chuyên môn vững chắc, lại thêm khả năng giao tiếp tốt nên nhanh chóng vượt qua buổi phỏng vấn."}]},{"hanzi":"态度","pinyin":"tàidù","pos":"dt.","vn":"thái độ","examples":[{"cn":"这家店服务员的服务态度特别好，每次来都很舒心。","pinyin":"Zhè jiā diàn fúwùyuán de fúwù tàidù tèbié hǎo, měi cì lái dōu hěn shūxīn.","vn":"Thái độ phục vụ của nhân viên quán này đặc biệt tốt, mỗi lần đến đều rất thoải mái."},{"cn":"对待学习和工作，我们都应该保持认真的态度。","pinyin":"Duìdài xuéxí hé gōngzuò, wǒmen dōu yīnggāi bǎochí rènzhēn de tàidù.","vn":"Đối với việc học và công việc, chúng ta đều nên giữ thái độ nghiêm túc."},{"cn":"面对突发困难，他依然保持着积极乐观的态度。","pinyin":"Miànduì tūfā kùnnan, tā yīrán bǎochí zhe jījí lèguān de tàidù.","vn":"Đối mặt với khó khăn bất ngờ, anh ấy vẫn giữ thái độ tích cực và lạc quan."}]},{"hanzi":"友好","pinyin":"yǒuhǎo","pos":"tt.","vn":"thân thiện, hữu nghị","examples":[{"cn":"这里的居民非常热情友好，经常主动帮助游客指路。","pinyin":"Zhèlǐ de jūmín fēicháng rèqíng yǒuhǎo, jīngcháng zhǔdòng bāngzhù yóukè zhǐlù.","vn":"Người dân ở đây vô cùng nhiệt tình và thân thiện, thường chủ động chỉ đường giúp du khách."},{"cn":"中越两国人民之间有着悠久的友好关系。","pinyin":"Zhōng-Yuè liǎng guó rénmín zhījiān yǒuzhe yōujiǔ de yǒuhǎo guānxì.","vn":"Nhân dân hai nước Trung - Việt có mối quan hệ hữu nghị lâu đời."},{"cn":"新来的同事性格很友好，很快就和大家打成一片了。","pinyin":"Xīnlái de tóngshì xìnggé hěn yǒuhǎo, hěn kuài jiù hé dàjiā dǎchéng yípiàn le.","vn":"Đồng nghiệp mới đến tính tình rất thân thiện, nhanh chóng hòa nhập với mọi người."}]},{"hanzi":"使得","pinyin":"shǐde","pos":"dgt.","vn":"khiến cho, làm cho","examples":[{"cn":"高铁的开通使得两座城市之间的交通变得十分便利。","pinyin":"Gāotiě de kāitōng shǐde liǎng zuò chéngshì zhījiān de jiāotōng biànde shífēn biànlì.","vn":"Việc thông tuyến tàu cao tốc khiến cho giao thông giữa hai thành phố trở nên vô cùng thuận tiện."},{"cn":"一场突如其来的大雨使得运动会不得不推迟举行。","pinyin":"Yì chǎng tūrúqílái de dàyǔ shǐde yùndònghuì bùdébù tuīchí jǔxíng.","vn":"Một cơn mưa lớn bất ngờ khiến cho hội thao buộc phải hoãn lại."},{"cn":"店主用心的经营使得这家小店在当地小有名气。","pinyin":"Diànzhǔ yòngxīn de jīngyíng shǐde zhè jiā xiǎodiàn zài dāngdì xiǎoyǒumíngqì.","vn":"Sự kinh doanh tận tâm của chủ tiệm khiến cho cửa hàng nhỏ này khá nổi tiếng ở địa phương."}]},{"hanzi":"者","pinyin":"zhě","pos":"trợ.","vn":"người..., kẻ... (dùng sau động từ hoặc tính từ để chỉ người)","examples":[{"cn":"作为一名理性购物者，他从来不买用不着的东西。","pinyin":"Zuòwéi yì míng lǐxìng gòuwùzhě, tā cónglái bù mǎi yòngbuzháo de dōngxi.","vn":"Là một người mua sắm lý trí, anh ấy chưa bao giờ mua những thứ không dùng đến."},{"cn":"这本书的作者是一位非常有名的儿童文学作家。","pinyin":"Zhè běn shū de zuòzhě shì yí wèi fēicháng yǒumíng de értóng wénxué zuòjiā.","vn":"Tác giả của cuốn sách này là một nhà văn viết cho thiếu nhi vô cùng nổi tiếng."},{"cn":"这次马拉松的参赛者来自全国三十多个城市。","pinyin":"Zhè cì mǎlāsōng de cānsàizhě láizì quánguó sānshí duō ge chéngshì.","vn":"Những người tham gia giải marathon lần này đến từ hơn ba mươi thành phố trên cả nước."}]},{"hanzi":"仔细","pinyin":"zǐxì","pos":"tt.","vn":"cẩn thận, kỹ lưỡng","examples":[{"cn":"交卷之前，请大家再仔细检查一遍答题卡。","pinyin":"Jiāojuàn zhīqián, qǐng dàjiā zài zǐxì jiǎnchá yíbiàn dátíkǎ.","vn":"Trước khi nộp bài, mọi người hãy kiểm tra kỹ lại phiếu trả lời một lần nữa."},{"cn":"签合同之前一定要把每一条内容都仔细看清楚。","pinyin":"Qiān hétong zhīqián yídìng yào bǎ měi yì tiáo nèiróng dōu zǐxì kàn qīngchu.","vn":"Trước khi ký hợp đồng nhất định phải đọc thật kỹ từng điều khoản một."},{"cn":"她做事一向非常仔细，很少出什么差错。","pinyin":"Tā zuòshì yíxiàng fēicháng zǐxì, hěn shǎo chū shénme chācuò.","vn":"Cô ấy làm việc trước nay luôn rất cẩn thận, hiếm khi xảy ra sai sót gì."}]},{"hanzi":"对于","pinyin":"duìyú","pos":"giới.","vn":"đối với, về","examples":[{"cn":"对于这个问题，不同的人可能会有不同的看法。","pinyin":"Duìyú zhège wèntí, bùtóng de rén kěnéng huì yǒu bùtóng de kànfǎ.","vn":"Đối với vấn đề này, những người khác nhau có thể có cách nhìn khác nhau."},{"cn":"对于刚开始学中文的外国学生来说，声调比较难掌握。","pinyin":"Duìyú gāng kāishǐ xué Zhōngwén de wàiguó xuésheng láishuō, shēngdiào bǐjiào nán zhǎngwò.","vn":"Đối với du học sinh nước ngoài mới bắt đầu học tiếng Trung, thanh điệu tương đối khó nắm vững."},{"cn":"对于你们提出的宝贵意见，公司会认真考虑。","pinyin":"Duìyú nǐmen tíchū de bǎoguì yìjiàn, gōngsī huì rènzhēn kǎolǜ.","vn":"Về những ý kiến quý báu mà các bạn đưa ra, công ty sẽ nghiêm túc xem xét."}]},{"hanzi":"不光","pinyin":"bùguāng","pos":"liên./phó.","vn":"không những, không chỉ","examples":[{"cn":"这座公园不光风景优美，而且免费向市民开放。","pinyin":"Zhè zuò gōngyuán bùguāng fēngjǐng yōuměi, érqiě miǎnfèi xiàng shìmín kāifàng.","vn":"Công viên này không những phong cảnh đẹp mà còn mở cửa miễn phí cho người dân."},{"cn":"他不光会说英语和汉语，还会说一点儿法语。","pinyin":"Tā bùguāng huì shuō Yīngyǔ hé Hànyǔ, hái huì shuō yìdiǎnr Fǎyǔ.","vn":"Anh ấy không chỉ biết nói tiếng Anh và tiếng Trung, mà còn biết nói một chút tiếng Pháp."},{"cn":"这件事不光我一个人反对，其他同事也觉得不太合适。","pinyin":"Zhè jiàn shì bùguāng wǒ yí ge rén fǎnduì, qítā tóngshì yě juéde bú tài héshì.","vn":"Chuyện này không chỉ một mình tôi phản đối, các đồng nghiệp khác cũng thấy không được phù hợp lắm."}]},{"hanzi":"外套","pinyin":"wàitào","pos":"dt.","vn":"áo khoác","examples":[{"cn":"早晚天气比较凉，出门时记得多带一件外套。","pinyin":"Zǎowǎn tiānqì bǐjiào liáng, chūmén shí jìde duō dài yí jiàn wàitào.","vn":"Sáng sớm và buổi tối trời khá mát, ra ngoài nhớ mang thêm một chiếc áo khoác."},{"cn":"这件米白色的外套配你的裙子真好看。","pinyin":"Zhè jiàn mǐbáisè de wàitào pèi nǐ de qúnzi zhēn hǎokàn.","vn":"Chiếc áo khoác màu trắng kem này phối với váy của cậu thật đẹp."},{"cn":"进屋以后暖和多了，快把厚外套脱下来挂好吧。","pinyin":"Jìnwū yǐhòu nuǎnhuo duō le, kuài bǎ hòu wàitào tuō xiàlai guàhǎo ba.","vn":"Vào trong nhà ấm hơn nhiều rồi, mau cởi áo khoác dày ra treo lên đi."}]},{"hanzi":"袜子","pinyin":"wàzi","pos":"dt.","vn":"tất, vớ","examples":[{"cn":"冬天穿一双厚厚的羊毛袜子，脚就不会冷了。","pinyin":"Dōngtiān chuān yì shuāng hòuhòu de yángmáo wàzi, jiǎo jiù bú huì lěng le.","vn":"Mùa đông đi một đôi tất len dày thì chân sẽ không bị lạnh nữa."},{"cn":"我在商场顺便买了几双纯棉的运动袜子。","pinyin":"Wǒ zài shāngchǎng shùnbiàn mǎi le jǐ shuāng chúnmián de yùndòng wàzi.","vn":"Ở trung tâm thương mại tôi tiện thể mua mấy đôi tất thể thao cotton nguyên chất."},{"cn":"你看见我另一只白色的袜子掉在哪儿了吗？","pinyin":"Nǐ kànjiàn wǒ lìng yì zhī báisè de wàzi diào zài nǎr le ma?","vn":"Cậu có thấy chiếc tất màu trắng còn lại của mình rơi ở đâu không?"}]}],"grammar":[{"title":"语气副词\"究竟\"","explanation_vn":"Phó từ ngữ khí \"究竟\" được dùng trong câu hỏi để nhấn mạnh ý truy hỏi, muốn tìm hiểu cho ra nhẽ hoặc có câu trả lời xác thực.","examples":[{"cn":"这里茶叶这么多，究竟买哪种好呢？","pinyin":"Zhèlǐ cháyè zhème duō, jiūjìng mǎi nǎ zhǒng hǎo ne?","vn":"Ở đây nhiều loại trà như vậy, rốt cuộc nên mua loại nào đây?"},{"cn":"我一直没找到他，他究竟去哪里了呢？","pinyin":"Wǒ yìzhí méi zhǎodào tā, tā jiūjìng qù nǎlǐ le ne?","vn":"Tôi mãi không tìm thấy anh ấy, rốt cuộc anh ấy đã đi đâu rồi?"},{"cn":"究竟是对还是错？我现在也不清楚。","pinyin":"Jiūjìng shì duì háishì cuò? Wǒ xiànzài yě bù qīngchu.","vn":"Rốt cuộc là đúng hay sai? Bây giờ tôi cũng không rõ nữa."}]},{"title":"承接复句\"首先……，然后/其次……\"","explanation_vn":"Câu phức liên tiếp \"首先……，然后/其次……\" biểu thị trình tự trước sau của hành động, sự việc hoặc phân biệt thứ tự chính phụ.","examples":[{"cn":"首先看样子喜不喜欢，然后再看质量怎么样、价格合适不合适。","pinyin":"Shǒuxiān kàn yàngzi xǐ bu xǐhuan, ránhòu zài kàn zhìliàng zěnmeyàng, jiàgé héshì bu héshì.","vn":"Trước tiên xem kiểu dáng có thích không, sau đó mới xem chất lượng thế nào, giá cả có phù hợp hay không."},{"cn":"遇到问题，首先想想问题为什么出现，然后再积极想办法解决。","pinyin":"Yùdào wèntí, shǒuxiān xiǎngxiang wèntí wèishénme chūxiàn, ránhòu zài jījí xiǎng bànfǎ jiějué.","vn":"Gặp vấn đề thì trước tiên hãy nghĩ xem tại sao vấn đề xuất hiện, sau đó mới tích cực tìm cách giải quyết."},{"cn":"请大家首先读一遍课文，然后根据课文完成课后练习。","pinyin":"Qǐng dàjiā shǒuxiān dú yí biàn kèwén, ránhòu gēnjù kèwén wánchéng kèhòu liànxí.","vn":"Mời mọi người trước tiên đọc bài khóa một lượt, sau đó dựa vào bài khóa hoàn thành bài tập sau bài."}]},{"title":"连词\"加上\"","explanation_vn":"Liên từ \"加上\" nối tiếp vế câu trước để bổ sung thêm một nhân tố nữa, vế câu phía sau thường nêu ra kết quả.","examples":[{"cn":"小店虽然小，但东西适合年轻人，加上店员态度友好，使得小店的生意越来越好。","pinyin":"Xiǎodiàn suīrán xiǎo, dàn dōngxi shìhé niánqīngrén, jiāshàng diànyuán tàidù yǒuhǎo, shǐde xiǎodiàn de shēngyi yuèláiyuè hǎo.","vn":"Cửa hàng tuy nhỏ nhưng đồ đạc phù hợp với giới trẻ, cộng thêm thái độ nhân viên thân thiện, khiến việc kinh doanh của cửa hàng ngày càng phát đạt."},{"cn":"虽然这里是郊区，但周围交通很方便，加上房租便宜，所以很多年轻人都在这里租房子。","pinyin":"Suīrán zhèlǐ shì jiāoqū, dàn zhōuwéi jiāotōng hěn fāngbiàn, jiāshàng fángzū piányi, suǒyǐ hěn duō niánqīngrén dōu zài zhèlǐ zū fángzi.","vn":"Tuy đây là vùng ngoại ô nhưng giao thông xung quanh rất thuận tiện, cộng thêm tiền thuê nhà rẻ, nên rất nhiều người trẻ đều thuê nhà ở đây."},{"cn":"他很聪明，加上一直非常努力，所以最后考上了理想的大学。","pinyin":"Tā hěn cōngming, jiāshàng yìzhí fēicháng nǔlì, suǒyǐ zuìhòu kǎoshàngle lǐxiǎng de dàxué.","vn":"Cậu ấy rất thông minh, cộng thêm luôn nỗ lực hết mình, nên cuối cùng đã thi đỗ vào trường đại học mơ ước."}]},{"title":"介词\"对于\"","explanation_vn":"Giới từ \"对于\" dùng để dẫn ra đối tượng cụ thể (người, sự việc, sự vật...) mà động tác, hành vi đề cập tới.","examples":[{"cn":"对于想买的东西，她不光看质量，还看价格。","pinyin":"Duìyú xiǎng mǎi de dōngxi, tā bùguāng kàn zhìliàng, hái kàn jiàgé.","vn":"Đối với món đồ muốn mua, cô ấy không chỉ xem chất lượng mà còn xem cả giá cả."},{"cn":"对于他的做法，大家都很支持。","pinyin":"Duìyú tā de zuòfǎ, dàjiā dōu hěn zhīchí.","vn":"Đối với cách làm của anh ấy, mọi người đều rất ủng hộ."},{"cn":"对于你们提的这个建议，我们一定好好研究。","pinyin":"Duìyú nǐmen tí de zhège jiànyì, wǒmen yídìng hǎohāo yánjiū.","vn":"Về đề xuất này mà các bạn đưa ra, chúng tôi nhất định sẽ nghiên cứu kỹ lưỡng."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"售货员","cn":"您要什么茶？","pinyin":"Nín yào shénme chá?"},{"speaker":"安妮","cn":"我先看看。这里茶叶这么多，究竟买哪种好呢？","pinyin":"Wǒ xiān kànkan. Zhèlǐ cháyè zhème duō, jiūjìng mǎi nǎ zhǒng hǎo ne?"},{"speaker":"售货员","cn":"茶叶主要分为红茶、绿茶等，看您喜欢喝哪种。","pinyin":"Cháyè zhǔyào fēnwéi hóngchá, lǜchá děng, kàn nín xǐhuan hē nǎ zhǒng."},{"speaker":"安妮","cn":"我想买一些自己喝，再买些送人。这种绿茶还有吗？","pinyin":"Wǒ xiǎng mǎi yìxiē zìjǐ hē, zài mǎi xiē sòng rén. Zhè zhǒng lǜchá hái yǒu ma?"},{"speaker":"售货员","cn":"抱歉，暂时没有。如果自己喝，可以买这个绿茶，今天满二两送半两，超过半斤再送小礼物；如果送人，可以买个盒子装进去。","pinyin":"Bàoqiàn, zànshí méiyǒu. Rúguǒ zìjǐ hē, kěyǐ mǎi zhège lǜchá, jīntiān mǎn èr liǎng sòng bàn liǎng, chāoguò bàn jīn zài sòng xiǎo lǐwù; rúguǒ sòng rén, kěyǐ mǎi ge hézi zhuāng jìnqù."},{"speaker":"安妮","cn":"嗯。那就先买六两这种绿茶吧，再买一个盒子。请帮我分着装，盒子里装半斤，剩下的用纸包一下就行。","pinyin":"Ng. Nà jiù xiān mǎi liù liǎng zhè zhǒng lǜchá ba, zài mǎi yí ge hézi. Qǐng bāng wǒ fēnzhe zhuāng, hézi lǐ zhuāng bàn jīn, shèngxià de yòng zhǐ bāo yíxià jiù xíng."}],"translation_vn":"Nhân viên bán hàng: Quý khách muốn mua trà gì ạ?\nAnnie: Tôi xem trước đã. Ở đây nhiều trà thế này, rốt cuộc nên mua loại nào tốt nhỉ?\nNhân viên bán hàng: Trà chủ yếu chia thành hồng trà, trà xanh,... tùy xem quý khách thích uống loại nào.\nAnnie: Tôi muốn mua một ít để tự uống, rồi mua thêm ít nữa mang đi biếu. Loại trà xanh này còn không ạ?\nNhân viên bán hàng: Xin lỗi, tạm thời hết rồi ạ. Nếu tự uống thì quý khách có thể mua loại trà xanh này, hôm nay mua đủ hai lạng tặng nửa lạng, trên nửa cân tặng thêm quà nhỏ; còn nếu mang biếu thì có thể mua một cái hộp đựng vào.\nAnnie: Ừm. Vậy thì mua trước sáu lạng trà xanh này đi, mua thêm một cái hộp nữa. Làm ơn đóng riêng giúp tôi, trong hộp đựng nửa cân, chỗ còn lại gói giấy một chút là được.","audio_dialogue":"14-1.mp3","audio_vocab":"14-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"广播员","cn":"各位顾客，本商场正在举办运动鞋假日低价促销活动，全场五折。","pinyin":"Gèwèi gùkè, běn shāngchǎng zhèngzài jǔbàn yùndòngxié jiàrì dījià cùxiāo huódòng, quánchǎng wǔ zhé."},{"speaker":"王一雪","cn":"一飞，广播里说价格减了一半呢，咱们过去看看？","pinyin":"Yīfēi, guǎngbō lǐ shuō jiàgé jiǎnle yíbàn ne, zánmen guòqù kànkan?"},{"speaker":"王一飞","cn":"好的。不过咱们也不能只听广告说什么，还得看质量。","pinyin":"Hǎo de. Búguò zánmen yě bù néng zhǐ tīng guǎnggào shuō shénme, hái děi kàn zhìliàng."},{"speaker":"王一雪","cn":"对，首先看样子喜不喜欢，然后再看质量怎么样、价格合适不合适。","pinyin":"Duì, shǒuxiān kàn yàngzi xǐ bu xǐhuan, ránhòu zài kàn zhìliàng zěnmeyàng, jiàgé héshì bu héshì."},{"speaker":"售货员","cn":"二位看看喜欢哪双？这个牌子质量很好，今天又降价，一双减300块。","pinyin":"Èrwèi kànkan xǐhuan nǎ shuāng? Zhège páizi zhìliàng hěn hǎo, jīntiān yòu jiàngjià, yì shuāng jiǎn sānbǎi kuài."},{"speaker":"王一雪","cn":"嗯，我知道这个牌子。一飞，你喜欢吗？你看，这个鞋的样式很新，价钱也不高。","pinyin":"Ng, wǒ zhīdào zhège páizi. Yīfēi, nǐ xǐhuan ma? Nǐ kàn, zhège xié de yàngshì hěn xīn, jiàqián yě bù gāo."},{"speaker":"王一飞","cn":"你喜欢就买吧。我再看看别的。","pinyin":"Nǐ xǐhuan jiù mǎi ba. Wǒ zài kànkan biéde."},{"speaker":"王一雪","cn":"好的。请给我拿一双37号的吧。","pinyin":"Hǎo de. Qǐng gěi wǒ ná yì shuāng sānshíqī hào de ba."}],"translation_vn":"Phát thanh viên: Kính thưa quý khách, trung tâm thương mại chúng tôi đang tổ chức chương trình khuyến mãi giá rẻ ngày lễ cho giày thể thao, giảm giá 50% toàn khu vực.\nVương Nhất Tuyết: Nhất Phi, trên loa nói giảm hẳn một nửa giá đấy, chúng mình sang xem thử không?\nVương Nhất Phi: Được thôi. Nhưng chúng ta cũng không thể chỉ nghe quảng cáo nói gì, còn phải xem chất lượng nữa.\nVương Nhất Tuyết: Đúng vậy, trước tiên xem kiểu dáng có thích không, sau đó mới xem chất lượng thế nào, giá cả có phù hợp hay không.\nNhân viên bán hàng: Hai chị xem thử thích đôi nào ạ? Thương hiệu này chất lượng rất tốt, hôm nay lại đang giảm giá, mỗi đôi giảm 300 tệ.\nVương Nhất Tuyết: Ừm, tôi biết thương hiệu này. Nhất Phi, cậu có thích không? Cậu nhìn xem, kiểu dáng đôi giày này rất mới, giá tiền cũng không cao.\nVương Nhất Phi: Cậu thích thì cứ mua đi. Mình xem thêm các mẫu khác nữa.\nVương Nhất Tuyết: Được. Làm ơn lấy cho tôi một đôi cỡ 37 nhé.","audio_dialogue":"14-3.mp3","audio_vocab":"14-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"李文的朋友徐前在商业区开了家小店，专门卖年轻人喜欢的东西。他的店里商品种类不少，既有几十年前的老游戏机，也有最近流行的盲盒等等，很吸引年轻人。","pinyin":"Lǐ Wén de péngyou Xú Qián zài shāngyèqū kāile jiā xiǎodiàn, zhuānmén mài niánqīngrén xǐhuan de dōngxi. Tā de diànlǐ shāngpǐn zhǒnglèi bùshǎo, jì yǒu jǐshí nián qián de lǎo yóuxìjī, yě yǒu zuìjìn liúxíng de mánghé děngděng, hěn xīyǐn niánqīngrén."},{"speaker":"","cn":"徐前说，自己就是年轻人，知道年轻人喜欢什么。他也常和来店里的年轻顾客聊天儿，了解他们的兴趣爱好。前段时间刚进的盲盒很快就卖到了缺货。许多年轻人表示，在徐前的店里能感受到快乐。小店虽然小，但东西适合年轻人，加上店员态度友好，使得小店的生意越来越好。李文觉得自己的朋友真会做生意。","pinyin":"Xú Qián shuō, zìjǐ jiùshì niánqīngrén, zhīdào niánqīngrén xǐhuan shénme. Tā yě cháng hé lái diànlǐ de niánqīng gùkè liáotiānr, liǎojiě tāmen de xìngqù àihào. Qiánduàn shíjiān gāng jìn de mánghé hěn kuài jiù màidàole quēhuò. Xǔduō niánqīngrén biǎoshì, zài Xú Qián de diànlǐ néng gǎnshòudào kuàilè. Xiǎodiàn suīrán xiǎo, dàn dōngxi shìhé niánqīngrén, jiāshàng diànyuán tàidù yǒuhǎo, shǐde xiǎodiàn de shēngyi yuèláiyuè hǎo. Lǐ Wén juéde zìjǐ de péngyou zhēn huì zuò shēngyi."}],"translation_vn":"Từ Tiền, bạn của Lý Văn, đã mở một cửa hàng nhỏ ở khu thương mại, chuyên bán những món đồ mà giới trẻ yêu thích. Chủng loại hàng hóa trong cửa hàng của anh không ít, vừa có máy chơi game cổ từ mấy chục năm trước, lại vừa có hộp mù đang thịnh hành gần đây,..., rất thu hút các bạn trẻ.\nTừ Tiền nói rằng bản thân anh cũng là người trẻ nên biết giới trẻ thích gì. Anh cũng thường trò chuyện với các vị khách trẻ đến cửa hàng để tìm hiểu sở thích của họ. Những chiếc hộp mù vừa nhập về cách đây không lâu đã nhanh chóng bán đến mức hết hàng. Rất nhiều bạn trẻ cho biết họ có thể cảm nhận được niềm vui khi ở trong cửa hàng của Từ Tiền. Cửa hàng tuy nhỏ nhưng hàng hóa phù hợp với giới trẻ, cộng thêm thái độ nhân viên thân thiện, khiến việc kinh doanh của cửa hàng ngày càng phát đạt. Lý Văn cảm thấy bạn mình thật sự rất biết cách làm ăn.","audio_dialogue":"14-5.mp3","audio_vocab":"14-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"关于购物，你是一位冷静购物者，还是不冷静购物者？一般来说，冷静购物者往往是真正需要一件东西时才买。购买时，还会从质量、价格等各方面仔细比较。不冷静购物者看见一个东西时，只要感觉喜欢就买，不管需要不需要，结果常常买完就后悔，买的东西也成了“垃圾”，还不环保。王一飞说，她从来不随便买东西。对于想买的东西，她不光看质量，还看价格。无论是一件外套，还是一条裤子，甚至一双袜子，都是仔细比较后才决定买不买。","pinyin":"Guānyú gòuwù, nǐ shì yí wèi lěngjìng gòuwùzhě, háishì bù lěngjìng gòuwùzhě? Yìbān láishuō, lěngjìng gòuwùzhě wǎngwǎng shì zhēnzhèng xūyào yí jiàn dōngxi shí cái mǎi. Gòumǎi shí, hái huì cóng zhìliàng, jiàgé děng gè fāngmiàn zǐxì bǐjiào. Bù lěngjìng gòuwùzhě kànjiàn yí ge dōngxi shí, zhǐyào gǎnjué xǐhuan jiù mǎi, bùguǎn xūyào bù xūyào, jiéguǒ chángcháng mǎiwán jiù hòuhuǐ, mǎi de dōngxi yě chéngle \"lājī\", hái bù huánbǎo. Wáng Yīfēi shuō, tā cónglái bù suíbiàn mǎi dōngxi. Duìyú xiǎng mǎi de dōngxi, tā bùguāng kàn zhìliàng, hái kàn jiàgé. Wúlùn shì yí jiàn wàitào, háishì yì tiáo kùzi, shènzhì yì shuāng wàzi, dōu shì zǐxì bǐjiào hòu cái juédìng mǎi bu mǎi."},{"speaker":"","cn":"其实，不仅是买东西，人生的很多事情都一样，选择合适的才是最好的。","pinyin":"Qíshí, bùjǐn shì mǎi dōngxi, rénshēng de hěn duō shìqing dōu yíyàng, xuǎnzé héshì de cái shì zuì hǎo de."}],"translation_vn":"Về việc mua sắm, bạn là một người mua sắm điềm tĩnh hay là người mua sắm thiếu kiềm chế? Thông thường, người mua sắm điềm tĩnh thường chỉ mua khi thật sự cần một món đồ nào đó. Khi mua, họ còn so sánh cẩn thận về mọi mặt như chất lượng, giá cả,... Người mua sắm thiếu kiềm chế khi nhìn thấy một món đồ, chỉ cần cảm thấy thích là mua, chẳng màng có cần hay không, kết quả thường mua xong lại hối hận, món đồ mua về cũng trở thành \"rác\", lại còn không thân thiện với môi trường. Vương Nhất Phi nói cô ấy chưa bao giờ mua đồ tùy tiện. Đối với món đồ muốn mua, cô ấy không chỉ xem chất lượng mà còn xem cả giá cả. Bất kể là một chiếc áo khoác, một chiếc quần, hay thậm chí là một đôi tất, đều phải so sánh kỹ lưỡng rồi mới quyết định có mua hay không.\nThực ra, không chỉ riêng việc mua đồ, rất nhiều việc trong cuộc đời cũng đều như vậy, chọn điều phù hợp mới là tốt nhất.","audio_dialogue":"14-7.mp3","audio_vocab":"14-8.mp3"}]},{"id":15,"title_cn":"我去应聘了","title_pinyin":"Wǒ qù yìngpìn le","title_vn":"Tôi đã đi ứng tuyển rồi","goals":["Có thể nghe hiểu và trao đổi các thông tin về ứng tuyển, phỏng vấn, thực tập,...","Có thể trình bày bằng lời hoặc bằng văn bản trải nghiệm tìm việc làm.","Hiểu được tình hình thực tập và ý nghĩa của việc thực tập đối với sinh viên đại học Trung Quốc."],"vocab":[{"hanzi":"期中","pinyin":"qīzhōng","pos":"dt.","vn":"giữa kỳ","examples":[{"cn":"下周就要进行期中考试了。","pinyin":"Xià zhōu jiù yào jìnxíng qīzhōng kǎoshì le.","vn":"Tuần sau là phải thi giữa kỳ rồi."},{"cn":"这次期中成绩我比上次进步了不少。","pinyin":"Zhè cì qīzhōng chéngjì wǒ bǐ shàng cì jìnbù le bùshǎo.","vn":"Điểm giữa kỳ lần này của tôi tiến bộ khá nhiều so với lần trước."},{"cn":"期中以后，学校会安排一些社会实践活动。","pinyin":"Qīzhōng yǐhòu, xuéxiào huì ānpái yìxiē shèhuì shíjiàn huódòng.","vn":"Sau giữa kỳ, trường sẽ sắp xếp một số hoạt động thực tiễn xã hội."}]},{"hanzi":"医药","pinyin":"yīyào","pos":"dt.","vn":"y dược, dược phẩm","examples":[{"cn":"他毕业后在一家医药公司工作。","pinyin":"Tā bìyè hòu zài yì jiā yīyào gōngsī gōngzuò.","vn":"Sau khi tốt nghiệp anh ấy làm việc tại một công ty dược phẩm."},{"cn":"近几年中国的医药行业发展很快。","pinyin":"Jìn jǐ nián Zhōngguó de yīyào hángyè fāzhǎn hěn kuài.","vn":"Mấy năm gần đây ngành y dược của Trung Quốc phát triển rất nhanh."},{"cn":"生病住院需要花不少医药费。","pinyin":"Shēngbìng zhùyuàn xūyào huā bùshǎo yīyàofèi.","vn":"Ốm nằm viện cần tốn không ít tiền thuốc men."}]},{"hanzi":"应聘","pinyin":"yìngpìn","pos":"dgt.","vn":"ứng tuyển, nộp đơn xin việc","examples":[{"cn":"他昨天去一家国际公司应聘了。","pinyin":"Tā zuótiān qù yì jiā guójì gōngsī yìngpìn le.","vn":"Hôm qua anh ấy đã đi ứng tuyển ở một công ty quốc tế."},{"cn":"应聘这份工作需要会说两门外语。","pinyin":"Yìngpìn zhè fèn gōngzuò xūyào huì shuō liǎng mén wàiyǔ.","vn":"Ứng tuyển công việc này cần biết nói hai ngoại ngữ."},{"cn":"这次来应聘的大学生特别多。","pinyin":"Zhè cì lái yìngpìn de dàxuéshēng tèbié duō.","vn":"Lần này sinh viên đại học đến ứng tuyển đặc biệt đông."}]},{"hanzi":"招聘","pinyin":"zhāopìn","pos":"dgt.","vn":"tuyển dụng","examples":[{"cn":"我们公司正在招聘中文翻译。","pinyin":"Wǒmen gōngsī zhèngzài zhāopìn Zhōngwén fānyì.","vn":"Công ty chúng tôi đang tuyển dụng phiên dịch tiếng Trung."},{"cn":"我在网上看到了一条招聘信息。","pinyin":"Wǒ zài wǎngshang kàndào le yì tiáo zhāopìn xìnxī.","vn":"Tôi nhìn thấy một tin tuyển dụng trên mạng."},{"cn":"学校明天会举办一场大型招聘会。","pinyin":"Xuéxiào míngtiān huì jǔbàn yì chǎng dàxíng zhāopìnhuì.","vn":"Ngày mai trường sẽ tổ chức một ngày hội tuyển dụng quy mô lớn."}]},{"hanzi":"实习","pinyin":"shíxí","pos":"dgt.","vn":"thực tập","examples":[{"cn":"我打算暑假去一家银行实习。","pinyin":"Wǒ dǎsuàn shǔjià qù yì jiā yínháng shíxí.","vn":"Tôi dự định kỳ nghỉ hè sẽ đến một ngân hàng thực tập."},{"cn":"这次实习让我学到了很多实用的经验。","pinyin":"Zhè cì shíxí ràng wǒ xuédào le hěn duō shíyòng de jīngyàn.","vn":"Đợt thực tập này giúp tôi học được rất nhiều kinh nghiệm thiết thực."},{"cn":"他在那家医院实习了三个月。","pinyin":"Tā zài nà jiā yīyuàn shíxí le sān ge yuè.","vn":"Anh ấy đã thực tập ở bệnh viện đó ba tháng."}]},{"hanzi":"考虑","pinyin":"kǎolǜ","pos":"dgt.","vn":"cân nhắc, suy xét","examples":[{"cn":"这件事很重要，我需要认真考虑一下。","pinyin":"Zhè jiàn shì hěn zhòngyào, wǒ xūyào rènzhēn kǎolǜ yíxià.","vn":"Việc này rất quan trọng, tôi cần cân nhắc kỹ một chút."},{"cn":"你考虑好毕业以后去哪儿工作了吗？","pinyin":"Nǐ kǎolǜ hǎo bìyè yǐhòu qù nǎr gōngzuò le ma?","vn":"Bạn đã cân nhắc xong sau khi tốt nghiệp sẽ đi đâu làm việc chưa?"},{"cn":"做决定之前，我们要把各种情况都考虑到。","pinyin":"Zuò juédìng zhīqián, wǒmen yào bǎ gèzhǒng qíngkuàng dōu kǎolǜ dào.","vn":"Trước khi đưa ra quyết định, chúng ta phải cân nhắc đến mọi tình huống."}]},{"hanzi":"单位","pinyin":"dānwèi","pos":"dt.","vn":"đơn vị, cơ quan","examples":[{"cn":"他在这家单位工作已经十年了。","pinyin":"Tā zài zhè jiā dānwèi gōngzuò yǐjīng shí nián le.","vn":"Anh ấy đã làm việc ở cơ quan này mười năm rồi."},{"cn":"今天单位组织大家去郊区爬山。","pinyin":"Jīntiān dānwèi zǔzhī dàjiā qù jiāoqū páshān.","vn":"Hôm nay cơ quan tổ chức cho mọi người đi leo núi ở ngoại ô."},{"cn":"每个单位都有自己的管理规定。","pinyin":"Měi ge dānwèi dōu yǒu zìjǐ de guǎnlǐ guīdìng.","vn":"Mỗi đơn vị đều có quy định quản lý của riêng mình."}]},{"hanzi":"毕业生","pinyin":"bìyèshēng","pos":"dt.","vn":"sinh viên tốt nghiệp, người tốt nghiệp","examples":[{"cn":"每年夏天都有很多大学毕业生找工作。","pinyin":"Měi nián xiàtiān dōu yǒu hěn duō dàxué bìyèshēng zhǎo gōngzuò.","vn":"Mỗi mùa hè đều có rất nhiều sinh viên đại học mới tốt nghiệp tìm việc."},{"cn":"这家公司特别欢迎优秀的毕业生加入。","pinyin":"Zhè jiā gōngsī tèbié huānyíng yōuxiù de bìyèshēng jiārù.","vn":"Công ty này đặc biệt hoan nghênh các sinh viên tốt nghiệp xuất sắc gia nhập."},{"cn":"她是今年我们专业的优秀毕业生代表。","pinyin":"Tā shì jīnnián wǒmen zhuānyè de yōuxiù bìyèshēng dàibiǎo.","vn":"Cô ấy là đại diện sinh viên tốt nghiệp xuất sắc năm nay của chuyên ngành chúng tôi."}]},{"hanzi":"经历","pinyin":"jīnglì","pos":"dt./dgt.","vn":"trải nghiệm, kinh nghiệm; trải qua","examples":[{"cn":"这段留学经历对我的人生影响很大。","pinyin":"Zhè duàn liúxué jīnglì duì wǒ de rénshēng yǐngxiǎng hěn dà.","vn":"Trải nghiệm du học này có ảnh hưởng rất lớn đến cuộc đời tôi."},{"cn":"他在中国经历过很多有趣的事情。","pinyin":"Tā zài Zhōngguó jīnglì guo hěn duō yǒuqù de shìqing.","vn":"Anh ấy đã từng trải qua rất nhiều chuyện thú vị ở Trung Quốc."},{"cn":"面试官让我介绍一下自己的工作经历。","pinyin":"Miànshìguān ràng wǒ jièshào yíxià zìjǐ de gōngzuò jīnglì.","vn":"Người phỏng vấn bảo tôi giới thiệu qua về kinh nghiệm làm việc của bản thân."}]},{"hanzi":"消息","pinyin":"xiāoxi","pos":"dt.","vn":"tin tức, thông tin","examples":[{"cn":"我告诉你一个好消息，我通过面试了！","pinyin":"Wǒ gàosu nǐ yí ge hǎo xiāoxi, wǒ tōngguò miànshì le!","vn":"Tôi báo cho bạn một tin vui, tôi đã vượt qua vòng phỏng vấn rồi!"},{"cn":"我等了好几天，还是没收到公司的消息。","pinyin":"Wǒ děng le hǎo jǐ tiān, háishì méi shōudào gōngsī de xiāoxi.","vn":"Tôi đợi mấy ngày rồi mà vẫn chưa nhận được tin tức từ công ty."},{"cn":"听到这个消息，大家都非常高兴。","pinyin":"Tīngdào zhège xiāoxi, dàjiā dōu fēicháng gāoxìng.","vn":"Nghe thấy tin này, mọi người đều vô cùng vui mừng."}]},{"hanzi":"报名","pinyin":"bàomíng","pos":"dgt.","vn":"đăng ký, ghi danh","examples":[{"cn":"我已经报名参加下个月的汉语水平考试了。","pinyin":"Wǒ yǐjīng bàomíng cānjiā xià ge yuè de Hànyǔ Shuǐpíng Kǎoshì le.","vn":"Tôi đã đăng ký tham gia kỳ thi HSK tháng sau rồi."},{"cn":"这个活动可以在网上直接报名。","pinyin":"Zhège huódòng kěyǐ zài wǎngshang zhíjiē bàomíng.","vn":"Hoạt động này có thể đăng ký trực tiếp trên mạng."},{"cn":"报名截止日期是本周五下午五点。","pinyin":"Bàomíng jiézhǐ rìqī shì běn zhōuwǔ xiàwǔ wǔ diǎn.","vn":"Hạn chót đăng ký là năm giờ chiều thứ Sáu tuần này."}]},{"hanzi":"填写","pinyin":"tiánxiě","pos":"dgt.","vn":"điền (thông tin, mẫu đơn)","examples":[{"cn":"请仔细填写这张申请表。","pinyin":"Qǐng zǐxì tiánxiě zhè zhāng shēnqǐngbiǎo.","vn":"Xin vui lòng điền cẩn thận tờ đơn đăng ký này."},{"cn":"报名时需要填写姓名、电话和邮箱。","pinyin":"Bàomíng shí xūyào tiánxiě xìngmíng, diànhuà hé yóuxiāng.","vn":"Khi đăng ký cần điền họ tên, số điện thoại và email."},{"cn":"你的地址填写错了一个字。","pinyin":"Nǐ de dìzhǐ tiánxiě cuò le yí ge zì.","vn":"Địa chỉ của bạn điền sai một chữ rồi."}]},{"hanzi":"笔试","pinyin":"bǐshì","pos":"dgt.","vn":"thi viết","examples":[{"cn":"这次应聘分为笔试和面试两个部分。","pinyin":"Zhè cì yìngpìn fēnwéi bǐshì hé miànshì liǎng ge bùfen.","vn":"Đợt ứng tuyển lần này chia làm hai phần là thi viết và phỏng vấn."},{"cn":"笔试主要考查我们的专业知识和外语水平。","pinyin":"Bǐshì zhǔyào kǎochá wǒmen de zhuānyè zhīshi hé wàiyǔ shuǐpíng.","vn":"Thi viết chủ yếu kiểm tra kiến thức chuyên ngành và trình độ ngoại ngữ của chúng tôi."},{"cn":"他笔试成绩排在第一名。","pinyin":"Tā bǐshì chéngjì pái zài dì yī míng.","vn":"Điểm thi viết của anh ấy đứng hạng nhất."}]},{"hanzi":"面试","pinyin":"miànshì","pos":"dgt.","vn":"phỏng vấn","examples":[{"cn":"明天上午九点我有一个面试。","pinyin":"Míngtiān shàngwǔ jiǔ diǎn wǒ yǒu yí ge miànshì.","vn":"Chín giờ sáng mai tôi có một buổi phỏng vấn."},{"cn":"面试的时候不要紧张，自然一点儿就好。","pinyin":"Miànshì de shíhou búyào jǐnzhāng, zìrán yìdiǎnr jiù hǎo.","vn":"Lúc phỏng vấn đừng căng thẳng, tự nhiên một chút là được."},{"cn":"为了准备面试，他提前了解了很多公司的情况。","pinyin":"Wèile zhǔnbèi miànshì, tā tíqián liǎojiě le hěn duō gōngsī de qíngkuàng.","vn":"Để chuẩn bị phỏng vấn, anh ấy đã tìm hiểu trước rất nhiều thông tin về công ty."}]},{"hanzi":"答","pinyin":"dá","pos":"dgt.","vn":"trả lời, đáp","examples":[{"cn":"这道题他答得非常准确。","pinyin":"Zhè dào tí tā dá de fēicháng zhǔnquè.","vn":"Câu hỏi này cậu ấy trả lời vô cùng chính xác."},{"cn":"考试时间到了，我还有两道题没答完。","pinyin":"Kǎoshì shíjiān dào le, wǒ hái yǒu liǎng dào tí méi dá wán.","vn":"Hết giờ làm bài rồi, tôi vẫn còn hai câu chưa trả lời xong."},{"cn":"老师问的问题太难了，谁也答不上来。","pinyin":"Lǎoshī wèn de wèntí tài nán le, shéi yě dá bu shànglái.","vn":"Câu hỏi thầy giáo nêu ra khó quá, chẳng ai trả lời được."}]},{"hanzi":"由","pinyin":"yóu","pos":"giới.","vn":"do, bởi","examples":[{"cn":"今天的会议由王经理来主持。","pinyin":"Jīntiān de huìyì yóu Wáng jīnglǐ lái zhǔchí.","vn":"Cuộc họp hôm nay do Giám đốc Vương chủ trì."},{"cn":"这项任务由我们部门负责完成。","pinyin":"Zhè xiàng rènwu yóu wǒmen bùmén fùzé wánchéng.","vn":"Nhiệm vụ này do bộ phận chúng tôi phụ trách hoàn thành."},{"cn":"关于去哪儿旅游，由大家一起决定吧。","pinyin":"Guānyú qù nǎr lǚyóu, yóu dàjiā yìqǐ juédìng ba.","vn":"Về việc đi du lịch ở đâu, do mọi người cùng nhau quyết định nhé."}]},{"hanzi":"部门","pinyin":"bùmén","pos":"dt.","vn":"bộ phận, phòng ban","examples":[{"cn":"我们公司一共有五个主要部门。","pinyin":"Wǒmen gōngsī yígòng yǒu wǔ ge zhǔyào bùmén.","vn":"Công ty chúng tôi có tổng cộng năm phòng ban chính."},{"cn":"请问您是哪个部门的员工？","pinyin":"Qǐngwèn nín shì nǎ ge bùmén de yuángōng?","vn":"Xin hỏi anh/chị là nhân viên của bộ phận nào ạ?"},{"cn":"这件事需要各个部门互相配合。","pinyin":"Zhè jiàn shì xūyào gè ge bùmén hùxiāng pèihé.","vn":"Việc này cần các bộ phận phối hợp lẫn nhau."}]},{"hanzi":"负责人","pinyin":"fùzérén","pos":"dt.","vn":"người phụ trách","examples":[{"cn":"他是这个项目的负责人。","pinyin":"Tā shì zhège xiàngmù de fùzérén.","vn":"Anh ấy là người phụ trách dự án này."},{"cn":"如果你有任何问题，可以直接找活动负责人。","pinyin":"Rúguǒ nǐ yǒu rènhé wèntí, kěyǐ zhíjiē zhǎo huódòng fùzérén.","vn":"Nếu bạn có bất kỳ vấn đề gì, có thể tìm trực tiếp người phụ trách hoạt động."},{"cn":"明天下午所有部门的负责人都要开会。","pinyin":"Míngtiān xiàwǔ suǒyǒu bùmén de fùzérén dōu yào kāihuì.","vn":"Chiều mai tất cả người phụ trách các phòng ban đều phải họp."}]},{"hanzi":"不论","pinyin":"búlùn","pos":"liên.","vn":"bất luận, bất kể, dù cho","examples":[{"cn":"不论天气怎么样，他每天早上都坚持跑步。","pinyin":"Búlùn tiānqì zěnmeyàng, tā měitiān zǎoshang dōu jiānchí pǎobù.","vn":"Bất kể thời tiết thế nào, mỗi sáng anh ấy đều kiên trì chạy bộ."},{"cn":"不论遇到什么困难，我们都不要轻易放弃。","pinyin":"Búlùn yùdào shénme kùnnan, wǒmen dōu búyào qīngyì fàngqì.","vn":"Dù gặp khó khăn gì, chúng ta đều không nên dễ dàng từ bỏ."},{"cn":"不论结果如何，只要努力过就不会后悔。","pinyin":"Búlùn jiéguǒ rúhé, zhǐyào nǔlì guo jiù bú huì hòuhuǐ.","vn":"Bất luận kết quả ra sao, chỉ cần đã nỗ lực thì sẽ không hối hận."}]},{"hanzi":"肯定","pinyin":"kěndìng","pos":"phó./tt.","vn":"chắc chắn, nhất định; khẳng định","examples":[{"cn":"你这么用心准备，这次考试肯定能考好。","pinyin":"Nǐ zhème yòngxīn zhǔnbèi, zhè cì kǎoshì kěndìng néng kǎo hǎo.","vn":"Bạn chuẩn bị chu đáo thế này, kỳ thi lần này chắc chắn sẽ làm tốt."},{"cn":"我很肯定自己把钥匙放在桌子上了。","pinyin":"Wǒ hěn kěndìng zìjǐ bǎ yàoshi fàng zài zhuōzi shang le.","vn":"Tôi rất chắc chắn mình đã để chìa khóa trên bàn."},{"cn":"大家对他的工作成绩都给予了肯定。","pinyin":"Dàjiā duì tā de gōngzuò chéngjì dōu jǐyǔ le kěndìng.","vn":"Mọi người đều ghi nhận và khẳng định thành tích công việc của anh ấy."}]},{"hanzi":"短信","pinyin":"duǎnxìn","pos":"dt.","vn":"tin nhắn","examples":[{"cn":"我刚刚给你发了一条短信，你看到了吗？","pinyin":"Wǒ gānggāng gěi nǐ fā le yì tiáo duǎnxìn, nǐ kàndào le ma?","vn":"Tôi vừa gửi cho bạn một tin nhắn, bạn thấy chưa?"},{"cn":"银行发短信提醒我按时还款。","pinyin":"Yínháng fā duǎnxìn tíxǐng wǒ ànshí huánkuǎn.","vn":"Ngân hàng gửi tin nhắn nhắc tôi trả tiền đúng hạn."},{"cn":"他收到录取短信后高兴极了。","pinyin":"Tā shōudào lùqǔ duǎnxìn hòu gāoxìng jíle.","vn":"Sau khi nhận được tin nhắn trúng tuyển, anh ấy vui vô cùng."}]},{"hanzi":"激动","pinyin":"jīdòng","pos":"tt./dgt.","vn":"xúc động, phấn khích; làm xúc động","examples":[{"cn":"听到自己获奖的消息，她激动得说不出话来。","pinyin":"Tīngdào zìjǐ huòjiǎng de xiāoxi, tā jīdòng de shuō bu chū huà lái.","vn":"Nghe tin mình đoạt giải, cô ấy xúc động đến mức không nói nên lời."},{"cn":"别太激动了，先坐下来慢慢说。","pinyin":"Bié tài jīdòng le, xiān zuò xiàlai mànmàn shuō.","vn":"Đừng kích động quá, ngồi xuống nói từ từ đã."},{"cn":"这个感人的故事让在场的观众都很激动。","pinyin":"Zhège gǎnrén de gùshi ràng zàichǎng de guānzhòng dōu hěn jīdòng.","vn":"Câu chuyện cảm động này khiến khán giả có mặt đều rất xúc động."}]},{"hanzi":"扔","pinyin":"rēng","pos":"dgt.","vn":"ném, vứt","examples":[{"cn":"请不要随手把垃圾扔在地上。","pinyin":"Qǐng búyào suíshǒu bǎ lājī rēng zài dìshang.","vn":"Xin đừng tiện tay vứt rác xuống đất."},{"cn":"这些旧报纸没用了，扔了吧。","pinyin":"Zhèxiē jiù bàozhǐ méi yòng le, rēng le ba.","vn":"Mấy tờ báo cũ này không dùng nữa đâu, vứt đi thôi."},{"cn":"他一回到家就把书包扔在沙发上。","pinyin":"Tā yì huídào jiā jiù bǎ shūbāo rēng zài shāfā shang.","vn":"Vừa về đến nhà cậu ấy đã ném cặp sách lên ghế sofa."}]},{"hanzi":"理发","pinyin":"lǐfà","pos":"dgt.","vn":"cắt tóc","examples":[{"cn":"我的头发太长了，周末想去理发。","pinyin":"Wǒ de tóufa tài cháng le, zhōumò xiǎng qù lǐfà.","vn":"Tóc tôi dài quá rồi, cuối tuần muốn đi cắt tóc."},{"cn":"学校附近新开了一家理发店。","pinyin":"Xuéxiào fùjìn xīn kāi le yì jiā lǐfàdiàn.","vn":"Gần trường mới mở một tiệm cắt tóc."},{"cn":"面试前他特意去理发了，看起来精神多了。","pinyin":"Miànshì qián tā tèyì qù lǐfà le, kàn qǐlai jīngshen duō le.","vn":"Trước khi phỏng vấn anh ấy đặc biệt đi cắt tóc, trông bảnh bao, tươi tỉnh hơn hẳn."}]},{"hanzi":"镜子","pinyin":"jìngzi","pos":"dt.","vn":"cái gương","examples":[{"cn":"出门前她总喜欢照一照镜子。","pinyin":"Chūmén qián tā zǒng xǐhuan zhào yi zhào jìngzi.","vn":"Trước khi ra ngoài cô ấy luôn thích soi gương một chút."},{"cn":"我卧室的墙上挂着一面大镜子。","pinyin":"Wǒ wòshì de qiáng shang guà zhe yí miàn dà jìngzi.","vn":"Trên tường phòng ngủ của tôi treo một chiếc gương lớn."},{"cn":"他对着镜子练习了好几遍自我介绍。","pinyin":"Tā duìzhe jìngzi liànxí le hǎo jǐ biàn zìwǒ jièshào.","vn":"Anh ấy đứng trước gương luyện tập phần tự giới thiệu mấy lần liền."}]},{"hanzi":"自我","pinyin":"zìwǒ","pos":"đt.","vn":"tự mình, bản thân","examples":[{"cn":"面试的第一个环节通常是自我介绍。","pinyin":"Miànshì de dì yī ge huánjié tōngcháng shì zìwǒ jièshào.","vn":"Phần đầu tiên của buổi phỏng vấn thường là tự giới thiệu bản thân."},{"cn":"大家要提高自我保护意识。","pinyin":"Dàjiā yào tígāo zìwǒ bǎohù yìshí.","vn":"Mọi người cần nâng cao ý thức tự bảo vệ bản thân."},{"cn":"他在日记里写下了一段自我评价。","pinyin":"Tā zài rìjì lǐ xiěxià le yí duàn zìwǒ píngjià.","vn":"Anh ấy viết trong nhật ký một đoạn tự đánh giá bản thân."}]},{"hanzi":"能够","pinyin":"nénggòu","pos":"dgt.","vn":"có thể","examples":[{"cn":"希望我能够顺利通过这次面试。","pinyin":"Xīwàng wǒ nénggòu shùnlì tōngguò zhè cì miànshì.","vn":"Hy vọng tôi có thể vượt qua buổi phỏng vấn lần này một cách suôn sẻ."},{"cn":"经过一年的学习，我已经能够用中文流利交流了。","pinyin":"Jīngguò yì nián de xuéxí, wǒ yǐjīng nénggòu yòng Zhōngwén liúlì jiāoliú le.","vn":"Sau một năm học tập, tôi đã có thể giao tiếp lưu loát bằng tiếng Trung."},{"cn":"只要大家齐心协力，就一定能够完成任务。","pinyin":"Zhǐyào dàjiā qíxīn xiélì, jiù yídìng nénggòu wánchéng rènwu.","vn":"Chỉ cần mọi người đồng lòng hợp sức thì nhất định có thể hoàn thành nhiệm vụ."}]},{"hanzi":"运用","pinyin":"yùnyòng","pos":"dgt.","vn":"vận dụng, áp dụng","examples":[{"cn":"我们要学会把学到的知识运用到实际工作中。","pinyin":"Wǒmen yào xuéhuì bǎ xuédào de zhīshi yùnyòng dào shíjì gōngzuò zhōng.","vn":"Chúng ta cần học cách vận dụng kiến thức đã học vào công việc thực tế."},{"cn":"他能够非常熟练地运用这个软件。","pinyin":"Tā nénggòu fēicháng shúliàn de yùnyòng zhège ruǎnjiàn.","vn":"Anh ấy có thể sử dụng phần mềm này một cách vô cùng thành thạo."},{"cn":"这篇文章运用了很多生动的例子。","pinyin":"Zhè piān wénzhāng yùnyòng le hěn duō shēngdòng de lìzi.","vn":"Bài viết này đã vận dụng rất nhiều ví dụ sinh động."}]},{"hanzi":"工厂","pinyin":"gōngchǎng","pos":"dt.","vn":"nhà máy, công xưởng","examples":[{"cn":"我爸爸在一家汽车工厂工作。","pinyin":"Wǒ bàba zài yì jiā qìchē gōngchǎng gōngzuò.","vn":"Bố tôi làm việc tại một nhà máy ô tô."},{"cn":"这家工厂主要生产电子产品。","pinyin":"Zhè jiā gōngchǎng zhǔyào shēngchǎn diànzǐ chǎnpǐn.","vn":"Nhà máy này chủ yếu sản xuất các sản phẩm điện tử."},{"cn":"老师下周会带我们去郊区的工厂参观。","pinyin":"Lǎoshī xià zhōu huì dài wǒmen qù jiāoqū de gōngchǎng cānguān.","vn":"Tuần sau thầy giáo sẽ dẫn chúng tôi đi tham quan nhà máy ở ngoại ô."}]},{"hanzi":"规定","pinyin":"guīdìng","pos":"dt./dgt.","vn":"quy định","examples":[{"cn":"每个员工都必须遵守公司的规定。","pinyin":"Měi ge yuángōng dōu bìxū zūnshǒu gōngsī de guīdìng.","vn":"Mỗi nhân viên đều phải tuân thủ quy định của công ty."},{"cn":"学校规定，考试的时候不许带手机。","pinyin":"Xuéxiào guīdìng, kǎoshì de shíhou bù xǔ dài shǒujī.","vn":"Trường quy định khi thi không được phép mang điện thoại."},{"cn":"请你按照规定的时间提交材料。","pinyin":"Qǐng nǐ ànzhào guīdìng de shíjiān tíjiāo cáiliào.","vn":"Bạn vui lòng nộp tài liệu theo đúng thời gian quy định."}]},{"hanzi":"课堂","pinyin":"kètáng","pos":"dt.","vn":"lớp học, tiết học","examples":[{"cn":"王老师的课堂气氛总是非常活跃。","pinyin":"Wáng lǎoshī de kètáng qìfēn zǒngshì fēicháng huóyuè.","vn":"Không khí lớp học của thầy Vương luôn vô cùng sôi nổi."},{"cn":"在课堂上，学生应该认真听讲并积极发言。","pinyin":"Zài kètáng shang, xuésheng yīnggāi rènzhēn tīngjiǎng bìng jījí fāyán.","vn":"Trong giờ học, học sinh nên chăm chú nghe giảng và tích cực phát biểu."},{"cn":"除了课堂学习，课后练习也很重要。","pinyin":"Chúle kètáng xuéxí, kèhòu liànxí yě hěn zhòngyào.","vn":"Ngoài việc học trên lớp, luyện tập sau giờ học cũng rất quan trọng."}]},{"hanzi":"完全","pinyin":"wánquán","pos":"phó./tt.","vn":"hoàn toàn; trọn vẹn, đầy đủ","examples":[{"cn":"我完全同意你的看法。","pinyin":"Wǒ wánquán tóngyì nǐ de kànfǎ.","vn":"Tôi hoàn toàn đồng ý với quan điểm của bạn."},{"cn":"他的感冒还没完全好，还需要多休息。","pinyin":"Tā de gǎnmào hái méi wánquán hǎo, hái xūyào duō xiūxi.","vn":"Bệnh cảm của anh ấy vẫn chưa khỏi hẳn, vẫn cần nghỉ ngơi nhiều hơn."},{"cn":"这两种工作的性质完全不同。","pinyin":"Zhè liǎng zhǒng gōngzuò de xìngzhì wánquán bùtóng.","vn":"Tính chất của hai loại công việc này hoàn toàn khác nhau."}]},{"hanzi":"例如","pinyin":"lìrú","pos":"dgt.","vn":"ví dụ, chẳng hạn","examples":[{"cn":"我喜欢很多运动，例如跑步、游泳和打网球。","pinyin":"Wǒ xǐhuan hěn duō yùndòng, lìrú pǎobù, yóuyǒng hé dǎ wǎngqiú.","vn":"Tôi thích rất nhiều môn thể thao, ví dụ như chạy bộ, bơi lội và chơi quần vợt."},{"cn":"中国有很多著名的传统节日，例如春节和中秋节。","pinyin":"Zhōngguó yǒu hěn duō zhùmíng de chuántǒng jiérì, lìrú Chūnjié hé Zhōngqiūjié.","vn":"Trung Quốc có rất nhiều ngày lễ truyền thống nổi tiếng, chẳng hạn như Tết Nguyên đán và Tết Trung thu."},{"cn":"学中文有很多好办法，例如多看中文电影、多和中国人聊天。","pinyin":"Xué Zhōngwén yǒu hěn duō hǎo bànfǎ, lìrú duō kàn Zhōngwén diànyǐng, duō hé Zhōngguórén liáotiān.","vn":"Học tiếng Trung có nhiều cách hay, ví dụ như xem nhiều phim Trung Quốc, trò chuyện nhiều với người Trung Quốc."}]},{"hanzi":"不如","pinyin":"bùrú","pos":"dgt.","vn":"không bằng, chẳng bằng; thà rằng","examples":[{"cn":"我的中文水平不如他高。","pinyin":"Wǒ de Zhōngwén shuǐpíng bùrú tā gāo.","vn":"Trình độ tiếng Trung của tôi không cao bằng anh ấy."},{"cn":"与其在家里干等，不如出去走走。","pinyin":"Yǔqí zài jiā li gān děng, bùrú chūqù zǒuzou.","vn":"Thay vì ngồi chờ suông ở nhà, chi bằng ra ngoài đi dạo một chút."},{"cn":"听说这家餐厅的菜不如以前好吃了。","pinyin":"Tīngshuō zhè jiā cāntīng de cài bùrú yǐqián hǎochī le.","vn":"Nghe nói món ăn của nhà hàng này không còn ngon như trước nữa."}]},{"hanzi":"细节","pinyin":"xìjié","pos":"dt.","vn":"chi tiết","examples":[{"cn":"做事情一定要注意细节。","pinyin":"Zuò shìqing yídìng yào zhùyì xìjié.","vn":"Làm việc nhất định phải chú ý đến các chi tiết."},{"cn":"这个计划的大方向不错，但还需要讨论一些细节。","pinyin":"Zhège jìhuà de dà fāngxiàng búcuò, dàn hái xūyào tǎolùn yìxiē xìjié.","vn":"Phương hướng lớn của kế hoạch này khá ổn, nhưng vẫn cần thảo luận thêm một số chi tiết."},{"cn":"那件事过去太久了，很多细节我都记不清了。","pinyin":"Nà jiàn shì guòqù tài jiǔ le, hěn duō xìjié wǒ dōu jì bu qīng le.","vn":"Chuyện đó đã qua quá lâu rồi, rất nhiều chi tiết tôi đều không nhớ rõ nữa."}]},{"hanzi":"答案","pinyin":"dá'àn","pos":"dt.","vn":"đáp án, câu trả lời","examples":[{"cn":"你知道这道题的正确答案是什么吗？","pinyin":"Nǐ zhīdào zhè dào tí de zhèngquè dá'àn shì shénme ma?","vn":"Bạn có biết đáp án đúng của câu hỏi này là gì không?"},{"cn":"请大家先把答案写在纸上。","pinyin":"Qǐng dàjiā xiān bǎ dá'àn xiě zài zhǐ shang.","vn":"Mọi người hãy viết đáp án lên giấy trước nhé."},{"cn":"生活中很多问题并没有标准答案。","pinyin":"Shēnghuó zhōng hěn duō wèntí bìng méiyǒu biāozhǔn dá'àn.","vn":"Trong cuộc sống rất nhiều vấn đề vốn không có đáp án tiêu chuẩn."}]},{"hanzi":"职业","pinyin":"zhíyè","pos":"dt.","vn":"nghề nghiệp","examples":[{"cn":"你理想中的职业是什么？","pinyin":"Nǐ lǐxiǎng zhōng de zhíyè shì shénme?","vn":"Nghề nghiệp lý tưởng của bạn là gì?"},{"cn":"医生是一个非常受人尊敬的职业。","pinyin":"Yīshēng shì yí ge fēicháng shòu rén zūnjìng de zhíyè.","vn":"Bác sĩ là một nghề nghiệp rất được mọi người kính trọng."},{"cn":"实习帮助他更清楚自己的职业发展方向。","pinyin":"Shíxí bāngzhù tā gèng qīngchu zìjǐ de zhíyè fāzhǎn fāngxiàng.","vn":"Việc thực tập giúp anh ấy hiểu rõ hơn hướng phát triển nghề nghiệp của mình."}]}],"grammar":[{"title":"固定格式\"再也不/没……\"","explanation_vn":"Cấu trúc cố định \"再也不\" biểu thị trong tương lai sẽ không bao giờ xảy ra việc gì đó nữa, còn \"再也没\" biểu thị từ quá khứ đến hiện tại vẫn luôn chưa từng xảy ra lại việc gì đó.","examples":[{"cn":"期中考试后就再也没见过你了。","pinyin":"Qīzhōng kǎoshì hòu jiù zài yě méi jiànguo nǐ le.","vn":"Sau kỳ thi giữa kỳ đến giờ tớ chẳng gặp lại cậu lần nào nữa."},{"cn":"对不起，我以后再也不迟到了。","pinyin":"Duìbuqǐ, wǒ yǐhòu zài yě bù chídào le.","vn":"Xin lỗi, sau này tôi sẽ không bao giờ đi muộn nữa."},{"cn":"我出国以后就再也没给他打过电话。","pinyin":"Wǒ chūguó yǐhòu jiù zài yě méi gěi tā dǎguo diànhuà.","vn":"Sau khi tôi ra nước ngoài thì chưa từng gọi điện cho anh ấy lần nào nữa."}]},{"title":"介词\"由\"","explanation_vn":"Giới từ \"由\" trong bài này được dùng để dẫn ra người thực hiện hành động.","examples":[{"cn":"那天是由部门负责人来面试的，我有点儿紧张。","pinyin":"Nà tiān shì yóu bùmén fùzérén lái miànshì de, wǒ yǒudiǎnr jǐnzhāng.","vn":"Hôm đó là do người phụ trách bộ phận trực tiếp phỏng vấn, tôi hơi căng thẳng một chút."},{"cn":"这个问题究竟由谁来负责解决？","pinyin":"Zhège wèntí jiūjìng yóu shéi lái fùzé jiějué?","vn":"Vấn đề này rốt cuộc do ai phụ trách giải quyết?"},{"cn":"这次活动是由他们公司来安排的。","pinyin":"Zhè cì huódòng shì yóu tāmen gōngsī lái ānpái de.","vn":"Hoạt động lần này là do công ty của họ sắp xếp."}]},{"title":"\"把\"字句\"主语+把+宾语+动词（+一/了）+动词\"","explanation_vn":"Trong kiểu câu chữ \"把\" này, động từ có thể lặp lại dưới dạng \"VV\", \"V一V\" hoặc \"V了V\", biểu thị hành động diễn ra trong thời gian tương đối ngắn, mức độ tương đối nhẹ.","examples":[{"cn":"他去理发店把头发理了理。","pinyin":"Tā qù lǐfàdiàn bǎ tóufa lǐ le lǐ.","vn":"Cậu ấy đến tiệm cắt tóc tỉa lại mái tóc một chút."},{"cn":"你先把作业检查检查，然后再交给老师。","pinyin":"Nǐ xiān bǎ zuòyè jiǎnchá jiǎnchá, ránhòu zài jiāo gěi lǎoshī.","vn":"Bạn hãy kiểm tra qua bài tập trước rồi hẵng nộp cho thầy/cô giáo."},{"cn":"上课前，我把今天要学习的内容看了看。","pinyin":"Shàngkè qián, wǒ bǎ jīntiān yào xuéxí de nèiróng kàn le kàn.","vn":"Trước khi vào học, tôi đã xem qua nội dung cần học hôm nay."}]},{"title":"比较句\"A不如B（+形容词）\"","explanation_vn":"Câu so sánh \"A不如B（+形容词）\" biểu thị A không tốt bằng B. Nếu trong câu có tính từ thì biểu thị mức độ của A ở một phương diện nào đó thấp hơn B.","examples":[{"cn":"有些事情，在课本上学不如自己做一遍。","pinyin":"Yǒuxiē shìqing, zài kèběn shàng xué bùrú zìjǐ zuò yí biàn.","vn":"Có một số việc, học trong sách giáo khoa không bằng tự mình làm thử một lần."},{"cn":"这家店不如那家店环境好。","pinyin":"Zhè jiā diàn bùrú nà jiā diàn huánjìng hǎo.","vn":"Quán này không gian không đẹp bằng quán kia."},{"cn":"我觉得坐公交不如坐地铁方便。","pinyin":"Wǒ juéde zuò gōngjiāo bùrú zuò dìtiě fāngbiàn.","vn":"Tôi thấy đi xe buýt không tiện bằng đi tàu điện ngầm."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"陈天中","cn":"李文，期中考试后就再也没见过你了，你这段时间在忙什么呢？","pinyin":"Lǐ Wén, qīzhōng kǎoshì hòu jiù zài yě méi jiànguo nǐ le, nǐ zhè duàn shíjiān zài máng shénme ne?"},{"speaker":"李文","cn":"我最近去一家医药公司应聘了，他们正在招聘实习生。","pinyin":"Wǒ zuìjìn qù yì jiā yīyào gōngsī yìngpìn le, tāmen zhèngzài zhāopìn shíxíshēng."},{"speaker":"陈天中","cn":"你这么早就考虑实习了？","pinyin":"Nǐ zhème zǎo jiù kǎolǜ shíxí le?"},{"speaker":"李文","cn":"现在很多单位在招聘毕业生时，都很重视有没有实习经历，所以我想提前去锻炼一下，积累一些经验。","pinyin":"Xiànzài hěn duō dānwèi zài zhāopìn bìyèshēng shí, dōu hěn zhòngshì yǒu méiyǒu shíxí jīnglì, suǒyǐ wǒ xiǎng tíqián qù duànliàn yíxià, jīlěi yìxiē jīngyàn."},{"speaker":"陈天中","cn":"那现在有结果了吗？","pinyin":"Nà xiànzài yǒu jiéguǒ le ma?"},{"speaker":"李文","cn":"我还在等消息，希望能有好结果。","pinyin":"Wǒ hái zài děng xiāoxi, xīwàng néng yǒu hǎo jiéguǒ."}],"translation_vn":"Trần Thiên Trung: Lý Văn, từ sau kỳ thi giữa kỳ đến giờ tớ chẳng gặp lại cậu nữa, thời gian này cậu đang bận gì thế?\nLý Văn: Gần đây tớ đã đi ứng tuyển ở một công ty dược phẩm, họ đang tuyển thực tập sinh.\nTrần Thiên Trung: Cậu đã tính đến chuyện thực tập sớm thế rồi à?\nLý Văn: Bây giờ nhiều đơn vị khi tuyển sinh viên mới tốt nghiệp đều rất coi trọng việc có kinh nghiệm thực tập hay không, nên tớ muốn đi rèn luyện sớm một chút, tích lũy thêm kinh nghiệm.\nTrần Thiên Trung: Vậy giờ đã có kết quả chưa?\nLý Văn: Tớ vẫn đang đợi tin, hy vọng sẽ có kết quả tốt.","audio_dialogue":"15-1.mp3","audio_vocab":"15-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"陈天中","cn":"李文，你是怎么应聘的？","pinyin":"Lǐ Wén, nǐ shì zěnme yìngpìn de?"},{"speaker":"李文","cn":"我先在网上报名，填写个人信息，然后等公司通知我去参加笔试。","pinyin":"Wǒ xiān zài wǎngshàng bàomíng, tiánxiě gèrén xìnxī, ránhòu děng gōngsī tōngzhī wǒ qù cānjiā bǐshì."},{"speaker":"陈天中","cn":"笔试都考些什么？","pinyin":"Bǐshì dōu kǎo xiē shénme?"},{"speaker":"李文","cn":"主要是一些专业知识。考完没多久，他们就让我去面试了。","pinyin":"Zhǔyào shì yìxiē zhuānyè zhīshi. Kǎowán méi duōjiǔ, tāmen jiù ràng wǒ qù miànshì le."},{"speaker":"陈天中","cn":"看来你笔试答得不错，那你面试得怎么样？","pinyin":"Kànlái nǐ bǐshì dá de búcuò, nà nǐ miànshì de zěnmeyàng?"},{"speaker":"李文","cn":"那天是由部门负责人来面试的，我有点儿紧张。他让我介绍了自己的学习经历、兴趣爱好和对工作的想法。","pinyin":"Nà tiān shì yóu bùmén fùzérén lái miànshì de, wǒ yǒudiǎnr jǐnzhāng. Tā ràng wǒ jièshàole zìjǐ de xuéxí jīnglì, xìngqù àihào hé duì gōngzuò de xiǎngfǎ."},{"speaker":"陈天中","cn":"听起来挺正式的。","pinyin":"Tīng qǐlái tǐng zhèngshì de."},{"speaker":"李文","cn":"是啊，我觉得这次经历很有用。不论结果怎么样，对我以后找工作肯定有帮助。","pinyin":"Shì a, wǒ juéde zhè cì jīnglì hěn yǒuyòng. Búlùn jiéguǒ zěnmeyàng, duì wǒ yǐhòu zhǎo gōngzuò kěndìng yǒu bāngzhù."}],"translation_vn":"Trần Thiên Trung: Lý Văn, cậu đã ứng tuyển như thế nào thế?\nLý Văn: Trước tiên tớ đăng ký trên mạng, điền thông tin cá nhân, rồi đợi công ty thông báo đi thi viết.\nTrần Thiên Trung: Thi viết thì thi những gì?\nLý Văn: Chủ yếu là một số kiến thức chuyên ngành. Thi xong không lâu thì họ gọi tớ đi phỏng vấn.\nTrần Thiên Trung: Xem ra phần thi viết cậu làm khá tốt đấy, thế buổi phỏng vấn thế nào?\nLý Văn: Hôm đó là do người phụ trách bộ phận trực tiếp phỏng vấn, tớ hơi căng thẳng. Ông ấy bảo tớ giới thiệu quá trình học tập, sở thích cá nhân và suy nghĩ của mình về công việc.\nTrần Thiên Trung: Nghe có vẻ khá trang trọng đấy.\nLý Văn: Ừ, tớ thấy trải nghiệm lần này rất hữu ích. Bất luận kết quả ra sao, chắc chắn cũng sẽ có ích cho việc tìm việc sau này của tớ.","audio_dialogue":"15-3.mp3","audio_vocab":"15-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"一天下午，李文突然收到一条短信，说他通过了面试，让他下周一到公司实习。李文看到信息后，激动得把手机扔到床上，在屋子里跳了起来。之后的几天，李文忙着做各种准备。为了给大家留个好印象，他去理发店把头发理了理，又去商店买了一身正式的衣服，还打算在镜子前把自我介绍练一练。","pinyin":"Yì tiān xiàwǔ, Lǐ Wén tūrán shōudào yì tiáo duǎnxìn, shuō tā tōngguòle miànshì, ràng tā xià zhōuyī dào gōngsī shíxí. Lǐ Wén kàndào xìnxī hòu, jīdòng de bǎ shǒujī rēng dào chuángshàng, zài wūzi lǐ tiàole qǐlái. Zhīhòu de jǐ tiān, Lǐ Wén mángzhe zuò gèzhǒng zhǔnbèi. Wèile gěi dàjiā liú ge hǎo yìnxiàng, tā qù lǐfàdiàn bǎ tóufa lǐ le lǐ, yòu qù shāngdiàn mǎile yì shēn zhèngshì de yīfu, hái dǎsuàn zài jìngzi qián bǎ zìwǒ jièshào liàn yi liàn."},{"speaker":"","cn":"在他看来，这次实习是一个新的开始。他希望不仅能够运用专业知识完成任务，还能够积累更多经验，为将来找工作打下基础。","pinyin":"Zài tā kànlái, zhè cì shíxí shì yí ge xīn de kāishǐ. Tā xīwàng bùjǐn nénggòu yùnyòng zhuānyè zhīshi wánchéng rènwu, hái nénggòu jīlěi gèng duō jīngyàn, wèi jiānglái zhǎo gōngzuò dǎxià jīchǔ."}],"translation_vn":"Một buổi chiều nọ, Lý Văn bất ngờ nhận được một tin nhắn, nói rằng cậu đã vượt qua buổi phỏng vấn và bảo cậu thứ Hai tuần sau đến công ty thực tập. Sau khi đọc tin nhắn, Lý Văn phấn khích đến nỗi ném điện thoại lên giường rồi nhảy cẫng lên trong phòng. Mấy ngày sau đó, Lý Văn bận rộn chuẩn bị đủ thứ. Để tạo ấn tượng tốt với mọi người, cậu đến tiệm cắt tóc tỉa lại mái tóc, lại ra cửa hàng mua một bộ trang phục lịch sự, còn dự định đứng trước gương tập luyện lại phần tự giới thiệu bản thân.\nTheo cậu thấy, kỳ thực tập lần này là một khởi đầu mới. Cậu hy vọng không chỉ có thể vận dụng kiến thức chuyên ngành để hoàn thành nhiệm vụ, mà còn có thể tích lũy thêm nhiều kinh nghiệm hơn, đặt nền tảng cho việc tìm việc làm sau này.","audio_dialogue":"15-5.mp3","audio_vocab":"15-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"在中国，很多大学生在毕业前都会去实习。实习的地方有公司、工厂，也有学校和医院。学生们通过实习，可以积累工作经验，熟悉工作内容和单位的管理规定，提前了解并适应社会。","pinyin":"Zài Zhōngguó, hěn duō dàxuéshēng zài bìyè qián dōu huì qù shíxí. Shíxí de dìfang yǒu gōngsī, gōngchǎng, yě yǒu xuéxiào hé yīyuàn. Xuéshengmen tōngguò shíxí, kěyǐ jīlěi gōngzuò jīngyàn, shúxī gōngzuò nèiróng hé dānwèi de guǎnlǐ guīdìng, tíqián liǎojiě bìng shìyìng shèhuì."},{"speaker":"","cn":"在实习中，学生常常会发现，课堂上学到的知识和实际工作并不完全一样。例如：有些事情，在课本上学不如自己做一遍，因为只有在做的时候，才会发现有很多细节需要注意；还有一些问题，在书上找不到答案，只能通过日常工作慢慢理解。在这样的过程中，学生能够对学到的知识有更好的认识，也更清楚自己的职业发展方向。","pinyin":"Zài shíxí zhōng, xuésheng chángcháng huì fāxiàn, kètáng shàng xuédào de zhīshi hé shíjì gōngzuò bìng bù wánquán yíyàng. Lìrú: yǒuxiē shìqing, zài kèběn shàng xué bùrú zìjǐ zuò yí biàn, yīnwèi zhǐyǒu zài zuò de shíhou, cái huì fāxiàn yǒu hěn duō xìjié xūyào zhùyì; hái yǒu yìxiē wèntí, zài shūshàng zhǎo bu dào dá'àn, zhǐ néng tōngguò rìcháng gōngzuò mànmàn lǐjiě. Zài zhèyàng de guòchéng zhōng, xuésheng nénggòu duì xuédào de zhīshi yǒu gèng hǎo de rènshi, yě gèng qīngchu zìjǐ de zhíyè fāzhǎn fāngxiàng."}],"translation_vn":"Ở Trung Quốc, rất nhiều sinh viên đại học trước khi tốt nghiệp đều sẽ đi thực tập. Nơi thực tập có công ty, nhà máy, cũng có trường học và bệnh viện. Thông qua thực tập, sinh viên có thể tích lũy kinh nghiệm làm việc, làm quen với nội dung công việc và quy định quản lý của đơn vị, tìm hiểu và thích nghi trước với xã hội.\nTrong quá trình thực tập, sinh viên thường nhận ra rằng kiến thức học trên lớp và công việc thực tế không hoàn toàn giống nhau. Ví dụ: có một số việc, học trong sách giáo khoa không bằng tự tay làm một lần, bởi vì chỉ khi trực tiếp làm mới phát hiện ra có rất nhiều chi tiết cần chú ý; lại có một số vấn đề không thể tìm thấy đáp án trong sách vở mà chỉ có thể dần dần thấu hiểu qua công việc hằng ngày. Trong quá trình như vậy, sinh viên có thể nhận thức sâu sắc hơn về kiến thức đã học, đồng thời cũng hiểu rõ hơn định hướng phát triển nghề nghiệp của bản thân.","audio_dialogue":"15-7.mp3","audio_vocab":"15-8.mp3"}]},{"id":16,"title_cn":"计划赶不上变化","title_pinyin":"Jìhuà gǎn bu shàng biànhuà","title_vn":"Kế hoạch không theo kịp sự thay đổi","goals":["Có thể nghe hiểu và trao đổi về các kế hoạch và sự thay đổi trong cuộc sống cũng như công việc.","Có thể trình bày bằng lời hoặc bằng văn bản cách sắp xếp kế hoạch và điều chỉnh kế hoạch của bản thân.","Hiểu được những quan điểm khác nhau của mọi người về việc lập kế hoạch cũng như cách ứng phó với sự thay đổi."],"vocab":[{"hanzi":"本来","pinyin":"běnlái","pos":"phó./tt.","vn":"vốn dĩ, ban đầu; vốn có","examples":[{"cn":"我本来打算周末去爬山，可是下雨了。","pinyin":"Wǒ běnlái dǎsuàn zhōumò qù páshān, kěshì xiàyǔ le.","vn":"Ban đầu tôi định cuối tuần đi leo núi, nhưng trời lại mưa."},{"cn":"这件事本来就很复杂，需要慢慢解决。","pinyin":"Zhè jiàn shì běnlái jiù hěn fùzá, xūyào mànmàn jiějué.","vn":"Chuyện này vốn dĩ đã rất phức tạp, cần phải giải quyết từ từ."},{"cn":"请你把桌子放回它本来的位置。","pinyin":"Qǐng nǐ bǎ zhuōzi fànghuí tā běnlái de wèizhi.","vn":"Bạn hãy đặt cái bàn về lại vị trí ban đầu của nó nhé."}]},{"hanzi":"只好","pinyin":"zhǐhǎo","pos":"phó.","vn":"đành phải","examples":[{"cn":"最后一班公交车已经走了，我只好打车回家。","pinyin":"Zuìhòu yì bān gōngjiāochē yǐjīng zǒu le, wǒ zhǐhǎo dǎchē huíjiā.","vn":"Chuyến xe buýt cuối cùng đã chạy rồi, tôi đành phải bắt taxi về nhà."},{"cn":"他今天生病了，只好在家休息。","pinyin":"Tā jīntiān shēngbìng le, zhǐhǎo zài jiā xiūxi.","vn":"Hôm nay anh ấy bị ốm nên đành phải nghỉ ngơi ở nhà."},{"cn":"外面雨下得太大，我们只好改天再去公园。","pinyin":"Wàimiàn yǔ xià de tài dà, wǒmen zhǐhǎo gǎitiān zài qù gōngyuán.","vn":"Ngoài trời mưa to quá, chúng tôi đành phải hôm khác mới đi công viên."}]},{"hanzi":"赶上","pinyin":"gǎnshàng","pos":"dgt.","vn":"đuổi kịp, bắt kịp","examples":[{"cn":"幸好出门早，我们才赶上了这趟火车。","pinyin":"Xìnghǎo chūmén zǎo, wǒmen cái gǎnshàng le zhè tàng huǒchē.","vn":"May mà ra khỏi nhà sớm nên chúng tôi mới kịp chuyến tàu này."},{"cn":"你快走几步，就能赶上前面的同学了。","pinyin":"Nǐ kuài zǒu jǐ bù, jiù néng gǎnshàng qiánmiàn de tóngxué le.","vn":"Bạn bước nhanh mấy bước là sẽ đuổi kịp bạn học phía trước ngay."},{"cn":"只要每天努力学习，你很快就能赶上大家。","pinyin":"Zhǐyào měitiān nǔlì xuéxí, nǐ hěn kuài jiù néng gǎnshàng dàjiā.","vn":"Chỉ cần mỗi ngày chăm chỉ học tập, bạn sẽ nhanh chóng bắt kịp mọi người."}]},{"hanzi":"旅行","pinyin":"lǚxíng","pos":"dgt.","vn":"du lịch, đi du lịch","examples":[{"cn":"放假的时候，我喜欢和朋友一起去旅行。","pinyin":"Fàngjià de shíhou, wǒ xǐhuan hé péngyou yìqǐ qù lǚxíng.","vn":"Khi được nghỉ, tôi thích cùng bạn bè đi du lịch."},{"cn":"这次云南旅行给我留下了非常美好的印象。","pinyin":"Zhè cì Yúnnán lǚxíng gěi wǒ liúxià le fēicháng měihǎo de yìnxiàng.","vn":"Chuyến du lịch Vân Nam lần này đã để lại cho tôi ấn tượng vô cùng tốt đẹp."},{"cn":"出发去旅行前，别忘了检查证件和行李。","pinyin":"Chūfā qù lǚxíng qián, bié wàng le jiǎnchá zhèngjiàn hé xíngli.","vn":"Trước khi khởi hành đi du lịch, đừng quên kiểm tra giấy tờ và hành lý."}]},{"hanzi":"推迟","pinyin":"tuīchí","pos":"dgt.","vn":"hoãn lại, lùi lại","examples":[{"cn":"因为天气原因，明天的比赛推迟到下周了。","pinyin":"Yīnwèi tiānqì yuányīn, míngtiān de bǐsài tuīchí dào xià zhōu le.","vn":"Vì lý do thời tiết, trận đấu ngày mai đã hoãn sang tuần sau rồi."},{"cn":"由于航班推迟，我们晚上十点才到北京。","pinyin":"Yóuyú hángbān tuīchí, wǒmen wǎnshang shí diǎn cái dào Běijīng.","vn":"Do chuyến bay bị hoãn, mười giờ tối chúng tôi mới đến Bắc Kinh."},{"cn":"这次会议能不能推迟半个小时开始？","pinyin":"Zhè cì huìyì néng bu néng tuīchí bàn ge xiǎoshí kāishǐ?","vn":"Cuộc họp lần này có thể lùi lại nửa tiếng rồi mới bắt đầu được không?"}]},{"hanzi":"取消","pinyin":"qǔxiāo","pos":"dgt.","vn":"hủy bỏ","examples":[{"cn":"因为临时有事，我把明天的机票取消了。","pinyin":"Yīnwèi línshí yǒushì, wǒ bǎ míngtiān de jīpiào qǔxiāo le.","vn":"Vì đột xuất có việc, tôi đã hủy vé máy bay ngày mai rồi."},{"cn":"下大雨了，学校的户外活动只好取消。","pinyin":"Xià dàyǔ le, xuéxiào de hùwài huódòng zhǐhǎo qǔxiāo.","vn":"Trời mưa to rồi, hoạt động ngoài trời của trường đành phải hủy bỏ."},{"cn":"请问这个酒店订单可以免费取消吗？","pinyin":"Qǐngwèn zhège jiǔdiàn dìngdān kěyǐ miǎnfèi qǔxiāo ma?","vn":"Xin hỏi đơn đặt phòng khách sạn này có thể hủy miễn phí không?"}]},{"hanzi":"可惜","pinyin":"kěxī","pos":"tt.","vn":"đáng tiếc","examples":[{"cn":"你没能去看那场音乐会，真是太可惜了。","pinyin":"Nǐ méi néng qù kàn nà chǎng yīnyuèhuì, zhēn shì tài kěxī le.","vn":"Bạn không thể đi xem buổi hòa nhạc đó, thật là quá đáng tiếc."},{"cn":"这件衣服很好看，可惜没有我的尺码。","pinyin":"Zhè jiàn yīfu hěn hǎokàn, kěxī méiyǒu wǒ de chǐmǎ.","vn":"Bộ quần áo này rất đẹp, tiếc là không có cỡ của tôi."},{"cn":"这么好的菜扔掉太可惜了，打包带回去吧。","pinyin":"Zhème hǎo de cài rēngdiào tài kěxī le, dǎbāo dài huíqù ba.","vn":"Món ăn ngon thế này vứt đi thì phí quá, gói mang về đi."}]},{"hanzi":"确实","pinyin":"quèshí","pos":"phó.","vn":"quả thực, thật sự","examples":[{"cn":"这部电影拍得确实非常精彩。","pinyin":"Zhè bù diànyǐng pāi de quèshí fēicháng jīngcǎi.","vn":"Bộ phim này quay quả thực vô cùng đặc sắc."},{"cn":"他说得确实有道理，我们应该听听他的建议。","pinyin":"Tā shuō de quèshí yǒu dàolǐ, wǒmen yīnggāi tīngting tā de jiànyì.","vn":"Anh ấy nói quả thật có lý, chúng ta nên nghe theo đề nghị của anh ấy."},{"cn":"最近工作任务太多，我确实有点儿累了。","pinyin":"Zuìjìn gōngzuò rènwu tài duō, wǒ quèshí yǒudiǎnr lèi le.","vn":"Gần đây nhiệm vụ công việc nhiều quá, tôi thật sự hơi mệt rồi."}]},{"hanzi":"等到","pinyin":"děngdào","pos":"giới.","vn":"đợi đến, chờ đến khi","examples":[{"cn":"等到放寒假的时候，我就回国看父母。","pinyin":"Děngdào fàng hánjià de shíhou, wǒ jiù huíguó kàn fùmǔ.","vn":"Đợi đến kỳ nghỉ đông, tôi sẽ về nước thăm bố mẹ."},{"cn":"等到雨停了，我们再出门吧。","pinyin":"Děngdào yǔ tíng le, wǒmen zài chūmén ba.","vn":"Đợi đến khi tạnh mưa rồi chúng ta hẵng ra ngoài nhé."},{"cn":"等到你真正工作以后，就会明白其中的辛苦。","pinyin":"Děngdào nǐ zhēnzhèng gōngzuò yǐhòu, jiù huì míngbai qízhōng de xīnkǔ.","vn":"Đợi đến khi bạn thực sự đi làm rồi, bạn sẽ hiểu nỗi vất vả trong đó."}]},{"hanzi":"早晨","pinyin":"zǎochen","pos":"dt.","vn":"buổi sáng, sáng sớm","examples":[{"cn":"公园里早晨的空气特别新鲜。","pinyin":"Gōngyuán lǐ zǎochen de kōngqì tèbié xīnxiān.","vn":"Không khí buổi sáng ở công viên đặc biệt trong lành."},{"cn":"我每天早晨六点半起床锻炼身体。","pinyin":"Wǒ měitiān zǎochen liù diǎn bàn qǐchuáng duànliàn shēntǐ.","vn":"Mỗi sáng sáu giờ rưỡi tôi dậy tập thể dục."},{"cn":"昨天早晨下了一场小雨。","pinyin":"Zuótiān zǎochen xià le yì chǎng xiǎoyǔ.","vn":"Sáng sớm hôm qua trời đổ một cơn mưa nhỏ."}]},{"hanzi":"忽然","pinyin":"hūrán","pos":"phó.","vn":"đột nhiên, bỗng nhiên","examples":[{"cn":"刚才还是晴天，怎么忽然下起雨来了？","pinyin":"Gāngcái háishì qíngtiān, zěnme hūrán xià qǐ yǔ lái le?","vn":"Vừa nãy trời còn nắng đẹp, sao bỗng dưng lại đổ mưa thế này?"},{"cn":"我正准备出门，手机忽然响了。","pinyin":"Wǒ zhèng zhǔnbèi chūmén, shǒujī hūrán xiǎng le.","vn":"Tôi đang chuẩn bị ra khỏi nhà thì điện thoại đột nhiên đổ chuông."},{"cn":"他走到半路，忽然想起忘了带钥匙。","pinyin":"Tā zǒudào bànlù, hūrán xiǎngqǐ wàng le dài yàoshi.","vn":"Anh ấy đi được nửa đường thì chợt nhớ ra mình quên mang chìa khóa."}]},{"hanzi":"增加","pinyin":"zēngjiā","pos":"dgt.","vn":"tăng thêm, thêm vào","examples":[{"cn":"这几年来中国旅游的外国游客增加了很多。","pinyin":"Zhè jǐ nián lái Zhōngguó lǚyóu de wàiguó yóukè zēngjiā le hěn duō.","vn":"Mấy năm nay du khách nước ngoài đến Trung Quốc du lịch tăng lên rất nhiều."},{"cn":"为了提高效率，公司决定增加两名工作人员。","pinyin":"Wèile tígāo xiàolǜ, gōngsī juédìng zēngjiā liǎng míng gōngzuò rényuán.","vn":"Để nâng cao hiệu suất, công ty quyết định tăng thêm hai nhân viên."},{"cn":"每天坚持阅读可以增加我们的词汇量。","pinyin":"Měitiān jiānchí yuèdú kěyǐ zēngjiā wǒmen de cíhuìliàng.","vn":"Mỗi ngày kiên trì đọc sách có thể tăng thêm vốn từ vựng cho chúng ta."}]},{"hanzi":"调整","pinyin":"tiáozhěng","pos":"dgt.","vn":"điều chỉnh","examples":[{"cn":"由于情况变化，我们需要重新调整工作计划。","pinyin":"Yóuyú qíngkuàng biànhuà, wǒmen xūyào chóngxīn tiáozhěng gōngzuò jìhuà.","vn":"Do tình hình thay đổi, chúng ta cần điều chỉnh lại kế hoạch công việc."},{"cn":"出国旅游后，我花了两天才调整好时差。","pinyin":"Chūguó lǚyóu hòu, wǒ huā le liǎng tiān cái tiáozhěng hǎo shíchā.","vn":"Sau khi đi du lịch nước ngoài, tôi mất hai ngày mới điều chỉnh xong chênh lệch múi giờ."},{"cn":"遇到压力时，要学会及时调整自己的心态。","pinyin":"Yùdào yālì shí, yào xuéhuì jíshí tiáozhěng zìjǐ de xīntài.","vn":"Khi gặp áp lực, cần học cách kịp thời điều chỉnh tâm trạng của bản thân."}]},{"hanzi":"错误","pinyin":"cuòwù","pos":"dt./tt.","vn":"sai lầm, lỗi sai; sai","examples":[{"cn":"这篇作文里还有几个语法错误。","pinyin":"Zhè piān zuòwén lǐ hái yǒu jǐ ge yǔfǎ cuòwù.","vn":"Trong bài văn này vẫn còn mấy lỗi ngữ pháp."},{"cn":"每个人都会犯错误，关键是要及时改正。","pinyin":"Měi ge rén dōu huì fàn cuòwù, guānjiàn shì yào jíshí gǎizhèng.","vn":"Ai cũng có thể mắc sai lầm, điều quan trọng là phải sửa chữa kịp thời."},{"cn":"事实证明，我当时的想法是错误的。","pinyin":"Shìshí zhèngmíng, wǒ dāngshí de xiǎngfǎ shì cuòwù de.","vn":"Thực tế chứng minh suy nghĩ lúc đó của tôi là sai lầm."}]},{"hanzi":"并且","pinyin":"bìngqiě","pos":"liên.","vn":"hơn nữa, vả lại, đồng thời","examples":[{"cn":"她不仅学习成绩好，并且非常乐于助人。","pinyin":"Tā bùjǐn xuéxí chéngjì hǎo, bìngqiě fēicháng lèyú zhùrén.","vn":"Cô ấy không chỉ học giỏi mà còn rất thích giúp đỡ mọi người."},{"cn":"我已经读完了这本书，并且写了一篇读后感。","pinyin":"Wǒ yǐjīng dúwán le zhè běn shū, bìngqiě xiě le yì piān dúhòugǎn.","vn":"Tôi đã đọc xong cuốn sách này, đồng thời viết một bài cảm nhận sau khi đọc."},{"cn":"这家餐厅的菜味道很好，并且价格也不贵。","pinyin":"Zhè jiā cāntīng de cài wèidao hěn hǎo, bìngqiě jiàgé yě bú guì.","vn":"Món ăn ở nhà hàng này rất ngon, hơn nữa giá cả cũng không đắt."}]},{"hanzi":"例子","pinyin":"lìzi","pos":"dt.","vn":"ví dụ","examples":[{"cn":"你能举一个具体的例子来说明这个问题吗？","pinyin":"Nǐ néng jǔ yí ge jùtǐ de lìzi lái shuōmíng zhège wèntí ma?","vn":"Bạn có thể nêu một ví dụ cụ thể để giải thích vấn đề này không?"},{"cn":"老师讲课的时候常常用生活中的例子。","pinyin":"Lǎoshī jiǎngkè de shíhou chángcháng yòng shēnghuó zhōng de lìzi.","vn":"Khi giảng bài, thầy giáo thường dùng những ví dụ trong cuộc sống."},{"cn":"这个例子太恰当了，我一下子就听懂了。","pinyin":"Zhège lìzi tài qiàdàng le, wǒ yíxiàzi jiù tīngdǒng le.","vn":"Ví dụ này quá thích hợp, tôi nghe phát hiểu ngay."}]},{"hanzi":"关键","pinyin":"guānjiàn","pos":"dt./tt.","vn":"mấu chốt, then chốt; quan trọng, mang tính quyết định","examples":[{"cn":"学好一门语言的关键是每天坚持练习。","pinyin":"Xuéhǎo yì mén yǔyán de guānjiàn shì měitiān jiānchí liànxí.","vn":"Mấu chốt để học tốt một ngôn ngữ là kiên trì luyện tập mỗi ngày."},{"cn":"在这场关键的比赛中，他表现得非常出色。","pinyin":"Zài zhè chǎng guānjiàn de bǐsài zhōng, tā biǎoxiàn de fēicháng chūsè.","vn":"Trong trận đấu then chốt này, anh ấy thể hiện vô cùng xuất sắc."},{"cn":"遇到问题不要慌，先找到问题的关键在哪里。","pinyin":"Yùdào wèntí búyào huāng, xiān zhǎodào wèntí de guānjiàn zài nǎlǐ.","vn":"Gặp vấn đề đừng hoảng loạn, trước tiên hãy tìm xem mấu chốt của vấn đề nằm ở đâu."}]},{"hanzi":"详细","pinyin":"xiángxì","pos":"tt.","vn":"chi tiết, tỉ mỉ","examples":[{"cn":"请你把事情的经过详细地说一遍。","pinyin":"Qǐng nǐ bǎ shìqing de jīngguò xiángxì de shuō yí biàn.","vn":"Bạn hãy kể lại chi tiết diễn biến sự việc một lần nhé."},{"cn":"这份旅游计划写得非常详细。","pinyin":"Zhè fèn lǚyóu jìhuà xiě de fēicháng xiángxì.","vn":"Bản kế hoạch du lịch này viết vô cùng chi tiết."},{"cn":"如果您想了解更多详细信息，可以查看我们的网站。","pinyin":"Rúguǒ nín xiǎng liǎojiě gèng duō xiángxì xìnxī, kěyǐ chákàn wǒmen de wǎngzhàn.","vn":"Nếu quý khách muốn tìm hiểu thêm thông tin chi tiết, có thể xem trên trang web của chúng tôi."}]},{"hanzi":"时间表","pinyin":"shíjiānbiǎo","pos":"dt.","vn":"thời gian biểu, lịch trình","examples":[{"cn":"我为自己制定了一份每天的复习时间表。","pinyin":"Wǒ wèi zìjǐ zhìdìng le yí fèn měitiān de fùxí shíjiānbiǎo.","vn":"Tôi đã lập cho bản thân một thời gian biểu ôn tập mỗi ngày."},{"cn":"这是明天会议的时间表，请大家看一下。","pinyin":"Zhè shì míngtiān huìyì de shíjiānbiǎo, qǐng dàjiā kàn yíxià.","vn":"Đây là lịch trình cuộc họp ngày mai, mời mọi người xem qua."},{"cn":"按照时间表做事，我的一天过得特别充实。","pinyin":"Ànzhào shíjiānbiǎo zuòshì, wǒ de yì tiān guò de tèbié chōngshí.","vn":"Làm việc theo thời gian biểu, một ngày của tôi trôi qua vô cùng ý nghĩa và hiệu quả."}]},{"hanzi":"把握","pinyin":"bǎwò","pos":"dt.","vn":"sự chắc chắn, phần chắc","examples":[{"cn":"这次考试我准备得很充分，非常有把握通过。","pinyin":"Zhè cì kǎoshì wǒ zhǔnbèi de hěn chōngfèn, fēicháng yǒu bǎwò tōngguò.","vn":"Kỳ thi lần này tôi chuẩn bị rất kỹ lưỡng, vô cùng chắc chắn sẽ đỗ."},{"cn":"对于这个新项目，我心里还不太有把握。","pinyin":"Duìyú zhège xīn xiàngmù, wǒ xīnli hái bú tài yǒu bǎwò.","vn":"Đối với dự án mới này, trong lòng tôi vẫn chưa mấy chắc chắn."},{"cn":"有了详细的计划，做起事来就更有把握了。","pinyin":"Yǒu le xiángxì de jìhuà, zuò qǐ shì lái jiù gèng yǒu bǎwò le.","vn":"Có kế hoạch chi tiết rồi, khi bắt tay vào làm sẽ càng thêm chắc chắn."}]},{"hanzi":"相反","pinyin":"xiāngfǎn","pos":"liên./tt.","vn":"trái lại, ngược lại; đối lập","examples":[{"cn":"我喜欢安静，相反，我弟弟却喜欢热闹。","pinyin":"Wǒ xǐhuan ānjìng, xiāngfǎn, wǒ dìdi què xǐhuan rènao.","vn":"Tôi thích yên tĩnh, trái lại, em trai tôi lại thích náo nhiệt."},{"cn":"我们俩对这件事的看法完全相反。","pinyin":"Wǒmen liǎ duì zhè jiàn shì de kànfǎ wánquán xiāngfǎn.","vn":"Quan điểm của hai chúng tôi về việc này hoàn toàn trái ngược nhau."},{"cn":"你坐反方向了，地铁应该往相反的方向坐。","pinyin":"Nǐ zuò fǎn fāngxiàng le, dìtiě yīnggāi wǎng xiāngfǎn de fāngxiàng zuò.","vn":"Bạn đi ngược chiều rồi, tàu điện ngầm phải đi theo hướng ngược lại."}]},{"hanzi":"部分","pinyin":"bùfen","pos":"dt.","vn":"bộ phận, phần","examples":[{"cn":"这本书一共分为三个部分。","pinyin":"Zhè běn shū yígòng fēnwéi sān ge bùfen.","vn":"Cuốn sách này được chia làm tổng cộng ba phần."},{"cn":"大部分学生都同意推迟考试时间。","pinyin":"Dàbùfen xuésheng dōu tóngyì tuīchí kǎoshì shíjiān.","vn":"Phần lớn sinh viên đều đồng ý lùi thời gian thi."},{"cn":"听力部分对我来说是最难的。","pinyin":"Tīnglì bùfen duì wǒ láishuō shì zuì nán de.","vn":"Phần nghe hiểu đối với tôi là khó nhất."}]},{"hanzi":"轻松","pinyin":"qīngsōng","pos":"tt.","vn":"nhẹ nhàng, thoải mái, thư thái","examples":[{"cn":"考完试以后，我觉得整个人都轻松多了。","pinyin":"Kǎowán shì yǐhòu, wǒ juéde zhěng ge rén dōu qīngsōng duō le.","vn":"Sau khi thi xong, tôi cảm thấy cả người nhẹ nhõm hẳn đi."},{"cn":"周末听听轻音乐，可以让人心情变得轻松。","pinyin":"Zhōumò tīngting qīngyīnyuè, kěyǐ ràng rén xīnqíng biàn de qīngsōng.","vn":"Cuối tuần nghe chút nhạc nhẹ có thể giúp tâm trạng con người trở nên thư thái."},{"cn":"看起来很简单，其实这份工作一点儿也不轻松。","pinyin":"Kàn qǐlai hěn jiǎndān, qíshí zhè fèn gōngzuò yìdiǎnr yě bù qīngsōng.","vn":"Trông có vẻ đơn giản, thực ra công việc này chẳng nhẹ nhàng chút nào."}]},{"hanzi":"标准","pinyin":"biāozhǔn","pos":"tt./dt.","vn":"tiêu chuẩn, chuẩn mực","examples":[{"cn":"他的普通话说得非常标准。","pinyin":"Tā de Pǔtōnghuà shuō de fēicháng biāozhǔn.","vn":"Anh ấy nói tiếng phổ thông vô cùng chuẩn."},{"cn":"请问这家公司的招聘标准是什么？","pinyin":"Qǐngwèn zhè jiā gōngsī de zhāopìn biāozhǔn shì shénme?","vn":"Xin hỏi tiêu chuẩn tuyển dụng của công ty này là gì?"},{"cn":"每个人对幸福的标准都不太一样。","pinyin":"Měi ge rén duì xìngfú de biāozhǔn dōu bú tài yíyàng.","vn":"Tiêu chuẩn về hạnh phúc của mỗi người đều không giống nhau."}]},{"hanzi":"严格","pinyin":"yángé","pos":"tt./dgt.","vn":"nghiêm khắc, nghiêm ngặt; thực hiện nghiêm túc","examples":[{"cn":"李老师对学生的要求非常严格。","pinyin":"Lǐ lǎoshī duì xuésheng de yāoqiú fēicháng yángé.","vn":"Thầy Lý yêu cầu đối với học sinh vô cùng nghiêm khắc."},{"cn":"我们要严格按照公司的规定办事。","pinyin":"Wǒmen yào yángé ànzhào gōngsī de guīdìng bànshì.","vn":"Chúng ta phải làm việc nghiêm ngặt theo đúng quy định của công ty."},{"cn":"这家工厂对产品质量的检查十分严格。","pinyin":"Zhè jiā gōngchǎng duì chǎnpǐn zhìliàng de jiǎnchá shífēn yángé.","vn":"Nhà máy này kiểm tra chất lượng sản phẩm hết sức nghiêm ngặt."}]},{"hanzi":"取得","pinyin":"qǔdé","pos":"dgt.","vn":"giành được, đạt được","examples":[{"cn":"经过一年的努力，他在中文学习上取得了很大进步。","pinyin":"Jīngguò yì nián de nǔlì, tā zài Zhōngwén xuéxí shang qǔdé le hěn dà jìnbù.","vn":"Qua một năm nỗ lực, anh ấy đã đạt được tiến bộ rất lớn trong việc học tiếng Trung."},{"cn":"祝你们这次合作取得圆满成功！","pinyin":"Zhù nǐmen zhè cì hézuò qǔdé yuánmǎn chénggōng!","vn":"Chúc sự hợp tác lần này của các bạn đạt được thành công mỹ mãn!"},{"cn":"我们已经和活动负责人取得了联系。","pinyin":"Wǒmen yǐjīng hé huódòng fùzérén qǔdé le liánxì.","vn":"Chúng tôi đã liên lạc được với người phụ trách hoạt động rồi."}]},{"hanzi":"说不定","pinyin":"shuōbudìng","pos":"phó.","vn":"biết đâu, có lẽ, chưa chắc","examples":[{"cn":"天这么阴，带上伞吧，说不定一会儿会下雨。","pinyin":"Tiān zhème yīn, dàishàng sǎn ba, shuōbudìng yíhuìr huì xiàyǔ.","vn":"Trời âm u thế này, mang ô đi nhé, biết đâu lát nữa sẽ mưa."},{"cn":"你再去问问经理，说不定他会同意你的建议。","pinyin":"Nǐ zài qù wènwen jīnglǐ, shuōbudìng tā huì tóngyì nǐ de jiànyì.","vn":"Bạn đi hỏi giám đốc lần nữa xem, biết đâu ông ấy sẽ đồng ý với đề nghị của bạn."},{"cn":"别着急，他现在说不定还在来学校的路上呢。","pinyin":"Bié zháojí, tā xiànzài shuōbudìng hái zài lái xuéxiào de lùshang ne.","vn":"Đừng vội, biết đâu bây giờ anh ấy vẫn đang trên đường tới trường đấy."}]},{"hanzi":"灵活","pinyin":"línghuó","pos":"tt.","vn":"linh hoạt","examples":[{"cn":"遇到突发情况时，我们要学会灵活处理。","pinyin":"Yùdào tūfā qíngkuàng shí, wǒmen yào xuéhuì línghuó chǔlǐ.","vn":"Khi gặp tình huống đột xuất, chúng ta cần học cách xử lý linh hoạt."},{"cn":"这家公司的上班时间比较灵活。","pinyin":"Zhè jiā gōngsī de shàngbān shíjiān bǐjiào línghuó.","vn":"Thời gian làm việc của công ty này tương đối linh hoạt."},{"cn":"他头脑很灵活，总能想到解决问题的办法。","pinyin":"Tā tóunǎo hěn línghuó, zǒng néng xiǎngdào jiějué wèntí de bànfǎ.","vn":"Đầu óc anh ấy rất linh hoạt, luôn nghĩ ra được cách giải quyết vấn đề."}]},{"hanzi":"一切","pinyin":"yíqiè","pos":"đt.","vn":"tất cả, mọi thứ","examples":[{"cn":"祝你在新的城市里一切顺利！","pinyin":"Zhù nǐ zài xīn de chéngshì lǐ yíqiè shùnlì!","vn":"Chúc bạn ở thành phố mới mọi thứ đều thuận lợi!"},{"cn":"会议前的一切准备工作都已经完成了。","pinyin":"Huìyì qián de yíqiè zhǔnbèi gōngzuò dōu yǐjīng wánchéng le.","vn":"Mọi công tác chuẩn bị trước cuộc họp đều đã hoàn thành rồi."},{"cn":"时间会慢慢改变一切的。","pinyin":"Shíjiān huì mànmàn gǎibiàn yíqiè de.","vn":"Thời gian sẽ dần dần thay đổi tất cả."}]},{"hanzi":"却","pinyin":"què","pos":"phó.","vn":"nhưng, lại, mà lại","examples":[{"cn":"他嘴上说没关系，心里却非常难过。","pinyin":"Tā zuǐshang shuō méiguānxi, xīnli què fēicháng nánguò.","vn":"Miệng anh ấy nói không sao, nhưng trong lòng lại vô cùng buồn bã."},{"cn":"我已经到了饭店，他却临时通知我说来不了了。","pinyin":"Wǒ yǐjīng dào le fàndiàn, tā què línshí tōngzhī wǒ shuō lái bu liǎo le.","vn":"Tôi đã đến nhà hàng rồi, vậy mà anh ấy lại đột xuất báo không tới được."},{"cn":"这个问题看起来很简单，做起来却很不容易。","pinyin":"Zhège wèntí kàn qǐlai hěn jiǎndān, zuò qǐlai què hěn bù róngyì.","vn":"Vấn đề này nhìn có vẻ đơn giản, nhưng làm thì lại chẳng dễ dàng chút nào."}]},{"hanzi":"不得不","pinyin":"bùdébù","pos":"phó.","vn":"buộc phải, đành phải, không thể không","examples":[{"cn":"因为突然生病，她不得不取消了这次旅行。","pinyin":"Yīnwèi tūrán shēngbìng, tā bùdébù qǔxiāo le zhè cì lǚxíng.","vn":"Vì đột nhiên bị ốm, cô ấy buộc phải hủy bỏ chuyến du lịch lần này."},{"cn":"时间太紧了，我们今天晚上不得不加班。","pinyin":"Shíjiān tài jǐn le, wǒmen jīntiān wǎnshang bùdébù jiābān.","vn":"Thời gian gấp quá rồi, tối nay chúng tôi buộc phải tăng ca."},{"cn":"面对这样的变化，大家不得不调整原来的计划。","pinyin":"Miànduì zhèyàng de biànhuà, dàjiā bùdébù tiáozhěng yuánlái de jìhuà.","vn":"Đối mặt với sự thay đổi như vậy, mọi người buộc phải điều chỉnh kế hoạch ban đầu."}]},{"hanzi":"约","pinyin":"yuē","pos":"dgt./phó.","vn":"hẹn; khoảng, ước chừng","examples":[{"cn":"周末我想约几个老朋友一起吃顿饭。","pinyin":"Zhōumò wǒ xiǎng yuē jǐ ge lǎo péngyou yìqǐ chī dùn fàn.","vn":"Cuối tuần tôi muốn hẹn vài người bạn cũ cùng ăn một bữa cơm."},{"cn":"从我家到公司坐地铁约需要三十分钟。","pinyin":"Cóng wǒ jiā dào gōngsī zuò dìtiě yuē xūyào sānshí fēnzhōng.","vn":"Từ nhà tôi đến công ty đi tàu điện ngầm mất khoảng ba mươi phút."},{"cn":"我已经约好了医生，明天上午去检查身体。","pinyin":"Wǒ yǐjīng yuēhǎo le yīshēng, míngtiān shàngwǔ qù jiǎnchá shēntǐ.","vn":"Tôi đã hẹn bác sĩ rồi, sáng mai đi khám sức khỏe."}]},{"hanzi":"不便","pinyin":"búbiàn","pos":"tt./dgt.","vn":"bất tiện; không tiện (làm gì)","examples":[{"cn":"施工期间给您带来的不便，请多多谅解。","pinyin":"Shīgōng qījiān gěi nín dàilái de búbiàn, qǐng duōduō liàngjiě.","vn":"Mong quý khách thông cảm cho sự bất tiện trong thời gian thi công."},{"cn":"那里交通不太发达，出行有点儿不便。","pinyin":"Nàlǐ jiāotōng bú tài fādá, chūxíng yǒudiǎnr búbiàn.","vn":"Giao thông ở đó không phát triển lắm, đi lại hơi bất tiện."},{"cn":"这件事涉及个人隐私，我现在不便多说。","pinyin":"Zhè jiàn shì shèjí gèrén yǐnsī, wǒ xiànzài búbiàn duō shuō.","vn":"Chuyện này liên quan đến quyền riêng tư cá nhân, hiện tại tôi không tiện nói nhiều."}]},{"hanzi":"失望","pinyin":"shīwàng","pos":"tt./dgt.","vn":"thất vọng; mất hy vọng","examples":[{"cn":"没能通过这次面试，他感到非常失望。","pinyin":"Méi néng tōngguò zhè cì miànshì, tā gǎndào fēicháng shīwàng.","vn":"Không thể vượt qua buổi phỏng vấn lần này, anh ấy cảm thấy vô cùng thất vọng."},{"cn":"放心吧，我一定会努力，不会让你失望的。","pinyin":"Fàngxīn ba, wǒ yídìng huì nǔlì, bú huì ràng nǐ shīwàng de.","vn":"Yên tâm đi, tôi nhất định sẽ cố gắng, sẽ không làm bạn thất vọng đâu."},{"cn":"别失望，以后肯定还会有更好的机会。","pinyin":"Bié shīwàng, yǐhòu kěndìng hái huì yǒu gèng hǎo de jīhuì.","vn":"Đừng thất vọng, sau này chắc chắn vẫn sẽ có cơ hội tốt hơn."}]},{"hanzi":"也许","pinyin":"yěxǔ","pos":"phó.","vn":"có lẽ, biết đâu","examples":[{"cn":"他今天没来上课，也许是生病了。","pinyin":"Tā jīntiān méi lái shàngkè, yěxǔ shì shēngbìng le.","vn":"Hôm nay cậu ấy không đến lớp, có lẽ là bị ốm rồi."},{"cn":"换个角度想想，也许这件事并没有那么糟糕。","pinyin":"Huàn ge jiǎodù xiǎngxiang, yěxǔ zhè jiàn shì bìng méiyǒu nàme zāogāo.","vn":"Thử suy nghĩ ở một góc độ khác xem, có lẽ chuyện này vốn không tệ đến thế đâu."},{"cn":"明年夏天，我也许会去上海工作。","pinyin":"Míngnián xiàtiān, wǒ yěxǔ huì qù Shànghǎi gōngzuò.","vn":"Mùa hè năm sau, có lẽ tôi sẽ đến Thượng Hải làm việc."}]},{"hanzi":"逛","pinyin":"guàng","pos":"dgt.","vn":"dạo chơi, đi dạo","examples":[{"cn":"周末我喜欢和闺蜜一起逛商场。","pinyin":"Zhōumò wǒ xǐhuan hé guīmì yìqǐ guàng shāngchǎng.","vn":"Cuối tuần tôi thích đi dạo trung tâm thương mại cùng bạn thân."},{"cn":"晚饭后，我们去家附近的公园逛了逛。","pinyin":"Wǎnfàn hòu, wǒmen qù jiā fùjìn de gōngyuán guàng le guàng.","vn":"Sau bữa tối, chúng tôi ra công viên gần nhà đi dạo một vòng."},{"cn":"去北京旅游的时候，我逛了不少老胡同。","pinyin":"Qù Běijīng lǚyóu de shíhou, wǒ guàng le bùshǎo lǎo hútòng.","vn":"Khi đi du lịch Bắc Kinh, tôi đã đi dạo qua khá nhiều con ngõ cổ."}]},{"hanzi":"有趣","pinyin":"yǒuqù","pos":"tt.","vn":"thú vị, hay","examples":[{"cn":"这本书里写了很多有趣的历史故事。","pinyin":"Zhè běn shū lǐ xiě le hěn duō yǒuqù de lìshǐ gùshi.","vn":"Trong cuốn sách này viết rất nhiều câu chuyện lịch sử thú vị."},{"cn":"他是一个非常幽默有趣的人，大家都很喜欢他。","pinyin":"Tā shì yí ge fēicháng yōumò yǒuqù de rén, dàjiā dōu hěn xǐhuan tā.","vn":"Anh ấy là một người vô cùng hài hước và thú vị, mọi người đều rất quý anh ấy."},{"cn":"今天的文化体验课真有趣！","pinyin":"Jīntiān de wénhuà tǐyànkè zhēn yǒuqù!","vn":"Tiết trải nghiệm văn hóa hôm nay thật thú vị!"}]},{"hanzi":"观看","pinyin":"guānkàn","pos":"dgt.","vn":"xem, theo dõi","examples":[{"cn":"昨天晚上，全家人一起在电视机前观看了足球比赛。","pinyin":"Zuótiān wǎnshang, quánjiārén yìqǐ zài diànshìjī qián guānkàn le zúqiú bǐsài.","vn":"Tối hôm qua, cả gia đình đã cùng ngồi trước tivi xem trận đấu bóng đá."},{"cn":"礼堂里坐满了前来观看演出的观众。","pinyin":"Lǐtáng lǐ zuòmǎn le qiánlái guānkàn yǎnchū de guānzhòng.","vn":"Trong hội trường ngồi chật kín khán giả đến xem biểu diễn."},{"cn":"大家可以通过手机在线观看这场直播。","pinyin":"Dàjiā kěyǐ tōngguò shǒujī zàixiàn guānkàn zhè chǎng zhíbō.","vn":"Mọi người có thể xem trực tuyến buổi phát sóng trực tiếp này qua điện thoại."}]},{"hanzi":"部","pinyin":"bù","pos":"lượng.","vn":"bộ (lượng từ cho sách, phim, tác phẩm,...)","examples":[{"cn":"我上周末看了一部非常感人的电影。","pinyin":"Wǒ shàng zhōumò kàn le yí bù fēicháng gǎnrén de diànyǐng.","vn":"Cuối tuần trước tôi đã xem một bộ phim vô cùng cảm động."},{"cn":"这位作家写过多部著名的小说。","pinyin":"Zhè wèi zuòjiā xiěguo duō bù zhùmíng de xiǎoshuō.","vn":"Nhà văn này đã viết nhiều bộ tiểu thuyết nổi tiếng."},{"cn":"我爸爸刚买了一部新手机。","pinyin":"Wǒ bàba gāng mǎi le yí bù xīn shǒujī.","vn":"Bố tôi vừa mua một chiếc điện thoại mới."}]},{"hanzi":"无法","pinyin":"wúfǎ","pos":"dgt.","vn":"không cách nào, không thể","examples":[{"cn":"因为临时有急事，我今天无法参加会议了。","pinyin":"Yīnwèi línshí yǒu jíshì, wǒ jīntiān wúfǎ cānjiā huìyì le.","vn":"Vì đột xuất có việc gấp, hôm nay tôi không thể tham dự cuộc họp được."},{"cn":"这个问题太复杂了，我一个人无法解决。","pinyin":"Zhège wèntí tài fùzá le, wǒ yí ge rén wúfǎ jiějué.","vn":"Vấn đề này quá phức tạp, một mình tôi không thể nào giải quyết được."},{"cn":"未来有很多事情是我们现在无法预测的。","pinyin":"Wèilái yǒu hěn duō shìqing shì wǒmen xiànzài wúfǎ yùcè de.","vn":"Trong tương lai có rất nhiều chuyện mà hiện tại chúng ta không cách nào dự đoán trước được."}]},{"hanzi":"接受","pinyin":"jiēshòu","pos":"dgt.","vn":"tiếp nhận, chấp nhận","examples":[{"cn":"他虚心地接受了大家提出的意见。","pinyin":"Tā xūxīn de jiēshòu le dàjiā tíchū de yìjiàn.","vn":"Anh ấy khiêm tốn tiếp thu ý kiến do mọi người đóng góp."},{"cn":"面对失败，我们要学会勇敢接受并总结经验。","pinyin":"Miànduì shībài, wǒmen yào xuéhuì yǒnggǎn jiēshòu bìng zǒngjié jīngyàn.","vn":"Đối mặt với thất bại, chúng ta phải học cách dũng cảm chấp nhận và rút kinh nghiệm."},{"cn":"非常感谢您接受我们的采访。","pinyin":"Fēicháng gǎnxiè nín jiēshòu wǒmen de cǎifǎng.","vn":"Vô cùng cảm ơn ông/bà đã nhận lời phỏng vấn của chúng tôi."}]}],"grammar":[{"title":"\"把\"字句\"主语+把+宾语+动词+了\"","explanation_vn":"Câu chữ \"把\" dạng \"主语+把+宾语+动词+了\" biểu thị việc thực hiện sự xử lý tương ứng đối với người hoặc sự vật xác định và tạo ra một kết quả nào đó.","examples":[{"cn":"我已经把机票和酒店取消了。","pinyin":"Wǒ yǐjīng bǎ jīpiào hé jiǔdiàn qǔxiāo le.","vn":"Mình đã hủy vé máy bay và khách sạn rồi."},{"cn":"你把灯关了吧，我想睡觉了。","pinyin":"Nǐ bǎ dēng guān le ba, wǒ xiǎng shuìjiào le.","vn":"Cậu tắt đèn đi nhé, mình muốn đi ngủ rồi."},{"cn":"你别忘了把衣服洗了，明天还得穿呢。","pinyin":"Nǐ bié wàng le bǎ yīfu xǐ le, míngtiān hái děi chuān ne.","vn":"Cậu đừng quên giặt quần áo nhé, ngày mai còn phải mặc đấy."}]},{"title":"递进复句\"……，并且……\"","explanation_vn":"Trong câu phức tăng tiến \"……，并且……\", từ \"并且\" dùng để nối các hành động hoặc tình huống, biểu thị sự giải thích, bổ sung thêm một bước nữa.","examples":[{"cn":"再检查一下有没有细节上的错误，并且试着增加一些例子。","pinyin":"Zài jiǎnchá yíxià yǒu méiyǒu xìjié shàng de cuòwù, bìngqiě shìzhe zēngjiā yìxiē lìzi.","vn":"Kiểm tra lại xem có lỗi nào về mặt chi tiết không, đồng thời thử thêm một số ví dụ nữa."},{"cn":"他按时完成了任务，并且做得很好。","pinyin":"Tā ànshí wánchéng le rènwu, bìngqiě zuò de hěn hǎo.","vn":"Anh ấy đã hoàn thành nhiệm vụ đúng hạn, hơn nữa còn làm rất tốt."},{"cn":"人们的生活水平提高了，并且生活方式也发生了很大的变化。","pinyin":"Rénmen de shēnghuó shuǐpíng tígāo le, bìngqiě shēnghuó fāngshì yě fāshēng le hěn dà de biànhuà.","vn":"Mức sống của người dân đã được nâng cao, đồng thời lối sống cũng xảy ra thay đổi rất lớn."}]},{"title":"固定短语\"说不定\"","explanation_vn":"Cụm từ cố định \"说不定\" biểu thị sự suy đoán, ước lượng đối với tình huống hoặc kết quả có thể xảy ra.","examples":[{"cn":"不做计划，说不定也会带来新的发现。","pinyin":"Bú zuò jìhuà, shuōbudìng yě huì dàilái xīn de fāxiàn.","vn":"Không lập kế hoạch, biết đâu cũng sẽ mang lại những phát hiện mới."},{"cn":"今天这么阴，说不定会下雨。","pinyin":"Jīntiān zhème yīn, shuōbudìng huì xiàyǔ.","vn":"Hôm nay trời âm u thế này, biết đâu sẽ mưa đấy."},{"cn":"你再试一次，说不定就成功了。","pinyin":"Nǐ zài shì yí cì, shuōbudìng jiù chénggōng le.","vn":"Bạn thử lại một lần nữa đi, biết đâu lại thành công."}]},{"title":"关联副词\"却\"","explanation_vn":"Phó từ liên kết \"却\" biểu thị sự chuyển ngoặt (tương phản).","examples":[{"cn":"你准备好了一切，却突然出现了新情况，让你不得不改变计划。","pinyin":"Nǐ zhǔnbèi hǎo le yíqiè, què tūrán chūxiàn le xīn qíngkuàng, ràng nǐ bùdébù gǎibiàn jìhuà.","vn":"Bạn đã chuẩn bị sẵn sàng mọi thứ, nhưng đột nhiên lại xuất hiện tình huống mới, khiến bạn buộc phải thay đổi kế hoạch."},{"cn":"他通过了面试，却一点儿也不激动。","pinyin":"Tā tōngguò le miànshì, què yìdiǎnr yě bù jīdòng.","vn":"Anh ấy đã vượt qua buổi phỏng vấn, nhưng lại chẳng phấn khích chút nào."},{"cn":"她长得很像她姐姐，性格却完全不同。","pinyin":"Tā zhǎng de hěn xiàng tā jiějie, xìnggé què wánquán bùtóng.","vn":"Cô ấy trông rất giống chị gái mình, nhưng tính cách lại hoàn toàn khác nhau."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"家月，周末你还打算去南京旅游吗？我去年去过那里，可以给你介绍一下。","pinyin":"Jiāyuè, zhōumò nǐ hái dǎsuàn qù Nánjīng lǚyóu ma? Wǒ qùnián qùguo nàlǐ, kěyǐ gěi nǐ jièshào yíxià."},{"speaker":"白家月","cn":"本来都计划好了，可是昨天突然接到通知，下周学校要安排一次考试，所以周末只好在家复习了。","pinyin":"Běnlái dōu jìhuà hǎo le, kěshì zuótiān tūrán jiēdào tōngzhī, xià zhōu xuéxiào yào ānpái yí cì kǎoshì, suǒyǐ zhōumò zhǐhǎo zài jiā fùxí le."},{"speaker":"王一雪","cn":"真是计划赶不上变化啊！看来你的旅行计划只能推迟了。","pinyin":"Zhēn shì jìhuà gǎn bu shàng biànhuà a! Kànlái nǐ de lǚxíng jìhuà zhǐ néng tuīchí le."},{"speaker":"白家月","cn":"是的，我已经把机票和酒店取消了。虽然有点儿可惜，但学习更重要。","pinyin":"Shì de, wǒ yǐjīng bǎ jīpiào hé jiǔdiàn qǔxiāo le. Suīrán yǒudiǎnr kěxī, dàn xuéxí gèng zhòngyào."},{"speaker":"王一雪","cn":"学习确实要放在第一位。等到考试结束后，你再找个时间去。","pinyin":"Xuéxí quèshí yào fàng zài dì yī wèi. Děngdào kǎoshì jiéshù hòu, nǐ zài zhǎo ge shíjiān qù."},{"speaker":"白家月","cn":"我也是这么想的，以后肯定还有很多机会。","pinyin":"Wǒ yě shì zhème xiǎng de, yǐhòu kěndìng hái yǒu hěn duō jīhuì."}],"translation_vn":"Vương Nhất Tuyết: Gia Nguyệt, cuối tuần cậu vẫn định đi Nam Kinh du lịch à? Năm ngoái mình từng đến đó rồi, có thể giới thiệu cho cậu đấy.\nBạch Gia Nguyệt: Vốn dĩ đã lên kế hoạch xong xuôi cả rồi, nhưng hôm qua đột nhiên nhận được thông báo tuần sau trường sẽ tổ chức một kỳ thi, nên cuối tuần đành phải ở nhà ôn bài thôi.\nVương Nhất Tuyết: Đúng là kế hoạch không theo kịp sự thay đổi mà! Xem ra kế hoạch du lịch của cậu chỉ có thể hoãn lại rồi.\nBạch Gia Nguyệt: Ừ, mình đã hủy vé máy bay và khách sạn rồi. Tuy có hơi đáng tiếc một chút, nhưng việc học quan trọng hơn.\nVương Nhất Tuyết: Quả thực phải đặt việc học lên hàng đầu. Đợi đến khi thi xong, cậu lại sắp xếp thời gian đi sau nhé.\nBạch Gia Nguyệt: Mình cũng nghĩ vậy, sau này chắc chắn vẫn còn nhiều cơ hội mà.","audio_dialogue":"16-1.mp3","audio_vocab":"16-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"杨同乐","cn":"刚接到通知，明天早晨的会议，时间改到下周了。","pinyin":"Gāng jiēdào tōngzhī, míngtiān zǎochen de huìyì, shíjiān gǎi dào xià zhōu le."},{"speaker":"王一雪","cn":"啊？时间都安排好了，怎么说变就变了？","pinyin":"Á? Shíjiān dōu ānpái hǎo le, zěnme shuō biàn jiù biàn le?"},{"speaker":"杨同乐","cn":"是啊，没想到忽然要改时间。","pinyin":"Shì a, méi xiǎngdào hūrán yào gǎi shíjiān."},{"speaker":"王一雪","cn":"好吧，那再看看有没有新的安排，或者增加的会议内容。","pinyin":"Hǎo ba, nà zài kànkan yǒu méiyǒu xīn de ānpái, huòzhě zēngjiā de huìyì nèiróng."},{"speaker":"杨同乐","cn":"好的。会议材料还需要调整吗？","pinyin":"Hǎo de. Huìyì cáiliào hái xūyào tiáozhěng ma?"},{"speaker":"王一雪","cn":"再检查一下有没有细节上的错误，并且试着增加一些例子，把内容准备得更全一些。","pinyin":"Zài jiǎnchá yíxià yǒu méiyǒu xìjié shàng de cuòwù, bìngqiě shìzhe zēngjiā yìxiē lìzi, bǎ nèiróng zhǔnbèi de gèng quán yìxiē."},{"speaker":"杨同乐","cn":"没问题，这样效果肯定会更好。","pinyin":"Méi wèntí, zhèyàng xiàoguǒ kěndìng huì gèng hǎo."},{"speaker":"王一雪","cn":"看来有时候变化不一定是坏事，关键是我们怎么去适应变化。","pinyin":"Kànlái yǒu shíhou biànhuà bù yídìng shì huàishì, guānjiàn shì wǒmen zěnme qù shìyìng biànhuà."}],"translation_vn":"Dương Đồng Lạc: Vừa nhận được thông báo, cuộc họp sáng mai đã đổi thời gian sang tuần sau rồi.\nVương Nhất Tuyết: Hả? Thời gian đã sắp xếp xong cả rồi, sao nói đổi là đổi ngay thế?\nDương Đồng Lạc: Đúng vậy, không ngờ đột nhiên lại phải đổi giờ.\nVương Nhất Tuyết: Thôi được rồi, vậy xem lại xem có sắp xếp gì mới hoặc có thêm nội dung cuộc họp nào không nhé.\nDương Đồng Lạc: Vâng. Tài liệu cuộc họp có cần điều chỉnh thêm không?\nVương Nhất Tuyết: Kiểm tra lại xem có lỗi nào về chi tiết không, đồng thời thử thêm một số ví dụ để chuẩn bị nội dung đầy đủ hơn một chút.\nDương Đồng Lạc: Không vấn đề gì, làm vậy hiệu quả chắc chắn sẽ tốt hơn.\nVương Nhất Tuyết: Xem ra đôi khi thay đổi không hẳn là chuyện xấu, mấu chốt là chúng ta thích nghi với sự thay đổi đó như thế nào.","audio_dialogue":"16-3.mp3","audio_vocab":"16-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"在生活和工作中，有的人喜欢做计划，他们会提前安排好每天要做的事情，然后按照详细的时间表去完成任务，觉得这样做更有把握。相反，也有一部分人不爱做计划，他们认为随意一些也很好，想到什么就去做什么，感觉这样比较轻松。","pinyin":"Zài shēnghuó hé gōngzuò zhōng, yǒude rén xǐhuan zuò jìhuà, tāmen huì tíqián ānpái hǎo měitiān yào zuò de shìqing, ránhòu ànzhào xiángxì de shíjiānbiǎo qù wánchéng rènwu, juéde zhèyàng zuò gèng yǒu bǎwò. Xiāngfǎn, yě yǒu yí bùfen rén bú ài zuò jìhuà, tāmen rènwéi suíyì yìxiē yě hěn hǎo, xiǎngdào shénme jiù qù zuò shénme, gǎnjué zhèyàng bǐjiào qīngsōng."},{"speaker":"","cn":"其实，事前做计划是好是坏没有标准答案。严格按照计划做事，常常能取得不错的效果；而不做计划，说不定也会带来新的发现。无论做不做计划，只要既能按时完成任务，又能根据情况灵活调整，就是适合自己的方式。","pinyin":"Qíshí, shìqián zuò jìhuà shì hǎo shì huài méiyǒu biāozhǔn dá'àn. Yángé ànzhào jìhuà zuòshì, chángcháng néng qǔdé búcuò de xiàoguǒ; ér bú zuò jìhuà, shuōbudìng yě huì dàilái xīn de fāxiàn. Wúlùn zuò bu zuò jìhuà, zhǐyào jì néng ànshí wánchéng rènwu, yòu néng gēnjù qíngkuàng línghuó tiáozhěng, jiù shì shìhé zìjǐ de fāngshì."}],"translation_vn":"Trong cuộc sống và công việc, có người thích lập kế hoạch, họ sẽ sắp xếp trước những việc cần làm hằng ngày, sau đó hoàn thành nhiệm vụ theo thời gian biểu chi tiết và cảm thấy làm như vậy sẽ chắc chắn hơn. Ngược lại, cũng có một bộ phận người không thích lập kế hoạch, họ cho rằng tùy hứng một chút cũng rất tốt, nghĩ ra gì thì làm nấy, cảm giác như thế tương đối thoải mái.\nThực ra, việc lập kế hoạch trước là tốt hay xấu vốn không có đáp án tiêu chuẩn. Làm việc nghiêm ngặt theo kế hoạch thường mang lại hiệu quả tốt; còn không lập kế hoạch, biết đâu cũng sẽ đem đến những phát hiện mới. Bất kể có lập kế hoạch hay không, chỉ cần vừa có thể hoàn thành nhiệm vụ đúng hạn, vừa có thể linh hoạt điều chỉnh tùy theo tình hình, thì đó chính là phương thức phù hợp với bản thân.","audio_dialogue":"16-5.mp3","audio_vocab":"16-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"人们常说“计划赶不上变化”。有时候，你准备好了一切，却突然出现了新情况，让你不得不改变计划。比如准备出去旅行，可能因为有事而取消；约好见朋友，可能因为天气不好而推迟。","pinyin":"Rénmen cháng shuō “jìhuà gǎn bu shàng biànhuà”. Yǒu shíhou, nǐ zhǔnbèi hǎo le yíqiè, què tūrán chūxiàn le xīn qíngkuàng, ràng nǐ bùdébù gǎibiàn jìhuà. Bǐrú zhǔnbèi chūqù lǚxíng, kěnéng yīnwèi yǒushì ér qǔxiāo; yuēhǎo jiàn péngyou, kěnéng yīnwèi tiānqì bù hǎo ér tuīchí."},{"speaker":"","cn":"虽然变化经常打乱计划，给我们带来不便，甚至让人感到失望，但这些变化也许会给生活带来新的可能。比如没去成旅行，于是在家门口的小公园逛了逛，发现那里也很有趣；没见到朋友，于是在家观看了一部电影，心情也变得很愉快。","pinyin":"Suīrán biànhuà jīngcháng dǎluàn jìhuà, gěi wǒmen dàilái búbiàn, shènzhì ràng rén gǎndào shīwàng, dàn zhèxiē biànhuà yěxǔ huì gěi shēnghuó dàilái xīn de kěnéng. Bǐrú méi qùchéng lǚxíng, yúshì zài jiāménkǒu de xiǎo gōngyuán guàng le guàng, fāxiàn nàlǐ yě hěn yǒuqù; méi jiàndào péngyou, yúshì zài jiā guānkàn le yí bù diànyǐng, xīnqíng yě biànde hěn yúkuài."},{"speaker":"","cn":"生活中很多变化是无法提前知道的，我们要做的就是学会接受变化、适应变化，在变化中找到新的解决办法。这样不仅能锻炼自己在面对不同情况时解决问题的能力，也能让我们的生活更轻松。","pinyin":"Shēnghuó zhōng hěn duō biànhuà shì wúfǎ tíqián zhīdào de, wǒmen yào zuò de jiù shì xuéhuì jiēshòu biànhuà, shìyìng biànhuà, zài biànhuà zhōng zhǎodào xīn de jiějué bànfǎ. Zhèyàng bùjǐn néng duànliàn zìjǐ zài miànduì bùtóng qíngkuàng shí jiějué wèntí de nénglì, yě néng ràng wǒmen de shēnghuó gèng qīngsōng."}],"translation_vn":"Người ta thường nói \"kế hoạch không theo kịp sự thay đổi\". Đôi khi, bạn đã chuẩn bị sẵn sàng mọi thứ, nhưng đột nhiên lại xuất hiện tình huống mới, khiến bạn buộc phải thay đổi kế hoạch. Ví dụ định đi du lịch, có thể bị hủy vì có việc bận; hẹn gặp bạn bè, có thể phải hoãn lại vì thời tiết xấu.\nMặc dù sự thay đổi thường làm đảo lộn kế hoạch, gây ra bất tiện cho chúng ta, thậm chí khiến người ta cảm thấy thất vọng, nhưng những thay đổi ấy có lẽ sẽ mang lại cho cuộc sống những khả năng mới. Ví dụ không đi du lịch được, thế là đi dạo quanh công viên nhỏ trước cửa nhà, lại phát hiện nơi đó cũng rất thú vị; không gặp được bạn, thế là ở nhà xem một bộ phim, tâm trạng cũng trở nên rất vui vẻ.\nRất nhiều thay đổi trong cuộc sống là điều không thể biết trước được, việc chúng ta cần làm là học cách chấp nhận thay đổi, thích nghi với thay đổi và tìm ra cách giải quyết mới trong sự thay đổi đó. Làm như vậy không chỉ rèn luyện được năng lực giải quyết vấn đề của bản thân khi đối mặt với những tình huống khác nhau, mà còn giúp cuộc sống của chúng ta nhẹ nhàng hơn.","audio_dialogue":"16-7.mp3","audio_vocab":"16-8.mp3"}]},{"id":17,"title_cn":"运动让我更健康","title_pinyin":"Yùndòng ràng wǒ gèng jiànkāng","title_vn":"Vận động giúp tôi khỏe mạnh hơn","goals":["Có thể nghe hiểu và trao đổi các nội dung về phương thức tập thể hình, thói quen rèn luyện sức khỏe,...","Có thể trình bày bằng lời nói hoặc văn bản về trải nghiệm tập thể hình và môn thể thao yêu thích của bản thân.","Hiểu được sự phát triển và tầm ảnh hưởng của môn bóng bàn tại Trung Quốc."],"vocab":[{"hanzi":"路过","pinyin":"lùguò","pos":"dgt.","vn":"đi ngang qua","examples":[{"cn":"我下班回家的时候正好路过那家超市。","pinyin":"Wǒ xiàbān huíjiā de shíhou zhènghǎo lùguò nà jiā chāoshì.","vn":"Lúc tan làm về nhà tôi vừa hay đi ngang qua siêu thị đó."},{"cn":"如果你路过学校门口，顺便帮我拿个快递吧。","pinyin":"Rúguǒ nǐ lùguò xuéxiào ménkǒu, shùnbiàn bāng wǒ ná ge kuàidì ba.","vn":"Nếu bạn đi ngang qua cổng trường thì tiện thể lấy giúp tôi một bưu kiện nhé."},{"cn":"刚才我路过会议室，看见大家正在开会。","pinyin":"Gāngcái wǒ lùguò huìyìshì, kànjiàn dàjiā zhèngzài kāihuì.","vn":"Vừa nãy tôi đi ngang qua phòng họp, thấy mọi người đang họp."}]},{"hanzi":"趟","pinyin":"tàng","pos":"lượng.","vn":"chuyến, lượt (lượng từ cho chuyến đi về)","examples":[{"cn":"明天我要去一趟上海出差。","pinyin":"Míngtiān wǒ yào qù yí tàng Shànghǎi chūchāi.","vn":"Ngày mai tôi phải đi Thượng Hải công tác một chuyến."},{"cn":"这趟高铁只需要四个小时就能到北京。","pinyin":"Zhè tàng gāotiě zhǐ xūyào sì ge xiǎoshí jiù néng dào Běijīng.","vn":"Chuyến tàu cao tốc này chỉ cần bốn tiếng đồng hồ là có thể đến Bắc Kinh."},{"cn":"我一会儿得回家一趟，忘带身份证了。","pinyin":"Wǒ yíhuìr děi huíjiā yí tàng, wàng dài shēnfènzhèng le.","vn":"Một lát nữa tôi phải về nhà một chuyến, quên mang thẻ căn cước rồi."}]},{"hanzi":"健身房","pinyin":"jiànshēnfáng","pos":"dt.","vn":"phòng tập thể hình, phòng gym","examples":[{"cn":"我们小区附近新开了一家健身房。","pinyin":"Wǒmen xiǎoqū fùjìn xīn kāi le yì jiā jiànshēnfáng.","vn":"Gần khu dân cư của chúng tôi mới mở một phòng tập thể hình."},{"cn":"他每周去健身房锻炼三次。","pinyin":"Tā měi zhōu qù jiànshēnfáng duànliàn sān cì.","vn":"Anh ấy mỗi tuần đến phòng gym tập luyện ba lần."},{"cn":"这家健身房环境很好，而且离公司很近。","pinyin":"Zhè jiā jiànshēnfáng huánjìng hěn hǎo, érqiě lí gōngsī hěn jìn.","vn":"Phòng gym này môi trường rất tốt, hơn nữa còn rất gần công ty."}]},{"hanzi":"健身","pinyin":"jiànshēn","pos":"dgt.","vn":"tập thể hình, rèn luyện thân thể","examples":[{"cn":"坚持健身让他看起来精神多了。","pinyin":"Jiānchí jiànshēn ràng tā kàn qǐlai jīngshen duō le.","vn":"Kiên trì tập thể hình giúp anh ấy trông tràn đầy sức sống hơn hẳn."},{"cn":"现在越来越多的年轻人喜欢下班后去健身。","pinyin":"Xiànzài yuè lái yuè duō de niánqīngrén xǐhuan xiàbān hòu qù jiànshēn.","vn":"Hiện nay ngày càng nhiều người trẻ thích đi tập thể hình sau giờ tan làm."},{"cn":"你是从什么时候开始健身的？","pinyin":"Nǐ shì cóng shénme shíhou kāishǐ jiànshēn de?","vn":"Bạn bắt đầu tập thể hình từ khi nào vậy?"}]},{"hanzi":"体重","pinyin":"tǐzhòng","pos":"dt.","vn":"cân nặng, trọng lượng cơ thể","examples":[{"cn":"最近吃得太多，我的体重增加了三公斤。","pinyin":"Zuìjìn chī de tài duō, wǒ de tǐzhòng zēngjiā le sān gōngjīn.","vn":"Gần đây ăn nhiều quá, cân nặng của tôi đã tăng thêm ba cân."},{"cn":"医生建议他控制饮食，保持健康的体重。","pinyin":"Yīshēng jiànyì tā kòngzhì yǐnshí, bǎochí jiànkāng de tǐzhòng.","vn":"Bác sĩ khuyên anh ấy kiểm soát chế độ ăn uống, duy trì cân nặng khỏe mạnh."},{"cn":"坚持跑步两个月后，她的体重减轻了不少。","pinyin":"Jiānchí pǎobù liǎng ge yuè hòu, tā de tǐzhòng jiǎnqīng le bùshǎo.","vn":"Sau hai tháng kiên trì chạy bộ, cân nặng của cô ấy đã giảm đi đáng kể."}]},{"hanzi":"会员","pinyin":"huìyuán","pos":"dt.","vn":"hội viên, thành viên","examples":[{"cn":"在这家超市办会员卡可以享受打折优惠。","pinyin":"Zài zhè jiā chāoshì bàn huìyuánkǎ kěyǐ xiǎngshòu dǎzhé yōuhuì.","vn":"Làm thẻ hội viên ở siêu thị này có thể được hưởng ưu đãi giảm giá."},{"cn":"我是这家书店的老会员了。","pinyin":"Wǒ shì zhè jiā shūdiàn de lǎo huìyuán le.","vn":"Tôi là hội viên lâu năm của hiệu sách này rồi."},{"cn":"现在成为会员，还可以免费体验两节课程。","pinyin":"Xiànzài chéngwéi huìyuán, hái kěyǐ miǎnfèi tǐyàn liǎng jié kèchéng.","vn":"Trở thành hội viên ngay bây giờ còn có thể trải nghiệm miễn phí hai buổi học."}]},{"hanzi":"饼干","pinyin":"bǐnggān","pos":"dt.","vn":"bánh quy","examples":[{"cn":"饿了的话，先吃点儿饼干垫垫肚子吧。","pinyin":"È le de huà, xiān chī diǎnr bǐnggān diàndian dùzi ba.","vn":"Nếu đói thì ăn tạm chút bánh quy lót dạ trước đi."},{"cn":"妹妹最喜欢吃巧克力味道的饼干。","pinyin":"Mèimei zuì xǐhuan chī qiǎokèlì wèidào de bǐnggān.","vn":"Em gái thích ăn nhất là bánh quy vị sô-cô-la."},{"cn":"桌子上放着一盒妈妈刚烤好的饼干。","pinyin":"Zhuōzi shang fàng zhe yì hé māma gāng kǎo hǎo de bǐnggān.","vn":"Trên bàn có đặt một hộp bánh quy mẹ vừa mới nướng xong."}]},{"hanzi":"酸奶","pinyin":"suānnǎi","pos":"dt.","vn":"sữa chua","examples":[{"cn":"每天早饭后喝一杯酸奶对身体很有好处。","pinyin":"Měitiān zǎofàn hòu hē yì bēi suānnǎi duì shēntǐ hěn yǒu hǎochù.","vn":"Mỗi ngày uống một cốc sữa chua sau bữa sáng rất có lợi cho sức khỏe."},{"cn":"冰箱里的酸奶快过期了，记得早点儿喝完。","pinyin":"Bīngxiāng lǐ de suānnǎi kuài guòqī le, jìde zǎodiǎnr hē wán.","vn":"Sữa chua trong tủ lạnh sắp hết hạn rồi, nhớ uống sớm cho hết nhé."},{"cn":"我喜欢在酸奶里加一些新鲜的水果。","pinyin":"Wǒ xǐhuan zài suānnǎi lǐ jiā yìxiē xīnxiān de shuǐguǒ.","vn":"Tôi thích thêm một ít hoa quả tươi vào sữa chua."}]},{"hanzi":"果汁","pinyin":"guǒzhī","pos":"dt.","vn":"nước ép trái cây","examples":[{"cn":"请问，您要喝茶、咖啡还是果汁？","pinyin":"Qǐngwèn, nín yào hē chá, kāfēi háishi guǒzhī?","vn":"Xin hỏi, quý khách muốn uống trà, cà phê hay nước ép trái cây?"},{"cn":"夏天喝一杯冰凉的果汁特别舒服。","pinyin":"Xiàtiān hē yì bēi bīngliáng de guǒzhī tèbié shūfu.","vn":"Mùa hè uống một cốc nước ép trái cây mát lạnh thật đặc biệt dễ chịu."},{"cn":"她每天早上都会自己做新鲜的苹果果汁。","pinyin":"Tā měitiān zǎoshang dōu huì zìjǐ zuò xīnxiān de píngguǒ guǒzhī.","vn":"Mỗi sáng cô ấy đều tự làm nước ép táo tươi."}]},{"hanzi":"教练","pinyin":"jiàoliàn","pos":"dt.","vn":"huấn luyện viên","examples":[{"cn":"我们的游泳教练非常有耐心。","pinyin":"Wǒmen de yóuyǒng jiàoliàn fēicháng yǒu nàixīn.","vn":"Huấn luyện viên bơi lội của chúng tôi vô cùng kiên nhẫn."},{"cn":"在教练的指导下，我的动作越来越标准了。","pinyin":"Zài jiàoliàn de zhǐdǎo xià, wǒ de dòngzuò yuè lái yuè biāozhǔn le.","vn":"Dưới sự hướng dẫn của huấn luyện viên, động tác của tôi ngày càng chuẩn xác."},{"cn":"他以前是国家队运动员，现在当了篮球教练。","pinyin":"Tā yǐqián shì guójiāduì yùndòngyuán, xiànzài dāng le lánqiú jiàoliàn.","vn":"Trước đây anh ấy là vận động viên đội tuyển quốc gia, nay làm huấn luyện viên bóng rổ."}]},{"hanzi":"动作","pinyin":"dòngzuò","pos":"dt.","vn":"động tác","examples":[{"cn":"这个动作有点儿难，请你再示范一遍。","pinyin":"Zhège dòngzuò yǒudiǎnr nán, qǐng nǐ zài shìfàn yí biàn.","vn":"Động tác này hơi khó một chút, phiền bạn làm mẫu lại một lần nữa."},{"cn":"健身时如果动作不标准，很容易受伤。","pinyin":"Jiànshēn shí rúguǒ dòngzuò bù biāozhǔn, hěn róngyì shòushāng.","vn":"Khi tập thể hình nếu động tác không chuẩn thì rất dễ bị thương."},{"cn":"你动作快一点儿，火车马上就要开了。","pinyin":"Nǐ dòngzuò kuài yìdiǎnr, huǒchē mǎshàng jiù yào kāi le.","vn":"Bạn nhanh tay nhanh chân lên một chút, tàu hỏa sắp chạy rồi."}]},{"hanzi":"科学","pinyin":"kēxué","pos":"tt./dt.","vn":"khoa học","examples":[{"cn":"随着科学的发展，人们的生活越来越便利。","pinyin":"Suízhe kēxué de fāzhǎn, rénmen de shēnghuó yuè lái yuè biànlì.","vn":"Cùng với sự phát triển của khoa học, cuộc sống của con người ngày càng tiện lợi."},{"cn":"减肥一定要用科学的方法，不能只靠节食。","pinyin":"Jiǎnféi yídìng yào yòng kēxué de fāngfǎ, bù néng zhǐ kào jiéshí.","vn":"Giảm cân nhất định phải dùng phương pháp khoa học, không thể chỉ dựa vào nhịn ăn."},{"cn":"这个时间安排非常科学，学习效率提高了不少。","pinyin":"Zhège shíjiān ānpái fēicháng kēxué, xuéxí xiàolǜ tígāo le bùshǎo.","vn":"Cách sắp xếp thời gian này rất khoa học, hiệu suất học tập đã nâng cao đáng kể."}]},{"hanzi":"受伤","pinyin":"shòushāng","pos":"dgt.","vn":"bị thương","examples":[{"cn":"他昨天踢足球的时候不小心脚受伤了。","pinyin":"Tā zuótiān tī zúqiú de shíhou bù xiǎoxīn jiǎo shòushāng le.","vn":"Hôm qua lúc đá bóng anh ấy không cẩn thận bị thương ở chân."},{"cn":"运动前做好热身，可以避免受伤。","pinyin":"Yùndòng qián zuò hǎo rèshēn, kěyǐ bìmiǎn shòushāng.","vn":"Khởi động kỹ trước khi vận động có thể tránh bị chấn thương."},{"cn":"听说你受伤了，现在好点儿了吗？","pinyin":"Tīngshuō nǐ shòushāng le, xiànzài hǎo diǎnr le ma?","vn":"Nghe nói bạn bị thương, bây giờ đã đỡ hơn chút nào chưa?"}]},{"hanzi":"操场","pinyin":"cāochǎng","pos":"dt.","vn":"sân vận động, sân tập","examples":[{"cn":"每天傍晚都有很多学生在操场上跑步。","pinyin":"Měitiān bàngwǎn dōu yǒu hěn duō xuésheng zài cāochǎng shang pǎobù.","vn":"Mỗi buổi chiều tối đều có rất nhiều học sinh chạy bộ trên sân vận động."},{"cn":"我们学校的操场非常大，可以同时举行好几场比赛。","pinyin":"Wǒmen xuéxiào de cāochǎng fēicháng dà, kěyǐ tóngshí jǔxíng hǎojǐ chǎng bǐsài.","vn":"Sân vận động của trường chúng tôi rất rộng, có thể cùng lúc tổ chức nhiều trận đấu."},{"cn":"下课了，同学们纷纷跑到操场上玩儿。","pinyin":"Xiàkè le, tóngxuémen fēnfēn pǎodào cāochǎng shang wánr.","vn":"Tan học rồi, các bạn học sinh lũ lượt chạy ra sân tập chơi."}]},{"hanzi":"其中","pinyin":"qízhōng","pos":"dt.","vn":"trong đó","examples":[{"cn":"我们班有二十个学生，其中一半是留学生。","pinyin":"Wǒmen bān yǒu èrshí ge xuésheng, qízhōng yíbàn shì liúxuéshēng.","vn":"Lớp chúng tôi có hai mươi học sinh, trong đó một nửa là du học sinh."},{"cn":"这本书介绍了很多种茶，其中我最喜欢龙井茶。","pinyin":"Zhè běn shū jièshào le hěn duō zhǒng chá, qízhōng wǒ zuì xǐhuan Lóngjǐngchá.","vn":"Cuốn sách này giới thiệu rất nhiều loại trà, trong đó tôi thích nhất là trà Long Tỉnh."},{"cn":"这次活动有很多人报名，他也是其中之一。","pinyin":"Zhè cì huódòng yǒu hěn duō rén bàomíng, tā yě shì qízhōng zhī yī.","vn":"Hoạt động lần này có rất nhiều người đăng ký, anh ấy cũng là một trong số đó."}]},{"hanzi":"之","pinyin":"zhī","pos":"trợ.","vn":"của (trợ từ dùng giữa định ngữ và trung tâm ngữ)","examples":[{"cn":"长城是中国最有名的旅游景点之一。","pinyin":"Chángchéng shì Zhōngguó zuì yǒumíng de lǚyóu jǐngdiǎn zhī yī.","vn":"Vạn Lý Trường Thành là một trong những điểm du lịch nổi tiếng nhất Trung Quốc."},{"cn":"他是我最信任的朋友之一。","pinyin":"Tā shì wǒ zuì xìnrèn de péngyou zhī yī.","vn":"Anh ấy là một trong những người bạn tôi tin tưởng nhất."},{"cn":"这次展览展出了三分之二的新作品。","pinyin":"Zhè cì zhǎnlǎn zhǎnchū le sānfēn zhī èr de xīn zuòpǐn.","vn":"Buổi triển lãm lần này đã trưng bày hai phần ba số tác phẩm mới."}]},{"hanzi":"火","pinyin":"huǒ","pos":"tt./dt.","vn":"nổi tiếng, thịnh hành; lửa","examples":[{"cn":"那家新开的火锅店最近在网上特别火。","pinyin":"Nà jiā xīn kāi de huǒguōdiàn zuìjìn zài wǎngshang tèbié huǒ.","vn":"Quán lẩu mới mở đó dạo gần đây đặc biệt nổi tiếng trên mạng."},{"cn":"这部电影上映后一下子就火了起来。","pinyin":"Zhè bù diànyǐng shàngyìng hòu yíxiàzi jiù huǒ le qǐlai.","vn":"Bộ phim này sau khi công chiếu lập tức trở nên vô cùng ăn khách."},{"cn":"做完饭别忘了把火关掉，注意安全。","pinyin":"Zuò wán fàn bié wàng le bǎ huǒ guāndiào, zhùyì ānquán.","vn":"Nấu cơm xong đừng quên tắt bếp lửa nhé, chú ý an toàn."}]},{"hanzi":"好处","pinyin":"hǎochù","pos":"dt.","vn":"lợi ích, điều tốt","examples":[{"cn":"每天坚持散步对身体健康有很多好处。","pinyin":"Měitiān jiānchí sànbù duì shēntǐ jiànkāng yǒu hěn duō hǎochù.","vn":"Mỗi ngày kiên trì đi bộ có rất nhiều lợi ích cho sức khỏe."},{"cn":"早睡早起的好处说也说不完。","pinyin":"Zǎoshuì zǎoqǐ de hǎochù shuō yě shuō bu wán.","vn":"Lợi ích của việc ngủ sớm dậy sớm nói mãi cũng không hết."},{"cn":"多读书对你以后的工作一定有好处。","pinyin":"Duō dúshū duì nǐ yǐhòu de gōngzuò yídìng yǒu hǎochù.","vn":"Đọc nhiều sách nhất định sẽ có ích cho công việc sau này của bạn."}]},{"hanzi":"设备","pinyin":"shèbèi","pos":"dt.","vn":"thiết bị","examples":[{"cn":"这家健身房的运动设备非常齐全。","pinyin":"Zhè jiā jiànshēnfáng de yùndòng shèbèi fēicháng qíquán.","vn":"Thiết bị tập luyện của phòng gym này vô cùng đầy đủ."},{"cn":"学校今年为实验室买了一批新设备。","pinyin":"Xuéxiào jīnnián wèi shíyànshì mǎi le yì pī xīn shèbèi.","vn":"Năm nay nhà trường đã mua một lô thiết bị mới cho phòng thí nghiệm."},{"cn":"使用这台设备之前，请先仔细看说明书。","pinyin":"Shǐyòng zhè tái shèbèi zhīqián, qǐng xiān zǐxì kàn shuōmíngshū.","vn":"Trước khi sử dụng thiết bị này, xin hãy đọc kỹ sách hướng dẫn."}]},{"hanzi":"全身","pinyin":"quánshēn","pos":"dt.","vn":"toàn thân","examples":[{"cn":"游泳是一项可以锻炼全身的运动。","pinyin":"Yóuyǒng shì yí xiàng kěyǐ duànliàn quánshēn de yùndòng.","vn":"Bơi lội là một môn thể thao có thể rèn luyện toàn thân."},{"cn":"昨天爬山爬得太累了，今天全身都疼。","pinyin":"Zuótiān páshān pá de tài lèi le, jīntiān quánshēn dōu téng.","vn":"Hôm qua leo núi mệt quá, hôm nay đau nhức khắp toàn thân."},{"cn":"他冒雨跑回家，全身都淋湿了。","pinyin":"Tā màoyǔ pǎo huíjiā, quánshēn dōu línshī le.","vn":"Anh ấy đội mưa chạy về nhà, toàn thân đều ướt sũng."}]},{"hanzi":"准确","pinyin":"zhǔnquè","pos":"tt.","vn":"chính xác","examples":[{"cn":"他的中文发音非常准确。","pinyin":"Tā de Zhōngwén fāyīn fēicháng zhǔnquè.","vn":"Phát âm tiếng Trung của anh ấy vô cùng chính xác."},{"cn":"请你再检查一下这些数字是否准确。","pinyin":"Qǐng nǐ zài jiǎnchá yíxià zhèxiē shùzì shìfǒu zhǔnquè.","vn":"Bạn hãy kiểm tra lại xem những con số này có chính xác không."},{"cn":"教练能帮我们把每个动作都做准确。","pinyin":"Jiàoliàn néng bāng wǒmen bǎ měi ge dòngzuò dōu zuò zhǔnquè.","vn":"Huấn luyện viên có thể giúp chúng tôi thực hiện chính xác từng động tác."}]},{"hanzi":"仅仅","pinyin":"jǐnjǐn","pos":"phó.","vn":"chỉ, vẻn vẹn","examples":[{"cn":"我仅仅学了半年中文，还说得不够流利。","pinyin":"Wǒ jǐnjǐn xué le bàn nián Zhōngwén, hái shuō de búgòu liúlì.","vn":"Tôi chỉ mới học tiếng Trung nửa năm nên nói vẫn chưa đủ lưu loát."},{"cn":"完成这项任务仅仅花了两天时间。","pinyin":"Wánchéng zhè xiàng rènwu jǐnjǐn huā le liǎng tiān shíjiān.","vn":"Hoàn thành nhiệm vụ này vẻn vẹn chỉ mất hai ngày."},{"cn":"学好一门语言不能仅仅依靠背单词。","pinyin":"Xuéhǎo yì mén yǔyán bù néng jǐnjǐn yīkào bèi dāncí.","vn":"Học tốt một ngôn ngữ không thể chỉ dựa vào việc học thuộc từ vựng."}]},{"hanzi":"表扬","pinyin":"biǎoyáng","pos":"dgt.","vn":"khen ngợi, biểu dương","examples":[{"cn":"老师在班会上表扬了他乐于助人的精神。","pinyin":"Lǎoshī zài bānhuì shang biǎoyáng le tā lèyú zhùrén de jīngshén.","vn":"Cô giáo đã biểu dương tinh thần sẵn lòng giúp đỡ mọi người của cậu ấy trong buổi họp lớp."},{"cn":"妈妈表扬我今天把房间收拾得很干净。","pinyin":"Māma biǎoyáng wǒ jīntiān bǎ fángjiān shōushi de hěn gānjìng.","vn":"Mẹ khen tôi hôm nay dọn dẹp phòng rất sạch sẽ."},{"cn":"得到经理的表扬后，她工作得更有干劲了。","pinyin":"Dédào jīnglǐ de biǎoyáng hòu, tā gōngzuò de gèng yǒu gànjìn le.","vn":"Sau khi được giám đốc khen ngợi, cô ấy làm việc càng hăng hái hơn."}]},{"hanzi":"进步","pinyin":"jìnbù","pos":"dgt./tt.","vn":"tiến bộ","examples":[{"cn":"经过一个学期的努力，她的口语进步很大。","pinyin":"Jīngguò yí ge xuéqī de nǔlì, tā de kǒuyǔ jìnbù hěn dà.","vn":"Sau một học kỳ nỗ lực, khả năng nói của cô ấy tiến bộ rất nhiều."},{"cn":"只要每天坚持练习，你一定会不断进步。","pinyin":"Zhǐyào měitiān jiānchí liànxí, nǐ yídìng huì búduàn jìnbù.","vn":"Chỉ cần mỗi ngày kiên trì luyện tập, bạn chắc chắn sẽ không ngừng tiến bộ."},{"cn":"科技的进步给人们带来了许多方便。","pinyin":"Kējì de jìnbù gěi rénmen dàilái le xǔduō fāngbiàn.","vn":"Sự tiến bộ của khoa học kỹ thuật đã mang lại cho con người rất nhiều tiện ích."}]},{"hanzi":"鼓励","pinyin":"gǔlì","pos":"dgt.","vn":"khích lệ, động viên","examples":[{"cn":"每当我遇到困难时，父母总是鼓励我不要放弃。","pinyin":"Měidāng wǒ yùdào kùnnan shí, fùmǔ zǒngshì gǔlì wǒ búyào fàngqì.","vn":"Mỗi khi tôi gặp khó khăn, bố mẹ luôn động viên tôi đừng bỏ cuộc."},{"cn":"老师的话给了我很大的鼓励。","pinyin":"Lǎoshī de huà gěi le wǒ hěn dà de gǔlì.","vn":"Lời nói của thầy giáo đã cho tôi nguồn khích lệ rất lớn."},{"cn":"我们应该多鼓励孩子大胆表达自己的想法。","pinyin":"Wǒmen yīnggāi duō gǔlì háizi dàdǎn biǎodá zìjǐ de xiǎngfǎ.","vn":"Chúng ta nên khích lệ trẻ em mạnh dạn bày tỏ suy nghĩ của mình nhiều hơn."}]},{"hanzi":"帅","pinyin":"shuài","pos":"tt.","vn":"đẹp trai, bảnh bao","examples":[{"cn":"他穿上这身西装看起来特别帅。","pinyin":"Tā chuānshang zhè shēn xīzhuāng kàn qǐlai tèbié shuài.","vn":"Anh ấy mặc bộ vest này vào trông đặc biệt bảnh bao."},{"cn":"那个正在打篮球的男生又高又帅。","pinyin":"Nàge zhèngzài dǎ lánqiú de nánshēng yòu gāo yòu shuài.","vn":"Cậu con trai đang chơi bóng rổ kia vừa cao vừa đẹp trai."},{"cn":"换了一个新发型，你显得更帅了。","pinyin":"Huàn le yí ge xīn fàxíng, nǐ xiǎnde gèng shuài le.","vn":"Đổi kiểu tóc mới trông bạn càng đẹp trai hơn rồi."}]},{"hanzi":"乒乓球","pinyin":"pīngpāngqiú","pos":"dt.","vn":"bóng bàn","examples":[{"cn":"乒乓球是中国的国球，很多人都会打。","pinyin":"Pīngpāngqiú shì Zhōngguó de guóqiú, hěn duō rén dōu huì dǎ.","vn":"Bóng bàn là quốc cầu của Trung Quốc, rất nhiều người đều biết chơi."},{"cn":"周末我们一起去体育馆打乒乓球吧。","pinyin":"Zhōumò wǒmen yìqǐ qù tǐyùguǎn dǎ pīngpāngqiú ba.","vn":"Cuối tuần chúng ta cùng đến nhà thi đấu đánh bóng bàn nhé."},{"cn":"爷爷虽然七十岁了，但乒乓球打得非常好。","pinyin":"Yéye suīrán qīshí suì le, dàn pīngpāngqiú dǎ de fēicháng hǎo.","vn":"Ông nội tuy đã bảy mươi tuổi rồi nhưng đánh bóng bàn rất giỏi."}]},{"hanzi":"队","pinyin":"duì","pos":"dt.","vn":"đội","examples":[{"cn":"他今年成功进入了学校的足球队。","pinyin":"Tā jīnnián chénggōng jìnrù le xuéxiào de zúqiúduì.","vn":"Năm nay cậu ấy đã gia nhập thành công đội bóng đá của trường."},{"cn":"今天买票的人很多，门口排了很长的队。","pinyin":"Jīntiān mǎipiào de rén hěn duō, ménkǒu pái le hěn cháng de duì.","vn":"Hôm nay người mua vé rất đông, ngoài cửa xếp một hàng rất dài."},{"cn":"我们队在这次比赛中获得了冠军。","pinyin":"Wǒmen duì zài zhè cì bǐsài zhōng huòdé le guànjūn.","vn":"Đội chúng tôi đã giành chức vô địch trong cuộc thi lần này."}]},{"hanzi":"项","pinyin":"xiàng","pos":"lượng.","vn":"hạng mục, môn (lượng từ)","examples":[{"cn":"跑步是一项既简单又有效的运动。","pinyin":"Pǎobù shì yí xiàng jì jiǎndān yòu yǒuxiào de yùndòng.","vn":"Chạy bộ là một môn thể thao vừa đơn giản vừa hiệu quả."},{"cn":"公司决定把这项重要工作交给他负责。","pinyin":"Gōngsī juédìng bǎ zhè xiàng zhòngyào gōngzuò jiāogěi tā fùzé.","vn":"Công ty quyết định giao công việc quan trọng này cho anh ấy phụ trách."},{"cn":"这次运动会一共有十多项比赛。","pinyin":"Zhè cì yùndònghuì yígòng yǒu shí duō xiàng bǐsài.","vn":"Đại hội thể thao lần này có tổng cộng hơn mười hạng mục thi đấu."}]},{"hanzi":"赢得","pinyin":"yíngdé","pos":"dgt.","vn":"giành được, thắng được","examples":[{"cn":"他们齐心协力，终于赢得了这场比赛。","pinyin":"Tāmen qíxīn xiélì, zhōngyú yíngdé le zhè chǎng bǐsài.","vn":"Họ đồng tâm hiệp lực, cuối cùng đã giành chiến thắng trong trận đấu này."},{"cn":"她真诚的态度赢得了大家的信任。","pinyin":"Tā zhēnchéng de tàidù yíngdé le dàjiā de xìnrèn.","vn":"Thái độ chân thành của cô ấy đã giành được sự tin tưởng của mọi người."},{"cn":"这位歌手凭借精彩的表演赢得了热烈掌声。","pinyin":"Zhè wèi gēshǒu píngjiè jīngcǎi de biǎoyǎn yíngdé le rèliè zhǎngshēng.","vn":"Ca sĩ này nhờ màn trình diễn xuất sắc đã giành được tràng pháo tay nồng nhiệt."}]},{"hanzi":"叫作","pinyin":"jiàozuò","pos":"dgt.","vn":"được gọi là","examples":[{"cn":"这座美丽的海滨城市被叫作“东方夏威夷”。","pinyin":"Zhè zuò měilì de hǎibīn chéngshì bèi jiàozuò \"Dōngfāng Xiàwēiyí\".","vn":"Thành phố ven biển xinh đẹp này được gọi là \"Hawaii phương Đông\"."},{"cn":"那种长在山上的植物叫作什么？","pinyin":"Nà zhǒng zhǎng zài shānshang de zhíwù jiàozuò shénme?","vn":"Loài thực vật mọc trên núi đó gọi là gì vậy?"},{"cn":"中国乒乓球队常被大家叫作“梦之队”。","pinyin":"Zhōngguó pīngpāngqiúduì cháng bèi dàjiā jiàozuò \"Mèngzhīduì\".","vn":"Đội tuyển bóng bàn Trung Quốc thường được mọi người gọi là \"Đội tuyển trong mơ\"."}]},{"hanzi":"梦","pinyin":"mèng","pos":"dt./dgt.","vn":"giấc mơ; nằm mơ","examples":[{"cn":"昨天晚上我做了一个很奇怪的梦。","pinyin":"Zuótiān wǎnshang wǒ zuò le yí ge hěn qíguài de mèng.","vn":"Tối hôm qua tôi đã nằm mơ một giấc mơ rất kỳ lạ."},{"cn":"祝你做个好梦，晚安！","pinyin":"Zhù nǐ zuò ge hǎomèng, wǎn'ān!","vn":"Chúc bạn ngủ ngon và có giấc mơ đẹp!"},{"cn":"我昨晚梦见自己回到了小时候住的村庄。","pinyin":"Wǒ zuówǎn mèngjiàn zìjǐ huídào le xiǎoshíhou zhù de cūnzhuāng.","vn":"Tối qua tôi mơ thấy mình quay về ngôi làng sống hồi nhỏ."}]},{"hanzi":"不断","pinyin":"búduàn","pos":"phó./dgt.","vn":"không ngừng, liên tục","examples":[{"cn":"我们只有不断学习，才能跟上时代的发展。","pinyin":"Wǒmen zhǐyǒu búduàn xuéxí, cái néng gēnshàng shídài de fāzhǎn.","vn":"Chúng ta chỉ có không ngừng học tập mới có thể theo kịp sự phát triển của thời đại."},{"cn":"近年来，这座城市的交通条件在不断改善。","pinyin":"Jìnnián lái, zhè zuò chéngshì de jiāotōng tiáojiàn zài búduàn gǎishàn.","vn":"Những năm gần đây, điều kiện giao thông của thành phố này đang không ngừng được cải thiện."},{"cn":"窗外雨声不断，看来今天没法出门了。","pinyin":"Chuāngwài yǔshēng búduàn, kànlái jīntiān méifǎ chūmén le.","vn":"Ngoài cửa sổ tiếng mưa rơi không ngớt, xem ra hôm nay không thể ra ngoài được rồi."}]},{"hanzi":"队员","pinyin":"duìyuán","pos":"dt.","vn":"đội viên, thành viên đội","examples":[{"cn":"为了迎接比赛，所有队员都在刻苦训练。","pinyin":"Wèile yíngjiē bǐsài, suǒyǒu duìyuán dōu zài kèkǔ xùnliàn.","vn":"Để đón chờ cuộc thi, tất cả các đội viên đều đang chăm chỉ tập luyện."},{"cn":"队员之间的互相配合非常重要。","pinyin":"Duìyuán zhījiān de hùxiāng pèihé fēicháng zhòngyào.","vn":"Sự phối hợp lẫn nhau giữa các thành viên trong đội vô cùng quan trọng."},{"cn":"这位年轻的队员在决赛中表现得非常出色。","pinyin":"Zhè wèi niánqīng de duìyuán zài juésài zhōng biǎoxiàn de fēicháng chūsè.","vn":"Vị đội viên trẻ tuổi này đã thể hiện vô cùng xuất sắc trong trận chung kết."}]},{"hanzi":"训练","pinyin":"xùnliàn","pos":"dgt.","vn":"huấn luyện, tập luyện","examples":[{"cn":"运动员们每天都要进行高强度的训练。","pinyin":"Yùndòngyuánmen měitiān dōu yào jìnxíng gāoqiángdù de xùnliàn.","vn":"Các vận động viên mỗi ngày đều phải tập luyện cường độ cao."},{"cn":"他正在训练自己的小狗学会握手。","pinyin":"Tā zhèngzài xùnliàn zìjǐ de xiǎogǒu xuéhuì wòshǒu.","vn":"Anh ấy đang huấn luyện chú chó nhỏ của mình học cách bắt tay."},{"cn":"经过三个月的听力训练，我的汉语听力提高了很多。","pinyin":"Jīngguò sān ge yuè de tīnglì xùnliàn, wǒ de Hànyǔ tīnglì tígāo le hěn duō.","vn":"Sau ba tháng luyện nghe, kỹ năng nghe tiếng Hán của tôi đã tiến bộ rất nhiều."}]},{"hanzi":"球队","pinyin":"qiúduì","pos":"dt.","vn":"đội bóng","examples":[{"cn":"你最喜欢哪支足球球队？","pinyin":"Nǐ zuì xǐhuan nǎ zhī zúqiú qiúduì?","vn":"Bạn thích nhất đội bóng đá nào?"},{"cn":"这支球队今年请来了一位经验丰富的新教练。","pinyin":"Zhè zhī qiúduì jīnnián qǐnglái le yí wèi jīngyàn fēngfù de xīn jiàoliàn.","vn":"Đội bóng này năm nay đã mời về một huấn luyện viên mới giàu kinh nghiệm."},{"cn":"球队赢下关键比赛后，全场观众都欢呼起来。","pinyin":"Qiúduì yíngxià guānjiàn bǐsài hòu, quánchǎng guānzhòng dōu huānhū qǐlai.","vn":"Sau khi đội bóng thắng trận đấu then chốt, khán giả cả sân đều reo hò."}]},{"hanzi":"球迷","pinyin":"qiúmí","pos":"dt.","vn":"người hâm mộ bóng","examples":[{"cn":"我爸爸是个忠实的足球球迷，每场大赛都不错过。","pinyin":"Wǒ bàba shì ge zhōngshí de zúqiú qiúmí, měi chǎng dàsài dōu bú cuòguò.","vn":"Bố tôi là một người hâm mộ bóng đá trung thành, trận đấu lớn nào cũng không bỏ lỡ."},{"cn":"比赛结束后，很多球迷留下来找运动员签名。","pinyin":"Bǐsài jiéshù hòu, hěn duō qiúmí liú xiàlái zhǎo yùndòngyuán qiānmíng.","vn":"Sau khi trận đấu kết thúc, rất nhiều người hâm mộ ở lại xin chữ ký vận động viên."},{"cn":"热情的球迷们一直在看台上为球队加油。","pinyin":"Rèqíng de qiúmímen yìzhí zài kàntái shang wèi qiúduì jiāyóu.","vn":"Những người hâm mộ nhiệt tình luôn cổ vũ cho đội bóng trên khán đài."}]},{"hanzi":"梦想","pinyin":"mèngxiǎng","pos":"dt./dgt.","vn":"ước mơ, giấc mơ; mơ ước","examples":[{"cn":"他从小就有一个当医生的梦想。","pinyin":"Tā cóngxiǎo jiù yǒu yí ge dāng yīshēng de mèngxiǎng.","vn":"Từ nhỏ cậu ấy đã có ước mơ làm bác sĩ."},{"cn":"只要勇敢坚持，梦想总有一天会实现的。","pinyin":"Zhǐyào yǒnggǎn jiānchí, mèngxiǎng zǒng yǒu yì tiān huì shíxiàn de.","vn":"Chỉ cần dũng cảm kiên trì, ước mơ nhất định sẽ có ngày thành hiện thực."},{"cn":"她一直梦想着能去世界各地旅行。","pinyin":"Tā yìzhí mèngxiǎng zhe néng qù shìjiè gèdì lǚxíng.","vn":"Cô ấy luôn mơ ước có thể đi du lịch khắp nơi trên thế giới."}]},{"hanzi":"大赛","pinyin":"dàsài","pos":"dt.","vn":"giải đấu lớn","examples":[{"cn":"她今年将代表学校参加全国演讲大赛。","pinyin":"Tā jīnnián jiāng dàibiǎo xuéxiào cānjiā quánguó yǎnjiǎng dàsài.","vn":"Năm nay cô ấy sẽ đại diện nhà trường tham gia cuộc thi hùng biện toàn quốc."},{"cn":"参加世界大赛对年轻运动员来说是宝贵的经验。","pinyin":"Cānjiā shìjiè dàsài duì niánqīng yùndòngyuán láishuō shì bǎoguì de jīngyàn.","vn":"Tham gia các giải đấu thế giới là kinh nghiệm quý báu đối với các vận động viên trẻ."},{"cn":"这次摄影大赛收到了来自全球的数千幅作品。","pinyin":"Zhè cì shèyǐng dàsài shōudào le láizì quánqiú de shùqiān fú zuòpǐn.","vn":"Cuộc thi nhiếp ảnh lớn lần này đã nhận được hàng nghìn tác phẩm từ khắp toàn cầu."}]},{"hanzi":"赢","pinyin":"yíng","pos":"dgt.","vn":"thắng","examples":[{"cn":"昨天的羽毛球比赛，我们以二比一赢了对手。","pinyin":"Zuótiān de yǔmáoqiú bǐsài, wǒmen yǐ èr bǐ yī yíng le duìshǒu.","vn":"Trận cầu lông hôm qua, chúng tôi đã thắng đối thủ với tỷ số 2-1."},{"cn":"比赛最重要的是享受过程，不一定非要赢。","pinyin":"Bǐsài zuì zhòngyào de shì xiǎngshòu guòchéng, bùyídìng fēi yào yíng.","vn":"Điều quan trọng nhất trong thi đấu là tận hưởng quá trình, không nhất thiết cứ phải thắng."},{"cn":"他下棋非常厉害，我从来没赢过他。","pinyin":"Tā xiàqí fēicháng lìhai, wǒ cónglái méi yíng guo tā.","vn":"Anh ấy chơi cờ rất giỏi, tôi chưa từng thắng anh ấy bao giờ."}]},{"hanzi":"连","pinyin":"lián","pos":"giới.","vn":"ngay cả, đến cả","examples":[{"cn":"他最近忙得连午饭都顾不上吃。","pinyin":"Tā zuìjìn máng de lián wǔfàn dōu gùbushàng chī.","vn":"Dạo gần đây anh ấy bận đến nỗi ngay cả bữa trưa cũng không kịp ăn."},{"cn":"这道题太难了，连班里最聪明的同学也不会做。","pinyin":"Zhè dào tí tài nán le, lián bān lǐ zuì cōngming de tóngxué yě bú huì zuò.","vn":"Bài toán này khó quá, đến cả bạn học thông minh nhất lớp cũng không làm được."},{"cn":"我连他的名字都没听说过。","pinyin":"Wǒ lián tā de míngzi dōu méi tīngshuō guo.","vn":"Tôi đến tên anh ta còn chưa từng nghe qua."}]}],"grammar":[{"title":"固定格式\"你×你的吧\"","explanation_vn":"Cấu trúc cố định \"你×你的吧\" biểu thị mỗi người tự làm việc của mình, không cần cùng nhau làm một việc nào đó, thường dùng để từ chối một cách lịch sự.","examples":[{"cn":"您走您的吧，我一会儿还要去一趟健身房。","pinyin":"Nín zǒu nín de ba, wǒ yíhuìr hái yào qù yí tàng jiànshēnfáng.","vn":"Chị cứ về trước đi ạ, lát nữa em còn phải qua phòng tập thể hình một chuyến."},{"cn":"你忙你的吧，我自己就能完成。","pinyin":"Nǐ máng nǐ de ba, wǒ zìjǐ jiù néng wánchéng.","vn":"Cậu cứ làm việc của cậu đi, mình tự làm xong được."},{"cn":"你们玩你们的吧，我今天想在家休息。","pinyin":"Nǐmen wán nǐmen de ba, wǒ jīntiān xiǎng zài jiā xiūxi.","vn":"Các cậu cứ đi chơi đi, hôm nay mình muốn ở nhà nghỉ ngơi."}]},{"title":"固定短语\"一A一B\"","explanation_vn":"Cụm từ cố định \"一A一B\" biểu thị sự đối xứng hoặc hai phương diện của một tình huống, trong đó A và B là các từ đơn âm tiết (một chữ).","examples":[{"cn":"一来一回得半个小时，太浪费时间了。","pinyin":"Yì lái yì huí děi bàn ge xiǎoshí, tài làngfèi shíjiān le.","vn":"Cả đi cả về mất nửa tiếng đồng hồ, lãng phí thời gian quá."},{"cn":"她说话的声音不大，但是一字一句说得很清楚。","pinyin":"Tā shuōhuà de shēngyīn bú dà, dànshì yí zì yí jù shuō de hěn qīngchu.","vn":"Giọng nói của cô ấy không lớn, nhưng từng chữ từng câu nói rất rõ ràng."},{"cn":"记者和运动员一问一答，谈到了很多比赛中的事情。","pinyin":"Jìzhě hé yùndòngyuán yí wèn yì dá, tándào le hěn duō bǐsài zhōng de shìqing.","vn":"Phóng viên và vận động viên kẻ hỏi người đáp, đã trò chuyện về rất nhiều chuyện trong trận đấu."}]},{"title":"兼语句\"主语+表扬/批评+宾语1+动词+宾语2\"","explanation_vn":"Câu kiêm ngữ \"主语+表扬/批评+宾语1+动词+宾语2\" (Chủ ngữ + 表扬/批评 + Tân ngữ 1 + Động từ + Tân ngữ 2) biểu thị sự đánh giá đối với việc mà một người nào đó đã làm.","examples":[{"cn":"教练也表扬他取得了很大的进步。","pinyin":"Jiàoliàn yě biǎoyáng tā qǔdé le hěn dà de jìnbù.","vn":"Huấn luyện viên cũng khen ngợi anh ấy đã đạt được tiến bộ rất lớn."},{"cn":"老师表扬白家月坚持每天学习中文。","pinyin":"Lǎoshī biǎoyáng Bái Jiāyuè jiānchí měitiān xuéxí Zhōngwén.","vn":"Thầy giáo khen ngợi Bạch Gia Nguyệt kiên trì học tiếng Trung mỗi ngày."},{"cn":"经理批评他没有按时完成工作。","pinyin":"Jīnglǐ pīpíng tā méiyǒu ànshí wánchéng gōngzuò.","vn":"Giám đốc phê bình anh ấy không hoàn thành công việc đúng hạn."}]},{"title":"递进复句\"连……也/都……，……更……\"","explanation_vn":"Câu phức tăng tiến \"连……也/都……，……更……\" biểu thị việc giải thích một tình huống thông qua cách nhấn mạnh một ví dụ cực đoan.","examples":[{"cn":"连一些年龄比较大的老人都坚持打球，年轻人更是把它作为一种日常锻炼的方式。","pinyin":"Lián yìxiē niánlíng bǐjiào dà de lǎorén dōu jiānchí dǎqiú, niánqīng rén gèng shì bǎ tā zuòwéi yì zhǒng rìcháng duànliàn de fāngshì.","vn":"Ngay cả một số cụ già lớn tuổi cũng kiên trì đánh bóng, giới trẻ lại càng coi đó là một cách rèn luyện sức khỏe hằng ngày."},{"cn":"我有时候连老师说的话也听不懂，听广播就更难了。","pinyin":"Wǒ yǒu shíhou lián lǎoshī shuō de huà yě tīng bu dǒng, tīng guǎngbō jiù gèng nán le.","vn":"Tôi đôi khi đến lời thầy giáo nói cũng không nghe hiểu, nghe đài phát thanh thì càng khó hơn."},{"cn":"今天早上他连脸都没来得及洗，更没有时间准备早饭了。","pinyin":"Jīntiān zǎoshang tā lián liǎn dōu méi láidejí xǐ, gèng méiyǒu shíjiān zhǔnbèi zǎofàn le.","vn":"Sáng nay anh ấy đến mặt cũng chưa kịp rửa, càng không có thời gian chuẩn bị bữa sáng."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"下班了！同乐，我今天正好要路过你们家那边，用不用我开车送你？","pinyin":"Xiàbān le! Tónglè, wǒ jīntiān zhènghǎo yào lùguò nǐmen jiā nàbiān, yòng bu yòng wǒ kāichē sòng nǐ?"},{"speaker":"杨同乐","cn":"谢谢一雪姐，不过您走您的吧，我一会儿还要去一趟健身房。","pinyin":"Xièxie Yīxuě jiě, búguò nín zǒu nín de ba, wǒ yíhuìr hái yào qù yí tàng jiànshēnfáng."},{"speaker":"王一雪","cn":"去健身房？你什么时候开始健身的？","pinyin":"Qù jiànshēnfáng? Nǐ shénme shíhou kāishǐ jiànshēn de?"},{"speaker":"杨同乐","cn":"我上个星期发现单位旁边新开了一家健身房。我最近体重增加了不少，正好想运动一下，就进去看了看。","pinyin":"Wǒ shàng ge xīngqī fāxiàn dānwèi pángbiān xīn kāi le yì jiā jiànshēnfáng. Wǒ zuìjìn tǐzhòng zēngjiā le bùshǎo, zhènghǎo xiǎng yùndòng yíxià, jiù jìnqù kàn le kàn."},{"speaker":"王一雪","cn":"感觉怎么样？","pinyin":"Gǎnjué zěnmeyàng?"},{"speaker":"杨同乐","cn":"挺不错的。当时正好有打折活动，我就办了一张会员卡。","pinyin":"Tǐng búcuò de. Dāngshí zhènghǎo yǒu dǎzhé huódòng, wǒ jiù bàn le yì zhāng huìyuánkǎ."}],"translation_vn":"Vương Nhất Tuyết: Tan làm rồi! Đồng Lạc, hôm nay chị vừa hay đi ngang qua phía nhà em, có cần chị lái xe đưa em về không?\nDương Đồng Lạc: Cảm ơn chị Nhất Tuyết, nhưng chị cứ về trước đi ạ, lát nữa em còn phải qua phòng tập thể hình một chuyến.\nVương Nhất Tuyết: Đến phòng gym à? Em bắt đầu tập thể hình từ bao giờ thế?\nDương Đồng Lạc: Tuần trước em phát hiện bên cạnh cơ quan mới mở một phòng gym. Gần đây cân nặng của em tăng lên không ít, vừa hay muốn vận động một chút nên em đã vào xem thử.\nVương Nhất Tuyết: Thấy thế nào?\nDương Đồng Lạc: Khá ổn chị ạ. Lúc đó vừa đúng có chương trình giảm giá nên em đã làm một thẻ hội viên luôn.","audio_dialogue":"17-1.mp3","audio_vocab":"17-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"王一雪","cn":"同乐，你晚上不吃饭就去健身，不会饿吗？","pinyin":"Tónglè, nǐ wǎnshang bù chīfàn jiù qù jiànshēn, bú huì è ma?"},{"speaker":"杨同乐","cn":"我带了饼干、酸奶和果汁，一会儿吃完了再去。","pinyin":"Wǒ dài le bǐnggān, suānnǎi hé guǒzhī, yíhuìr chīwán le zài qù."},{"speaker":"王一雪","cn":"那你为什么不在家附近找健身房？吃完晚饭，休息一下再去，不是更好吗？","pinyin":"Nà nǐ wèishénme bú zài jiā fùjìn zhǎo jiànshēnfáng? Chīwán wǎnfàn, xiūxi yíxià zài qù, bú shì gèng hǎo ma?"},{"speaker":"杨同乐","cn":"离我家最近的健身房也要坐两站公交车，一来一回得半个小时，太浪费时间了。","pinyin":"Lí wǒ jiā zuì jìn de jiànshēnfáng yě yào zuò liǎng zhàn gōngjiāochē, yì lái yì huí děi bàn ge xiǎoshí, tài làngfèi shíjiān le."},{"speaker":"王一雪","cn":"确实。那这家健身房的教练怎么样？","pinyin":"Quèshí. Nà zhè jiā jiànshēnfáng de jiàoliàn zěnmeyàng?"},{"speaker":"杨同乐","cn":"教练很热情，也非常专业，动作讲得很清楚。","pinyin":"Jiàoliàn hěn rèqíng, yě fēicháng zhuānyè, dòngzuò jiǎng de hěn qīngchu."},{"speaker":"王一雪","cn":"听你这么一说，我也想试试了。我现在都是在家看着视频练，动作不一定标准。","pinyin":"Tīng nǐ zhème yì shuō, wǒ yě xiǎng shìshi le. Wǒ xiànzài dōu shì zài jiā kànzhe shìpín liàn, dòngzuò bù yídìng biāozhǔn."},{"speaker":"杨同乐","cn":"好啊，那您也来吧。锻炼要科学，否则容易受伤。","pinyin":"Hǎo a, nà nín yě lái ba. Duànliàn yào kēxué, fǒuzé róngyì shòushāng."}],"translation_vn":"Vương Nhất Tuyết: Đồng Lạc, buổi tối em không ăn cơm mà đi tập gym ngay, không sợ đói à?\nDương Đồng Lạc: Em có mang theo bánh quy, sữa chua và nước ép trái cây, lát nữa ăn xong rồi mới đi.\nVương Nhất Tuyết: Vậy sao em không tìm phòng gym ở gần nhà? Ăn cơm tối xong, nghỉ ngơi một chút rồi đi chẳng phải tốt hơn sao?\nDương Đồng Lạc: Phòng gym gần nhà em nhất cũng phải đi hai bến xe buýt, cả đi cả về mất nửa tiếng đồng hồ, lãng phí thời gian quá ạ.\nVương Nhất Tuyết: Đúng thật. Thế huấn luyện viên ở phòng gym này thế nào?\nDương Đồng Lạc: Huấn luyện viên rất nhiệt tình, cũng vô cùng chuyên nghiệp, giảng giải động tác rất rõ ràng.\nVương Nhất Tuyết: Nghe em nói vậy, chị cũng muốn thử rồi đấy. Hiện tại chị toàn ở nhà xem video tập theo, động tác chưa chắc đã chuẩn.\nDương Đồng Lạc: Vâng ạ, vậy chị cũng đến tập đi. Rèn luyện sức khỏe phải khoa học, nếu không sẽ dễ bị chấn thương lắm.","audio_dialogue":"17-3.mp3","audio_vocab":"17-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"有人爱在操场跑步，有人喜欢通过打球锻炼身体，还有一部分人愿意去健身房健身，杨同乐就是其中之一。","pinyin":"Yǒurén ài zài cāochǎng pǎobù, yǒurén xǐhuan tōngguò dǎqiú duànliàn shēntǐ, hái yǒu yí bùfen rén yuànyì qù jiànshēnfáng jiànshēn, Yáng Tónglè jiù shì qízhōng zhī yī."},{"speaker":"","cn":"杨同乐认为健身房火起来是因为它有很多好处——环境好、设备全，可以锻炼全身。另外，健身房里一般还有专业教练，能帮助大家把动作做准确，练习的效果也更好。","pinyin":"Yáng Tónglè rènwéi jiànshēnfáng huǒ qǐlái shì yīnwèi tā yǒu hěn duō hǎochù — huánjìng hǎo, shèbèi quán, kěyǐ duànliàn quánshēn. Lìngwài, jiànshēnfáng lǐ yìbān hái yǒu zhuānyè jiàoliàn, néng bāngzhù dàjiā bǎ dòngzuò zuò zhǔnquè, liànxí de xiàoguǒ yě gèng hǎo."},{"speaker":"","cn":"仅仅经过一个月左右的锻炼，杨同乐就感觉自己的身体比以前更健康了。教练也表扬他取得了很大的进步，并鼓励他坚持下去，还说随着身体越来越好，人看起来也会更帅。","pinyin":"Jǐnjǐn jīngguò yí ge yuè zuǒyòu de duànliàn, Yáng Tónglè jiù gǎnjué zìjǐ de shēntǐ bǐ yǐqián gèng jiànkāng le. Jiàoliàn yě biǎoyáng tā qǔdé le hěn dà de jìnbù, bìng gǔlì tā jiānchí xiàqù, hái shuō suízhe shēntǐ yuèláiyuè hǎo, rén kàn qǐlái yě huì gèng shuài."}],"translation_vn":"Có người thích chạy bộ trên sân vận động, có người thích rèn luyện thân thể thông qua chơi bóng, cũng có một bộ phận mọi người thích đến phòng tập thể hình để tập gym, Dương Đồng Lạc chính là một trong số đó.\nDương Đồng Lạc cho rằng phòng gym trở nên thịnh hành là vì nó có rất nhiều lợi ích — môi trường tốt, thiết bị đầy đủ, có thể rèn luyện toàn thân. Ngoài ra, trong phòng gym thường còn có huấn luyện viên chuyên nghiệp, có thể giúp mọi người thực hiện động tác thật chính xác, hiệu quả tập luyện cũng tốt hơn.\nVẻn vẹn chỉ qua khoảng một tháng rèn luyện, Dương Đồng Lạc đã cảm thấy cơ thể mình khỏe mạnh hơn trước rất nhiều. Huấn luyện viên cũng khen ngợi cậu ấy đã đạt được tiến bộ rất lớn và động viên cậu kiên trì tiếp tục, còn nói rằng cùng với cơ thể ngày càng khỏe đẹp hơn, trông cậu cũng sẽ đẹp trai hơn nữa.","audio_dialogue":"17-5.mp3","audio_vocab":"17-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"中国乒乓球队非常有名，常在各项比赛中赢得第一名，被叫作“梦之队”。为了不断提高自己的水平，队员们每天都要进行严格的训练。正因为这样，球队才能在比赛中取得更好的成绩，获得更多球迷的喜爱。许多年轻的乒乓球运动员都有一个梦想，那就是进入国家队，参加世界大赛，为球队赢下比赛。","pinyin":"Zhōngguó pīngpāngqiúduì fēicháng yǒumíng, cháng zài gè xiàng bǐsài zhōng yíngdé dì yī míng, bèi jiàozuò “mèng zhī duì”. Wèile búduàn tígāo zìjǐ de shuǐpíng, duìyuánmen měitiān dōu yào jìnxíng yángé de xùnliàn. Zhèng yīnwèi zhèyàng, qiúduì cái néng zài bǐsài zhōng qǔdé gèng hǎo de chéngjì, huòdé gèng duō qiúmí de xǐ'ài. Xǔduō niánqīng de pīngpāngqiú yùndòngyuán dōu yǒu yí ge mèngxiǎng, nà jiù shì jìnrù guójiāduì, cānjiā shìjiè dàsài, wèi qiúduì yíngxià bǐsài."},{"speaker":"","cn":"在中国，除了专业运动员，喜欢打乒乓球的普通人也特别多。连一些年龄比较大的老人都坚持打球，年轻人更是把它作为一种日常锻炼的方式。可以说，乒乓球是中国人生活中最常见的运动之一。","pinyin":"Zài Zhōngguó, chúle zhuānyè yùndòngyuán, xǐhuan dǎ pīngpāngqiú de pǔtōngrén yě tèbié duō. Lián yìxiē niánlíng bǐjiào dà de lǎorén dōu jiānchí dǎqiú, niánqīng rén gèng shì bǎ tā zuòwéi yì zhǒng rìcháng duànliàn de fāngshì. Kěyǐ shuō, pīngpāngqiú shì Zhōngguórén shēnghuó zhōng zuì chángjiàn de yùndòng zhī yī."}],"translation_vn":"Đội tuyển bóng bàn Trung Quốc vô cùng nổi tiếng, thường xuyên giành giải nhất trong các giải đấu lớn nhỏ, được mệnh danh là \"Đội tuyển trong mơ\". Để không ngừng nâng cao trình độ của bản thân, các đội viên mỗi ngày đều phải tiến hành huấn luyện nghiêm ngặt. Chính vì vậy, đội tuyển mới có thể giành được những thành tích tốt hơn trong các trận đấu và nhận được sự yêu mến của ngày càng nhiều người hâm mộ. Rất nhiều vận động viên bóng bàn trẻ tuổi đều có một ước mơ, đó là được vào đội tuyển quốc gia, tham gia các giải đấu lớn tầm cỡ thế giới và giành chiến thắng cho đội tuyển.\nỞ Trung Quốc, ngoài các vận động viên chuyên nghiệp, người bình thường thích chơi bóng bàn cũng đặc biệt đông đảo. Ngay cả một số cụ già lớn tuổi cũng kiên trì đánh bóng, giới trẻ lại càng coi đó là một cách rèn luyện sức khỏe hằng ngày. Có thể nói, bóng bàn là một trong những môn thể thao phổ biến nhất trong đời sống của người Trung Quốc.","audio_dialogue":"17-7.mp3","audio_vocab":"17-8.mp3"}]},{"id":18,"title_cn":"科技改变生活","title_pinyin":"Kējì gǎibiàn shēnghuó","title_vn":"Công nghệ thay đổi cuộc sống","goals":["Có thể nghe hiểu và trao đổi các chủ đề về ứng dụng công nghệ mới, tiến bộ khoa học công nghệ thay đổi cuộc sống,...","Có thể trình bày bằng lời nói hoặc văn bản về cách quay video ngắn, quan điểm đối với video ngắn,...","Hiểu được các hình thái kinh tế mới ở Trung Quốc như xe đạp chia sẻ, video ngắn, kinh tế dịch vụ tận nhà,..."],"vocab":[{"hanzi":"猜","pinyin":"cāi","pos":"dgt.","vn":"đoán","examples":[{"cn":"你猜猜我手里拿的是什么礼物？","pinyin":"Nǐ cāicai wǒ shǒulǐ ná de shì shénme lǐwù?","vn":"Bạn đoán xem trên tay tôi đang cầm món quà gì?"},{"cn":"真厉害，你一下子就猜对了！","pinyin":"Zhēn lìhai, nǐ yíxiàzi jiù cāiduì le!","vn":"Giỏi thật đấy, bạn đoán đúng ngay lập tức!"},{"cn":"我猜明天天气一定会很暖和。","pinyin":"Wǒ cāi míngtiān tiānqì yídìng huì hěn nuǎnhuo.","vn":"Tôi đoán ngày mai thời tiết chắc chắn sẽ rất ấm áp."}]},{"hanzi":"共享单车","pinyin":"gòngxiǎng dānchē","pos":"","vn":"xe đạp chia sẻ","examples":[{"cn":"地铁站门口停着很多共享单车，骑车回家特别方便。","pinyin":"Dìtiězhàn ménkǒu tíng zhe hěn duō gòngxiǎng dānchē, qíchē huíjiā tèbié fāngbiàn.","vn":"Trước cửa ga tàu điện ngầm đỗ rất nhiều xe đạp chia sẻ, đạp xe về nhà đặc biệt tiện lợi."},{"cn":"现在越来越多的人选择骑共享单车上班。","pinyin":"Xiànzài yuè lái yuè duō de rén xuǎnzé qí gòngxiǎng dānchē shàngbān.","vn":"Hiện nay ngày càng nhiều người chọn đạp xe đạp chia sẻ đi làm."},{"cn":"骑完共享单车后，请把车停在指定的区域。","pinyin":"Qí wán gòngxiǎng dānchē hòu, qǐng bǎ chē tíng zài zhǐdìng de qūyù.","vn":"Sau khi đạp xong xe đạp chia sẻ, xin hãy đỗ xe ở khu vực quy định."}]},{"hanzi":"出口","pinyin":"chūkǒu","pos":"dt.","vn":"lối ra, cửa ra","examples":[{"cn":"请沿着指示牌往东出口走。","pinyin":"Qǐng yánzhe zhǐshìpái wǎng dōng chūkǒu zǒu.","vn":"Xin vui lòng đi theo biển chỉ dẫn về phía lối ra phía Đông."},{"cn":"我们一会儿在地铁站的B出口见面吧。","pinyin":"Wǒmen yíhuìr zài dìtiězhàn de B chūkǒu jiànmiàn ba.","vn":"Một lát nữa chúng ta gặp nhau ở cửa ra B của ga tàu điện ngầm nhé."},{"cn":"商场的出口处停着很多出租车。","pinyin":"Shāngchǎng de chūkǒuchù tíng zhe hěn duō chūzūchē.","vn":"Ở lối ra của trung tâm thương mại có rất nhiều xe taxi đang đỗ."}]},{"hanzi":"推","pinyin":"tuī","pos":"dgt.","vn":"đẩy, dắt (xe)","examples":[{"cn":"门上写着“推”，不是“拉”。","pinyin":"Mén shang xiě zhe \"tuī\", búshì \"lā\".","vn":"Trên cửa viết là \"đẩy\", không phải \"kéo\"."},{"cn":"自行车没气了，我只好推着车走回家。","pinyin":"Zìxíngchē méiqì le, wǒ zhǐhǎo tuī zhe chē zǒu huíjiā.","vn":"Xe đạp hết hơi rồi, tôi đành phải dắt xe đi bộ về nhà."},{"cn":"在超市里，他推着购物车挑选了很多蔬菜。","pinyin":"Zài chāoshì lǐ, tā tuī zhe gòuwùchē tiāoxuǎn le hěn duō shūcài.","vn":"Trong siêu thị, anh ấy đẩy xe hàng chọn mua rất nhiều rau củ."}]},{"hanzi":"对","pinyin":"duì","pos":"dgt.","vn":"hướng về, chĩa vào","examples":[{"cn":"你把手机摄像头对着这个二维码扫一下就行了。","pinyin":"Nǐ bǎ shǒujī shèxiàngtóu duìzhe zhège èrwéimǎ sǎo yíxià jiù xíng le.","vn":"Bạn hướng camera điện thoại vào mã QR này quét một cái là được."},{"cn":"拍照的时候，大家请对着镜头笑一笑。","pinyin":"Pāizhào de shíhou, dàjiā qǐng duìzhe jìngtóu xiàoyixiào.","vn":"Lúc chụp ảnh, mọi người hãy hướng về ống kính mỉm cười nhé."},{"cn":"别把空调风直接对着身体吹，容易感冒。","pinyin":"Bié bǎ kōngtiáo fēng zhíjiē duìzhe shēntǐ chuī, róngyì gǎnmào.","vn":"Đừng để gió điều hòa thổi trực tiếp vào người, rất dễ bị cảm lạnh."}]},{"hanzi":"二维码","pinyin":"èrwéimǎ","pos":"dt.","vn":"mã QR","examples":[{"cn":"在餐厅吃饭，扫一下桌上的二维码就能点菜。","pinyin":"Zài cāntīng chīfàn, sǎo yíxià zhuō shang de èrwéimǎ jiù néng diǎncài.","vn":"Đi ăn ở nhà hàng, quét mã QR trên bàn là có thể gọi món ngay."},{"cn":"请你打开付款二维码，我来扫你。","pinyin":"Qǐng nǐ dǎkāi fùkuǎn èrwéimǎ, wǒ lái sǎo nǐ.","vn":"Bạn hãy mở mã QR thanh toán ra, để tôi quét mã của bạn."},{"cn":"现在用二维码坐公交车和地铁非常方便。","pinyin":"Xiànzài yòng èrwéimǎ zuò gōngjiāochē hé dìtiě fēicháng fāngbiàn.","vn":"Hiện nay dùng mã QR đi xe buýt và tàu điện ngầm vô cùng tiện lợi."}]},{"hanzi":"注册","pinyin":"zhùcè","pos":"dgt.","vn":"đăng ký","examples":[{"cn":"第一次使用这个网站，需要先用手机号注册。","pinyin":"Dì yī cì shǐyòng zhège wǎngzhàn, xūyào xiān yòng shǒujīhào zhùcè.","vn":"Lần đầu sử dụng trang web này, cần dùng số điện thoại để đăng ký trước."},{"cn":"我刚刚在网上注册了一个学习汉语的账号。","pinyin":"Wǒ gānggāng zài wǎngshang zhùcè le yí ge xuéxí Hànyǔ de zhànghào.","vn":"Tôi vừa mới đăng ký một tài khoản học tiếng Hán trên mạng."},{"cn":"新生入学前必须按时完成注册手续。","pinyin":"Xīnshēng rùxué qián bìxū ànshí wánchéng zhùcè shǒuxù.","vn":"Tân sinh viên trước khi nhập học bắt buộc phải hoàn thành thủ tục đăng ký đúng hạn."}]},{"hanzi":"费用","pinyin":"fèiyong","pos":"dt.","vn":"chi phí, phí","examples":[{"cn":"这次出差的所有费用都由公司报销。","pinyin":"Zhè cì chūchāi de suǒyǒu fèiyong dōu yóu gōngsī bàoxiāo.","vn":"Toàn bộ chi phí của chuyến công tác lần này đều do công ty thanh toán."},{"cn":"请问参加这个夏令营需要多少费用？","pinyin":"Qǐngwèn cānjiā zhège xiàlìngyíng xūyào duōshao fèiyong?","vn":"Xin hỏi tham gia trại hè này cần bao nhiêu chi phí?"},{"cn":"每个月的生活费用我们要合理安排。","pinyin":"Měi ge yuè de shēnghuó fèiyong wǒmen yào hélǐ ānpái.","vn":"Chi phí sinh hoạt hằng tháng chúng ta cần sắp xếp hợp lý."}]},{"hanzi":"说明","pinyin":"shuōmíng","pos":"dt./dgt.","vn":"hướng dẫn; giải thích, nói rõ","examples":[{"cn":"吃药之前一定要仔细阅读使用说明。","pinyin":"Chīyào zhīqián yídìng yào zǐxì yuèdú shǐyòng shuōmíng.","vn":"Trước khi uống thuốc nhất định phải đọc kỹ hướng dẫn sử dụng."},{"cn":"请你向大家说明一下明天的活动安排。","pinyin":"Qǐng nǐ xiàng dàjiā shuōmíng yíxià míngtiān de huódòng ānpái.","vn":"Bạn hãy giải thích rõ với mọi người về lịch trình hoạt động ngày mai nhé."},{"cn":"他这次能拿到好成绩，说明平时非常努力。","pinyin":"Tā zhè cì néng nádào hǎo chéngjì, shuōmíng píngshí fēicháng nǔlì.","vn":"Lần này cậu ấy đạt được thành tích tốt, chứng tỏ bình thường rất chăm chỉ."}]},{"hanzi":"办事","pinyin":"bànshì","pos":"dgt.","vn":"làm việc, giải quyết công việc","examples":[{"cn":"今天上午我要去银行办事，下午才能回公司。","pinyin":"Jīntiān shàngwǔ wǒ yào qù yínháng bànshì, xiàwǔ cái néng huí gōngsī.","vn":"Sáng nay tôi phải đến ngân hàng giải quyết công việc, buổi chiều mới về công ty được."},{"cn":"他办事非常认真，大家都很放心。","pinyin":"Tā bànshì fēicháng rènzhēn, dàjiā dōu hěn fàngxīn.","vn":"Anh ấy làm việc rất nghiêm túc, mọi người đều rất yên tâm."},{"cn":"现在很多事情在网上就能办，出门办事省了不少时间。","pinyin":"Xiànzài hěn duō shìqing zài wǎngshang jiù néng bàn, chūmén bànshì shěng le bùshǎo shíjiān.","vn":"Bây giờ rất nhiều việc có thể làm ngay trên mạng, ra ngoài giải quyết công việc tiết kiệm được khá nhiều thời gian."}]},{"hanzi":"差点儿","pinyin":"chàdiǎnr","pos":"phó.","vn":"suýt nữa, thiếu chút nữa","examples":[{"cn":"今天早上路上堵车，我差点儿迟到了。","pinyin":"Jīntiān zǎoshang lùshang dǔchē, wǒ chàdiǎnr chídào le.","vn":"Sáng nay trên đường bị tắc xe, tôi suýt nữa thì đến muộn."},{"cn":"刚才差点儿忘了把书还给你。","pinyin":"Gāngcái chàdiǎnr wàng le bǎ shū huángěi nǐ.","vn":"Vừa nãy suýt chút nữa thì quên trả sách cho bạn."},{"cn":"地上有点儿滑，他差点儿摔倒。","pinyin":"Dìshang yǒudiǎnr huá, tā chàdiǎnr shuāidǎo.","vn":"Mặt đất hơi trơn, anh ấy suýt nữa thì bị ngã."}]},{"hanzi":"拍","pinyin":"pāi","pos":"dgt.","vn":"quay (phim, video), chụp (ảnh)","examples":[{"cn":"我们在这个风景优美的地方拍张合影吧。","pinyin":"Wǒmen zài zhège fēngjǐng yōuměi de dìfang pāi zhāng héyǐng ba.","vn":"Chúng ta chụp một bức ảnh chung ở nơi phong cảnh tuyệt đẹp này nhé."},{"cn":"他喜欢用手机拍短视频，记录自己的旅行生活。","pinyin":"Tā xǐhuan yòng shǒujī pāi duǎnshìpín, jìlù zìjǐ de lǚxíng shēnghuó.","vn":"Anh ấy thích dùng điện thoại quay video ngắn để ghi lại cuộc sống du lịch của mình."},{"cn":"这部反映中国美食的纪录片拍得特别精彩。","pinyin":"Zhè bù fǎnyìng Zhōngguó měishí de jìlùpiàn pāi de tèbié jīngcǎi.","vn":"Bộ phim tài liệu về ẩm thực Trung Quốc này quay đặc biệt xuất sắc."}]},{"hanzi":"各个","pinyin":"gègè","pos":"đt./phó.","vn":"các, từng, mỗi","examples":[{"cn":"这个问题需要从各个方面去考虑。","pinyin":"Zhège wèntí xūyào cóng gègè fāngmiàn qù kǎolǜ.","vn":"Vấn đề này cần phải xem xét từ các phương diện."},{"cn":"运动会上，各个班级的同学都表现得很出色。","pinyin":"Yùndònghuì shang, gègè bānjí de tóngxué dōu biǎoxiàn de hěn chūsè.","vn":"Tại hội thao, các bạn học sinh của từng lớp đều thể hiện rất xuất sắc."},{"cn":"我们班的同学各个都很热心，喜欢互相帮助。","pinyin":"Wǒmen bān de tóngxué gègè dōu hěn rèxīn, xǐhuan hùxiāng bāngzhù.","vn":"Các bạn trong lớp chúng tôi ai nấy đều rất nhiệt tình, thích giúp đỡ lẫn nhau."}]},{"hanzi":"小组","pinyin":"xiǎozǔ","pos":"dt.","vn":"nhóm, tổ","examples":[{"cn":"老师把全班同学分成了五个学习小组。","pinyin":"Lǎoshī bǎ quánbān tóngxué fēnchéng le wǔ ge xuéxí xiǎozǔ.","vn":"Thầy giáo đã chia cả lớp thành năm nhóm học tập."},{"cn":"我们小组明天下午要汇报调查结果。","pinyin":"Wǒmen xiǎozǔ míngtiān xiàwǔ yào huìbào diàochá jiéguǒ.","vn":"Chiều mai nhóm chúng tôi sẽ báo cáo kết quả khảo sát."},{"cn":"在小组合作中，每个人都有自己的任务。","pinyin":"Zài xiǎozǔ hézuò zhōng, měi ge rén dōu yǒu zìjǐ de rènwu.","vn":"Trong hoạt động hợp tác nhóm, mỗi người đều có nhiệm vụ riêng của mình."}]},{"hanzi":"讨论","pinyin":"tǎolùn","pos":"dgt.","vn":"thảo luận","examples":[{"cn":"请大家分组讨论一下这个话题。","pinyin":"Qǐng dàjiā fēnzǔ tǎolùn yíxià zhège huàtí.","vn":"Mời mọi người chia nhóm thảo luận về chủ đề này."},{"cn":"关于去哪儿旅游，我们全家讨论了整整一个晚上。","pinyin":"Guānyú qù nǎr lǚyóu, wǒmen quánjiā tǎolùn le zhěngzhěng yí ge wǎnshang.","vn":"Về việc đi du lịch ở đâu, cả nhà chúng tôi đã thảo luận suốt cả một buổi tối."},{"cn":"经过热烈讨论，大家终于达成了一致意见。","pinyin":"Jīngguò rèliè tǎolùn, dàjiā zhōngyú dáchéng le yízhì yìjiàn.","vn":"Sau cuộc thảo luận sôi nổi, cuối cùng mọi người đã đạt được ý kiến thống nhất."}]},{"hanzi":"演","pinyin":"yǎn","pos":"dgt.","vn":"diễn, đóng vai","examples":[{"cn":"她在这部电影里演一位年轻的老师。","pinyin":"Tā zài zhè bù diànyǐng lǐ yǎn yí wèi niánqīng de lǎoshī.","vn":"Cô ấy đóng vai một cô giáo trẻ trong bộ phim này."},{"cn":"这个节目他们演得非常生动，逗得观众哈哈大笑。","pinyin":"Zhège jiémù tāmen yǎn de fēicháng shēngdòng, dòu de guānzhòng hāhā dàxiào.","vn":"Tiết mục này họ diễn vô cùng sinh động, khiến khán giả cười phá lên."},{"cn":"听说今天晚上剧院里要演一场京剧。","pinyin":"Tīngshuō jīntiān wǎnshang jùyuàn lǐ yào yǎn yì chǎng Jīngjù.","vn":"Nghe nói tối nay ở nhà hát sẽ diễn một vở Kinh kịch."}]},{"hanzi":"厨师","pinyin":"chúshī","pos":"dt.","vn":"đầu bếp","examples":[{"cn":"这家饭店的厨师手艺非常高超。","pinyin":"Zhè jiā fàndiàn de chúshī shǒuyì fēicháng gāochāo.","vn":"Tay nghề của đầu bếp nhà hàng này vô cùng điêu luyện."},{"cn":"我叔叔是一位有二十年经验的川菜厨师。","pinyin":"Wǒ shūshu shì yí wèi yǒu èrshí nián jīngyàn de Chuāncài chúshī.","vn":"Chú tôi là một đầu bếp món Tứ Xuyên có hai mươi năm kinh nghiệm."},{"cn":"他从小对做饭感兴趣，长大后当了一名厨师。","pinyin":"Tā cóngxiǎo duì zuòfàn gǎn xìngqù, zhǎngdà hòu dāng le yì míng chúshī.","vn":"Từ nhỏ anh ấy đã hứng thú với việc nấu ăn, lớn lên trở thành một đầu bếp."}]},{"hanzi":"各地","pinyin":"gèdì","pos":"dt.","vn":"khắp nơi, các địa phương","examples":[{"cn":"每年都有来自世界各地的游客参观故宫。","pinyin":"Měi nián dōu yǒu láizì shìjiè gèdì de yóukè cānguān Gùgōng.","vn":"Hằng năm đều có du khách từ khắp nơi trên thế giới đến tham quan Cố Cung."},{"cn":"中国各地的饮食习惯都有自己的特色。","pinyin":"Zhōngguó gèdì de yǐnshí xíguàn dōu yǒu zìjǐ de tèsè.","vn":"Thói quen ăn uống ở các địa phương Trung Quốc đều có nét đặc sắc riêng."},{"cn":"春节前，全国各地的火车站都非常热闹。","pinyin":"Chūnjié qián, quánguó gèdì de huǒchēzhàn dōu fēicháng rènao.","vn":"Trước Tết Nguyên Đán, các nhà ga xe lửa trên khắp cả nước đều vô cùng nhộn nhịp."}]},{"hanzi":"著名","pinyin":"zhùmíng","pos":"tt.","vn":"nổi tiếng","examples":[{"cn":"西湖是杭州最著名的风景区。","pinyin":"Xīhú shì Hángzhōu zuì zhùmíng de fēngjǐngqū.","vn":"Tây Hồ là khu danh thắng nổi tiếng nhất Hàng Châu."},{"cn":"这是一位非常著名的作家写的长篇小说。","pinyin":"Zhè shì yí wèi fēicháng zhùmíng de zuòjiā xiě de chángpiān xiǎoshuō.","vn":"Đây là cuốn tiểu thuyết dài do một nhà văn rất nổi tiếng viết."},{"cn":"北京烤鸭是享誉中外的著名美食。","pinyin":"Běijīng kǎoyā shì xiǎngyù Zhōngwài de zhùmíng měishí.","vn":"Vịt quay Bắc Kinh là món ngon nổi tiếng vang danh trong và ngoài nước."}]},{"hanzi":"小吃","pinyin":"xiǎochī","pos":"dt.","vn":"đồ ăn vặt, món ăn đặc sản địa phương","examples":[{"cn":"这条老街上有很多当地特色小吃。","pinyin":"Zhè tiáo lǎojiē shang yǒu hěn duō dāngdì tèsè xiǎochī.","vn":"Trên con phố cổ này có rất nhiều món ăn vặt đặc sản địa phương."},{"cn":"去成都旅游，一定不能错过那里的各种小吃。","pinyin":"Qù Chéngdū lǚyóu, yídìng bù néng cuòguò nàlǐ de gèzhǒng xiǎochī.","vn":"Đi du lịch Thành Đô, nhất định không thể bỏ lỡ các loại đồ ăn vặt ở đó."},{"cn":"周末晚上，我和朋友去夜市尝了不少小吃。","pinyin":"Zhōumò wǎnshang, wǒ hé péngyou qù yèshì cháng le bùshǎo xiǎochī.","vn":"Tối cuối tuần, tôi và bạn đi chợ đêm thưởng thức không ít món ăn vặt."}]},{"hanzi":"互联网","pinyin":"hùliánwǎng","pos":"dt.","vn":"mạng internet","examples":[{"cn":"互联网让世界变得越来越小了。","pinyin":"Hùliánwǎng ràng shìjiè biàn de yuè lái yuè xiǎo le.","vn":"Mạng internet làm cho thế giới trở nên ngày càng nhỏ bé hơn."},{"cn":"他毕业后进了一家很有名的互联网公司。","pinyin":"Tā bìyè hòu jìn le yì jiā hěn yǒumíng de hùliánwǎng gōngsī.","vn":"Sau khi tốt nghiệp anh ấy đã vào làm ở một công ty internet rất nổi tiếng."},{"cn":"通过互联网，我们可以随时查阅各种资料。","pinyin":"Tōngguò hùliánwǎng, wǒmen kěyǐ suíshí cháyuè gèzhǒng zīliào.","vn":"Thông qua mạng internet, chúng ta có thể tra cứu đủ loại tài liệu bất cứ lúc nào."}]},{"hanzi":"点赞","pinyin":"diǎnzàn","pos":"dgt.","vn":"nhấn thích (like), tán thưởng","examples":[{"cn":"她发的朋友圈照片太美了，很多人都给她点赞。","pinyin":"Tā fā de péngyouquān zhàopiàn tài měi le, hěn duō rén dōu gěi tā diǎnzàn.","vn":"Bức ảnh cô ấy đăng trên trang cá nhân đẹp quá, rất nhiều người đều nhấn thích cho cô ấy."},{"cn":"这条关于环保的短视频获得了一万多个点赞。","pinyin":"Zhè tiáo guānyú huánbǎo de duǎnshìpín huòdé le yíwàn duō ge diǎnzàn.","vn":"Đoạn video ngắn về bảo vệ môi trường này đã nhận được hơn một vạn lượt thích."},{"cn":"大家纷纷为这位见义勇为的年轻人点赞。","pinyin":"Dàjiā fēnfēn wèi zhè wèi jiànyìyǒngwéi de niánqīngrén diǎnzàn.","vn":"Mọi người thi nhau bày tỏ sự tán thưởng dành cho chàng trai trẻ dũng cảm làm việc nghĩa này."}]},{"hanzi":"AI眼镜","pinyin":"AI yǎnjìng","pos":"","vn":"kính AI, kính thông minh AI","examples":[{"cn":"戴上这副AI眼镜，就能实时翻译外语。","pinyin":"Dàishang zhè fù AI yǎnjìng, jiù néng shíshí fānyì wàiyǔ.","vn":"Đeo chiếc kính AI này vào là có thể dịch ngoại ngữ theo thời gian thực."},{"cn":"科技展上，很多观众排队体验最新款的AI眼镜。","pinyin":"Kējìzhǎn shang, hěn duō guānzhòng páiduì tǐyàn zuìxīnkuǎn de AI yǎnjìng.","vn":"Tại triển lãm công nghệ, rất nhiều khách tham quan xếp hàng trải nghiệm mẫu kính AI mới nhất."},{"cn":"这款AI眼镜不仅轻便，还可以拍照和导航。","pinyin":"Zhè kuǎn AI yǎnjìng bùjǐn qīngbiàn, hái kěyǐ pāizhào hé dǎoháng.","vn":"Mẫu kính AI này không chỉ nhẹ nhàng tiện lợi mà còn có thể chụp ảnh và chỉ đường."}]},{"hanzi":"3D打印机","pinyin":"3D dǎyìnjī","pos":"","vn":"máy in 3D","examples":[{"cn":"设计师用3D打印机做出了一个精致的建筑模型。","pinyin":"Shèjìshī yòng 3D dǎyìnjī zuòchū le yí ge jīngzhì de jiànzhù móxíng.","vn":"Nhà thiết kế đã dùng máy in 3D tạo ra một mô hình kiến trúc tinh xảo."},{"cn":"现在很多学校的创客教室里都配备了3D打印机。","pinyin":"Xiànzài hěn duō xuéxiào de chuàngkè jiàoshì lǐ dōu pèibèi le 3D dǎyìnjī.","vn":"Hiện nay phòng học sáng tạo ở nhiều trường học đều được trang bị máy in 3D."},{"cn":"你知道3D打印机还能用来打印医疗器材吗？","pinyin":"Nǐ zhīdào 3D dǎyìnjī hái néng yònglái dǎyìn yīliáo qìcái ma?","vn":"Bạn có biết máy in 3D còn có thể dùng để in thiết bị y tế không?"}]},{"hanzi":"上门","pinyin":"shàngmén","pos":"dgt.","vn":"đến tận nhà, tới cửa","examples":[{"cn":"空调坏了，我打电话请维修师傅上门检查。","pinyin":"Kōngtiáo huài le, wǒ dǎ diànhuà qǐng wéixiū shīfu shàngmén jiǎnchá.","vn":"Điều hòa bị hỏng rồi, tôi gọi điện nhờ thợ sửa chữa đến tận nhà kiểm tra."},{"cn":"现在寄快递特别方便，快递员会按时上门取件。","pinyin":"Xiànzài jì kuàidì tèbié fāngbiàn, kuàidìyuán huì ànshí shàngmén qǔjiàn.","vn":"Bây giờ gửi chuyển phát nhanh đặc biệt tiện lợi, nhân viên giao hàng sẽ đến tận nhà lấy hàng đúng hẹn."},{"cn":"这家商店提供免费上门安装服务。","pinyin":"Zhè jiā shāngdiàn tígōng miǎnfèi shàngmén ānzhuāng fúwù.","vn":"Cửa hàng này cung cấp dịch vụ lắp đặt tận nhà miễn phí."}]},{"hanzi":"到底","pinyin":"dàodǐ","pos":"phó.","vn":"rốt cuộc, tóm lại (dùng trong câu hỏi để nhấn mạnh)","examples":[{"cn":"这件事到底是谁负责的？","pinyin":"Zhè jiàn shì dàodǐ shì shéi fùzé de?","vn":"Việc này rốt cuộc là ai phụ trách vậy?"},{"cn":"你明天到底去不去参加聚会？","pinyin":"Nǐ míngtiān dàodǐ qù bu qù cānjiā jùhuì?","vn":"Ngày mai rốt cuộc bạn có đi dự tiệc không?"},{"cn":"我找了半天，钥匙到底放到哪儿去了？","pinyin":"Wǒ zhǎo le bàntiān, yàoshi dàodǐ fàngdào nǎr qù le?","vn":"Tôi tìm mãi rồi, rốt cuộc chìa khóa đã để ở đâu mất tiêu rồi?"}]},{"hanzi":"仅","pinyin":"jǐn","pos":"phó.","vn":"chỉ, mới","examples":[{"cn":"从这里坐地铁到机场仅需半个小时。","pinyin":"Cóng zhèlǐ zuò dìtiě dào jīchǎng jǐn xū bàn ge xiǎoshí.","vn":"Từ đây đi tàu điện ngầm đến sân bay chỉ mất nửa tiếng đồng hồ."},{"cn":"那本书仅售二十元，非常划算。","pinyin":"Nà běn shū jǐn shòu èrshí yuán, fēicháng huásuàn.","vn":"Cuốn sách đó chỉ bán hai mươi tệ, vô cùng phải chăng."},{"cn":"他仅用三天时间就完成了这项设计。","pinyin":"Tā jǐn yòng sān tiān shíjiān jiù wánchéng le zhè xiàng shèjì.","vn":"Anh ấy chỉ dùng ba ngày đã hoàn thành bản thiết kế này."}]},{"hanzi":"多样","pinyin":"duōyàng","pos":"tt.","vn":"đa dạng","examples":[{"cn":"学校食堂的菜品种类丰富多样。","pinyin":"Xuéxiào shítáng de càipǐn zhǒnglèi fēngfù duōyàng.","vn":"Các món ăn ở nhà ăn trường học vô cùng phong phú và đa dạng."},{"cn":"现在的支付方式非常多样，出门甚至不用带现金。","pinyin":"Xiànzài de zhīfù fāngshì fēicháng duōyàng, chūmén shènzhì búyòng dài xiànjīn.","vn":"Phương thức thanh toán hiện nay rất đa dạng, ra ngoài thậm chí không cần mang tiền mặt."},{"cn":"这座公园的植物形态多样，四季景色各不相同。","pinyin":"Zhè zuò gōngyuán de zhíwù xíngtài duōyàng, sìjì jǐngsè gè bù xiāngtóng.","vn":"Thực vật ở công viên này có hình thái đa dạng, cảnh sắc bốn mùa đều khác nhau."}]},{"hanzi":"推出","pinyin":"tuīchū","pos":"dgt.","vn":"ra mắt, tung ra, giới thiệu","examples":[{"cn":"这家公司最近推出了一款新型智能手机。","pinyin":"Zhè jiā gōngsī zuìjìn tuīchū le yì kuǎn xīnxíng zhìnéng shǒujī.","vn":"Công ty này gần đây đã cho ra mắt một mẫu điện thoại thông minh kiểu mới."},{"cn":"为了吸引顾客，饭店推出了几道春季新菜。","pinyin":"Wèile xīyǐn gùkè, fàndiàn tuīchū le jǐ dào chūnjì xīncài.","vn":"Để thu hút khách hàng, nhà hàng đã tung ra vài món mới cho mùa xuân."},{"cn":"这个在线课程一经推出，就受到了大家的欢迎。","pinyin":"Zhège zàixiàn kèchéng yìjīng tuīchū, jiù shòudào le dàjiā de huānyíng.","vn":"Khóa học trực tuyến này vừa ra mắt đã nhận được sự đón nhận của mọi người."}]},{"hanzi":"预约","pinyin":"yùyuē","pos":"dgt.","vn":"đặt lịch trước, hẹn trước","examples":[{"cn":"参观这座博物馆需要提前在网上预约门票。","pinyin":"Cānguān zhè zuò bówùguǎn xūyào tíqián zài wǎngshang yùyuē ménpiào.","vn":"Tham quan bảo tàng này cần đặt vé trước trên mạng."},{"cn":"我已经预约了明天上午十点看牙医。","pinyin":"Wǒ yǐjīng yùyuē le míngtiān shàngwǔ shí diǎn kàn yáyī.","vn":"Tôi đã đặt lịch khám nha sĩ vào mười giờ sáng mai rồi."},{"cn":"这家理发店生意很好，去之前最好先电话预约。","pinyin":"Zhè jiā lǐfàdiàn shēngyi hěn hǎo, qù zhīqián zuìhǎo xiān diànhuà yùyuē.","vn":"Tiệm cắt tóc này làm ăn rất phát đạt, trước khi đến tốt nhất nên gọi điện đặt lịch trước."}]},{"hanzi":"取","pinyin":"qǔ","pos":"dgt.","vn":"lấy, nhận","examples":[{"cn":"我下楼去快递柜取一下刚到的包裹。","pinyin":"Wǒ xiàlóu qù kuàidìguì qǔ yíxià gāng dào de bāoguǒ.","vn":"Tôi xuống lầu ra tủ giao nhận hàng lấy bưu kiện vừa tới."},{"cn":"请问附近哪里有可以取现金的银行？","pinyin":"Qǐngwèn fùjìn nǎlǐ yǒu kěyǐ qǔ xiànjīn de yínháng?","vn":"Xin hỏi gần đây có ngân hàng nào rút được tiền mặt không?"},{"cn":"衣服洗好了，明天下午你可以来干洗店取。","pinyin":"Yīfu xǐhǎo le, míngtiān xiàwǔ nǐ kěyǐ lái gānxǐdiàn qǔ.","vn":"Quần áo đã giặt xong rồi, chiều mai bạn có thể đến tiệm giặt khô lấy."}]},{"hanzi":"原因","pinyin":"yuányīn","pos":"dt.","vn":"nguyên nhân, lý do","examples":[{"cn":"由于天气原因，今天的航班推迟了两个小时。","pinyin":"Yóuyú tiānqì yuányīn, jīntiān de hángbān tuīchí le liǎng ge xiǎoshí.","vn":"Do nguyên nhân thời tiết, chuyến bay hôm nay bị hoãn hai tiếng đồng hồ."},{"cn":"你能告诉我你迟到的原因吗？","pinyin":"Nǐ néng gàosu wǒ nǐ chídào de yuányīn ma?","vn":"Bạn có thể nói cho tôi biết lý do bạn đến muộn không?"},{"cn":"我们必须找出问题发生的主要原因。","pinyin":"Wǒmen bìxū zhǎochū wèntí fāshēng de zhǔyào yuányīn.","vn":"Chúng ta nhất định phải tìm ra nguyên nhân chính dẫn đến vấn đề này."}]},{"hanzi":"然而","pinyin":"rán'ér","pos":"liên.","vn":"tuy nhiên, nhưng mà","examples":[{"cn":"他虽然年纪不大，然而做事却非常成熟稳重。","pinyin":"Tā suīrán niánjì búdà, rán'ér zuòshì què fēicháng chéngshú wěnzhòng.","vn":"Tuy tuổi anh ấy chưa lớn, nhưng làm việc lại vô cùng chín chắn, điềm đạm."},{"cn":"我们做了充分的准备，然而比赛结果还是出乎意料。","pinyin":"Wǒmen zuò le chōngfèn de zhǔnbèi, rán'ér bǐsài jiéguǒ háishi chūhū yìliào.","vn":"Chúng tôi đã chuẩn bị rất kỹ càng, tuy nhiên kết quả thi đấu vẫn nằm ngoài dự đoán."},{"cn":"本来以为今天会晴天，然而下午突然下起了大雨。","pinyin":"Běnlái yǐwéi jīntiān huì qíngtiān, rán'ér xiàwǔ tūrán xiàqǐ le dàyǔ.","vn":"Vốn tưởng hôm nay trời sẽ nắng, nhưng buổi chiều bỗng nhiên đổ mưa to."}]},{"hanzi":"不必","pinyin":"búbì","pos":"phó.","vn":"không cần, không nhất thiết","examples":[{"cn":"这点儿小事我自己能处理，你不必专门跑一趟。","pinyin":"Zhè diǎnr xiǎoshì wǒ zìjǐ néng chǔlǐ, nǐ búbì zhuānmén pǎo yí tàng.","vn":"Chuyện nhỏ này tôi tự xử lý được, bạn không cần mất công chạy sang một chuyến đâu."},{"cn":"大家都是老朋友了，不必这么客气。","pinyin":"Dàjiā dōu shì lǎo péngyou le, búbì zhème kèqi.","vn":"Mọi người đều là bạn cũ cả rồi, không cần khách sáo như vậy đâu."},{"cn":"你不必太担心，医生说他的伤很快就会好。","pinyin":"Nǐ búbì tài dānxīn, yīshēng shuō tā de shāng hěn kuài jiù huì hǎo.","vn":"Bạn không cần quá lo lắng, bác sĩ nói vết thương của anh ấy sẽ nhanh khỏi thôi."}]},{"hanzi":"亲戚","pinyin":"qīnqi","pos":"dt.","vn":"họ hàng, người thân","examples":[{"cn":"过年的时候，我们全家都会去拜访亲戚朋友。","pinyin":"Guònián de shíhou, wǒmen quánjiā dōu huì qù bàifǎng qīnqi péngyou.","vn":"Dịp Tết đến, cả nhà chúng tôi đều đi thăm hỏi họ hàng bạn bè."},{"cn":"我在北京没有亲戚，平时遇到困难多亏了朋友帮忙。","pinyin":"Wǒ zài Běijīng méiyǒu qīnqi, píngshí yùdào kùnnan duōkuī le péngyou bāngmáng.","vn":"Tôi không có họ hàng ở Bắc Kinh, bình thường gặp khó khăn đều nhờ bạn bè giúp đỡ."},{"cn":"昨天我表姐结婚，家里来了很多亲戚。","pinyin":"Zuótiān wǒ biǎojiě jiéhūn, jiālǐ lái le hěn duō qīnqi.","vn":"Hôm qua chị họ tôi kết hôn, rất nhiều họ hàng đã đến nhà."}]},{"hanzi":"按","pinyin":"àn","pos":"giới./dgt.","vn":"theo, dựa theo; ấn, bấm","examples":[{"cn":"请大家按顺序排队上车，不要拥挤。","pinyin":"Qǐng dàjiā àn shùnxù páiduì shàngchē, búyào yōngjǐ.","vn":"Xin mọi người xếp hàng lên xe theo thứ tự, đừng chen lấn."},{"cn":"进入电梯后，请帮我按一下八楼。","pinyin":"Jìnrù diàntī hòu, qǐng bāng wǒ àn yíxià bā lóu.","vn":"Vào thang máy rồi, phiền bạn bấm giúp tôi tầng tám nhé."},{"cn":"只要按说明书上的步骤操作，很快就能学会。","pinyin":"Zhǐyào àn shuōmíngshū shang de bùzhòu cāozuò, hěn kuài jiù néng xuéhuì.","vn":"Chỉ cần thao tác theo các bước trong sách hướng dẫn là sẽ học được rất nhanh."}]},{"hanzi":"提出","pinyin":"tíchū","pos":"dgt.","vn":"đưa ra, đề xuất","examples":[{"cn":"在今天的会议上，他提出了一个非常好的建议。","pinyin":"Zài jīntiān de huìyì shang, tā tíchū le yí ge fēicháng hǎo de jiànyì.","vn":"Trong cuộc họp hôm nay, anh ấy đã đề xuất một ý kiến vô cùng hay."},{"cn":"如果大家对这个计划有什么意见，现在就可以提出来。","pinyin":"Rúguǒ dàjiā duì zhège jìhuà yǒu shénme yìjiàn, xiànzài jiù kěyǐ tíchūlai.","vn":"Nếu mọi người có ý kiến gì về kế hoạch này thì ngay bây giờ có thể nêu ra."},{"cn":"老师对我们的毕业论文提出了严格的要求。","pinyin":"Lǎoshī duì wǒmen de bìyè lùnwén tíchū le yángé de yāoqiú.","vn":"Thầy giáo đã đưa ra những yêu cầu nghiêm ngặt đối với luận văn tốt nghiệp của chúng tôi."}]},{"hanzi":"大大","pinyin":"dàdà","pos":"phó.","vn":"rất nhiều, đáng kể, vô cùng","examples":[{"cn":"高速铁路的开通大大缩短了城市之间的距离。","pinyin":"Gāosù tiělù de kāitōng dàdà suōduǎn le chéngshì zhījiān de jùlí.","vn":"Việc thông tuyến đường sắt cao tốc đã rút ngắn đáng kể khoảng cách giữa các thành phố."},{"cn":"使用新软件以后，我们的工作效率大大提高了。","pinyin":"Shǐyòng xīn ruǎnjiàn yǐhòu, wǒmen de gōngzuò xiàolǜ dàdà tígāo le.","vn":"Sau khi sử dụng phần mềm mới, hiệu suất làm việc của chúng tôi đã nâng cao rất nhiều."},{"cn":"这次活动的报名人数大大超过了我们的预期。","pinyin":"Zhè cì huódòng de bàomíng rénshù dàdà chāoguò le wǒmen de yùqī.","vn":"Số lượng người đăng ký hoạt động lần này đã vượt xa dự kiến của chúng tôi."}]},{"hanzi":"现有","pinyin":"xiànyǒu","pos":"tt.","vn":"hiện có","examples":[{"cn":"我们要充分利用现有的资源来解决这个问题。","pinyin":"Wǒmen yào chōngfèn lìyòng xiànyǒu de zīyuán lái jiějué zhège wèntí.","vn":"Chúng ta cần tận dụng triệt để các nguồn lực hiện có để giải quyết vấn đề này."},{"cn":"图书馆现有的藏书已经超过了一百万册。","pinyin":"Túshūguǎn xiànyǒu de cángshū yǐjīng chāoguò le yìbǎiwàn cè.","vn":"Số đầu sách hiện có của thư viện đã vượt quá một triệu cuốn."},{"cn":"随着业务扩大，公司现有的办公场地已经不够用了。","pinyin":"Suízhe yèwù kuòdà, gōngsī xiànyǒu de bàngōng chǎngdì yǐjīng búgòu yòng le.","vn":"Cùng với sự mở rộng kinh doanh, không gian văn phòng hiện có của công ty đã không còn đủ dùng nữa."}]}],"grammar":[{"title":"\"数词+形容词+量词\"结构","explanation_vn":"Cấu trúc \"Số từ + Tính từ + Lượng từ\" mang ngữ khí khoa trương, nhấn mạnh chủ quan độ lớn nhỏ của số lượng. Số từ thường là \"一\", tính từ thường là từ đơn âm tiết như \"大\", \"小\", lượng từ thường là danh lượng từ lâm thời. Thường dùng trong khẩu ngữ.","examples":[{"cn":"快到那边那个出口时又推了一小段。","pinyin":"Kuài dào nàbiān nàge chūkǒu shí yòu tuī le yì xiǎo duàn.","vn":"Lúc sắp tới lối ra đằng kia thì lại dắt bộ thêm một đoạn ngắn nữa."},{"cn":"今天早上我没吃饭就去上班了，中午饿极了，吃了一大碗面条儿。","pinyin":"Jīntiān zǎoshang wǒ méi chīfàn jiù qù shàngbān le, zhōngwǔ è jíle, chī le yí dà wǎn miàntiáor.","vn":"Sáng nay tôi chưa ăn gì đã đi làm, buổi trưa đói meo nên đã ăn một bát mì to đùng."},{"cn":"我今天又收到了妈妈寄来的快递，打开一看，除了衣服外，里边还有一大包巧克力。","pinyin":"Wǒ jīntiān yòu shōudào le māma jìlái de kuàidì, dǎkāi yí kàn, chúle yīfu wài, lǐbiān hái yǒu yí dà bāo qiǎokèlì.","vn":"Hôm nay tôi lại nhận được bưu kiện mẹ gửi tới, mở ra xem thì ngoài quần áo ra, bên trong còn có một gói sô-cô-la to nữa."}]},{"title":"被动句\"主语+让/叫+宾语+动词+其他成分\"","explanation_vn":"Câu bị động \"主语+让/叫+宾语+动词+其他成分\" (Chủ ngữ + 让/叫 + Tân ngữ + Động từ + Thành phần khác) biểu thị nghĩa bị động. Chủ ngữ là đối tượng chịu tác động (thụ sự), \"让\" hoặc \"叫\" dẫn ra chủ thể thực hiện hành động (thi sự). Thường dùng trong khẩu ngữ. Cấu trúc cơ bản: Chủ ngữ chịu tác động + 让/叫 + Tân ngữ thực hiện hành động + Động từ (thường đi kèm \"给\" hoặc bổ ngữ, trợ từ động thái).","examples":[{"cn":"后来这个视频让我同学放到了互联网上。","pinyin":"Hòulái zhège shìpín ràng wǒ tóngxué fàng dào le hùliánwǎng shàng.","vn":"Sau đó đoạn video này được bạn học của mình đăng lên mạng internet."},{"cn":"门叫小明给关上了。","pinyin":"Mén jiào Xiǎomíng gěi guānshàng le.","vn":"Cánh cửa bị Tiểu Minh đóng lại rồi."},{"cn":"不好意思，月饼都让我吃了。","pinyin":"Bù hǎoyìsi, yuèbǐng dōu ràng wǒ chī le.","vn":"Ngại quá, bánh trung thu đều bị mình ăn hết mất rồi."}]},{"title":"语气副词\"到底\"","explanation_vn":"Phó từ ngữ khí \"到底\" dùng trong câu hỏi, biểu thị sự truy hỏi, hỏi đến cùng. Thường dùng trong khẩu ngữ.","examples":[{"cn":"科技到底对世界产生了怎样的影响？","pinyin":"Kējì dàodǐ duì shìjiè chǎnshēng le zěnyàng de yǐngxiǎng?","vn":"Khoa học công nghệ rốt cuộc đã tạo ra những ảnh hưởng như thế nào đối với thế giới?"},{"cn":"你们到底还来不来？","pinyin":"Nǐmen dàodǐ hái lái bu lái?","vn":"Các cậu rốt cuộc có còn đến nữa không?"},{"cn":"你到底是怎么想的？为什么不同意？","pinyin":"Nǐ dàodǐ shì zěnme xiǎng de? Wèishénme bù tóngyì?","vn":"Cậu rốt cuộc nghĩ thế nào vậy? Tại sao lại không đồng ý?"}]},{"title":"转折复句\"……，然而……\"","explanation_vn":"Trong câu phức chuyển ngoặt \"……，然而……\", \"然而\" đứng ở đầu vế câu sau để biểu thị sự chuyển ngoặt. Tình huống phía sau \"然而\" hoặc tạo sự tương phản với tình huống phía trước, hoặc không giống với dự đoán ở phía trước.","examples":[{"cn":"由于工作等原因，她需要经常出差，然而又很担心猫的安全。","pinyin":"Yóuyú gōngzuò děng yuányīn, tā xūyào jīngcháng chūchāi, rán'ér yòu hěn dānxīn māo de ānquán.","vn":"Vì lý do công việc và các nguyên nhân khác, cô ấy cần thường xuyên đi công tác, tuy nhiên lại rất lo lắng cho sự an toàn của chú mèo."},{"cn":"毕业旅行现在越来越流行，然而由于学生没什么社会和生活经验，可能会遇到各种问题。","pinyin":"Bìyè lǚxíng xiànzài yuèláiyuè liúxíng, rán'ér yóuyú xuésheng méi shénme shèhuì hé shēnghuó jīngyàn, kěnéng huì yùdào gèzhǒng wèntí.","vn":"Du lịch tốt nghiệp hiện nay ngày càng thịnh hành, tuy nhiên do sinh viên chưa có nhiều kinh nghiệm xã hội và cuộc sống nên có thể gặp phải đủ loại vấn đề."},{"cn":"春天应该是花开的季节，然而由于前一段时间下大雪，现在花都没开。","pinyin":"Chūntiān yīnggāi shì huākāi de jìjié, rán'ér yóuyú qián yí duàn shíjiān xià dàxuě, xiànzài huā dōu méi kāi.","vn":"Mùa xuân đáng lẽ phải là mùa hoa nở, tuy nhiên do thời gian trước có tuyết rơi dày nên bây giờ hoa vẫn chưa nở."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"白家月","cn":"安妮，我们在这儿呢。","pinyin":"Ānnī, wǒmen zài zhèr ne."},{"speaker":"安妮","cn":"天中、家月，你们猜我是怎么过来的？","pinyin":"Tiānzhōng, Jiāyuè, nǐmen cāi wǒ shì zěnme guòlái de?"},{"speaker":"白家月","cn":"坐公交车吗？","pinyin":"Zuò gōngjiāochē ma?"},{"speaker":"安妮","cn":"我先坐的公交车，然后骑共享单车，快到那边那个出口时又推了一小段。","pinyin":"Wǒ xiān zuò de gōngjiāochē, ránhòu qí gòngxiǎng dānchē, kuài dào nàbiān nàge chūkǒu shí yòu tuī le yì xiǎo duàn."},{"speaker":"白家月","cn":"我看很多人都骑共享单车，我还没骑过呢。","pinyin":"Wǒ kàn hěn duō rén dōu qí gòngxiǎng dānchē, wǒ hái méi qíguo ne."},{"speaker":"陈天中","cn":"我骑过，很方便的。第一次骑的时候，你打开微信，对着共享单车上的二维码扫一下，在App上完成注册就可以了，怎么使用、费用标准什么的App上都有说明。","pinyin":"Wǒ qíguo, hěn fāngbiàn de. Dì yī cì qí de shíhou, nǐ dǎkāi Wēixìn, duìzhe gòngxiǎng dānchē shàng de èrwéimǎ sǎo yíxià, zài App shàng wánchéng zhùcè jiù kěyǐ le, zěnme shǐyòng, fèiyong biāozhǔn shénme de App shàng dōu yǒu shuōmíng."},{"speaker":"白家月","cn":"好啊！哪天我出去办事时也试试。","pinyin":"Hǎo a! Nǎ tiān wǒ chūqù bànshì shí yě shìshi."}],"translation_vn":"Bạch Gia Nguyệt: Annie, bọn mình ở đây nè.\nAnnie: Thiên Trung, Gia Nguyệt, hai cậu đoán xem mình đến đây bằng cách nào?\nBạch Gia Nguyệt: Đi xe buýt à?\nAnnie: Mình đi xe buýt trước, sau đó đạp xe đạp chia sẻ, lúc sắp đến lối ra đằng kia thì lại dắt bộ thêm một đoạn ngắn nữa.\nBạch Gia Nguyệt: Mình thấy nhiều người đi xe đạp chia sẻ lắm, mình vẫn chưa đi thử bao giờ.\nTrần Thiên Trung: Mình đi rồi, tiện lắm. Lần đầu đi, cậu mở WeChat, hướng camera vào mã QR trên xe đạp chia sẻ quét một cái, hoàn tất đăng ký trên ứng dụng là được, cách sử dụng hay mức phí ra sao trên ứng dụng đều có hướng dẫn cả.\nBạch Gia Nguyệt: Hay quá! Hôm nào ra ngoài giải quyết công việc mình cũng sẽ thử xem sao.","audio_dialogue":"18-1.mp3","audio_vocab":"18-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"安妮","cn":"差点儿忘了，我给你们看个短视频。","pinyin":"Chàdiǎnr wàng le, wǒ gěi nǐmen kàn ge duǎnshìpín."},{"speaker":"白家月","cn":"啊？你们拍的？真不错！","pinyin":"Á? Nǐmen pāi de? Zhēn búcuò!"},{"speaker":"安妮","cn":"对！前段时间老师留了个作业，叫各个小组拍个短视频，介绍中国美食。我们小组讨论后决定，由AI小语演厨师，做出中国各地的著名小吃。拍完后，老师说很不错。","pinyin":"Duì! Qián duàn shíjiān lǎoshī liú le ge zuòyè, jiào gègè xiǎozǔ pāi ge duǎnshìpín, jièshào Zhōngguó měishí. Wǒmen xiǎozǔ tǎolùn hòu juédìng, yóu AI Xiǎoyǔ yǎn chúshī, zuòchū Zhōngguó gèdì de zhùmíng xiǎochī. Pāiwán hòu, lǎoshī shuō hěn búcuò."},{"speaker":"陈天中","cn":"嗯，语言也很幽默！","pinyin":"Èn, yǔyán yě hěn yōumò!"},{"speaker":"安妮","cn":"后来这个视频让我同学放到了互联网上，很多人都来点赞。","pinyin":"Hòulái zhège shìpín ràng wǒ tóngxué fàng dào le hùliánwǎng shàng, hěn duō rén dōu lái diǎnzàn."},{"speaker":"白家月","cn":"看来大家都喜欢这个视频。","pinyin":"Kànlái dàjiā dōu xǐhuan zhège shìpín."},{"speaker":"安妮","cn":"后边我们打算拍第二个、第三个，让小语带大家到中国各地走一走、看一看。","pinyin":"Hòubiān wǒmen dǎsuàn pāi dì èr ge, dì sān ge, ràng Xiǎoyǔ dài dàjiā dào Zhōngguó gèdì zǒu yi zǒu, kàn yi kàn."},{"speaker":"陈天中","cn":"这样大家就能通过你们的视频了解中国了，我支持你们！","pinyin":"Zhèyàng dàjiā jiù néng tōngguò nǐmen de shìpín liǎojiě Zhōngguó le, wǒ zhīchí nǐmen!"}],"translation_vn":"Annie: Suýt nữa thì quên, mình cho hai cậu xem một đoạn video ngắn nhé.\nBạch Gia Nguyệt: Ồ? Các cậu quay à? Hay thật đấy!\nAnnie: Đúng vậy! Thời gian trước thầy giáo giao một bài tập, yêu cầu các nhóm quay một video ngắn giới thiệu ẩm thực Trung Quốc. Sau khi thảo luận, nhóm mình quyết định để AI Tiểu Ngữ đóng vai đầu bếp, làm ra các món ăn vặt nổi tiếng khắp các vùng miền Trung Quốc. Quay xong, thầy giáo khen hay lắm.\nTrần Thiên Trung: Ừ, lời thoại cũng rất hài hước nữa!\nAnnie: Sau đó đoạn video này được bạn học của mình đăng lên mạng internet, rất nhiều người đã vào nhấn thích.\nBạch Gia Nguyệt: Xem ra ai cũng thích video này cả.\nAnnie: Sắp tới bọn mình dự định quay video thứ hai, thứ ba, để Tiểu Ngữ dẫn mọi người đi dạo, tham quan khắp nơi ở Trung Quốc.\nTrần Thiên Trung: Như vậy mọi người sẽ có thể hiểu thêm về Trung Quốc thông qua video của các cậu rồi, mình ủng hộ các cậu!","audio_dialogue":"18-3.mp3","audio_vocab":"18-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"安妮骑共享单车到了白家月、陈天中的学校，三人从共享单车聊到AI眼镜和3D打印机，从绿色经济聊到上门经济。科技到底对世界产生了怎样的影响？他们都认为，科技确实改变了人们的生活。","pinyin":"Ānnī qí gòngxiǎng dānchē dàole Bái Jiāyuè, Chén Tiānzhōng de xuéxiào, sān rén cóng gòngxiǎng dānchē liáodào AI yǎnjìng hé 3D dǎyìnjī, cóng lǜsè jīngjì liáodào shàngmén jīngjì. Kējì dàodǐ duì shìjiè chǎnshēng le zěnyàng de yǐngxiǎng? Tāmen dōu rènwéi, kējì quèshí gǎibiàn le rénmen de shēnghuó."},{"speaker":"","cn":"接着，安妮给大家看了她和同学们拍的短视频。安妮说，短视频是用手机拍的，他们装了一些免费的App，仅用几天就拍完了。视频里，小语做的小吃丰富多样，看起来好吃极了。短视频推出后，大家认为非常精彩，白家月和陈天中看后也特别喜欢，并且表示支持他们拍更多的视频。","pinyin":"Jiēzhe, Ānnī gěi dàjiā kànle tā hé tóngxuémen pāi de duǎnshìpín. Ānnī shuō, duǎnshìpín shì yòng shǒujī pāi de, tāmen zhuāng le yìxiē miǎnfèi de App, jǐn yòng jǐ tiān jiù pāiwán le. Shìpín lǐ, Xiǎoyǔ zuò de xiǎochī fēngfù duōyàng, kàn qǐlái hǎochī jíle. Duǎnshìpín tuīchū hòu, dàjiā rènwéi fēicháng jīngcǎi, Bái Jiāyuè hé Chén Tiānzhōng kàn hòu yě tèbié xǐhuan, bìngqiě biǎoshì zhīchí tāmen pāi gèng duō de shìpín."}],"translation_vn":"Annie đạp xe đạp chia sẻ đến trường của Bạch Gia Nguyệt và Trần Thiên Trung, ba người trò chuyện từ xe đạp chia sẻ sang kính AI và máy in 3D, từ kinh tế xanh sang kinh tế dịch vụ tận nhà. Khoa học công nghệ rốt cuộc đã tạo ra những ảnh hưởng như thế nào đối với thế giới? Họ đều cho rằng khoa học công nghệ thực sự đã thay đổi cuộc sống của con người.\nTiếp đó, Annie cho mọi người xem đoạn video ngắn do cô và các bạn học quay. Annie nói rằng video ngắn được quay bằng điện thoại di động, họ đã cài đặt một vài ứng dụng miễn phí và chỉ mất vài ngày là quay xong. Trong video, những món ăn vặt mà Tiểu Ngữ làm vô cùng phong phú đa dạng, trông ngon tuyệt vời. Sau khi video ngắn được tung ra, mọi người đều cho rằng rất đặc sắc, Bạch Gia Nguyệt và Trần Thiên Trung xem xong cũng đặc biệt yêu thích, đồng thời bày tỏ sự ủng hộ họ quay thêm nhiều video nữa.","audio_dialogue":"18-5.mp3","audio_vocab":"18-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"随着互联网技术的发展，现在又出现了一种新的服务方式——上门经济，就是预约者通过网上预约，让服务人员在合适的时间到家里或者约好的地点服务，服务内容有上门做饭、照顾小动物、取东西等。赵女士养了一只猫，由于工作等原因，她需要经常出差，然而又很担心猫的安全。有了上门服务后，她觉得方便多了，不必再找亲戚帮忙。每次出差，在网上预约并支付费用后，服务人员就会按她提出的要求上门照顾小猫，大大减轻了她的压力，赵女士也特别满意。","pinyin":"Suízhe hùliánwǎng jìshù de fāzhǎn, xiànzài yòu chūxiàn le yì zhǒng xīn de fúwù fāngshì — shàngmén jīngjì, jiù shì yùyuēzhě tōngguò wǎngshàng yùyuē, ràng fúwù rényuán zài héshì de shíjiān dào jiālǐ huòzhě yuēhǎo de dìdiǎn fúwù, fúwù nèiróng yǒu shàngmén zuòfàn, zhàogù xiǎo dòngwù, qǔ dōngxi děng. Zhào nǚshì yǎng le yì zhī māo, yóuyú gōngzuò děng yuányīn, tā xūyào jīngcháng chūchāi, rán'ér yòu hěn dānxīn māo de ānquán. Yǒule shàngmén fúwù hòu, tā juéde fāngbiàn duō le, búbì zài zhǎo qīnqi bāngmáng. Měi cì chūchāi, zài wǎngshàng yùyuē bìng zhīfù fèiyong hòu, fúwù rényuán jiù huì àn tā tíchū de yāoqiú shàngmén zhàogù xiǎo māo, dàdà jiǎnqīng le tā de yālì, Zhào nǚshì yě tèbié mǎnyì."},{"speaker":"","cn":"当然，上门经济也有一些问题，特别是现有服务人员有些还不够专业，需要重新学习，提高服务质量。","pinyin":"Dāngrán, shàngmén jīngjì yě yǒu yìxiē wèntí, tèbié shì xiànyǒu fúwù rényuán yǒuxiē hái búgòu zhuānyè, xūyào chóngxīn xuéxí, tígāo fúwù zhìliàng."}],"translation_vn":"Cùng với sự phát triển của công nghệ internet, hiện nay lại xuất hiện một hình thức dịch vụ mới — kinh tế dịch vụ tận nhà, tức là người đặt lịch thông qua đặt hẹn trực tuyến để nhân viên dịch vụ đến nhà hoặc địa điểm đã hẹn vào thời gian phù hợp nhằm phục vụ, nội dung dịch vụ bao gồm nấu ăn tận nhà, chăm sóc thú cưng, lấy đồ giúp, v.v. Cô Triệu nuôi một con mèo, vì lý do công việc và các nguyên nhân khác nên cô cần thường xuyên đi công tác, tuy nhiên lại rất lo lắng cho sự an toàn của chú mèo. Từ khi có dịch vụ tận nhà, cô thấy tiện lợi hơn hẳn, không cần phải nhờ vả họ hàng giúp đỡ nữa. Mỗi lần đi công tác, sau khi đặt lịch và thanh toán chi phí trên mạng, nhân viên dịch vụ sẽ đến tận nhà chăm sóc chú mèo theo yêu cầu cô đưa ra, giúp giảm bớt đáng kể áp lực cho cô và cô Triệu cũng vô cùng hài lòng.\nTất nhiên, kinh tế dịch vụ tận nhà cũng tồn tại một số vấn đề, đặc biệt là một bộ phận nhân viên dịch vụ hiện có vẫn chưa đủ chuyên nghiệp, cần phải học tập bồi dưỡng lại để nâng cao chất lượng dịch vụ.","audio_dialogue":"18-7.mp3","audio_vocab":"18-8.mp3"}]},{"id":19,"title_cn":"他们都很棒","title_pinyin":"Tāmen dōu hěn bàng","title_vn":"Họ đều rất tuyệt","goals":["Có thể nghe hiểu và trao đổi các chủ đề liên quan đến văn học và nghệ thuật.","Có thể giới thiệu bằng lời nói hoặc văn bản về một tác phẩm hoặc một loại hình nghệ thuật.","Tìm hiểu về Kinh kịch — một trong những quốc túy của văn hóa truyền thống Trung Quốc."],"vocab":[{"hanzi":"话剧","pinyin":"huàjù","pos":"dt.","vn":"kịch nói","examples":[{"cn":"这个周末我打算和朋友去看一场话剧。","pinyin":"Zhège zhōumò wǒ dǎsuàn hé péngyou qù kàn yì chǎng huàjù.","vn":"Cuối tuần này tôi định đi xem một vở kịch nói cùng bạn bè."},{"cn":"小雪在学校的话剧表演中演得非常好。","pinyin":"Xiǎoxuě zài xuéxiào de huàjù biǎoyǎn zhōng yǎn de fēicháng hǎo.","vn":"Tiểu Tuyết diễn rất hay trong buổi biểu diễn kịch nói ở trường."},{"cn":"这部经典话剧已经在很多城市演出过了。","pinyin":"Zhè bù jīngdiǎn huàjù yǐjīng zài hěn duō chéngshì yǎnchū guo le.","vn":"Vở kịch nói kinh điển này đã được công diễn ở rất nhiều thành phố rồi."}]},{"hanzi":"排","pinyin":"pái","pos":"dgt.","vn":"diễn tập, tập dượt","examples":[{"cn":"为了学校的艺术节，我们排了一个月的话剧。","pinyin":"Wèile xuéxiào de yìshùjié, wǒmen pái le yí ge yuè de huàjù.","vn":"Vì lễ hội nghệ thuật của trường, chúng tôi đã tập kịch nói suốt một tháng."},{"cn":"这个节目已经排得差不多了，明天可以上台表演。","pinyin":"Zhège jiémù yǐjīng pái de chàbuduō le, míngtiān kěyǐ shàngtái biǎoyǎn.","vn":"Tiết mục này đã tập gần xong rồi, ngày mai có thể lên sân khấu biểu diễn."},{"cn":"演员们每天都在认真地排新节目。","pinyin":"Yǎnyuánmen měitiān dōu zài rènzhēn de pái xīn jiémù.","vn":"Các diễn viên mỗi ngày đều đang chăm chỉ tập dượt tiết mục mới."}]},{"hanzi":"艺术","pinyin":"yìshù","pos":"dt.","vn":"nghệ thuật","examples":[{"cn":"她从小就对音乐和绘画等艺术非常感兴趣。","pinyin":"Tā cóngxiǎo jiù duì yīnyuè hé huìhuà děng yìshù fēicháng gǎn xìngqù.","vn":"Cô ấy từ nhỏ đã rất hứng thú với các môn nghệ thuật như âm nhạc và hội họa."},{"cn":"我们学校每年秋天都会举办校园艺术节。","pinyin":"Wǒmen xuéxiào měinián qiūtiān dōu huì jǔbàn xiàoyuán yìshùjié.","vn":"Trường chúng tôi mỗi mùa thu đều tổ chức lễ hội nghệ thuật trong trường."},{"cn":"京剧是中国非常有代表性的传统艺术。","pinyin":"Jīngjù shì Zhōngguó fēicháng yǒu dàibiǎoxìng de chuántǒng yìshù.","vn":"Kinh kịch là loại hình nghệ thuật truyền thống vô cùng tiêu biểu của Trung Quốc."}]},{"hanzi":"内心","pinyin":"nèixīn","pos":"dt.","vn":"nội tâm, trong lòng","examples":[{"cn":"虽然他表面上很平静，但内心其实特别紧张。","pinyin":"Suīrán tā biǎomiàn shang hěn píngjìng, dàn nèixīn qíshí tèbié jǐnzhāng.","vn":"Tuy bề ngoài anh ấy rất bình tĩnh, nhưng trong lòng thực ra vô cùng căng thẳng."},{"cn":"听到这个好消息，我内心感到无比激动。","pinyin":"Tīngdào zhège hǎo xiāoxi, wǒ nèixīn gǎndào wúbǐ jīdòng.","vn":"Nghe thấy tin tốt này, trong lòng tôi cảm thấy vô cùng xúc động."},{"cn":"好朋友之间应该多交流，了解彼此内心的想法。","pinyin":"Hǎo péngyou zhījiān yīnggāi duō jiāoliú, liǎojiě bǐcǐ nèixīn de xiǎngfǎ.","vn":"Giữa những người bạn thân nên trò chuyện nhiều hơn để hiểu suy nghĩ trong lòng nhau."}]},{"hanzi":"自信","pinyin":"zìxìn","pos":"tt./dt./dgt.","vn":"tự tin; sự tự tin","examples":[{"cn":"老师鼓励大家在舞台上要表现得更加自信。","pinyin":"Lǎoshī gǔlì dàjiā zài wǔtái shang yào biǎoxiàn de gèngjiā zìxìn.","vn":"Thầy cô khích lệ mọi người phải thể hiện tự tin hơn nữa trên sân khấu."},{"cn":"这次比赛的成功给了她很大的自信。","pinyin":"Zhè cì bǐsài de chénggōng gěi le tā hěn dà de zìxìn.","vn":"Thành công của cuộc thi lần này đã mang lại cho cô ấy sự tự tin rất lớn."},{"cn":"只要平时准备充分，考试时就会很自信。","pinyin":"Zhǐyào píngshí zhǔnbèi chōngfèn, kǎoshì shí jiù huì hěn zìxìn.","vn":"Chỉ cần bình thường chuẩn bị kỹ lưỡng thì lúc thi sẽ rất tự tin."}]},{"hanzi":"少年","pinyin":"shàonián","pos":"dt.","vn":"thiếu niên","examples":[{"cn":"这位少年虽然年纪不大，但钢琴弹得非常出色。","pinyin":"Zhè wèi shàonián suīrán niánjì bú dà, dàn gāngqín tán de fēicháng chūsè.","vn":"Cậu thiếu niên này tuy tuổi không lớn nhưng chơi piano vô cùng xuất sắc."},{"cn":"这部电影讲述了一个少年追逐梦想的故事。","pinyin":"Zhè bù diànyǐng jiǎngshù le yí ge shàonián zhuīzhú mèngxiǎng de gùshi.","vn":"Bộ phim này kể câu chuyện về một thiếu niên theo đuổi ước mơ."},{"cn":"少年时期是培养良好学习习惯的重要阶段。","pinyin":"Shàonián shíqī shì péiyǎng liánghǎo xuéxí xíguàn de zhòngyào jiēduàn.","vn":"Thời niên thiếu là giai đoạn quan trọng để rèn luyện thói quen học tập tốt."}]},{"hanzi":"歌手","pinyin":"gēshǒu","pos":"dt.","vn":"ca sĩ","examples":[{"cn":"你最喜欢的中国流行歌手是谁？","pinyin":"Nǐ zuì xǐhuan de Zhōngguó liúxíng gēshǒu shì shéi?","vn":"Ca sĩ nhạc trẻ Trung Quốc mà bạn thích nhất là ai?"},{"cn":"这位年轻歌手的演唱会门票一分钟就卖光了。","pinyin":"Zhè wèi niánqīng gēshǒu de yǎnchànghuì ménpiào yì fēnzhōng jiù mài guāng le.","vn":"Vé đêm nhạc của ca sĩ trẻ này đã bán sạch chỉ trong một phút."},{"cn":"我的梦想是将来成为一名优秀的歌手。","pinyin":"Wǒ de mèngxiǎng shì jiānglái chéngwéi yì míng yōuxiù de gēshǒu.","vn":"Ước mơ của tôi là tương lai trở thành một ca sĩ xuất sắc."}]},{"hanzi":"歌声","pinyin":"gēshēng","pos":"dt.","vn":"tiếng hát, giọng hát","examples":[{"cn":"教室里传来孩子们快乐的歌声。","pinyin":"Jiàoshì lǐ chuánlái háizimen kuàilè de gēshēng.","vn":"Trong phòng học vang lên tiếng hát vui vẻ của lũ trẻ."},{"cn":"她的歌声非常温柔，让人听了觉得很放松。","pinyin":"Tā de gēshēng fēicháng wēnróu, ràng rén tīng le juéde hěn fàngsōng.","vn":"Giọng hát của cô ấy rất dịu dàng, khiến người nghe cảm thấy vô cùng thư giãn."},{"cn":"广场上到处都是大家的笑声和歌声。","pinyin":"Guǎngchǎng shang dàochù dōu shì dàjiā de xiàoshēng hé gēshēng.","vn":"Trên quảng trường đâu đâu cũng là tiếng cười và tiếng hát của mọi người."}]},{"hanzi":"度假","pinyin":"dùjià","pos":"dgt.","vn":"đi nghỉ mát, đi nghỉ dưỡng","examples":[{"cn":"今年夏天我们全家打算去海边度假。","pinyin":"Jīnnián xiàtiān wǒmen quánjiā dǎsuàn qù hǎibiān dùjià.","vn":"Mùa hè năm nay cả nhà tôi định đi biển nghỉ mát."},{"cn":"这里风景优美、气候宜人，是个度假的好地方。","pinyin":"Zhèlǐ fēngjǐng yōuměi, qìhòu yírén, shì ge dùjià de hǎo dìfang.","vn":"Nơi đây phong cảnh tươi đẹp, khí hậu dễ chịu, là một địa điểm nghỉ dưỡng tuyệt vời."},{"cn":"他在国外度假的时候拍了很多漂亮的照片。","pinyin":"Tā zài guówài dùjià de shíhou pāi le hěn duō piàoliang de zhàopiàn.","vn":"Lúc đi nghỉ dưỡng ở nước ngoài anh ấy đã chụp rất nhiều bức ảnh đẹp."}]},{"hanzi":"演员","pinyin":"yǎnyuán","pos":"dt.","vn":"diễn viên","examples":[{"cn":"这部电影里的每位演员都演得十分精彩。","pinyin":"Zhè bù diànyǐng lǐ de měi wèi yǎnyuán dōu yǎn de shífēn jīngcǎi.","vn":"Mỗi diễn viên trong bộ phim này đều diễn vô cùng xuất sắc."},{"cn":"演出结束后，演员们向观众深深鞠了一躬。","pinyin":"Yǎnchū jiéshù hòu, yǎnyuánmen xiàng guānzhòng shēnshēn jū le yì gōng.","vn":"Sau khi buổi diễn kết thúc, các diễn viên cúi chào khán giả thật sâu."},{"cn":"当一名专业的京剧演员需要多年的刻苦练习。","pinyin":"Dāng yì míng zhuānyè de Jīngjù yǎnyuán xūyào duō nián de kèkǔ liànxí.","vn":"Để trở thành một diễn viên Kinh kịch chuyên nghiệp cần nhiều năm khổ luyện."}]},{"hanzi":"演唱","pinyin":"yǎnchàng","pos":"dgt.","vn":"biểu diễn ca hát, hát","examples":[{"cn":"晚会上她为大家演唱了一首经典中文歌曲。","pinyin":"Wǎnhuì shang tā wèi dàjiā yǎnchàng le yì shǒu jīngdiǎn Zhōngwén gēqǔ.","vn":"Tại đêm liên hoan cô ấy đã biểu diễn một ca khúc tiếng Trung kinh điển cho mọi người."},{"cn":"这位京剧演员的演唱非常有感染力。","pinyin":"Zhè wèi Jīngjù yǎnyuán de yǎnchàng fēicháng yǒu gǎnrǎnlì.","vn":"Giọng hát biểu diễn của diễn viên Kinh kịch này rất có sức truyền cảm."},{"cn":"今天晚上将有十位歌手同台演唱。","pinyin":"Jīntiān wǎnshang jiāng yǒu shí wèi gēshǒu tóngtái yǎnchàng.","vn":"Tối nay sẽ có mười ca sĩ cùng biểu diễn trên một sân khấu."}]},{"hanzi":"留下","pinyin":"liúxia","pos":"dgt.","vn":"để lại, lưu lại","examples":[{"cn":"这次中国之行给我留下了非常美好的印象。","pinyin":"Zhè cì Zhōngguó zhī xíng gěi wǒ liúxia le fēicháng měihǎo de yìnxiàng.","vn":"Chuyến đi Trung Quốc lần này đã để lại cho tôi ấn tượng vô cùng tốt đẹp."},{"cn":"请您留下联系电话，方便我们之后通知您。","pinyin":"Qǐng nín liúxia liánxì diànhuà, fāngbiàn wǒmen zhīhòu tōngzhī nín.","vn":"Xin ngài để lại số điện thoại liên hệ để chúng tôi tiện thông báo sau."},{"cn":"爷爷给我们留下了许多珍贵的回忆。","pinyin":"Yéye gěi wǒmen liúxia le xǔduō zhēnguì de huíyì.","vn":"Ông nội đã để lại cho chúng tôi biết bao kỷ niệm quý giá."}]},{"hanzi":"青年","pinyin":"qīngnián","pos":"dt.","vn":"thanh niên","examples":[{"cn":"现在越来越多的青年人喜欢上了传统文化。","pinyin":"Xiànzài yuè lái yuè duō de qīngniánrén xǐhuan shàng le chuántǒng wénhuà.","vn":"Hiện nay ngày càng nhiều thanh niên yêu thích văn hóa truyền thống."},{"cn":"他是一位非常有才华的青年作家。","pinyin":"Tā shì yí wèi fēicháng yǒu cáihuá de qīngnián zuòjiā.","vn":"Anh ấy là một nhà văn trẻ rất có tài năng."},{"cn":"这场比赛主要面向全国各地的青年歌手。","pinyin":"Zhè chǎng bǐsài zhǔyào miànxiàng quánguó gèdì de qīngnián gēshǒu.","vn":"Cuộc thi này chủ yếu hướng tới các ca sĩ trẻ trên khắp cả nước."}]},{"hanzi":"观众","pinyin":"guānzhòng","pos":"dt.","vn":"khán giả","examples":[{"cn":"今天的演出非常精彩，台下的观众都看呆了。","pinyin":"Jīntiān de yǎnchū fēicháng jīngcǎi, táixià de guānzhòng dōu kàndāi le.","vn":"Buổi biểu diễn hôm nay vô cùng đặc sắc, khán giả bên dưới đều xem đến mê mẩn."},{"cn":"离演出开始还有半小时，观众们已经陆续入座了。","pinyin":"Lí yǎnchū kāishǐ hái yǒu bàn xiǎoshí, guānzhòngmen yǐjīng lùxù rùzuò le.","vn":"Còn nửa tiếng nữa mới bắt đầu diễn mà khán giả đã lục tục vào chỗ ngồi rồi."},{"cn":"演员们用真诚的表演打动了每一位观众。","pinyin":"Yǎnyuánmen yòng zhēnchéng de biǎoyǎn dǎdòng le měi yí wèi guānzhòng.","vn":"Các diễn viên đã làm lay động từng khán giả bằng màn trình diễn chân thành."}]},{"hanzi":"功课","pinyin":"gōngkè","pos":"dt.","vn":"sự chuẩn bị trước; bài tập, bài vở","examples":[{"cn":"去旅游之前，我们要提前做做功课，了解当地情况。","pinyin":"Qù lǚyóu zhīqián, wǒmen yào tíqián zuòzuo gōngkè, liǎojiě dāngdì qíngkuàng.","vn":"Trước khi đi du lịch, chúng ta cần tìm hiểu chuẩn bị trước về tình hình địa phương."},{"cn":"他每天放学回家后都会先认真完成功课。","pinyin":"Tā měitiān fàngxué huíjiā hòu dōu huì xiān rènzhēn wánchéng gōngkè.","vn":"Mỗi ngày tan học về nhà cậu ấy đều chăm chỉ làm xong bài vở trước."},{"cn":"为了通过这次面试，她做了很多功课。","pinyin":"Wèile tōngguò zhè cì miànshì, tā zuò le hěn duō gōngkè.","vn":"Để vượt qua buổi phỏng vấn lần này, cô ấy đã chuẩn bị rất kỹ lưỡng."}]},{"hanzi":"转发","pinyin":"zhuǎnfā","pos":"dgt.","vn":"chuyển tiếp, chia sẻ lại","examples":[{"cn":"这篇文章写得太好了，我马上转发给朋友们看看。","pinyin":"Zhè piān wénzhāng xiě de tài hǎo le, wǒ mǎshàng zhuǎnfā gěi péngyoumen kànkan.","vn":"Bài viết này hay quá, tôi chia sẻ ngay cho bạn bè cùng xem."},{"cn":"请把老师发的通知转发到班级群里。","pinyin":"Qǐng bǎ lǎoshī fā de tōngzhī zhuǎnfā dào bānjí qún lǐ.","vn":"Hãy chuyển tiếp thông báo thầy giáo gửi vào nhóm lớp nhé."},{"cn":"我查到演出时间后，立刻把信息转发给了你。","pinyin":"Wǒ chádào yǎnchū shíjiān hòu, lìkè bǎ xìnxī zhuǎnfā gěi le nǐ.","vn":"Sau khi tra được giờ diễn, tôi đã lập tức chuyển tiếp thông tin cho bạn rồi."}]},{"hanzi":"入口","pinyin":"rùkǒu","pos":"dt.","vn":"lối vào, cổng vào","examples":[{"cn":"咱们下午两点在公园的南门入口见面吧。","pinyin":"Zánmen xiàwǔ liǎng diǎn zài gōngyuán de nánmén rùkǒu jiànmiàn ba.","vn":"Hai giờ chiều chúng mình gặp nhau ở lối vào cổng nam công viên nhé."},{"cn":"地铁站入口处有很多人正在排队进站。","pinyin":"Dìtiězhàn rùkǒu chù yǒu hěn duō rén zhèngzài páiduì jìnzhàn.","vn":"Ở lối vào ga tàu điện ngầm có rất nhiều người đang xếp hàng vào ga."},{"cn":"请问一下，博物馆的入口往哪边走？","pinyin":"Qǐngwèn yíxià, bówùguǎn de rùkǒu wǎng nǎbiān zǒu?","vn":"Xin hỏi một chút, lối vào bảo tàng đi về phía nào ạ?"}]},{"hanzi":"国家大剧院","pinyin":"Guójiā Dàjùyuàn","pos":"danh từ riêng","vn":"Nhà hát Lớn Quốc gia (Trung Quốc)","examples":[{"cn":"国家大剧院的建筑外形非常有特色。","pinyin":"Guójiā Dàjùyuàn de jiànzhù wàixíng fēicháng yǒu tèsè.","vn":"Kiến trúc bên ngoài của Nhà hát Lớn Quốc gia vô cùng độc đáo."},{"cn":"下周六晚上我打算去国家大剧院听音乐会。","pinyin":"Xià zhōuliù wǎnshang wǒ dǎsuàn qù Guójiā Dàjùyuàn tīng yīnyuèhuì.","vn":"Tối thứ Bảy tuần sau tôi định đến Nhà hát Lớn Quốc gia nghe hòa nhạc."},{"cn":"很多世界著名的艺术团体都曾在国家大剧院演出。","pinyin":"Hěn duō shìjiè zhùmíng de yìshù tuántǐ dōu céng zài Guójiā Dàjùyuàn yǎnchū.","vn":"Rất nhiều đoàn nghệ thuật nổi tiếng thế giới từng biểu diễn tại Nhà hát Lớn Quốc gia."}]},{"hanzi":"京剧","pinyin":"Jīngjù","pos":"danh từ riêng","vn":"Kinh kịch","examples":[{"cn":"京剧是中国国粹之一，有着悠久的历史。","pinyin":"Jīngjù shì Zhōngguó guócuì zhī yī, yǒuzhe yōujiǔ de lìshǐ.","vn":"Kinh kịch là một trong những quốc túy của Trung Quốc, có lịch sử lâu đời."},{"cn":"虽然是第一次看京剧，但我觉得非常有意思。","pinyin":"Suīrán shì dì yī cì kàn Jīngjù, dàn wǒ juéde fēicháng yǒu yìsi.","vn":"Tuy là lần đầu tiên xem Kinh kịch, nhưng tôi thấy vô cùng thú vị."},{"cn":"爷爷非常喜欢听京剧，每天早上都要听一会儿。","pinyin":"Yéye fēicháng xǐhuan tīng Jīngjù, měitiān zǎoshang dōu yào tīng yíhuìr.","vn":"Ông nội rất thích nghe Kinh kịch, sáng nào cũng phải nghe một lúc."}]},{"hanzi":"梅兰芳","pinyin":"Méi Lánfāng","pos":"danh từ riêng","vn":"Mai Lan Phương","examples":[{"cn":"梅兰芳是中国家喻户晓的京剧表演艺术家。","pinyin":"Méi Lánfāng shì Zhōngguó jiāyùhùxiǎo de Jīngjù biǎoyǎn yìshùjiā.","vn":"Mai Lan Phương là nghệ sĩ biểu diễn Kinh kịch nổi tiếng khắp Trung Quốc."},{"cn":"我在网上看过梅兰芳先生演出的珍贵视频。","pinyin":"Wǒ zài wǎngshang kànguo Méi Lánfāng xiānsheng yǎnchū de zhēnguì shìpín.","vn":"Tôi đã xem những thước phim quý giá về buổi diễn của ngài Mai Lan Phương trên mạng."},{"cn":"北京有一座专门纪念梅兰芳先生的纪念馆。","pinyin":"Běijīng yǒu yí zuò zhuānmén jìniàn Méi Lánfāng xiānsheng de jìniànguǎn.","vn":"Ở Bắc Kinh có một nhà tưởng niệm dành riêng để tưởng nhớ ngài Mai Lan Phương."}]},{"hanzi":"入","pinyin":"rù","pos":"dgt.","vn":"vào, bước vào","examples":[{"cn":"演出马上就要开始了，请各位观众尽快入座。","pinyin":"Yǎnchū mǎshàng jiù yào kāishǐ le, qǐng gèwèi guānzhòng jǐnkuài rùzuò.","vn":"Buổi biểu diễn sắp bắt đầu rồi, xin mời quý khán giả nhanh chóng vào chỗ ngồi."},{"cn":"进入图书馆后，请大家把手机调成静音。","pinyin":"Jìnrù túshūguǎn hòu, qǐng dàjiā bǎ shǒujī tiáochéng jìngyīn.","vn":"Sau khi bước vào thư viện, xin mọi người chuyển điện thoại sang chế độ im lặng."},{"cn":"秋天一到，北方很多城市很快就入冬了。","pinyin":"Qiūtiān yí dào, běifāng hěn duō chéngshì hěn kuài jiù rùdōng le.","vn":"Mùa thu vừa qua, rất nhiều thành phố phương Bắc rất nhanh đã bước vào mùa đông."}]},{"hanzi":"指","pinyin":"zhǐ","pos":"dgt.","vn":"chỉ, trỏ","examples":[{"cn":"他指着地图上的北京，兴奋地说这是他最想去的城市。","pinyin":"Tā zhǐzhe dìtú shang de Běijīng, xīngfèn de shuō zhè shì tā zuì xiǎng qù de chéngshì.","vn":"Anh ấy chỉ vào Bắc Kinh trên bản đồ, hào hứng nói đây là thành phố anh muốn đến nhất."},{"cn":"姐姐指着橱窗里的裙子问我好不好看。","pinyin":"Jiějie zhǐzhe chúchuāng lǐ de qúnzi wèn wǒ hǎo bu hǎokàn.","vn":"Chị gái chỉ vào chiếc váy trong tủ kính hỏi tôi có đẹp không."},{"cn":"导游指着前方的古建筑向游客们作介绍。","pinyin":"Dǎoyóu zhǐzhe qiánfāng de gǔ jiànzhù xiàng yóukèmen zuò jièshào.","vn":"Hướng dẫn viên chỉ vào công trình kiến trúc cổ phía trước giới thiệu cho du khách."}]},{"hanzi":"功夫","pinyin":"gōngfu","pos":"dt.","vn":"công phu, kỹ năng, tay nghề","examples":[{"cn":"这些京剧演员的基本功非常扎实，功夫很深。","pinyin":"Zhèxiē Jīngjù yǎnyuán de jīběngōng fēicháng zhāshi, gōngfu hěn shēn.","vn":"Nền tảng cơ bản của những diễn viên Kinh kịch này rất vững chắc, công phu rất thâm hậu."},{"cn":"学好一门外语必须下一番苦功夫才行。","pinyin":"Xuéhǎo yì mén wàiyǔ bìxū xià yì fān kǔ gōngfu cái xíng.","vn":"Muốn học giỏi một ngoại ngữ nhất định phải bỏ công sức rèn luyện chăm chỉ."},{"cn":"很多外国朋友都非常喜欢看中国功夫电影。","pinyin":"Hěn duō wàiguó péngyou dōu fēicháng xǐhuan kàn Zhōngguó gōngfu diànyǐng.","vn":"Rất nhiều bạn bè nước ngoài đều vô cùng thích xem phim võ thuật công phu Trung Quốc."}]},{"hanzi":"获奖","pinyin":"huòjiǎng","pos":"dgt.","vn":"đoạt giải, giành giải thưởng","examples":[{"cn":"听说你的作品在摄影比赛中获奖了，恭喜你！","pinyin":"Tīngshuō nǐ de zuòpǐn zài shèyǐng bǐsài zhōng huòjiǎng le, gōngxǐ nǐ!","vn":"Nghe nói tác phẩm của bạn đã đoạt giải trong cuộc thi nhiếp ảnh rồi, chúc mừng bạn!"},{"cn":"这位青年演员曾在多个国际艺术节上获奖。","pinyin":"Zhè wèi qīngnián yǎnyuán céng zài duō ge guójì yìshùjié shang huòjiǎng.","vn":"Diễn viên trẻ này từng đoạt giải tại nhiều liên hoan nghệ thuật quốc tế."},{"cn":"所有获奖选手今天下午都要上台领奖。","pinyin":"Suǒyǒu huòjiǎng xuǎnshǒu jīntiān xiàwǔ dōu yào shàngtái lǐngjiǎng.","vn":"Tất cả các thí sinh đoạt giải chiều nay đều phải lên sân khấu nhận thưởng."}]},{"hanzi":"奖","pinyin":"jiǎng","pos":"dt.","vn":"giải thưởng, phần thưởng","examples":[{"cn":"他在今年的汉语演讲比赛中得了一等奖。","pinyin":"Tā zài jīnnián de Hànyǔ yǎnjiǎng bǐsài zhōng dé le yīděngjiǎng.","vn":"Anh ấy đã giành được giải nhất trong cuộc thi hùng biện tiếng Hán năm nay."},{"cn":"这部小说获得过国内最有影响力的文学大奖。","pinyin":"Zhè bù xiǎoshuō huòdé guo guónèi zuì yǒu yǐngxiǎnglì de wénxué dàjiǎng.","vn":"Cuốn tiểu thuyết này từng giành giải thưởng văn học có tầm ảnh hưởng nhất trong nước."},{"cn":"不管能不能拿奖，参加这次比赛本身就很有意义。","pinyin":"Bùguǎn néng bu néng ná jiǎng, cānjiā zhè cì bǐsài běnshēn jiù hěn yǒu yìyì.","vn":"Bất kể có giành được giải hay không, bản thân việc tham gia cuộc thi này đã rất có ý nghĩa rồi."}]},{"hanzi":"期待","pinyin":"qīdài","pos":"dgt.","vn":"mong đợi, kỳ vọng","examples":[{"cn":"我非常期待下个月和大家一起去旅行。","pinyin":"Wǒ fēicháng qīdài xià ge yuè hé dàjiā yìqǐ qù lǚyóu.","vn":"Tôi vô cùng mong đợi chuyến đi du lịch cùng mọi người vào tháng sau."},{"cn":"观众们都在期待这部新电影早日上映。","pinyin":"Guānzhòngmen dōu zài qīdài zhè bù xīn diànyǐng zǎorì shàngyìng.","vn":"Khán giả đều đang mong đợi bộ phim mới này sớm ra rạp."},{"cn":"父母对我的未来充满了期待，我一定会加倍努力。","pinyin":"Fùmǔ duì wǒ de wèilái chōngmǎn le qīdài, wǒ yídìng huì jiābèi nǔlì.","vn":"Bố mẹ đặt rất nhiều kỳ vọng vào tương lai của tôi, tôi nhất định sẽ nỗ lực gấp bội."}]},{"hanzi":"鼓掌","pinyin":"gǔzhǎng","pos":"dgt.","vn":"vỗ tay","examples":[{"cn":"她的精彩发言一结束，全场观众就热烈鼓掌。","pinyin":"Tā de jīngcǎi fāyán yì jiéshù, quánchǎng guānzhòng jiù rèliè gǔzhǎng.","vn":"Bài phát biểu xuất sắc của cô ấy vừa dứt, khán giả cả hội trường liền vỗ tay nhiệt liệt."},{"cn":"让我们一起鼓掌欢迎新同学的到来！","pinyin":"Ràng wǒmen yìqǐ gǔzhǎng huānyíng xīn tóngxué de dàolái!","vn":"Chúng ta hãy cùng vỗ tay chào đón sự có mặt của bạn học mới nào!"},{"cn":"看到演员完成高难度动作，大家忍不住不断鼓掌。","pinyin":"Kàndào yǎnyuán wánchéng gāo nándù dòngzuò, dàjiā rěnbuzhù búduàn gǔzhǎng.","vn":"Thấy diễn viên hoàn thành động tác độ khó cao, mọi người không kìm được liên tục vỗ tay."}]},{"hanzi":"邀请","pinyin":"yāoqǐng","pos":"dgt.","vn":"mời","examples":[{"cn":"感谢您邀请我们参加您的生日晚会。","pinyin":"Gǎnxiè nín yāoqǐng wǒmen cānjiā nín de shēngrì wǎnhuì.","vn":"Cảm ơn ngài đã mời chúng tôi tham dự tiệc sinh nhật của ngài."},{"cn":"学校邀请了一位著名作家来做讲座。","pinyin":"Xuéxiào yāoqǐng le yí wèi zhùmíng zuòjiā lái zuò jiǎngzuò.","vn":"Nhà trường đã mời một nhà văn nổi tiếng đến thuyết giảng."},{"cn":"她愉快地接受了朋友一起去看演出的邀请。","pinyin":"Tā yúkuài de jiēshòu le péngyou yìqǐ qù kàn yǎnchū de yāoqǐng.","vn":"Cô ấy vui vẻ nhận lời mời đi xem biểu diễn cùng bạn."}]},{"hanzi":"庆祝","pinyin":"qìngzhù","pos":"dgt.","vn":"chúc mừng, ăn mừng, kỷ niệm","examples":[{"cn":"项目顺利完成了，大家决定去吃顿大餐庆祝一下。","pinyin":"Xiàngmù shùnlì wánchéng le, dàjiā juédìng qù chī dùn dàcān qìngzhù yíxià.","vn":"Dự án đã hoàn thành suôn sẻ, mọi người quyết định đi ăn một bữa thịnh soạn để ăn mừng."},{"cn":"你平时过生日的时候都会怎么庆祝？","pinyin":"Nǐ píngshí guò shēngrì de shíhou dōu huì zěnme qìngzhù?","vn":"Bình thường đến sinh nhật bạn hay ăn mừng như thế nào?"},{"cn":"今天全校师生欢聚一堂，共同庆祝建校一百周年。","pinyin":"Jīntiān quánxiào shīshēng huānjù yìtáng, gòngtóng qìngzhù jiànxiào yìbǎi zhōunián.","vn":"Hôm nay thầy trò toàn trường sum họp một nhà, cùng nhau kỷ niệm 100 năm thành lập trường."}]},{"hanzi":"点头","pinyin":"diǎntóu","pos":"dgt.","vn":"gật đầu","examples":[{"cn":"听了我的解释以后，老师满意地点了点头。","pinyin":"Tīng le wǒ de jiěshì yǐhòu, lǎoshī mǎnyì de diǎn le diǎntóu.","vn":"Sau khi nghe tôi giải thích, cô giáo hài lòng gật đầu."},{"cn":"大多数国家用点头表示同意，但也有少数国家相反。","pinyin":"Dàduōshù guójiā yòng diǎntóu biǎoshì tóngyì, dàn yě yǒu shǎoshù guójiā xiāngfǎn.","vn":"Phần lớn các nước dùng cái gật đầu để biểu thị đồng ý, nhưng cũng có một số ít nước ngược lại."},{"cn":"在路上遇到认识的人时，大家通常会微笑点头打招呼。","pinyin":"Zài lùshang yùdào rènshi de rén shí, dàjiā tōngcháng huì wēixiào diǎntóu dǎ zhāohu.","vn":"Khi gặp người quen trên đường, mọi người thường mỉm cười gật đầu chào hỏi."}]},{"hanzi":"作品","pinyin":"zuòpǐn","pos":"dt.","vn":"tác phẩm","examples":[{"cn":"老舍先生一生创作了许多优秀的文学作品。","pinyin":"Lǎoshě xiānsheng yìshēng chuàngzuò le xǔduō yōuxiù de wénxué zuòpǐn.","vn":"Cả cuộc đời nhà văn Lão Xá đã sáng tác rất nhiều tác phẩm văn học xuất sắc."},{"cn":"这次展览展出了来自不同国家艺术家的绘画作品。","pinyin":"Zhè cì zhǎnlǎn zhǎnchū le láizì bùtóng guójiā yìshùjiā de huìhuà zuòpǐn.","vn":"Triển lãm lần này trưng bày các tác phẩm hội họa của nghệ sĩ đến từ nhiều quốc gia."},{"cn":"这部作品虽然不长，但内容十分感人。","pinyin":"Zhè bù zuòpǐn suīrán bù cháng, dàn nèiróng shífēn gǎnrén.","vn":"Tác phẩm này tuy không dài nhưng nội dung vô cùng cảm động."}]},{"hanzi":"作者","pinyin":"zuòzhě","pos":"dt.","vn":"tác giả","examples":[{"cn":"这本书太精彩了，你知道它的作者是谁吗？","pinyin":"Zhè běn shū tài jīngcǎi le, nǐ zhīdào tā de zuòzhě shì shéi ma?","vn":"Cuốn sách này hay quá, bạn có biết tác giả của nó là ai không?"},{"cn":"作者在文章里详细介绍了自己在中国的旅行经历。","pinyin":"Zuòzhě zài wénzhāng lǐ xiángxì jièshào le zìjǐ zài Zhōngguó de lǚxíng jīnglì.","vn":"Tác giả đã giới thiệu chi tiết trải nghiệm du lịch tại Trung Quốc của mình trong bài viết."},{"cn":"很多读者排队等着请作者在书上签名。","pinyin":"Hěn duō dúzhě páiduì děngzhe qǐng zuòzhě zài shū shang qiānmíng.","vn":"Rất nhiều độc giả xếp hàng chờ xin tác giả ký tên lên sách."}]},{"hanzi":"世纪","pinyin":"shìjì","pos":"dt.","vn":"thế kỷ","examples":[{"cn":"现在我们生活在充满机遇的二十一世纪。","pinyin":"Xiànzài wǒmen shēnghuó zài chōngmǎn jīyù de èrshíyī shìjì.","vn":"Hiện nay chúng ta đang sống trong thế kỷ 21 đầy ắp cơ hội."},{"cn":"这座古老的桥梁建于十六世纪，至今依然非常坚固。","pinyin":"Zhè zuò gǔlǎo de qiáoliáng jiàn yú shíliù shìjì, zhìjīn yīrán fēicháng jiāngù.","vn":"Cây cầu cổ này được xây dựng vào thế kỷ 16, đến nay vẫn vô cùng vững chắc."},{"cn":"近半个世纪以来，这座城市发生了翻天覆地的变化。","pinyin":"Jìn bàn ge shìjì yǐlái, zhè zuò chéngshì fāshēng le fāntiān-fùdì de biànhuà.","vn":"Gần nửa thế kỷ trở lại đây, thành phố này đã có những thay đổi long trời lở đất."}]},{"hanzi":"读者","pinyin":"dúzhě","pos":"dt.","vn":"độc giả, người đọc","examples":[{"cn":"这本新书一上市就受到了广大读者的欢迎。","pinyin":"Zhè běn xīnshū yí shàngshì jiù shòudào le guǎngdà dúzhě de huānyíng.","vn":"Cuốn sách mới này vừa ra mắt đã nhận được sự đón nhận của đông đảo độc giả."},{"cn":"作为一名忠实读者，我读过他写的所有小说。","pinyin":"Zuòwéi yì míng zhōngshí dúzhě, wǒ dúguo tā xiě de suǒyǒu xiǎoshuō.","vn":"Là một độc giả trung thành, tôi đã đọc tất cả các tiểu thuyết anh ấy viết."},{"cn":"图书馆每天都接待数以千计的读者。","pinyin":"Túshūguǎn měitiān dōu jiēdài shùyǐqiānjì de dúzhě.","vn":"Thư viện mỗi ngày đều đón tiếp hàng nghìn lượt độc giả."}]},{"hanzi":"作家","pinyin":"zuòjiā","pos":"dt.","vn":"nhà văn","examples":[{"cn":"她从小热爱阅读和写作，梦想将来成为一名作家。","pinyin":"Tā cóngxiǎo rè'ài yuèdú hé xiězuò, mèngxiǎng jiānglái chéngwéi yì míng zuòjiā.","vn":"Cô ấy từ nhỏ đã say mê đọc sách và viết lách, ước mơ tương lai trở thành một nhà văn."},{"cn":"这位著名作家的新作品今年冬天就要出版了。","pinyin":"Zhè wèi zhùmíng zuòjiā de xīn zuòpǐn jīnnián dōngtiān jiù yào chūbǎn le.","vn":"Tác phẩm mới của nhà văn nổi tiếng này mùa đông năm nay sẽ xuất bản."},{"cn":"我最喜欢的作家擅长用简单的文字写出动人的故事。","pinyin":"Wǒ zuì xǐhuan de zuòjiā shàncháng yòng jiǎndān de wénzì xiěchū dòngrén de gùshi.","vn":"Nhà văn tôi thích nhất giỏi dùng câu chữ giản dị để viết nên những câu chuyện lay động lòng người."}]},{"hanzi":"版","pinyin":"bǎn","pos":"dt.","vn":"phiên bản, ấn bản","examples":[{"cn":"我在书店买了一本最新版的汉越词典。","pinyin":"Wǒ zài shūdiàn mǎi le yì běn zuìxīnbǎn de Hàn-Yuè cídiǎn.","vn":"Tôi đã mua một cuốn từ điển Hán-Việt phiên bản mới nhất ở hiệu sách."},{"cn":"这本书既有纸质版，也有方便携带的电子版。","pinyin":"Zhè běn shū jì yǒu zhǐzhìbǎn, yě yǒu fāngbiàn xiédài de diànzǐbǎn.","vn":"Cuốn sách này vừa có bản in giấy, vừa có bản điện tử tiện mang theo."},{"cn":"她先读了英文版，后来又找来中文版仔细看了一遍。","pinyin":"Tā xiān dú le Yīngwénbǎn, hòulái yòu zhǎolái Zhōngwénbǎn zǐxì kàn le yí biàn.","vn":"Cô ấy đọc bản tiếng Anh trước, sau đó lại tìm bản tiếng Trung đọc kỹ thêm một lượt."}]},{"hanzi":"文章","pinyin":"wénzhāng","pos":"dt.","vn":"bài viết, bài văn","examples":[{"cn":"这篇文章观点清晰，语言也很生动。","pinyin":"Zhè piān wénzhāng guāndiǎn qīngxī, yǔyán yě hěn shēngdòng.","vn":"Bài viết này quan điểm rõ ràng, ngôn từ cũng rất sinh động."},{"cn":"老师要求我们这周用中文写一篇关于旅行的文章。","pinyin":"Lǎoshī yāoqiú wǒmen zhè zhōu yòng Zhōngwén xiě yì piān guānyú lǚxíng de wénzhāng.","vn":"Thầy giáo yêu cầu tuần này chúng tôi viết một bài văn bằng tiếng Trung về du lịch."},{"cn":"她经常在网上发表自己写的文章，分享学习经验。","pinyin":"Tā jīngcháng zài wǎngshang fābiǎo zìjǐ xiě de wénzhāng, fēnxiǎng xuéxí jīngyàn.","vn":"Cô ấy thường xuyên đăng tải các bài viết của mình lên mạng để chia sẻ kinh nghiệm học tập."}]},{"hanzi":"全部","pinyin":"quánbù","pos":"dt.","vn":"toàn bộ, tất cả","examples":[{"cn":"我已经把今天的作业全部做完了。","pinyin":"Wǒ yǐjīng bǎ jīntiān de zuòyè quánbù zuòwán le.","vn":"Tôi đã làm xong toàn bộ bài tập hôm nay rồi."},{"cn":"为了这次演出，大家付出了全部的心血和努力。","pinyin":"Wèile zhè cì yǎnchū, dàjiā fùchū le quánbù de xīnxuè hé nǔlì.","vn":"Vì buổi biểu diễn lần này, mọi người đã dồn toàn bộ tâm huyết và nỗ lực."},{"cn":"这并不是故事的全部，后面还有更精彩的内容。","pinyin":"Zhè bìng bú shì gùshi de quánbù, hòumiàn hái yǒu gèng jīngcǎi de nèiróng.","vn":"Đây hoàn toàn không phải toàn bộ câu chuyện, phía sau còn có nội dung đặc sắc hơn nữa."}]},{"hanzi":"整理","pinyin":"zhěnglǐ","pos":"dgt.","vn":"chỉnh lý, sắp xếp lại","examples":[{"cn":"每次上完课，我都会把笔记重新整理一遍。","pinyin":"Měi cì shàngwán kè, wǒ dōu huì bǎ bǐjì chóngxīn zhěnglǐ yí biàn.","vn":"Mỗi lần học xong, tôi đều sắp xếp lại ghi chép một lượt."},{"cn":"出发前请把需要带的证件和行李整理好。","pinyin":"Chūfā qián qǐng bǎ xūyào dài de zhèngjiàn hé xíngli zhěnglǐ hǎo.","vn":"Trước khi xuất phát hãy sắp xếp gọn gàng giấy tờ và hành lý cần mang theo."},{"cn":"她花了一个周末把电脑里的照片全部整理好了。","pinyin":"Tā huā le yí ge zhōumò bǎ diànnǎo lǐ de zhàopiàn quánbù zhěnglǐ hǎo le.","vn":"Cô ấy mất một ngày cuối tuần để sắp xếp lại toàn bộ ảnh trong máy tính."}]},{"hanzi":"文字","pinyin":"wénzì","pos":"dt.","vn":"văn tự, chữ viết, câu chữ","examples":[{"cn":"汉字是世界上历史最悠久的文字之一。","pinyin":"Hànzì shì shìjiè shang lìshǐ zuì yōujiǔ de wénzì zhī yī.","vn":"Chữ Hán là một trong những hệ thống văn tự có lịch sử lâu đời nhất thế giới."},{"cn":"她写的散文文字优美，读起来非常舒服。","pinyin":"Tā xiě de sǎnwén wénzì yōuměi, dú qǐlai fēicháng shūfu.","vn":"Tản văn cô ấy viết câu chữ đẹp đẽ, đọc lên rất dễ chịu."},{"cn":"有些美好的感受很难用文字完全表达出来。","pinyin":"Yǒuxiē měihǎo de gǎnshòu hěn nán yòng wénzì wánquán biǎodá chūlái.","vn":"Có những cảm xúc tươi đẹp rất khó dùng câu chữ để diễn tả trọn vẹn."}]},{"hanzi":"图片","pinyin":"túpiàn","pos":"dt.","vn":"hình ảnh, tranh ảnh","examples":[{"cn":"这本书里配了很多精美的图片，看起来非常直观。","pinyin":"Zhè běn shū lǐ pèi le hěn duō jīngměi de túpiàn, kàn qǐlai fēicháng zhíguān.","vn":"Trong cuốn sách này có kèm rất nhiều hình ảnh tinh xảo, nhìn rất trực quan."},{"cn":"你能把刚才发的那几张图片传给我吗？","pinyin":"Nǐ néng bǎ gāngcái fā de nà jǐ zhāng túpiàn chuán gěi wǒ ma?","vn":"Bạn có thể gửi mấy tấm hình vừa đăng cho tôi được không?"},{"cn":"做演示文稿时加上合适的图片，效果会更好。","pinyin":"Zuò yǎnshì wéngǎo shí jiāshàng héshì de túpiàn, xiàoguǒ huì gèng hǎo.","vn":"Khi làm bài thuyết trình mà thêm hình ảnh phù hợp thì hiệu quả sẽ tốt hơn."}]},{"hanzi":"报考","pinyin":"bàokǎo","pos":"dgt.","vn":"đăng ký dự thi","examples":[{"cn":"今年我打算报考北京大学的研究生。","pinyin":"Jīnnián wǒ dǎsuàn bàokǎo Běijīng Dàxué de yánjiūshēng.","vn":"Năm nay tôi dự định đăng ký dự thi cao học Đại học Bắc Kinh."},{"cn":"你已经想好大学要报考什么专业了吗？","pinyin":"Nǐ yǐjīng xiǎnghǎo dàxué yào bàokǎo shénme zhuānyè le ma?","vn":"Bạn đã nghĩ kỹ sẽ đăng ký thi chuyên ngành nào ở đại học chưa?"},{"cn":"每年都有很多外国学生报考汉语水平考试。","pinyin":"Měinián dōu yǒu hěn duō wàiguó xuésheng bàokǎo Hànyǔ Shuǐpíng Kǎoshì.","vn":"Mỗi năm đều có rất nhiều học sinh nước ngoài đăng ký dự thi kỳ thi năng lực Hán ngữ."}]},{"hanzi":"文学","pinyin":"wénxué","pos":"dt.","vn":"văn học","examples":[{"cn":"她大学主修的是中国语言文学专业。","pinyin":"Tā dàxué zhǔxiū de shì Zhōngguó yǔyán wénxué zhuānyè.","vn":"Chuyên ngành chính ở đại học của cô ấy là Ngôn ngữ và Văn học Trung Quốc."},{"cn":"多读世界文学名著可以开阔我们的眼界。","pinyin":"Duō dú shìjiè wénxué míngzhù kěyǐ kāikuò wǒmen de yǎnjiè.","vn":"Đọc nhiều tác phẩm văn học kinh điển thế giới có thể mở rộng tầm mắt của chúng ta."},{"cn":"他对古典文学有着非常浓厚的兴趣。","pinyin":"Tā duì gǔdiǎn wénxué yǒuzhe fēicháng nónghòu de xìngqù.","vn":"Anh ấy có niềm đam mê rất sâu sắc đối với văn học cổ điển."}]},{"hanzi":"马可·波罗","pinyin":"Mǎkě·Bōluó","pos":"danh từ riêng","vn":"Marco Polo","examples":[{"cn":"马可·波罗是一位著名的意大利旅行家。","pinyin":"Mǎkě·Bōluó shì yí wèi zhùmíng de Yìdàlì lǚxíngjiā.","vn":"Marco Polo là một nhà du hành nổi tiếng người Ý."},{"cn":"十三世纪时，马可·波罗随家人来到中国生活了很多年。","pinyin":"Shísān shìjì shí, Mǎkě·Bōluó suí jiārén láidào Zhōngguó shēnghuó le hěn duō nián.","vn":"Vào thế kỷ 13, Marco Polo đã cùng gia đình đến Trung Quốc sinh sống nhiều năm."},{"cn":"马可·波罗为促进东西方文化交流做出了重要贡献。","pinyin":"Mǎkě·Bōluó wèi cùjìn dōngxīfāng wénhuà jiāoliú zuòchū le zhòngyào gòngxiàn.","vn":"Marco Polo đã có đóng góp quan trọng trong việc thúc đẩy giao lưu văn hóa Đông - Tây."}]},{"hanzi":"意大利","pinyin":"Yìdàlì","pos":"danh từ riêng","vn":"Ý (Italia)","examples":[{"cn":"意大利以美食、历史建筑和艺术闻名世界。","pinyin":"Yìdàlì yǐ měishí, lìshǐ jiànzhù hé yìshù wénmíng shìjiè.","vn":"Nước Ý nổi tiếng thế giới với ẩm thực, kiến trúc lịch sử và nghệ thuật."},{"cn":"我的朋友明年要去意大利留学，学习服装设计。","pinyin":"Wǒ de péngyou míngnián yào qù Yìdàlì liúxué, xuéxí fúzhuāng shèjì.","vn":"Bạn tôi năm sau sẽ sang Ý du học ngành thiết kế thời trang."},{"cn":"周末我们去那家新开的意大利餐厅吃比萨吧。","pinyin":"Zhōumò wǒmen qù nà jiā xīnkāi de Yìdàlì cāntīng chī bǐsà ba.","vn":"Cuối tuần chúng ta đi ăn pizza ở nhà hàng Ý mới mở kia nhé."}]},{"hanzi":"马可·波罗游记","pinyin":"Mǎkě·Bōluó Yóujì","pos":"danh từ riêng","vn":"Marco Polo du ký","examples":[{"cn":"《马可·波罗游记》让当时的欧洲人第一次认识了中国。","pinyin":"«Mǎkě·Bōluó Yóujì» ràng dāngshí de Ōuzhōurén dì yī cì rènshi le Zhōngguó.","vn":"«Marco Polo du ký» đã giúp người châu Âu thời bấy giờ lần đầu tiên biết đến Trung Quốc."},{"cn":"我在图书馆借了一本中文版的《马可·波罗游记》。","pinyin":"Wǒ zài túshūguǎn jiè le yì běn Zhōngwénbǎn de «Mǎkě·Bōluó Yóujì».","vn":"Tôi đã mượn một cuốn «Marco Polo du ký» bản tiếng Trung ở thư viện."},{"cn":"读完《马可·波罗游记》后，我对历史和旅行更感兴趣了。","pinyin":"Dúwán «Mǎkě·Bōluó Yóujì» hòu, wǒ duì lìshǐ hé lǚxíng gèng gǎn xìngqù le.","vn":"Sau khi đọc xong «Marco Polo du ký», tôi càng hứng thú hơn với lịch sử và du lịch."}]},{"hanzi":"东方旅行日记","pinyin":"Dōngfāng Lǚxíng Rìjì","pos":"danh từ riêng","vn":"Nhật ký du hành phương Đông","examples":[{"cn":"白家月打算把自己的游记整理成一部《东方旅行日记》。","pinyin":"Bái Jiāyuè dǎsuàn bǎ zìjǐ de yóujì zhěnglǐ chéng yí bù «Dōngfāng Lǚxíng Rìjì».","vn":"Bạch Gia Nguyệt dự định chỉnh lý các bài du ký của mình thành một tác phẩm mang tên «Nhật ký du hành phương Đông»."},{"cn":"《东方旅行日记》里有精彩的文字，也有她拍的许多图片。","pinyin":"«Dōngfāng Lǚxíng Rìjì» lǐ yǒu jīngcǎi de wénzì, yě yǒu tā pāi de xǔduō túpiàn.","vn":"Trong «Nhật ký du hành phương Đông» vừa có câu chữ đặc sắc, vừa có nhiều bức ảnh do cô ấy chụp."},{"cn":"同学们都很期待早点儿读到她写的《东方旅行日记》。","pinyin":"Tóngxuémen dōu hěn qīdài zǎodiǎnr dúdào tā xiě de «Dōngfāng Lǚxíng Rìjì».","vn":"Các bạn học đều rất mong sớm được đọc cuốn «Nhật ký du hành phương Đông» do cô ấy viết."}]}],"grammar":[{"title":"选择复句\"不是……，就是……\"","explanation_vn":"Câu phức lựa chọn \"不是……，就是……\" (không phải... thì là...) biểu thị quan hệ lựa chọn, có nghĩa là chọn một trong hai tình huống hoặc khả năng.","examples":[{"cn":"有时候不是忘词，就是忘记做动作。","pinyin":"Yǒu shíhou bú shì wàngcí, jiù shì wàngjì zuò dòngzuò.","vn":"Có lúc không phải quên lời thì cũng là quên làm động tác."},{"cn":"周末的时候，小文不是在家看书，就是出去看演出。","pinyin":"Zhōumò de shíhou, Xiǎowén bú shì zài jiā kànshū, jiù shì chūqù kàn yǎnchū.","vn":"Vào cuối tuần, Tiểu Văn không phải ở nhà đọc sách thì cũng là ra ngoài xem biểu diễn."},{"cn":"杨同乐最近很忙，不是去外地出差，就是在公司加班。","pinyin":"Yáng Tónglè zuìjìn hěn máng, bú shì qù wàidì chūchāi, jiù shì zài gōngsī jiābān.","vn":"Dương Đồng Lạc gần đây rất bận, không phải đi công tác ở nơi khác thì cũng là tăng ca ở công ty."}]},{"title":"固定格式\"动词+一×是一×\"","explanation_vn":"Cấu trúc cố định \"动词+一×是一×\" (động từ + một × là một ×) nhấn mạnh việc cố gắng làm hết sức mình trong một điều kiện nhất định.","examples":[{"cn":"咱们先做做功课，提前了解下，能懂一点儿是一点儿。","pinyin":"Zánmen xiān zuòzuo gōngkè, tíqián liǎojiě xià, néng dǒng yìdiǎnr shì yìdiǎnr.","vn":"Chúng mình chuẩn bị trước một chút, tìm hiểu trước đi, hiểu được chút nào hay chút nấy."},{"cn":"虽然这本书很厚，但是我还是要看，看一页是一页，最后一定能看完。","pinyin":"Suīrán zhè běn shū hěn hòu, dànshì wǒ háishì yào kàn, kàn yí yè shì yí yè, zuìhòu yídìng néng kànwán.","vn":"Tuy cuốn sách này rất dày, nhưng tôi vẫn sẽ đọc, đọc được trang nào hay trang nấy, cuối cùng chắc chắn sẽ đọc xong."},{"cn":"你能多吃一点儿是一点儿，这样身体才能好起来。","pinyin":"Nǐ néng duō chī yìdiǎnr shì yìdiǎnr, zhèyàng shēntǐ cái néng hǎo qǐlái.","vn":"Bạn ăn thêm được chút nào hay chút nấy, như vậy sức khỏe mới có thể khá lên được."}]},{"title":"\"把\"字句\"主语+把+宾语+动词+动量补语\"","explanation_vn":"\"Chủ ngữ + 把 + Tân ngữ + Động từ + Bổ ngữ động lượng\" là một dạng câu chữ \"把\", nhấn mạnh số lần hoặc tần suất động tác tác động lên tân ngữ. \"Bổ ngữ động lượng\" là kết cấu \"số từ + động lượng từ\", đứng sau động từ để làm bổ ngữ.","examples":[{"cn":"因为李文他们提前把故事了解了一遍，所以差不多都看懂了。","pinyin":"Yīnwèi Lǐ Wén tāmen tíqián bǎ gùshi liǎojiě le yí biàn, suǒyǐ chàbuduō dōu kàndǒng le.","vn":"Vì Lý Văn và mọi người đã tìm hiểu trước câu chuyện một lượt nên hầu như đều xem hiểu cả."},{"cn":"他把这个动作做了好几次，最后终于做对了。","pinyin":"Tā bǎ zhège dòngzuò zuò le hǎo jǐ cì, zuìhòu zhōngyú zuòduì le.","vn":"Anh ấy đã làm động tác này mấy lần liền, cuối cùng cũng làm đúng rồi."},{"cn":"白家月又把这本书看了几遍，越看越喜欢。","pinyin":"Bái Jiāyuè yòu bǎ zhè běn shū kànle jǐ biàn, yuè kàn yuè xǐhuan.","vn":"Bạch Gia Nguyệt lại đọc cuốn sách này thêm mấy lượt nữa, càng đọc càng thích."}]},{"title":"\"把\"字句\"主语+把+宾语+动词+时量补语\"","explanation_vn":"\"Chủ ngữ + 把 + Tân ngữ + Động từ + Bổ ngữ thời lượng\" là một dạng câu chữ \"把\", nhấn mạnh độ dài thời gian duy trì động tác mà chủ ngữ tác động lên tân ngữ. Các từ ngữ biểu thị khoảng thời gian dài ngắn khi làm bổ ngữ được gọi là \"bổ ngữ thời lượng\".","examples":[{"cn":"（我）到家后又把这本书看了两天。","pinyin":"(Wǒ) dào jiā hòu yòu bǎ zhè běn shū kànle liǎng tiān.","vn":"(Tôi) về đến nhà lại đọc cuốn sách này thêm hai ngày nữa."},{"cn":"王老师把这个问题又讲了十分钟，大家才明白。","pinyin":"Wáng lǎoshī bǎ zhège wèntí yòu jiǎng le shí fēnzhōng, dàjiā cái míngbai.","vn":"Cô Vương giảng lại vấn đề này thêm mười phút nữa mọi người mới hiểu."},{"cn":"陈天中把这个动作又练了一小时。","pinyin":"Chén Tiānzhōng bǎ zhège dòngzuò yòu liàn le yì xiǎoshí.","vn":"Trần Thiên Trung lại tập động tác này thêm một tiếng đồng hồ nữa."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"王一雪","cn":"小雪，你们的话剧排好了吗？","pinyin":"Xiǎoxuě, nǐmen de huàjù páihǎo le ma?"},{"speaker":"刘小雪","cn":"差不多了，妈妈。艺术节周五下午开始，我内心还是有些紧张，有时候不是忘词，就是忘记做动作。","pinyin":"Chàbuduō le, māma. Yìshùjié zhōuwǔ xiàwǔ kāishǐ, wǒ nèixīn háishì yǒuxiē jǐnzhāng, yǒu shíhou bú shì wàngcí, jiù shì wàngjì zuò dòngzuò."},{"speaker":"王一雪","cn":"没事，妈妈相信你一定可以。放松些，再自信些！","pinyin":"Méishì, māma xiāngxìn nǐ yídìng kěyǐ. Fàngsōng xiē, zài zìxìn xiē!"},{"speaker":"刘小雪","cn":"好的，我同学演少年歌手，他的歌声美极了。我演他的妈妈，不知道像不像呢。","pinyin":"Hǎo de, wǒ tóngxué yǎn shàonián gēshǒu, tā de gēshēng měi jíle. Wǒ yǎn tā de māma, bù zhīdào xiàng bu xiàng ne."},{"speaker":"王一雪","cn":"没问题的，努力做最好的自己就好。演出时，我和你爸都去给你加油。","pinyin":"Méi wèntí de, nǔlì zuò zuì hǎo de zìjǐ jiù hǎo. Yǎnchū shí, wǒ hé nǐ bà dōu qù gěi nǐ jiāyóu."},{"speaker":"刘小雪","cn":"好的，谢谢妈妈！","pinyin":"Hǎo de, xièxie māma!"}],"translation_vn":"Vương Nhất Tuyết: Tiểu Tuyết, vở kịch nói của các con tập xong chưa?\nLưu Tiểu Tuyết: Gần xong rồi ạ, mẹ ơi. Lễ hội nghệ thuật bắt đầu vào chiều thứ Sáu, trong lòng con vẫn hơi căng thẳng, có lúc không phải quên lời thì cũng là quên làm động tác.\nVương Nhất Tuyết: Không sao đâu, mẹ tin con nhất định làm được. Thả lỏng chút đi, tự tin thêm chút nữa nhé!\nLưu Tiểu Tuyết: Vâng ạ, bạn con đóng vai ca sĩ thiếu niên, giọng hát của bạn ấy hay tuyệt vời. Con đóng vai mẹ của bạn ấy, không biết có giống không nữa.\nVương Nhất Tuyết: Không vấn đề gì đâu, cố gắng làm phiên bản tốt nhất của chính mình là được rồi. Lúc biểu diễn, mẹ và bố đều sẽ đến cổ vũ cho con.\nLưu Tiểu Tuyết: Vâng ạ, con cảm ơn mẹ!","audio_dialogue":"19-1.mp3","audio_vocab":"19-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"李文","cn":"下周六晚上，我请大家去国家大剧院看京剧，怎么样？","pinyin":"Xià zhōuliù wǎnshang, wǒ qǐng dàjiā qù Guójiā Dàjùyuàn kàn Jīngjù, zěnmeyàng?"},{"speaker":"安妮","cn":"好啊。我小时候在加拿大度假时，在宾馆的电视上看过一次，是梅兰芳等演员演的，演员们都非常棒，他们演唱得好听极了，给我留下的印象特别深。","pinyin":"Hǎo a. Wǒ xiǎoshíhou zài Jiānádà dùjià shí, zài bīnguǎn de diànshì shàng kànguo yí cì, shì Méi Lánfāng děng yǎnyuán yǎn de, yǎnyuánmen dōu fēicháng bàng, tāmen yǎnchàng de hǎotīng jíle, gěi wǒ liúxia de yìnxiàng tèbié shēn."},{"speaker":"李文","cn":"梅兰芳先生是中国著名京剧艺术家。咱们要看的这个京剧是青年演员们演的，要去看的观众也特别多。","pinyin":"Méi Lánfāng xiānsheng shì Zhōngguó zhùmíng Jīngjù yìshùjiā. Zánmen yào kàn de zhège Jīngjù shì qīngnián yǎnyuánmen yǎn de, yào qù kàn de guānzhòng yě tèbié duō."},{"speaker":"陈天中","cn":"不知道我们能不能看懂。","pinyin":"Bù zhīdào wǒmen néng bu néng kàndǒng."},{"speaker":"白家月","cn":"咱们先做做功课，提前了解下，能懂一点儿是一点儿。","pinyin":"Zánmen xiān zuòzuo gōngkè, tíqián liǎojiě xià, néng dǒng yìdiǎnr shì yìdiǎnr."},{"speaker":"陈天中","cn":"对，我先去网上查资料，查完后也转发给你们。","pinyin":"Duì, wǒ xiān qù wǎngshàng chá zīliào, cháwán hòu yě zhuǎnfā gěi nǐmen."},{"speaker":"安妮","cn":"谢谢天中！","pinyin":"Xièxie Tiānzhōng!"},{"speaker":"李文","cn":"那我就在网上订票了，到时候咱们在大剧院入口见。","pinyin":"Nà wǒ jiù zài wǎngshàng dìngpiào le, dào shíhou zánmen zài Dàjùyuàn rùkǒu jiàn."}],"translation_vn":"Lý Văn: Tối thứ Bảy tuần sau, mình mời mọi người đến Nhà hát Lớn Quốc gia xem Kinh kịch, được không?\nAnnie: Được quá đi chứ. Hồi nhỏ đi nghỉ mát ở Canada, mình từng xem một lần trên tivi khách sạn, do các nghệ sĩ như Mai Lan Phương biểu diễn, các diễn viên đều rất tuyệt, họ hát hay vô cùng, để lại cho mình ấn tượng đặc biệt sâu sắc.\nLý Văn: Ngài Mai Lan Phương là nghệ sĩ Kinh kịch nổi tiếng của Trung Quốc. Vở Kinh kịch chúng mình sắp xem là do các diễn viên trẻ biểu diễn, khán giả muốn đi xem cũng đông lắm.\nTrần Thiên Trung: Không biết chúng mình có xem hiểu được không.\nBạch Gia Nguyệt: Chúng mình cứ tìm hiểu chuẩn bị trước một chút, hiểu được chút nào hay chút nấy.\nTrần Thiên Trung: Đúng rồi, mình lên mạng tra tài liệu trước, tra xong sẽ chuyển tiếp cho các cậu nhé.\nAnnie: Cảm ơn Thiên Trung!\nLý Văn: Vậy mình đặt vé trên mạng đây, đến lúc đó chúng mình gặp nhau ở lối vào Nhà hát Lớn nhé.","audio_dialogue":"19-3.mp3","audio_vocab":"19-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"周六晚上，李文等四人来到国家大剧院观看京剧演出。入座后，李文指着节目表说：“这些演员很专业，功夫很深，在京剧比赛中获过很多奖，有的还是国家、国际大奖。我特别期待这场演出。”","pinyin":"Zhōuliù wǎnshang, Lǐ Wén děng sì rén láidào Guójiā Dàjùyuàn guānkàn Jīngjù yǎnchū. Rùzuò hòu, Lǐ Wén zhǐzhe jiémùbiǎo shuō: “Zhèxiē yǎnyuán hěn zhuānyè, gōngfu hěn shēn, zài Jīngjù bǐsài zhōng huòguo hěn duō jiǎng, yǒude háishì guójiā, guójì dàjiǎng. Wǒ tèbié qīdài zhè chǎng yǎnchū.”"},{"speaker":"","cn":"演出开始后，他们看到演员们做的动作很难，但是做得都特别好，观众们不断鼓掌。因为李文他们提前把故事了解了一遍，所以差不多都看懂了。演出结束后，演员们邀请观众和他们一起庆祝演出成功。","pinyin":"Yǎnchū kāishǐ hòu, tāmen kàndào yǎnyuánmen zuò de dòngzuò hěn nán, dànshì zuò de dōu tèbié hǎo, guānzhòngmen búduàn gǔzhǎng. Yīnwèi Lǐ Wén tāmen tíqián bǎ gùshi liǎojiě le yí biàn, suǒyǐ chàbuduō dōu kàndǒng le. Yǎnchū jiéshù hòu, yǎnyuánmen yāoqǐng guānzhòng hé tāmen yìqǐ qìngzhù yǎnchū chénggōng."},{"speaker":"","cn":"回来的路上，大家特别激动，觉得京剧很有意思，演员演得很精彩。李文点头说：“是啊，以后咱们还来看。”","pinyin":"Huílái de lùshang, dàjiā tèbié jīdòng, juéde Jīngjù hěn yǒu yìsi, yǎnyuán yǎn de hěn jīngcǎi. Lǐ Wén diǎntóu shuō: “Shì a, yǐhòu zánmen hái lái kàn.”"}],"translation_vn":"Tối thứ Bảy, bốn người Lý Văn đến Nhà hát Lớn Quốc gia xem biểu diễn Kinh kịch. Sau khi vào chỗ ngồi, Lý Văn chỉ vào tờ chương trình nói: \"Những diễn viên này rất chuyên nghiệp, công phu rất thâm hậu, từng đoạt rất nhiều giải thưởng trong các cuộc thi Kinh kịch, có người còn đoạt giải lớn cấp quốc gia và quốc tế nữa. Mình đặc biệt mong đợi buổi diễn này.\"\nSau khi buổi diễn bắt đầu, họ thấy các động tác diễn viên thực hiện rất khó nhưng đều làm cực kỳ xuất sắc, khán giả vỗ tay không ngớt. Vì nhóm Lý Văn đã tìm hiểu trước câu chuyện một lượt nên hầu như đều xem hiểu cả. Sau khi buổi diễn kết thúc, các diễn viên mời khán giả cùng họ ăn mừng buổi biểu diễn thành công.\nTrên đường về, mọi người vô cùng phấn khích, cảm thấy Kinh kịch rất thú vị, diễn viên diễn rất đặc sắc. Lý Văn gật đầu nói: \"Đúng vậy, sau này chúng mình lại đến xem nữa nhé.\"","audio_dialogue":"19-5.mp3","audio_vocab":"19-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"马可·波罗是意大利旅行家，在1275年和家人来到中国，在中国大约生活了17年，最后完成了一部作品——《马可·波罗游记》。在这部影响很大的作品中，作者向世界介绍了13世纪时的中国。","pinyin":"Mǎkě · Bōluó shì Yìdàlì lǚxíngjiā, zài yī èr qī wǔ nián hé jiārén láidào Zhōngguó, zài Zhōngguó dàyuē shēnghuó le shíqī nián, zuìhòu wánchéng le yí bù zuòpǐn — 《Mǎkě · Bōluó Yóujì》. Zài zhè bù yǐngxiǎng hěn dà de zuòpǐn zhōng, zuòzhě xiàng shìjiè jièshào le shísān shìjì shí de Zhōngguó."},{"speaker":"","cn":"作为读者，读完这部作品后，我也很想成为作家，更想来中国看看。来到中国后，我发现现在的中国和书里的中国已有很大不同。","pinyin":"Zuòwéi dúzhě, dúwán zhè bù zuòpǐn hòu, wǒ yě hěn xiǎng chéngwéi zuòjiā, gèng xiǎng lái Zhōngguó kànkan. Láidào Zhōngguó hòu, wǒ fāxiàn xiànzài de Zhōngguó hé shū lǐ de Zhōngguó yǐ yǒu hěn dà bùtóng."},{"speaker":"","cn":"前两天，我去书店看到了中文版的《马可·波罗游记》，马上买了一本，到家后又把这本书看了两天。看完后，我决定把自己来中国后写的文章、日记等全部整理出来，完成一部文字加图片的作品——《东方旅行日记》，再次把中国介绍给世界。同时我也想继续学习中文和中国文化，报考中国语言文学专业的研究生。","pinyin":"Qián liǎng tiān, wǒ qù shūdiàn kàndàole Zhōngwén bǎn de 《Mǎkě · Bōluó Yóujì》, mǎshàng mǎi le yì běn, dào jiā hòu yòu bǎ zhè běn shū kànle liǎng tiān. Kànwán hòu, wǒ juédìng bǎ zìjǐ lái Zhōngguó hòu xiě de wénzhāng, rìjì děng quánbù zhěnglǐ chūlái, wánchéng yí bù wénzì jiā túpiàn de zuòpǐn — 《Dōngfāng Lǚxíng Rìjì》, zàicì bǎ Zhōngguó jièshào gěi shìjiè. Tóngshí wǒ yě xiǎng jìxù xuéxí Zhōngwén hé Zhōngguó wénhuà, bàokǎo Zhōngguó yǔyán wénxué zhuānyè de yánjiūshēng."}],"translation_vn":"Marco Polo là nhà du hành người Ý, ông cùng gia đình đến Trung Quốc vào năm 1275, sống ở Trung Quốc khoảng 17 năm và cuối cùng hoàn thành một tác phẩm — «Marco Polo du ký». Trong tác phẩm có tầm ảnh hưởng lớn này, tác giả đã giới thiệu với thế giới về Trung Quốc vào thế kỷ 13.\nLà một độc giả, sau khi đọc xong tác phẩm này, mình cũng rất muốn trở thành nhà văn, và càng muốn đến Trung Quốc tham quan. Sau khi đến Trung Quốc, mình phát hiện Trung Quốc hiện nay đã khác rất nhiều so với Trung Quốc trong sách.\nMấy hôm trước, mình đi hiệu sách thấy cuốn «Marco Polo du ký» bản tiếng Trung, liền mua ngay một cuốn, về đến nhà lại đọc cuốn sách này thêm hai ngày nữa. Đọc xong, mình quyết định chỉnh lý toàn bộ các bài viết, nhật ký mà mình viết từ khi đến Trung Quốc để hoàn thành một tác phẩm kết hợp câu chữ và hình ảnh — «Nhật ký du hành phương Đông», một lần nữa giới thiệu Trung Quốc ra thế giới. Đồng thời mình cũng muốn tiếp tục học tiếng Trung và văn hóa Trung Quốc, đăng ký dự thi cao học chuyên ngành Ngôn ngữ và Văn học Trung Quốc.","audio_dialogue":"19-7.mp3","audio_vocab":"19-8.mp3"}]},{"id":20,"title_cn":"看不完也读不完","title_pinyin":"Kàn bu wán yě dú bu wán","title_vn":"Xem không hết mà đọc cũng chẳng xong","goals":["Có thể nghe hiểu và trao đổi các chủ đề về đọc sách và du lịch.","Có thể trình bày bằng lời nói hoặc văn bản đặc sắc của một danh lam thắng cảnh nào đó.","Hiểu cách đi du lịch tại Trung Quốc và trải nghiệm văn hóa Trung Quốc."],"vocab":[{"hanzi":"堵车","pinyin":"dǔchē","pos":"dgt.","vn":"tắc đường, kẹt xe","examples":[{"cn":"早晚高峰的时候，市中心的道路经常堵车。","pinyin":"Zǎowǎn gāofēng de shíhou, shìzhōngxīn de dàolù jīngcháng dǔchē.","vn":"Vào giờ cao điểm sáng tối, đường sá trung tâm thành phố thường xuyên tắc đường."},{"cn":"对不起，刚才路上堵车，所以我来晚了一会儿。","pinyin":"Duìbuqǐ, gāngcái lùshang dǔchē, suǒyǐ wǒ láiwǎn le yíhuìr.","vn":"Xin lỗi, vừa nãy trên đường bị kẹt xe nên tôi đến muộn một chút."},{"cn":"为了避免堵车，我们决定坐地铁去机场。","pinyin":"Wèile bìmiǎn dǔchē, wǒmen juédìng zuò dìtiě qù jīchǎng.","vn":"Để tránh tắc đường, chúng tôi quyết định đi tàu điện ngầm ra sân bay."}]},{"hanzi":"乘","pinyin":"chéng","pos":"dgt.","vn":"đi (tàu, xe, máy bay), ngồi","examples":[{"cn":"明天早上我们将乘动车去杭州旅游。","pinyin":"Míngtiān zǎoshang wǒmen jiāng chéng dòngchē qù Hángzhōu lǚyóu.","vn":"Sáng mai chúng tôi sẽ đi tàu cao tốc đến Hàng Châu du lịch."},{"cn":"如果赶不上这趟车，我们可以改乘下一趟。","pinyin":"Rúguǒ gǎnbushàng zhè tàng chē, wǒmen kěyǐ gǎichéng xià yí tàng.","vn":"Nếu không kịp chuyến xe này, chúng ta có thể đổi sang đi chuyến tiếp theo."},{"cn":"请各位乘客有序排队，文明乘车。","pinyin":"Qǐng gèwèi chéngkè yǒuxù páiduì, wénmíng chéngchē.","vn":"Xin quý hành khách xếp hàng trật tự, lên xe văn minh."}]},{"hanzi":"难道","pinyin":"nándào","pos":"phó.","vn":"lẽ nào, chẳng lẽ","examples":[{"cn":"这么简单的道理，难道你还不懂吗？","pinyin":"Zhème jiǎndān de dàolǐ, nándào nǐ hái bù dǒng ma?","vn":"Đạo lý đơn giản như vậy, chẳng lẽ bạn vẫn không hiểu sao?"},{"cn":"已经九点了，难道他忘记今天要开会了吗？","pinyin":"Yǐjīng jiǔ diǎn le, nándào tā wàngjì jīntiān yào kāihuì le ma?","vn":"Đã chín giờ rồi, lẽ nào anh ấy quên hôm nay phải họp sao?"},{"cn":"难道你不觉得这里的夜景非常迷人吗？","pinyin":"Nándào nǐ bù juéde zhèlǐ de yèjǐng fēicháng mírén ma?","vn":"Chẳng lẽ bạn không thấy cảnh đêm ở đây vô cùng quyến rũ sao?"}]},{"hanzi":"无","pinyin":"wú","pos":"dgt.","vn":"không có, vô","examples":[{"cn":"春运期间车票很难买，他只好买了一张无座票。","pinyin":"Chūnyùn qījiān chēpiào hěn nán mǎi, tā zhǐhǎo mǎi le yì zhāng wúzuòpiào.","vn":"Dịp cao điểm Tết vé tàu rất khó mua, anh ấy đành mua một tấm vé không chỗ ngồi."},{"cn":"这篇文章写得非常好，几乎挑不出任何毛病，堪称无懈可击。","pinyin":"Zhè piān wénzhāng xiě de fēicháng hǎo, jīhū tiāobuchū rènhé máobìng, kānchēng wúxiè-kějī.","vn":"Bài viết này viết rất hay, hầu như không tìm ra bất kỳ lỗi nào, có thể nói là hoàn hảo không tì vết."},{"cn":"不管有钱无钱，一家人健康快乐才是最重要的。","pinyin":"Bùguǎn yǒuqián wúqián, yìjiārén jiànkāng kuàilè cái shì zuì zhòngyào de.","vn":"Bất kể có tiền hay không có tiền, cả nhà khỏe mạnh vui vẻ mới là điều quan trọng nhất."}]},{"hanzi":"动车","pinyin":"dòngchē","pos":"dt.","vn":"tàu cao tốc (tàu động lực phân tán)","examples":[{"cn":"坐动车从北京到天津只需要半个小时左右。","pinyin":"Zuò dòngchē cóng Běijīng dào Tiānjīn zhǐ xūyào bàn ge xiǎoshí zuǒyòu.","vn":"Đi tàu cao tốc từ Bắc Kinh đến Thiên Tân chỉ cần khoảng nửa tiếng đồng hồ."},{"cn":"动车里面非常干净宽敞，坐起来很舒服。","pinyin":"Dòngchē lǐmiàn fēicháng gānjìng kuānchang, zuò qǐlai hěn shūfu.","vn":"Bên trong tàu cao tốc rất sạch sẽ rộng rãi, ngồi vô cùng thoải mái."},{"cn":"现在在中国旅行，乘坐动车既快捷又方便。","pinyin":"Xiànzài zài Zhōngguó lǚxíng, chéngzuò dòngchē jì kuàijié yòu fāngbiàn.","vn":"Hiện nay đi du lịch ở Trung Quốc, đi tàu cao tốc vừa nhanh chóng vừa tiện lợi."}]},{"hanzi":"车速","pinyin":"chēsù","pos":"dt.","vn":"tốc độ xe (tàu)","examples":[{"cn":"下雨天路面很滑，开车时一定要降低车速。","pinyin":"Xiàyǔtiān lùmiàn hěn huá, kāichē shí yídìng yào jiàngdī chēsù.","vn":"Trời mưa mặt đường rất trơn, khi lái xe nhất định phải giảm tốc độ."},{"cn":"这列动车的车速非常快，但行驶得依然很平稳。","pinyin":"Zhè liè dòngchē de chēsù fēicháng kuài, dàn xíngshǐ de yīrán hěn píngwěn.","vn":"Tốc độ của đoàn tàu cao tốc này rất nhanh nhưng chạy vẫn vô cùng êm ái."},{"cn":"经过学校门口时，司机都应该放慢车速。","pinyin":"Jīngguò xuéxiào ménkǒu shí, sījī dōu yīnggāi fàngmàn chēsù.","vn":"Khi đi qua cổng trường học, tài xế đều nên giảm tốc độ xe."}]},{"hanzi":"列","pinyin":"liè","pos":"lượng.","vn":"chuyến, đoàn (dùng cho tàu hỏa, hàng loạt sự vật)","examples":[{"cn":"一列动车正缓缓驶进车站。","pinyin":"Yí liè dòngchē zhèng huǎnhuǎn shǐjìn chēzhàn.","vn":"Một đoàn tàu cao tốc đang từ từ tiến vào nhà ga."},{"cn":"这列车开往上海，中途停靠三个站。","pinyin":"Zhè liè chē kāiwǎng Shànghǎi, zhōngtú tíngkào sān ge zhàn.","vn":"Chuyến tàu này chạy đi Thượng Hải, dọc đường dừng ở ba ga."},{"cn":"每天有几十列火车从这座城市经过。","pinyin":"Měitiān yǒu jǐshí liè huǒchē cóng zhè zuò chéngshì jīngguò.","vn":"Mỗi ngày có mấy chục đoàn tàu hỏa đi qua thành phố này."}]},{"hanzi":"晚餐","pinyin":"wǎncān","pos":"dt.","vn":"bữa tối","examples":[{"cn":"今天晚上我亲自下厨，为大家准备一顿丰盛的晚餐。","pinyin":"Jīntiān wǎnshang wǒ qīnzì xiàchú, wèi dàjiā zhǔnbèi yí dùn fēngshèng de wǎncān.","vn":"Tối nay tôi tự tay vào bếp, chuẩn bị một bữa tối thịnh soạn cho mọi người."},{"cn":"医生建议晚餐不要吃得太油腻，也不要吃得太晚。","pinyin":"Yīshēng jiànyì wǎncān búyào chī de tài yóunì, yě búyào chī de tài wǎn.","vn":"Bác sĩ khuyên bữa tối không nên ăn quá dầu mỡ và cũng không nên ăn quá muộn."},{"cn":"在动车上可以提前用手机预订晚餐。","pinyin":"Zài dòngchē shang kěyǐ tíqián yòng shǒujī yùdìng wǎncān.","vn":"Trên tàu cao tốc có thể dùng điện thoại đặt bữa tối trước."}]},{"hanzi":"夜","pinyin":"yè","pos":"dt./lượng.","vn":"đêm, ban đêm","examples":[{"cn":"夏天的夜里，微风吹来非常凉爽。","pinyin":"Xiàtiān de yèlǐ, wēifēng chuīlái fēicháng liángshuǎng.","vn":"Vào ban đêm mùa hè, gió nhẹ thổi qua vô cùng mát mẻ."},{"cn":"为了准备明天的汇报，他昨晚熬了一整夜。","pinyin":"Wèile zhǔnbèi míngtiān de huìbào, tā zuówǎn áo le yì zhěng yè.","vn":"Để chuẩn bị cho buổi báo cáo ngày mai, tối qua anh ấy đã thức trắng cả một đêm."},{"cn":"夜深了，街道上渐渐安静了下来。","pinyin":"Yè shēn le, jiēdào shang jiànjiàn ānjìng le xiàlái.","vn":"Đêm đã khuya, đường phố dần dần trở nên yên tĩnh."}]},{"hanzi":"大巴","pinyin":"dàbā","pos":"dt.","vn":"xe buýt đường dài, xe khách lớn","examples":[{"cn":"机场外面有直接开往市中心的机场大巴。","pinyin":"Jīchǎng wàimiàn yǒu zhíjiē kāiwǎng shìzhōngxīn de jīchǎng dàbā.","vn":"Bên ngoài sân bay có xe buýt sân bay chạy thẳng về trung tâm thành phố."},{"cn":"我们全班同学明天坐旅游大巴去郊区春游。","pinyin":"Wǒmen quánbān tóngxué míngtiān zuò lǚyóu dàbā qù jiāoqū chūnyóu.","vn":"Cả lớp chúng tôi ngày mai sẽ đi xe khách du lịch ra ngoại ô dã ngoại mùa xuân."},{"cn":"从杭州坐大巴去苏州大约需要两个小时。","pinyin":"Cóng Hángzhōu zuò dàbā qù Sūzhōu dàyuē xūyào liǎng ge xiǎoshí.","vn":"Đi xe khách từ Hàng Châu đến Tô Châu mất khoảng hai tiếng đồng hồ."}]},{"hanzi":"杭州","pinyin":"Hángzhōu","pos":"danh từ riêng","vn":"Hàng Châu","examples":[{"cn":"中国有句古话叫“上有天堂，下有苏杭”，其中的“杭”就是杭州。","pinyin":"Zhōngguó yǒu jù gǔhuà jiào \"shàng yǒu tiāntáng, xià yǒu Sū-Háng\", qízhōng de \"Háng\" jiù shì Hángzhōu.","vn":"Trung Quốc có câu cổ ngữ \"Trên có thiên đường, dưới có Tô Hàng\", chữ \"Hàng\" trong đó chính là Hàng Châu."},{"cn":"杭州的春天百花盛开，非常适合旅游。","pinyin":"Hángzhōu de chūntiān bǎihuā shèngkāi, fēicháng shìhé lǚyóu.","vn":"Mùa xuân ở Hàng Châu trăm hoa đua nở, vô cùng thích hợp để du lịch."},{"cn":"去杭州旅行时，一定要尝尝当地的龙井茶。","pinyin":"Qù Hángzhōu lǚxíng shí, yídìng yào chángchang dāngdì de Lóngjǐngchá.","vn":"Khi đi du lịch Hàng Châu, nhất định phải nếm thử trà Long Tỉnh của địa phương."}]},{"hanzi":"西湖","pinyin":"Xī Hú","pos":"danh từ riêng","vn":"Tây Hồ","examples":[{"cn":"西湖的风景一年四季都美如画卷。","pinyin":"Xī Hú de fēngjǐng yìnián-sìjì dōu měi rú huàjuàn.","vn":"Phong cảnh Tây Hồ bốn mùa quanh năm đều đẹp như một bức tranh."},{"cn":"傍晚沿着西湖边散步是一件特别惬意的事。","pinyin":"Bàngwǎn yánzhe Xī Hú biān sànbù shì yí jiàn tèbié qièyì de shì.","vn":"Chiều tối tản bộ dọc bờ Tây Hồ là một việc vô cùng thư thái."},{"cn":"关于西湖，中国历史上流传着许多动人的传说和诗词。","pinyin":"Guānyú Xī Hú, Zhōngguó lìshǐ shang liúchuán zhe xǔduō dòngrén de chuánshuō hé shīcí.","vn":"Về Tây Hồ, trong lịch sử Trung Quốc lưu truyền rất nhiều truyền thuyết và thơ từ cảm động."}]},{"hanzi":"苏州","pinyin":"Sūzhōu","pos":"danh từ riêng","vn":"Tô Châu","examples":[{"cn":"苏州是一座有着两千多年历史的文化名城。","pinyin":"Sūzhōu shì yí zuò yǒuzhe liǎngqiān duō nián lìshǐ de wénhuà míngchéng.","vn":"Tô Châu là một thành phố văn hóa nổi tiếng có hơn hai nghìn năm lịch sử."},{"cn":"苏州离上海很近，坐高铁不到半小时就能到。","pinyin":"Sūzhōu lí Shànghǎi hěn jìn, zuò gāotiě bú dào bàn xiǎoshí jiù néng dào.","vn":"Tô Châu cách Thượng Hải rất gần, đi tàu cao tốc chưa tới nửa tiếng là đến nơi."},{"cn":"小桥流水是苏州古城最有代表性的景象。","pinyin":"Xiǎoqiáo liúshuǐ shì Sūzhōu gǔchéng zuì yǒu dàibiǎoxìng de jǐngxiàng.","vn":"Cầu nhỏ nước chảy là hình ảnh tiêu biểu nhất của cổ thành Tô Châu."}]},{"hanzi":"苏州园林","pinyin":"Sūzhōu Yuánlín","pos":"danh từ riêng","vn":"Viên lâm Tô Châu (Lâm viên Tô Châu)","examples":[{"cn":"苏州园林以其精巧的建筑设计闻名天下。","pinyin":"Sūzhōu Yuánlín yǐ qí jīngqiǎo de jiànzhù shèjì wénmíng tiānxià.","vn":"Viên lâm Tô Châu nổi tiếng khắp thiên hạ nhờ thiết kế kiến trúc tinh xảo."},{"cn":"这次去苏州，我们一共参观了三座著名的苏州园林。","pinyin":"Zhè cì qù Sūzhōu, wǒmen yígòng cānguān le sān zuò zhùmíng de Sūzhōu Yuánlín.","vn":"Lần này đi Tô Châu, chúng tôi đã tham quan tổng cộng ba khu Viên lâm Tô Châu nổi tiếng."},{"cn":"走在苏州园林里，一步一景，让人流连忘返。","pinyin":"Zǒu zài Sūzhōu Yuánlín lǐ, yíbù-yìjǐng, ràng rén liúlián-wàngfǎn.","vn":"Đi dạo trong Viên lâm Tô Châu, mỗi bước một cảnh đẹp, khiến người ta lưu luyến không muốn rời."}]},{"hanzi":"安检","pinyin":"ānjiǎn","pos":"dgt.","vn":"kiểm tra an ninh","examples":[{"cn":"节假日机场人很多，排队安检可能需要较长时间。","pinyin":"Jiéjiàrì jīchǎng rén hěn duō, páiduì ānjiǎn kěnéng xūyào jiào cháng shíjiān.","vn":"Ngày lễ tết sân bay rất đông người, xếp hàng kiểm tra an ninh có thể tốn khá nhiều thời gian."},{"cn":"过安检的时候，请把电脑和液体从包里拿出来。","pinyin":"Guò ānjiǎn de shíhou, qǐng bǎ diànnǎo hé yètǐ cóng bāo lǐ náchūlái.","vn":"Khi qua cửa kiểm tra an ninh, vui lòng lấy máy tính và chất lỏng ra khỏi túi."},{"cn":"在中国坐地铁进站之前也都需要先安检。","pinyin":"Zài Zhōngguó zuò dìtiě jìnzhàn zhīqián yě dōu xūyào xiān ānjiǎn.","vn":"Ở Trung Quốc trước khi vào ga đi tàu điện ngầm cũng đều cần kiểm tra an ninh trước."}]},{"hanzi":"登机","pinyin":"dēngjī","pos":"dgt.","vn":"lên máy bay","examples":[{"cn":"我们的航班将在四十分钟后开始登机。","pinyin":"Wǒmen de hángbān jiāng zài sìshí fēnzhōng hòu kāishǐ dēngjī.","vn":"Chuyến bay của chúng tôi sẽ bắt đầu cho hành khách lên máy bay sau bốn mươi phút nữa."},{"cn":"请前往西安的旅客在十二号登机口排队登机。","pinyin":"Qǐng qiánwǎng Xī'ān de lǚkè zài shí'èr hào dēngjīkǒu páiduì dēngjī.","vn":"Xin mời hành khách đi Tây An xếp hàng lên máy bay tại cửa số 12."},{"cn":"办完手续后，大家坐在候机室里一边聊天一边等着登机。","pinyin":"Bànwán shǒuxù hòu, dàjiā zuò zài hòujīshì lǐ yìbiān liáotiān yìbiān děngzhe dēngjī.","vn":"Sau khi làm xong thủ tục, mọi người ngồi trong phòng chờ vừa trò chuyện vừa đợi lên máy bay."}]},{"hanzi":"小说","pinyin":"xiǎoshuō","pos":"dt.","vn":"tiểu thuyết","examples":[{"cn":"我最近在读一本非常精彩的中国现代小说。","pinyin":"Wǒ zuìjìn zài dú yì běn fēicháng jīngcǎi de Zhōngguó xiàndài xiǎoshuō.","vn":"Gần đây tôi đang đọc một cuốn tiểu thuyết hiện đại Trung Quốc vô cùng hấp dẫn."},{"cn":"这部电影是根据一本畅销小说改编而成的。","pinyin":"Zhè bù diànyǐng shì gēnjù yì běn chàngxiāo xiǎoshuō gǎibiān ér chéng de.","vn":"Bộ phim này được chuyển thể từ một cuốn tiểu thuyết bán chạy."},{"cn":"坐长途火车时看小说是打发时间的好办法。","pinyin":"Zuò chángtú huǒchē shí kàn xiǎoshuō shì dǎfa shíjiān de hǎo bànfǎ.","vn":"Đọc tiểu thuyết khi đi tàu hỏa đường dài là cách giết thời gian rất hay."}]},{"hanzi":"航班","pinyin":"hángbān","pos":"dt.","vn":"chuyến bay","examples":[{"cn":"因为天气原因，今天上午的几个航班都晚点了。","pinyin":"Yīnwèi tiānqì yuányīn, jīntiān shàngwǔ de jǐ ge hángbān dōu wǎndiǎn le.","vn":"Vì lý do thời tiết, mấy chuyến bay sáng nay đều bị trễ giờ."},{"cn":"请问您乘坐的是哪一趟航班？","pinyin":"Qǐngwèn nín chéngzuò de shì nǎ yí tàng hángbān?","vn":"Xin hỏi ngài đi chuyến bay nào ạ?"},{"cn":"从北京到昆明的直飞航班每天有很多班。","pinyin":"Cóng Běijīng dào Kūnmíng de zhífēi hángbān měitiān yǒu hěn duō bān.","vn":"Chuyến bay thẳng từ Bắc Kinh đến Côn Minh mỗi ngày có rất nhiều chuyến."}]},{"hanzi":"值机","pinyin":"zhíjī","pos":"dgt.","vn":"làm thủ tục lên máy bay (check-in)","examples":[{"cn":"现在很多航空公司都支持提前在网上办理值机。","pinyin":"Xiànzài hěn duō hángkōng gōngsī dōu zhīchí tíqián zài wǎngshang bànlǐ zhíjī.","vn":"Hiện nay nhiều hãng hàng không đều hỗ trợ làm thủ tục check-in trực tuyến trước."},{"cn":"国际航班一般需要提前两到三个小时到机场值机。","pinyin":"Guójì hángbān yìbān xūyào tíqián liǎng dào sān ge xiǎoshí dào jīchǎng zhíjī.","vn":"Các chuyến bay quốc tế thường cần đến sân bay làm thủ tục trước hai đến ba tiếng."},{"cn":"值机柜台的工作人员非常热情地帮我选了靠窗的座位。","pinyin":"Zhíjī guìtái de gōngzuò rényuán fēicháng rèqíng de bāng wǒ xuǎn le kàochuāng de zuòwèi.","vn":"Nhân viên quầy làm thủ tục rất nhiệt tình giúp tôi chọn chỗ ngồi gần cửa sổ."}]},{"hanzi":"旅客","pinyin":"lǚkè","pos":"dt.","vn":"hành khách, du khách","examples":[{"cn":"请各位旅客保管好自己的随身物品和证件。","pinyin":"Qǐng gèwèi lǚkè bǎoguǎn hǎo zìjǐ de suíshēn wùpǐn hé zhèngjiàn.","vn":"Xin quý hành khách bảo quản cẩn thận đồ đạc mang theo người và giấy tờ."},{"cn":"每年国庆假期，全国各地的火车站都会迎来大量旅客。","pinyin":"Měinián Guóqìng jiàqī, quánguó gèdì de huǒchēzhàn dōu huì yínglái dàliàng lǚkè.","vn":"Mỗi dịp nghỉ lễ Quốc khánh hằng năm, các nhà ga trên toàn quốc đều đón lượng lớn hành khách."},{"cn":"航空公司为延误航班的旅客安排了免费的休息酒店。","pinyin":"Hángkōng gōngsī wèi yánwù hángbān de lǚkè ānpái le miǎnfèi de xiūxi jiǔdiàn.","vn":"Hãng hàng không đã sắp xếp khách sạn nghỉ ngơi miễn phí cho hành khách bị hoãn chuyến bay."}]},{"hanzi":"牌","pinyin":"pái","pos":"dt.","vn":"thẻ, bảng, biển","examples":[{"cn":"登机时请提前准备好护照和登机牌。","pinyin":"Dēngjī shí qǐng tíqián zhǔnbèi hǎo hùzhào hé dēngjīpái.","vn":"Khi lên máy bay xin vui lòng chuẩn bị sẵn hộ chiếu và thẻ lên máy bay."},{"cn":"路边立着一块写有景点方向的指示牌。","pinyin":"Lùbiān lìzhe yí kuài xiěyǒu jǐngdiǎn fāngxiàng de zhǐshìpái.","vn":"Bên đường có dựng một tấm biển chỉ dẫn hướng đi đến danh lam thắng cảnh."},{"cn":"公园草坪旁边的牌子上写着“请勿踩踏草坪”。","pinyin":"Gōngyuán cǎopíng pángbiān de páizi shang xiězhe \"qǐng wù cǎità cǎopíng\".","vn":"Trên tấm biển bên cạnh bãi cỏ công viên có viết \"Vui lòng không giẫm lên cỏ\"."}]},{"hanzi":"靠","pinyin":"kào","pos":"dgt.","vn":"gần, sát cạnh; tựa vào, dựa vào","examples":[{"cn":"坐飞机的时候，我最喜欢选靠窗户的座位。","pinyin":"Zuò fēijī de shíhou, wǒ zuì xǐhuan xuǎn kào chuānghu de zuòwèi.","vn":"Khi đi máy bay, tôi thích nhất là chọn chỗ ngồi sát cửa sổ."},{"cn":"他走累了，便靠在树干上休息了一会儿。","pinyin":"Tā zǒulèi le, biàn kào zài shùgàn shang xiūxi le yíhuìr.","vn":"Anh ấy đi bộ mệt rồi, liền tựa vào thân cây nghỉ ngơi một lát."},{"cn":"在电梯里请大家自觉靠右站立，方便赶时间的人通过。","pinyin":"Zài diàntī lǐ qǐng dàjiā zìjué kào yòu zhànlì, fāngbiàn gǎn shíjiān de rén tōngguò.","vn":"Trên thang cuốn xin mọi người tự giác đứng sát bên phải để người vội đi qua."}]},{"hanzi":"窗户","pinyin":"chuānghu","pos":"dt.","vn":"cửa sổ","examples":[{"cn":"屋里有点儿闷，麻烦你把窗户打开透透气吧。","pinyin":"Wūlǐ yǒudiǎnr mēn, máfan nǐ bǎ chuānghu dǎkāi tòutouqì ba.","vn":"Trong phòng hơi ngột ngạt, phiền bạn mở cửa sổ ra cho thoáng khí nhé."},{"cn":"透过飞机的窗户，我看到了洁白的云海。","pinyin":"Tòuguò fēijī de chuānghu, wǒ kàndào le jiébái de yúnhǎi.","vn":"Qua khung cửa sổ máy bay, tôi nhìn thấy biển mây trắng tinh khôi."},{"cn":"离开房间之前别忘了把门和窗户都关好。","pinyin":"Líkāi fángjiān zhīqián bié wàng le bǎ mén hé chuānghu dōu guānhǎo.","vn":"Trước khi rời khỏi phòng đừng quên đóng kỹ cả cửa ra vào và cửa sổ."}]},{"hanzi":"转机","pinyin":"zhuǎnjī","pos":"dgt.","vn":"chuyển máy bay, quá cảnh","examples":[{"cn":"这次飞欧洲没有直飞航班，我们需要在迪拜转机。","pinyin":"Zhè cì fēi Ōuzhōu méiyǒu zhífēi hángbān, wǒmen xūyào zài Díbài zhuǎnjī.","vn":"Lần này bay đi châu Âu không có chuyến bay thẳng, chúng tôi cần quá cảnh ở Dubai."},{"cn":"虽然转机要多花几个小时，但机票价格便宜了很多。","pinyin":"Suīrán zhuǎnjī yào duō huā jǐ ge xiǎoshí, dàn jīpiào jiàgé piányi le hěn duō.","vn":"Tuy chuyển máy bay mất thêm vài tiếng đồng hồ nhưng giá vé máy bay rẻ hơn rất nhiều."},{"cn":"订转机机票时，最好留出足够的时间以免误机。","pinyin":"Dìng zhuǎnjī jīpiào shí, zuìhǎo liúchū zúgòu de shíjiān yǐmiǎn wùjī.","vn":"Khi đặt vé nối chuyến, tốt nhất nên chừa đủ thời gian để tránh lỡ chuyến bay."}]},{"hanzi":"老舍","pinyin":"Lǎoshě","pos":"danh từ riêng","vn":"Lão Xá (nhà văn nổi tiếng Trung Quốc)","examples":[{"cn":"老舍是中国现代文学史上非常著名的作家。","pinyin":"Lǎoshě shì Zhōngguó xiàndài wénxuéshǐ shang fēicháng zhùmíng de zuòjiā.","vn":"Lão Xá là nhà văn vô cùng nổi tiếng trong lịch sử văn học hiện đại Trung Quốc."},{"cn":"《骆驼祥子》和《茶馆》都是老舍先生的代表作。","pinyin":"«Luòtuo Xiángzi» hé «Cháguǎn» dōu shì Lǎoshě xiānsheng de dàibiǎozuò.","vn":"«Lạc đà Tường Tử» và «Quán trà» đều là những tác phẩm tiêu biểu của nhà văn Lão Xá."},{"cn":"老舍的作品语言生动幽默，充满了老北京的味道。","pinyin":"Lǎoshě de zuòpǐn yǔyán shēngdòng yōumò, chōngmǎn le lǎo Běijīng de wèidào.","vn":"Ngôn ngữ trong tác phẩm của Lão Xá sinh động hài hước, đậm chất Bắc Kinh xưa."}]},{"hanzi":"唐诗","pinyin":"Tángshī","pos":"danh từ riêng","vn":"Thơ Đường","examples":[{"cn":"很多中国孩子从小就会背诵几十首唐诗。","pinyin":"Hěn duō Zhōngguó háizi cóngxiǎo jiù huì bèisòng jǐshí shǒu Tángshī.","vn":"Rất nhiều trẻ em Trung Quốc từ nhỏ đã biết thuộc lòng mấy chục bài thơ Đường."},{"cn":"李白和杜甫是唐诗历史上最伟大的两位诗人。","pinyin":"Lǐ Bái hé Dù Fǔ shì Tángshī lìshǐ shang zuì wěidà de liǎng wèi shīrén.","vn":"Lý Bạch và Đỗ Phủ là hai nhà thơ vĩ đại nhất trong lịch sử thơ Đường."},{"cn":"通过阅读唐诗，我们可以领略古人的情感与智慧。","pinyin":"Tōngguò yuèdú Tángshī, wǒmen kěyǐ lǐnglüè gǔrén de qínggǎn yǔ zhìhuì.","vn":"Thông qua việc đọc thơ Đường, chúng ta có thể cảm nhận được tình cảm và trí tuệ của người xưa."}]},{"hanzi":"泼水节","pinyin":"Pōshuǐjié","pos":"danh từ riêng","vn":"Lễ hội Té nước","examples":[{"cn":"泼水节是傣族人民一年中最盛大的传统节日。","pinyin":"Pōshuǐjié shì Dǎizú rénmín yìnián zhōng zuì shèngdà de chuántǒng jiérì.","vn":"Lễ hội Té nước là lễ hội truyền thống long trọng nhất trong năm của người dân tộc Thái."},{"cn":"在泼水节上，人们互相泼水表达美好的祝福。","pinyin":"Zài Pōshuǐjié shang, rénmen hùxiāng pōshuǐ biǎodá měihǎo de zhùfú.","vn":"Trong Lễ hội Té nước, mọi người té nước vào nhau để gửi gắm những lời chúc tốt đẹp."},{"cn":"每年四月都有成千上万的游客专门赶来体验泼水节。","pinyin":"Měinián sìyuè dōu yǒu chéngqiān-shàngwàn de yóukè zhuānmén gǎnlái tǐyàn Pōshuǐjié.","vn":"Tháng tư hằng năm đều có hàng vạn du khách đặc biệt tìm đến để trải nghiệm Lễ hội Té nước."}]},{"hanzi":"西双版纳","pinyin":"Xīshuāngbǎnnà","pos":"danh từ riêng","vn":"Tây Song Bản Nạp","examples":[{"cn":"西双版纳位于中国云南省南部，风景十分迷人。","pinyin":"Xīshuāngbǎnnà wèiyú Zhōngguó Yúnnánshěng nánbù, fēngjǐng shífēn mírén.","vn":"Tây Song Bản Nạp nằm ở phía nam tỉnh Vân Nam, Trung Quốc, phong cảnh vô cùng quyến rũ."},{"cn":"西双版纳气候温暖湿润，有很多珍稀的热带动植物。","pinyin":"Xīshuāngbǎnnà qìhòu wēnnuǎn shīrùn, yǒu hěn duō zhēnxī de rèdài dòngzhíwù.","vn":"Tây Song Bản Nạp khí hậu ấm áp ẩm ướt, có rất nhiều động thực vật nhiệt đới quý hiếm."},{"cn":"去年四月，我和朋友一起去了西双版纳参加泼水节。","pinyin":"Qùnián sìyuè, wǒ hé péngyou yìqǐ qù le Xīshuāngbǎnnà cānjiā Pōshuǐjié.","vn":"Tháng tư năm ngoái, tôi và bạn đã cùng nhau đến Tây Song Bản Nạp tham gia Lễ hội Té nước."}]},{"hanzi":"从中","pinyin":"cóngzhōng","pos":"phó.","vn":"từ trong đó, qua đó","examples":[{"cn":"阅读经典著作不仅让人愉快，还能让我们从中学到很多智慧。","pinyin":"Yuèdú jīngdiǎn zhùzuò bùjǐn ràng rén yúkuài, hái néng ràng wǒmen cóngzhōng xuédào hěn duō zhìhuì.","vn":"Đọc các tác phẩm kinh điển không chỉ khiến ta vui vẻ mà còn giúp ta học hỏi được nhiều trí tuệ từ trong đó."},{"cn":"失败并不可怕，关键是要能从中吸取教训。","pinyin":"Shībài bìng bù kěpà, guānjiàn shì yào néng cóngzhōng xīqǔ jiàoxùn.","vn":"Thất bại không hề đáng sợ, điều quan trọng là phải rút ra được bài học từ trong đó."},{"cn":"他参加了很多社会实践活动，从中积累了宝贵的经验。","pinyin":"Tā cānjiā le hěn duō shèhuì shíjiàn huódòng, cóngzhōng jīlěi le bǎoguì de jīngyàn.","vn":"Anh ấy đã tham gia nhiều hoạt động thực tiễn xã hội và tích lũy được kinh nghiệm quý báu từ đó."}]},{"hanzi":"总结","pinyin":"zǒngjié","pos":"dgt.","vn":"tổng kết, đúc kết","examples":[{"cn":"每次考试结束后，我们都应该认真总结经验与不足。","pinyin":"Měi cì kǎoshì jiéshù hòu, wǒmen dōu yīnggāi rènzhēn zǒngjié jīngyàn yǔ bùzú.","vn":"Sau mỗi kỳ thi, chúng ta đều nên nghiêm túc tổng kết kinh nghiệm và thiếu sót."},{"cn":"年终总结会上，经理表扬了我们团队的出色表现。","pinyin":"Niánzhōng zǒngjiéhuì shang, jīnglǐ biǎoyáng le wǒmen tuánduì de chūsè biǎoxiàn.","vn":"Trong buổi họp tổng kết cuối năm, giám đốc đã khen ngợi thành tích xuất sắc của nhóm chúng tôi."},{"cn":"经过多次旅行，他们总结出了一套非常实用的省钱攻略。","pinyin":"Jīngguò duō cì lǚxíng, tāmen zǒngjié chū le yí tào fēicháng shíyòng de shěngqián gōnglüè.","vn":"Qua nhiều lần du lịch, họ đã đúc kết ra một bộ bí kíp tiết kiệm tiền vô cùng hữu ích."}]},{"hanzi":"道路","pinyin":"dàolù","pos":"dt.","vn":"đường sá, con đường","examples":[{"cn":"这几年家乡的道路修得越来越宽敞平坦了。","pinyin":"Zhè jǐ nián jiāxiāng de dàolù xiū de yuè lái yuè kuānchang píngtǎn le.","vn":"Mấy năm nay đường sá ở quê hương được xây sửa ngày càng rộng rãi bằng phẳng."},{"cn":"下大雪以后，山区的道路非常湿滑，出行要注意安全。","pinyin":"Xià dàxuě yǐhòu, shānqū de dàolù fēicháng shīhuá, chūxíng yào zhùyì ānquán.","vn":"Sau trận tuyết lớn, đường sá vùng núi rất trơn trượt, đi lại cần chú ý an toàn."},{"cn":"通往成功的道路往往充满挑战，需要坚持不懈。","pinyin":"Tōngwǎng chénggōng de dàolù wǎngwǎng chōngmǎn tiǎozhàn, xūyào jiānchí-búxiè.","vn":"Con đường dẫn đến thành công thường đầy rẫy thử thách, đòi hỏi sự kiên trì bền bỉ."}]},{"hanzi":"特点","pinyin":"tèdiǎn","pos":"dt.","vn":"đặc điểm","examples":[{"cn":"中国不同地区的饮食文化都有各自的鲜明特点。","pinyin":"Zhōngguó bùtóng dìqū de yǐnshí wénhuà dōu yǒu gèzì de xiānmíng tèdiǎn.","vn":"Văn hóa ẩm thực ở các vùng miền khác nhau của Trung Quốc đều có những đặc điểm riêng rõ nét."},{"cn":"这款新手机最大的特点就是拍照清晰、电池耐用。","pinyin":"Zhè kuǎn xīn shǒujī zuì dà de tèdiǎn jiù shì pāizhào qīngxī, diànchí nàiyòng.","vn":"Đặc điểm lớn nhất của chiếc điện thoại mới này là chụp ảnh sắc nét và pin bền."},{"cn":"你能介绍一下你们家乡气候的特点吗？","pinyin":"Nǐ néng jièshào yíxià nǐmen jiāxiāng qìhòu de tèdiǎn ma?","vn":"Bạn có thể giới thiệu một chút về đặc điểm khí hậu quê hương bạn không?"}]},{"hanzi":"所有","pinyin":"suǒyǒu","pos":"tt.","vn":"tất cả, mọi","examples":[{"cn":"所有的准备工作都已经顺利完成了。","pinyin":"Suǒyǒu de zhǔnbèi gōngzuò dōu yǐjīng shùnlì wánchéng le.","vn":"Tất cả công việc chuẩn bị đều đã hoàn thành suôn sẻ rồi."},{"cn":"他把所有的零花钱都用来买喜欢的书了。","pinyin":"Tā bǎ suǒyǒu de línghuāqián dōu yònglái mǎi xǐhuan de shū le.","vn":"Cậu ấy đã dùng toàn bộ tiền tiêu vặt để mua những cuốn sách mình thích."},{"cn":"祝所有参加考试的同学们都能取得好成绩！","pinyin":"Zhù suǒyǒu cānjiā kǎoshì de tóngxuémen dōu néng qǔdé hǎo chéngjì!","vn":"Chúc tất cả các bạn học sinh tham gia kỳ thi đều đạt được thành tích tốt!"}]},{"hanzi":"意见","pinyin":"yìjiàn","pos":"dt.","vn":"ý kiến, ý kiến bất đồng","examples":[{"cn":"关于这个旅行计划，大家还有什么不同意见吗？","pinyin":"Guānyú zhège lǚxíng jìhuà, dàjiā hái yǒu shénme bùtóng yìjiàn ma?","vn":"Về kế hoạch du lịch này, mọi người còn có ý kiến nào khác không?"},{"cn":"做出重要决定之前，我习惯先听听父母的意见。","pinyin":"Zuòchū zhòngyào juédìng zhīqián, wǒ xíguàn xiān tīngting fùmǔ de yìjiàn.","vn":"Trước khi đưa ra quyết định quan trọng, tôi có thói quen nghe ý kiến của bố mẹ trước."},{"cn":"如果您对我们的服务有任何意见，欢迎随时提出。","pinyin":"Rúguǒ nín duì wǒmen de fúwù yǒu rènhé yìjiàn, huānyíng suíshí tíchū.","vn":"Nếu quý khách có bất kỳ ý kiến đóng góp nào về dịch vụ của chúng tôi, xin vui lòng góp ý bất cứ lúc nào."}]},{"hanzi":"细","pinyin":"xì","pos":"tt.","vn":"kỹ lưỡng, tỉ mỉ; nhỏ, mảnh","examples":[{"cn":"旅行前的计划做得越细，路上遇到的麻烦就越少。","pinyin":"Lǚxíng qián de jìhuà zuò de yuè xì, lùshang yùdào de máfan jiù yuè shǎo.","vn":"Kế hoạch trước chuyến đi làm càng tỉ mỉ thì rắc rối gặp phải trên đường càng ít."},{"cn":"这根绳子太细了，恐怕绑不住这么重的箱子。","pinyin":"Zhè gēn shéngzi tài xì le, kǒngpà bǎngbuzhù zhème zhòng de xiāngzi.","vn":"Sợi dây này mảnh quá, e rằng không buộc nổi chiếc vali nặng thế này."},{"cn":"她做事一向心细，很少出现粗心大意的错误。","pinyin":"Tā zuòshì yíxiàng xīnxì, hěn shǎo chūxiàn cūxīn-dàyì de cuòwù.","vn":"Cô ấy làm việc xưa nay rất cẩn thận tỉ mỉ, hiếm khi mắc lỗi bất cẩn."}]},{"hanzi":"烦恼","pinyin":"fánnǎo","pos":"tt.","vn":"phiền não, phiền muộn, bực mình","examples":[{"cn":"每个人生活中都会遇到一些烦恼，关键是要保持乐观。","pinyin":"Měi ge rén shēnghuó zhōng dōu huì yùdào yìxiē fánnǎo, guānjiàn shì yào bǎochí lèguān.","vn":"Trong cuộc sống ai cũng sẽ gặp phải một số phiền muộn, quan trọng là phải giữ tinh thần lạc quan."},{"cn":"听听轻音乐或者去公园跑跑步，能让我暂时忘记烦恼。","pinyin":"Tīngting qīngyīnyuè huòzhě qù gōngyuán pǎopao bù, néng ràng wǒ zànshí wàngjì fánnǎo.","vn":"Nghe nhạc nhẹ hoặc ra công viên chạy bộ giúp tôi tạm thời quên đi phiền não."},{"cn":"你最近看起来心情不太好，是在为工作烦恼吗？","pinyin":"Nǐ zuìjìn kàn qǐlai xīnqíng bú tài hǎo, shì zài wèi gōngzuò fánnǎo ma?","vn":"Gần đây trông tâm trạng bạn không tốt lắm, đang phiền lòng vì công việc sao?"}]},{"hanzi":"百分之","pinyin":"bǎi fēn zhī","pos":"","vn":"phần trăm (%)","examples":[{"cn":"我们班有百分之九十以上的同学都通过了HSK四级考试。","pinyin":"Wǒmen bān yǒu bǎi fēn zhī jiǔshí yǐshàng de tóngxué dōu tōngguò le HSK sìjí kǎoshì.","vn":"Hơn chín mươi phần trăm học sinh lớp chúng tôi đều đã thi đỗ HSK cấp 4."},{"cn":"提前一个月订机票，价格可以便宜百分之三十左右。","pinyin":"Tíqián yí ge yuè dìng jīpiào, jiàgé kěyǐ piányi bǎi fēn zhī sānshí zuǒyòu.","vn":"Đặt vé máy bay trước một tháng thì giá có thể rẻ hơn khoảng ba mươi phần trăm."},{"cn":"这家商场周末大打折，全场商品便宜百分之二十。","pinyin":"Zhè jiā shāngchǎng zhōumò dà dǎzhé, quánchǎng shāngpǐn piányi bǎi fēn zhī èrshí.","vn":"Trung tâm thương mại này cuối tuần giảm giá lớn, toàn bộ hàng hóa rẻ hơn hai mươi phần trăm."}]},{"hanzi":"节省","pinyin":"jiéshěng","pos":"dgt.","vn":"tiết kiệm","examples":[{"cn":"坐地铁上班不仅方便，还能节省很多路上时间。","pinyin":"Zuò dìtiě shàngbān bùjǐn fāngbiàn, hái néng jiéshěng hěn duō lùshang shíjiān.","vn":"Đi làm bằng tàu điện ngầm không chỉ tiện lợi mà còn tiết kiệm được rất nhiều thời gian đi đường."},{"cn":"我们应该养成随手关灯、节省水电的好习惯。","pinyin":"Wǒmen yīnggāi yǎngchéng suíshǒu guāndēng, jiéshěng shuǐdiàn de hǎo xíguàn.","vn":"Chúng ta nên rèn thói quen tắt đèn khi ra khỏi phòng, tiết kiệm điện nước."},{"cn":"自己在家里做饭既健康，每个月又能节省不少生活费。","pinyin":"Zìjǐ zài jiālǐ zuòfàn jì jiànkāng, měi ge yuè yòu néng jiéshěng bùshǎo shēnghuófèi.","vn":"Tự nấu ăn ở nhà vừa tốt cho sức khỏe, mỗi tháng lại tiết kiệm được kha khá tiền sinh hoạt."}]},{"hanzi":"当","pinyin":"dàng","pos":"dgt.","vn":"coi như, xem như","examples":[{"cn":"别客气，就把这里当成自己的家吧。","pinyin":"Bié kèqi, jiù bǎ zhèlǐ dàngchéng zìjǐ de jiā ba.","vn":"Đừng khách sáo, hãy cứ coi nơi đây như nhà của chính mình nhé."},{"cn":"她一直把这位热心的中国同学当成自己的亲姐姐。","pinyin":"Tā yìzhí bǎ zhè wèi rèxīn de Zhōngguó tóngxué dàngchéng zìjǐ de qīn jiějie.","vn":"Cô ấy luôn coi người bạn Trung Quốc nhiệt tình này như chị gái ruột của mình."},{"cn":"我本来只是开个玩笑，没想到他竟然当真了。","pinyin":"Wǒ běnlái zhǐshì kāi ge wánxiào, méi xiǎngdào tā jìngrán dàngzhēn le.","vn":"Tôi vốn chỉ nói đùa thôi, không ngờ anh ấy lại coi là thật."}]},{"hanzi":"红包","pinyin":"hóngbāo","pos":"dt.","vn":"bao lì xì, phong bao đỏ","examples":[{"cn":"过春节的时候，长辈通常会给孩子们发压岁红包。","pinyin":"Guò Chūnjié de shíhou, zhǎngbèi tōngcháng huì gěi háizimen fā yāsuì hóngbāo.","vn":"Vào dịp Tết Nguyên đán, người lớn tuổi thường mừng tuổi bao lì xì cho trẻ nhỏ."},{"cn":"现在大家在微信群里抢红包已经成为一种有趣的互动方式。","pinyin":"Xiànzài dàjiā zài Wēixìn qún lǐ qiǎng hóngbāo yǐjīng chéngwéi yì zhǒng yǒuqù de hùdòng fāngshì.","vn":"Hiện nay mọi người giật lì xì trong nhóm WeChat đã trở thành một cách tương tác thú vị."},{"cn":"朋友结婚那天，我包了一个大红包祝他们新婚快乐。","pinyin":"Péngyou jiéhūn nà tiān, wǒ bāo le yí ge dà hóngbāo zhù tāmen xīnhūn kuàilè.","vn":"Hôm bạn kết hôn, tôi đã gói một phong bao đỏ lớn chúc họ tân hôn hạnh phúc."}]},{"hanzi":"卷","pinyin":"juàn","pos":"lượng.","vn":"quyển, cuốn (sách)","examples":[{"cn":"古人常说“读万卷书，行万里路”，意思是既要读书也要实践。","pinyin":"Gǔrén cháng shuō \"dú wàn juàn shū, xíng wàn lǐ lù\", yìsi shì jì yào dúshū yě yào shíjiàn.","vn":"Người xưa thường nói \"đọc vạn quyển sách, đi vạn dặm đường\", ý là vừa phải đọc sách vừa phải trải nghiệm thực tế."},{"cn":"这套历史大辞典一共有十二卷，内容非常全面。","pinyin":"Zhè tào lìshǐ dà cídiǎn yígòng yǒu shí'èr juàn, nèiróng fēicháng quánmiàn.","vn":"Bộ đại từ điển lịch sử này có tổng cộng mười hai quyển, nội dung vô cùng toàn diện."},{"cn":"图书馆珍藏着许多珍贵的古代文献书卷。","pinyin":"Túshūguǎn zhēncáng zhe xǔduō zhēnguì de gǔdài wénxiàn shūjuàn.","vn":"Thư viện lưu giữ rất nhiều quyển sách tư liệu cổ quý giá."}]},{"hanzi":"里","pinyin":"lǐ","pos":"lượng.","vn":"dặm (đơn vị đo chiều dài, 1 dặm Trung Quốc = 500 mét)","examples":[{"cn":"两里路等于一公里，走过去大概需要十几分钟。","pinyin":"Liǎng lǐ lù děngyú yì gōnglǐ, zǒuguòqù dàgài xūyào shíjǐ fēnzhōng.","vn":"Hai dặm đường bằng một ki-lô-mét, đi bộ qua đó mất khoảng mười mấy phút."},{"cn":"万里长城像一条巨龙一样盘踞在崇山峻岭之间。","pinyin":"Wànlǐ Chángchéng xiàng yì tiáo jùlóng yíyàng pánjù zài chóngshān-jùnlǐng zhījiān.","vn":"Vạn Lý Trường Thành giống như một con rồng khổng lồ uốn lượn giữa núi non trùng điệp."},{"cn":"从我们村到镇上只有五里地，骑自行车很快就能到。","pinyin":"Cóng wǒmen cūn dào zhènshang zhǐ yǒu wǔ lǐ dì, qí zìxíngchē hěn kuài jiù néng dào.","vn":"Từ làng chúng tôi đến thị trấn chỉ có năm dặm, đạp xe rất nhanh là tới nơi."}]},{"hanzi":"要是","pinyin":"yàoshi","pos":"liên.","vn":"nếu, nếu như","examples":[{"cn":"要是明天下雨，我们就取消爬山计划，改去博物馆。","pinyin":"Yàoshi míngtiān xiàyǔ, wǒmen jiù qǔxiāo páshān jìhuà, gǎi qù bówùguǎn.","vn":"Nếu ngày mai trời mưa, chúng ta sẽ hủy kế hoạch leo núi và đổi sang đi bảo tàng."},{"cn":"你要是遇到什么困难，随时可以给我打电话。","pinyin":"Nǐ yàoshi yùdào shénme kùnnan, suíshí kěyǐ gěi wǒ dǎ diànhuà.","vn":"Nếu bạn gặp khó khăn gì, bất cứ lúc nào cũng có thể gọi điện cho tôi."},{"cn":"要是能早点儿出发，我们就不会在路上堵车了。","pinyin":"Yàoshi néng zǎodiǎnr chūfā, wǒmen jiù bú huì zài lùshang dǔchē le.","vn":"Nếu có thể xuất phát sớm hơn một chút thì chúng ta đã không bị kẹt xe trên đường rồi."}]},{"hanzi":"少数","pinyin":"shǎoshù","pos":"dt.","vn":"thiểu số, số ít","examples":[{"cn":"云南是中国少数民族最多的省份。","pinyin":"Yúnnán shì Zhōngguó shǎoshù mínzú zuì duō de shěngfèn.","vn":"Vân Nam là tỉnh có nhiều dân tộc thiểu số nhất ở Trung Quốc."},{"cn":"绝大多数人都支持这个方案，只有少数人提出异议。","pinyin":"Juédàduōshù rén dōu zhīchí zhège fāng'àn, zhǐ yǒu shǎoshù rén tíchū yìyì.","vn":"Đại đa số mọi người đều ủng hộ phương án này, chỉ có số ít người nêu ý kiến trái chiều."},{"cn":"遇到分歧时，我们应该充分讨论，少数服从多数。","pinyin":"Yùdào fēnqí shí, wǒmen yīnggāi chōngfèn tǎolùn, shǎoshù fúcóng duōshù.","vn":"Khi gặp bất đồng, chúng ta nên thảo luận kỹ lưỡng, thiểu số phục tùng đa số."}]},{"hanzi":"民族","pinyin":"mínzú","pos":"dt.","vn":"dân tộc","examples":[{"cn":"中国是一个由五十六个民族组成的大家庭。","pinyin":"Zhōngguó shì yí ge yóu wǔshíliù ge mínzú zǔchéng de dàjiātíng.","vn":"Trung Quốc là một đại gia đình gồm năm mươi sáu dân tộc."},{"cn":"每个民族都有自己独特的传统服饰、音乐和节日。","pinyin":"Měi ge mínzú dōu yǒu zìjǐ dútè de chuántǒng fúshì, yīnyuè hé jiérì.","vn":"Mỗi dân tộc đều có trang phục truyền thống, âm nhạc và lễ hội độc đáo của riêng mình."},{"cn":"演出中，演员们为我们表演了精彩的民族舞蹈。","pinyin":"Yǎnchū zhōng, yǎnyuánmen wèi wǒmen biǎoyǎn le jīngcǎi de mínzú wǔdǎo.","vn":"Trong buổi biểu diễn, các diễn viên đã trình diễn điệu múa dân tộc vô cùng đặc sắc cho chúng tôi xem."}]},{"hanzi":"导游","pinyin":"dǎoyóu","pos":"dt./dgt.","vn":"hướng dẫn viên du lịch; dẫn đoàn du lịch","examples":[{"cn":"这位导游知识非常渊博，一路上给大家讲了很多有趣的历史故事。","pinyin":"Zhè wèi dǎoyóu zhīshi fēicháng yuānbó, yílù shang gěi dàjiā jiǎng le hěn duō yǒuqù de lìshǐ gùshi.","vn":"Hướng dẫn viên này kiến thức vô cùng uyên bác, suốt dọc đường đã kể cho mọi người nghe rất nhiều câu chuyện lịch sử thú vị."},{"cn":"请大家紧跟导游手中的小旗子，不要走散了。","pinyin":"Qǐng dàjiā jǐngēn dǎoyóu shǒuzhōng de xiǎo qízi, búyào zǒusàn le.","vn":"Xin mọi người đi sát theo lá cờ nhỏ trên tay hướng dẫn viên, đừng để bị lạc đoàn."},{"cn":"他毕业后考了导游证，专门接待来自世界各地的游客。","pinyin":"Tā bìyè hòu kǎo le dǎoyóuzhèng, zhuānmén jiēdài láizì shìjiè gèdì de yóukè.","vn":"Sau khi tốt nghiệp anh ấy đã thi lấy thẻ hướng dẫn viên, chuyên đón tiếp du khách đến từ khắp nơi trên thế giới."}]},{"hanzi":"解释","pinyin":"jiěshì","pos":"dgt.","vn":"giải thích","examples":[{"cn":"这个问题老师解释得非常清楚，我一下子就明白了。","pinyin":"Zhège wèntí lǎoshī jiěshì de fēicháng qīngchu, wǒ yíxiàzi jiù míngbai le.","vn":"Vấn đề này cô giáo giải thích vô cùng rõ ràng, tôi hiểu ngay lập tức."},{"cn":"你先别生气，听我好好跟你解释一下当时的情况。","pinyin":"Nǐ xiān bié shēngqì, tīng wǒ hǎohǎo gēn nǐ jiěshì yíxià dāngshí de qíngkuàng.","vn":"Bạn khoan hãy giận, nghe tôi giải thích rõ ràng với bạn tình hình lúc đó đã."},{"cn":"遇到不懂的词语时，可以查词典看看它的意思和解释。","pinyin":"Yùdào bù dǒng de cíyǔ shí, kěyǐ chá cídiǎn kànkan tā de yìsi hé jiěshì.","vn":"Khi gặp từ ngữ không hiểu, có thể tra từ điển xem ý nghĩa và lời giải thích của nó."}]},{"hanzi":"泼","pinyin":"pō","pos":"dgt.","vn":"té, hất, tạt (nước)","examples":[{"cn":"泼水节那天，大家拿着水盆开心地互相泼水。","pinyin":"Pōshuǐjié nà tiān, dàjiā názhe shuǐpén kāixīn de hùxiāng pōshuǐ.","vn":"Hôm Lễ hội Té nước, mọi người cầm chậu nước vui vẻ té nước vào nhau."},{"cn":"他一不小心把桌子上的茶水泼到了笔记本上。","pinyin":"Tā yì bù xiǎoxīn bǎ zhuōzi shang de cháshuǐ pō dào le bǐjìběn shang.","vn":"Anh ấy sơ ý làm hất nước trà trên bàn đổ lên cuốn sổ ghi chép."},{"cn":"在西双版纳，被泼的水越多代表收到的祝福越多。","pinyin":"Zài Xīshuāngbǎnnà, bèi pō de shuǐ yuè duō dàibiǎo shōudào de zhùfú yuè duō.","vn":"Ở Tây Song Bản Nạp, nước được té càng nhiều đại diện cho lời chúc nhận được càng nhiều."}]},{"hanzi":"流利","pinyin":"liúlì","pos":"tt.","vn":"lưu loát, trôi chảy","examples":[{"cn":"他在中国留学三年，现在能说一口非常流利的中文。","pinyin":"Tā zài Zhōngguó liúxué sān nián, xiànzài néng shuō yì kǒu fēicháng liúlì de Zhōngwén.","vn":"Anh ấy du học ở Trung Quốc ba năm, giờ đã có thể nói một thứ tiếng Trung vô cùng lưu loát."},{"cn":"多听多说、不怕犯错，口语才会越来越流利。","pinyin":"Duō tīng duō shuō, bú pà fàncuò, kǒuyǔ cái huì yuè lái yuè liúlì.","vn":"Nghe nhiều nói nhiều, không sợ mắc lỗi thì khẩu ngữ mới ngày càng trôi chảy được."},{"cn":"这位小导游用流利的英语向外国游客介绍西安的历史。","pinyin":"Zhè wèi xiǎo dǎoyóu yòng liúlì de Yīngyǔ xiàng wàiguó yóukè jièshào Xī'ān de lìshǐ.","vn":"Hướng dẫn viên trẻ này dùng tiếng Anh lưu loát giới thiệu lịch sử Tây An cho du khách nước ngoài."}]},{"hanzi":"唐装","pinyin":"Tángzhuāng","pos":"danh từ riêng","vn":"Đường trang (trang phục truyền thống kiểu Trung Hoa)","examples":[{"cn":"春节期间，很多老人喜欢穿喜庆的红色唐装。","pinyin":"Chūnjié qījiān, hěn duō lǎorén xǐhuan chuān xǐqìng de hóngsè Tángzhuāng.","vn":"Vào dịp Tết Nguyên đán, nhiều người lớn tuổi thích mặc Đường trang màu đỏ mang không khí vui tươi."},{"cn":"在西安的古街上，随处可见身穿唐装拍照留念的游客。","pinyin":"Zài Xī'ān de gǔjiē shang, suíchù kějiàn shēnchuān Tángzhuāng pāizhào liúniàn de yóukè.","vn":"Trên khu phố cổ ở Tây An, đâu đâu cũng thấy du khách mặc Đường trang chụp ảnh lưu niệm."},{"cn":"安妮在商店买了一件精美的唐装准备带回国送给妈妈。","pinyin":"Ānnī zài shāngdiàn mǎi le yí jiàn jīngměi de Tángzhuāng zhǔnbèi dài huíguó sòng gěi māma.","vn":"Annie đã mua một chiếc áo Đường trang tinh xảo ở cửa hàng để chuẩn bị mang về nước tặng mẹ."}]}],"grammar":[{"title":"语气副词\"难道\"","explanation_vn":"Phó từ ngữ khí \"难道\" (lẽ nào, chẳng lẽ) có thể biểu thị ngữ khí phỏng đoán, cũng có thể dùng trong câu phản vấn \"难道……吗？\" để nhấn mạnh ngữ khí phủ định hoặc khẳng định. Nếu dùng hình thức khẳng định thì biểu thị ý phủ định; nếu dùng hình thức phủ định thì biểu thị ý khẳng định.","examples":[{"cn":"难道你买的是无座票吗？","pinyin":"Nándào nǐ mǎi de shì wúzuò piào ma?","vn":"Chẳng lẽ cậu mua vé không chỗ ngồi sao?"},{"cn":"车快开了他还没到，难道他不去了？","pinyin":"Chē kuài kāi le tā hái méi dào, nándào tā bú qù le?","vn":"Xe sắp chạy rồi mà anh ấy vẫn chưa tới, lẽ nào anh ấy không đi nữa sao?"},{"cn":"难道我们不应该保护环境吗？","pinyin":"Nándào wǒmen bù yīnggāi bǎohù huánjìng ma?","vn":"Chẳng lẽ chúng ta không nên bảo vệ môi trường sao?"}]},{"title":"反问句：由疑问代词构成的反问句","explanation_vn":"Câu phản vấn được cấu tạo từ các đại từ nghi vấn như \"谁\" (ai), \"什么\" (cái gì), \"怎么\" (thế nào/sao), \"哪里\" (đâu), \"为什么\" (tại sao)... có tác dụng nhấn mạnh ngữ khí. Nếu ở hình thức khẳng định thì biểu thị nghĩa phủ định; nếu ở hình thức phủ định thì biểu thị nghĩa khẳng định.","examples":[{"cn":"谁说不是呢？","pinyin":"Shéi shuō bú shì ne?","vn":"Ai bảo không phải chứ? (Đúng quá đi chứ!)"},{"cn":"这里离苏州这么近，我们为什么不去苏州玩玩呢？","pinyin":"Zhèlǐ lí Sūzhōu zhème jìn, wǒmen wèishénme bú qù Sūzhōu wánwan ne?","vn":"Ở đây cách Tô Châu gần thế này, tại sao chúng ta không đi Tô Châu chơi một chuyến nhỉ?"},{"cn":"我们连手机都没有，怎么能查到这些信息啊？","pinyin":"Wǒmen lián shǒujī dōu méiyǒu, zěnme néng chádào zhèxiē xìnxī a?","vn":"Chúng ta đến điện thoại còn không có, làm sao tra được những thông tin này chứ?"}]},{"title":"固定格式\"×就×（点儿）吧\"","explanation_vn":"Cấu trúc cố định \"×就×（点儿）吧\" biểu thị sự thỏa hiệp, nhượng bộ, có nghĩa là chấp nhận tạm được rồi. Cấu trúc này thường dùng trong khẩu ngữ.","examples":[{"cn":"累就累点儿吧，花更少的钱去看更多的地方，很值得。","pinyin":"Lèi jiù lèi diǎnr ba, huā gèng shǎo de qián qù kàn gèng duō de dìfang, hěn zhídé.","vn":"Mệt thì mệt một chút cũng được, tiêu ít tiền hơn để đi ngắm được nhiều nơi hơn, rất xứng đáng."},{"cn":"我租的房子离公司有些远，我想，远就远吧，至少房租便宜。","pinyin":"Wǒ zū de fángzi lí gōngsī yǒuxiē yuǎn, wǒ xiǎng, yuǎn jiù yuǎn ba, zhìshǎo fángzū piányi.","vn":"Căn nhà tôi thuê hơi xa công ty, tôi nghĩ xa thì xa vậy, ít nhất tiền thuê nhà rẻ."},{"cn":"慢就慢点儿吧，安全最重要。","pinyin":"Màn jiù màn diǎnr ba, ānquán zuì zhòngyào.","vn":"Chậm thì chậm một chút cũng được, an toàn là quan trọng nhất."}]},{"title":"假设复句\"要是……，（就）……，否则……\"","explanation_vn":"\"要是……，（就）……，否则……\" là câu phức được cấu tạo bởi giả thiết và hậu quả. \"要是……，（就）……\" (nếu... thì...) biểu thị giả thiết trong một điều kiện hoặc tình huống nào đó nên thực hiện hành động gì hoặc sẽ dẫn đến kết quả nào; \"否则\" (nếu không thì) biểu thị nếu không làm như vậy sẽ dẫn đến một hậu quả nào đó.","examples":[{"cn":"你们要是想多了解中国，就不能只通过读书，还要多出门旅行，否则只能认识课本里的中国。","pinyin":"Nǐmen yàoshi xiǎng duō liǎojiě Zhōngguó, jiù bù néng zhǐ tōngguò dúshū, hái yào duō chūmén lǚxíng, fǒuzé zhǐ néng rènshi kèběn lǐ de Zhōngguó.","vn":"Các em nếu muốn hiểu nhiều hơn về Trung Quốc thì không thể chỉ thông qua đọc sách, mà còn phải ra ngoài du lịch nhiều hơn, nếu không thì chỉ có thể biết một Trung Quốc trong sách giáo khoa thôi."},{"cn":"要是出去的话，咱们就爬山，否则我哪儿都不去。","pinyin":"Yàoshi chūqù de huà, zánmen jiù páshān, fǒuzé wǒ nǎr dōu bú qù.","vn":"Nếu ra ngoài thì chúng mình đi leo núi, nếu không thì tôi chẳng đi đâu cả."},{"cn":"要是你同意的话，这个计划就通过，否则可能需要重新讨论。","pinyin":"Yàoshi nǐ tóngyì de huà, zhège jìhuà jiù tōngguò, fǒuzé kěnéng xūyào chóngxīn tǎolùn.","vn":"Nếu bạn đồng ý thì kế hoạch này sẽ được thông qua, nếu không thì có lẽ cần phải thảo luận lại."}]}],"texts":[{"label":"Bài khóa 1","type":"dialogue","lines":[{"speaker":"安妮","cn":"终于上车了，刚刚路上堵车，差点儿晚了。","pinyin":"Zhōngyú shàngchē le, gānggāng lùshang dǔchē, chàdiǎnr wǎn le."},{"speaker":"白家月","cn":"没关系，晚了就改乘下一趟。天中，你坐哪儿？看你一直不坐下，我还在想，难道你买的是无座票吗？","pinyin":"Méi guānxi, wǎn le jiù gǎichéng xià yí tàng. Tiānzhōng, nǐ zuò nǎr? Kàn nǐ yìzhí bú zuòxia, wǒ hái zài xiǎng, nándào nǐ mǎi de shì wúzuò piào ma?"},{"speaker":"陈天中","cn":"我的座位就在前边，我想先站这儿跟你们说说话。","pinyin":"Wǒ de zuòwèi jiù zài qiánbiān, wǒ xiǎng xiān zhàn zhèr gēn nǐmen shuōshuohuà."},{"speaker":"安妮","cn":"动车车速也挺快啊！对了，这列车晚上七点多到杭州，咱们在车上吃晚餐，到站后就先去西湖吧，夜里的西湖更美。","pinyin":"Dòngchē chēsù yě tǐng kuài a! Duì le, zhè liè chē wǎnshang qī diǎn duō dào Hángzhōu, zánmen zài chēshang chī wǎncān, dào zhàn hòu jiù xiān qù Xī Hú ba, yèlǐ de Xī Hú gèng měi."},{"speaker":"陈天中","cn":"好！后天我们坐大巴去苏州，看苏州园林。","pinyin":"Hǎo! Hòutiān wǒmen zuò dàbā qù Sūzhōu, kàn Sūzhōu Yuánlín."},{"speaker":"白家月","cn":"嗯。中国太大了！真是看也看不完啊。","pinyin":"Èn. Zhōngguó tài dà le! Zhēn shì kàn yě kàn bu wán a."}],"translation_vn":"Annie: Cuối cùng cũng lên tàu rồi, vừa nãy trên đường bị tắc đường, suýt nữa thì trễ.\nBạch Gia Nguyệt: Không sao đâu, trễ thì đổi sang đi chuyến tiếp theo. Thiên Trung, cậu ngồi chỗ nào? Thấy cậu đứng mãi không ngồi xuống, mình còn đang nghĩ chẳng lẽ cậu mua vé không chỗ ngồi sao?\nTrần Thiên Trung: Chỗ ngồi của mình ở ngay phía trước, mình muốn đứng đây nói chuyện với các cậu một lúc trước.\nAnnie: Tốc độ tàu cao tốc cũng nhanh ghê! À đúng rồi, chuyến tàu này hơn bảy giờ tối đến Hàng Châu, chúng mình ăn tối trên tàu, đến ga thì đi Tây Hồ trước nhé, Tây Hồ ban đêm còn đẹp hơn nữa.\nTrần Thiên Trung: Được! Ngày kia chúng ta đi xe khách sang Tô Châu, tham quan Viên lâm Tô Châu.\nBạch Gia Nguyệt: Ừ. Trung Quốc rộng lớn quá! Thật sự xem mãi cũng chẳng hết.","audio_dialogue":"20-1.mp3","audio_vocab":"20-2.mp3"},{"label":"Bài khóa 2","type":"dialogue","lines":[{"speaker":"李文","cn":"安检完就等着登机了。你们在看什么？","pinyin":"Ānjiǎn wán jiù děngzhe dēngjī le. Nǐmen zài kàn shénme?"},{"speaker":"白家月","cn":"我在读老舍的小说。","pinyin":"Wǒ zài dú Lǎoshě de xiǎoshuō."},{"speaker":"陈天中","cn":"我读的是一本中国历史书。","pinyin":"Wǒ dú de shì yì běn Zhōngguó lìshǐ shū."},{"speaker":"安妮","cn":"我读唐诗呢。几千年的中国文化，真是读也读不完。","pinyin":"Wǒ dú Tángshī ne. Jǐ qiān nián de Zhōngguó wénhuà, zhēn shì dú yě dú bu wán."},{"speaker":"李文","cn":"谁说不是呢？不过，现在咱们得去排队，航班的值机员在叫大家登机呢——","pinyin":"Shéi shuō bú shì ne? Búguò, xiànzài zánmen děi qù páiduì, hángbān de zhíjīyuán zài jiào dàjiā dēngjī ne —"},{"speaker":"","cn":"（值机员的话）去西安的旅客开始登机，请拿好登机牌按顺序排队。","pinyin":"(Zhíjīyuán de huà) Qù Xī'ān de lǚkè kāishǐ dēngjī, qǐng náhǎo dēngjīpái àn shùnxù páiduì."},{"speaker":"","cn":"……","pinyin":"……"},{"speaker":"白家月","cn":"终于上来了，我的座位靠窗户。","pinyin":"Zhōngyú shànglái le, wǒ de zuòwèi kào chuānghu."},{"speaker":"安妮","cn":"我在最外边。这么多人，是不是跟咱们一样，都是去感受泼水节的啊？","pinyin":"Wǒ zài zuì wàibiān. Zhème duō rén, shì bu shì gēn zánmen yíyàng, dōu shì qù gǎnshòu Pōshuǐjié de a?"},{"speaker":"李文","cn":"应该不是。很多人的目的地是西安，你别忘了，咱们是在西安转机，然后再飞西双版纳。","pinyin":"Yīnggāi bú shì. Hěn duō rén de mùdìdì shì Xī'ān, nǐ bié wàng le, zánmen shì zài Xī'ān zhuǎnjī, ránhòu zài fēi Xīshuāngbǎnnà."}],"translation_vn":"Lý Văn: Kiểm tra an ninh xong là đợi lên máy bay thôi. Các cậu đang đọc gì thế?\nBạch Gia Nguyệt: Mình đang đọc tiểu thuyết của Lão Xá.\nTrần Thiên Trung: Mình đang đọc một cuốn sách lịch sử Trung Quốc.\nAnnie: Mình đang đọc thơ Đường. Văn hóa Trung Quốc mấy nghìn năm, thật sự đọc mãi cũng không hết.\nLý Văn: Ai bảo không phải chứ? Nhưng mà giờ chúng mình phải đi xếp hàng thôi, nhân viên làm thủ tục của chuyến bay đang gọi mọi người lên máy bay kìa——\n(Lời nhân viên làm thủ tục) Hành khách đi Tây An bắt đầu lên máy bay, xin vui lòng cầm sẵn thẻ lên máy bay xếp hàng theo thứ tự.\n……\nBạch Gia Nguyệt: Cuối cùng cũng lên máy bay rồi, chỗ ngồi của mình sát cửa sổ.\nAnnie: Mình ngồi ngoài cùng. Đông người thế này, có phải đều giống chúng mình, đi trải nghiệm Lễ hội Té nước không nhỉ?\nLý Văn: Chắc là không đâu. Điểm đến của nhiều người là Tây An, cậu đừng quên là chúng mình chỉ quá cảnh ở Tây An rồi mới bay tiếp đi Tây Song Bản Nạp.","audio_dialogue":"20-3.mp3","audio_vocab":"20-4.mp3"},{"label":"Bài khóa 3","type":"passage","lines":[{"speaker":"","cn":"来中国留学后，白家月、安妮和陈天中常外出旅行，从中了解中国。他们还总结出几点旅行经验：","pinyin":"Lái Zhōngguó liúxué hòu, Bái Jiāyuè, Ānnī hé Chén Tiānzhōng cháng wàichū lǚxíng, cóngzhōng liǎojiě Zhōngguó. Tāmen hái zǒngjié chū jǐ diǎn lǚxíng jīngyàn:"},{"speaker":"","cn":"第一，好计划是成功的一半。旅行前，要了解目的地天气、道路交通特点等，安排好每天的活动，保证所有人对计划都没意见。准备越细，烦恼越少。","pinyin":"Dì yī, hǎo jìhuà shì chénggōng de yíbàn. Lǚxíng qián, yào liǎojiě mùdìdì tiānqì, dàolù jiāotōng tèdiǎn děng, ānpái hǎo měitiān de huódòng, bǎozhèng suǒyǒu rén duì jìhuà dōu méi yìjiàn. Zhǔnbèi yuè xì, fánnǎo yuè shǎo."},{"speaker":"","cn":"第二，节假日早点儿订机票、酒店和各种门票，否则很难订到。","pinyin":"Dì èr, jiéjiàrì zǎodiǎnr dìng jīpiào, jiǔdiàn hé gèzhǒng ménpiào, fǒuzé hěn nán dìngdào."},{"speaker":"","cn":"第三，转机会比直飞更便宜。此次去西双版纳，在西安转机，机票价格比直飞便宜了百分之四十多。虽然有些累，但累就累点儿吧，花更少的钱去看更多的地方，很值得，节省下来的钱就当是给自己的大“红包”了。","pinyin":"Dì sān, zhuǎnjī huì bǐ zhífēi gèng piányi. Cǐcì qù Xīshuāngbǎnnà, zài Xī'ān zhuǎnjī, jīpiào jiàgé bǐ zhífēi piányi le bǎi fēn zhī sìshí duō. Suīrán yǒuxiē lèi, dàn lèi jiù lèi diǎnr ba, huā gèng shǎo de qián qù kàn gèng duō de dìfang, hěn zhídé, jiéshěng xiàlái de qián jiù dàng shì gěi zìjǐ de dà “hóngbāo” le."}],"translation_vn":"Sau khi đến Trung Quốc du học, Bạch Gia Nguyệt, Annie và Trần Thiên Trung thường xuyên đi du lịch, qua đó tìm hiểu về Trung Quốc. Họ còn đúc kết được mấy kinh nghiệm du lịch sau:\nThứ nhất, kế hoạch tốt là một nửa của thành công. Trước chuyến đi, cần tìm hiểu thời tiết, đặc điểm đường sá giao thông của điểm đến..., sắp xếp chu đáo hoạt động mỗi ngày, đảm bảo tất cả mọi người đều không có ý kiến gì với kế hoạch. Chuẩn bị càng tỉ mỉ, phiền phức càng ít.\nThứ hai, vào ngày lễ tết nên đặt sớm vé máy bay, khách sạn và các loại vé tham quan, nếu không sẽ rất khó đặt được.\nThứ ba, bay quá cảnh sẽ rẻ hơn bay thẳng. Chuyến đi Tây Song Bản Nạp lần này, quá cảnh tại Tây An, giá vé máy bay rẻ hơn bay thẳng hơn bốn mươi phần trăm. Tuy có hơi mệt nhưng mệt thì mệt một chút cũng được, tiêu ít tiền hơn để đi ngắm được nhiều nơi hơn, rất xứng đáng, số tiền tiết kiệm được cứ coi như là một \"bao lì xì\" lớn tự thưởng cho bản thân vậy.","audio_dialogue":"20-5.mp3","audio_vocab":"20-6.mp3"},{"label":"Bài khóa 4","type":"passage","lines":[{"speaker":"","cn":"王一飞常对她的学生说：“读万卷书，行万里路。你们要是想多了解中国，就不能只通过读书，还要多出门旅行，否则只能认识课本里的中国。”","pinyin":"Wáng Yīfēi cháng duì tā de xuésheng shuō: “Dú wàn juàn shū, xíng wàn lǐ lù. Nǐmen yàoshi xiǎng duō liǎojiě Zhōngguó, jiù bù néng zhǐ tōngguò dúshū, hái yào duō chūmén lǚxíng, fǒuzé zhǐ néng rènshi kèběn lǐ de Zhōngguó.”"},{"speaker":"","cn":"旅行，不仅能看到自然美景，还能近距离感受不同的历史文化。比如，白家月等人想了解少数民族泼水节，就去了西双版纳。泼水节上，导游向他们解释说，被泼的水越多，新的一年就会越健康、幸福。安妮喜欢唐诗，就来到了西安，在那里遇到身穿唐装的“对诗人”，对诗人说上句，游客就能流利地说出下句。安妮觉得在西安，唐诗活了。","pinyin":"Lǚxíng, bùjǐn néng kàndào zìrán měijǐng, hái néng jìn jùlí gǎnshòu bùtóng de lìshǐ wénhuà. Bǐrú, Bái Jiāyuè děng rén xiǎng liǎojiě shǎoshù mínzú Pōshuǐjié, jiù qùle Xīshuāngbǎnnà. Pōshuǐjié shàng, dǎoyóu xiàng tāmen jiěshì shuō, bèi pō de shuǐ yuè duō, xīn de yì nián jiù huì yuè jiànkāng, xìngfú. Ānnī xǐhuan Tángshī, jiù láidàole Xī'ān, zài nàlǐ yùdào shēnchuān Tángzhuāng de “duìshīrén”, duìshīrén shuō shàngjù, yóukè jiù néng liúlì de shuōchū xiàjù. Ānnī juéde zài Xī'ān, Tángshī huó le."},{"speaker":"","cn":"虽然已经去了很多地方，但是白家月他们觉得还不够。他们也认为，美丽中国，不只是在书中，更是在脚下。","pinyin":"Suīrán yǐjīng qùle hěn duō dìfang, dànshì Bái Jiāyuè tāmen juéde hái búgòu. Tāmen yě rènwéi, měilì Zhōngguó, bù zhǐ shì zài shū zhōng, gèng shì zài jiǎoxià."}],"translation_vn":"Vương Nhất Phi thường nói với học sinh của mình: \"Đọc vạn quyển sách, đi vạn dặm đường. Các em nếu muốn hiểu nhiều hơn về Trung Quốc thì không thể chỉ thông qua đọc sách, mà còn phải ra ngoài du lịch nhiều hơn, nếu không thì chỉ có thể biết một Trung Quốc trong sách giáo khoa thôi.\"\nDu lịch không chỉ giúp ngắm nhìn cảnh đẹp thiên nhiên, mà còn có thể cảm nhận ở cự ly gần những nền lịch sử văn hóa khác nhau. Ví dụ, nhóm Bạch Gia Nguyệt muốn tìm hiểu Lễ hội Té nước của dân tộc thiểu số nên đã đến Tây Song Bản Nạp. Tại Lễ hội Té nước, hướng dẫn viên giải thích với họ rằng nước được té càng nhiều thì năm mới sẽ càng khỏe mạnh, hạnh phúc. Annie thích thơ Đường nên đã đến Tây An, ở đó cô gặp \"người đối thơ\" mặc Đường trang, người đối thơ đọc câu trên thì du khách có thể đọc lưu loát câu dưới. Annie cảm thấy ở Tây An, thơ Đường như sống dậy vậy.\nTuy đã đi rất nhiều nơi, nhưng nhóm Bạch Gia Nguyệt vẫn cảm thấy chưa đủ. Họ cũng cho rằng, một Trung Quốc tươi đẹp không chỉ nằm trong sách vở, mà càng nằm ngay dưới bước chân mình.","audio_dialogue":"20-7.mp3","audio_vocab":"20-8.mp3"}]}],"pos_table":[{"pos_cn":"名词","pos_vn":"Danh từ","abbr":"dt."},{"pos_cn":"动词","pos_vn":"Động từ","abbr":"dgt."},{"pos_cn":"形容词","pos_vn":"Tính từ","abbr":"tt."},{"pos_cn":"代词","pos_vn":"Đại từ","abbr":"đt."},{"pos_cn":"副词","pos_vn":"Phó từ","abbr":"phó."},{"pos_cn":"介词","pos_vn":"Giới từ","abbr":"giới."},{"pos_cn":"连词","pos_vn":"Liên từ","abbr":"liên."},{"pos_cn":"助词","pos_vn":"Trợ từ","abbr":"trợ."},{"pos_cn":"数词","pos_vn":"Từ chỉ số đếm","abbr":"số."},{"pos_cn":"量词","pos_vn":"Lượng từ","abbr":"lượng."},{"pos_cn":"数量词","pos_vn":"Từ chỉ số lượng","abbr":"sl."},{"pos_cn":"叹词","pos_vn":"Từ cảm thán","abbr":"ct."},{"pos_cn":"拟声词","pos_vn":"Từ tượng thanh","abbr":"tượng."},{"pos_cn":"能愿动词","pos_vn":"Động từ năng nguyện","abbr":"đtnn."},{"pos_cn":"前缀","pos_vn":"Tiền tố","abbr":"ttố."},{"pos_cn":"后缀","pos_vn":"Hậu tố","abbr":"htố."}]};
